{"assumptions":[],"created_at":"2026-10-26T19:31:20.883383+00:00","domain":"probability theory","id":"claim_5edcbceda759efc2d7c3425260a80f38270bab3cc86aadd5b76fed933cd97b10","kind":"theorem","schema_version":1,"statement":"[Corollary 3 of arXiv:2506.11918, 'Central limit theorems for the Euler characteristic in the Random Connection Model for hig'] The expectation and variance of the generalized Euler characteristic $\chi_a(\Delta_W)$ are given by
\begin{align*}
\E{ \chi_a(\Delta_W) } \,&=\, \sum_{m=1}^{\alpha+1} a_{m-1} \frac{\beta^m}{m!} \z m m m (W), \\
\V{ \chi_a(\Delta_W) } \,&=\, \sum_{m,l=1}^{\alpha+1} \sum_{r=\max\{m,l\}}^{m+l-1} a_{m-1} a_{l-1} \frac{\beta^r}{(r-m)!(r-l)!(m+l-r)!} \, \z m l r (W).
\end{align*}","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-28T00:52:17.597009+00:00","domain":"probability theory","id":"claim_5ee289d9bdf09f802681eadc1fad83e101b2dafc30110b9325a1fa8881fb4d5a","kind":"theorem","schema_version":1,"statement":"[Prp equivalent of arXiv:2411.15724, 'Wasserstein Convergence Rates for Empirical Measures of Random Subsequence of $\{nα\}$'] Let $\varphi$ be a characteristic function of an integer-valued random variable $X$ and let $0< \beta \leq 2$. The following assertions are equivalent.
\begin{enumerate}[(i)]
\item 
There exists $c > 0$ such that in an open neighborhood of $0$,
\begin{align*}
|1 - \varphi(x)| \geq c |x|^\beta.
\end{align*}

\item 
There exist $d \in \mathbb Z^+$ and $c' > 0$ such that for any $x \in \mathbb R$,
\begin{align*}
|1 - \varphi(2 \pi x)| \geq c' \| d x \|^\beta.
\end{align*}

\item 
There exist $d \in \mathbb Z^+$ and $c' > 0$ such that for any $x \in \mathbb R$,
\begin{align*}
|1 - \varphi(2 \pi x)| \geq c' |\varphi(2\pi x)| \| d x \|^\beta.
\end{align*}

\end{enumerate}","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T16:57:16.041163+00:00","domain":"probability theory","id":"claim_5ee33a8e957f7df7912c40eb955bf2c2c1e8ec6b0a3ecfadc5f882e722e75c99","kind":"concept","schema_version":1,"statement":"[Proposition estimate_boundary of arXiv:2506.02611, '\textbf{The tight length spectrum of large-genus random hyperbolic surfaces with many cusp'] For any $\mu_g \underset{g \to +\infty}{\rightarrow}\mu_c$ such that $\mu_c - \mu_g = o(g^{-2})$ and any $n \ge 0$, we have
    \begin{align*}
        T_{g,n}\bigg(\bigg(-\frac{M_1}{3M_0}\bigg)^{\frac{1}{2}}\mathbf{L},\mu_g\bigg) = \bigg(\prod_{i=1}^{n}\frac{\sinh(L_i)}{L_i}\bigg)T_{g,n}(\mu_g)\,\bigg(1+o_{n,\mathbf{L}}(1)\bigg),
    \end{align*}
   where $o_{n,\mathbf{L}}(1)$ is uniform in $\mathbf{L}\in K$ if $K \subset \mathbb{R}_{+}^{n}$ is compact.\\
   Moreover, for $K \subset \mathbb{R}^n$ compact, there exists $g_0 \ge 0$ such that for $g$ large enough
   \begin{align*}
      \forall \mathbf{L} \in K, \text{ } \forall g^{'}
\in \{g_0,\cdots,g\}, \text{ } T_{g^{'},n}\bigg(\bigg(-\frac{M_1}{3M_0}\bigg)^{\frac{1}{2}}\mathbf{L},\mu_g\bigg) \le 2e^{\somme{i=1}{n}{L_i}}T_{g^{'},n}(\mu_g), 
\end{align*}
where the constant $g_0$ depends on the choice of $(\mu_g)$, $n$ and $K$. (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T21:07:15.771447+00:00","domain":"probability theory","id":"claim_5ee58d59d87019cf045b8bdb3f95ce842167906b8c6c07f0c327a979458d4626","kind":"theorem","schema_version":1,"statement":"[Proposition prop:two-level of arXiv:2608.04900, 'A Sharper Hoeffding Bound for Weighted Sums of Exchangeable Random Variables'] Fix $1\le k\le N-1$ and $\rho\ge0$, and define
\begin{align*}
F_{N,k}(y)=\log\biggl\{\frac{e_k(e^{y_1},\ldots,e^{y_N})}{\binom{N}{k}}\biggr\}.
\end{align*}
The maximum of $F_{N,k}$ over $\{y\in\mathbb{R}^N:\sum_{i=1}^N y_i=0,\ \|y\|_2=\rho\}$ is attained by a vector with at most two distinct coordinate values.","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T10:39:18.532206+00:00","domain":"probability theory","id":"claim_5ee65854726d6c16fb668b80d1a718000810b040c5f14315d1dbcf06837d3eb4","kind":"theorem","schema_version":1,"statement":"[Theorem 11 of arXiv:2609.02283, 'The game chromatic number of generalized Mycielski graphs of paths and cycles'] For $k\geq2$, the following statements hold for generalized Mycielski graphs of paths:

