{"assumptions":[],"created_at":"2026-10-27T11:26:52.656411+00:00","domain":"probability theory","id":"claim_5f6d0958c9eb12e516dd8293d37f5b42b8a8654739f6b0f30fe44eea960ae7c0","kind":"lemma","schema_version":1,"statement":"[Lemma 18 of arXiv:2609.03726, 'Inverse Scattering for Single Photons in Quantum Optics'] Let $\alpha\in\mathbb{S}^{n-1}$ and $h\in \mathscr{S}(\mathbb{R}^n)$.
For $\varepsilon>0$, define
\begin{equation*}
    T_\alpha^\varepsilon h(x)
  :=
  \mathcal{F}^{-1}\left[\frac{\widehat{h}(\eta)}{\alpha\cdot\eta-i\varepsilon}\right](x)
  = \frac{1}{(2\pi)^n}\int_{\mathbb{R}^n}
    \frac{e^{ix\cdot\eta}\widehat{h}(\eta)}{\alpha\cdot\eta-i\varepsilon}d\eta,
\end{equation*}
\begin{equation*}
    T_\alpha h(x)
    :=
    i\int_{-\infty}^{x\cdot\alpha} h(\tau\alpha+x_\perp)d\tau,
  \qquad x_\perp = x-(x\cdot\alpha)\alpha.
\end{equation*}
Then, for any compact set K,
\begin{equation*}
    \lim_{\varepsilon\to 0} \left\|T_{\alpha} h
    -
    T_{\alpha}^\varepsilon h 
    \right\|_{C^0(K)} =0.
\end{equation*}","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-26T19:35:10.792480+00:00","domain":"probability theory","id":"claim_5f6d8146c199a622572428d3ffdb9c38c2569b089a56456b52922788028d8713","kind":"lemma","schema_version":1,"statement":"[Lemme 16 of arXiv:2604.00635, 'Large deviations of the periodic Toda chain'] The following relation holds

\bem

\det_{N-1}\big[ \op{A} \big]  \, = \,   | \ln(2\veps_N)|^{N-1}

   \det_N\bigg[  \Big( 1- \frac{1}{\ln(2\veps_N)}  \ln|P^{\prime}(\eta_j)| \Big) \delta_{kj}  + \frac{ N }{ \ln(2\veps_N) } M_{kj} \\

\, +  \, \mathrm{O}\Big( \big( 1+ N \de_{jN} \mathbbm{1}_{k \leq N-1}   \big)\vartheta_N \Big) \bigg]  \, .

\end{multline}

in which the matrix $\op{M}$ is defined as

\begin{align}

M_{kj} \,  =  \, \f{1}{N}\mathbbm{1}_{k \neq j} \ln| \eta_k -\eta_j| \, = \,

    \begin{cases}

\frac{1}{N} \ln|\eta_k - \eta_j| & k \neq j  \vspace{2mm}\\

0 & k = j

\end{cases} \, .

\end{align}","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T09:01:15.335653+00:00","domain":"probability theory","id":"claim_5f6dfa94af514cd3625e222679d69103616f0c73a6b4926070cab310f1467451","kind":"lemma","schema_version":1,"statement":"[Lemma 15 of arXiv:2608.30409, 'Gradient estimates and volume doubling for locally finite weighted graphs with $CD\psi(n,-'] Let $G=\left(V,E\right)$ be a locally finite weighted graph satisfying the $CD\psi\left(n,-K\right)$ condition with $K\geq0$ where $\psi\in C^{1}\left(0,+\infty\right)$ is a concave function with $\psi^\prime \left(1\right)>0$. Assume that $g\le0$ is a $d$-Lipschitz function. Then for any $\tau,\lambda>0$, there exists a constant $C\left(\lambda,d,\psi,D_{\mu}\right)>0$ depending only on $\lambda,d,\psi,D_{\mu}$ such that 
    \begin{equation*}
        \partial_t \varphi_{\lambda}\geq - \frac{1}{\psi^{\prime}\left(1\right)t}\left[\lambda C\left(\lambda,d,\psi,D_{\mu}\right)\tau+\frac{n}{8\lambda}\log\left(1+\frac{t}{\tau}\right)\right]
          -\frac{nK}{2\psi^{\prime}(1)\lambda},
    \end{equation*}
    where $\varphi_{\lambda}$ is defined by \eqref{varphi def}.","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T06:16:18.680559+00:00","domain":"probability theory","id":"claim_5f6e668e2cdda33fe5863a0753c5e625ba460e23b6a51ffc729554d883e03404","kind":"lemma","schema_version":1,"statement":"[Lemma 12 of arXiv:2607.25986, 'Asymptotics of a two-species particle system associated to the doubly parabolic Keller-Seg'] We fix $c_0 \in L^\infty(\R^2)\cap L^1(\R^2)$ and $\theta>0$, $\lambda>0$.
There exists a constant $A$ such that for all $t> 0$, all $x\in\R^2$, all $\e\in [0,1]$,
\begin{equation}
|K^{\theta,\lambda}_t(x)|\leq A (t+|x|^2)^{-1} \quad \text{and} \quad 
|(\phi_\e \ast K^{\theta,\lambda}_t)(x)|\leq A \int_{\R^2} (t+|x-\sqrt \e y|^2)^{-1} \phi(y)\dd y.
\end{equation}
For any $\alpha>0$, any $t>0$, any $x\in \R^2$, any $\e\in [0,1]$,
\begin{align}
|\nabla K^{\theta,\lambda}_t(x)|\leq &
C_3(\theta,\alpha)(t+\alpha |x|^2)^{-\frac{3}{2}}, \quad \text{where} \quad C_3(\theta,\alpha)=\frac{\sqrt \theta C_0\big(\frac{4\alpha}{\theta}\big)}{4\pi}, \\
|\nabla (\phi_\e \ast K^{\theta,\lambda}_t)(x)|\leq& 
C_3(\theta,\alpha)\int_{\R^2}(t+\alpha |x-\sqrt\e y|^2)^{-\frac{3}{2}}\phi(y)\dd y.

\end{align}
There exists $A>0$ depending on $\theta$, $c_0$ and $\phi$ such that for any $t>0$, any $\e\in [0,1]$,
\begin{equation}
||\nabla (\phi_{\e}\ast b^{c_0,\theta,\lambda}_t) ||_{L^\infty(\R^2)}\leq  A (\e+t)^{-\frac 1 2}.
\end{equation}
For all $t\geq 0$, it holds that
\begin{equation}
\lim_{\e\to 0}\int_0^t ||\nabla \phi_{\e}\ast b^{c_0,\theta,\lambda}_{s} - \nabla b^{c_0,\theta,\lambda}_{s}||_{L^\infty(\R^2)} 
\dd s=0.
\end{equation}
For all $s>0$, if $x_n\to x$ and $\e_n\to 0$, then
\begin{equation}
(\nabla \phi_{\e_n}\ast b^{c_0,\theta,\lambda}_{s})(x_n)\to \nabla b^{c_0,\theta,\lambda}_{s}(x).
\end{equation}","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T08:26:47.152232+00:00","domain":"probability theory","id":"claim_5f6f1ad9a9adb930ad66965cb912f9b3ac4837d219ed4e526f86f84657d05739","kind":"lemma","schema_version":1,"statement":"[Lemma 25 of arXiv:2608.29361, 'Convergence of the subcritical $\gamma$-LQG metric to the critical $2$-LQG metric as $\gam'] Fix $\theta \in (0,\xi_c / 8)$. Then, there exists a choice of the functions $b,M$ (depending only on $\theta$) such that the following is true for all $\xi \in (\xi_c / 2, \xi_c]$. Let $U \subseteq \CC$ be a bounded open set and fix $\varepsilon \in (0,1)$. Then, there exists deterministic constant $C>0$ depending only on $\varepsilon,\theta$, and $U$, such that the following holds with probability at least $1-\varepsilon$. For all $z \in U$ and all $n \in \NN$, we have that
