   \end{align}

     and 
    \begin{align}
        \frac{C_{n,n}^\rho-\operatorname{\mathbb E}(C_{n,n}^\rho)}{\sqrt{\mathrm{Var}\bclr{C_{n,n}^\rho}}}\overset{\mathrm{d}}{\longrightarrow} \mathcal{N}(0,1)\mbox{ as } n\to\infty.
    \end{align} (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-26T19:28:04.864401+00:00","domain":"probability theory","id":"claim_5f84fb42ca9626d01a0b8b0e55c6fb054534a0b74e7493e99b7ade0f6fcfc278","kind":"theorem","schema_version":1,"statement":"[Theorem 7 of arXiv:2511.23453, 'Convergence rates of self-repellent random walks, their local time and Event Chain Monte C'] Assume that
    \begin{enumerate}[(i)]
        \item the operator $(\hatL,\dom(\hatL))$ is a second-order lift of $(\L,\dom(\L))$ such that $g\circ\pi\in\dom(\hatL^*)$ and $\hatL^*(g\circ\pi) = -\hatL(g\circ\pi)$ for all $g\in\dom(\L)$;
        \item the operator $(\L,\dom(\L))$ has purely discrete spectrum on $L^2(\mu)$ and a spectral gap $m>0$, i.e.\ 
        \begin{equation*}
            \norm{g-\mu(g)}_{L^2(\mu)}^2\ \leq \ \frac{1}{m}\E(g)
        \end{equation*}
        for all $f\in\dom(\E)$;
        \item there exists a constant $C_1>0$ such that
        \begin{equation*}
            \big\langle \hatL(g\circ\pi),\hatL(f-\Pi f)\big\rangle_{L^2(\hat\mu)}\ \leq\ C_1\norm{\L g}_{L^2(\mu)}\norm{f-Qf}_{L^2(\hat\mu)}
        \end{equation*}
        for all $f\in\dom(\hatL)$ and $g\in\dom(\L)$;
        \item the transition matrix $Q$ has a spectral gap $m_Q$, i.e.\ 
        \begin{equation*}
            x^\top Qx\leq (1-m_Q)|x|^2
        \end{equation*}
        for all $x\in\R^n$ with $\sum_{i=1}^nx_i=0$.
    \end{enumerate}
    Then there exists a universal constant $C > 0$ such that, for any $T>0$ and $\gamma>0$, 
    the semigroup $(\hat P_t^{(\gamma)})$ generated by $(\hatLgamma,\dom(\hatLgamma))$ satisfies
    \begin{equation*}
        \lVert\hat P_t^{(\gamma)}f\lVert_{L^2(\hat\mu)}\ \leq\ e^{-\nu(t-T)}\lVert f\rVert_{L^2(\hat\mu)}\qquad\text{for all }t\geq 0\text{ and }f\in L_0^2(\hat\mu),
    \end{equation*}
    where the rate $\nu$ is given by 
    \begin{equation}
         \nu = C\,\frac{\gamma}{\gamma^2/m+C_1^2 + \frac{1}{m_Q}(1 + \frac1{mT^2})}.
    \end{equation}","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T11:11:44.358052+00:00","domain":"probability theory","id":"claim_5f856ec1d2abdafc53520cc51bfa0d3a9bb80e32c1c56b3384cd1fd3476273d0","kind":"theorem","schema_version":1,"statement":"[Proposition 15 of arXiv:2609.03098, 'Standing waves for Schr\"odinger equations with Kato class potentials and $L^\infty$-bound'] Assume the mappings $f_{n}:\R^N\times \R\to\R$, $n\ge 0$, satisfy condition $(f1)$ with a common function $c\in L^{2}(\R^{N}$ and condition $(f2)$ with the same Lipschitz constant $l\in L^{\infty}(\R^{N})$. Suppose that 
