{"assumptions":[],"created_at":"2026-10-27T17:43:53.646238+00:00","domain":"probability theory","id":"claim_5f868ca178700b8bc884184acb25378b851c0efbd4279252128f25b95aa31683","kind":"theorem","schema_version":1,"statement":"[Proposition prop:asympt lx of arXiv:2512.17747, 'On exponentially height-penalized random trees'] Let $x>0$ and $\lambda_x$ be the function defined in~(equation eq:lx of the paper).
    Let $t_x$ be the minimizer of $\lambda_x$.
    Then, as $x$ converges to $0$, we have the following asymptotic behaviour.
    \begin{itemize}
        \item[$\mathbf{(1)}$] The minimizer $t_x$ of the function satisfies
        \begin{align*}
            t_x=\left(\frac{2\pi^2}{x}\right)^{1/3}\left[1+\frac{1}{9}\left(\frac{\pi x}{2}\right)^{2/3}+O\left(x^{4/3}\right)\right]=\left(\frac{2\pi^2}{x}\right)^{1/3}+O\left(x^{1/3}\right)
        \end{align*}
        \item[$\mathbf{(2)}$] The minimum of the function satisfies
        \begin{align*}
            \lambda_x(t_x)=3\left(\frac{\pi x}{2}\right)^{2/3}+\frac{1}{6}\left(\frac{x}{2\pi}\right)^{4/3}+O\left(x^2\right)\,,
        \end{align*}
        \item[$\mathbf{(3)}$] For any $\epsilon=\epsilon_x$ converging to $0$ as $x$ goes to $0$ (allowed to be negative), the asymptotic behaviour of $\lambda_x$ at $(1+\epsilon)t_x$ is given by
        \begin{align*}
            \lambda_x\big((1+\epsilon)t_x\big)-\lambda_x(t_x)&=3\left(\frac{\pi x}{2}\right)^{2/3}\epsilon^2+O\left(\epsilon^3x^{2/3}+\epsilon^2x^{4/3}\right)\,,
        \end{align*}
        and the $O(\cdot)$ term is uniform over any window of the form $[-\delta,\delta]$ for $\delta=\delta_x\ll1$.
    \end{itemize}","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T07:58:01.572110+00:00","domain":"probability theory","id":"claim_5f8b5ae4f396d9de2ef587223a3e2ee67e825891ee1ae9b17fcccdacfe41613d","kind":"theorem","schema_version":1,"statement":"[Proposition 24 of arXiv:2608.27307, '2608.27307'] Under Assumption~\ref{ass:basic}, let $E_*$ be a regular right edge in the sense of Definition~\ref{def:reg_r_edge}. Then
        \begin{align}
                \avg{\Pi_{*,21}\Sg\Pi_{*,12}}_N + & \sqrt{\avg{\Pi_{*,22}^2}_N \avg{\Sg\Pi_{*,11}\Sg\Pi_{*,11}}_N} =1,                  \\
                \avg{\Pi_{*,22}^2}_N                                                                            \sim1, \qquad &\avg{\Sg\Pi_{*,11}\Sg\Pi_{*,11}}_N                                                              \sim1. 
        \end{align}
        Consequently, $1$ and $\la_*$ are the two simple eigenvalues of $\calJ_*$ and
        \begin{align}
                1-\la_* =2\sqrt{\avg{\Pi_{*,22}^2}_N\avg{\Sg\Pi_{*,11}\Sg\Pi_{*,11}}_N} \sim1. 
        \end{align}
        Moreover, the dual basis relations imply the spectral decomposition
        \begin{align}
                I_2 & =\f{r}_*\f{\ell}_*^*+\wh{\f{r}}_*\wh{\f{\ell}}_*^*, \qquad
                \calJ_*  =\f{r}_*\f{\ell}_*^*+\la_*\wh{\f{r}}_*\wh{\f{\ell}}_*^*. 
        \end{align}
        In particular,
        \begin{align}
                \|\f{r}_*\|+\|\wh{\f{r}}_*\|+\|\f{\ell}_*\|+\|\wh{\f{\ell}}_*\|\lesssim1. 
        \end{align}","status":"unverified"}

