{"assumptions":[],"created_at":"2026-10-26T20:47:22.250619+00:00","domain":"probability theory","id":"claim_602e03d686510ebf548e1c37ddbdbd68c3f16ace6aad1b7524be0818c4f11473","kind":"concept","schema_version":1,"statement":"[Lem 53 of arXiv:2605.26664, 'Mixing times for Glauber dynamics of lozenge tilings of the hexagon'] Fix a real number $K$ satisfying \eqref{eq:costanti}; $\mathtt{d} \in [N^{-1/2}, 1)$; and real numbers $q \ge q' \ge 0$ with $\varepsilon_0\ge q \ge N^{3500K\delta-2/3} \mathtt{d}^{-1/3}$. Consider the Glauber dynamics $(H_t)_{t \ge 0}$ starting from an initial condition $\mu\in\mathcal P^+$ and assume that, w.o.p., 
	\begin{flalign}

		\begin{aligned} 
			& H_0 (w) \le \mathcal{H}_q (w) + N^{K\delta-1}, \qquad \text{for all $w \in \mathfrak{X}$}; \\
			& H_0 (w) \le \mathcal{H}_q (w), \qquad \qquad \qquad \text{for all $w \notin \mathfrak{L}_q^+ ({K\delta})$}. 
		\end{aligned} 
	\end{flalign} 

	\noindent Denoting $\mathsf{t} = q^{-1} \mathtt{d}^{-1/3} N^{4/3+15000K\delta}$, the following holds w.o.p. for any $t \in [\mathsf{t}, N^5]$. For any $z \in \mathfrak{X}$ satisfying
	\begin{flalign}

		\mathtt{d}_z \ge N^{-K\delta} \mathtt{d}; \qquad \mathtt{d}_z^{1/2} \mathtt{e}_{z;q'}^{3/2} \le N^{K\delta-1}, \qquad \text{and} \qquad N^{K\delta} (q-q') \le N^{-2/3} \mathtt{d}_z^{-1/3},
	\end{flalign}
	\noindent we have
	\begin{flalign}

		\begin{aligned}
			& H_t (z) \le \mathcal{H}_{q'} (z) + N^{\delta/4-1}, \qquad \text{and} \qquad H_t (z) \le \mathcal{H}_{q'} (z),  \quad \text{if $z \notin \mathfrak{L}_{q'}^+ (\delta)$}.
		\end{aligned} 
	\end{flalign} (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-26T20:38:37.405684+00:00","domain":"probability theory","id":"claim_6033d48cf795607748e12379e2853a2f6f3cc42f92a696ef1d9338b413c54640","kind":"concept","schema_version":1,"statement":"[Theorem 2 (\cite{Li}) of arXiv:2605.15781, 'Mean-Field Backward Stochastic Differential Equations with Nonlinear Resistance and Double'] Suppose that $l,r$ satisfy Assumption \ref{asslr}. For any given $s\in C[0,T]$, there exists a unique pair of solution to the Skorokhod problem $(x,K)=\mathbb{SP}_l^r(s)$. Moreover, for any $t\geq 0$, let $\phi_t,\psi_t$ be the unique solutions to the following equations, respectively, 
    \begin{align*}
        l(t,s_t+x)=0,\ r(t,s_t+x)=0.
    \end{align*}
    Then, we have 
    \begin{align*}
        &K_t=-\max\left((-\phi_0)^{+}\wedge  \inf_{r\in[0,T]}(-\psi_r), \sup_{s\in[0,T]}\left[(-\phi_s) \wedge  \inf_{r\in[s,t]}(-\psi_r)\right]\right),\\
    \end{align*}
    and 
   \begin{align*}
        &\sup_{t\in[0,T]}\left|K_t\right|\leq \sup_{t\in[0,T]}\left|\phi_t\right|+\sup_{t\in[0,T]}\left|\psi_t\right|.\\
    \end{align*} (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T18:25:35.632864+00:00","domain":"probability theory","id":"claim_6034869438fb0822eed769dfabce5eba2bfe3dcfafe89c6de6b0d1f53c46d845","kind":"concept","schema_version":1,"statement":"[Theorem local_limit_middle of arXiv:2603.05491, '\textbf{Local limits of uniform triangulations with boundaries in high genus}'] Fix $\theta \in [0,\frac{1}{2})$, $\displaystyle \frac{g_n}{n} \to \theta$ and $\mathbf{p}^{n} = (p^n_{1},\cdots,p^n_{\ell_n})$ such that $|\mathbf{p}^{n}|= o(n)$. Let $e^n$ denote an oriented edge chosen uniformly at random in $T_{n,g_n,\mathbf{p}^{n}}$. Then the following convergence holds for the local topology
    \begin{align*}
       &(T_{n,g_n,\mathbf{p}^{n}},e^n) \overset{(d)}{\to}\mathbb{T}_{\lambda(\theta)},
       \end{align*}
 where $\lambda(\theta)$ is the unique solution to the equation 
\begin{align*}
    d(\lambda(\theta)) = \frac{1-2\theta}{6}.
\end{align*}
Moreover, let us also fix $p \ge 1$. Consider $T_{n,g_n,(p,\mathbf{p}^{n})}$ and let $e^n_1$ denote the distinguished edge on the first boundary of $T_{n,g_n,(p,\mathbf{p}^{n})}$. Then the following convergence holds for the local topology
    \begin{align*}
(T_{n,g_n,(p,\mathbf{p}^{n})},e^n_1) \overset{(d)}{\to}\mathbb{T}^{(p)}_{\lambda(\theta)}.
 \end{align*} (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T06:51:11.969106+00:00","domain":"probability theory","id":"claim_6036dae4b39fa806f3beb2b211e734518c30ce51a37e4c1745d11633f5e4571a","kind":"theorem","schema_version":1,"statement":"[Theorem 12 (Primitive normal-cone theorem) of arXiv:2608.08756, 'Infinite-Dimensional L\'evy Area and Spectral Ancestry'] There is a natural isomorphism of normal-graded Hopf algebras
\begin{equation}
 {\operatorname{gr}}_JT(V)\cong T(Q)\#_\rho S(V)
 \cong U\!\left(V_{\mathrm{ab}}\ltimes_\rho{\mathfrak L}(Q)\right).

\end{equation}
The isomorphism is induced by the identity on the degree-zero primitives
\(L/D\cong V\) and the degree-one primitives \(D/[D,D]=Q\), and it
respects ordinary tensor degree.
Consequently,
\begin{align}
 J^r/J^{r+1}&\cong Q^{\otimes r}\otimes S(V),
 \\
 {\operatorname{Prim}}({\operatorname{gr}}_JT(V))_0&\cong V,
 \qquad
 {\operatorname{Prim}}({\operatorname{gr}}_JT(V))_r
 \cong{\mathfrak L}_r(Q)\cong\gamma_r(D)/\gamma_{r+1}(D),
 \quad r\geq1,

\end{align}
and, most importantly,
\begin{equation}
 L\cap J^r=\gamma_r(D),\qquad r\geq1.

\end{equation}
Thus normal order and derived-ideal ancestry agree exactly.","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-28T01:29:08.755366+00:00","domain":"probability theory","id":"claim_6037ac87b56a9962dcc1ef268d520fe858c253dff611934699cffece2bbcb6d0","kind":"lemma","schema_version":1,"statement":"[Lem polyencodingGOEGSE of arXiv:2412.00593, 'A new approach to strong convergence II.\\The classical ensembles'] For any $h\in \mathcal{P}_q$, there is $\Phi_h\in\mathcal{P}_{qq_0}$
so that
\begin{alignat*}{2}
	&\mathbf{E}[\mathop{\textnormal{tr}} h(X^N)] &&= \Phi_h(\tfrac{1}{N}),\\
	&\mathbf{E}[\mathop{\textnormal{tr}} h(Y^N)] &&= \Phi_h(-\tfrac{1}{2N}).
\end{alignat*}","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-26T20:38:37.405627+00:00","domain":"probability theory","id":"claim_603945d9fbd1bdd72d24987aa6f5c7226e9a13d1b549226d5657020479a8721e","kind":"definition","schema_version":1,"statement":"[Definition 1 of arXiv:2605.15781, 'Mean-Field Backward Stochastic Differential Equations with Nonlinear Resistance and Double'] Let $s\in C[0,T]$,  and $l,r:[0,T] \times \mathbb{R}\rightarrow \mathbb{R}$ be two functions with $l\leq r$.  A pair of functions $(x,K)\in C[0,T]\times BV[0,T]$ is called a solution to the  Skorokhod problem for $s$ with nonlinear constraints $l,r$ ($(x,K)=\mathbb{SP}_l^r(s)$ for short) if 
\begin{itemize}
\item[(i)] $x_t=s_t+K_t$;
\item[(ii)] $l(t,x_t)\leq 0\leq r(t,x_t)$;
\item[(iii)]  $K_{0-}=0$ and $K$ has the decomposition $K=K^r-K^l$, where $K^r,K^l$ are nondecreasing functions satisfying  
\begin{align}
\int_0^{T} I_{\{l(s,x_s)<0\}}dK^l_s=0, \  \int_0^{T} I_{\{r(s,x_s)>0\}}dK^r_s=0.
\end{align}
\end{itemize}","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T22:48:00.298393+00:00","domain":"probability theory","id":"claim_603c39e9f81f3c47a7a57c539b4bb12d8219211158636dbd5c6256a6983efa74","kind":"concept","schema_version":1,"statement":"[Conj strip GW formula of arXiv:2609.03152, 'Experiments with membranes, maps and sheaves'] Suppose $X$ is a strip geometry and $(X\times\mathbb{C}^{2},\mathsf{T})$ is equivariantly Calabi--Yau. Then if we denote the tangent $\mathsf{T}$-weights of the affine plane by $\epsilon_4,\epsilon_5$ we have
    \begin{equation*}

    \GWarg{X\times\mathbb{C}^{2}}{\mathsf{T}}{} = \Exp \left(-\sum_{1 \leq m < n \leq N+1} \frac{[\kappa q_{v_m}]}{[q_{v_n}] \, [q_4] \, [q_5]} \prod_{i=m}^{n-1} Q_i \right)
	\end{equation*}
    under the change of variables $q_i = \mathrm{e}^{u \epsilon_i}$. (Stated as a conjecture by the paper; open unless the paper says otherwise.)","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-26T19:26:40.360791+00:00","domain":"probability theory","id":"claim_603c9644280e3bc1b3cde4bb0da7059a3904c0e639bd50fa749f7307b9fa3eab","kind":"lemma","schema_version":1,"statement":"[Lemma 41 of arXiv:2511.09517, 'From Cannings model to Brownian motion conditioned on local time profile'] For any $\delta>0$, $n\ge 1$ and $h_*+\frac{n}{(\log n)^{1+\frac{\varepsilon}{8}}}\le s \le h^*$, we have on the event $(\Xi_n)^{\rm c}\cap \Big\{T^{(r)}_{\lfloor (\log n)^{1+\frac{\varepsilon}{2}} \rfloor}(s) < s^{\downarrow} \Big\}$,
\begin{align}
    X^{(r)}_s - X^{(r)}_{s^{\downarrow}} \ge \frac{2}{(\log n)^{\frac\varepsilon{12}}}\sum_{j=s^{\downarrow}+1}^{s} \widetilde N_j.
\end{align}","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T07:23:05.299281+00:00","domain":"probability theory","id":"claim_603d0970ebfc6a022f611c74bf4058f6eaa5d538dbdb96e2a7c8fd1d74186153","kind":"concept","schema_version":1,"statement":"[Corollary 8 (High-noise decay of the smoothed likelihood force) of arXiv:2608.21709, 'Posterior Information Dynamics of Diffusion Models for Linear Inverse Problems'] Under the assumptions of Lemma~\ref{thm:posterior-tweedie}, the force
\(g_t\) satisfies, under the joint law of \((X_t,R)\),
\begin{equation}

\E\|g_t(X_t,R)\|^2
=
\frac{a_t^2}{\Delta_t^2}
\E\big\|\E[X_0\mid X_t,R]-\E[X_0\mid X_t]\big\|^2.
\end{equation}
Moreover,
\begin{equation}

\E\|g_t(X_t,R)\|^2
\le
\frac{a_t^2}{\Delta_t^2}\Tr\Cov(X_0).
\end{equation}
Consequently, along any dimension sequence for which
\(d^{-1}\Tr\Cov(X_0)=O(1)\), and on any high-noise window where
\(\Delta_t\ge \Delta_0>0\),
\begin{equation}

\frac1d\E\|g_t(X_t,R)\|^2=O(a_t^2).
