			F(x,t) \leq \psi(x,t) \quad \text{for each} \, \, (x,t) \in \mathbb{R} \times [t_{0} - r, t_{0} + r], \quad \text{and} \\
			(x_{0},t_{0}) \in \{ (x,t) \in \mathbb{R} \times [t_{0} - r, t_{0} + r] \, \mid \, F(x,t) = \psi(x,t) \} \subseteq (-\infty,x_{0}] \times \{t_{0}\}.
