  \end{align} (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T12:48:49.872299+00:00","domain":"probability theory","id":"claim_60e1e80930710b25a9f91f7c3959c86e57542172221db9b0ed2d2863c16e1ed3","kind":"concept","schema_version":1,"statement":"[Lemma lem:secondmomentofy of arXiv:2509.21253, '\bf Capacity in high dimensional percolation'] There exists $C>0$, such that for all $L\ge 10K$, $M\ge 1$, and $r\ge 2L$, we have 
		\begin{align*}
			\E{Z_{r,L}^2\cdot \1(X_r^{K-\textrm{line-good}}=M)}\leq C\cdot  M^2\cdot L^4\cdot \pr{X_r^{K-\textrm{line-good}}=M}.
		\end{align*} (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T23:41:03.289864+00:00","domain":"probability theory","id":"claim_60e6a1cc1d9046f49fc808f411911450fbf34e4a2def0ce87676870824733f43","kind":"definition","schema_version":1,"statement":"[Definition def:ucp of arXiv:2411.08846, 'On the Number of Crossings and Bouncings\\ of a Diffusion at a Sticky Threshold'] We say that $(A^{n})_{n\ge1} $
	\emph{converges locally uniformly in time, in probability} 

	to $A^{0}$ if 
	\begin{equation}
		\forall t\ge 0:\;
		\sup_{s\le t} \bigabsbraces{A^{n}_s - A^{0}_s}  \xlongrightarrow[n \rightarrow  \infty]{\Prob}  0.
	\end{equation}
	We denote this convergence with 
	\begin{equation}
		A^{n} \convergence{ {\Prob}\text{-}\mathrm{ucp}} A^{0} .
	\end{equation}","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T07:25:06.135732+00:00","domain":"probability theory","id":"claim_60e6f05be2fa3b88ea1f3aecb83255cbd9d367d4be15eebff6a41e22efaf7bf6","kind":"lemma","schema_version":1,"statement":"[Lem 5 (Aldous' criterion) of arXiv:2608.22514, 'Diffusion limits of cyclic finite-velocity random motions\\ along vector fields'] For any $\eta\in(0,1]$, any $T\in[0,\infty)$
\ba
\lim_{h\downarrow 0}\limsup_{\e,\delta\downarrow 0}
\sup_{\sigma,\tau\in\mathbb F^{\e,\delta},
\sigma\leq\tau\leq(\sigma+h)\wedge T}
\P_{x,\iota}\Big(|Z^{\e,\delta}_\tau-Z^{\e,\delta}_\sigma|\geq\eta\Big)=0.
\ea
The convergence is uniform over
$(x,\iota)\in\mathbb R^d\times\{1,\dots,p\}$.","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T20:14:57.636467+00:00","domain":"probability theory","id":"claim_60e88584c1f12636ca5aaf3981cd1c2822102cf95bb01aa603032c0ac82b0d95","kind":"concept","schema_version":1,"statement":"[Corollary of arXiv:2605.28770, 'Cutoff profiles for conjugacy invariant random walks on symmetric groups'] Let $\delta>0$. For each $n$, let $ {\ensuremath{\mathcal C}} ^{(n)} \in{\ensuremath{\textup{Conj}}} ^*({\ensuremath{\mathfrak{S}}} _n)$. Assume that $f_1({\ensuremath{\mathcal C}} ^{(n)})\geq \delta n$ for $n$ large enough. Let $a\in {\ensuremath{\mathbb R}} $.
Let $S\subset {\ensuremath{\mathbb N}} $ and $(t_n)_{n\in S}$ be a sequence of positive integers such that, along $S$, $t_n = \frac{\ln n + a + o(1)}{\ln(n/f_1({\ensuremath{\mathcal C}} ^{(n)}))}$. Let $\theta >0$.   
As $S \ni n\to \infty$, we have
\begin{equation}
    \textup{d}_2^{{\ensuremath{\mathcal C}} ^{(n)}}(t_n) \to \sqrt{e^{e^{-2a}}-1} \quad \quad \text{ and } \quad \quad \textup{d}_\infty^{{\ensuremath{\mathcal C}} ^{(n)}}(2t_n) \to e^{e^{-2a}}-1.
\end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T23:01:54.384332+00:00","domain":"probability theory","id":"claim_60eaffe83fae2d2022296aee584fc73a867f970900709fb296c322ce4cc6d4b5","kind":"concept","schema_version":1,"statement":"[Lemma lm:PPP.clusters of arXiv:2411.02046, 'Speed of Convergence and Moderate Deviations of FPP on Random Geometric Graphs'] Let $d \geq 2$ and $r>r_c$. Then, there exist $C,c>0$ such that, for each $t>0$,
    \begin{equation*}
    \mu_v\big(v \not\in \Hh , ~\mathlcal{C}(v) \not\subseteq B(v,t)\big) \leq C e^{-c t}.
    \end{equation*}
    Furthermore, there exist $C',c,>0$ and $\beta' >1$ such that, for all $u,v \in \R^d$ and every $t> \beta' \|u-v\|$,
    \begin{equation*}
        \mu_{u,v}\big(\accentset{\rule{.4em}{.5pt}}{D}(u,v) \mathbbm{1}_{u \in\mathlcal{C}(v)}> t\big)  \leq C'e^{-c' t}.
    \end{equation*} (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T22:23:25.622331+00:00","domain":"probability theory","id":"claim_60edb1bce175b87f412e2651fbf4704d5118953b12e1f795bf5c306727a66085","kind":"concept","schema_version":1,"statement":"[Theorem thm.2d of arXiv:2609.01189, 'The lower mean curvature bound in Gromov's mean-of-the-mean-curvature conjecture'] Let $(X,g)$ be a compact connected Riemannian surface with boundary of length $L$.
Assume that
\[
  K_g\geq -c^2
\]
with a constant $c\ge0$.
Then
\begin{equation}
  \int_{\partial X} \kappa_g
  \leq
  \begin{cases}
    \sqrt{4\pi^2+c^2L^2},& \text{if $X$ is homeomorphic to a 2-disk,}\\
    cL,& \text{otherwise.}
  \end{cases}
\end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T20:36:16.065155+00:00","domain":"probability theory","id":"claim_60edb7cc18d0605dea982cd651218a92f9b7a60dfdb39873c52bd04889871285","kind":"lemma","schema_version":1,"statement":"[Lemma lemma_reg_wasserstein of arXiv:2606.28067, 'Ergodic approximation for the invariant distribution: An abstract framework for law-depend'] Let $1\le p<p^{\prime }$. Suppose that $
		\mu(\omega,dx)$ and $\nu(\omega,dx)$ are random probability measures on~${\ 
			\mathbb{R}}^d$ such that $\left\Vert \mu \right\Vert _{p^{\prime
		}}^{p^{\prime }}+\left\Vert \nu \right\Vert _{p^{\prime }}^{p^{\prime
		}}<\infty$. We assume that there exists an exponent $\mathbf{e}_d>0$ such that 
		\begin{equation} \exists C \in {\mathbb R}_+,\ \forall x \in {\mathbb R}^d, \forall r \in (0,1], \ S_{\mu ,\nu ,1}(\phi_r(x-\cdot)) \le C r^{-\mathbf{e}_d}\overline{W}_{1}^{\mathcal{A}}(\mu ,\nu ).
		\end{equation}		
		Let $\hat{p}=\frac{p(p^{\prime }-p)}{
			(\mathbf{e}_d+p)(p^{\prime }-p)+(d+p)p}$. Then, there exists a constant $C\in {\mathbb{R}}_+$ depending on 
		$p$, $p^{\prime }$ and $d$ such that  
		\begin{equation}
			\mathbb{E}[W_{p}^{p}(\mu ,\nu )]\leq C (1+ \left\Vert \mu \right\Vert
			_{p^{\prime }}^{p^{\prime }}+\left\Vert \nu \right\Vert _{p^{\prime
			}}^{p^{\prime }})^{1-\hat{p}} \overline{W}^{\mathcal{A}}_{1}(\mu ,\nu )^{\hat{p}}.

