	\end{align}
	and 
	\begin{eqnarray}
	\sup_{0\le t\le T} \left(\big\Vert f_\varepsilon(t) \big\Vert_{\mathrm{H}^{1,\varepsilon}}\vee \big\Vert g_\varepsilon(t) \big\Vert_{\mathrm{H}^{1,\varepsilon}}\right)\le C .
	\end{eqnarray} (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T21:44:17.443407+00:00","domain":"probability theory","id":"claim_6112de582eac112c0c8b6ad9b211b23edecc79edc8e35f64037dc816c7daa0c3","kind":"concept","schema_version":1,"statement":"[Proposition prop:certified-stopping-rules of arXiv:2608.25551, 'Beyond Optimal Rates in Stochastic Optimization: Trajectory-Adaptive Stopping Rules'] Fix $\alpha \in (0,1)$ and $\varepsilon > 0$.
\begin{itemize}
    \item[(i)] If $\{U^{\mathrm{dist}}_{t+1}(\alpha)\}_{t \ge t_0}$ is an anytime-valid upper confidence sequence for $\{Z_{t+1}\}_{t \ge t_0}$, then
    \[
        \mathbb{P}\left(
            \{\tau^{\mathrm{dist}}_\varepsilon(\alpha) < \infty\}
            \cap
            \left\{
                \norm{
                    x_{\tau^{\mathrm{dist}}_\varepsilon(\alpha)+1}
                    - x^\star
                }^2
                >
                \varepsilon
            \right\}
        \right)
        \le
        \alpha.
    \]

    \item[(ii)] If $\{U^{\mathrm{sub}}_t(\alpha)\}_{t \ge t_0}$ is an anytime-valid upper confidence sequence for $\{\bar F_t\}_{t \ge t_0}$, then
    \[
        \mathbb{P}\left(
            \{\tau^{\mathrm{sub}}_\varepsilon(\alpha) < \infty\}
            \cap
            \left\{
                f\bigl(
                    \bar x_{\tau^{\mathrm{sub}}_\varepsilon(\alpha)}
                \bigr)
                -
                f(x^\star)
                >
                \varepsilon
            \right\}
        \right)
        \le
        \alpha.
    \]
\end{itemize}
Thus, for each stopping rule separately, with probability at least $1 - \alpha$, whenever the stopping time is finite, the returned iterate satisfies the prescribed accuracy requirement. (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

