\end{equation}
    The constant $K_0$ is equal to 

\begin{equation} 
    K_0=\sum_{n=1}^\infty \int_{[{\lambda^o},A)} \lambda \bar{G}_{\ell}(n, (A-\lambda) \textrm{-}) \Pi(n-1, d \lambda) \ .

