{"assumptions":[],"created_at":"2026-10-26T20:48:17.123726+00:00","domain":"probability theory","id":"claim_62cc84a0b2c585005cc92631ff821558a6ecab4b78461411bbc0aa4ef997b096","kind":"concept","schema_version":1,"statement":"[Prop 12 of arXiv:2605.27713, 'Lower path regularity in all dimensions'] Suppose that $X=(X_t)_{t\in[0,T]}$ satisfies Assumption \ref{a1} (i). Let $0\leq \alpha < d$ and $0\leq \beta \leq 1$ be such that 
		\eqref{eq:key-restriction} holds and let $n$ be an even integer. Then for every $0 \leq u < v\leq T$ and $x,h \in \rd$ we have
		\begin{equation}
			\E \lvert L^{\alpha,X}(x,[u,v])\rvert^n \leq c_9^n n^{H\left(\theta+d-\alpha\right)n}(v-u)^{\left(1-H\left(d-\alpha\right)\right)n}[\log(e+(v-u))]^{2nd\zeta}
		\end{equation}
		and
		\begin{multline}
			\E [L^{\alpha,X}(x+h,[u,v])-L^{\alpha,X}(x,[u,v])]^{n}\\
			\leq \|h\|^{\beta n}   c_9^n n^{H\left(\theta+d-\alpha+\beta\right)n}(v-u)^{\left(1-H\left(d-\alpha+\beta\right)\right)n}[\log(e+(v-u))]^{2nd\zeta}
		\end{multline}
		with a constant $c_9>0$ depending only on $T$, $d$, $H$, $\alpha$ and $\beta$ and where $\zeta=1$ if $\beta<\alpha$ while $\zeta=0$ if $\beta\geq \alpha$. (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T09:38:13.638403+00:00","domain":"probability theory","id":"claim_62d1a3cfc469db02b522bd23fc6f2302450b7cb591c538b047210232135a8316","kind":"theorem","schema_version":1,"statement":"[Corollary 4 of arXiv:2609.00687, 'A unification of Euler-Maclaurin and Euler-Boole summation formulas'] Let $q\in\mathbb{N}$, $m\in\mathbb{N}_{0}$ and $a,b\in\mathbb{R}$ with $2\mid q$ and $a<b$. Let $\chi$ be a Dirichlet character modulo $q$ and let $f(t)$ be an $m+1$
times continuously differentiable function on the interval $[a,b]$. Then
\begin{eqnarray}
&&\sum_{\substack{a<k\leqslant b\\k\in\mathbb{Z}}}(-1)^{k}\chi(k)f(k)\nonumber\\
&&\qquad=\sum_{k=0}^{m}\frac{(-1)^{k+1}}{(k+1)!}\bigl(\widehat{B}_{k+1}(\{b\}_{\chi},\chi^{-})f^{(k)}(b)-\widehat{B}_{k+1,\chi^{-}}(\{a\}_{\chi},\chi^{-})f^{(k)}(a)\bigl)\nonumber\\
&&\qquad\quad+\widehat{B}_{0}(\chi^{-})\int_{a}^{b}f(t)dt\nonumber\\
&&\qquad\quad+\frac{(-1)^{m}}{(m+1)!}\int_{a}^{b}\widehat{B}_{m+1}(\{t\}_{\chi},\chi^{-})f^{(m+1)}(t)dt,
\end{eqnarray}
where
\begin{equation*}
\widehat{B}_{0}(\chi^{-})=\frac{1}{q}\sum_{r=1}^{q}(-1)^{r}\chi(-r),
\end{equation*}
and
\begin{equation*}
\widehat{B}_{m}(\{x\}_{\chi},\chi^{-})=q^{m-1}\sum_{r=1}^{q}(-1)^{r}\chi(-r)B_{m}\biggl(\biggl\{\frac{x+r}{q}\biggl\}\biggl).
\end{equation*}","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T13:04:55.814186+00:00","domain":"probability theory","id":"claim_62d9f0c863d94832a93c090becea87fba46a331754d878c964c8bc9d6c516d4e","kind":"lemma","schema_version":1,"statement":"[Lemm l:coincidence-with-CDRP of arXiv:2607.18194, 'Temperature chaos in directed polymers'] {QRV25}}]
