{"assumptions":[],"created_at":"2026-10-27T08:12:13.421847+00:00","domain":"probability theory","id":"claim_62dfe2c3ee75ff30a6f5f8c8e6c83a2f3d5f341a35f747d0b45e8c730b5417c1","kind":"definition","schema_version":1,"statement":"[Defn 85 of arXiv:2608.28200, '\textbf On the Formality of Configuration Spaces of $\aka$'] Let $\Gamma$ be a diagram and let $e$ be a contractible edge of $\Gamma$. The diagram obtained from $\Gamma$ by contraction of the edge $e$ is the diagram $\Gamma/e$ defined as follows: 
\begin{itemize}
\item $A_{\Gamma/e}=A_\Gamma$
\item $I_{\Gamma/e}=I_{\Gamma} \setminus \lr{\max(s_\Gamma(e),t_{\Gamma}(e))}$
\item $E_{\Gamma/e}=E_\Gamma\setminus \lr{e}$
\item $s_{\Gamma/e}=q\circ s_\Gamma$ and $t_{\Gamma/e}=q\circ t_\Gamma$ where $q$ is defined by 
\ali{
q: V_\Gamma & \lra V_{\Gamma/e} \\
v & \lmt \begin{cases}
\min (s_\Gamma(e),t_{\Gamma}(e)) & v=\max(s_\Gamma(e),t_{\Gamma}(e)) \\
v & \mathrm{otherwise}
\end{cases}
}
where the linear orders on $I_{\Gamma/e}$ and $E_{\Gamma/e}$ are restrictions. 
\item $W^V_{\Gamma/e}=\begin{cases}
W^V_{\Gamma}(s_\Gamma(e))\cdot W^V_{\Gamma}(t_\Gamma(e)) & w=\min (s_\Gamma(e),t_{\Gamma}(e)) \\
W^V_{\Gamma}(w) & \text{else} \\
\end{cases}$
\item $W^E_{\Gamma/e}=W^E_{\Gamma}|_{E_{\Gamma/e}}$
\end{itemize}","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T19:06:39.356338+00:00","domain":"probability theory","id":"claim_62e1b9f79f788608a291410e6bdd81ceac3ebf6320d6ca96185dc3257374539b","kind":"lemma","schema_version":1,"statement":"[Lemma l:compactness of arXiv:2607.15140, 'On the absence of blow-up in the 3D Navier-Stokes equations with transport noise'] Fix 
$$
\gamma,\sigma,\eta,\varepsilon>0, \qquad 1<p_0,q_0<\infty, \qquad p_1\in (2,p_0),\ q_1\in (2,q_0),
$$
and a sequence $\mathbf{a}=(a_n)_{n}$ of strictly positive numbers. Let
\begin{align*}
\mathscr{Y}
&=C_{{\rm loc}}^{\mathbf{a},\gamma}([0,\infty);H^{-\sigma}) \cap C_{\eta}([0,\infty);L^2)\cap  L^2 ({\mathbb R}_+;H^1)\cap L^{p_0}({\mathbb R}_+;L^{q_0}),\\
\mathscr{X}
&=L^{p_1}({\mathbb R}_+;L^{q_1})\cap C_{0}([0,\infty);H^{-\varepsilon}).
\end{align*}
Then, the embedding $\mathscr{Y}\hookrightarrow \mathscr{X}$ is compact. Moreover, for all $K\geq 1$, 
$$
\mathscr{X}_{K}=\big\{f\in \mathscr{X}\,:\, \|f\|_{L^2({\mathbb R}_+;H^1)}\leq K\big\}
$$
is a closed subset of $\mathscr{X}$.","status":"unverified"}

