\end{equation}
Moreover, for every $\delta>0$,
\begin{equation}
 \sum_{Q>M}Q^{-\delta}\lesssim_\delta M^{-\delta},
 \qquad
 \sum_{Q>L}Q^{-\delta}\lesssim_\delta L^{-\delta}.
\end{equation}","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T22:46:36.093018+00:00","domain":"probability theory","id":"claim_6342a90e7d42bf33433679cc93097759712dffd3fd96d799fdc063e11b70dec1","kind":"theorem","schema_version":1,"statement":"[Proposition prop:uniform-ball-control of arXiv:2609.02710, 'Asymptotic Mean Value Laplacian\\ on equiregular sub-Riemannian manifolds'] For every compact $K\Subset O$, there exist $C\ge1$ and $r_0>0$ such that
