\end{equation}
where
\begin{equation}
A(p-q)=\left(\sum_{\alpha\in\ell}(2\mathbb N)^{(q-p)\alpha}\right)^{1/2}.
  \end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T07:21:06.859968+00:00","domain":"probability theory","id":"claim_643cb9e3d820cc07f5b0406132c3e3466bc9d4ff14ccb728d5ac852d078fa62c","kind":"lemma","schema_version":1,"statement":"[Lem 14 of arXiv:2608.21090, 'Ornstein--Uhlenbeck process conditioned to have restricted $L_2$-norm'] Let $x\in\R$, $t_0>0$ and take $h$ as defined in Lemma \ref{lem:ratiouniformasymptotics}. Assume there is a $K>0$ and $\beta\in(0,1/2)$ such that for the sequence $y_T$ we have $|y_T-\theta T|\leq K T^\beta$. Then, for any Borel-measurable $D\subset\CC([0,t_0])$, we have
    \begin{equation}
        \lim_{T\to\infty}\P_x(U\in D~\vert~Z_T\leq y_T)=\E_x\left[\1_{U\in D}\,h(U_{t_0}, Z_{t_0}, t_0)\right].
    \end{equation}","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-26T19:28:04.860192+00:00","domain":"probability theory","id":"claim_643d5acfa2b65a013cd05b7161a746e266caf056735992dc25100e4bf0ef54ad","kind":"lemma","schema_version":1,"statement":"[Lem 22 of arXiv:2511.21496, 'Optimal local central limit theorems on Wiener chaos'] Let $F \in \bW^{k+1, p}$, $\Delta_F^{-1} \in L^q(\Omega)$, and $G \in \bW^{k, r_0}$ for some $k \in \N_0$ and $p, q, r_0 \in (1, \infty)$. 
Define $r_j, \ j \in \{1, \ldots, k+1\}$ by 
\begin{equation}
    \frac{1}{r_j} = \frac{1}{r_0} + \sum_{i=0}^{j-1} \left( \frac{2k+1-2i}{p} + \frac{k+1-i}{q} \right) = \frac{1}{r_0} + \frac{j(2k+2-j)}{p} + \frac{j(2k+3-j)}{2q}. 
\end{equation}
If $r_j > 1$ for some $j \in \{1, \ldots, k+1\}$, then for every $i \in \{1, \ldots, j\}$, we have
\begin{equation}
    \Theta_F^{\circ (i-1)}(G) \Delta_F^{-1} DF \in \bW^{k-i+1, r_i}(\fH), \qquad  \Theta_F^{\circ i}(G) \in \bW^{k-i, r_i},
\end{equation}
and 
\begin{equation}
    \norm{\Theta_F^{\circ i}(G)}_{\bW^{k-i, r_i}} \lesssim_{i,k,p,q,r_0} \norm{G}_{\bW^{k,r_0}} \norm{F}_{\bW^{k+1, p}}^{i(2k+2-i)} \norm{\Delta_F^{-1}}_{L^q(\Omega)}^{\frac{i(2k+3-i)}{2}}.
\end{equation}","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T19:26:26.794037+00:00","domain":"probability theory","id":"claim_6440c5026ec70593d3b35bcb389d0c88028e951072a1099ad75c99ffb3bbdc04","kind":"theorem","schema_version":1,"statement":"[Corollary cor:ClusterBound of arXiv:2608.05105, 'Cluster-Cluster model in $\mathbb{Z}^d$'] Let $p=1$ and $\alpha>0$. Write $f(t)$ for the cluster density, i.e.,  
\begin{equation*}
    f(t):=   \sum_{m \geq 1} \frac{V_m(t)}{m}  = {\mathbb{E}}\left[ \frac{1}{\mathfs{K}_0(t)}\right]
\end{equation*}
with $V_m(t)$ from (equation def:Vmt of the paper). Then there exist constants $C_1,C_2,C_3>0$ such that
\begin{equation}
    f(t)\le (C_1 t +C_2)^{-1/\alpha}
\end{equation} for all $t>0$. Moreover, we get that
\begin{equation}
    {\mathbb{E}}\left[|\mathfs{K}_0(t)|\right]\ge\frac{1}{f(t)}\ge C_3 t^{\frac{1}{\alpha}} , 
\end{equation}
and that for every $\epsilon$ there exists $c > 0$ such that for all $t$ large enough
\begin{equation}
    {\mathbb{P}}\left[|\mathfs{K}_0(t)|\ge C_3 t^{\frac{1}{\alpha}}\right] \geq 1 - \epsilon. 
\end{equation}","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T10:02:28.652379+00:00","domain":"probability theory","id":"claim_6443995104277648e1cf6ab60651410181fbef02755d33be807ca63ac6471ae3","kind":"lemma","schema_version":1,"statement":"[Lem 33 of arXiv:2609.01389, 'K-stability and birational rigidity of Fano 3-fold weighted complete intersections'] The defining polynomials of $X$ can be written as 
\[
\begin{split}
\msF_1 &= z w + s t + w f_2 + f_6, \\
\msF_2 &= z^3 y + z^2 (\delta x s + \varepsilon x t + g_4) + z (\alpha s^2 + \beta t^2 + \gamma s t + w g_2 + g_6) \\
&\hspace{6cm} + w^2 + w h_4 + g_8,
\end{split}
\]
where $\alpha, \beta, \gamma, \varepsilon \in \mbC$, $f_2, f_6, g_2, g_4 \in \mbC [x, y]$ and $g_6, g_8, h_4 \in (x, y) \subset \mbC [x, y, s, t]$ with $g_6, g_8 \in (x^2, y)$.","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T13:20:07.901782+00:00","domain":"probability theory","id":"claim_6445cde7d4070863190deb87e4aca79b21b41f82381e2e8ce384090f43734636","kind":"theorem","schema_version":1,"statement":"[Proposition prop:p1:linearrate of arXiv:2608.23765, '\texorpdfstring{Tight Majorizations and Convergence Rates\\ of Nuclear Norm Minimization I'] Let $\mathbf{X}_\star \in \R^{d_1 \times d_2}$. Assume that the measurement operator $\mathcal{A}: \mathbb{R}^{d_1 \times d_2} \longrightarrow \R^m $ 
	satisfies the NSP (eq:NSP:definition of the paper) of order $r$ for some $0 < \eta_r<1$ 
	and that $ \mathbf{y} = \mathcal{A} \left(  \mathbf{X}_\star \right) $.
	Let the IRLS iterates  $\left\{   \mathbf{X}^{(k)} \right\}_k$ and $ \left\{ \varepsilon_{k} \right\}_k$ be defined by (eq:IRLS:step_1 of the paper) and (eq:IRLS:step_2 of the paper) of (alg:algo1 of the paper) with arbitrary positive definite initial weight operator $W^{(0)}$ and rank estimate $\widetilde{r} =r$, and assume that (alg:algo1 of the paper) does not return in iteration $k$, i.e., that $\varepsilon_k > 0$, so that the iterate $\mathbf{X}^{(k+1)}$ is defined.
	Assume that the weight operator $\W{\mathbf{X}^{(k)}}{\varepsilon_k}(\cdot)$ used in each iteration of (alg:algo1 of the paper) is defined as in (def:weightcore of the paper) 
	is admissible in the sense of (def:admissible:weightoperators of the paper), let $c_q$ be the weight operator-dependent constant (eq:c_q:def of the paper) of (lemma:normbound:hadamard of the paper).
	Set
	\begin{equation*}
	\gamma :=
	\begin{cases}
	3/4 \quad & \text{if } \besterrNuc{\mathbf{X}_\star}{r}=0, \\
	1/2 \quad & \text{otherwise}.
	\end{cases}
	\end{equation*}
	If 
	\begin{equation*}
		\besterrNuc{\mathbf{X}_\star}{r}  \le  \frac{1}{9} \nucnorm{\mathbf{X}_\star -\mathbf{X}^{(k)}}
	\quad \text{and} \quad
	\gamma > \frac{2\eta_r}{1+\eta_r},
	\end{equation*}
	then it holds that
	\begin{equation*} 
		\mathcal{J}_{\varepsilon_{k+1}}( \mathbf{X}^{(k+1)} ) -  \nucnorm{\mathbf{X}_\star} \le \left(  1-  \frac{ C_{\eta_r,\gamma}  }{ c_q \eta_1  d }\right) \left(     \mathcal{J}_{\varepsilon_{k}} \left( \mathbf{X}^{(k)}  \right) -  \nucnorm{ \mathbf{X}_\star } \right)
	\end{equation*} 
	where the constant $C_{\eta_r}$ is defined by 
	\begin{equation*}
	C_{\eta_r,\gamma}
	:=
	\frac{\left( \gamma - \frac{2\eta_r}{1+\eta_r}  \right)^2 }{\left( 3 + 2\eta_r \right)}.
	\end{equation*}","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T19:37:08.315115+00:00","domain":"probability theory","id":"claim_64464426aef0695b848f7d536cbae840c1137b2686c38d242e3901371c1e6b2c","kind":"concept","schema_version":1,"statement":"[Cor:distinguished of arXiv:2608.30973, 'Pseudo-Anosov flow and dynamics on guts'] Let \(z\in \mathcal{C}_{2}(\varphi)\) and let \(D_{n}(z)\) be the set of regular closed orbits which is \(z\)-distinguished in at least \(n\) directions. Then
