    \end{aligned}\end{equation}
    where $H_1=H_{[n-d]\times[d]}$, $H_2=H_{[n-d]\times[d+1,2d]}$ and $R=2^{44}B^2c_0^{-3}(\frac{8}{\sqrt{\nu p}}+\frac{256B^2}{\sqrt{c_0}})$.","status":"unverified"}

