{"assumptions":[],"created_at":"2026-10-26T20:58:53.193398+00:00","domain":"probability theory","id":"claim_652307b06a4dc65d81fca8f1d72ad379805a12d5ab675596b93512ca212ca53e","kind":"theorem","schema_version":1,"statement":"[Corollary 20 of arXiv:2606.31455, 'Discrete time-multidimensional renewal theory and applications'] Assume $\mathbbm{E}\!\left[(X_1^{[u]})^2\right]<\infty$ for all $u=1,\ldots,d$ and let
$k_{1:d}\stackrel{\lambda}{\to}\infty$ in the sense of \eqref{eq:lambda-scaling}.
Set $\mu_u:=\mathbbm{E}[X_1^{[u]}]$ and

\begin{equation*}
\mu_\lambda:=\min_{1\le u\le d}\left\{\frac{\lambda^u}{\mu_u}\right\}.
\end{equation*}

\noindent
\emph{Interpretation.}
Since $N(k)=\min_{u}N^{[u]}(k_u)$ and $N^{[u]}(k_u)\approx k_u/\mu_u$ for large $k_u$,
the smallest linear trend $\min_u k_u/\mu_u$ governs the asymptotic growth of $N(k)$.
If the minimizer is unique, the corresponding coordinate becomes the unique active constraint
and eventually $N(k)=N^{[u_\lambda]}(k_{u_\lambda})$ along the direction $\lambda$.

Now, assume that this minimum is attained at a unique index $u_\lambda\in\{1,\ldots,d\}$, i.e.

\begin{equation}
\frac{\lambda^{u_\lambda}}{\mu_{u_\lambda}}
<
\frac{\lambda^{v}}{\mu_{v}},
\qquad v\neq u_\lambda.
\end{equation}

Let $\sigma_{u_\lambda}^2:=\mathrm{Var}(X_1^{[u_\lambda]})$. Then

\begin{equation}
\frac{N(k_{1:d})-\frac{k_{u_\lambda}}{\mu_{u_\lambda}}}{\sqrt{|k|_1}}
\xrightarrow[k_{1:d}\stackrel{\lambda}{\to}\infty]{d}
\mathcal{N}\!\left(0,\ \lambda^{u_\lambda}\,\frac{\sigma_{u_\lambda}^2}{\mu_{u_\lambda}^3}\right).
\end{equation}

If in addition the deterministic scaling satisfies
$k_{u_\lambda}=\lambda^{u_\lambda}|k|_1+o(\sqrt{|k|_1})$, then \eqref{eq:clt-N-unique-centered-ku}
is equivalent to

\begin{equation}
\sqrt{|k|_1}\left(\frac{N(k_{1:d})}{|k|_1}-\mu_\lambda\right)
\xrightarrow[k_{1:d}\stackrel{\lambda}{\to}\infty]{d}
\mathcal{N}\!\left(0,\ \lambda^{u_\lambda}\,\frac{\sigma_{u_\lambda}^2}{\mu_{u_\lambda}^3}\right).
\end{equation}","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T13:12:09.044881+00:00","domain":"probability theory","id":"claim_6523a33d670a6bdca459303e1442fdc66bb3e9665c3c53ea79ffdbb3cdc3ee3c","kind":"lemma","schema_version":1,"statement":"[Lemma lem:interiorcycle of arXiv:2608.25279, 'Provable Non-Acceleration of Standard Strang\\ Splittings of Kinetic Langevin Dynamics'] Let $C_\star>C_{\mathrm{GTD}}=(3+\sqrt5)^2$, let $\kappa\ge2C_\star$, and let $(s,\beta)\in(0,\infty)\times(0,1)$ satisfy the numerical stability condition (equation eq:HBstability of the paper) with
