{"assumptions":[],"created_at":"2026-10-27T06:39:11.674088+00:00","domain":"probability theory","id":"claim_6544ccb3eb32eb54be162e3944527ab511734ddd673f8416bbcb0dd9ad2e5e44","kind":"lemma","schema_version":1,"statement":"[Lemma 12 of arXiv:2608.04853, 'Minimal-Norm Extensions of Stationary Kernels on Subgroups of Locally Compact Abelian Grou'] Let $G$ be a locally compact abelian group and let $H\subseteq G$ be a closed subgroup. Let $k:G \times G \to \R$ be a stationary kernel with spectral density $\hat{k}:\hat{G} \to \R$.
Define
\begin{align*}
    \hat k_H(\xi_H)
:=
\int_{H^\perp}
\hat k(\xi_H+\xi^\perp) \d\xi^\perp,
\qquad
\xi_H\in \hat G/H^\perp\simeq \widehat H.
\end{align*}
Let $g\in\mathcal N(H)$. Then the unique solution of the minimal-norm extension problem
\begin{align*}
    \min
\left\{
\Vert f\Vert_{\mathcal N(G)}^2
=
\int_{\hat G}
\frac{|\hat f(\xi)|^2}{\hat k(\xi)} \d\xi
 \, \middle| \, 
f\in\mathcal N(G),\ f|_H=g \right\}
\end{align*}
is characterized on the Fourier side by
\begin{align*}
    \hat f(\xi_H+\xi^\perp)
=
\hat g(\xi_H)
\frac{\hat k(\xi_H+\xi^\perp)}
{\hat k_H(\xi_H)}
\end{align*}
for almost all $\xi_H\in \hat G/H^\perp$ and $\xi^\perp\in H^\perp$. On the set where $\hat k_H=0$, the quotient is interpreted as zero.","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-28T01:10:08.764816+00:00","domain":"probability theory","id":"claim_6549b2feea85f35b98f19fad185a71f60d12eeebc4c19bfc1973e657071452b2","kind":"lemma","schema_version":1,"statement":"[Lem thm:1+eps-exp of arXiv:2411.18155, 'Besov regularity of random wavelet series'] Let $(X_{j,\tau})_{j\in\mathds{N}_0,\tau\in\mathds{N}}$ be a family of non-negative i.i.d.\ random variables, $d\in\mathds{N}$, $C,\eps\in (0,\infty)$, and $\sigma\in [1,\infty)$.
Suppose that
\begin{equation*}
\mathds{E}[\exp(CX_{j,\tau}^\sigma)]<\infty.
\end{equation*}
Fix $d\in\mathds{N}$ and let
\begin{align*}
M_j&\mathrel{\mathop:}= \#\setcond{m\in\mathds{Z}^d}{\left\lVertm\right\rVert_{\infty}\leq 2^j}=(2^{j+1}+1)^d\\
N_j&\mathrel{\mathop:}=\#\setcond{m\in\mathds{Z}^d}{2^j<\left\lVertm\right\rVert_\infty\leq 2^{j+1}}=M_{j+1}-M_j\\
\end{align*}
for $j\in\mathds{N}_0$.
Then, for
\begin{equation*}
\Xi\mathrel{\mathop:}= \sup_{j \in \mathds{N}_0} \lr{\frac{1}{M_j} \sum_{\tau=1}^{M_j} X_{j,\tau}+\sup_{\ell\geq j} \frac{1}{N_\ell} \sum_{\tau=M_\ell + 1}^{M_{\ell+1}} X_{j,\tau}},
\end{equation*} 
we have $\mathds{E}\left[\exp\lr{\frac{C}{2^{\sigma+1}(1+\eps)} \Xi^\sigma}\right]<\infty$.","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T12:27:11.219921+00:00","domain":"probability theory","id":"claim_6549e73dcc5b62cc261c5814b0ee2ad1041759001e50098919f0131667a1c8bd","kind":"lemma","schema_version":1,"statement":"[Lemma no-eigenvalue outside support of arXiv:2605.19894, 'Sharp Spectral Thresholds for Multi-View Spiked Wigner Models'] For a compact set $S\subset\RR$, write
