{"assumptions":[],"created_at":"2026-10-27T11:40:59.382217+00:00","domain":"probability theory","id":"claim_65e04ee775423e3fabac8de2010bf67e8d2e0febc927b153ae16fc75936e7531","kind":"lemma","schema_version":1,"statement":"[Lemma 17 of arXiv:2609.03962, '$L^p$ isomorphisms for the fractional Laplacian on $\mathbb{R}^n$ and their application'] Let $p\in(1,\infty)$ and $0<\alpha<\beta\le2$, with the convention
    $(-\triangle)^{\frac{2}{2}}:=-\triangle$. Then
    \begin{equation}
        \norm{(-\triangle)^{\frac{\alpha}{2}}f}_{L^p(\R^n)}
        \lesssim_{\alpha,\beta,p}
        \norm{f}_{L^p(\R^n)}^{1-\frac{\alpha}{\beta}}\,
        \norm{(-\triangle)^{\frac{\beta}{2}}f}_{L^p(\R^n)}^{\frac{\alpha}{\beta}},
        \qquad f\in\mathscr S(\R^n).
    \end{equation}
    In particular, for all $f\in\mathscr S(\R^n)$,
    \begin{align}
        \norm{(-\triangle)^{\frac{\sigma}{2}}f}_{L^p(\R^n)}
        &\lesssim\norm{f}_{L^p(\R^n)}^{1-\sigma}\,
          \norm{Df}_{L^p(\R^n)}^{\sigma},
        &&0<\sigma<1,\\
        \norm{\flap f}_{L^p(\R^n)}
        &\lesssim\norm{f}_{L^p(\R^n)}^{1-\frac{s}{2}}\,
          \norm{D^2f}_{L^p(\R^n)}^{\frac{s}{2}},
        &&0<s<2,\\
        \norm{Df}_{L^p(\R^n)}
        &\lesssim\norm{f}_{L^p(\R^n)}^{1-\frac{1}{s}}\,
          \norm{\flap f}_{L^p(\R^n)}^{\frac{1}{s}},
        &&1<s<2.
    \end{align}","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T22:46:36.096478+00:00","domain":"probability theory","id":"claim_65e3b5000088590e9fc02a694709d8f4b542c6ae9460ab6f877422074a39e225","kind":"theorem","schema_version":1,"statement":"[Corollary thm:cc_iDCI of arXiv:2609.02832, 'Copula Transformations for Data-Consistent Inversion'] Let $
