{"assumptions":[],"created_at":"2026-10-27T23:03:39.771867+00:00","domain":"probability theory","id":"claim_66037964229e0bcf8f015504af22aad2001dc5c42f1cb9cdc0fd11c99a6e61fd","kind":"theorem","schema_version":1,"statement":"[Prop admissibility-vs-shift-new of arXiv:2411.03065, 'Growing conditioned BGW trees with\\ log-concave offspring distributions'] Let $d\geq1$ and $s\in\{0,1,\dots,d-1\}$.
	Let $({\mathbf{a}},{\mathbf{b}})$ be a $(d,s)$-non-degenerate weight pair.
	Then there holds the following.
	\begin{enumerate}
		\item 
		\begin{enumerate}
			\item If $d=1$, $s=0$ and $r_{1,0}({\mathbf{a}})=1$, that is if ${\mathbf{a}}=(a_0,a_1,0,0,\dots)$, then $({\mathbf{a}},{\mathbf{b}})$ is $(1,0)$ admissible.
			\item If $d\geq 2$, $s=1$ and $r_{d,s}({\mathbf{a}})=0$, that is if ${\mathbf{a}}=(0,a_1,0,0,\dots)$, then $({\mathbf{a}},{\mathbf{b}})$  is $(d,1)$-admissible.
		\end{enumerate}
		\item
		\begin{enumerate}
			\item If $s\neq 0$ and the weight pair $({\mathbf{a}}^+,{\mathbf{b}})$ is $(d,s-1)$-admissible and if the inequalities
			\begin{align}
			\frac{\PFComp{{\mathbf{a}}^+,{\mathbf{b}}}{(n+1-m)d+(s-1)}}{\PFComp{{\mathbf{a}}^+,{\mathbf{b}}}{(n-m)d+(s-1)}}
			\leq
			\frac{\PFComp{{\mathbf{a}},{\mathbf{b}}}{(n+1)d+s}}{\PFComp{{\mathbf{a}},{\mathbf{b}}}{nd+s}}
			\geq
			\frac{b_{md+1}}{b_{(m-1)d+1}},
			\end{align}
			are satisfied for $m=1,\dots,n$, then $({\mathbf{a}},{\mathbf{b}})$ is $(d,s)$-admissible.
			\item If $s= 0$ and the weight pair $({\mathbf{a}}^+,{\mathbf{b}})$ is $(d,d-1)$-admissible and if the inequalities
			\begin{align}
			\frac{\PFComp{{\mathbf{a}}^+,{\mathbf{b}}}{(n+1-m-1)d+(d-1)}}{\PFComp{{\mathbf{a}}^+,{\mathbf{b}}}{(n-m-1)d+(d-1)}}
			\leq
			\frac{\PFComp{{\mathbf{a}},{\mathbf{b}}}{(n+1)d}}{\PFComp{{\mathbf{a}},{\mathbf{b}}}{dn}}
			\geq
			\frac{b_{md+1}}{b_{(m-1)d+1}},
			\end{align}
			are satisfied for $m=1,\dots,n-1$, then $({\mathbf{a}},{\mathbf{b}})$ is $(d,0)$-admissible.
		\end{enumerate}
	\end{enumerate}","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T12:17:13.069924+00:00","domain":"probability theory","id":"claim_6604a0bb39d7eaf5d7c567364e38ca27f3bb2464e4ecd96a4266e20c8c87b5bc","kind":"concept","schema_version":1,"statement":"[Lemma lem:N-ball-type-4 of arXiv:2509.06273, 'Normalized Matching Property for Competing Urn Models'] Suppose that $e$ and $f$ are incident to $v_{n}$, with 
