\item all points $(s\xi)^{-1}$ is outside of the contour $\mathcal C$;
\item the image $q\mathcal C$ of the contour $\mathcal C$ under the multiplication by $q$ is inside $\mathcal C$.
\end{itemize}
\begin{equation*}
\mathbb{F}_{\lambda}(x_1,\dots, x_n\mid\xi,s)\\
=\xi^{-|\lambda|}\oint_{\mathcal C}\frac{du_1}{2\pi\mathbf i u_1}\dots\oint_{\mathcal C}\frac{du_k}{2\pi\mathbf i u_k}\prod_{i<j}\frac{u_i-u_j}{u_i-qu_j}\prod_{i=1}^k\(\frac{(1-s\xi u_i)^{\lambda_i'-1}}{(u_i-\xi^{-1}s)^{\lambda'_i}}\prod_{j=1}^n\frac{1-u_ix_j}{1-u_i\xi s}\).
\end{equation*} (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T21:04:07.029565+00:00","domain":"probability theory","id":"claim_66447a27498e9d982b4a1d7abaadb5a6e153bea762908c44fb6aea9320258f07","kind":"lemma","schema_version":1,"statement":"[Lemma lem:parisi-maximal-estimate of arXiv:2607.29330, 'Large deviations for the maximum of\\ the generalized TAP free energy'] For the fixed finite-step order parameter $\zeta$, as
