{"assumptions":[],"created_at":"2026-10-27T19:11:35.833322+00:00","domain":"probability theory","id":"claim_664af6b44f5bff468e0dcb671560c3627dfe43c1887e7476b4d8f7fc94e93c88","kind":"concept","schema_version":1,"statement":"[Theorem t:linvar of arXiv:2607.25567, 'Random Trees in Hyperbolic FPP'] {BM19}}]

