{"assumptions":[],"created_at":"2026-10-26T20:23:03.030620+00:00","domain":"probability theory","id":"claim_66961b1ddd7cb24a6a4c7bc1057aac8d5553308da86c5ac638cd89734bd585ca","kind":"lemma","schema_version":1,"statement":"[Lemma 11 of arXiv:2605.02713, '2605.02713'] \begin{itemize}
		\item[(i)] If $\sigma_n^2 \gg  (1 - \alpha_n^2) $ consider $f=\sum_{q=m}^p c_q H_q$. Then 
		\begin{align*}
			\hat{S}_{n,t}(f) &= c_p \hat{S}_{n,t}(H_p)  + R_{n,t}(f), 
		\end{align*}
		where $R_{n,t}(f) \longrightarrow_{L^2} 0$ for $n \to \infty$. Moreover,  with $C_{p,l}=\frac{p!}{l! (p-2l)! 2^l}$,  \begin{align*}
			\hat{S}_{n,t}(H_p) &= \frac{  \big( \mathrm{Var} X_{1,n} \big)^{p/2} \sum_{i=1}^{\lfloor nt \rfloor}   \sum_{l=0}^{\lfloor (p-1)/2 \rfloor} C_{p,l} H_{p-2l}  \big( Z_{i,n} \big)}{\sqrt{\mathrm{Var}S_{n,1}(H_p)}} \big(1 + o_{n,\mathrm{unif}}(1) \big) \quad\text{and}\\
			\mathrm{Var} S_{n,t}(H_p) &=  \left( \mathrm{Var} X_{1,n} \right)^{p}  \sum_{l=0}^{\lfloor p/2 \rfloor}  C_{p,l}^2 (p-2l)! \Lambda_{p-2l}(n,t)\big(1 + o_{n,\mathrm{unif}}(1) \big) . 
		\end{align*}
		\item[(ii)] If $\sigma_n^2 = \sigma^2 (1 - \alpha_n^2) $ consider $f = \sum_{q=m}^\infty c_q H_q ( \cdot; \sigma^2) \in L^2 \left(\mathcal{N} \left(0, \sigma^2 \right) \right)$. Then 
		\begin{align*}
			\mathrm{Var} S_{n,t}(f) = \sum_{q=m}^\infty  c_q^2 q!  \left(   \sigma^2  \right)^q \Lambda_{q}(n,t) 
		\end{align*}  
		for any $t\in [0,1]$.
		\item[(iii)] If $\sigma_n^2 \ll  (1 - \alpha_n^2) $ consider  $f=\sum_{q=m}^p c_q H_q$. Then 
		\begin{align*}
			\hat{S}_{n,t}(f)  = \frac{ \left( \mathrm{Var} X^{(n)} \right)^{m_*/2}  \sum_{i=1}^{ {\lfloor nt \rfloor} } \sum_{r=1}^{m_*} D_r^{(m_*,m,p)}     H_{r}(Z_{i,n})  }{\sqrt{\mathrm{Var} S_{n,1}(f)}} + R_{n,t}(f),
		\end{align*}
		where $R_{n,t}(f) \longrightarrow_{L^2} 0$ for $n \to \infty$, 
		\begin{align*}
			D_r^{(m_*,m,p)}  =   \sum_{s=0}^{\lfloor p/2 \rfloor}  \mathds{1}_{A_{s,r}} (m_*) \sum_{u=0}^{\lfloor p/2 \rfloor}  \mathds{1}_{B_{m,p}}(m_*+2u) \,  c_{m_*+2u} \,  C_{m_*+2u,s+u} \,  \binom{s+u}{s} (-1)^{u} ,
		\end{align*}
		where the sets are $A_{s,r}= \{ x : x=2s+r \}$ and $B_{m,p} = \{ y : m \leq y \leq p \}$, and  $m_* := \min \{w \geq 1:  \sum_{r=1}^p D_r^{(w,m,p)}  \neq 0 \}$.  Moreover, for any $t\in [0,1]$,
		\begin{align*}
			\mathrm{Var} S_{n,t}(f) = \left( \mathrm{Var} X_{1,n} \right)^{m_*} \sum_{r=1}^{m_*} \left( D_r^{(m_*,m,p)}  \right)^2 r! \; \Lambda_{r}(n,t) \big(1 + o_{n,\mathrm{unif}}(1) \big)  .
		\end{align*}
	\end{itemize}","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T16:57:16.068975+00:00","domain":"probability theory","id":"claim_6699c626fdc85fffb6b3ba05531897af40d0e2e500e75656fb3e34f1e12f62aa","kind":"concept","schema_version":1,"statement":"[Thm OPRE-percolates of arXiv:2507.00329, 'Oriented bond-site percolation in random environment and contact processes with periodic r'] Assume that the environment $(\xi_x)_{x\in\mathbb{Z}_{\geq0}},(\nu_{x,x+1})_{x\in\mathbb{Z}_{\geq0}}$ in Definition~(def:OPRE-model of the paper) is given by mutually independent families of i.i.d.\ random variables that satisfy the moment condition 
    \begin{equation}
        \mathbb{E}[\xi_0^{1+\varepsilon}], \, \mathbb{E}[\nu_{0,1}^{1+\varepsilon}]<\infty\qquad\text{for some $\varepsilon>0$}.
    \end{equation}
 Furthermore, let $(\kappa_\lambda)_{\lambda\geq 0}$ be a family of connection functions satisfying
    \begin{enumerate}[(i)]
        \item $\kappa_\lambda\colon [0,\infty)\to[0,1]$ is monotonically decreasing for every $\lambda\geq0$, and
        \item there exists some $\sigma>0$ such that, for every $s\in\mathbb{N}$,        \begin{equation}
          \exp(-\sigma s) \leq \kappa_\lambda(s)  \quad \text{ for every }\lambda\geq0, 
          \qquad\text{ as well as } \qquad
          \kappa_\lambda(s)\xrightarrow{\lambda\to\infty} 1.
        \end{equation} 
    \end{enumerate}    
    Then, there exists $\lambda_c  <\infty$ such that, for every $\lambda>\lambda_c$, the OPRE almost-surely percolates for almost-all realisations of the environment $(\xi_x)_{x\in\mathbb{Z}_{\geq0}},(\nu_{x,x+1})_{x\in\mathbb{Z}_{\geq0}}$. (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-26T19:43:44.238306+00:00","domain":"probability theory","id":"claim_669bfecadce702d79efc209c2bb5b791cad9be874b878febfb945955085fba7d","kind":"definition","schema_version":1,"statement":"[Definition 11 (Entropy chaos) of arXiv:2604.14427, 'A criterion for proving entropy chaos on path space'] We say that $\rho_N$ is $\rho-$entropic chaotic if for any fixed $t\in [0,T]$
