\lim_{n\to\infty}r_{i^{\tau_1}i^{\tau_2}\cdots i^{\tau_n}}^{-2}\cQ(A_{i^{\tau_1}i^{\tau_2}\cdots i^{\tau_n}}u,A_{i^{\tau_1}i^{\tau_2}\cdots i^{\tau_n}}u)=(u_i,u)_{l(V_0)}^2 \cQ(v_i,v_i).
