    \end{equation}  
so that we define \begin{equation}C_{\Delta,M,\beta}:=\left(\frac{e^{-\beta\Delta-M}+e^{\beta\Delta+M}}{e^{-\beta\Delta-M}}\right)^2.\end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T13:01:22.634662+00:00","domain":"probability theory","id":"claim_685131d5d9d729f05c5c64c7cc64fb8d07a9f2e8b580b37a0fda67f17bb97161","kind":"concept","schema_version":1,"statement":"[Proposition prop:pathwise-unique of arXiv:2607.00800, 'Brownian motion in Minkowski normed spaces'] Let $d\geq 2$, $z\in \mathbb{R}^d$ and $s>0$. 
Probabilistically weak solutions to 
\begin{equation}
    \mathrm d X_t = \frac 1 2 \divv \Bigl(D^2 Q^*\bigl(\nabla Q(z-X_t)\bigr)\Bigr) \,\mathrm d t + \sqrt{D^2Q^*\bigl(\nabla Q(z-X_t)\bigr)} \,\mathrm d W_t
\end{equation}
$($that is, to the first equation in (equation eq:f-DDSDE of the paper)$)$ with initial datum $\mathcal{L}(X_0) = f^z_Q(s,x)\,\mathrm d x$ are \emph{pathwise unique}, i.e., $X_t = \widetilde{X}_t$ for all $t\geq 0$ a.s.\ for any two probabilistically weak solutions $X$ and $\widetilde{X}$ to (equation SDE-linear of the paper) with initial datum $f^z_Q(s,x) \,\mathrm d x$ on the same stochastic basis with the same standard Brownian motion $W$ such that $X_0 = \widetilde{X}_0$ a.s. (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-26T19:39:41.442058+00:00","domain":"probability theory","id":"claim_685268e70b76a1be39ac9ea9e7959cbadfd1ba5ba4edc75b8588df06f2bc859d","kind":"concept","schema_version":1,"statement":"[Corollary 10 of arXiv:2604.07478, 'Mixing Times and Cutoff for the Rook's Walk'] Let $t_\text{mix}$ and $\hat{t}_{\text{mix}}$ be the mixing times of the standard Rook's walk and the RWBD resp. (each with parameters $n,d$). Then:
     \[\forall \epsilon \in (0,1), \quad t_\text{mix}(\epsilon) = \hat{t}_{\text{mix}}(\epsilon)\]
\begin{proof}
   Consider the variation distance of the RWBD chain (denoted $d_*(t)$),
   \begin{align*}
   d_*(t) &=  \max_{x\in \Omega_*}\Vert P^t_*(x,\cdot) - \pi_*  \Vert_\text{TV}\\
    &= \Vert P^t_*(0,\cdot) - \pi_*\Vert_\text{TV} \tag{Lemma \ref{dd}}\\
    &= \Vert P^t(\hat{1},\cdot) - \pi\Vert_\text{TV}\tag{Lemma \ref{d}}\\&=d(t)\tag{ Lemma \ref{transitivity}}
   \end{align*}
Thus, the distance from stationary at time $t$ of the two chains is equal and the equality of mixing times follows trivially.
\end{proof} (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T15:12:20.549447+00:00","domain":"probability theory","id":"claim_685353305b1c548d3b2160d6e563d8b82fc467f68a61352d3d1b88c9a0ced6d8","kind":"concept","schema_version":1,"statement":"[Proposition prop:gf-existence-bub of arXiv:2603.28161, 'Boundary four-point connectivities of conformal loop ensembles'] For $x_1,...,x_n\in\mathbbm{R}$, the limit
\[
\widehat{G}^\mathrm{Bub}_0(x_1,...,x_n)=\lim_{r_i\to0}\prod_{i=1}^nr_i^{-h}\cdot \mu^\mathrm{Bub}_0[\gamma\cap B(x_i,r_i)\neq\emptyset,1\le i\le n]
\]
exists and is continuous of $x_1,...,x_n$. Furthermore, for any disjoint $S_1,..,S_n\subset\mathbbm{R}$,
    \begin{equation}
        \int_{S_1\times...\times S_n}\widehat{G}^\mathrm{Bub}_0(x_1,...,x_n)\prod_{i=1}^ndx_i=C^n\mu^\mathrm{Bub}_0\left[\prod_{i=1}^n\nu_{\gamma\cap\mathbbm{R}}(S_i)\right].
    \end{equation}
Hence, $\widehat{G}^\mathrm{Bub}_0(x_1,...,x_n)=C^n G^\mathrm{Bub}_0(x_1,...,x_n)$ where $G^\mathrm{Bub}_0(x_1,...,x_n)$ is defined in~(equation eq:def-gf-bub of the paper) and $C$ is the same constant as in Proposition~(prop:equivalence of the paper). (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T06:29:21.947654+00:00","domain":"probability theory","id":"claim_68538939815a12893fabab3585d7b5fb0a141a9c981cc2e26490884d82f4346a","kind":"concept","schema_version":1,"statement":"[Lem 21 of arXiv:2608.01860, 'A Variational Characterization of a Gibbs Measure related to the Aviles-Giga Functional'] Let $\delta>0$. We have for any $s\in\R$ and $p,q_1,q_2\in[1,\infty]$, $q_1<q_2$
    \begin{align}
        \Vert f\Vert_{B_{p,q_2}^s}\lesssim \Vert f\Vert_{B_{p,q_1}^s}\lesssim \Vert f\Vert_{B_{p,\infty}^{s+\delta}}\quad \forall f\in\mathcal{S}'(\mathbb{T}^d).
    \end{align}
    If we denote the fractional Sobolev spaces by $W^{s,p}$ then for any $q\in[1,\infty]$
    \begin{align}
        \Vert f\Vert_{B_{p,q}^s}\lesssim \Vert f\Vert_{W^{s+\delta,p}}\lesssim \Vert f\Vert_{B_{p,\infty}^{s+2\delta}}\quad \forall f\in\mathcal{S}'(\mathbb{T}^d),
    \end{align}
    and
    \begin{align}
        \Vert f\Vert_{W^{s,p}}\lesssim\Vert f\Vert_{B_{p,q}^{s+\delta}}\quad \forall f\in\mathcal{S}'(\mathbb{T}^d).
    \end{align}
    For all $\alpha\in\N_0^d$ and for all $s,t\in\R$, $p_1,p_2,q_1,q_2\in [1,\infty]$, with
    \begin{align*}
        p_2\geq p_1,\quad q_2\geq q_1,\quad t\leq s-d(\frac{1}{p_1}-\frac{1}{p_2})
    \end{align*}
    one has
    \begin{align}
        \Vert \partial^\alpha f\Vert_{B^{t-|\alpha|}_{p_2,q_2}}\lesssim\Vert f\Vert_{B^s_{p_1,q_1}} \quad \forall f\in\mathcal{S}'(\mathbb{T}^d).
    \end{align} (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-26T19:25:40.048962+00:00","domain":"probability theory","id":"claim_685437838a6fb06c031a3fc9228f116565de60b3ad72cdbcd7e8f57723698145","kind":"theorem","schema_version":1,"statement":"[Cor 4 of arXiv:2510.26207, 'A combinatorial perspective on the Kemeny constant and more'] For each fixed $t\geq 0$, the power series $\l(\bK_u^{\geq t}(x), u \in V\r)$ are all equal inside $\bar{B}(0,R_t)$, and their common value is 
  \begin{align}
