{"assumptions":[],"created_at":"2026-10-27T07:06:18.027480+00:00","domain":"probability theory","id":"claim_68bd52016a0fdf877d7daf030ce73c5f3e4e193f4c7a80c9b5bb5163aa91697d","kind":"lemma","schema_version":1,"statement":"[Lemma 13 of arXiv:2608.15616, '\textbf{Compact Support Property of Super-Brownian Motion with Irregular Drift}'] Let $r >0$, $m >0$, and 
		\begin{equation}
			\psi^{m,r}(x) =
			\begin{cases}
				0, & |x| \leq r, \\
				m(|x|/r - 1), & r \leq |x| \leq 2r, \\
				m, & 2r \leq |x|.
			\end{cases}
		\end{equation}
		Then there exists a unique mild solution $V(0,\psi^{m,r})=V^{m,r}$ to 
		\begin{equation}
			\begin{cases}
				&\partial_t V^{m,r}_t(x) = \frac{1}{2}\Delta V^{m,r}_t(x) - \frac{1}{2}(V^{m,r}_t(x))^2 + \psi^{m,r}(x), \quad t >0, x\in \R,\\
				&V_0^{m,r}\equiv 0\\
				& V_t^{m,r}(x) \geq 0,  \quad t >0, x\in \R.
			\end{cases}
		\end{equation}
		Furthermore, for $(t,x) \in \R_+\times \R$, the sequence $(V_t^{m,r}(x))_{m> 0}$ is monotonically increasing in $m$.  We get the bounds
		\begin{equation}
			\lim_{m \rightarrow \infty}V_t^{m,r}(x) \leq \constFromEq{c}{eq:est_v_infty_1} (r-|x|)^{-2}, \quad t > 0,  -r<x<r,
		\end{equation}
		and
		\begin{equation}
			\lim_{m \rightarrow \infty}V_t^{m,r}(x) \leq \constFromEq{c}{eq:ext_v_infty_2} (r-|x|) t^{-\frac{3}{2}} \exp\Big(-\frac{(r-|x|)^2}{2t}\Big), \quad t>0, r-|x|>2\sqrt{t},
		\end{equation} 
		for some constants $\constFromEq{c}{eq:est_v_infty_1}, \constFromEq{c}{eq:ext_v_infty_2}>0$.","status":"unverified"}

