{"assumptions":[],"created_at":"2026-10-27T05:44:27.926020+00:00","domain":"probability theory","id":"claim_695be83bd308b027d5a80e6b1e8637a818c88a376801f055964eec250f98110c","kind":"lemma","schema_version":1,"statement":"[Lemma 9 of arXiv:2607.12667, 'Phase Transition of Eigenvalues of Covariances from the Spiked Mixture Model in High-dimen'] Let $\X \in \mathbb{R}^{d\times n}$ have \ac{iid} Gaussian entries $\sim \mathcal{N}(0,1)$. Partition the columns as $\X = \begin{bmatrix}
    \X_1 & \X_2 & \ldots & \X_K
\end{bmatrix}$, with $\X_i \in \mathbb{R}^{d\times n_i}$, $(n_1,\ldots, n_K) \sim \text{Mult}(n,\pi_1, \ldots, \pi_K)$, an independent random vector sampled from the multinomial distribution. For $i,j \in [K]$, set:
\begin{align*}
    \Sb_n &:= \frac{\X\X^\mathsf{T}}{n}, &&\R_n(z):= (z\I- \Sb_n)^{-1}, \text{and }&&\Bb_n(z) := \frac{\X_i\X_i^\mathsf{T}}{n_i} \R_n(z)\frac{\X_j\X_j^\mathsf{T}}{n_j},
\end{align*}
where $z \in \mathbb{C}\setminus \{\lambda_1(\Sb_n), \ldots, \lambda_d(\Sb_n)\}$.

Assume $d,n \to \infty$ with $d/n \to \gamma \in (0, \infty)$. Then, 
\begin{align*}
    \frac{1}{d}\Tr(\Bb_n(z)) \xrightarrow[]{\text{a.s.}} T(z) \left(\frac{\gamma}{\pi_i} \ind_{i=j} + \frac{1}{1-\gamma G(z)}\right),
\end{align*}
where $T(z) = \int_t \frac{t}{z-t} d\mu_{\text{MP}(\gamma)}(t)$, $G(z) = \int_t \frac{1}{z-t} \mu_{\text{MP}(\gamma)}(t)$ are respectively the $T$- and the Cauchy transform of the \acl{MP} law of parameter $\gamma$.
Moreover, this convergence is uniform on $\mathcal{K}(\eta) = \{z\in \mathbb{C},\: d(z,[a,b])> \eta\}$ for all $\eta>0$.","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-26T19:33:46.776422+00:00","domain":"probability theory","id":"claim_695d13a49a66ba2a722fb4f7f3af88e33c20f335b125bbb3357165f7697b1fd3","kind":"theorem","schema_version":1,"statement":"[Theorem 6 (Necessary Maximum Principle) of arXiv:2603.25452, 'New approach to optimal control of delayed stochastic Volterra integral equations'] Assume $({\bf A4)}$-$({\bf A6})$ hold. Let $\hat{u} \in \mathcal{A}_{\mathcal{G}}$, and denote by $\hat{X}(t)$  the corresponding state process solving \eqref{ee1}. Let $(\hat{p}(t), \hat{q}(\cdot,t))$ be the adjoint processes associated with $\hat{u}$, solution of \eqref{p}. Then, the following statements are equivalent.
\begin{itemize}
\item[(i)] For every bounded $\beta\in \mathcal{A}_{\mathcal{G}}$, we have
\begin{eqnarray*}
\lim_{s \to 0}\frac{J(x_{0},\hat{u}+s\beta)-J(x_{0},\hat{u})}{ds} =\frac{dJ}{ds}(x_0,\hat{u}+s\beta)|_{s=0}= 0
\end{eqnarray*}
\item[(ii)] For all $t \in [0,T]$, we have
