{"assumptions":[],"created_at":"2026-10-26T19:28:04.863874+00:00","domain":"probability theory","id":"claim_6a2454de6589474d23abd4a9c32824ebf05c46ab86ac389ddb190f8979ad7c18","kind":"concept","schema_version":1,"statement":"[Prop 30 of arXiv:2511.22156, ''] (1).  $\|U_{\lambda}^{(n)}f\|_{\infty}\leq \lambda^{-1}\|f\|_{\infty}$, for $f$ is bounded measurable.\\
(2).  For $f\in C_0(\tilde{F}_n)$, $\lambda U_{\lambda}^{(n)}f\rightarrow f$ in $C_0(\tilde{F}_n)$ as $\lambda\rightarrow \infty$.\\
(3).  $U_{\lambda}^{(n)}$ satisfies the resolvent equation:
\[
U_{\lambda}^{(n)}-U_{\lambda^{\prime}}^{(n)}=(\lambda-\lambda^{\prime})U_{\lambda}^{(n)}U_{\lambda^{\prime}}^{(n)}
\]
(4).  There exists $\alpha>0$ and $c(\lambda)$ independent of $n$ such that for $x,y\in \tilde{F}_n$ with $|x-y|\leq 1$, 
\begin{equation}
    |U_{\lambda}^{(n)}f(x)-U_{\lambda}^{(n)}f(y)|\leq c(\lambda)|x-y|^{\alpha}\|f\|_{\infty}.
\end{equation}

\begin{proof}
Of these (1)-(3) are standard properties of resolvents. Let $B=B(x,r)$ and $\tau=\tau_B$. Notice that
\begin{equation}
\begin{aligned}
U_{\lambda}^{(n)}f(x)&=E^x[\int_0^{\tau}e^{-\lambda t}f(X_t^{(n)})dt]+E^x[\int_\tau^{\infty}e^{-\lambda t}f(X_t^{(n)})dt]\\
&=E^x[\int_0^{\tau}e^{-\lambda t}f(X_t^{(n)})dt]+E^x[U_{\lambda}^{(n)}f(X_{\tau}^{(n)})].
\end{aligned}
\end{equation}
By scaling and \eqref{e:6.7}, 
\begin{equation}
\begin{aligned}
&E^x[\int_0^{\tau}e^{-\lambda t}f(X_t^{(n)})dt]\leq Cr^{\beta}\|f\|_{\infty}, \hbox{ if } 3^n r>1,\\
&E^x[\int_0^{\tau}e^{-\lambda t}f(X_t^{(n)})dt]\leq Cr^{2}\|f\|_{\infty}, \hbox{ if } 3^n r\leq1.
\end{aligned}
\end{equation} 
Since $E^x[U_{\lambda}^{(n)}f(X_{\tau}^{(n)})]$ is harmonic in $B$, it follows from Lemma \eqref{e:6.7} 
\begin{equation}
|E^x[U_{\lambda}^{(n)}f(X_{\tau}^{(n)})]-E^y[U_{\lambda}^{(n)}f(X_{\tau}^{(n)})]|\leq Cr^{-\alpha_1}|x-y|^{\alpha_1} \|f\|_{\infty}.
\end{equation}
for $y\in B(x,\frac{r}{2})$, Combining \eqref{6:18}, \eqref{e:6.19}, \eqref{6:20} imply 
\begin{equation*}
\begin{aligned}
&|U_{\lambda}^{(n)}f(x)-U_{\lambda}^{(n)}f(y)|\leq C(1+\lambda^{-1})\|f\|_{\infty}(r^{\beta}+r^{-\alpha_1}|x-y|^{\alpha_1}) .\qquad \hbox{if }|x-y|<\frac{r}{2},\ 3^nr>1,\\
&|U_{\lambda}^{(n)}f(x)-U_{\lambda}^{(n)}f(y)|\leq C(1+\lambda^{-1})\|f\|_{\infty}(r^{2}+r^{-\alpha_1}|x-y|^{\alpha_1}) .\qquad \hbox{if }|x-y|<\frac{r}{2},\ 3^nr\leq1.
\end{aligned}
\end{equation*}
Now take $x,y\in \tilde{F}_n,\ |x-y|\leq1$. If $|x-y|\leq (\frac{1}{2})^{\frac{\beta+\alpha_1}{\beta}}\wedge(\frac{1}{2})^{\frac{2+\alpha_1}{2}}$, set $r=|x-y|^{\frac{\alpha_1}{\alpha_1+\beta}}$. Thus $|x-y|\leq \frac{r}{2}$, then 
\begin{equation}
  |U_{\lambda}^{(n)}f(x)-U_{\lambda}^{(n)}f(y)|\leq  C(1+\lambda^{-1})|x-y|^{\alpha}\|f\|_{\infty}\\
\end{equation}
for $\alpha=\min\{\frac{\alpha_1\beta}{\alpha_1+\beta},\frac{2\alpha_1}{\alpha_1+2}\}$. If $|x-y|> (\frac{1}{2})^{\frac{\beta+\alpha_1}{\beta}}\wedge(\frac{1}{2})^{\frac{2+\alpha_1}{2}}$, then we adjust the constant $C$ in \eqref{e:6.21}.
\end{proof} (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-26T20:43:04.690084+00:00","domain":"probability theory","id":"claim_6a25ceb88bea40a08611f728a8e903052a20647cf656472da8c393486434ea08","kind":"definition","schema_version":1,"statement":"[Definition 10 of arXiv:2605.17328, 'Transportation cost inequalities for mean reflection SPDEs with white noise'] {\rm (\cite[Definition 3.1]{DuanJTP2025}) A pair $(\bar{z},K)$ is called a solution to Eq.\,\eqref{deterministicparabolicobstacleEq} if it satisfies the following conditions}
\begin{itemize}
\item[(i)] {\rm $\bar{z}$ is continuous function on $[0,T]\times[0,1]$ satisfying $\bar{z}(t,x)\geq-v(t,x)$, $\bar{z}(t,0)=\bar{z}(t,1)=0  \text{ and } \bar{z}(0,x)=0$.}
\item[(ii)] {\rm $K$ \text{is a measure on} $(0,1)\times\mathbb R_+$ \text{such that}  $K\left((\e,1-\e)\times[0,T]\right)<\infty$ for every small $\e>0$ and $T>0$.}
\item[(iii)] {\rm $\bar{z}$ weakly solves the partial differential equation}
{\rm \begin{align}
\frac{\partial \bar{z}}{\partial t}=\frac{\partial^2 \bar{z}}{\partial x^2}+\dot{K}.
\end{align}
\text{That is, for every} $t\in [0,T]$ and every $\varphi\in  C_0^2 ([0,1])$,
$$
\int_0^1 \bar{z}(t,x)\varphi(x)\mathrm{d}x=\int_0^t \int_0^1 \bar{z}(s,x)\varphi''(x)\mathrm{d}s\mathrm{d}x+\int_0^t \int_0^1 \varphi(x)K(\mathrm{d}s,\mathrm{d}x).
$$}
\item[(iv)] {\rm
$$
\int_0^t \int_0^1 \left(\bar{z}(s,x)+v(s,x)\right)K(\mathrm{d}s,\mathrm{d}x)=0
$$}
\end{itemize}","status":"unverified"}

