\[ r(g)(x) \leq \pi\left(1 -\gamma + \omega(g) - x\right),\]
with equality for all $x \geq U(g)$, that is, $r(g)$ is a line with slope $-1$ on $[U(g), U(r(g))]$.
\item[(ii)] For $\bm{x} \in \mathbb{R}^{K+1}$ non-increasing, let $L' := L(f_{\bm{x}})\vee x_{K-1}$ when $K\in \mathbb{N}$ and $L' = L(f_{\bm{x}})$ when $K = \infty$. Then $\omega(f_{\bm{x}}) = U(f_{\bm{x}}) = x_0$ and \begin{equation} 
r(f_{\bm{x}})(x) = \begin{cases}
