\end{equation}
\end{itemize}","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T14:49:05.397026+00:00","domain":"probability theory","id":"claim_6a773a8d704df11f2ced57e71f51e42f3e26bf43e8ee5b1b5af8c7f935c93f4c","kind":"concept","schema_version":1,"statement":"[Lemma of arXiv:2601.07808, 'Supercritical long-range percolation on graphs of polynomial growth: the truncated one-arm'] \label[lemma]{prop:cluster_size_connectivity}
