    \{w\ge w^*(s)\}. 
\end{equation*}
In particular, if $|\{w=w^*(s)\}|=0$, then one can choose
\begin{equation*}
    \int_0^s w^*(r)\, dr= \int_{\{w>w^*(s)\}} w (x)\,d x, 
\end{equation*}","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-26T19:31:20.858950+00:00","domain":"probability theory","id":"claim_6a8faaad90ca2d26d2917281a06c5ab3fbfb81dcae97bebde9b5cc2fde00dae8","kind":"concept","schema_version":1,"statement":"[Theorem 1 of arXiv:2506.10724, 'Detecting transitions from steady states to chaos with gamma distribution'] Let $X_t$ be a random variable representing the population at time $t$. Let $y_t=E[X_t]$. Assume that the steady state of stochastic discrete model \eqref{eq:logistic3}, $X_t$, follows the gamma distribution \eqref{eq:x_gamma_distribution}.  Then stochastic logistic equation \eqref{eq:logistic3} implies that 
