{"assumptions":[],"created_at":"2026-10-27T13:52:23.601133+00:00","domain":"probability theory","id":"claim_6a9ea6cf1bac83216619e380732f089f8ab8e92e4874929424fddf1251fc6788","kind":"concept","schema_version":1,"statement":"[Theorem Thm3.2 of arXiv:2602.23124, '\textsc{ Necessary and Sufficient Conditions for the Lacunary/Hereditary Laws of Large Num'] {\bf Sufficiency/Necessity in the  Lacunary/Hereditary   WLLN  for    General Sequences:}
   Consider a sequence of measurable functions $\,f_1, f_2, \cdots$ on a   probability space $\,(\Omega, \mathcal F, {\mathbb P})$, and recall the tail $\sigma-$algebra of (equation A6a of the paper). Then the following conditions are equivalent: 

     \smallskip
     \noindent 
     {\bf (i)} {\rm Lacunary-Hereditary WLLN:} There exist real-valued,  $\,{\cal T}-$measurable ``correctors" $D_1, D_2, \cdots\,$ with $\,{\mathbb P} \big( \big| D_N \big| \le N,\, \forall \, N \in \mathbb N \big)=1$ and a subsequence $\,f_{k_1}, f_{k_2}, \cdots\,  $       along which,   and   along whose every  subsequence,  
     \begin{equation} 

 \lim_{N \to \infty} \bigg(  \frac{1}{\,N\,} \sum_{n=1}^N f_{k_n}   - D_N \bigg) =\,0 \quad \text{holds in} ~{\mathbb P}\text{\,--\,probability.}    
\end{equation}
 {\bf (i)$^\prime$} {\rm Lacunary-Hereditary Conditional WLLN:} There exist real-valued $\,{\cal T}-$measurable ``correctors" $\,D_1, D_2, \cdots$ with $\,{\mathbb P} \big( \big| D_N \big| \le N,\, \forall \, N \in \mathbb N \big)=1\,$ and a subsequence $\,f_{k_1}, f_{k_2}, \cdots\, $     along which, and along whose every subsequence,   we have  for every $\, \varepsilon >0 \,$ the convergence           \begin{equation} 

 \lim_{N \to \infty} {\mathbb P}  \bigg(  \bigg|  \frac{1}{\,N\,} \sum_{n=1}^N f_{k_n}   - D_N \bigg| > \varepsilon  \, \bigg| \,{\cal T} \bigg) =\,0 \quad \text{in} ~~{\mathbb P}\text{\,--\,probability.}    
\end{equation}
     {\bf (ii)} The sequence $\, f_1, f_2, \cdots\,$ contains a {\rm determining} subsequence $\, f_{k_1}, f_{k_2}, \cdots\,$   whose limit random probability distribution  ${\bm \mu} \,,$      as in and below (equation B0 of the paper),   satisfies  in ${\mathbb P}-$probability 
       \begin{equation} 

\lim_{N \to \infty}  \Big( N \, {\bm \mu}  \big(\mathbb R \setminus [-N,N]  \big) \Big) = \,0\,,\qquad \lim_{N \to \infty}  \frac{1}{\,N\,} \int_{[-N,N]} x^2  \,  {\bm \mu}  (\mathrm{d}   x, \cdot \,) \,=\,0\,.
\end{equation} 
Each  corrector    $\,D_N \,$  in {\bf (i)},\,{\bf (i)}$^\prime$  can be taken     as the weak$\,-\,\mathbb{L}^2\,$ limit of      $ \, \big( \, \mathbb E \big(  f_{k_{n}} \, \mathbf{1}_{\{ | f_{k_{n}} | \le N \}} \,\big|\, {\cal T} \,\big) \big)_{n \in \mathbb N}\,;$  and $\,  \lim_{N \to \infty} \big( D_N  /  \sqrt{N\,} \, \big) =0\,$ holds in ${\mathbb P}-$probability. (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-28T01:54:57.452471+00:00","domain":"probability theory","id":"claim_6aa07eedd95d92b295c935c913fa619cd8af5a7ca507a0d59eb940ff09990723","kind":"concept","schema_version":1,"statement":"[Lemma lem : Intro/sketch/UB_LB of arXiv:2412.03320, 'Large deviation principle at speed $n$ for the random metric in first-passage percolation'] Let $(\mathbb{X}, \mathrm{d}_\mathbb{X})$ be a metric space and $(X_n)_{n\ge 1}$ a random process with values in $\mathbb{X}$. Define, for all $x\in \mathbb{X}$,
    \begin{align*}
        \overline{I}(x)&\coloneqq\lim_{\varepsilon \to 0}\!\!\uparrow\! \limsup_{n\to\infty} -\frac{1}{n}\log \Pb{\mathrm{d}_\mathbb{X}(x, X_n)\le \varepsilon }
        \intertext{and}\underline{I}(x)&\coloneqq\lim_{\varepsilon \to 0}\!\!\uparrow\! \liminf_{n\to\infty} -\frac{1}{n}\log \Pb{\mathrm{d}_\mathbb{X}(x, X_n)\le \varepsilon }.
    \end{align*}
    Then
    \begin{enumerate}[(i)]
        \item 
        $\overline I$ and $\underline I$ are rate functions on $\mathbb{X}$.
        \item For every open set $U\subseteq \mathbb{X}$,
            \begin{equation}

                \limsup_{n\to\infty}-\frac{1}{n}\log\Pb{X_n \in U} \le \inf_{x\in U} \overline{I}(x).
            \end{equation}
        \item  For every compact set $K\subseteq \mathbb{X}$,
            \begin{equation}

                \liminf_{n\to\infty}-\frac{1}{n}\log\Pb{X_n \in K} \ge \min_{x\in K} \underline{I}(x).
            \end{equation}
    \end{enumerate} (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-26T20:28:53.745616+00:00","domain":"probability theory","id":"claim_6aa2534bc5f9e9a059470bdd5db5b66f65997215dcf575494f2b1a56bb750fd5","kind":"theorem","schema_version":1,"statement":"[Proposition 17 of arXiv:2605.13727, 'Stochastic evolution equations\\ driven by arbitrary cylindrical Lévy processes'] Let $H,U$ and $V$ be separable Hilbert spaces, and $(Y_n)_{n \in \mathbb{N}}$ be a sequence of $H$-valued processes of the form
    \[Y_n(t)={S_n(t)}\left(\int_{(0,t]} \drift_n(s)\,{\rm d}s+\int_{(0,t]} \diff_n(s)\,{\rm d}L(s)\right)+C_n(t)
    \qquad\text{for all }t\ge 0, \]
where, for some constants $K_1,K_2>0$,  the following conditions hold: 
\begin{enumerate}
    {\item [{\rm (1)}] the sequence $(S_n)_{n\in \mathbb{N}}$ consists of $\mathcal{L}(V,H)$-valued, strongly continuous, deterministic functions satisfying $\sup_{n \in \mathbb{N}}\sup_{t\geq 0}\norm{S_n(t)}_{V\rightarrow H}\leq 1$;}
    \item [{\rm (2)}] the sequence $(\drift_n)_{n \in \mathbb{N}}$ consists of {$V$-valued}, $P$-a.s.\ Bochner integrable, predictable processes satisfying, for all $n \in \mathbb{N}$ and $t\geq 0$,  that $\drift_n^*(t)\leq K_1 Y_n^*(t-)$;
    \item [{\rm (3)}] the sequence $(\diff_n)_{n \in \mathbb{N}}$ consists of  {$L_2(U,V)$-valued},  $L$-integrable, predictable processes satisfying, for all $n \in \mathbb{N}$ and $t\geq 0$,  that $\diff_n^*(t)\leq K_2 Y_n^*(t-)$;    \item  [{\rm (4)}] the sequence   $(C_n)_{n \in \mathbb{N}}$ consists of   $H$-valued, càdlàg, adapted processes converging to $0$ uniformly on compacts in probability.
\end{enumerate}
Then  $(Y_n)_{n \in \mathbb{N}}$ converges to $0$ uniformly on compacts in probability.","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T11:50:36.755051+00:00","domain":"probability theory","id":"claim_6aa3adbe85c1e295b3e75f57f6f841525b060619d0339008823feef84b519f80","kind":"lemma","schema_version":1,"statement":"[Lemma 29 of arXiv:2609.04153, '\vspace*{-3cm}Smooth autonomous fast dynamo action on the three-torus'] Let $T: \TT^2 \to \TT^2$ be a volume preserving diffeomorphism that is isotopic to the identity, and let $g \in C^\infty(\TT^2)$ be mean free. Then, for any $n \in \NN$ large enough, there exists $u^{(n)} \in C_\sigma^\infty(\TT^3)$ with $u^{(n)}_3>0$, so that 
