{"assumptions":[],"created_at":"2026-10-26T20:43:04.732312+00:00","domain":"probability theory","id":"claim_6acf84ea9302bf43665c533edcbd64f2b78add29ee79168a14911be8f0de0f1d","kind":"theorem","schema_version":1,"statement":"[Proposition 10 (First passage time for the reflected process at upper  level) of arXiv:2605.18136, 'L\'evy processes with partially stochastic resetting'] Let $a$, $b\in \mathbb  R$, $p \in (0,1)$, $q >0 $ and $\lambda \geq 0$. Then, it holds that 
		\begin{align*}
			\mathbb E_x(\ee ^{-q\tau^-_{b,U^a}})&={\mathcal{Z}_{b,a}^\p}r_a^{(q+\lambda )}(x)-
			\frac{{\mathcal{Z}_{b,a}^{\p\prime} }r_a^{(q+\lambda )}(a)}{{\mathcal{W}_{b,a}^{\p\prime}}r_a^{(q+\lambda )}(a)}{\mathcal{W}_{b,a}^\p}r_a^{(q+\lambda )}(x)+  \int_b^{a\wedge bp^{-1}} \overline{\V}^{(p)}_\lambda[r_a^{(q+\lambda)}](x,y)\dd y\mathbf 1_{\{a,b\in \mathbb R_+\}}\\
			&\quad + \ell_b^{(q)}(a)\int_{ap^{-1}\vee b}^{a}\overline{\V}^{(p)}_\lambda[r_a^{(q+\lambda)}](x,y)\dd y\mathbf 1_{\{a,b\in \mathbb R_-\}},
			\end{align*}
			where ${\mathcal{W}_{b,a}^{\p\prime} }r_a^{(q+\lambda )}(a)=\frac{\dd }{\dd x }{\mathcal{W}_{b,a}^{\p} }r_a^{(q+\lambda )}(x)|_{x=a}$, similarly for  ${\mathcal{Z}_{b,a}^{\p\prime} }r_a^{(q+\lambda )}(a)$  and 
			\begin{align*}
				\ell_b^{(q)}(a)
				=
			\Bigl[1-
			\displaystyle\int_{ap^{-1}\vee b}^{a}
			\overline{\mathcal V}^{(p)}_\lambda
			[r_a^{(q+\lambda)}](a,y)\,\mathrm{d}y\Bigr]^{-1}\Bigl[	{
					{\mathcal{Z}_{b,a}^{p}}r_a^{(q+\lambda)}(a)
					-
					\dfrac{
						{\mathcal{Z}_{b,a}^{p\prime}}r_a^{(q+\lambda)}(a)
					}{
						{\mathcal{W}_{b,a}^{p\prime}}r_a^{(q+\lambda)}(a)
					}
					{\mathcal{W}_{b,a}^{p}}r_a^{(q+\lambda)}(a)
				}\Bigr].
			\end{align*}","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T11:07:35.028887+00:00","domain":"probability theory","id":"claim_6ad20a339275f96f7689a3b78d6c858be4453fcb4d2ff31c825b593954f10348","kind":"theorem","schema_version":1,"statement":"[Pro 12 of arXiv:2609.02879, 'On the cut locus of Hamilton--Jacobi equations I: structure and propagation via the touchi'] Let \( \Omega \subset \R^n \) be an open convex subset and $\phi\in\text{\rm SCL}\,(\Omega)$. Then
	\begin{align*}
		\reg(\phi)=\big\{x\in\Omega:\partial_P \phi(x)\neq\varnothing\big\},\qquad \cut(\phi)=\big\{x\in\Omega:\partial_P \phi(x)=\varnothing\big\}.
	\end{align*}
	Moreover, for any $x\in\reg(\phi)$, $\phi$ is differentiable at $x$ and $\partial_P \phi(x)=\{D\phi(x)\}$.","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T20:38:36.830997+00:00","domain":"probability theory","id":"claim_6ad26c4aa241f9b0cd88f9476134d38e177cbb40d2fe13648a12bd11ef998c29","kind":"lemma","schema_version":1,"statement":"[Lem 112074 of arXiv:2606.29143, 'Comonotonic and moment matching approximations for sums of lognormal random variables'] Let $X$ be a random variable, not necessarily continuous, and $\omega$ a nonnegative weight function such that $0 < E[\omega(X)] < \infty$. Define the function 
\begin{equation} 
G_{X, \omega}(t) = \frac{1}{E[\omega(X)]}\int^t_0 \omega(F^{-1}_X(u))du, \,\, t \in [0, 1]
\end{equation}
where $F_X^{-1}(u)$ is the inverse distribution function of $X$. Then we have that 
\begin{itemize} 
\item $G_{X, \omega}(0) = 0$ and $G_{X, \omega}(1) = 1$, 
\item $G_{X, \omega}(t)$ is increasing in $t$, 
\item $G_{X, \omega}(t)$ is continuous in $t$. 
\end{itemize}
In other words, $G_{X, \omega}(t)$ is a continuous distortion function on the unit interval $[0, 1]$.","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-28T00:22:21.907553+00:00","domain":"probability theory","id":"claim_6ad9efbb0a9240fcd0fabdf7e8e3f566ba4c992f28654867e2c0a97e474d7ebd","kind":"concept","schema_version":1,"statement":"[Lemma lm:bulinsk of arXiv:2411.11429, 'Functional Central Limit Theorem for topological functionals of Gaussian critical points'] [Bulinskaya]

