        \item For any $z,w\in D$,
        \begin{align*}
            \langle\field{\overline{\mathrm{cos}}(\alpha\phi(z))}\field{\overline{\mathrm{cos}}(\alpha\phi(w))}\rangle\leq\langle:\! \sin(\alpha\phi(z)) \!: :\! \sin(\alpha\phi(w)) \!: \rangle.
