{"assumptions":[],"created_at":"2026-10-26T19:32:15.339140+00:00","domain":"probability theory","id":"claim_6c029b355bd1a7f359305056c17dfda6019d1c397dc69f49076f67971c16655d","kind":"concept","schema_version":1,"statement":"[Theorem 12 of arXiv:2506.15044, '2506.15044'] Let $X,Y\in \mathcal{R}^\mathbb{B}$, and $Z\in\mathcal{R}$.
\begin{itemize}
  \item [$(1)$] If $(T_n,X^{(n)})$ is an FCS for $X\in \mathcal{R}^\mathbb{B}$, then $(T_n,\Delta X^{(n)})$ is a CS for $\Delta X$. Furthermore, if $X\in \mathcal{R}^\mathbb{C}$ and $(\tau_n)$ is an FS for $\mathbb{C}$, then $(\tau_n,\Delta X^{\tau_n})$ is a CS for $\Delta X$.

  \item [$(2)$] For all $a\in \mathbf{R}$,
\begin{align}
\Delta(aX)=a \Delta X, \quad \Delta(X+Y)= \Delta X+\Delta Y.
\end{align}

  \item [$(3)$] If $\widetilde{\mathbb{B}}$ is another stochastic set of interval type satisfying $\widetilde{\mathbb{B}}\subseteq \mathbb{B}$, then
  \begin{equation}
  \Delta (X\mathfrak{I}_{\widetilde{\mathbb{B}}})=(\Delta X)\mathfrak{I}_{\widetilde{\mathbb{B}}}.
  \end{equation}
  Specially, $\Delta (Z\mathfrak{I}_{\mathbb{B}})=(\Delta Z)\mathfrak{I}_{\mathbb{B}}$.

  \item [$(4)$] If $T$ is a $\mathbb{B}$-inner stopping time, then
  \begin{align}
\Delta X^T=\Delta XI_{\llbracket{0,T}\rrbracket},\quad \Delta X^{T-}=\Delta XI_{\llbracket{0,T}\llbracket},
\end{align}
  where $X^{T-}$ is defined by
 \begin{equation*}
     X^{T-}=XI_{\llbracket{0,T}\llbracket}+X_{T-}I_{\llbracket{T,{+\infty}}\llbracket}.
  \end{equation*}
  Specially, $\Delta Z^S=\Delta ZI_{\llbracket{0,S}\rrbracket}$ and $\Delta Z^{S-}=\Delta ZI_{\llbracket{0,S}\llbracket}$, where $S$ is a stopping time.

  \item [$(5)$] $\Delta X=0\mathfrak{I}_\mathbb{B}$ if and only if $X\in \mathcal{C}^\mathbb{B}$.
  \item [$(6)$] Assume further that $X,Y\in \mathcal{S}^\mathbb{B}$. Then $\Delta X\Delta Y$ is a $\mathbb{B}$-thin process satisfying $\Sigma (\Delta X\Delta Y)\in \mathcal{V}^\mathbb{B}$. Furthermore, if $(T_n,X^{(n)})$ and $(T_n,Y^{(n)})$ are FCSs for $X\in \mathcal{S}^\mathbb{B}$ and $Y\in \mathcal{S}^\mathbb{B}$ respectively, then $(T_n,\Delta X^{(n)}\Delta Y^{(n)})$ is an FCS for $\Delta X\Delta Y$ (a $\mathbb{B}$-thin process), and $(T_n,\Sigma(\Delta X^{(n)}\Delta Y^{(n)}))$ is an FCS for $\Sigma (\Delta X\Delta Y)\in \mathcal{V}^\mathbb{B}$.
\end{itemize} (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T12:27:11.332709+00:00","domain":"probability theory","id":"claim_6c035b7fd53eda0bf49d0137a036b972e1b63793a0bab22fc3097537dbc78235","kind":"concept","schema_version":1,"statement":"[Proposition p:mixing condition uniformity of arXiv:2605.22803, 'Persistence of asymptotic variance under transport:\\ from hyperfluctuation to stealthy hy'] Let $p\in(-d,\infty)$. Suppose that $\Phi$ is a locally square-integrable invariant random complex measure, and that $\hat\beta_\Phi$ admits a density $S_\Phi$ (close to $0$) satisfying
    \begin{equation}
        S_\Phi(k) = a \|k\|^p + o(\|k\|^p)
    \end{equation}
    as $k\to0$ for some $a\geq0$.
    Then $\Phi$ is $p$-uniform. Furthermore, $\Phi$ is beyond $p$-uniform iff $a=0$. If one supposes that, for some $\vartheta>0$, $f\in L^1$ is Fourier-smooth with exponent $p+\vartheta$ and $x\mapsto x_jf(x)$ is Fourier-smooth with exponent $p+2+\vartheta$ for each $j\in\{1,...,d\}$, then
    \begin{equation}
        \frac{\BV[\Phi(f_r)]}{r^{d-p}} \xrightarrow{r\to\infty} \frac{a}{(2\pi)^d} \int|\hat{f}(k)|^2\|k\|^p\, dk.
    \end{equation}
    The limit terms can also be expressed without the Fourier transform as in~(equation e: laplace version of the paper) if $p\in2\N_0$.
    \begin{proof}
        Under the assumption that $\hat\beta_\Phi$ has the density $S_\Phi$ close to $0$, one obtains that
        \begin{equation}
            \frac{\hat\beta_\Phi(B_\varepsilon)}{\varepsilon^{d+p}} \xrightarrow{\varepsilon\to0} \frac{d\kappa_d}{d+p} a.
        \end{equation}
        Hence, $\Phi$ is $p$-uniform and beyond $p$-uniform iff $a=0$. To obtain~(equation e: limit var density of the paper), we can almost apply~(equation e: limit var formula of the paper) from Proposition~(p:asymptotic variance test function of the paper). What is missing is that we do not assume that $\Phi$ is isotropic here. However,~(equation e: sf asymptotics of the paper) yields that the component of $\hat\beta_\Phi$ which contributes to the limit is isotropic.
    \end{proof} (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-28T02:28:34.925265+00:00","domain":"probability theory","id":"claim_6c05074d06f5bdfda0c794c8977fe16335911d4a9a04705297dd7757a0fa40e0","kind":"lemma","schema_version":1,"statement":"[Lemma lemma_subharminic of arXiv:2412.05706, 'Quasi-multiplicativity and regularity for metric graph Gaussian free fields'] For any disjoint $A,D_1\subset \widetilde{\mathbb{Z}}^d$ and $D_2\subset \mathbb{Z}^d$ such that $\widetilde{B}_w(1)\cap (A\cup D_1)=\emptyset$ for all $w\in \partial D_2$, and for any $x\in D_2$, 
