{"assumptions":[],"created_at":"2026-10-27T20:50:48.843012+00:00","domain":"probability theory","id":"claim_6c9a00ffc7a92eedbff5efdbac8693e4d51159bc6075dfecb9563a41757c8e84","kind":"definition","schema_version":1,"statement":"[Definition def:SPDE.limit of arXiv:2607.07598, 'Universal Central Limit Theorem for non-exchangeable interacting diffusions'] Let $k \ge \lambda_d+2$ be an integer. On a filtered probability space $(\Omega, {\mathcal{F}}, {\mathbb{F}} = ({\mathcal{F}}_t)_{t \in [0, T]}, {\mathbb{P}})$, let $\zeta_0$ be an ${\mathcal{H}}^{-k}$-valued ${\mathcal{F}}_0$-measurable random variable. A pair $ (\eta,W)\in C([0,T];{\mathcal{H}}^{-k})\times C([0,T];{\mathcal{H}}^{-k-1})$ is called a solution of the fluctuation SPDE with initial condition $\zeta_0$ if
		\begin{enumerate}[(i)]
\item  $\eta\in L^2([0,T];{\mathcal{H}}^{-(k-1)}_w)$ ${\mathbb{P}}$-a.s. By Lemma (lem:sob of the paper)(equation embed.k1.k2 of the paper), this implies that $\eta\in L^2([0,T];{\mathcal{H}}^{-k}_w)$ ${\mathbb{P}}$-a.s. Therefore, the drift term  in (equation eq: SPDE.integral of the paper) is well-defined.
			\item  $W$ is a continuous ${\mathbb{F}}$-adapted ${\mathcal{H}}^{-k-1}$-valued centered Gaussian process with covariance given, for all $f_1,f_2 \in {\mathcal{H}}^{k+1}$, by
			\begin{align} 
				{\mathbb{E}}\big[	\langle W_s,f_1\rangle_{{\mathcal{H}}^{-k-1},{\mathcal{H}}^{k+1}}\,\langle W_t,f_2\rangle_{{\mathcal{H}}^{-k-1},{\mathcal{H}}^{k+1}}\big]
				=
				\sigma^2\int_0^{s\wedge t}\big\langle \mu_u,\,\nabla f_1\cdot\nabla f_2\big\rangle\,\mathrm{d} u.
			\end{align}
			\item  for every $f\in C_c^\infty({\mathbb{R}}^d)$ and every $t\in[0,T]$,
			\begin{align}  
				\langle \eta_t,f\rangle_{{\mathcal{H}}^{-k},{\mathcal{H}}^{k}}
				&=
				\langle \zeta_0,f\rangle_{{\mathcal{H}}^{-k},{\mathcal{H}}^{k}}
				+
				\int_0^t \big\langle \eta_s, {\mathcal{L}}_{s,\mu_s} f\big\rangle_{{\mathcal{H}}^{-k}_w,{\mathcal{H}}^{k}_w}\,\mathrm{d} s
				+
				\langle W_t,f\rangle_{{\mathcal{H}}^{-k-1},{\mathcal{H}}^{k+1}}.
			\end{align}
		\end{enumerate}","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T08:26:47.157209+00:00","domain":"probability theory","id":"claim_6c9a5e7c64827bb43ee4c978bf5d77ecfdeb14366de1bd2e153f7e4e69457153","kind":"lemma","schema_version":1,"statement":"[Lemma 12 (Master component identity) of arXiv:2608.29406, 'Partially Totally Real Submanifolds of Sasakian Manifolds'] For \(X,Y\in\Gamma(\Dtilde)\) and \(Z\in\Gamma(\Dperp)\),
