\max\{\sigma(x),s_0\}
}
\right]
\le
C\sqrt{\log(eM_{r_0,s_0})}.
\end{equation}
Consequently, for every \(x\in T\),
\begin{equation}
\mathbb E|X_x|
\le
C\max\{\Phi_\mu(x),r_0\}
+
C\max\{\sigma(x),s_0\}\sqrt{\log(eM_{r_0,s_0})}.
\end{equation}
At the global level, taking \(r_0\ge\Phi_{\mu,\ast}\) and \(s_0=R_\ast\) gives \(M_{r_0,s_0}=1\), hence
\begin{equation}
\mathbb E\sup_{x\in T}|X_x|
\le
C(r_0+R_\ast).
\end{equation}
Letting \(r_0\downarrow \Phi_{\mu,\ast}\), then optimizing over \(\mu\), and using \eqref{eq:absolute-global-optimality}, we obtain the sharp equivalence
\begin{equation}
\mathbb E\sup_{x\in T}|X_x|
\asymp
R_\ast+\inf_{\mu\in\Delta(T)}\Phi_{\mu,\ast}.
\end{equation}
Thus the optimized expectation version is optimal up to absolute constants. (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

