{"assumptions":[],"created_at":"2026-10-27T20:48:25.216926+00:00","domain":"probability theory","id":"claim_6cded10dcfd7dc3e88a71fe5287a5657209c5994301876705463d5c9cfa23c61","kind":"concept","schema_version":1,"statement":"[Lemma lem:continuity of arXiv:2607.05671, 'Bi-infinite systems of singularly interacting Brownian particles and the KPZ equation'] Fix $r \in [1,\infty)$, $\theta \in (0,1)$, and $T \in (0,\infty)$.
\begin{enumerate}[label = (\roman*)]
\item There exist constants $C_1 = C_1(\theta,r,T)$ and $C_2 = C_2(\theta,r,T)$ in $(0,\infty)$ such that for all $\varepsilon \in (0,1]$, $t \in [0,T]$ and $x,x' \in \mathbb{R}$, 
\begin{equation} 
\|\tilde{\mathcal{E}}_\theta^\varepsilon(t,x') - \tilde{\mathcal{E}}_\theta^\varepsilon(t,x)\|_r \leq C_1e^{C_2(|x|+|x'|)}|x' - x|^{\theta/2}.
\end{equation}
\item 

There exist constants $C_3 = C_3(\theta,r,T)$ and $C_4 = C_4(\theta,r,T)$ in $(0,\infty)$ such that for all $\varepsilon \in (0,1]$, $x \in \mathbb{R}$ and $t,t' \in [0,T]$,
\begin{equation} 
\| \tilde{\mathcal{E}}_\theta^\varepsilon(t',x) - \tilde{\mathcal{E}}_\theta^\varepsilon(t,x) \|_r \leq C_3 e^{C_4|x|}|t' - t|^{\theta/4}.
\end{equation}
\end{enumerate} (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T06:16:18.694764+00:00","domain":"probability theory","id":"claim_6ce2b8dbbc3246db8b1c7128d67b435f43e775cd861895ec366b3382dd07ed46","kind":"theorem","schema_version":1,"statement":"[Proposition 41 (Axis formula for a metric-tree translation) of arXiv:2607.26377, '\textbf{Entire Logarithmic Signatures\\ of Bounded-Variation Paths in Finite Dimensions}'] Let $(\mathscr{T},d)$ be a complete metric tree and let $L:\mathscr{T}\to\mathscr{T}$ be a surjective isometry. Suppose that a closed geodesic line $\mathcal{A}\subset\mathscr{T}$ has an isometric parametrisation $\alpha_{\mathcal A}:\R\to\mathcal{A}$ satisfying
\[
L(\alpha_{\mathcal A}(t))=\alpha_{\mathcal A}(t+\tau)\qquad(t\in\R)
\]
for some $\tau>0$. For $x\in\mathscr{T}$, let $q$ be the projection of $x$ onto $\mathcal{A}$. Then $Lq$ is the projection of $Lx$ and
\begin{equation}
[x,Lx]=[x,q]\cup[q,Lq]\cup[Lq,Lx],
\end{equation}
with intersections only at consecutive endpoints. Moreover,
\begin{equation}
d(x,Lx)=2d(x,\mathcal{A})+\tau,
\end{equation}
and
\begin{equation}
\mathcal{A}=\{x\in\mathscr{T}:d(x,Lx)=\tau\}.
\end{equation}
Thus $\mathcal{A}$ is the unique minimum-displacement axis of $L$.","status":"unverified"}

