{"assumptions":[],"created_at":"2026-10-26T20:24:10.191652+00:00","domain":"probability theory","id":"claim_6d45e6a12ad75c4e6c3f4164662edfad980b108f31f01b1ad5e69e4bbaab595e","kind":"theorem","schema_version":1,"statement":"[Thm 3 (Bounding Wasserstein distance by the uniform discrepancy) of arXiv:2605.03528, '\bf Kolmogorov-Smirnov distance and discrepancies {\em versus} Wasserstein distances'] Let $\mu$ and $\nu$ two probability measures on $([0,1]^d, {\cal B}or([0,1]^d),\lambda_d)$.  Then,
\begin{itemize}
\item If $p>d$ then
\begin{align*}
{\cal W}_p^p(\mu, \nu)& \le   \frac{\diamd^p(2^p+1)}{2(2^{p-d}-1)}    D^{\infty}(\mu,\nu) .


\end{align*}
If furthermore, $1+2^{-p}-2^{p-d}>0$, i.e. $p< d+\frac{\log(1+\sqrt{1+2^{-(d-2)}})}{\log 2}-1$, then
\begin{align*}
{\cal W}_p^p(\mu, \nu)& \le   \frac{\diamd^p}{2^{p-d}-1}\left[\frac{2^p+1}{2}    D^{\infty}(\mu,\nu) -  2^{p(1-\frac{1}{d})}\left(1+2^{-p}-2^{p-d}\right) D^{\infty}(\mu,\nu)^{\frac{p}{d}}\right].


\end{align*}

\item If $p=d$  then
\[
{\cal W}_p^p(\mu, \nu) \le  \diamd^d   \bigg( \bigg(   \frac{(d+1)2^{d-1}}{d}+\frac 1{2d}\bigg) D^{\infty}(\mu,\nu)+\frac{2^d+1}{2d\log 2} D^{\infty}(\mu,\nu)\log\Big(\frac{1}{ D^{\infty}(\mu,\nu)}\Big)\bigg).
\]
\item If $p<d$ then
\[
{\cal W}_p^p(\mu, \nu) \le \diamd^p    {2^{-\frac pd}}   \bigg( \frac{2^p+1}{1-{2^{p-d}}} + 2^{p}\bigg) D^{\infty}(\mu,\nu)^{\frac pd}.
\]
\end{itemize}","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-26T19:31:49.844254+00:00","domain":"probability theory","id":"claim_6d460a633315808d9a36f2f67c56545432167841c76f38c1e77eba85ad903816","kind":"theorem","schema_version":1,"statement":"[Proposition 10 of arXiv:2506.14145, '\bf Global-in-time optimal control of stochastic third-grade fluids with additive noise'] Let $\vb_1,\vb_2$ be two solutions to system \eqref{STGF-Projected} in the sense of Definition \ref{def-Solution} satisfying \eqref{eqn-vb-exponential-moments} associated with external forcing $\fb_1,\fb_2\in \Lrm^2(\Omega;\mathrm{L}^2(0,T;\dot{\Hb}^{1}(\mathbb{T}^2)))$ and same initial data $\vb_{0}\in \Drm(\A^{\frac{3}{2}})$, respectively. Then, there exists a constant $K$ depending only on the given data $\nu$, $\alpha_1$, $\alpha_2$ and $\beta$ such that 
