{"assumptions":[],"created_at":"2026-10-26T19:34:09.926532+00:00","domain":"probability theory","id":"claim_6d4d937972426b016634bb3a61f80109605b807404c7fc3ff7f144e527821fad","kind":"concept","schema_version":1,"statement":"[Lemma 6 of arXiv:2603.27712, 'Bridging Schr\"odinger and Bass: A Semimartingale Optimal Transport Problem with Diffusion'] Fix $T,\beta>0$ and $\psi\in\bar\Cc^{\conc}$. Set $\phi:=\mathbf{T}_\beta^-[\psi]$. Then:
\begin{enumerate}
\item[{\rm (1)}] $h^\phi_t:=\Nc_{T-t}*e^\phi >0$ for all $t\le T$, and $h^\phi\in C^{1,3}(Q_T)$ satisfies
\begin{equation}
\partial_t h^\phi+\tfrac12\Delta h^\phi=0~\text{on } Q_T.
\end{equation}
\item[{\rm (2)}] $\tilde u^\phi:=\log{h^\phi}\!\in\! C^{1,3}(Q_T)$, with $D^2\tilde u^\phi_t\!+\!\kappa(t)I\succeq 0,$ $\kappa(t)\!:=\!\frac{\beta}{1+\beta(T-t)}$, $t\!<\!T$, and
\begin{equation}
\partial_t \tilde u^\phi+\tfrac12\big(\Delta \tilde u^\phi+|\nabla \tilde u^\phi|^2\big)=0~\text{on } Q_T.
\end{equation}
\item[{\rm (3)}] $v^\phi:=\mathbf{T}_\beta^+[\tilde u^\phi]\in C^{1,2}(Q_T)$, and the minimum in $\mathbf{T}_\beta^+[\tilde u^\phi_t](x)$ is uniquely attained at $\msY_t(x)$, for all $(t,x)\in Q_T$. Moreover,
\\
{\rm (3-a)} $\nabla v^\phi=\beta({\rm id}-\msY)$, $\partial_t v^\phi=\partial_t \tilde u^\phi(\msY)$, and $D^2 v^\phi-\beta I=-\beta^2\big(\beta I+D^2\tilde u^\phi(\msY)\big)^{-1}$. 
In particular, $-\frac1{T-t}I\preceq D^2 v^\phi_t\prec \beta I$, for all $t<T$.
\\ 
{\rm (3-b)} $v^\phi$ is a solution of the HJB equation \eqref{HJB}.
\\
{\rm (3-c)} If, in addition, $\psi\in\Cc_{w,\uparrow}^{\conc}$, then $v^\phi_t\to \psi$ locally uniformly as $t\uparrow T$, and $v^\phi$ has quadratic growth uniformly in $t$, i.e. there exists a constant $C<\infty$ such that
\begin{equation}
|v^\phi_t(x)|\le C(1+|x|^2),
\qquad (t,x)\in Q_T.
\end{equation}
\end{enumerate} (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T06:06:21.725457+00:00","domain":"probability theory","id":"claim_6d527944eed78dfbe1cda54e3930179cfab9e972962c5a3e8cb40062c428dff7","kind":"lemma","schema_version":1,"statement":"[Lemma 15 of arXiv:2607.21374, 'Local structure at the maximum and sharp persistence asymptotics of rough fractional Brown'] For every \(R<\infty\) and \(\varepsilon>0\),
