				\|Q_{+}u(t)\|_{L^{\infty}} \le R_{Q,\infty}, \quad t\in\R.
			\end{align*}","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T08:26:47.152091+00:00","domain":"probability theory","id":"claim_6e0fafad07818c4b16d15e3c9d3878a32f0d981ad51ea0e1ba3bf6cdbfebcf87","kind":"lemma","schema_version":1,"statement":"[Lemma 24 of arXiv:2608.29361, 'Convergence of the subcritical $\gamma$-LQG metric to the critical $2$-LQG metric as $\gam'] Let $U \subseteq \CC$ be a bounded open set and fix $\varepsilon \in (0,1), \delta \in (0,\xi_c / 2)$. Suppose that we choose the continuous functions $b,M$ such that $b(\xi) \sqrt{M(\xi)} > 40 (1+\xi_c) / \delta$ for all $\xi \in (\xi_c / 2 , \xi_c]$. Then, the following holds for all $\xi \in (\xi_c/2 , \xi_c]$. There exists deterministic constant $C>1$ depending only on $\varepsilon,\delta$, and $U$, such that the following is true with probability at least $1-\varepsilon$. Fix $z \in U$. Then, we have the following.
\begin{enumerate}
    \item 
    For all $m,n \in \NN$ with $m<n$,
    \begin{align*}
        \widetilde{D}_h^{\xi}(\partial B_{e^{-n-50}}(z) , \partial B_{e^{-m}}(z)) \leq C \sum_{k=m}^{n-1} \min_{t \in [k,k+1]} \left(\exp\left((\xi-\delta) (h_{e^{-t}}(z)-2t)\right)\right).
    \end{align*}
    \item 
    For all $n \in \NN$,
    \begin{equation*}
        \widetilde{D}_h^{\xi}(\text{around}\,\,\mathbb{A}_{e^{-n-1},e^{-n}}(z)) \leq C \min_{t \in [n+1,n+2]} \left(\exp\left((\xi-\delta) (h_{e^{-t}}(z) - 2t)\right)\right).
    \end{equation*}
\end{enumerate}","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T21:37:09.015610+00:00","domain":"probability theory","id":"claim_6e0fe40f959459628c66f83db894dfeee5ca58594b03c530e29fbb39761339ab","kind":"theorem","schema_version":1,"statement":"[Proposition prop:harvest of arXiv:2609.01697, 'Unique ergodicity of projective cocycles over the 2D stochastic Navier--Stokes equations'] Fix $T > 0$ and $z_0 \in \mathcal{X}$, and let $\eta = (\delta w, \delta\pi) \in T_{z_T}\mathcal{X}$ satisfy $\langle M_T(z_0)\eta, \eta\rangle = 0$, with $\eta_s$ as in~(equation eq:eta_def of the paper). Then $\delta w = 0$ and, for every bracket-generated $\mathfrak{g} \subseteq \mathrm{Op}^{\beta_\star}$,
  \begin{equation}
    \langle \eta_s, {A}^\sharp\pi_s \rangle = 0 ,
    \qquad \forall s \in (0,T] , \ A \in \mathfrak{g} ,
  \end{equation}
  almost surely, with an exceptional null set that depends only on $T$, $z_0$, and
  $\mathfrak{g}$,  but
  not on $\eta$.","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T08:22:48.869992+00:00","domain":"probability theory","id":"claim_6e13643587e8f8fab53ef5f8d7b3b2bc0805e42a2a0793d426638e13fddc58a5","kind":"theorem","schema_version":1,"statement":"[Prop 15 of arXiv:2608.29148, '2608.29148'] The curvature tensor $R'_{abcd}$ is given by 
