	\end{equation}","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T09:57:28.709147+00:00","domain":"probability theory","id":"claim_708465542a17dc5000bf0264c9d1c5176e5a183278d6ca22ae37f885738c28cf","kind":"definition","schema_version":1,"statement":"[Definition 5 of arXiv:2609.01143, 'The voter model on the hyperbolic graph'] The degree--dependent voter model is the voter model dual to the Markov chain
\begin{equation}
q(v)=\de(v)^\varphi, \qquad Q_{v,w}=\de(v)^{\varphi-1}\mathbbm{1}_{\{v\sim w\}},

\end{equation}
i.e. each vertex $v$ imitates each $w$ at rate $Q_{v,w}$, and so by iteration the opinion history has these dynamics after time reversal.","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T06:00:15.225016+00:00","domain":"probability theory","id":"claim_7086d0508d5c334cf359d0b575f780533ffc50f0897bc7d7f95ece363a637f2a","kind":"lemma","schema_version":1,"statement":"[Lemma 2 (Exponential peeling) of arXiv:2607.18619, 'Chernoff's Density Is Strongly Log-Concave'] Let $E\sim\Exp(\lambda)$ have rate $\lambda>0$, let $T$ be independent of
$E$, and let $c\in\R$.  Assume that $T$ has a strictly positive $C^1$
log-concave density $q$ on $\R$ and that
\begin{equation}
    \resmgf(s):=\E e^{sT}<\infty
    \qquad\text{for every }s\in[-\lambda,\infty).
\end{equation}
If $G$ is the density of $c-E+T$, then $G$ is $C^2$ and
\begin{equation}
    -(\log G)''(x)>0, \qquad x\in\R.
\end{equation}
More precisely, define the Esscher-transformed probability density
\begin{equation}
    p(t):=\frac{e^{-\lambda t}q(t)}{\resmgf(-\lambda)},
\end{equation}
let $S(z)=\int_z^\infty p(t)\dd t$, and let $h=p/S$ be its right hazard
rate.  Then
\begin{equation}
    G(x)=\lambda e^{\lambda(x-c)}\resmgf(-\lambda)S(x-c), 
\end{equation}
and
\begin{equation}
    -(\log G)''(x)=h'(x-c)>0.
\end{equation}","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T23:32:34.760238+00:00","domain":"probability theory","id":"claim_708723a719aac4f0329410e837accf936596b270915db64c789d3655db872e9d","kind":"concept","schema_version":1,"statement":"[Theorem nier_Hardyego of arXiv:2411.08220, 'Nonlocal operators with Neumann conditions'] [Hardy inequality]
    For $u\in L^2(\mathbb{R})$ and $\alpha\in (0,1)\cup(1,2)$,
    \begin{align}
    \mathcal{E}[u] \geq (\mathcal{C}_\alpha + \mathcal{D}_\alpha) \int_D u^2(x)|x|^{-\alpha}\,\mathrm{d}x + \mathcal{C}_\alpha \int_{D^c} u^2(x)|x|^{-\alpha}\,\mathrm{d}x,
    \end{align}
    where
    \[
        \mathcal{C}_{\alpha} = \mathcal{A}_{1,\alpha} \Big[\alpha^{-1} - \frac{\big(\Gamma(\tfrac{\alpha+1}{2})\big)^2}{\Gamma(\alpha+1)}\Big]> 0 \qquad and \qquad
        \mathcal{D}_{\alpha} = \mathcal{A}_{1,\alpha} \int_0^1 \frac{(1-t^{(\alpha-1)/2})^2}{(1-t)^{\alpha+1}}\,{\rm d}t > 0.
    \] (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T20:58:09.903179+00:00","domain":"probability theory","id":"claim_708998b13b4d354cc4fa7a9f2c33a1cf91d645e64c529e883ed6ab96aaf5c5fb","kind":"definition","schema_version":1,"statement":"[Def CPS of arXiv:2607.19511, 'A Conditional Probability Hierarchy for Stochastic Choice\footnote{We thank Samson Abramsk'] A \textbf{conditional probability space} (\textbf{CPS}) (relative to $\cal G$) is a map $p : {\cal G} \rightarrow \Delta(\Omega)$, which we will also write as $G \mapsto p_G(\cdot)$ for $G \in {\cal G}$, satisfying:
\begin{enumerate}
\item $p_G(G) = 1$ for every $G \in \cal G$;
\item $p_G(E) = p_G(F) \times p_F(E)$ for every $E \subseteq F \subseteq G$ with $E \in \cal F$ and $F, G \in \cal G$.
\end{enumerate}","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-26T19:24:25.931965+00:00","domain":"probability theory","id":"claim_708b2971d19e792b7bf170096be1dccb453a6eb86f90c62cc6db74f506d0adb3","kind":"definition","schema_version":1,"statement":"[Defn 24 (The black-golden coupling) of arXiv:2506.19123, 'The longest increasing subsequence of Brownian separable permutons'] We say that the decreasing chains $\DMC$ and $\DMC'$ have the \textbf{black-golden coupling} when the dynamics of $\DMC$ (and $\DMC'$) are described for all $t\geq 0$ as follows:\footnote{We stress that here we are using a \emph{unique} set of black and golden instructions for \emph{both} chains $\DMC$ and $\DMC'$.}
    \begin{equation}
    	\DMC_{t+1} = \left\lbrace \begin{aligned}
    	& G_{\DMC_t} \qquad \text{if } \DMC_t \in \intervalleentier{5\ell}{7\ell} \text{ for some good scale $\ell$  and } B_{\DMC_t}  \in \intervalleentier{\ell}{4\ell}; \\
    	&B_{\DMC_t} \qquad \text{otherwise.}
    \end{aligned}
	\right.
    \end{equation}
    Moreover, when two chains $\DMC$ and $\DMC'$ are started from $k$ and $k'$ respectively, we denote their joint law under this coupling by $\mathbb{P}_{k,k'}$.","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T09:48:30.932188+00:00","domain":"probability theory","id":"claim_708e6a8e5fd44dd27cf8f0fab7ca6e917307c3fdbf6032167d69bd8d0e9bf5d1","kind":"concept","schema_version":1,"statement":"[Lemma 22 of arXiv:2609.01020, '2609.01020'] Assume that $f=(f_1,\ldots , f_d)\colon X\longrightarrow \CC_s^d$ 
satisfies the Thom condition in a direction $a\in \CC^d \setminus \mathrm{C}_{\{0\}}(\Delta_f)$. 
Then there exists a neighborhood $U\subset \CC^d \setminus \mathrm{C}_{\{0\}}(\Delta_f)$ 
of $a$ and $0<\e_0 \ll 1$ such that for any 
