{"assumptions":[],"created_at":"2026-10-28T00:52:17.591313+00:00","domain":"probability theory","id":"claim_712777358549484e877935d3b548699d72b310a44a655f3fc10311f988daeba8","kind":"definition","schema_version":1,"statement":"[Definition A1 of arXiv:2411.15485, '\bf\Large Stochastic Volterra Equations for Local Times of Spectrally Positive L\'evy Proc'] Consider a sequence of $\mathbb{H}^\#$-semimartingales $\{Y_n\}_{n\geq 1}$.
 \begin{enumerate}
 	\item[(1)] It is {\rm uniformly tight} if for each  $t\geq 0$, the family $\{\mathcal{H}_{n,t}\}_{n\geq 1}$ is uniformly stochastically bounded, where $\mathcal{H}_{n,t}$ is defined as in ((eqn.Ht of the paper)) with $Y$ replaced by $Y_n$.

 	\item[(2)] We say $Y_n$ {\rm converges weakly} to $Y$ and write $Y_n \Rightarrow Y$ if for any $m\geq 1$ and $f_1,\cdots,f_m\in\mathbb{H}$,
 	\begin{eqnarray*}
 	(Y_n(f_1),\cdots, Y_n(f_m))\overset{\rm d}\to(Y(f_1),\cdots, Y(f_m))\quad \mbox{in }D([0,\infty),\mathbb{R}^m).
 	\end{eqnarray*}
 	In addition,
 	we also write $(X_n,Y_n) \Rightarrow (X,Y)$ if
 	\begin{eqnarray*}
 	(X_n, Y_n(f_1),\cdots,Y_n(f_m))\overset{\rm d}\to(X,Y(f_1),\cdots, Y(f_m))\quad \mbox{in }D([0,\infty),\mathbb{H}\times\mathbb{R}^m).
 	\end{eqnarray*}
 \end{enumerate}","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-26T19:47:01.668454+00:00","domain":"probability theory","id":"claim_7127e5b858369cb9a459e63d54fad629cb92c4245ddf03fa51569aee7c98ebd2","kind":"theorem","schema_version":1,"statement":"[Thm 15 of arXiv:2604.24189, 'Malliavin calculus and densities for chaos-driven stochastic differential equations'] Under the conditions of Theorem \ref{thm:MallDiff}, we have, for all $1 \leq k \leq d$ and $t\in (0,T]$
\begin{enumerate}[(a)]
	\item 	
	\begin{align}
		D X_t^k &=  \sum_{\ell=1}^{m} \int_{0}^{t} \Theta_{t}^{k l}(r) d DF^l(r)\nonumber\\
		&:=\lim_{|\mathcal{P}|\to 0}\sum_{\ell=1}^{m}\sum_{[u,v]\in \mathcal{P}} \Theta_{t}^{k l}(u) (DF^l(v)-DF^l(u)),
	\end{align}
	where $\Theta^{k,\ell}_t$ is given by \eqref{eq:Theta} and the above limit is in $\HHH$, along an arbitrary sequence of partitions of $[0,t]$ with mesh tending to zero.
	Furthermore, for any $\beta\in (0, H-\frac{1}{2})$ there exists a constant $C>0$ such that
	\begin{align}
		&\left\|\sum_{\ell=1}^{m} \int_{s}^{t} \Theta_{t}^{k l}(r) d DF^l(r)- \sum_{\ell=1}^{d}\Theta_{t}^{k l}(s)\big(DF^l(t)-D^{(l)}F(s)\big)\right\|_{\HHH}\\
		&\leq C \sum_{\ell=1}^{m}\|\Theta_{t}^{k l}\|_{\mathcal{C}^{H-\beta_1}} \|DF^l\|_{\mathcal{C}^{H-\beta_2}} |t-s|^{2(H-\beta)};\nonumber
	\end{align}	
	uniform in $s,t\in [0,T]$. 
	\item for all $h \in \mathfrak{H}$, 
	\begin{align}
		&\left<D X_t^k, h\right>_{\HHH} =  \sum_{\ell=1}^{m} \int_{0}^{t} \Theta_{t}^{k l}(s) d \left<DF^l(s), h\right>_{\HHH}\nonumber\\
		&:=\lim_{|\mathcal{P}|\to 0}\sum_{\ell=1}^{m}\sum_{[u,v]\in \mathcal{P}} \Theta_{t}^{k l}(u) \left<DF^l(v)-DF^l(u),h\right>_{\HHH},	
	\end{align}
	where the limit is along an arbitrary sequence of partitions of $[0,t]$ with mesh tending to zero.
