\begin{align}
\widehat{\mathsf K}^{T,\beta,\varepsilon,\pi'}_{[s,t]}(x,A)
\;\le\;
\widehat{\mathsf K}^{T,\beta,\varepsilon,\pi}_{[s,t]}(x,A).
\end{align}

\item Fix $0\le r<s<t\le T$ and let $\pi$ be a partition of $[r,t]$ with $s\in\pi$. Then for every $x\in E_\varepsilon$ and $A\in\mathcal B(E_\varepsilon)$,
\begin{align}
\widehat{\mathsf K}^{T,\beta,\varepsilon,\pi}_{[r,t]}(x,A)
