		\end{align}
		As a consequence, we have 
		\begin{align}
			\forall x \in {\scaleobj{1}{\square}} \setminus  \mathscr{C}_{\operatorname{bc}}^F({\scaleobj{1}{\square}}), \qquad (D_F u)(x) = (D_F u)([x]).
		\end{align}","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T09:19:56.669824+00:00","domain":"probability theory","id":"claim_71bb0853165d7f3a6cd85ab756e4463fbdc63aa2b7a5ea7711487b5e4a1421c0","kind":"lemma","schema_version":1,"statement":"[Lemma 14 of arXiv:2608.30875, 'A Decomposition Theorem for Topological Semi-small Maps'] Let $R$ be a closed topologically stratified space with the intrinsic stratification $R=\bigsqcup_{\alpha} S_{\alpha}$. Consider a finite decomposition $R=\bigsqcup_{\beta} T_{\beta}$ such that each $T_{\beta}$ is a topologically stratified space with a stratification $T_{\beta}=\sqcup_{\gamma} V^{\beta}_{\gamma}$. Assume the following:
    	\begin{enumerate}
		\item The inclusion $\overline{V^{\beta}_{\gamma}} \hookrightarrow R$ is locally flat, for all $\beta$ and $\gamma$.
		\item For each point $r \in R$ there is an open neighborhood that intersects finitely many connected components of finitely many $V^{\beta}_{\gamma}$. 
		\item The collection $\{ V_{\gamma}^{\beta}\}$ satisfies the frontier condition, i.e., $V^{\beta}_{\gamma} \cap \overline{V^{\beta^{\prime}}_{\gamma^{\prime}}} \neq \emptyset$ implies $V^{\beta}_{\gamma} \subseteq \overline{V^{\beta^{\prime}}_{\gamma^{\prime}}}$ for all $\gamma, \gamma^{\prime}, \beta,$ and $\beta^{\prime}$. 
	   \end{enumerate}
	   Then the decomposition $R=\bigsqcup_{\alpha,\beta,\gamma} (V_{\gamma}^{\beta} \cap S_{\alpha})$ is a topological stratification.","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-26T19:33:23.330432+00:00","domain":"probability theory","id":"claim_71bd31658caf7fc929a7ccd1354e25a13d83747731e45934aaa082f9bd035bd7","kind":"concept","schema_version":1,"statement":"[Lemma 7 of arXiv:2506.22020, 'Norm-dependent Lamperti-type MAP representations of stable processes and Brownian motions '] Let $(\hat{\xi},\hat{\Xi})=(\hat{\xi}_t,\hat{\Xi}_t)_{t\geq0}$ be the underlying MAP of $\hat{X}$ from (\ref{item_b}) with respect to the $L^1$ norm on $\mathbb{R}^d$, and $L$ be the first time of appearance of a jump of $(\hat{\xi},\hat{\Xi})$ due to the reflection. Let $\tau_D=\inf\{t>0: X_t\notin D\},$ the first exit from the orthant  $D:=(0,\infty)$ by the stable process $X$ in (a). The distribution of the ``corrective" jumps of the MAP $(\hat{\xi},\hat{\Xi})$ is determined by the first exit from the orthant $D$ as follows
\begin{equation}
\begin{split}
&{E}_{\theta}\left(G\left(\log\left(\frac{\|X_{\tau_D}\|_1}{\|X_{\tau_D-}\|_1}\right), \left(\frac{|X^{(i)}_{\tau_D}|}{\|X_{\tau_D}\|}, i\in\{1,\ldots, d\}\right)\right) \Bigg| X_{\tau_D-}\right)
\\
&\hspace{2cm}={\mathbb{E}_{0,\theta}\left(G\left(\Delta\hat{\xi}_{L}, \hat{\Xi}_L\right)\Big| \hat{\Xi}_{L-}=X_{\tau_D-}/\norm{X_{\tau_D-}}_1 \right),
\qquad \theta\in \mathcal{S}_{\|\cdot\|_1} }
\end{split}
\end{equation}
for any bounded measurable function $G:\mathbb{R}\times\mathcal{S}^{d,+}_{1}\to\mathbb{R}$ and any $\boldsymbol{\theta}\in\mathcal{S}^{d,+}_{1}.$ The latter can be computed further via 
\begin{equation}
	\mathbb{E}_{(0,\boldsymbol{\theta})}[G(\Delta \hat{\xi}_{L},\hat{\Xi}_{L})|\hat{\Xi}_{L-}]  = H(\hat{\Xi}_{L-})

\end{equation}
where, for $\Xi\in \mathcal{S}^{d,+}_{1}$
\begin{equation}
H(\Xi)=q(\Xi)^{-1}\cdot\sum_{j=1}^d \int_{\log(1- \Xi^{(j)})}^\infty G\Big(x,\frac{1}{{\rm e}^x}\big( \Xi +({\rm e}^x-1)\boldsymbol{e}_j\big)\Big)\cdot ({\rm e}^x+2 \Xi^{(j)}-1)^{-(1+\alpha)}\cdot {\rm e}^x dx,
\end{equation}
  and we are using the notation $\Xi^{(j)}$ for the the $j$-th coordinate of the position $\Xi$ and $q$ is the function given by \eqref{q}  taking $\rho_k=1/2$ for all $k$. (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-28T01:37:28.980930+00:00","domain":"probability theory","id":"claim_71bf00e60c2a096905427fddff7e35dd7e91981e8dbef5e1800375364897ac52","kind":"concept","schema_version":1,"statement":"[Thm jointr of arXiv:2412.00610, 'Joint Poisson Convergence of Monochromatic Hyperedges in Multiplex Hypergraphs'] Fix an integer $r \ge 2$. Let $\bm H_n =(H_n^{(1)}, H_n^{(2)})$ be a sequence of 2-hypermultiplexes on the same vertex set $V_n$ with $|E(H_n^{(1)})| \to \infty$ and $|E(H_n^{(2)})| \to \infty$. Suppose $V_n$ is colored uniformly at random with $c_n$ colors as in (equation eq:cn of the paper), such that the following hold:
    \begin{itemize}
      \item  There exists constants $\lambda_1, \lambda_2, \lambda_{1,2} \ge 0$ with $\lambda_1 \ge \lambda_{1,2}, \lambda_2 \ge \lambda_{1,2}$ such that 
            \begin{align}
            \frac{|E(H_n^{(1)})|}{c_n^{r-1}} \to \lambda_1,~\frac{|E(H_n^{(2)})|}{c_n^{r-1}} \to \lambda_2, \text{ and } \frac{|E(H_n^{(1, 2)})|}{c_n^{r-1}} \to \lambda_{1,2}. 
            \end{align}


      \item  For all $t \in [2, r - 1]$
      \begin{align}
      \frac{|\cK(t, H_n^{(1)})|}{c_n^{2r-t-1}} \to 0 \text{ and } \frac{|\cK(t, H_n^{(2)})|}{c_n^{2r-t-1}} \to 0 , 
      \end{align}
     where $\cK(t, \cdot)$ is defined in (equation defn:K of the paper). 
  \end{itemize} 
Then 
$$\begin{pmatrix}
    T(H_n^{(1)}\setminus H_n^{(2)})\\
    T(H_n^{(2)}\setminus H_n^{(1)})\\
    T(H_n^{(1, 2)})
\end{pmatrix} \dto \begin{pmatrix}
        Z_1 \\
        Z_2 \\
        Z_{1,2}
        \end{pmatrix} , $$
  where $Z_1 \sim \Pois(\lambda_1 - \lambda_{1,2})$, $Z_2 \sim \Pois(\lambda_2 - \lambda_{1,2})$, and $Z_{1,2} \sim \Pois(\lambda_{1,2})$ are independent. (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

