{"assumptions":[],"created_at":"2026-10-28T00:59:45.457335+00:00","domain":"probability theory","id":"claim_71e4974601d881198db43bb8e3670037c4e3f84b3e5a52677cd77be563a41665","kind":"concept","schema_version":1,"statement":"[Lemma lemma_M of arXiv:2411.16572, 'Optimal decay of eigenvector overlap for non-Hermitian random matrices'] For any bounded deterministic matrices $A_1,A_2 \in {\mathbb C}^{2n \times 2n}$, we have
	\begin{align}
		\|M^{A_1}_{12}(\mathrm{i} \eta_1,z_1,\mathrm{i} \eta_2,z_2)\| \lesssim \frac{1}{\gamma},
	\end{align}
\begin{align}
	\big|\<\widehat M^{A_1}_{12} (\mathrm{i} \eta_1,z_1,\mathrm{i} \eta_2,z_2) A_2 \>\big| \lesssim \frac{\rho_1\rho_2}{\widehat \gamma},
\end{align}
\begin{align}
	\|M^{A_1,A_2}_{121}(\mathrm{i} \eta_1, A_1,\mathrm{i} \eta_2, A_2,\mathrm{i} \eta_1)\|  \lesssim \frac{1}{\eta_*\gamma},
\end{align}
uniformly for any $|z_i|<10$ and  $0<|\eta_i|<10$, where $\eta_*:=\min_{i=1,2}|\eta_i|$ and $\rho^*:=\max_{i=1,2}|\rho_i|$ with $\rho_i:=\pi^{-1}|\mathrm{Im}\, m^{z_i}(\mathrm{i}\eta_i)|$\normalcolor, and the following parameters:
\begin{align}
	\gamma=\gamma(\mathrm{i} \eta_1,z_1,\mathrm{i} \eta_2,z_2):=\frac{|z_1-z_2|^2+\rho_1|\eta_1|+\rho_2|\eta_2|+\left(\frac{\eta_1}{\rho_1}\right)^2+\left(\frac{\eta_2}{\rho_2}\right)^2}{|z_1-z_2|+\rho_1^2+\rho_2^2+\frac{\eta_1}{\rho_1}+\frac{\eta_2}{\rho_2}},
\end{align}
\begin{align}
	\widehat\gamma=\widehat\gamma(\mathrm{i} \eta_1,z_1,\mathrm{i} \eta_2,z_2):=|z_1-z_2|^2+\rho_1|\eta_1|+\rho_2|\eta_2|+\left(\frac{\eta_1}{\rho_1}\right)^2+\left(\frac{\eta_2}{\rho_2}\right)^2.
\end{align} (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T23:48:35.779290+00:00","domain":"probability theory","id":"claim_71e6d6675a0345cbb82252d7bc00fc8c18c9c9528e39183067babb75f8ebd953","kind":"theorem","schema_version":1,"statement":"[Proposition of arXiv:2411.09257, 'Iterated Generalized Counting Process and its Extensions'] The L\'evy measure of multivariate IGCP is given by
\begin{equation*}
