		\item For fixed $t \ge 0$, the map $(\bA, q) \mapsto P^B_t(\bA, q)$ is locally Lipschitz-continuous from $\ccA \times \ccM$ to $\cL(L^2(B))$.
		\item For fixed $(\bA, q) \in \ccA \times \ccM$, the map $t \mapsto P^B_t(\bA, q)$ is continuous from $[0, \infty)$ to $\cL(L^2(B))$.
		\item For fixed $(\bA, q) \in \ccA \times \ccM$ and $0 \leq s < t < \infty$, one has the semigroup property $P^B_{t}(\bA, q) = P^B_{t-s}(\bA, q) \circ P^B_{s}(\bA, q)$.
	\end{enumerate}","status":"unverified"}

