{"assumptions":[],"created_at":"2026-10-26T20:54:53.442160+00:00","domain":"probability theory","id":"claim_7271aa8722179a56cb08748109ac09c3fbf95ecc876bb2b898591118be54ea2c","kind":"theorem","schema_version":1,"statement":"[Proposition 36 of arXiv:2606.15425, 'Well-posedness of stochastic parabolic equations with gradient nonlinearities and applicat'] Let $z_0 \in L^0(\Omega;B^{d/q}_{q,2p})$ be $\mathcal F_0$-measurable and take values in a compact subset $\mathcal A \Subset B^{d/q}_{q,2p}$. Given a measurable process $c \colon \Omega \times [0,\tau] \rightarrow \mathcal X_c$, there exists a 
deterministic $t_0 > 0$ and unique mild solution $z$ of 
\begin{equation} 
\d z_t  = \left(\Delta z_t - |\nabla z_t|^2 + \widetilde h(z_t,c_t) + \widetilde\Phi(z_t,c_t) |\nabla z_t|\right) \d t
\end{equation}
with $$z \in L^\infty(\Omega;\mathbb Z_q(\tau_0)),$$ where $\tau_0 = \tau \wedge t_0$. In particular, for $(z,c)$ given by Lemma \ref{lemma:phasefieldlocalstrongex}, $z \in \mathbb Z_q(\tau_0)$. Moreover, if $z_0\geq 0$, $\mathbb P$-a.s., then $z_t \geq 0$ for all $t \in [0,t_0 \wedge \tau)$, $\mathbb P$-a.s.","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-28T02:47:21.594623+00:00","domain":"probability theory","id":"claim_72762cb6666fd8007aba2ec2405a837f22793af16315d3d5ac0da97e50f78b35","kind":"concept","schema_version":1,"statement":"[Lemma Eq:5.2 of arXiv:2412.08964, 'Phase transition and critical behavior in hierarchical\\integer-valued Gaussian and Coulom'] Let~$\alpha\in\mathbb R$ and, given $\{w_1(q)\}_{q\in\mathbb Z}\in\ell^1(\mathbb Z)$, define
$\{w_k(\cdot)\}_{k=1}^{ n+1}$ by the recursion
\begin{equation}

w_{k+1}(q):=\frac{a_{k-1}(0)^b}{a_{k}(0)}\sum_{\begin{subarray}{c}
\ell_1,\dots,\ell_b\in\mathbb Z\\\ell_1+\dots+\ell_b=q
\end{subarray}}
\biggl(\,\prod_{i=1}^{b-1}\frac{a_{k-1}(\ell_i)}{a_{k-1}(0)}\biggr)\,w_k(\ell_b)\,\theta_{k}^{(q+\alpha)^2}.
\end{equation}
Then $\{w_k(q)\}_{q\in\mathbb Z}\in\ell^1(\mathbb Z)$ for all~$k=1,\dots, n+1$  and so we can set 
\begin{equation}

f_k(z) := a_{k-1}(0)\text{\rm  e}\mkern0.7mu^{v_{k-1}(z)}\sum_{q\in\mathbb Z}w_k(q)\text{\rm  e}\mkern0.7mu^{2\pi\text{\rm  i}\mkern0.7mu qz}.
\end{equation}
Moreover, with $\mathcal F_k$ as in (equation Eq:4.1 of the paper),
\begin{equation}

E\bigl(\text{\rm  e}\mkern0.7mu^{2\pi\text{\rm  i}\mkern0.7mu\alpha \phi_k}f_k(\phi_k)\,\big|\,\mathcal F_{k+1}\bigr) =
\text{\rm  e}\mkern0.7mu^{2\pi\text{\rm  i}\mkern0.7mu\alpha \phi_{k+1}}f_{k+1}(\phi_{k+1})
\end{equation}
then holds for all~$k=1,\dots,n$. In short, $\{\text{\rm  e}\mkern0.7mu^{2\pi\text{\rm  i}\mkern0.7mu\alpha \phi_k}f_k(\phi_k)\}_{k=1}^{ n+1}$ is a reverse martingale. (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T15:32:35.571879+00:00","domain":"probability theory","id":"claim_7276e68b4773996c7528a9f294a8364ddd0d894c8f2fdfc9a03e8c2b21ddba1f","kind":"concept","schema_version":1,"statement":"[Lemma lem:contraction of arXiv:2606.04859, 'Stein's method for the Wishart distribution'] Let $\alpha > 3d-3$ and $\Sigma\in \mathcal{S}_{++}^d$ be given. Let $(\mathfrak{W}_t)_{t\geq 0}$ be the Wishart process defined in (equation eq:Wishart.process of the paper), with transition semigroup $(\mathcal{P}^{\mathcal{W}}_t)_{t\geq 0}$ and stationary limiting distribution $\xi = \mathcal{W}_d(\alpha, \Sigma)$. For any given $t > 0$, let $\Sigma_t = (1 - e^{-2t})\Sigma$ and define
\[
h_t(X) \vcentcolon= h(\Sigma_t^{1/2}X\Sigma_t^{1/2}), \qquad X\in \mathcal{S}_{++}^d,
\]
with $h:\mathcal{S}_{++}^d\to\mathbb{R}$ being bounded and Lipschitz. Assume that $h\in C^d(\mathcal{S}_{++}^d)$ and that for every differential monomial $\overline{\nabla}$ of order at most $d$ in the entries of $\nabla_{\!X}$, there exist constants $C_{\overline{\nabla}}, N_{\overline{\nabla}}\geq 0$ such that
\begin{equation}
|\overline{\nabla}h(X)| \leq C_{\overline{\nabla}} (1 + \|X\|_F^{N_{\overline{\nabla}}}), \qquad X\in \mathcal{S}_{++}^d,
\end{equation}
and assume that
\begin{equation}
M_t^{\mathcal{D}}(h) \vcentcolon= \sup_{X\in \mathcal{S}_{++}^d} \sup_{\substack{U\in \mathcal{S}^d\\ \|U\|_F = 1}}\big|\langle U, \mathcal{D}\rangle_F \, h_t(X)\big| < \infty.
\end{equation}
Then, for every $W\in \mathcal{S}_{++}^d$, we have
\begin{equation}
\begin{aligned}
\big|(\mathcal{P}^{\mathcal{W}}_t h)(W)-\mathsf{E}[h(\mathfrak{W}_{\infty})]\big|
&\leq \frac{e^{-2t}}{1 - e^{-2t}} \, M_t^{\mathcal{D}}(h) \, \|\Sigma^{-1/2}W\Sigma^{-1/2}\|_F \\
&\qquad + e^{-2t} [h]_1 \, \|\Sigma\|_2 \, \mathsf{E}[\|\mathfrak{V}\|_F],
\end{aligned}
\end{equation}
where $\mathfrak{V}\sim \mathcal{W}_d(\alpha, I_d)$. (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T19:48:47.284466+00:00","domain":"probability theory","id":"claim_7277fabbafdab4b9c52eed9546e2bb09f4588432016f83e8cc0a4e16f5f14425","kind":"theorem","schema_version":1,"statement":"[Prop tv-general of arXiv:2604.20629, 'Rates of forgetting for the sequentially Markov coalescent'] Let $K$ be a Markov kernel on $(0,\infty)$
with transition density $q( \cdot |s)$ with respect to Lebesgue
measure, and let $\pi$ be an invariant probability measure for $K$.
Suppose that:
\begin{enumerate}
\item There exists $L<\infty$ such that 
\begin{equation}
\int^{\infty}_{0}\bigl|q(t|a)-q(t|b)\bigr| dt\le L |a-b|,\qquad a,b>0;
\end{equation}
\item There exists a coupling $(X_{n},Y_{n})_{n\ge0}$ of two copies of
the chain, with 
\[
X_{0}=x,\qquad Y_{0}\sim\pi,
\]
such that for some $r\in(0,1)$, 
\begin{equation}
\mathbb{E}\!\left[ |X_{n+1}-Y_{n+1}| \, \mid  \, X_{n},Y_{n}\right]\le r |X_{n}-Y_{n}|\qquad\text{a.s. for all }n\ge0.
\end{equation}
Then for every $n\ge1$, 
\begin{equation}
d_{\mathrm{TV}}\!\bigl(K^{n}(x,\cdot),\pi\bigr)\le\frac{L}{2} r^{ n-1} \mathbb{E}|x-Y_{0}|.
\end{equation}
In particular, the chain is geometrically ergodic in total variation.
\end{enumerate}","status":"unverified"}

