{"assumptions":[],"created_at":"2026-10-27T12:27:11.296779+00:00","domain":"probability theory","id":"claim_72c07209f4b399c487471c7587e490ce0a138d819417467ed47449835c50cbc8","kind":"lemma","schema_version":1,"statement":"[Lemma l:infconv of arXiv:2605.20587, 'Persistence and entropic repulsion of stationary Gaussian fields with spectral singularity'] Let $\mu$ be a spectral measure in $\mathbb{R}^d$ and let $\delta > 0$.  
 \begin{enumerate}[\rm (1)]

 \item There exists $T_0=T_0(\mu,\delta)>0$ such that, for all $T>T_0$,
 \[ \inf_{\mu' \le \mu} \mathbb{E} \inf_{B(T)} f_{\mu'} \ge -\sqrt{(2d\|\mu_{a.c.} + \mu_{s.c.}\|-\delta)\log T} . \]

\item As $T \to \infty$
\begin{equation*}
     \inf_{\mu' \le \mu} \mathbb{P} \Big[  \frac{\inf_{x \in B(T)} f_{\mu'}(x) }{ \sqrt{\log T}} \ge - \sqrt{2d\|\mu_{a.c.} + \mu_{s.c.}\|- \delta } \Big] \to 1. 
