{"assumptions":[],"created_at":"2026-10-26T19:36:44.553996+00:00","domain":"probability theory","id":"claim_73211fda371b42103fe358527ab469f779e75663009a16fee44efdbd8f4913e3","kind":"definition","schema_version":1,"statement":"[Definition 2 (Coercivity and continuity assumptions) of arXiv:2604.02312, 'A weak transport approach to the Schrödinger--Bass bridge'] Let $C_V:\mathcal X\times\cP_p(\mathcal Y)\to\R\cup\{+\infty\}$ be a standard weak transport cost and let $W:\cP_p(\mathcal Y)\times\cP_p(\mathcal Z)\to\R\cup\{+\infty\}$ be a standard weak transport problem.

    \begin{enumerate}
        \asptitem{Crc}{Crc}  \textbf{Coercivity assumption.}
        We say that $(C_V,W)$ satisfies the coercivity assumption for $r \in [1,p]$ if for each compact $K \subseteq \mathcal X \times \cP_p(\mathcal Z)$, the map
        \[
            \rho \longmapsto \inf_{(x,\eta)\in K}\bigl\{C_V(x,\rho)+W(\rho,\eta)\bigr\}
        \]
        has compact sublevel sets in $(\cP_p(\mathcal Y),\Wcal_r)$. 

        \asptitem{Cnt}{Cnt}  \textbf{Continuity assumption.}
        We say that $(C_V,W)$ satisfies the continuity assumption if, for every $\rho$ with $(x,\rho) \in {\rm dom}(C_V)$ for some $x \in \mathcal X$, the maps $x \mapsto C_V(x,\rho)$ and $\eta \mapsto W(\rho,\eta)$ are continuous on $\mathcal X$ and on $\cP_p(\mathcal Z)$, respectively.
    \end{enumerate}","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T21:31:49.907531+00:00","domain":"probability theory","id":"claim_732178fe436207a866761b56efb52f4638c7e3d316aab3b1a664ee087d655c4d","kind":"lemma","schema_version":1,"statement":"[Lemma lem:sum-mdp of arXiv:2608.26745, 'Moderate Deviations for the Largest Eigenvalue of a Randomly Deformed Gaussian Unitary Ens'] Let $b_N\to\infty$, $b_N=o(\sqrt N)$, and $b_N=N^{o(1)}$.  Define
