{"assumptions":[],"created_at":"2026-10-26T19:25:12.191048+00:00","domain":"probability theory","id":"claim_73886ec40a22179f1469ad576e31629879d629531d678636dd992fe621aeff5e","kind":"concept","schema_version":1,"statement":"[Thm 3 of arXiv:2510.21446, '{Uniqueness of adapted solutions to scalar BSDEs\\ with Peano-type generators}\tnoteref{fo'] Suppose the function $g$ defined in \eqref{eq:3.1} satisfies assumptions \ref{A1}-\ref{A3} and $\xi\in L^p(\R_{++})$. Let the process $\alpha_\cdot\geq c$ for a constant $c\geq 0$ and the constants $\hat p>\bar p>q$, and let $\tilde p>1$ be the constant such that $1/p+1/\bar p=1/\tilde p$. If $\frac{1}{\varphi(\xi)+c}\in L^{\hat p\lambda {\rm e}^{2\tilde\beta T}}(\R_+)$, then the following BSDE
\begin{equation}
  Y_t=\xi+\int_t^T g(s,Y_s,Z_s){\rm d}s-\int_t^T Z_s {\rm d}B_s, \ \ t\in\T
\end{equation}
admits a unique adapted solution $(Y_t,Z_t)_{t\in\T}\in \scal^p(\R_{++})\times \mcal^p(\R^{1\times d})$. Moreover, by denoting
\begin{equation}
f^*(\omega,t,q):=\sup_{y\in\R_+}(f(\omega,t,y)-qy),\ \ (\omega,t,q)\in\Omega\times \T\times\R_+,
\end{equation}
we have for each $t\in\T$,
\begin{equation}
Y_t=\essinf_{q_\cdot\in \hcal} \big({\rm e}^{-\int_0^t q_s{\rm d}s}Y^{q_\cdot}_t\big),
\end{equation}
and there exists $q^*_\cdot:=f'(\cdot,Y_\cdot)\in\hcal$ such that $Y_\cdot=Y^{q^*}_\cdot,$
where the admissible control set is defined by
\begin{equation}
\hcal:=\left\{(q_t)_{t\in\T}:\
\begin{array}{l}
q_\cdot \ {\rm is\ an}\ (\F_t)\hbox{-}{\rm progressively\ measurable}\ \R_{+}\hbox{-}{\rm valued\ process}\vspace{0.1cm}\\
 {\rm such\ that}\ \ {\rm e}^{\int_0^T q_s{\rm d}s}\in L^{\bar p}(\R_+)\ \ {\rm and}
 \ \ (f^*(t,q_t))_{t\in\T}\in \lcal^p(\R_+)
\end{array}
\right\}
\end{equation}
and $(Y^{q_\cdot}_t,Z^{q_\cdot}_t)_{t\in\T}$ is the unique adapted solution in $\scal^{\tilde p}(\R_{++})\times\mcal^{\tilde p}(\R^{1\times d})$ of the following BSDE:
\begin{equation}
  Y^{q_\cdot}_t=\xi^{q_\cdot}+\int_t^T g^{q_\cdot}(s,Y^{q_\cdot}_s,Z^{q_\cdot}_s) {\rm d}s-\int_t^T Z^{q_\cdot}_s {\rm d}B_s, \ \ t\in\T
\end{equation}
with $\xi^{q_\cdot}:={\rm e}^{\int_0^T q_s{\rm d}s}\xi$ and for each $(\omega,t,y,z)\in\Omega\times\T\times\R_+\times\R^{1\times d}$,
\begin{equation}
g^{q_\cdot}(t,y,z):={\rm e}^{\int_0^t q_s{\rm d}s}\left[f^*(t,q_t)+\bar f(t,{\rm e}^{-\int_0^t q_s{\rm d}s}y\big)+\tilde f(t,{\rm e}^{-\int_0^t q_s{\rm d}s}y, {\rm e}^{-\int_0^t q_s{\rm d}s}z\big)\right].
\end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-26T19:34:09.913436+00:00","domain":"probability theory","id":"claim_738924f53504abbfefec598a479e27128a94be40adb90a6f7d6c12cb79d513fe","kind":"concept","schema_version":1,"statement":"[Lemma 14 of arXiv:2603.26936, 'Sharp Riemannian heat kernel estimates on the cut locus and the Parabolic Anderson model'] Suppose $W$ satisfies Dalang's condition $\alpha>{(d-2)}/{2}$ and $t\ge1$. Define a function $$k^{1}_L(s):=\sup_{x,x'\in M}\iint_{M^2}  [G^{[1]}_s(x,z)+1][G^{[1]}_s(x',z')+1]\bm{d}(z,z')^{2\alpha-d}m(dz)m(dz'),\quad s>0.$$
    We have $$k^1_L(s)\leq C_{\alpha,M}(1+s^{\frac{2\alpha-d}{2}}),$$
    for some positive constant $C_{\alpha,M}$ depending on $\alpha$ and $M$. Moreover,
    \begin{align}\mathcal{L}_1(t,x_0,x,x_0',x')\leq C_L [G^{[1]}_t(d(x_0,x))+1][G^{[1]}_t(d(x_0',x'))+1]\left(\int_0^t k^1_L(s)ds\right),\end{align}
    where $C_L$ is a positive constant depending on $M$. (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-26T20:58:53.191763+00:00","domain":"probability theory","id":"claim_738aa04d7302ac87b0e0f2e0db9f021692aa06d9bd2ac233cb93e510e6520aea","kind":"theorem","schema_version":1,"statement":"[Theorem 4 of arXiv:2606.31455, 'Discrete time-multidimensional renewal theory and applications'] Let $a:\mathbb{N}^d\to\mathbb{R}$.
Then $a$ is convolutionally invertible if and only if $a(0_d)\neq 0$.
Moreover, if $a(0_d)\neq 0$ and we define the normalized sequence

\begin{equation}
\widetilde a(k):=\frac{a(k)}{a(0_d)},\qquad k\in\mathbb{N}^d,
\end{equation}

then $\widetilde a(0_d)=1$ and the convolutional inverse of $a$ is given coefficientwise by

\begin{equation}
a^{(-1)}(k)
=\frac{1}{a(0_d)}\sum_{n=0}^{|k|_1}\big(\ez-\widetilde a\big)^{(n)}(k),
\qquad k\in\mathbb{N}^d.
\end{equation}

Equivalently,

\begin{equation}
a^{(-1)}(k)
=\frac{1}{a(0_d)}
\sum_{n=0}^{|k|_1}
(-1)^n
\binom{|k|_1+1}{n+1}\,
\widetilde a^{(n)}(k),
\qquad k\in\mathbb{N}^d.
\end{equation}","status":"unverified"}

