{"assumptions":[],"created_at":"2026-10-27T05:50:44.862564+00:00","domain":"probability theory","id":"claim_74ad7e4f638753d1800beb40128fece987f2abbfe6aba2ce031a5d45ef95c433","kind":"lemma","schema_version":1,"statement":"[Lemma 14 of arXiv:2607.16502, 'Asymptotic Behavior of Path Functionals for Vector-Valued Gaussian Processes at High Level'] Suppose that \( \bm{X}_{u, \tau}(t) \), \( t \in E \), \( u > 0 \), \( \tau \in Q_u \) satisfy~\ref{A1}--\,\ref{A3} and that \( \Gamma \) satisfies~\ref{F1}.
    Let \(I\dot\cup\Jtan\dot\cup\Jsl=\{1,\ldots,d\}\) be the
    quadratic-programming decomposition associated with \((\Sigma,\bm b)\),
    and use the normalization in \eqref{def hat u}, namely
    \[
      (\uu)_I=u\bm1_I,
      \qquad
      (\uu)_{\Jtan}=\bm1_{\Jtan},
      \qquad
      (\uu)_{\Jsl}=u^{-1}\bm1_{\Jsl}.
    \]
    Let \( \bm{W}(t) \), \(t \in E\), be a centered Gaussian random field with covariance
    matrix function \( K (t, s) \). For \(\bm x\in\R^d\), put
    \[
      \mathcal W_{\bm x}
      =
      \begin{pmatrix}
        \bm W_I-\bm d_I-\bm x_I\\
        -\bm x_{\Jtan}\\
        (\bb-\bm b)_{\Jsl}
      \end{pmatrix}.
    \]
    Assume moreover that \(\Gamma\) satisfies conditions~\ref{F2}--\ref{F3} for
    this shifted limiting random element \(\mathcal W_{\bm x}\). Then, as
    $u \to \infty$, we have
    \begin{equation*}
      \pk{\Gamma ( \uu ( \bm{X}_{u, \tau} - u \bm{b} ) ) > 0}
      \sim
      H_{\Gamma, \bm{W}, \bm{d}, \Sigma, \bm{b}} \,
      u^{-|I|} \, 
      \varphi_{\Sigma_{u, \tau}} ( u \bb ),
    \end{equation*}
    where
    \begin{equation*}
      H_{\Gamma, \bm{W}, \bm{d}, \Sigma, \bm{b}}
      \coloneqq
      \int_{\R^d}
      \exp \left(
      \bm{x}_I^\top \bm{w}_I 
      - \frac{1}{2} \, \bm{x}_J^\top ( \Sigma^{-1} )_{J J} \, \bm{x}_J
      \right)
      \pk{
        \Gamma 
        \begin{pmatrix}
          \bm{W}_I - \bm{d}_I - \bm{x}_I \\
          -\bm{x}_{\Jtan}                                  \\
          ( \bb - \bm{b} )_{\Jsl}
        \end{pmatrix}
        > 0
      }
      \, d \bm{x}
    \end{equation*}
    uniformly in $\tau \in Q_u$.","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-26T19:32:38.635524+00:00","domain":"probability theory","id":"claim_74b05cb9b789108e94e41645ad7f0746debf486c0605200592aab192d0019a87","kind":"concept","schema_version":1,"statement":"[Theorem 8 of arXiv:2506.17109, 'Limit theorems under nonlinear expectations dominated by sublinear expectations'] Let a nonlinear expectation $\mathbb{\tilde{E}}[\cdot]$ be
dominated by a sublinear expectation $\mathbb{\hat{E}}[\cdot]$ on
$(\Omega,\mathcal{H})$, and let $\{(X_{n,i},Y_{n,i}):n\in \mathbb{N}$,
$i=1$,$\ldots$,$n\}$ be a sequence of $2d$-dimensional random vectors such
that $(X_{n,i},Y_{n,i})\overset{d}{=}(X_{n,1},Y_{n,1})$ and $(X_{n,i}
,Y_{n,i})$ is independent of $(X_{n,1}$,$\ldots$,$X_{n,i-1}$,$Y_{n,1}$
,$\ldots$,$Y_{n,i-1})$ for $n\in \mathbb{N}$, $i=2$,$\ldots$,$n$ under
$\mathbb{\tilde{E}}[\cdot]$ and $\mathbb{\hat{E}}[\cdot]$ respectively.
Suppose that
\begin{equation}
\mathbb{\hat{E}}[X_{n,1}]=\mathbb{\hat{E}}[-X_{n,1}]=0\text{ for }
n\in \mathbb{N},\text{ }\lim_{N\rightarrow \infty}\sup_{n\geq1}\mathbb{\hat{E}
}\left[  (n|X_{n,1}|^{2}-N)^{+}+(n|Y_{n,1}|-N)^{+}\right]  =0, 
\end{equation}
and for each given $(A,p)\in \mathbb{S}_{d}\times \mathbb{R}^{d}$,
\begin{equation}
\tilde{G}(A,p):=\lim_{n\rightarrow \infty}n\mathbb{\tilde{E}}\left[  \frac
{1}{2}\langle AX_{n,1},X_{n,1}\rangle+\langle p,Y_{n,1}\rangle \right]  \text{
exists,} 
\end{equation}
where $\mathbb{S}_{d}$ denotes the space of $d\times d$ symmetric matrices.
Then for each $\phi \in C_{b.Lip}(\mathbb{R}^{2d})$, we have
\begin{equation}
\lim_{n\rightarrow \infty}\mathbb{\tilde{E}}\left[  \phi \left(  \sum_{i=1}
^{n}X_{n,i},\sum_{i=1}^{n}Y_{n,i}\right)  \right]  =u^{\phi}(1,0,0),

\end{equation}
where $u^{\phi}$ is the unique viscosity solution of the following PDE:
\begin{equation}
\partial_{t}u-\tilde{G}(D_{x}^{2}u,D_{y}u)=0\text{, }u(0,x,y)=\phi(x,y).

\end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

