{"assumptions":[],"created_at":"2026-10-27T19:06:39.309100+00:00","domain":"probability theory","id":"claim_75bda6e999fe4d7635b931a294aee5e68168395ea71677109b02f4531126eb5a","kind":"concept","schema_version":1,"statement":"[Lemma lem:SSL_flow of arXiv:2607.13748, 'Load Balancing with Individually Heterogeneous Servers'] Recall $\mu_{\min}<\mu_{\max}$ by Assumption~(asm:arrival_service_rates of the paper). For $\mathbf{x}=(x_1,x_2)\in\Omega$, let $\tau(\mathbf{x})\in[0,\infty]$ be the
hitting time of the reflecting boundary $\{x_1=0\}$ by the deterministic flow generated by the first-order part of $\mathcal{G}_{\mathrm{SSL}}$,
\begin{equation}

    \tau(\mathbf{x}):=\inf\Big\{s\ge0:\ -\frac{\beta}{\mu_{\max}}
    +\Big(x_1+\frac{\beta}{\mu_{\max}}\Big)e^{-\mu_{\max}s}
    +\frac{\mu_{\min}x_2}{\mu_{\max}-\mu_{\min}}
     \big(e^{-\mu_{\min}s}-e^{-\mu_{\max}s}\big)=0\Big\}
\end{equation}
Consider the following system of nonlinear equations
\begin{align}
    &-\frac{\beta}{\mu_{\max}}
    +\Big(x_1+\frac{\beta}{\mu_{\max}}\Big)e^{-\mu_{\max}\tau}
    +\frac{\mu_{\min}x_2}{\mu_{\max}-\mu_{\min}}
      \big(e^{-\mu_{\min}\tau}-e^{-\mu_{\max}\tau}\big)=0,\\
    &x_2e^{-\mu_{\min}\tau}=\kappa.

\end{align}

For any $\kappa\geq \beta/\mu_{\min}$ and $x_1\leq 0$, (equation eq:SSL_Gamma1 of the paper) and (equation eq:SSL_Gamma2 of the paper) has a unique solution, which we
denote $(x_2^\ast(x_1,\kappa),\tau)\in[\kappa,\infty) \times [0, \infty)$. Hence, the set 
\[\Gamma_\kappa = \{\mathbf{x}\in \Omega: x_2 = x_2^*(x_1, \kappa)\}\]
is well-defined, and we write $\mathbf{x}\ge\Gamma_\kappa$ when $x_2\ge x_2^\ast(x_1,\kappa)$, and $\mathbf{x}\le\Gamma_\kappa$ similarly. In addition, 
\begin{enumerate}
    \item[i)] for $\kappa\ge\beta/\mu_{\min}$, $\Gamma_\kappa$ exists and is unique, and $\Gamma_{\kappa'}>\Gamma_\kappa$ whenever $\kappa'>\kappa$;
    \item[ii)] $\tau(\mathbf{x})<\infty$ if and only if  $\mathbf{x}\ge\Gamma_{\beta/\mu_{\min}}$, in which case $x_2e^{-\mu_{\min}\tau(\mathbf{x})}\ge\beta/\mu_{\min}$;
    \item[iii)] for $\kappa>\beta/\mu_{\min}$, $\tau$ is differentiable on $\{\mathbf{x}\ge\Gamma_\kappa\}$ with
    \begin{align}
        \tau_1(\mathbf{x}) &= \frac{\partial \tau(\mathbf{x})}{\partial x_1}
        =-\frac{e^{-\mu_{\max}\tau(\mathbf{x})}}
               {\mu_{\min}x_2e^{-\mu_{\min}\tau(\mathbf{x})}-\beta}\le0,\\
        \tau_2(\mathbf{x})&= \frac{\partial \tau(\mathbf{x})}{\partial x_2}=\frac{\mu_{\min}}{\mu_{\min}-\mu_{\max}}\,
         \frac{e^{-\mu_{\min}\tau(\mathbf{x})}-e^{-\mu_{\max}\tau(\mathbf{x})}}
              {\mu_{\min}x_2e^{-\mu_{\min}\tau(\mathbf{x})}-\beta}\le0,
    \end{align}
    where $\tau_1$ is the left derivative at $x_1=0$.
\end{enumerate} (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

