			\end{equation*}
			\item For every fixed constant $s\geqslant 1$, there exists a positive constant $C(\rho)$ such that for every $\ell\in\mathbb{Z}_{+}$, the following estimate holds:
			\begin{equation*}
				\sum_{x\in\mathbb{Z}}\sum_{|y-x|\leqslant s}\left({\mathsf{D}}_1\overline{g}_\lambda(x,y)\right)^2
