{"assumptions":[],"created_at":"2026-10-27T12:59:58.432540+00:00","domain":"probability theory","id":"claim_767f410b2da8c77416ecab359217cc94cc5cc805bd11ef859efbff55f0457a14","kind":"definition","schema_version":1,"statement":"[Definition def:IVGFFwithpotentialV of arXiv:2604.24743, 'The impact of disorder and non-convex interactions on delocalisation of height functions'] Given an integer $L \in \ensuremath{\mathbb{N}}$ and an inverse temperature $\beta \geq 0$, we define the integer-valued height function with potential $V$ to be the probability distribution on the set $\Omega_{\Lambda_L}^\ensuremath{\mathbb{Z}}$ given by the identity

\begin{equation} 
    \mu_{\Lambda_L , \beta}^{\ensuremath{\mathbb{Z}}-V} (\left\{ \varphi \right\}) := \frac{1}{Z_{\Lambda_L,\beta}^{\ensuremath{\mathbb{Z}}-V}} \exp \left( - \sum_{x \sim y}  V \left( \frac{ \varphi(x) - \varphi(y)}{\sqrt{\beta}} \right)\right).
\end{equation}
We denote by $\mathrm{Var}_{L , \beta}^{\ensuremath{\mathbb{Z}}-V}$ the variance with respect to the measure $\mu_{L , \beta}^{\ensuremath{\mathbb{Z}}-V}$.","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T14:18:13.203534+00:00","domain":"probability theory","id":"claim_768111d2afc2a5306d249efc89248becb2d608e38bf66f986bb153d31c17e0ab","kind":"theorem","schema_version":1,"statement":"[Prop valoriHgamma of arXiv:2506.08202, 'Stochastic dissipative systems in Banach spaces driven by L\'evy noise'] Let $\delta\geq 0$. Assume that $\nu(H\setminus H_\delta)=0$, $m =0$,   and  
\begin{equation}
\int_H{\left|z\right|}_\delta^2\nu(dz) = \int_{H_{\delta}}{\left|z\right|}_\delta^2\nu(dz) <+\infty. 
\end{equation}
Then the following statements hold.
\begin{enumerate}
\item $\{L(t)\}_{t\geq 0}$ is a Lévy process on $H_\delta$.
\item $\{L_A(t)\}$ is a mean square continuous $H_{\gamma}$-valued stochastic process, for every $\gamma<1/2+\delta$,  namely for every $t_0\geq 0$ we have
\begin{equation}
\lim_{t\rightarrow t_0}\mathbb{E}\left[{\left\|L_A(t)-L_A(t_0)\right\|}_\gamma^2\right]=0,
\end{equation}
in the case $t_0=0$ we consider only the right limit in (equation Mean-cont of the paper).
\end{enumerate}","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-28T02:39:12.216141+00:00","domain":"probability theory","id":"claim_7681dec481ae457025db1fbeafbdaa841eb0279a7bcd9550cce461f7be9f8f75","kind":"concept","schema_version":1,"statement":"[Corollary cor: KR_crit of arXiv:2412.07690, 'A law of large numbers concerning the distribution of critical points of random Fourier se'] Let  $\EuScript{V}\subset{\mathbb R}^m$  an open set.  Suppose that  $\Phi: \EuScript{V}\to {\mathbb R}$ a Gaussian random function that is $\mathrm{a.s.}$ $C^2$ and such that  the Gaussian vector $\nabla \Phi({\boldsymbol{v}})$ is nondegenerate  for any ${\boldsymbol{v}}\in \EuScript{V}$. We denote by $p_{\nabla \Phi(v)}$ is probability \emph{density}.  The following hold.

  \begin{enumerate}

  \item  The random function  $\Phi$ is $\mathrm{a.s.}$ Morse

  \item We set
  \begin{equation}
  \mathfrak{C}[-,\Phi]:=\sum_{\nabla F({\boldsymbol{v}})=0}\delta_v
  \end{equation}
  Then $\mathfrak{C}[-,\Phi]$ is a random locally finite measure on $\mathscr{V}$  in the sense of [DaVere2] or [Kalle_RM].   For any  nonnegative measurable function ${\varphi}:\mathscr{V}\to [0,\infty)$ we set
  \[
  \mathfrak{C}[{\varphi},\phi]=\int {\varphi}(v)\mathfrak{C}[dv,\Phi]=\sum_{\nabla \Phi(v)=0}{\varphi}(v).
  \]
  \item  For any box $B\subset \mathscr{V}$,   the function $\Phi$ $\mathrm{a.s.}$ has no critical points on $\partial B$ and
  \begin{equation}
  {\mathbb E}\big[\, \mathfrak{C}^\Phi[\boldsymbol{I}_B{\varphi}]\,\big]=\int_B{\mathbb E}\big[\, \vert\det \Hess_\Phi({\boldsymbol{v}})\vert \, \,\big\vert\,\nabla \Phi({\boldsymbol{v}})=0\,\big] p_{\nabla \Phi(v)}(0) {\varphi}({\boldsymbol{v}})d{\boldsymbol{v}}.
\end{equation}
\end{enumerate}
The quantity 
\begin{equation}
\rho_\Phi:={\mathbb E}\big[\, \vert\det \Hess_\Phi({\boldsymbol{v}})\vert \, \,\big\vert\,\nabla \Phi({\boldsymbol{v}})=0\,\big] p_{\nabla F(v)}(0)
\end{equation} 
is called the  Kac-Rice (or KR) density of $\Phi$.
 \nobreak\hfill\penalty250 \hbox{}\nobreak\hfill$\rlap{$\sqcap$}\sqcup$\vskip\aline (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T23:05:09.626671+00:00","domain":"probability theory","id":"claim_76833c21799ac2b956773e745568b911e3bf026c05a6024dcafcbf760e8e6e7c","kind":"concept","schema_version":1,"statement":"[Theorem thm:continuous ergodic  of arXiv:2411.03512, 'Ergodicity and Mixing of Sublinear Expectation System and Applications'] Let $(\Omega,f)$ be a topological dynamical system. Then the following statements are equivalent:
