{"assumptions":[],"created_at":"2026-10-27T05:50:44.876105+00:00","domain":"probability theory","id":"claim_76cf2d45ac5a92e935a3d52ddc4f7e2c0257d2d121aace64008a13f7486e7cf2","kind":"theorem","schema_version":1,"statement":"[Theorem 56 (Second-order singular group-dual transfer) of arXiv:2607.16724, 'Algebraic Transfer for Operator-Valued Gaussian Chaoses: Oriented Schatten Profiles and Si'] Assume \eqref{eq:group-growth}, let
$D/4<\sigma\le D/2$, $c_x=\langle x\rangle^{-\sigma}$, and fix
$1\le r<\infty$.  With $\beta=D-2\sigma$, suppose
\begin{equation}

 a>\beta,\qquad b>\beta,\qquad
 a+b>\beta+\frac Dr.
\end{equation}
Then $T_{2,N}^{a,b}(c)$ converges, as $N\to\infty$, to a common random
operator $T_2^{a,b}(c)$ in
$L^p(\Omega;\Sch_r(\ell^2(\Gamma)))$ for every $1\le p<\infty$ and almost
surely in $\Sch_r$.  Define
\begin{equation}

 \eta_*:=
 \min\left\{
  \frac{4\sigma-D}{2},\,
  a-\beta,\,
  b-\beta,\,
  a+b-\beta-\frac Dr
 \right\}>0.
\end{equation}
For every $0<\eta<\eta_*$ and $1\le p<\infty$,
\begin{equation}

 \norm{T_{2,N}^{a,b}(c)-T_2^{a,b}(c)}
      _{L^p(\Omega;\Sch_r)}
 \le C_{\Gamma,D,\sigma,a,b,r,\eta}(p+r)N^{-\eta}.
\end{equation}
For a common realization and every $t\ge1$,
\begin{align}

 \Prob\!\left(
  \norm{T_{2,N}^{a,b}(c)-T_2^{a,b}(c)}_{\Sch_r}
  >\mathrm e\,C_{\Gamma,D,\sigma,a,b,r,\eta}
    (t+r)N^{-\eta}
 \right)
 \le\mathrm e^{-t}.
\end{align}
Moreover, for every $0<\eta<\eta_*$,
\begin{equation}

 \norm{T_{2,N}^{a,b}(c)-T_2^{a,b}(c)}_{\Sch_r}
 =O_\omega(N^{-\eta})
 \qquad\text{almost surely}.
\end{equation}","status":"unverified"}

