{"assumptions":[],"created_at":"2026-10-26T19:36:04.993644+00:00","domain":"probability theory","id":"claim_76e2ceb9b0eb420fa364eb19b6c516efbfbbf837c5ce45290340e07b2fbce425","kind":"definition","schema_version":1,"statement":"[Definition 3 of arXiv:2604.01685, 'Probability with Measure\footnote{Lecture notes. University of Ljubljana.}'] Let $(\Omega,\FF)$ be a measurable space and $\mu:\FF\to [0,\infty]$. 

	$\mu$ is a measure on $(\Omega,\FF)$ (also, on $\FF$)\footnote{There will never be any ambiguity as to which of the two we intend, since an ordered pair cannot at the same time be a $\sigma$-algebra (on any set).} \deff $\mu(\emptyset)=0$ and $\mu$ is countably additive: $\mu(\cup_{n\in \mathbb{N}}A_n)=\sum_{n\in \mathbb{N}}\mu(A_n)$ whenever $(A_n)_{n\in \mathbb{N}}$ is a sequence in $\FF$ of pairwise disjoint sets. 




	A measure $\mu$ on $(\Omega,\FF)$: 
	\begin{itemize}
	\item 
	is finite \deff $\mu(\Omega)<\infty$;
	\item  	 is a probability measure (also, a probability (law)) \deff $\mu(\Omega)=1$;
	\item is $\sigma$-finite \deff there is a sequence $(A_n)_{n\in \mathbb{N}}$ in $\FF$ with $\Omega= \cup_{m\in \mathbb{N}}A_m$ and  $\mu(A_n)<\infty$ for all $n\in \mathbb{N}$; 
	   \item 
	   has $\mu(\Omega)$ for its (total) mass. 
	   \end{itemize}

	$(\Omega,\FF,\mu)$ is a measure space \deff $\mu$ is a measure on $(\Omega,\FF)$.

	If $(\Omega,\FF,\mu)$ is a measure space, then for  $A\in \FF$: 
	\begin{itemize}
	\item $A$ is $\mu$-negligible \deff $\mu(A)=0$; 
	\item $A$ is $\mu$-trivial \deff $A$ or $\Omega\backslash A$ is $\mu$-negligible;
	\item  $A$ carries $\mu$ \deff $\Omega\backslash A$ is $\mu$-negligible. 
	\end{itemize}
	If in addition one has a property (predicate) $P(\omega)$ in $\omega\in A$, then: 
	\begin{itemize}
	\item $P(\omega)$ holds $\mu$-almost everywhere (abbreviated to $\mu$-a.e. or a.e.-$\mu$) in $\omega\in A$ \deff $A_{\neg P}:=\{\omega\in A:\neg P(\omega)\}\in \FF$ and $\mu(A_{\neg P})=0$; 
	\item $P(\omega)$ holds $\mu$-almost surely (abbreviated $\mu$-a.s. or a.s.-$\mu$) in $\omega\in A$ \deff the preceding and in addition $\mu$ is a probability measure. 
	\end{itemize}
	When $A=\Omega$, then:  ``$\in A$'' can be omitted in the preceding (i.e. one can just say ``for $\mu$-a.e. $\omega$'' in lieu of ``for $\mu$-a.e. $\omega\in \Omega$'', etc.). 

	Given a map $f:U\to W$ and a property (predicate) $P(v)$ in $v\in W$ we often write: 
	\begin{itemize}
	\item $\{P(f)\}:=\{u\in U:P(f(u))\text{ is true}\}$;
	\item ``$P(f)$ holds'' to mean ``$P(f(u))$ holds true for all $u\in U$'', 
	\end{itemize}
	and correspondingly, when $\mu$ is a measure on a $\sigma$-field of $U$, 
	\begin{itemize}
	\item ``$P(f)$ holds true $\mu$-a.e.'' to mean ``$P(f(u))$ holds true for $\mu$-a.e. $u$'' etc. 
	\end{itemize} (for instance, if $W=\mathbb{R}$, $f\geq 2$ a.e.-$\mu$ means $f(u)\geq 2$ for $\mu$-a.e. $u$, while $\{f\geq 2\}=\{u\in U:f(u)\geq 2\}$). Similarly, if, in addition, $f':U\to W'$ and we have a property $P(w,w')$ in $w\in W$ and $w'\in W'$, then we interpret 
	\begin{itemize}
	\item $\{P(f,f')\}$ and ``$P(f,f')$ holds true (a.e.-$\mu$)''  by considering $(f,f'):U\to W\times W'$;
	\end{itemize} likewise for any family $f_\lambda:U\to W_\lambda$, $\lambda\in \Lambda$. 	Besides, if $E(w)$ is some expression (term) involving $w\in W$ and if $f$ is as above, then
	\begin{itemize}
	 \item $E(f)$ means the map $(U\ni u\mapsto E(f(u)))$; 
	 \end{itemize}
	 if $E(w,w')$ is some expression involving $w\in W$ and $w'\in W'$ and $f,f'$ are as above, then considering again $(f,f'):U\to W\times W'$,
	 \begin{itemize}
	  \item $E(f,f')$ means the map $(U\ni u\mapsto E(f(u),f'(u)))$; 
	  \end{itemize}
	  analogously for any family $f_\lambda:U\to W_\lambda$, $\lambda\in \Lambda$.","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T10:55:56.995164+00:00","domain":"probability theory","id":"claim_76e33206a1b085800182193c8547fac5d41f9571a9b0bda9e9b095eea32ecb56","kind":"lemma","schema_version":1,"statement":"[Lemma 4 (Analyticity and contour representation) of arXiv:2609.02784, 'Maximizing the fundamental Laplace--Neumann \\ eigenvalue on quadrilaterals'] Let $U \subseteq \mathbb R^4$ be an open set on which the following three conditions hold:
\begin{enumerate}
\item[(i)] $c_i(\p) > 0$ for $i = 1, \ldots, 4$;
\item[(ii)] $M(\p) \succ 0$;
\item[(iii)] the two smallest generalized eigenvalues $\lambda_1(\p) \le \lambda_2(\p)$ of the pencil $(K(\p), M(\p))$ lie in the open interval $\left(\tfrac{\pi^2}{2}, \tfrac{3\pi^2}{2}\right)$, and the remaining three exceed $\tfrac{3\pi^2}{2}$.
\end{enumerate}
Then the cluster $\{\lambda_1(\p), \lambda_2(\p)\}$ is isolated from the rest of the spectrum, and its elementary symmetric functions $\Sigma(\p) := \lambda_1(\p) + \lambda_2(\p)$ and $\Pi(\p) := \lambda_1(\p)\,\lambda_2(\p)$ are real-analytic on $U$, given by the contour integrals over $\Gamma := \{w \in \mathbb C \colon |w - \pi^2| = \tfrac{\pi^2}{2}\}$,
\begin{align*}
  \Sigma(\p) &\;=\; -\tr\!\biggl(\frac{1}{2\pi i}\!\oint_{\Gamma}\!
                       w\,\bigl(K(\p) - w M(\p)\bigr)^{-1} M(\p)\,dw\biggr), \\
  \Pi(\p) &\;=\; \frac{\Sigma(\p)^2}{2} + \frac{1}{2}\,\tr\!\biggl(\frac{1}{2\pi i}\!\oint_{\Gamma}\!
                       w^2\,\bigl(K(\p) - w M(\p)\bigr)^{-1} M(\p)\,dw\biggr).
\end{align*}
Consequently
\begin{equation}
  f_2(\p) \;=\; \frac{1}{2\,|Q_\p|}\!\left(\frac{1}{\lambda_1(\p)}
                                          + \frac{1}{\lambda_2(\p)}\right)
            \;=\; \frac{\Sigma(\p)}{2\,|Q_\p|\,\Pi(\p)}
\end{equation}
is real-analytic on $U$, with $|Q_\p| = 1 - a^2 - d^2 > 0$ and $\Pi(\p) > \tfrac{\pi^4}{4} > 0$.","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T19:51:00.244020+00:00","domain":"probability theory","id":"claim_76e3d3f639ca63161e5882c47d7b59a7efe1adfa1e1910d7055581c8f7f86ecf","kind":"concept","schema_version":1,"statement":"[Thm restate of limiting profile of arXiv:2604.23890, 'The Cutoff Profile for Random Transpositions on Repeated Cards in the Full Range of Parame'] Let $c\in\mathbb{R}$ be an absolute constant. Let $(n_N)_{N\ge 1},(m_N)_{N\ge 1}$ and $(l_N)_{N\ge 1}$ be sequences of positive integers, such that 
\begin{enumerate}
\item $m_N,l_N\ge 2$ for all $N\ge 1$, and $\lim_{N\rightarrow\infty}l_N=\infty$.
\item $n_N=m_Nl_N$ for all $N\ge 1$.
\end{enumerate}
For all $N\ge 1$, let $t_N=\frac{n_N}{2}(\log n_N-\frac 12\log l_N+c)$. Let $\sim_{l_N}\backslash P_{n_N}^{*t_N}$ be defined as in (defi: Pnk and its convolution of the paper), and let $\sim_{l_N}\backslash U_{\mathfrak{S}_{n_N}}$ be defined as in (defi: quotient of space of the paper). Then, we have
$$\lim_{N\rightarrow\infty}d_{TV}(\sim_{l_N}\backslash P_{n_N}^{*t_N},\sim_{l_N}\backslash U_{\mathfrak{S}_{n_N}})=2\Phi\left(\frac{\exp(-c)}{2}\right)-1$$
when $\lim_{N\rightarrow\infty}m_N=\infty$, and 
$$\lim_{N\rightarrow\infty}d_{TV}(\sim_{l_N}\backslash P_{n_N}^{*t_N},\sim_{l_N}\backslash U_{\mathfrak{S}_{n_N}})=2\Phi\left(\sqrt{1-\frac 1m}\frac{\exp(-c)}{2}\right)-1$$
when $m_N=m\ge 2$ is fixed. (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T08:12:13.583681+00:00","domain":"probability theory","id":"claim_76e751211b0c2fc25045178daee4e4bf6174fab389a4c7ec693897eccf4b5b3c","kind":"lemma","schema_version":1,"statement":"[Lemma 32 (Concentration of the Stein witness map) of arXiv:2608.28827, 'Quantitative Target Convergence and Uniform-in-Time\\ Propagation of Chaos for Langevin-Re'] Under Assumptions~\ref{ass:core-target}, \ref{ass:ksd-kernel} and \ref{ass:concentration}, there are constants $c_{\mathrm{KSD}}>0$ and $1\le C_{\mathrm{KSD}}<\infty$ such that
\begin{equation}
    \int\exp\left(
      c_{\mathrm{KSD}}\sqrt N\,
      \KSD_\pi(\mu_X^N,\mu_t)
    \right)\,d\mu_t^{\otimes N}(X)
    \le C_{\mathrm{KSD}}
\end{equation}
uniformly in $N$ and $t$.","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T23:05:09.624872+00:00","domain":"probability theory","id":"claim_76e8ea2b7400554faa17c5a7d50066b1ef8e4959016db087d81356ec1c55f36e","kind":"lemma","schema_version":1,"statement":"[Lemma Suf cond for admissible 1 of arXiv:2411.03512, 'Ergodicity and Mixing of Sublinear Expectation System and Applications'] Let $g: \mathbb N\to \mathbb R_+$ be a given function. If there exists $\delta>0$ such that
     \begin{equation}
         \liminf_{k\to \infty}\frac{g(k+1)-g(k)}{(\ln k)^{1+\delta}}>0,
     \end{equation}
     then $\{g(k)\}_{k\geq 1}$ is $(\gamma,\delta)$-admissible for any $0<\gamma<1$. In particular, if there exists $\beta>0$ such that
     \begin{equation}
         \liminf_{k\to \infty}\frac{g(k+1)-g(k)}{k^{\beta}}>0,
     \end{equation}
     then $\{g(k)\}_{k\geq 1}$ is $(\gamma,\delta)$-admissible for any $0<\gamma<1$ and $\delta>0$.","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T21:35:04.100706+00:00","domain":"probability theory","id":"claim_76eb6cd728bb2b508e89902166ac5afae5726186bd422dc0c694bcb5a5ba3afb","kind":"theorem","schema_version":1,"statement":"[Theorem thm:marked-shell of arXiv:2608.29403, 'Kac's Walk on Rotation Matrices Mixes in $\boldsymbol{\Theta(n^2)}$ Steps:\\ A Proof Disco'] For every fixed $L$ there are numerical
$A_{\rm sh},C,r$ such that
\[
 \|\mathcal C_k\|_{L^2(\Omega;\mathfrak{so}(n))}
 \le C\sqrt n\,c^{(k+1)/2}(k+1)^rA_{\rm sh}^k,
 \qquad 1\le k\le L\log n.
\tag{3.5.6}
