{"assumptions":[],"created_at":"2026-10-26T19:16:49.560136+00:00","domain":"probability theory","id":"claim_781f572dc1052fa6bb434a1a06947da3401a11363804637af45d28555e623bfc","kind":"theorem","schema_version":1,"statement":"[Cor 48 of arXiv:2509.06869, 'Infinite Interacting Brownian Motions and EVI Gradient Flows'] Suppose~\ref{ass:CE}, ~\ref{ass:ConditionalClos} and Assumption~\ref{a:AP}.  Then, the following hold: 
\begin{enumerate}[{\rm (a)}]
\item  The space~$(\dom{\Ent_\QP}, {\mssW}_{2, \mssd_\U})$ is an extended geodesic metric space: for every pair $\nu, \sigma \in \dom{\Ent_\QP}$ with ${\mssW}_{2, \mssd_\U}(\nu, \sigma)<\infty$, there exists a constant speed ${\mssW}_{2, \mssd_\U}$-geodesic $(\nu_t)_{t \in [0,1]}$ connecting $\nu$ and $\sigma$:
\begin{align} 
\nu_0=\nu \cquad \nu_1=\sigma \cquad {\mssW}_{2, \mssd_\U}(\nu_t, \nu_s) =|t-s|{\mssW}_{2, \mssd_\U}(\nu, \sigma) \cquad s, t \in [0, 1]\fstop
\end{align}

\item  $(${\bf $K$-geodesical convexity}$)$ The entropy~$\Ent_\QP$ is $K$-geodesically convex along every constant speed ${\mssW}_{2, \mssd_\U}$-geodesic $(\nu_t)_{t \in [0,1]}$:

\begin{align*}
\Ent_\QP(\nu_t) \le (1-t)\Ent_{\QP}(\nu_0) + t \Ent_{\QP}(\nu_1) -\frac{K}{2}t(1-t)\mssW_{2, \mssd_{\U}}(\nu_0, \nu_1)\cquad t \in [0,1] \fstop
\end{align*}

\item  $(${\bf $\RCD$ property}$)$  The extended metric measure space $(\U, \tau_\mrmv, \mssd_\U, \QP)$ is an $\RCD(K,\infty)$ space. 

\item   The descendent ${\mssW}_{2, \mssd_\U}$-slope of $\Ent_\QP$ coincides with the Fisher information:
\begin{align*}
|{\sf D}_{{\mssW}_{2, \mssd_\U}}^- \Ent_\QP(\nu)|^2 = 4{\sf F}_\QP(\nu) \cquad \nu \in \dom{\Fis_\QP}\ ;
\end{align*}

\item    $(${\bf Distorted Brunn--Minkowski inequality}$)$ Let $A_0, A_1$ be Borel sets with $\QP(A_0)\QP(A_1)>0$ and define the $t$-barycentre $(0 \le t \le 1)$ as 
$$[A_0, A_1]_t:=\{\eta \in \U: \eta=\gamma_t,\ \gamma \in {\rm Geo}(\U, \mssd_\U),\ \gamma_0 \in A_0,\ \gamma_1 \in A_1\} \fstop$$
Define $\nu_0:=\frac{\1_{A_0}}{\QP(A_0)} \cdot \mu$ and $\nu_1:=\frac{\1_{A_1}}{\QP(A_1)} \cdot \mu$. If $\mssW_{2, \mssd_{\U}}(\nu_0, \nu_1)<\infty$, 
\begin{align*}
\log \frac{1}{\mu\bigl([A_0, A_1]_t \bigr)} \le (1-t)	\log \frac{1}{\mu(A_0)} + t \log \frac{1}{\mu(A_1)} - \frac{K}{2}(1-t)t\mssW_{2, \mssd_\U}(\nu_0, \nu_1) \fstop
\end{align*}
\item    $(${\bf HWI inequality}$)$ For~$\nu_0 \in \dom{\Ent_\QP}, \nu_1 \in \mcP(\U)$ with  $\mssW_{2, \mssd_\U}(\nu_0, \nu_1)<\infty$, 
$$\Ent_{\QP}(\nu_0) \le \Ent_{\QP}(\nu_1)+2\mssW_{2, \mssd_{\U}}(\nu_0, \nu_1)\Fis_{\QP}(\nu_0)^{1/2} -\frac{K}{2}\mssW_{2, \mssd_{\U}}(\nu_0, \nu_1)^2 \fstop$$

\end{enumerate}","status":"unverified"}

