  &\mathbb{E}\bigl[|\eth_s X(t)|\bigr]\asymp s^{\bar{h}(t)-1}
  \text{ as }s\to0,\;\text{uniformly in }t,\tag{C-iii}\\
  &\bar{h}(t)\text{ is not constant on any interval.}\tag{C-iv}
\end{align}
Then $D(h,\omega)=\bar D(h)$ a.s.\ for all $h\ge0$. (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-26T20:54:34.579707+00:00","domain":"probability theory","id":"claim_788c19d52f782c840fe6fda9efbb659572408a2fff6bb9e41131cd9d880c1163","kind":"theorem","schema_version":1,"statement":"[Proposition 23 of arXiv:2606.14876, 'High-Order Talagrand and Eldan--Gross Inequalities via Besov-Type Variance Functionals'] For all $k\in \Nbb$ and $f\in \Sob^k(\Rbb^n,\gamma_n)$,
