\end{align*}","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T21:56:36.581096+00:00","domain":"probability theory","id":"claim_790b42c83c8cd8d3ed8f15f49522bc29d46c9ee2bd357289094b3416e9445a01","kind":"lemma","schema_version":1,"statement":"[Lemma fromulationcingty of arXiv:2608.30443, 'On smooth holosphere solutions to compressible Euler equation'] Let $\mathcal G$ be given by (equation fialfrmaulg of the paper) and consider the decomposition 
\begin{equation}

\left|\begin{array}{l}
\mathcal G=\sum_{k=0}^{K-1}g_k u^k+r_{\mathcal G},\\
\Theta=\sum_{k={0}}^{K-1}\theta_k u^k+r_\Theta,
\end{array}\right.
\end{equation}
where
\begin{equation}

\left|\begin{array}{l}
\theta_k=(-1)^kw_{\gamma-1,\nu_b+1}(k) S_k, \ \ 0\le k\le K-1,\\
S_k=\frac{\gamma}{a(\gamma-2)}\sum_{j=0}^k\frac{(-1)^jg_j}{(j+\nu_b+2)w_{\gamma,\nu_b}(j)},
\end{array}\right.
\end{equation}
then the unique solution to the fixed point problem
\begin{equation}

r_\Theta=(-1)^{K-1}S_{K-1}M_0(u)-\mathcal T(r_\mathcal G).
\end{equation}
generates the unique solution $\Theta$ to (equation thetaeqaiotjoihs of the paper) which satisfies:
\begin{equation}

\forall k\ge 0, \ \ \mathop{\rm lim}_{u\downarrow 0} \frac{\Theta^{(k)}(u)}{k!}=\theta_k
\end{equation}
where $(\theta_k)_{k\ge 0}$ is computed by induction from (equation vneineionvioenvionoe of the paper).","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T08:44:39.712072+00:00","domain":"probability theory","id":"claim_790c4992e2fb823b39c0288cbe8694bff2cf034b94329c668e955728f0f4bf7a","kind":"concept","schema_version":1,"statement":"[Proposition 3 of arXiv:2608.29736, '2608.29736'] Let $(M^n,\omega)$ be a compact K\"ahler manifold of complex
 dimension $n\geq 2$. Let $\chi$ be another K\"ahler form. Suppose that the $J$-semistable condition~\eqref{topintegralnonnegative}--~\eqref{$J$-semistablecondition} holds.
Then for any modified nef class $\beta$, we have \begin{equation}
    \int_M F_{n-1}(\chi)\wedge\beta \geq c\int_M \omega^{n-1}\wedge \beta,
    \end{equation}
    where \begin{equation}
   c= \frac{2n\displaystyle\int_M\Big(\chi^n-n\chi^{n-1}\wedge\omega\Big)+\int_M \omega^n}{8n^2\displaystyle\int_M\chi\wedge\omega^{n-1}}.\end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-26T19:36:04.990216+00:00","domain":"probability theory","id":"claim_790d8a752bf25d9c765875e9d195dfefcfc733ee6664c86dfd4f6f52d29b73af","kind":"concept","schema_version":1,"statement":"[Theorem 11 of arXiv:2604.00882, 'On some extensions of generalized counting processes'] The probability generating function $
	\tilde {G}_\nu(u, t) = \sum_{k=0}^{\infty} u^k \tilde{p}_k^\nu(t)$, $|u| \leq 1$, solves the following fractional differential equation
	\begin{equation}
		\frac{\partial^{2\nu} \tilde G_\nu(u, t)}{\partial t^{2\nu}} + 2\lambda \frac{\partial^\nu \tilde G_\nu(u, t)}{\partial t^\nu} = -\sum_{j=1}^{k}\lambda_j(1-u^j)\tilde G_\nu(u, t), \,\,|u| < 1,
	\end{equation}
	subject to the initial condition $\tilde {G}_\nu(u, 0) = 1$, and is given as
	\begin{equation}
		\tilde G_\nu(u, t) = \tilde \ell_\nu \Big(\sum_{j=1}^{k}\lambda_j(1-u^j), t\Big), \,\,|u| < 1,
	\end{equation}
	where the expression for $\tilde \ell_\nu$ is given by \eqref{2.21}  $($or by \eqref{eq:xLaplace}$)$. (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T06:02:34.831426+00:00","domain":"probability theory","id":"claim_790ecc958894416d7a7be0c6d8a7d14493c60f15c91618eb7d9d91b9ed378b3d","kind":"concept","schema_version":1,"statement":"[Proposition 32 of arXiv:2607.19873, 'Local limit theorem for the operator norm of products of random matrices'] Let $\bf G$ be a real reductive group and let $\mu$ be a Borel probability measure on $G$. 
Suppose that $\Gamma_{\mu}$ is Zariski dense in $G$ and that $\mu$ admits a finite exponential moment \eqref{Exponential-moment}.
Then, for any $\varphi \in C^0(\wt B)$, we have, uniformly in $\wt b \in \wt B$,  
\begin{align*}
 P_{\mu}^n \varphi (\wt b) - Q \varphi \big((\ell_0^{\mu})^n \theta(\wt b) \big) \xrightarrow[n\to\infty]{}  0. 
\end{align*} (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T15:27:25.799364+00:00","domain":"probability theory","id":"claim_79111f514773e75602e402e5276d759b22489add23eef2a5f5abf21072daa7dc","kind":"theorem","schema_version":1,"statement":"[Corollary cor:modewise of arXiv:2605.17082, 'Spectral Purification in Reversible Markov Chains: Hidden Parameters, Observable Equivalen'] Let $g_k = \sum_{i=2}^n c_i \lambda_i^k \phi_i$. Then
\begin{equation}
E_k - E_{k+1} = \sum_{i=2}^n (1 - \lambda_i^2) \, n_i(k).
\end{equation}
Equivalently, in terms of the relaxation spectrum $\mu_i = 1 - \lambda_i$,
\begin{equation}
E_k - E_{k+1} = \sum_{i=2}^n (2\mu_i - \mu_i^2) \, n_i(k),
\end{equation}
where $n_i(k) = |c_i|^2 \lambda_i^{2k}$.","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T11:11:44.347264+00:00","domain":"probability theory","id":"claim_7911856dc285b70dcf01563f833233650a3195c78db5e006cc3fd076847fc195","kind":"concept","schema_version":1,"statement":"[Corollary 11 of arXiv:2609.03098, 'Standing waves for Schr\"odinger equations with Kato class potentials and $L^\infty$-bound'] There exists $R'_e>0$, depending on the potential $V$ and the constants $M$, $L_\sigma$, $C_{\sigma}$ such that for any full solution $u$ of \eqref{main-eq} bounded in $H^{1}(\R^{N})$, the following estimate holds
			\begin{align}
