{"assumptions":[],"created_at":"2026-10-26T20:47:22.242048+00:00","domain":"probability theory","id":"claim_7991f60c12d095fddbb3ad846df1d32760fbba3c26056ba5e98f74d810f3511f","kind":"concept","schema_version":1,"statement":"[Lemma 5 of arXiv:2605.25719, 'A note on convergence rate for reflected BSDEs with quadratic generators by penalization m'] Let assumptions $(A1^{'})$, $(A2)$, $(A3)$ and $(H)$ be satisfied, then for numerical scheme \eqref{e3} we have
\begin{equation*}
M_{\lambda} \leq C\lambda,\quad N_{\lambda}\leq C\lambda^{max\{2,\frac{2}{\epsilon}\}}.
\end{equation*}
\begin{proof}
For any $i=1,\dots,n$ and $t\in[T_{n-i},T_{n-i+1}]$, let $(Y_{t}^{n,i,0},Z_{t}^{n,i,0})$ be the unique solution of 
\begin{equation*}
Y_{t}^{n,i,0}=Y_{T_{n-i+1}}^{n,i-1,0}+\int_{t}^{T_{n-i+1}} f \left( s,
E^{\mathcal{F}_{s}} \left[ Y_{T_{n-i+1}}^{n,i-1,0} \right],Z_{s}^{n,i,0} \right)ds-\int_{t}^{T} 
Z_{s}^{n,i,0} dW_{s}
\end{equation*}
where $Y_{T}^{n,0,0}=\xi$. From  \cite[Lemma 2.1]{HT}, we have $ Y_{t}^{n,1,\lambda} \geq Y_{t}^{n,1,0}$ in $[T_{n-1},T_{n}]$, which implies that
\begin{equation*}
f\left( s,E^{\mathcal{F}_{s}} \left[ Y_{T_{n-1}}^{n,1,0} \right],z \right) \leq f\left( s,E^{\mathcal{F}_{s}} \left[ Y_{T_{n-1}}^{n,1,\lambda} \right],z \right) \leq f^{\lambda}\left( s,E^{\mathcal{F}_{s}} \left[ Y_{T_{n-1}}^{n,1,\lambda} \right],z \right).
\end{equation*}
Thus, we can deduce inductively that $Y_{t}^{n,2,\lambda} \geq Y_{t}^{n,2,0}$ in $[T_{n-2},T_{n-1}]$ and $Y_{t}^{n,\lambda} \geq Y_{t}^{n,0}$ in $[0,T]$. Note that $Y_{t}^{n,0}$ is independent of $\lambda$, and there exists 
\begin{equation*}
K:=\sup \limits_{n\in \mathbb{N}} \left\{ \Vert Y^{n,0} \Vert_{\mathcal{S}^{\infty}(R)} \right\} \leq C
\end{equation*}
from \cite{LT}, which implies that $Y_{t}^{n,\lambda} \geq -K$.\par
On the other hand, let $(\hat{Y}_{t}^{n,i,\lambda},\hat{Z}_{t}^{n,i,\lambda})$ be the unique solution of
\begin{equation*}
\hat{Y}_{t}^{n,i,\lambda}=\hat{Y}_{T_{n-i+1}}^{n,i-1,\lambda}+\int_{t}^{T_{n-i+1}} g^{\lambda} \left( s,
E^{\mathcal{F}_{s}} \left[ \hat{Y}_{T_{n-i+1}}^{n,i-1,\lambda} \right],\hat{Z}_{s}^{n,i,\lambda} \right)ds-\int_{t}^{T_{n-i+1}} 
\hat{Z}_{s}^{n,i,\lambda} dW_{s}
\end{equation*}
where $g^{\lambda}(s,y,z)=f(s,y,z)+\lambda(K+S_{s}^{+})$ and $\hat{Y}_{T}^{n,0,\lambda}=\xi$. The comparison theorem implies that $Y_{t}^{n,1,\lambda} \leq \hat{Y}_{t}^{n,1,\lambda}$. We also have
\begin{equation*}
\begin{aligned}
f^{\lambda}\left( s,E^{\mathcal{F}_{s}} \left[ Y_{T_{n-1}}^{n,1,\lambda} \right],z \right) 
&\leq f \left( t,E^{\mathcal{F}_{s}} \left[ Y_{T_{n-1}}^{n,1,\lambda} \right],z \right) + \lambda \left( E^{\mathcal{F}_{s}} \left[ Y_{T_{n-1}}^{n,1,\lambda} \right]^{-}+S_{s}^{+} \right) \\
&\leq g^{\lambda} \left( s,E^{\mathcal{F}_{s}} \left[ \hat{Y}_{T_{n-1}}^{n,1,\lambda} \right],z \right).
\end{aligned}
\end{equation*}
Then using the same technique we have $Y_{t}^{n,2,\lambda} \leq \hat{Y}_{t}^{n,2,\lambda}$ in $[T_{n-2},T_{n-1}]$ and $Y_{t}^{n,\lambda} \leq \hat{Y}_{t}^{n,\lambda}$ in $[0,T]$. 
Using the inequality $\vert z \vert^{2-\varepsilon} \leq 1+\vert z \vert^{2}$ we have
\begin{equation*}
\begin{aligned}
g^{\lambda} \left( s,
E^{\mathcal{F}_{s}} \left[ \hat{Y}_{T_{n-i+1}}^{n,i-1,\lambda} \right],z \right)
&\leq \overline{C} \left( 1+\Vert \hat{Y}^{n,i-1,\lambda} \Vert_{\mathcal{S}^{\infty,i-1}(\mathbb{R})} + \vert z \vert^{2-\varepsilon} \right) + \lambda \left( K+\Vert S^{+} \Vert_{\mathcal{S}^{\infty}(\mathbb{R})} \right)\\
&\leq \left( 2\overline{C}+\lambda K+\lambda \Vert S^{+} \Vert_{\mathcal{S}^{\infty}(\mathbb{R})} \right) + \overline{C} \Vert \hat{Y}^{n,i-1,\lambda} \Vert_{\mathcal{S}^{\infty,i-1}(\mathbb{R})} + \overline{C} \vert z \vert^{2} \\
&= \alpha_{\lambda}+\overline{C} \Vert \hat{Y}^{n,i-1,\lambda} \Vert_{\mathcal{S}^{\infty,i-1}(\mathbb{R})} + \overline{C} \vert z \vert^{2}.
\end{aligned}
\end{equation*}
Then from \cite[Lemma 2.1]{HT}, we have
\begin{equation*}
\begin{aligned}
\Vert \hat{Y}^{n,i,\lambda} \Vert_{\mathcal{S}^{\infty,i}(\mathbb{R})}
\leq &\alpha_{\lambda}\frac{T}{n} + \left( 1+\frac{\overline{C}T}{n} \right) \Vert \hat{Y}^{n,i-1,\lambda} \Vert_{\mathcal{S}^{\infty,i-1}(\mathbb{R})}\\
\leq &\alpha_{\lambda} \frac{T}{n} + \left( 1+\frac{\overline{C}T}{n} \right)
\left[  \alpha_{\lambda}\frac{T}{n} + \left( 1+\frac{\overline{C}T}{n} \right) \ (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T06:54:15.703159+00:00","domain":"probability theory","id":"claim_7995807aab5ac1bbd5490a622b3feb34040866c0d029c8dce9ef1ccb1406fbf7","kind":"lemma","schema_version":1,"statement":"[Lemma 6 of arXiv:2608.09840, 'Langevin dynamics along the zero set of real-analytic potentials'] Fix a singularity type $(\lambda,m)$, a function $f \in C^\infty_c(D_{\lambda,m})$, and a monomializing chart $(U,y)$. Then for any compact set $K \subset U$ there is $\varepsilon > 0$ such that
