{"assumptions":[],"created_at":"2026-10-27T18:51:26.590107+00:00","domain":"probability theory","id":"claim_7ad8e91af9eab17f5c892a1fce1e42be3e1e219519916bf16c895b4ea04a4e11","kind":"lemma","schema_version":1,"statement":"[Lemma lem:kernel-asymp of arXiv:2606.02003, 'Higher-Order Multifractional Stable Motion:\\ Definition and Fundamental Properties'] Under Assumption~(ass:params of the paper), with $\gamma(t) = H(t)-1/\alpha$:

\begin{enumerate}[label=(\roman*)]

\item \textbf{Vanishing for $u > t$.}
  For all $u > \max\{0,t\}$: $f_n(t,u;H,\alpha) = 0$.

\item \textbf{Near-diagonal behaviour.}
  For $u \in (t-\delta, t)$ with $\delta \in (0,t)$ sufficiently
  small (so that $u > 0$):
  \begin{equation}

  f_n(t,u;H,\alpha)
  = \frac{(t-u)^{\gamma(t)}}{\Gamma(\gamma(t)+1)} + R_1(t,u),
  \end{equation}
  where $|R_1(t,u)| \leq C_1\,(t-u)^{\gamma(t)+1}$ for a constant
  $C_1 > 0$ uniform in $t$ on compact intervals.

\item \textbf{Tail behaviour.}
  For $u < \min\{0, t-1\}$ (so that $|u|$ is large and $|t/u| < 1$):
  \begin{equation}

  f_n(t,u;H,\alpha)
  = C_n(t)\,|u|^{\gamma(t)-n} + R_2(t,u),
  \end{equation}
  where $|R_2(t,u)| \leq C_2\,|u|^{\gamma(t)-n-1}$, and the leading
  coefficient is
  \begin{equation}

  C_n(t)
  = \frac{(-t)^n}{\Gamma(\gamma(t)+1)}\binom{\gamma(t)}{n},
  \quad
  \binom{\gamma}{n} := \frac{\gamma(\gamma-1)\cdots(\gamma-n+1)}{n!}.
  \end{equation}
  The constant $C_2 > 0$ is uniform in $t$ on compact intervals.

\end{enumerate}","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T05:37:15.263664+00:00","domain":"probability theory","id":"claim_7ada8880096aa177422dafbd552be6d241b7ff37257dbc63352a9e38ce8d994c","kind":"theorem","schema_version":1,"statement":"[Proposition 9 (Sampling from a large sample) of arXiv:2607.12263, 'Random sets are close to low-discrepancy sets'] Fix $0<\delta<1$. Assume that $N$ has the form $N=n2^k$ for some positive integers $n$ and $k$. Let $Z_1,\ldots,Z_N$ be iid random variables taking values in $[0,1]^d$. Let $S\subset[N]$ be a random $n$-element subset, chosen uniformly without replacement, independently of the sample $Z_i$. Then there is a randomized algorithm that produces an $n$-element subset $Q\subset[N]$ such that
	\begin{equation}
		\E \abs*{Q \cap S} \ge n(1-\delta)-2\sqrt n,
	\end{equation}
	and
	\begin{equation}
		\E\sup_B \abs*{ \frac1n\sum_{i\in Q}\one_{\{Z_i\in B\}} - \frac1N\sum_{i=1}^N\one_{\{Z_i\in B\}}}
