		\left(\frac{k}{\delta}+\log(2n)\right),
	\end{equation}
where the supremum is over anchored boxes \eqref{eq: anchored box}.","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-26T20:24:30.015560+00:00","domain":"probability theory","id":"claim_7adefb1cb12a7fe1be10ab889f32f76a55f75fb80aae3c2e6cdd8057adc31d52","kind":"theorem","schema_version":1,"statement":"[Thm 5 of arXiv:2605.05430, 'Dirichlet problems and exit distributions for the telegraph process and its planar extensi'] For $j=1,3$, the Fourier transforms $\widetilde{u}_j(\alpha,y\mathord{;}z)$ read
\begin{equation}\widetilde{u}_1(\alpha,y\mathord{;}z)=\frac{2\lambda^2\sinh\left(\frac{\lvert\alpha\lvert\lambda(L-y)}{\sqrt{\lambda^2+\alpha^2c^2}}\right)e^{i\alpha z}}{\big(\sqrt{\lambda^2+\alpha^2c^2}+\lvert\alpha\lvert c\big)^2\;e^{\frac{\lvert\alpha\lvert\,\lambda\,L}{\sqrt{\lambda^2+\alpha^2c^2}}}-\big(\sqrt{\lambda^2+\alpha^2c^2}-\lvert\alpha\lvert c\big)^2\;e^{-\frac{\lvert\alpha\lvert\,\lambda\,L}{\sqrt{\lambda^2+\alpha^2c^2}}}}\end{equation}
and
