{"assumptions":[],"created_at":"2026-10-27T07:12:19.475369+00:00","domain":"probability theory","id":"claim_7c62234fb00b6e9bf00ec9631e24c6a7aa6ba1e73ebe7deaeb1eb5228f91c827","kind":"theorem","schema_version":1,"statement":"[Theorem 3 (Geometric-time embedding) of arXiv:2608.17927, 'Near-unit-root persistence of symmetric stable \\ autoregressive sequences'] Let $X$ satisfy \eqref{eq:ar1} with innovations normalized by \eqref{eq:stable-cf}, and set
\begin{equation}

u_{0} = 0, \quad u_{n} \,\deq\, \sigma^{\alpha}\sum_{j=1}^{n}a^{-\alpha j} =
\sigma^{\alpha}\biggl(\frac{a^{-\alpha n}-1}{1-a^{\alpha}}\biggr).
\end{equation}
Then, as random elements of $\RR^{\NN_{0}}$,
\begin{equation}

(X_{n})_{n \geq 0} \,\dis\, (a^{n}(x+L_{u_{n}}))_{n \geq 0}.
\end{equation}
In particular,
\begin{equation}

Q_{n}(x;a,\alpha,\sigma) = \PP(x+L_{u_{k}} > 0,\ 1 \leq k \leq n).
