\item for every $\varepsilon > 0$, there is a function $\phi_\varepsilon \colon \R \to \R$ satisfying
\[
\phi_\varepsilon(t) = t \text{ on } [0,1], \quad -\varepsilon \le \phi_\varepsilon \le 1 + \varepsilon, \quad 0 \le \phi_\varepsilon(t) - \phi_\varepsilon(s) \le t-s \text{ for } s \le t,
\]
such that $\phi_\varepsilon \circ f \in C^1_{c,\,\textnormal{strat}}(\Scal)$ for every $f \in C^1_{c,\,\textnormal{strat}}(\Scal)$.
\item for any open relatively compact set $G \subset X$ and compact set $K \subset G$, there is a function $h \in C^1_{c,\,\textnormal{strat}}(\Scal)$ with $h \ge 0$, $h = 1$ on $K$, and $h = 0$ on $X \setminus G$;
\item $C^1_{c,\,\textnormal{strat}}(\Scal)$ is dense in $C_c(X)$ with respect to the uniform norm, and dense in $L^2(X,\mu)$ for any Radon measure $\mu$ on $X$.
\end{enumerate}","status":"unverified"}

