        \left(\frac{\eta}{1-\rho}\right)^{\frac1\beta},
        \frac{\eta}{1-\rho}
    \right\}.
\]
Hence the Nesterov label-noise floor is
\[
    \frac{\eta^2\sigma^2}{B}\sum_{\tau=0}^{k-1}\mathcal K_{\nesterov}(\tau)
    \eqsim
    \frac{\sigma^2}{B}
    \min\left\{
        \left(\frac{\eta}{1-\rho}\right)^{\frac1\beta},
        \frac{\eta}{1-\rho}
    \right\}.
\]","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T21:49:15.471161+00:00","domain":"probability theory","id":"claim_7ca95347e8e754241bb2031029e3de19b7e70fa92dd312d0d6c1dac3e8791aa7","kind":"concept","schema_version":1,"statement":"[Lemma lemma MARSDEN of arXiv:2608.28278, 'Reduction of symmetric time-dependent Hamiltonian systems I: presymplectic principal $\R$-'] Let $\phi: G \times M \to M$ be a presymplectic Hamiltonian action of a Lie group $G$ on the presymplectic manifold $(M,\omega)$ with $Ad^*$-equivariant momentum map $J:M \to \mathfrak{g}^*$. Let $\nu \in \mathfrak{g}^*$ a regular value of $J$ and $x\in J^{-1}(\nu)$, then
