        \item[(i)] $T_x(G_\nu \cdot x) = T_x(G\cdot x) \cap T_x(J^{-1}(\nu))$.
        \item[(ii)] $T_x(J^{-1}(\nu))=(T_x(G\cdot x))^{\perp,\omega}$, where $(T_x(G\cdot x))^{\perp,\omega}$ denotes the $\omega$-orthogonal complement of $T_x(G\cdot x)$.
