{"assumptions":[],"created_at":"2026-10-27T21:09:59.303694+00:00","domain":"probability theory","id":"claim_7cd7f480805ea73b1d159952bb71db441be990222569c7d511786b2bd521bc19","kind":"concept","schema_version":1,"statement":"[Proposition isometry of arXiv:2608.07236, 'Negative association of Busemann functions \\in exponential last-passage percolation'] {fan_seppalainen20}}]
