{"assumptions":[],"created_at":"2026-10-26T20:52:45.029236+00:00","domain":"probability theory","id":"claim_7d2d1d4dc1cce93b62e63d5a3a2702b3f1833d60e419caa0a4640c9ce4d0e755","kind":"lemma","schema_version":1,"statement":"[Lemma 7 of arXiv:2606.07096, 'Non-Selection of Lagrangian Trajectories in the Zero-Noise Limit for a Class of Stochastic'] Let $(\cF_t)_{t\in [S,T]}$ be a given filtration, $W^H$ be a $\R^d$-valued $(\cF_t)_t$-fBm of parameter $H\in (0,+\infty)$ and let $f\in L^\infty([S,T];C^1_x)$. Let $Z$ be a $\R^d$-valued $\cF_S$-measurable random variable and $\psi$ be a $\R^d$-valued, $(\cF_t)_t$-progressive process such that $\llbracket \psi\rrbracket_\varsigma<+\infty$ for some $\varsigma>0$ (for $\llbracket \psi\rrbracket_\varsigma$ defined by~\eqref{eq:slowly_varying_process}). Then:
\begin{enumerate}
    \item If $H\in (0,1/2)$ and $\varsigma=1$, there exists a constant $C_1=C_1(H,d)>0$ such that, uniformly over $\kappa\in (0,1]$, for every $(s,t)\in [S,T]^2_\leq$ one has
    \begin{equation}
	   \bigg\|\int_s^t f(r, Z+ \kappa W^H_r + \kappa\psi_r) \dd r \bigg\|_{L^2(\Omega)} \leq C_1 \kappa^{-1} |t-s|^{1-H} (1+\llbracket \psi\rrbracket_1)\| f\|_{L^\infty([S,T];C^{-1}_x)}.
    \end{equation}
    \item If $H\in [1/2,+\infty)\setminus \N$ and $\varsigma>H$, then for any $\theta>0$ such that
    \begin{equation}
        \theta<\frac{1}{2H}, \quad \theta<\frac{\varsigma}{H}-1
    \end{equation}
    there exists a constant $C_2=C_2(H,d,\theta,\varsigma)>0$ such that, uniformly over $\kappa\in (0,1]$, for every $(s,t)\in [S,T]^2_\leq$ one has
    \begin{equation}
	   \bigg\| \int_s^t f(r, Z+ \kappa W^H_r + \kappa \psi_r) \dd r\bigg\|_{L^2(\Omega)} \leq C_2 \kappa^{-\theta} |t-s|^{1-\theta H} (1+\llbracket \psi\rrbracket_\varsigma)\| f\|_{L^\infty([S,T];C^{-\theta}_x)}.
    \end{equation}
\end{enumerate}
Similarly, if $f$, $Z$, $\psi$ are as above and $W^\beta$ is a $\beta$-stable Lévy process with $\beta\in (0,2]$ and $\varsigma>1/\beta$, then for any $\theta>0$ such that
\begin{equation}
        \theta<\frac{\beta}{2}, \quad \theta<\varsigma\beta-1
    \end{equation}
there exists a constant $C_3=C_3(\beta,d,\theta,\varsigma)>0$ such that, uniformly over $\kappa\in (0,1]$, for every $(s,t)\in [S,T]^2_\leq$
    \begin{equation}
	   \bigg\| \int_s^t f(r, Z+ \kappa W^\beta_r + \kappa \psi_r) \dd r\bigg\|_{L^2(\Omega)}
       \leq C_3 \kappa^{-\theta} |t-s|^{1-\theta H} (1+\llbracket \psi\rrbracket_\varsigma)\| f\|_{L^\infty([S,T];C^{-\theta}_x)}.
    \end{equation}","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T05:57:28.229956+00:00","domain":"probability theory","id":"claim_7d30456c204813fc31316b4420403407b1a5a98b6cd01a01f9b9c9c166de8a45","kind":"lemma","schema_version":1,"statement":"[Lemma 14 of arXiv:2607.18104, '2607.18104'] For $\delta>0$, $i \in \lbr \delta^{-1}\rbr$,  $n\in \N$ and $a\in \R$, we define the events
  \begin{equation*}
     \mathsf{A}_{n,i}^{\delta,a} := \left\{ \Lpa(x,s;y,t)=\Lpat(x,s;y,t) \,\,\, \forall (x,s;y,t) \in \big([a,a+1)\times [(i-1)\delta,i\delta]\big)^2_{\uparrow} \cap \mathcal{V}_{\delta^{-1}} \cap \mathcal{D}_{(4\delta)^2} \right\} , 
  \end{equation*} 
  where the arguments $x$ and $y$ in $\Lpa$ are understood modulo $1$.
  Then there exists  $c_1,C_1>0$ such that for all $\delta>0$, $i \in \lbr \delta^{-1}\rbr$, and  $n \geq \delta^{-2}$,  
    \begin{equation}
      \P( \mathsf{A}^{\delta,a}_{n,i} ) \geq 1- C_1 \exp\big(-c_1 \delta^{-1/2}\big) . 
  \end{equation}
Further, there exist $c_2,C_2>0$ such that for all $n\in \N$, there is a coupling $\mathbf{P}$ between a full-space directed landscape $\mathcal{L}$ and a wrapped patched directed landscape $\Lpa$ such that for all $n \geq \delta^{-2}$,
\begin{align}
\begin{split}
    &\mathbf{P}\Big( \Lpa(x,s;y,t) = \mathcal{L}(x,s;y,t) \,\,\, \forall (x,s;y,t)\in \big([a,a+1)\times [(i-1)\delta,i\delta]\big)^2_{\uparrow} \cap \mathcal{V}_{\delta^{-1}} \cap \mathcal{D}_{(4\delta)^2}\Big) \\&\qquad\geq 1 - C_2\exp(-c_2\delta^{-1/2}) .
\end{split}
\end{align}","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-26T20:23:03.036202+00:00","domain":"probability theory","id":"claim_7d30772bfaa8d8434bfc46096f01d1ae3e087d5497c15d6605ffdb3886f482fa","kind":"concept","schema_version":1,"statement":"[Theorem 7 of arXiv:2605.03182, 'Exponential integrability of the solution to the stochastic Burgers equation driven by whi'] Let $\alpha \ge 1$. Consider $\gamma \in \left[0,\frac{1}{4}\right)$,  $1 < p <+\infty$,
