{"assumptions":[],"created_at":"2026-10-27T21:05:37.772878+00:00","domain":"probability theory","id":"claim_7eb017d84e306889bf562e9c2135273597c90d70f804b42a51c9a13c877b799f","kind":"theorem","schema_version":1,"statement":"[Proposition prop1 of arXiv:2608.00295, 'Quadratic Perturbations of Markov Systems'] Let $A_1=	\begin{pmatrix}
a_1 & b_1\\
c_1 & d_1 
\end{pmatrix}$ and $A_2=	\begin{pmatrix}
a_2 & b_2\\
c_2 & d_2 
\end{pmatrix}$ be $2\times 2$ stochastic matrices, and $b_{1,2}=\begin{pmatrix}
\alpha_{1,2}^{(1)}\\
\alpha_{1,2}^{(2)}
\end{pmatrix}\in \mathbb{R}^2,$ $b_{2,1}=\begin{pmatrix}
\alpha_{2,1}^{(1)}\\
\alpha_{2,1}^{(2)}
\end{pmatrix}\in \mathbb{R}^2$ null-sum vectors. 
We define the nonlinear operator 

$$T(A_1,A_2;b_{1,2}, b_{2,1}):\mathbb{R}^2\times \mathbb{R}^2\to \mathbb{R}^2\times \mathbb{R}^2,$$ 
determined by 
\begin{equation}
T(A_1,A_2;b_{1,2},b_{2,1})\begin{bmatrix}
v_1\\
v_2
\end{bmatrix}=\begin{bmatrix}
A_1v_1+\langle v_1,v_2\rangle b_{1,2}\\
A_2v_2+\langle v_2,v_1\rangle b_{2,1}
\end{bmatrix}.
\end{equation}
The following are equivalent. 
\begin{enumerate}
\item For each of the four possible choices of $\pm$ sign of the null-sum vectors $b_{1,2}$ and $b_{2,1}$,  the maps $T(A_1,A_2;\pm b_{1,2}, \pm b_{2,1})$ induce  well defined nonlinear operators from $\Delta_1\times \Delta_1$ to $\Delta_1\times \Delta_1$. 
\item The entries of  $A_1$, $A_2$, $b_{1,2}$ and $b_{2,1}$ satisfy the  following inequalities
\begin{eqnarray}

\begin{aligned}
|\alpha_{1,2}^{(1)}|\leq \min \{a_1,b_1\},\\
|\alpha_{2,1}^{(1)}|\leq \min \{a_2,b_2\},\\
|\alpha_{1,2}^{(2)}|\leq \min \{c_1,d_1\}, \\
|\alpha_{2,1}^{(2)}|\leq \min \{c_2,d_2\}.
\end{aligned}

\end{eqnarray}
\end{enumerate}","status":"unverified"}

