{"assumptions":[],"created_at":"2026-10-28T00:52:17.580024+00:00","domain":"probability theory","id":"claim_7f2910c6a0128f1ebf9dbc5670d60f18210b51d8846373ea3a04b8ea3dc6270b","kind":"definition","schema_version":1,"statement":"[Definition Measurable fields of closable operators of arXiv:2411.14936, 'Massive Particle Systems,\\Wasserstein Brownian Motions,\\ and the Dean--Kawasaki Equation'] Let~$H$ be as in~(equation eq:DirInt of the paper). For each~$\zeta\in Z$ further let~$(A_\zeta,D_\zeta)$ be a closable operator on~$H_\zeta$.
A field of closable operators~$\zeta\mapsto (A_\zeta, D_\zeta)$ is called \emph{$\nu$-measurable} (\emph{with underlying space~$S$}) if
\begin{enumerate*}[$(a)$]
\item $\zeta\mapsto A_\zeta u_\zeta\in H_\zeta$ is a $\nu$-measurable vector field for every $\nu$-measurable vector field~$u$ with~$u_\zeta\in D_\zeta$ for every~$\zeta\in Z$;
\item there exists a sequence~$\left(u_n\right)_n$ of $\nu$-measurable vector fields such that~$u_{n,\zeta}\in D_\zeta$ and~$\tseq{(u_{n,\zeta},A_\zeta u_{n,\zeta})}_n$ is a total sequence in~$\Graph(\overline{A_\zeta})$ for all~$\zeta\in Z$.
\end{enumerate*}
For a $\nu$-measurable vector field of closable operators~$\zeta\mapsto (A_\zeta, D_\zeta)$, its direct-integral operator~$(A,D)$ is the operator on~$H$ defined as
\begin{gather*}
D\eqdef \set{u\in H : \begin{gathered} u_\zeta\in D_\zeta {\textrm{\,for ${\nu}$-a.e.~}} \zeta\in Z\,\mathrm{,}\;\, \\ \zeta\mapsto A_\zeta u_\zeta \text{~is square-integrable}\end{gathered}}\,\mathrm{,}\;\,
\\
A u \eqdef (\zeta\mapsto A_\zeta u_\zeta)\,\mathrm{,}\;\, \qquad u\in D\,\mathrm{.}
\end{gather*}","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-26T19:20:15.485200+00:00","domain":"probability theory","id":"claim_7f2957c63cbf081ea7e33bcd24e55b0d00ea816653c442baf7b96959bb05045c","kind":"theorem","schema_version":1,"statement":"[Prop 66 of arXiv:2509.01797, 'Relation between Wick powers and excursion clusters of the 2D GFF'] For every $w\in\C$, $x>0$ and $y\in\R$ such that $\vert y\vert <x$,
the following holds:
\begin{equation}

\sum_{n=1}^{+\infty}
\dfrac{1}{n!}
\Big(\sum_{k=1}^{n}\dfrac{n! (n-1)!}{(n-k)! k! (k-1)! }
\,\vert y\vert^{n-k}\,\vert w\vert^{k}
\Big)
\dfrac{1}{x^{n}}
<+\infty,
\end{equation}
and
\begin{eqnarray}

\sum_{n=1}^{+\infty} (-1)^{n-1}
\dfrac{1}{n!}
\dfrac{w^{n}}{(x-y)^{n}}
&=&
