\quad \text{for all } u \in \mathcal{H}_X.
\end{equation}
The operator $D_X \colon L^2(\Omega) \to \mathcal{H}_X$ is called the \emph{operator--covariant derivative}.","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T19:01:48.561155+00:00","domain":"probability theory","id":"claim_7f8a7032ae202c09f0524037d80d5ca6dbbbfd4f1cdc5f71f9c3ac7fafed6c89","kind":"theorem","schema_version":1,"statement":"[Theorem analyticity_general of arXiv:2606.29622, 'Affine Structure of the Brownian Signature'] Let $\bm p \in \mathcal B\,$, and $\bm \xi$ be as in (equation eq:def_xi of the paper). Then, defining $\bm u_t := \mathbb{E}[\bm \xi_t]$ for all $t \in [0\,,T]\,$, we have:
    \begin{enumerate}
        \item $\bm u_t \in \mathcal A_{\infty}$ for all $t \in [0\,,T]\,$, so that
        \begin{align}
         \mathbb{E} \left[\exp\left(\bracket{\bm p}{\sigX[] \otimes \sigW[t,T]}\right) \right] = \bracket{\bm u_t}{\sigX[]}\,, \quad \sigX[] \in G\,, \quad t \in [0, T]\,.
    \end{align}
    In particular,
\begin{align}
\mathbb{E}\left[\exp \left(\bracket{\bm p}{\sigW[T]}\right)\, \Big|\, \mathcal F_t\right] = \bracket{\bm{u}_t}{\sigW[t]}, \quad t \in [0, T].     \end{align}
    \item For all $\sigX[] \in G\,$, $\sup_{t \in [0, T]}\,\|\bm u_t\|_{\sigX[]} \leq \exp\left(C_{\bm p, T} \,(1 + M_{\bm p}(\sigX[]))^{\deg_{{\color{NavyBlue}{\mathbf{1}}}}(\bm p)}\right) < + \infty\,$.
    \item $t \mapsto \bm u_t^{{\color{NavyBlue}{\mathbf{\varnothing}}}}$ is continuous on $[0\,,T]\,$. 
    \end{enumerate}","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T12:10:07.264281+00:00","domain":"probability theory","id":"claim_7f8f027485a970dc40fc5c77f10b0cccc9f1736fe0adbacac80dba9e4952ceb5","kind":"concept","schema_version":1,"statement":"[Lemma dependentperco of arXiv:2603.05467, 'Thresholds for colouring the random Borsuk graph'] Let $ C_m(\underline{0}) $ be the cluster of $ \underline{0} $ in bond percolation restricted to $ \Lambda_m\coloneqq \{-m,\dots,m \}^d $ with parameter $ p $. Then, for all $ 0<\varepsilon <1/10$ we can choose $ p=p(\varepsilon,d) $ large enough such that for all large enough $ m\geq m_0(\varepsilon,d,p) $ 
	\begin{equation*}
		\mathbb{P}_p(|C_m(\underline{0})|>(1-\varepsilon)|\Lambda_m|)>1-\varepsilon.
	\end{equation*} (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-26T19:45:07.263202+00:00","domain":"probability theory","id":"claim_7f8ffbf0bf13c4baebe0169ca233c301f26085ebb693f5f82662dcc4cba8e139","kind":"concept","schema_version":1,"statement":"[Lemma 28 (Lemma 1.3.2~\cite{kuczma1990iterative}) of arXiv:2604.19738, 'Phase Transitions in the Fluctuations of Functionals of Random Neural Networks \\'] Let $(x_n\; |\; n \in \N)$  be a sequence of positive elements and let $s\in (0,1)$ be such that
	$$ p_n= \frac{x_{n+1}}{x_n} -s \to 0 \qquad \text{ as } n \to \infty \ .$$
	If, moreover, $p_n \in (-s,1-s)$ for every $n\in \N$, then
	$$ \sum_{n=0}^\infty r(x_n) < \infty $$
	for every monotonic measurable function $r:\, \R\to \R^+$ such that,
	$$ \int_0^\delta \frac{r(x)} {x} \di x <\infty  \qquad \delta>0 \  .  $$ (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T14:18:13.231912+00:00","domain":"probability theory","id":"claim_7f9058084226d828fe7c5c24fc679fa07b9c9e7a02c1aaae9bf4d31da73f1564","kind":"lemma","schema_version":1,"statement":"[Lemma lem:discrete of arXiv:2506.15949, 'On the passage times of self-similar Gaussian processes on curved boundaries'] Suppose that $t_{n+1}-t_n = \mathcal{o}(t_n)$ as $n\to\infty$.
	Then, there exists a constant $K >1$ with the following property:
	Whenever $m(n)$ is an integer in $(1\,,n)$ for every $n\in\mathbb{N}$,
	\[
		\mathrm{P}\{\hat{T}_c > t_n\}
		\leqslant \mathrm{P}\{ T_{c+\varepsilon,\alpha} > t_n/t_{m(n)}\}
		+ K\sum_{j=m(n)}^n \exp\left(- \frac{\varepsilon^2}{K}
		\left|\frac{t_j}{t_{j+1}-t_j}\right|^{2\alpha} \right),
	\]
	for every $c,\varepsilon>0$ and $n\in\mathbb{N}$.","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T23:48:35.825903+00:00","domain":"probability theory","id":"claim_7f91245585cd10734e961933441027d8aefe72a7cdf16f5f7aaae04df1db703e","kind":"definition","schema_version":1,"statement":"[Defi of arXiv:2411.09629, 'A Kesten Stigum theorem for Galton-Watson processes with infinitely many types in a random'] Let $(F_{x,e})_{x\in\mathbb{X}, e\in\mathcal{E}}$ be a familiy of integer-valued random variables. We say that $(F_{x,e})_{x\in\mathbb{X}, e\in\mathcal{E}}$ belongs to
	\begin{itemize}[-]
		\item \textbf{BS} if and only if for each $(x,e)\in\mathbb{X}\times \mathcal{E}$, there exists a deterministic integer $A_{x,e}$ and a real number $\varepsilon >0$ such that 
		\begin{align*} {\mathbb P}[F_{x,e}\geq A_{x,e}]=0 \text{ and } \mathbb{E}\left[\sup_{x\in\mathbb{X}} \frac{A_{x,\xi_0}\left(\log^+(A_{x,\xi_0})\right)^{1+\varepsilon}}{f_{x,\xi_0}}\right]<\infty,
		\end{align*}
		\item \textbf{ExpTail} if and only if for each $(x,e)\in\mathbb{X}\times \mathcal{E}$, there exists $q(x,e)<1, \alpha(x,e)>0$ and $\beta(e)>0$ such that
		$${\mathbb P}[F_{x,e}\geq k] \overset{\beta(e)}{\asymp}\alpha(x,e) q(x,e)^k$$ and
		\begin{align*}
			\mathbb{E}\left[\frac{\beta(\xi_0)^2}{1-\sup_{x\in\mathbb{X}}q(x,\xi_0)}\right]&<\infty.
		\end{align*}
		\item \textbf{PolyTail} if and only if for each $(x,e)\in\mathbb{X}\times \mathcal{E}$, there exists $\delta(x,e)>1, \alpha(x,e)>0$ and $\beta(e)>0$, it holds
		$${\mathbb P}[F_{x,e}\geq k] \overset{\beta(e)}{\asymp}\alpha(x,e) k^{-\delta(x,e)},$$ where 
		\begin{align*}
			\mathbb{E}\left[\beta(\xi_0)^2 \inf_{x\in \mathbb{X}} \delta(x,\xi_0)\right]<\infty \text{ and } \mathbb{E}\left[\frac{\beta(\xi_0)^2}{(\inf_{x\in \mathbb{X}} \delta(x,\xi_0)-1)^{1+\varepsilon}}\right]&<\infty \text{ for some $\varepsilon>0$.}
		\end{align*}
	\end{itemize}","status":"unverified"}

