	\lim_{p\to 0}\mathbb E_x(\ee ^{-q\tau^-_{b,U^a}})&=\mathcal{Z}_{b,a}^{(q+\lambda )}(x)-\frac{\mathcal{Z}_{b,a}^{(q+\lambda )\prime}(a)}{\mathcal{W}_{b,a}^{(q+\lambda )\prime}(a)}\mathcal{W}_{b,a}^{(q+\lambda )}(x)+\lambda\int_b^ar_a^{(q+\lambda)}(x,y)\dd y \mathbf 1_{\{a,b\in \mathbb R_+\}}\\
	&\quad +\Bigl(\mathcal{Z}_{b,a}^{(q+\lambda )}(a)-\frac{\mathcal{Z}_{b,a}^{(q+\lambda )\prime}(a)}{\mathcal{W}_{b,a}^{(q+\lambda )\prime}(a)}\mathcal{W}_{b,a}^{(q+\lambda )}(a)\Bigr)\frac{\lambda\int_b^ar_a^{(q+\lambda)}(x,y)\dd y}{1-\lambda\int_b^ar_a^{(q+\lambda)}(a,y)\dd y} \mathbf 1_{\{a,b\in \mathbb R_-\}}
								\end{align*}
		\end{itemize}","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-26T20:53:31.967433+00:00","domain":"probability theory","id":"claim_7fd40055381adcebee6ed6dd8956f4f4f06732a692a46399fb18c469b5039acf","kind":"concept","schema_version":1,"statement":"[Proposition 12 (Lemma 8.6 of \cite{Gubinelli:06}) of arXiv:2606.09904, 'Non-explosion principles for branched rough differential equations with unbounded coeffici'] For any \(\phi \in C^{N}\), defining \(\phi(\mathbf{Y})\) by
