{"assumptions":[],"created_at":"2026-10-27T20:48:25.216827+00:00","domain":"probability theory","id":"claim_8008aee4f91854f7a21c4296f890e47817c0b75c053571bfa7a13f3b93e34935","kind":"concept","schema_version":1,"statement":"[Lemma lem:continuity0-bd of arXiv:2607.05671, 'Bi-infinite systems of singularly interacting Brownian particles and the KPZ equation'] Let $\theta \in (0,1)$, and for $\varepsilon \in (0,1]$, choose $\delta = \varepsilon^{1/2\theta}$, so that $\tilde{\mathcal{E}}_\theta^\varepsilon(t,x) = \tilde{\mathcal{E}}^{t,x,\delta,\varepsilon}(t)$. Fix $T > 0$ and $r \in [1,\infty)$. 
\begin{enumerate}[label = (\roman*)]
\item There exist constants $b_1 = b_1(r,T)$ and $b_2 = b_2(\theta,r,T)$ in $(0,\infty)$ such that, for all $\varepsilon \in (0,1]$, $t \in [0,T]$ and $x,x' \in \mathbb{R}$, 
\begin{equation} 
\| \tilde{\mathcal{E}}^{t,x,\delta,\varepsilon}(0) - \tilde{\mathcal{E}}^{t,x',\delta,\varepsilon}(0) \|_r \leq b_1 e^{b_2(|x| + |x'|)}|x' - x|^{\theta/2}.
\end{equation}
\item There exist constants $b_3 = b_3(r,T)$ and $b_4 = b_4(\theta, r,T)$ in $(0,\infty)$ such that, for all $\varepsilon \in (0,1]$, $t,t' \in [0,T]$ and $x \in \mathbb{R}$, 
\begin{equation} 
\| \tilde{\mathcal{E}}^{t,x,\delta,\varepsilon}(0) - \tilde{\mathcal{E}}^{t',x,\delta,\varepsilon}(0) \|_r \leq b_3 e^{b_4|x|}|t' - t|^{\theta/4}.
\end{equation}
\end{enumerate} (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T23:00:22.781317+00:00","domain":"probability theory","id":"claim_800cec4b6578f02a361e3cbcf9484768f5f98ffe4fe0903a066bde630a11c6fa","kind":"theorem","schema_version":1,"statement":"[Prop Quantitative Approximation Probability  of arXiv:2411.01633, 'On the Limit of the Tridiagonal Model \\for $\beta$-Dyson Brownian Motion'] For any fixed $k$, there exist constants $C(T,k), C'(T,k)$ such that
