C_\pi(\tau)\eqdef \int_\mbfT \sum_i s_i\,\tau(s_i^{-1})\mathop{}\!\mathrm{d} \pi(\mbfs)<\infty \quad \text{form some $\tau$ as above} \,\mathrm{.}
