{"assumptions":[],"created_at":"2026-10-27T12:52:05.694476+00:00","domain":"probability theory","id":"claim_8068a31d0b7591d8611ae3a5aac63fb0b46823cc6f2dfdcc601750634a38860e","kind":"concept","schema_version":1,"statement":"[Prop LT-2 of arXiv:2602.21277, 'A Limit in Law for the Cover Time and Last Visited Vertex of Wired Planar Domains'] Given $c,\theta>0$, there exists $C=C(c,\theta,\gamma) > 0$ such that, if $k$ is large enough, given any integer $j>1$, $n \geq k$ and $\widetilde{x} \in {\rm D}_n$ such that $\overline{{\rm B}^+[\widetilde{x};j]}\subseteq {\rm D}_n$, for all $x,x' \in {\rm B}^-[\widetilde{x};j-1]$ with $\log \| x-x'\| \geq k+(j-2-c)k^\gamma$ we have
\begin{equation}
	\mathbb{P} \Big( \max\{L_t(x), L_t(x')\} \leq \theta \,\Big|\, \sqrt{\widehat{N}_t[\widetilde{x};j]} \geq v \,; 
\mathcal F[\widetilde{x};j]\Big) \\ \leq  {\rm e}^{ - 4(k+jk^\gamma) -4\sqrt{2}\widehat{v}  + Ck^\gamma}.
\end{equation}
uniformly over all $t >0$ and $v \geq \sqrt{2}(k+(j-1)k^\gamma)$. (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T11:23:37.875319+00:00","domain":"probability theory","id":"claim_8069f25b929a505e6e88b84058c74d934495f412859729896791355374612fe4","kind":"theorem","schema_version":1,"statement":"[Theorem 35 of arXiv:2609.03647, 'Extension Problems for the Vladimirov--Taibleson Operator and the Hierarchical Laplacian'] Assume that
\begin{align*}
    \kappa:=\lim_{k\to+\infty}
    \frac{\lambda(B_k(x))}{C(B_k(x))}\in(0,+\infty)
\end{align*}
is independent of $x$ and that the convergence is locally uniform in $x$.
Assume further that, for each fixed $k$, the series
\begin{align*}
    \sum_{j=k}^{+\infty}
    \frac{m(B_j(x))}{W(B_j(x),B_{j-1}(x))}
\end{align*}
converges and is locally bounded in $x$, and suppose that the coefficient in Lemma
\ref{lem:relation_partialn_and_g} converges locally
uniformly to a constant $\kappa_W\in(0,+\infty)$ independent of $x$. Then
\begin{align*}
    G_W=L_C^{-1}\text{ on }\mathcal{S}_0(X)
    \quad\Longleftrightarrow\quad
    W(B,B')=\frac{1}{\kappa}
    \frac{m(B)\lambda(B)\lambda(B')}{C(B)}.
\end{align*}
For the weight on the right-hand side, $\kappa_W=\kappa$.","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-26T19:26:00.617324+00:00","domain":"probability theory","id":"claim_806e19481bf8becc5af0d9658e8af2bbc58bb3af5a58593c607a44d065207374","kind":"concept","schema_version":1,"statement":"[Lemma 61 ({\cite[Lemma 3.2) of arXiv:2510.27589, 'Geodesic switches and exceptional times in dynamical Brownian last passage percolation'] {Dau23}}]

