{"assumptions":[],"created_at":"2026-10-26T19:47:01.667941+00:00","domain":"probability theory","id":"claim_80b3d5c2f354f0cfaf6fb78f5f96eef7a72f08447300dd403783aa1ce502e074","kind":"theorem","schema_version":1,"statement":"[Prop 10 of arXiv:2604.24189, 'Malliavin calculus and densities for chaos-driven stochastic differential equations'] Let $F=\{F_t=(I_q(f_t^1),\ldots,I_q(f_t^m))\,,\;t\in \R_+\}$ be an $\R^m$-valued chaos process on an abstract Wiener space $(\Omega,\mathcal{F},\P,\mathfrak{H})$, and assume that $F$ satisfies hypothesis $\mathbf{(H_2)}$ with $H\in(\tfrac{1}{2},1)$.
	Let $R=\{R^h_{t,\varepsilon}\,;\;t\in\R,\, \varepsilon\in\R,\, h\in\HHH\}$ and $S=\{S^{h}_{t,\varepsilon}\,;\;t\in\R,\, \varepsilon\in\R,\, h\in\HHH\}$ be the $\R^m$-valued stochastic processes defined, respectively, by
 \begin{align}
	R_{t,\varepsilon}^h=F_t(\bullet + \varepsilon\,j(h)) \quad \text{ and } \quad S^{h}_{t,\varepsilon} = \sum_{k=0}^{q}  \frac{\varepsilon^k}{k!}\langle D^k F_t,h^{\otimes k} \rangle_{\mathfrak{H}^{\otimes k}}.
 \end{align}
Then the following hold:
\begin{enumerate}[(a)]
	\item $S$ is a version of $R$;
	\item for every $h\in \HHH$, almost every $\omega\in\Omega$ and every $\varepsilon\in\R$, one has $S^{h}_{\star,\varepsilon}(\omega)\in W_{2}^{1-\alpha}\left(0, T ; \mathbb{R}^{m}\right)$;
	\item for every $\beta\in(0,H-\tfrac{1}{2})$ and $1-\alpha = H-\beta$, and for almost every $\omega\in\Omega$, the map from $\R$ into $W_{2}^{1-\alpha}\left(0, T ; \mathbb{R}^{m}\right)$ defined by $\varepsilon\mapsto S^{h}_{\star,\varepsilon}(\omega)$ is of class $\mathcal{C}^{\infty}$. Moreover, for every $h\in \HHH$, almost every $\omega\in\Omega$, every $\varepsilon\in\R$ and every $\ell \in \N$,
	$$
\frac{d^\ell}{d\varepsilon^\ell} S^{h}_{\star,\varepsilon}(\omega)= \left\{
\begin{array}{lcl}
\sum_{k=l}^{q}\frac{\varepsilon^{k-l}}{k!} \left<D^kF_\star(\omega) ,h^{\otimes k}\right>_{\HHH^{\otimes k}}, & \text{if }& 0 \leq \ell \leq q\\
0,&  \text{if }& \ell >q.
\end{array}\right.
$$
\end{enumerate}","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T11:32:18.841581+00:00","domain":"probability theory","id":"claim_80b70296a67ba8a2c390c2d7591c91c1f131b648471e844d270d075b6d6b5a52","kind":"theorem","schema_version":1,"statement":"[Corollary 18 of arXiv:2609.03831, 'On flows generated by square-integrable vector fields'] Let $\rho\in L^\infty(\R; L^2(\R^d))$ be a solution of \eqref{CE}
