\end{equation} for all $N$ and $\np=\np(N)$ large enough. (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T12:43:43.440725+00:00","domain":"probability theory","id":"claim_80f9bee1d4b777429488fe8f352fe4de308b26de02c93b9e064f1fd24bfce76a","kind":"concept","schema_version":1,"statement":"[Theorem thm:SobolevPoincare of arXiv:2509.04155, 'An Approach to Sub-Gaussian Heat Kernel Estimates via Analysis on Metric Spaces'] Let $1 \leq p \leq q$, $(\mathcal{F}_p,\Gamma_p,\Psi)$ be a $p$-energy structure, $\Theta$ be a scale function and $\nu$ be a Borel measure of $X$.
    Then the following two conditions are equivalent.
    \begin{enumerate}[label=\textup{(T\arabic*)}, leftmargin=*]

        \vspace{2pt}
        \item 
        There is a constant $K \geq 1$ such that for all $x \in X$ and $r \in (0,\diam(X))$,
        \begin{equation*}
            \nu(B(x,r))^{\frac{1}{q}} \leq K \Theta(x,r) \left( \frac{\mu(B(x,r))}{\Psi(x,r)} \right)^{\frac{1}{p}}
        \end{equation*}
        \vspace{2pt}
        \item 
        There are constants $C,\sigma \geq 1$ such that for all $x \in X$, $r \in (0,\diam(X))$ and $f \in \mathcal{F}_p$,
        \begin{equation*}
    \left(\int_{B(x,r)} \abs{\tilde{f} - f_{B(x,r)}}^{q} \, d\nu \right)^{\frac{1}{q}} \leq C \Theta(x,r) \left(\int_{B(x,\sigma r)} d\Gamma_p\Span{f} \right)^{\frac{1}{p}}
        \end{equation*}
    \end{enumerate}
    Here $\tilde{f}$ is the precise representative given in (equation eq:Exact of the paper).
    This equivalence is quantitative in the sense that the constants appearing in (T2 of the paper) \textup{(}resp. (T1 of the paper)\textup{)} depend only on the constants in (T1 of the paper) \textup{(}resp. (T2 of the paper)\textup{)}, the constants appearing in (eq:PI of the paper),(eq:UCap of the paper), (equation eq:muDoubling of the paper), (equation eq:RadDiam of the paper), the constants associated with $\Psi$ and $\Theta$ in (equation eq:Psi of the paper), $p$ and $q$. (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T13:41:28.180692+00:00","domain":"probability theory","id":"claim_80fb933ba1ffa3b07ad4f3f7a122d3e1e18279e79360649c390a38c5deb01ef5","kind":"concept","schema_version":1,"statement":"[Conjecture of arXiv:2511.10630, 'Cutoff for generalised Bernoulli--Laplace urn models'] Let $d, \mu, \gamma$, and $q$ be as in Theorem~(thm:shuffle of the paper). Then the following hold.
    \begin{enumerate}[label=(\alph*)]
        \item The multi-stack random-to-random shuffle chain $\mathbf{X}^{\textup{shuf}}$ exhibits cutoff around time
        \begin{equation*}
            T \coloneqq n \log n \cdot \max\set{\frac{1}{2\gamma}, \frac{3}{4}}.
        \end{equation*}

        \item The restricted random-to-random shuffle chain $\mathbf{X}^{\textup{res-shuf}}$ exhibits cutoff around time
        \begin{equation*}
            T \coloneqq n \log n \cdot \max\set{\frac{1}{2\gamma}, \frac{3}{4q}}.
        \end{equation*}
    \end{enumerate} (Stated as a conjecture by the paper; open unless the paper says otherwise.)","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-26T19:37:51.456558+00:00","domain":"probability theory","id":"claim_80fdf5337e182cb059598b4b09a671969f7585bf417ef6e1261e6b9ffba99d5b","kind":"concept","schema_version":1,"statement":"[Lem 18 of arXiv:2604.03777, 'Equilibrium fluctuations for a multi-species particle system with long jumps'] For every $n \in \mathbb{N}_+$, it holds
\begin{align} 
 \sup_{r \in [0,T]} \Bigg\{ \frac{1}{n} \sum_{x} \big[  \widehat{\mathbb{L}}_{n, \lambda}^{ \gamma} H ( \tfrac{x + q_n^r }{n}  ) \big]^{2}  \Bigg\} \leq | \lambda| K_n C(\gamma,H).
\end{align}
Moreover, if $H \in C_c^{2}(\mathbb{R})$, then the role of $C(\gamma,H)$ above is fulfilled by some constant $C(H)$ satisfying \eqref{Cinvshift}. (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-26T20:24:59.502666+00:00","domain":"probability theory","id":"claim_81021bd71bf24efb630dbb1caf9c0adf2aadc9f257382a495db8f338ed505f32","kind":"lemma","schema_version":1,"statement":"[Lemma 53 of arXiv:2605.10150, 'Rough path theory and an introduction to rough partial differential equations'] Let $\bfx = (X,\bbx) \in \scrc^{\alpha}([0,T],V)$ be a rough path for some index $\alpha \in (\frac{1}{3},\frac{1}{2}]$. Furthermore, let $\xi \in W$ be arbitrary, and let $(Y,Y') \in \scrd_X^{2 \alpha}([0,T_0],W)$ be a local solution to the RDE \eqref{RDE} with $Y_0 = \xi$ for some $T_0 \in (0,T]$. Let $s,t \in [0,T_0]$ with $s \leq t$ be arbitrary, and define the interval $I := [s,t]$. Then we have
\begin{align*}
| R_{s,t}^Y | &\leq C \Big( 1 + \| Y \|_{\alpha;I} + \| X \|_{\alpha;I} \| R^{f(Y)} \|_{2 \alpha;I}
\\ &\qquad\quad + \| \bbx \|_{2\alpha;I} ( 1 + \| Y \|_{\alpha;I} ) \Big) |t-s| + C | \bbx_{s,t} |,
\end{align*}
where the constant $C > 0$ depends on $\xi$, $\alpha$, $T$, $\| f_0 \|_{\Lip}$ and $\| f \|_{C_b^{2\alpha,2}}$.","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T14:31:57.858073+00:00","domain":"probability theory","id":"claim_8104f716ed330a4a47b235ba6b39299e4cc53e02d399351257ff144080ecdb2d","kind":"concept","schema_version":1,"statement":"[Theorem th:IB of arXiv:2510.10299, '\Large Sparse graphs and their Benjamini-Schramm limits: a spectral tour'] Let $G = (V, E)$ be a finite graph, and let $A$, $B$ and $D$ be its adjacency, non-backtracking and degree diagianol operators ($D \varphi(v) = \deg(v) \varphi(v)$). For all $z \in \mathbb{C}$, we have:
\begin{equation}
\det(z 1_{E} - B) = (z^2 - 1)^{\chi - 1} \det(z^2 1_V - z A + D - 1_V),
\end{equation}
where $1_V$ and $1_{E}$ are the identity operators on $\mathbb{C}^V$ and $\mathbb{C}^{E}$, respectively, and $\chi = |E|/2 - |V| + 1$ is the Euler characteristic of the graph. (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-26T20:24:47.653367+00:00","domain":"probability theory","id":"claim_8105970df1f1a6446dc8d35f8e3b8640d5ffc4b7183f4382d590e5a76bdb721e","kind":"theorem","schema_version":1,"statement":"[Thm 4 of arXiv:2605.07059, 'Modified ruin probability for a Cram{\'e}r-Lundberg model driven by a compound mixed Poiss'] Assume that $\ell_1<c/\mu$ and $G(\{\ell_1\})=0$. Suppose that there exist $\delta>0$, $B,C_1,D_1,R_1>0$, and $b>0$ such that:
\begin{enumerate}
\item$G$ has a density $g$ on $(\ell_1-\delta,\ell_1)$ and $g(\ell_1-z)\sim Bz^{b-1}$ as $z\downarrow0$;
\item the fixed-intensity theorem holds at $\ell=\ell_1$, with constant $C_{\ell_1}$, and for every $M>0$,
\[
\sup_{0\le v\le M}\left|\frac{\psi_{\rm cl}(u,\ell_1-v/(D_1u))}{C_1e^{-R_1u}e^{-v}}-1\right|\to0,
\]
\[
\sup_{0\le v\le M}\left|\frac{\psi_{\ell_1-v/(D_1u)}(u)}{\psi_{\rm cl}(u,\ell_1-v/(D_1u))}-C_{\ell_1}\right|\to0;
\]
\item the adjustment coefficient $R(\ell)$ exists on $(\ell_1-\delta,\ell_1]$, satisfies $R(\ell_1)=R_1$, is differentiable at $\ell_1$ with $R'(\ell_1)=-D_1$, and there is $\eta>0$ such that $R(\ell)\ge R_1+\eta$ for $\ell\le \ell_1-\delta$.
\end{enumerate}
If $\psi$ is continuous or monotone on $(-\infty,0)$, then
\[
\psi(u)\sim C_{\ell_1}\,\psi_{\rm cl}(u)\sim C_{\ell_1}\frac{BC_1\Gamma(b)}{(D_1u)^b}e^{-R_1u},\qquad u\to\infty.
\]","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-28T00:48:45.306527+00:00","domain":"probability theory","id":"claim_81071533925e27592790529f29396671dc7c33e7ca28a51c4a5f2e92e7a6f8cd","kind":"concept","schema_version":1,"statement":"[Proposition eq:seat_psi of arXiv:2411.14818, 'Scaling limits of solitons in the Box-Ball system'] Suppose that $\eta \in \Omega$. Then, for any $k, \ell \in {\mathbb{N}}$, $\sigma \in \{\uparrow, \downarrow\}$ and $x \in {\mathbb{Z}}$, we have 
                    \begin{align}
                        \Psi_{k}\left( \eta \right)^{\sigma}_{\ell}(x) = \eta^{\sigma}_{ k + \ell}\left(s_{k}\left(\eta, x + \xi_{k}\left(\eta, 0\right) \right) \right).
                    \end{align}
                In addition, we have 
                    \begin{align}
                        \Psi_{k }\left( \Psi_{\ell}\left(\eta\right) \right)\left( \ \cdot \ \right) =  \Psi_{k + \ell }\left( \eta\right)\left( \ \cdot \ \right),
                    \end{align}
                and 
                    \begin{align}
                        \zeta_{k}\left(\Psi_{\ell}\left( \eta \right), \ \cdot \ \right) = \zeta_{k+\ell}\left(\eta, \ \cdot \ \right) .
                    \end{align} (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-26T19:31:20.861167+00:00","domain":"probability theory","id":"claim_8109d193f3c60c2fefa54e5626df00c1392d4870811c703d3a0f34d0c84ca6f9","kind":"concept","schema_version":1,"statement":"[Theorem 3 of arXiv:2506.10817, 'On the Weak Error for Local Stochastic Volatility Models'] Let $X^h, Y$ be defined as above, let Assumption \ref{Aspt_new} hold and assume that $f:\mathbb{R}\rightarrow \mathbb{R}$ is $l$-times weakly differentiable with derivatives which are functions of polynomial growth. Then, for $h \in (0,1)$, 
    \begin{align*}
        \Bigl| \E\bigl[f\bigl(X_T^h\bigr)\bigr]-\E\bigl[f\bigl(Y_T\bigr)\bigr] \Bigr|\lesssim \begin{cases}
            \sqrt{h} & \text{if } l=1, \\
