{"assumptions":[],"created_at":"2026-10-27T19:55:37.869037+00:00","domain":"probability theory","id":"claim_81188c88dbcb8a5ebad93a698ff77de0dc607ebb11233805096ef731bf46a56c","kind":"theorem","schema_version":1,"statement":"[Theo eq:xiinfsup of arXiv:2605.06488, 'Continuous-state branching processes with L\'evy-Khintchine drift-interaction: Laplace dua'] Let $\hat\Sigma$ and $\Phi$ be regularly varying mechanisms respectively at $\infty$ and $0$.  Suppose that  the potential measure $U$ associated to $\Phi$ admits a density that is monotone in a neighbourhood of  $\infty$.  Assume that the conditions $\negHone$, $\negHhattwo$, $\hatHone$  and $\Htwo$ hold. Consider $Y^{\mathrm{e}0}$ the extended $\mathrm{CBDI}(\hat\Psi,\Psi)$ at $0$.
\begin{enumerate}
\item If $\hat\Sigma$ and $\Phi$ are regularly varying, at $\infty$ and $0$ respectively, with index $1$, then 
\[\overline{\theta}_{\,\scriptscriptstyle\Phi,\hat{\Sigma}}=\frac{1}{\underline{\varrho}_{\,\scriptscriptstyle\hat\Sigma,\Phi}}=\underset{z\rightarrow 0}{\limsup} \frac{\Phi(z)}{z^2\hat\Sigma(1/z)}, \ \underline{\theta}_{\,\scriptscriptstyle\Phi,\hat{\Sigma}}=\frac{1}{\overline{\varrho}_{\,\scriptscriptstyle\hat\Sigma,\Phi}}=\underset{z\rightarrow 0}{\liminf} \frac{\Phi(z)}{z^2\hat\Sigma(1/z)} .\]
In particular if $\overline{\theta}_{\,\scriptscriptstyle\Phi,\hat{\Sigma}}<1$ then $\underline{\varrho}_{\,\scriptscriptstyle\hat\Sigma,\Phi}>1$, and in this case  $0$ is accessible and absorbing for $Y^{\mathrm{e}0}$ ($0$ is an exit). Similarly, if $\underline{\theta}_{\,\scriptscriptstyle\Phi,\hat{\Sigma}}>1$ then $\overline{\varrho}_{\,\scriptscriptstyle\hat\Sigma,\Phi}<1$ and $0$ is inaccessible and non-absorbing ($0$ is an entrance).
\item Let $\alpha\in (0,1)$. Assume that $\hat{\Sigma}(x)=x^{2-\alpha}\hat{L}(x)$ and $\Phi(x)=x^{\alpha}\ell(x)$ with $\hat{L}$ and $\ell$ slowly varying at $\infty$ and $0$ respectively. Then,

\[\overline{\theta}_{\,\scriptscriptstyle\Phi,\hat{\Sigma}}=\frac{1}{\Gamma(2-\alpha)\Gamma(\alpha)}\frac{1}{\underline{\varrho}_{\,\scriptscriptstyle\hat\Sigma,\Phi}}, \ \underline{\theta}_{\,\scriptscriptstyle\Phi,\hat{\Sigma}}=\frac{1}{\Gamma(2-\alpha)\Gamma(\alpha)}\frac{1}{\overline{\varrho}_{\,\scriptscriptstyle\hat\Sigma,\Phi}}.\]
Define moreover the $[0,\infty]$-valued parameters:
\begin{equation}\underline{\xi}:=\underset{z\rightarrow 0}{\liminf} \frac{\ell(z)}{\hat{L}(1/z)}, \ \overline{\xi}:=\underset{z\rightarrow 0}{\limsup} \frac{\ell(z)}{\hat{L}(1/z)}.\end{equation}
Then, $\overline{\theta}_{\,\scriptscriptstyle\Phi,\hat{\Sigma}}=\frac{1}{\Gamma(2-\alpha)}\overline{\xi},\  \underline{\theta}_{\,\scriptscriptstyle\Phi,\hat{\Sigma}}=\frac{1}{\Gamma(2-\alpha)}\underline{\xi}$, and $\overline{\varrho}_{\,\scriptscriptstyle\hat\Sigma,\Phi}=\frac{1}{\Gamma(\alpha)\underline{\xi}},\  \underline{\varrho}_{\,\scriptscriptstyle\hat\Sigma,\Phi}=\frac{1}{\Gamma(\alpha)\overline{\xi}}$,
\begin{enumerate}
\item If $\underline{\xi}>\Gamma(2-\alpha)$, $0$ is an entrance,
\item if $\frac{1}{\Gamma(\alpha)}<\underline{\xi}, \overline{\xi}<\Gamma(2-\alpha)$, $0$ is regular,
\item if $\overline{\xi}<\frac{1}{\Gamma(\alpha)}$, $0$ is an exit.
\end{enumerate}
\end{enumerate}","status":"unverified"}

