{"assumptions":[],"created_at":"2026-10-26T19:36:05.000540+00:00","domain":"probability theory","id":"claim_8191e18e197b6032175e0d029bda2765831ed1a389b2f5a88492ce358dcd734d","kind":"concept","schema_version":1,"statement":"[Proposition 95 of arXiv:2604.01685, 'Probability with Measure\footnote{Lecture notes. University of Ljubljana.}'] Let $(\Omega,\AA,\PP)$ be a probability space. Some methods for directly computing the conditional expectation are as follows. 
	\begin{enumerate}[(I)]
		\item (Discrete conditioning $\sigma$-field.) Let $\II\in 2^\AA$ be a countable partition of $\Omega$. Then for $X\in \AA/\mathcal{B}_{[-\infty,\infty]}$ with $\PP [X^+]\land \PP [X^-]<\infty$, $\PP$-a.s. 
		\begin{equation}
\PP[X\vert \sigma_\Omega(\II)]=\sum_{I\in \II\cap \PP^{-1}((0,1])}\PP[X\vert I]\mathbbm{1}_I
		\end{equation}
(so $\PP[X\vert \sigma_\Omega(\II)]=\PP[X\vert I]$ on\footnote{No a.s. qualifier is needed here. True, conditional expectations are in general defined only up to a.s. equality. However, in this case the measurability requirement forces the constancy of $\PP_{\sigma_\Omega(\II)}(X)$ on every member of $I\in\II$ and then the ``testing condition'' determines this value provided $\PP(I)>0$.} $I$, for all $I\in \II$ with $\PP(I)>0$).
		\item Let $(F,\FF)$ and  $(E,\EE)$  be measurable spaces, $X\in \AA/\FF$, $Y\in \AA/\EE$ two random elements. Let also $h\in (\FF\otimes \EE)/\mathcal{B}_{[-\infty,\infty]}$ be such that $\PP[(h\circ (X,Y))^+]\land \PP[(h\circ (X,Y))^-]<\infty$. 
		\begin{enumerate}[(1)]

			\item (Absolutely continuous random elements.) Suppose $\ee$ is a $\sigma$-finite measure on $(E,\EE)$ and $\ff$ a $\sigma$-finite measure on $(F,\FF)$ and suppose that $\PP_{(X,Y)}\ll\ff\times \ee$ (which implies $\PP_X\ll \ff$ and $\PP_Y\ll\ee$); denote $f_{12}:=\frac{\dd \PP_{(X,Y)}}{\dd(\ff\times \ee)}$ and $f_2:=\frac{\dd \PP_Y}{\dd \ee}$. Then $\PP$-a.s. 
			\begin{equation}
\PP [h (X,Y)\vert \sigma(Y)]=c( Y),
			\end{equation}  where $$c(y):=\int h(x,y)\frac{f_{12}(x,y)}{f_2(y)}\ff(\dd x)\mathbbm{1}_{\{f_2>0\}}(y)\text{ for }y\in E.$$ Furthermore, it is the case that $c\in \EE/\mathcal{B}_{[-\infty,\infty]}$.

			\item (Independent maps.) Let $\GG$ be a sub-$\sigma$-field of $\AA$ such that $Y\in \GG/\mathcal{E}$ and $X$ is independent of $\GG$ under $\PP$. Then $\PP$-a.s. 			
			\begin{equation}
			\PP [h (X,Y)\vert \GG]=d(Y),
			\end{equation} where $$d(y):=\PP[h (X,y)]\text{ for } y\in E.$$ Furthermore, it is the case that $d\in \EE/\mathcal{B}_{[-\infty,\infty]}$. 

		\end{enumerate}
	\end{enumerate} (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-26T19:20:15.492606+00:00","domain":"probability theory","id":"claim_81944f7e9e2467f50cad0d8b15882fad1963fe5aa5ac28160525357fb9219e04","kind":"concept","schema_version":1,"statement":"[Thm 1 of arXiv:2512.02538, 'On the spectral geometry of Liouville quantum gravity'] \begin{equation}
