{"assumptions":[],"created_at":"2026-10-27T21:30:14.225677+00:00","domain":"probability theory","id":"claim_82eb3630e41c03fd598fb24d0e6eaec444010ddcc94432c19cc7812c0b9f4874","kind":"concept","schema_version":1,"statement":"[Prop number variance of arXiv:2608.23156, 'Disc counting statistics of the real Ginibre ensemble'] Let $N$ be a positive even integer, and $R\equiv R_N$ be a positive real number.
    \begin{enumerate}[label=\textup{(\roman*)}]
        \item \textup{\textbf{(Bulk)}}
        Suppose that $R\in(0,1)$ is fixed. Then 
        \begin{equation}
            \lim_{N\to\infty}\frac{ \operatorname{Var} \mathcal{N}_N^{ \rm c}(R) }{ \sqrt{2N/\pi} } = 2R , \qquad  \lim_{N\to\infty}\frac{ \operatorname{Var} \mathcal{N}_N^{\rm r}(R) }{ \sqrt{2N/\pi} } = (2-\sqrt{2}) R,
        \end{equation}
        and
        \begin{equation}
            \lim_{N\to\infty}  \dfrac{\operatorname{Cov}( \mathcal{N}_N^{ \rm r }(R), \mathcal{N}_N^{ \rm c }(R) )  }{  \sqrt{2N/\pi} } = -(2-\sqrt{2}) R.
        \end{equation}
        Consequently, we have
        \begin{equation} 
            \lim_{N\to\infty}\frac{ \operatorname{Var} \mathcal{N}_N(R) }{ \sqrt{2N/\pi}  } = \sqrt{2}R.
        \end{equation}

        \item \textup{\textbf{(Edge)}} 
        Suppose that $R = 1- s/\sqrt{2N}$ for some $s\in\mathbb{R}$. Then 
        \begin{equation}
            \lim_{N\to\infty}\frac{ \operatorname{Var} \mathcal{N}_N^{ \rm c }(R) }{ \sqrt{2N/\pi} } = \sqrt{2}\,\mathcal{F}(s) + 2-\sqrt{2}, \qquad  \lim_{N\to\infty}\frac{ \operatorname{Var} \mathcal{N}_N^{ \rm r }(R) }{ \sqrt{2N/\pi} } = 2-\sqrt{2},
        \end{equation}
        and
        \begin{equation}
             \lim_{N\to\infty} \dfrac{  \operatorname{Cov}( \mathcal{N}_N^{ \rm r }(R), \mathcal{N}_N^{ \rm c }(R) )  }{  \sqrt{2N/\pi} } = -(2-\sqrt{2}),
        \end{equation}
        where
        \begin{equation} 
            \mathcal{F}(s)  :=  \sqrt{ 2\pi }   \int_{-\infty}^{s} \frac{\operatorname{erfc}(t)\operatorname{erfc}(-t)}{4}  \,dt.
        \end{equation}
        Consequently, we have
        \begin{equation} 
            \lim_{N\to\infty} \frac{\operatorname{Var} \mathcal{N}_N(R)}{\sqrt{2N/\pi}} = \sqrt{2} \, 
            \mathcal{F}(s).
        \end{equation} 

        \item \textup{\textbf{(Outside)}}
        Suppose that $R \in (1,\infty]$ is fixed. Then 
        \begin{equation}
            \lim_{N\to\infty}\frac{\operatorname{Var} \mathcal{N}_N^{ \rm c }(R) }{\sqrt{2N/\pi}} = 2-\sqrt{2}, \qquad \lim_{N\to\infty}\frac{\operatorname{Var} \mathcal{N}_N^{\rm r  }(R) }{\sqrt{2N/\pi}} = 2 - \sqrt{2},
        \end{equation}
        and
        \begin{equation}
            \lim_{N\to\infty} \frac{ \operatorname{Cov}( \mathcal{N}_N^{ \rm r }(R), \mathcal{N}_N^{ \rm c }(R) ) }{ \sqrt{2N/\pi} } = -(2-\sqrt{2}).
        \end{equation}
        Consequently, we have
        \begin{equation} 
            \lim_{N\to\infty} \frac{\operatorname{Var} \mathcal{N}_N(R) }{\sqrt{2N/\pi}} = 0.
        \end{equation}
    \end{enumerate} (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-26T20:52:17.371496+00:00","domain":"probability theory","id":"claim_82ef630602da729d6e7338e27eae3728444d8380d72516f4f4026be0c49c2947","kind":"definition","schema_version":1,"statement":"[Definition 16 of arXiv:2606.03661, '2606.03661'] Let $X_{\alpha, \nu}$ be a random variable with Laplace transform of the density $f_{X_{\alpha, \nu}}(\cdot)$ given in \eqref{LTpsi}, then we define the process $Y_{\alpha,\nu}:=\left\{ Y_{\alpha,\nu}(t) \right\}_{t \geq 0}$ as follows

