		\begin{equation}
			\sum_{\substack{q\geq 0 \\ \tau_q\prec\dots\prec\tau_1\prec\tau}}\sum_{k\geq 0} \frac{1}{k!}{\bf C}_k(Z_{\downarrow^k\tau/\tau_1},\dots,Z_{\tau_{q-1}/\tau_q}, Z_{\tau_q}^\circ) = 0.
