{"assumptions":[],"created_at":"2026-10-27T11:17:33.997396+00:00","domain":"probability theory","id":"claim_8352dcdc54b15a0b22cc1e0999098c3ffc4b409ac222133bcfeb38d83b19356a","kind":"theorem","schema_version":1,"statement":"[Proposition 14 of arXiv:2609.03403, 'Hyperpositive functions, sector bounded functions and a trace formula'] Let $G$ be a $\mathbb C^{m\times m}$-valued contractive function satisfying $\det G(z)\not \equiv 0$, analytic in $\mathbb C_r$ and extended to $\mathbb C\setminus i\mathbb R$ via
        \eqref{Gext}. The function $K_G(z,w)$ so extended is positive definite on
        \begin{equation}

        \Omega(G)=\mathbb C\setminus\left\{i\mathbb R\cup\left\{z\in\mathbb C\setminus i\mathbb R,
            \det G(z)=0\right\}\right\}.
\end{equation}
        The corresponding reproducing kernel Hilbert space of functions analytic in $\Omega(G)$, denoted by $\mathcal H_{ext}(G)$, has the
        following properties, where $\alpha\in\Omega(G)$:\smallskip

       $(1)$ $\mathcal H_{ext}(G)$ is $R_\alpha$-invariant.\\
$(2)$ For every $c\in\mathbb C^m$, the function $R_\alpha Sc\in\mathcal H(G)$ and for $\alpha$ such that $\det S(\alpha)\not=0$ it holds that
\begin{equation}

  (R_\alpha G)(z)=-2\pi K_G(z,-\overline{\alpha})G(-\overline{\alpha})^{-*},
\end{equation}
\begin{equation}
  K_G(\alpha,-\overline{\alpha})=-\frac{1}{2\pi}G^\prime(\alpha)G(\alpha)^{-1}

\end{equation}
and
\begin{equation}
\|R_\alpha Gc\|^2_{\mathcal H(G)}=2\pi c^*\frac{I-G(\alpha)^*G(\alpha)}{\alpha+\overline{\alpha}}c.
\end{equation}
$(3)$ With moreover $\beta\in\Omega(G)$ and $f,g\in\mathcal H_{ext}(G)$,
\begin{equation}
  \langle R_\alpha f,g\rangle_{\mathcal H_{ext}(G)}+  \langle f,R_\beta g\rangle_{\mathcal H_{ext}(G)}+(\alpha+\overline{\beta})
  \langle R_\alpha f,R_\beta g\rangle_{\mathcal H_{ext}(G)}=2\pi g(\beta)^*f(\alpha).

  \end{equation}
  $(4)$ We have
  \begin{equation}
