\de(v_j)\asymp e^{h(v_j)/2}, \qquad \de(v_j)^{2\alpha}\asymp\frac nj, \qquad h(v_j)=\frac1\alpha\log\frac nj+O(1).                   
\end{equation}","status":"unverified"}

