{"assumptions":[],"created_at":"2026-10-27T07:53:39.244529+00:00","domain":"probability theory","id":"claim_848c4a267978bc8d745510fceb6083697283c1deaeefd6629690cc08282d17a4","kind":"concept","schema_version":1,"statement":"[Theorem 7 (Blow-up criteria for the non-critical setting) of arXiv:2608.27054, 'GLOBAL WELL-POSEDNESS FOR THE 2D STOCHASTIC HYPOVISCOUS NAVIER-STOKES EQUATIONS'] Suppose that the conditions of Theorem \ref{thm:localWP} hold (with non-critical $\kappa$), and let $(u, \sigma)$ be the $L^p_\kappa$-maximal solution to \eqref{eq:abstract_eq}. Then
\begin{equation*}
    \mathbf{P}(\sigma < \infty,\sup\limits_{t \in [0, \sigma)} \|u(t)\|_{X_{1 - \frac{1+\kappa}{p}, p}}<\infty) = 0,
\end{equation*}
if $(p,\kappa)$ is non-critical (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-26T20:46:09.856641+00:00","domain":"probability theory","id":"claim_848c4ac1d5aa00878d9bcd1e82bbaf41cdbffd7453df025987a1ec339faf182f","kind":"concept","schema_version":1,"statement":"[Lemma 19 of arXiv:2605.20115, 'Moment bounds on correctors for the degenerate random conductance model'] Suppose that $U,V:\ZZ^d\to\RR$ are non-negative and there exists $p>1$ such that 
    \begin{equation}
        \fint_{B} U^p\,\le\,  \fint_{2B} V^p + C \Big(\fint_{2B}U\Big)^p 
    \end{equation}
    for a constant $C$ and all balls $B$. Then there exists $\bar p>p$ depending on $C$ and $p$ such that for any $p\le q \le \bar p$,
    \begin{equation}
        \fint_{B} U^{q}\,\lesssim \,\fint_{2B} V^{q} + \Big(\fint_{2B}U\Big)^{q}. 
    \end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T13:56:17.356084+00:00","domain":"probability theory","id":"claim_848e4f321b6d716e419668445a6546874ef21864ed3419a798c00e4afbd97be8","kind":"lemma","schema_version":1,"statement":"[Lemma tightness-drift of arXiv:2605.14149, 'The mean-field limit of online stochastic vector balancing'] For each $n$, the empirical measure $\hat{\mu}_n^A$ is ${\mathbb P}$-almost surely contained in the compact set
	\begin{equation*}
		\mathcal{K}_1 \coloneqq \bigg\{\mu\in{\mathcal P}({\mathcal C}): \mu(H_0^1)=1,\ \esssup_{t\in[0,1]} \int_{H_0^1} \dot{\phi}(t)^2\,\mu(d\phi) \leq 1\bigg\}.
	\end{equation*}
	In particular, the sequence $\big\{\mathcal{L}(\hat{\mu}_n^A): n\in{\mathbb N}\big\}\subset {\mathcal P}({\mathcal P}({\mathcal C}))$ is tight.
	If $\nu=\mathcal{N}(0,1)$, the statement holds true if we replace the upper bound $1$ in the definition of $\mathcal{K}_1$ by $2/\pi$.","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T22:52:32.334255+00:00","domain":"probability theory","id":"claim_848eebcb77cb0be81395904beb776b4d0195316bded7d93a05ac7840bed275cc","kind":"theorem","schema_version":1,"statement":"[Proposition prop:reductiontohzero of arXiv:2609.03980, 'Decay Rates and Domain Dependence of a Coupled Wave-Heat System with Spatially Dependant H'] Let $(\Omega,\Omega_w,\Omega_h)$ be a Lipschitz interface triple and let $p:\mathbb{R} \to [0,\infty)$ be a weight function satisfying $p(\lambda)\lesssim |\lambda|$ for all $|\lambda|\gg 1.$ 
    If the generator $A_S^\perp$ of the coupled wave-heat system~(equation eq:1 of the paper) satisfies the residual estimate
    \begin{align*}
        \|(\lambda i +A_S^\perp  )f\|_{\mathbb{H}_1} \gtrsim p(\lambda) \|f\|_{\mathbb{H}_1}, ~~ |\lambda|\gg1,\lambda\in \mathbb{R}
    \end{align*}
    for every $f = (w_1,w_2,h_1)  \in \operatorname{dom}\left(A_S^\perp\right)$ with $h_1=0$, then $A_S^\perp$ even satisfies the estimate
    \begin{align*}
        \|(\lambda i +A_S^\perp  )f\|_{\mathbb{H}_1} \gtrsim \left(\frac{p(\lambda)}{|\lambda|}\right)^2 \|f\|_{\mathbb{H}_1},~~ |\lambda|\gg1,\lambda\in \mathbb{R}
    \end{align*}
    for all $f \in \operatorname{dom}\left(A_S^\perp\right)$.","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T08:26:47.159048+00:00","domain":"probability theory","id":"claim_848f396dceeb4706e36b89e6b1672869770c7615c324d7979b6f0c1654889dd5","kind":"theorem","schema_version":1,"statement":"[Proposition 24 (Reeb correction to the K\"ahler shape conclusion) of arXiv:2608.29406, 'Partially Totally Real Submanifolds of Sasakian Manifolds'] For every PTR-submanifold, every $Z\in\Gamma(\Dperp)$ and $U\in\Gamma(TM)$,
\begin{equation}
 g(A_{\phi Z}U,\xi)=-g(U,Z).
\end{equation}
If, in addition, $F$ is parallel and $\Dperp$ is maximal, then
\begin{equation}
 A_{\phi Z}U\in\Gamma(\Dperp\oplus\langle\xi\rangle).
\end{equation}
Thus the K\"ahler statement $A_{JZ}U\in\mathcal H^\perp$ is replaced by \eqref{eq:AphiZ-split}; its extra component is exactly the Reeb term in \eqref{eq:AphiZ-Reeb}.","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T23:32:34.770304+00:00","domain":"probability theory","id":"claim_849104d5c7ef10f160b041843de469293dd1adb6489c2405ab2dc1330a288bfe","kind":"theorem","schema_version":1,"statement":"[Corollary cor:oszac_p^D_nu of arXiv:2411.08220, 'Nonlocal operators with Neumann conditions'] For $\alpha\in (0,2)$, $t>0$, $x>0$ and $y<0$,
    \begin{align*}
        \mathcal{J}(t,x,y) := \int_D  p_t^D(x,z)\nu(z,y)\,{\rm d}z \approx t^{-1} \Big(1\wedge \frac{|x|}{t^{1/\alpha}}\Big)^{\alpha/2}\Big(1\wedge \frac{|y|}{t^{1/\alpha}}\Big)^{-\alpha/2} p_t(x,y).
    \end{align*}","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T19:35:19.869815+00:00","domain":"probability theory","id":"claim_84917103015f68af1b4778bd13c4718c3fbeeb4e40e7c8c8e5185ca70ec9900d","kind":"theorem","schema_version":1,"statement":"[Thm expander-consensus of arXiv:2609.03856, 'Consensus time for asynchronous $\ell^p$ relaxation: graph dependence'] Fix $1<p<\infty$.  Let $G$ have $n$ vertices and satisfy $h(G)\ge h_0>0$.
For every $f_0\in[-1,1]^V$ and $0<\epsilon\le1$,
\begin{equation}
 \mathbb{E}\tau_p(\epsilon;f_0)\le C_{p,h_0}n\log(n/\epsilon).
\end{equation}
Moreover, at tolerance $1/2$ the globally defined worst-profile consensus
time satisfies
\begin{equation}
 cn\log n
 \le \mathsf T_p(G,1/2)
 \le C_{p,h_0}n\log n.
\end{equation}
Thus, for fixed $p$ and $h_0$, the worst-profile consensus time at fixed
tolerance is exactly of order $n\log n$, with no degree assumption.","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T18:35:57.166103+00:00","domain":"probability theory","id":"claim_84945e84329af3a71c35d46a0a6d87f90aef5aba5554c4b7276c57a12a2de859","kind":"concept","schema_version":1,"statement":"[Proposition Rnsecbase of arXiv:2604.07227, 'Transition probabilities of step-reinforced random walks'] Assume that $\alpha \in [0,1]$, then the elephant polynomials $(R_n(x))_{n\geq 1}$ defined by ((defelepoly of the paper)) can be written as 
    \begin{equation}

    R_n(x) =\sum_{k=0}^{\lfloor \frac{n}{2} \rfloor} (-1)^k \lambda_{n,k}x^{n-2k}(1-x^2)^k, \quad x\in \mathbb{R},
  \end{equation}
  where $\lambda_{n,k}$ $(k=0,1,2\dots, \lfloor n/2 \rfloor)$ are non-negative numbers. Moreover, for any $n\geq 1$,
  \begin{equation}

 e^{-\frac{(1-\alpha)n}{3+\alpha}}\binom{n}{2k} \alpha^k \leq \lambda_{n,k} \leq \binom{n}{2k} \alpha^k, \quad k\in \left\{0,1,\dots, \lfloor \frac{n}{2} \rfloor\right\}.
  \end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T06:21:45.350859+00:00","domain":"probability theory","id":"claim_8497bb2a8cfbe38be8c4272b1be8c7eccb4a94be14e1dc886ec7f84b8cd5bb5c","kind":"concept","schema_version":1,"statement":"[Prop 6 of arXiv:2607.27535, 'Universal topological statistics on \\ triangulated singular spaces'] Let $\phi: K \rightarrow M \subset \RR^D$ be an admissible triangulation and let $\sigma_1, \sigma_2 \in K$ be distinct $d$-simplices. Given points $x_1 \in \phi(\sigma_1)$, $x_2 \in \phi(\sigma_2)$, the following holds for $i=1,2$ if $\|x_1-x_2\|$ is sufficiently small:
    \begin{align*}
        \dist_\euclidean (x_i, \partial_\phi M) \le \frac{2 \|x_1 - x_2\|}{\sin(\Theta_\phi/4)}.
    \end{align*} (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T19:35:19.868910+00:00","domain":"probability theory","id":"claim_849810025afb20fa83bc4fdaaf062ab1db4b8d9d309a89b820500c5060016880","kind":"lemma","schema_version":1,"statement":"[Lem box-poincare of arXiv:2609.03856, 'Consensus time for asynchronous $\ell^p$ relaxation: graph dependence'] For every fixed $1<p<\infty$, all integers $d\ge1$ and $L\ge2$, and every
$f:[L]^d\to\mathbb{R}$,
\begin{equation}
 \sum_{x\in[L]^d}|f(x)-\bar f|^p
 \le C_p d^{\max\{0,p/2-1\}}L^p\mathcal{E}_p(f),
 \qquad \bar f=L^{-d}\sum_xf(x).
\end{equation}
Consequently,
\begin{equation}
 \Phi_p([L]^d)\le C_p
 \begin{cases}
  dL^p,&1<p<2,\\
  d^{p/2}L^p,&p\ge2.
 \end{cases}
\end{equation}","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-26T20:24:59.493077+00:00","domain":"probability theory","id":"claim_849c39fddbfa2deeb7f3de3f4799ad9e3155d60e8c39d448c15af1e14a8f9f08","kind":"concept","schema_version":1,"statement":"[Lemma 5 of arXiv:2605.09459, 'Multipoint connectivity in the branching interlacement process'] Let $d \geq 2$, $a \geq b > 0$. If $f,g : \mathbb{Z}^d \to \mathbb{R}$ are such that $|f(x)| \lesssim \|x\|^{-a}$ and $|g(x)| \lesssim \|x\|^{-b}$, then there exists a constant $C = C(a,b,d)$ such that for all $x \in \mathbb{Z}^d$,
  \[
    |(f*g)(x)| \leq
    \begin{cases}
      C\|x\|^{d-(a+b)} & \text{if } a < d \text{ and } a + b > d,\\
      C\|x\|^{-b} & \text{if } a > d.
    \end{cases}
  \] (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T12:52:05.692172+00:00","domain":"probability theory","id":"claim_849c7e925227abf6044f44387c82109f15797ded402e07af94467ae8b98d0523","kind":"concept","schema_version":1,"statement":"[Thm p:300.3 of arXiv:2602.21277, 'A Limit in Law for the Cover Time and Last Visited Vertex of Wired Planar Domains'] Let $u \geq 0$.
\begin{equation}

\lim_{k \to \infty}
\limsup_{n \to \infty} \mathbb{P} \big( {\mathbf G}_n(u) \setminus 
{\mathbf W}_n^k(u) \neq \emptyset \big) = 0 \,.
\end{equation}
Morevoer,
\begin{equation}

\frac{ \big| {\mathbf W}_n(u) \setminus 
{\mathbf W}_n^k(u) \big|}{\sqrt{n}} \overset{\mathbb{P}}\longrightarrow 0 \,,
\end{equation}
as $n \to \infty$ followed by $k \to \infty$, and 
\begin{equation}

\frac{\big|{\rm W}_n^{[r_n, n-r_n]}(u)  \big|}{\sqrt{n}}
	\overset{\mathbb{P}}{\underset{n \to \infty}\longrightarrow} 0 \,.
\end{equation}
as $n \to \infty$. (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T23:11:09.324324+00:00","domain":"probability theory","id":"claim_849d6a1809e7c6b36f8d0f633718f4eec5639fd8168f1db8c6477532934b78eb","kind":"theorem","schema_version":1,"statement":"[Prop prop-cond-on-ext of arXiv:2411.06301, 'Inverting the operation of conditioning a branching process on extinction'] Let $X = \{X(n) \}_{n\in\mathbbm N_0}$ be a positive regular, non-singular $d$-type branching process  (Definition~(def-bp-basic of the paper)) with generating function $f$. Let $E$ be the event that the process eventually becomes extinct. For $k\in \{1,\dots,d\}$, define the extinction probability 
\begin{equation*}
a_k := \mathbbm P_k\mathopen{}\mathclose\bgroup\originalleft[ E \aftergroup\egroup\originalright] .
\end{equation*} 
Then the only solutions of $f(q) =q$ in the unit cube $[0,1]^d$ are $a = (a_1,\dots,a_d)$ and $(1,\dots,1)$. 

Suppose that $0 < a_k < 1$ for every $k \in \{1,\dots,d\}$. Then for each $k\in\{1,\dots,d\}$, the $\mathbbm P_k$-conditional law of $X$ given $E$ is that of a branching process with offspring distribution determined by 
\begin{equation} 
\mathbbm E_k\mathopen{}\mathclose\bgroup\originalleft[ F(X_1(1) , \dots, X_d(1)) \,|\, E \aftergroup\egroup\originalright] 
 = \frac{1}{a_k} \mathbbm E_k\mathopen{}\mathclose\bgroup\originalleft[ F(X_1(1),\dots,X_d(1)) \prod_{j=1}^d a_j^{X_j(1)} \aftergroup\egroup\originalright]   
\end{equation} 
for every bounded measurable function $F : \mathbbm N_0^d \to \mathbbm R$. Moreover, this branching process is subcritical.","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T21:09:59.185942+00:00","domain":"probability theory","id":"claim_849d75568c4467c9f7a801275ee187052074f73b181599b2754b4a4a1843dcc2","kind":"theorem","schema_version":1,"statement":"[Proposition prop:canonical of arXiv:2608.05123, 'A central limit theorem for the random assignment problem'] Adjoin an independent uniform root and use its shortest-path
potential.  After the root and tree are forgotten, the induced law
\(\mathbb P_n^{\mathrm{can}}\) of \((D,U)\) has density
\begin{equation}
 \frac{n!}{n^{2n-1}}\,
 \1_{\{0\le D_i\le n\ \forall i\}}
 \prod_{i\ne j}\rho_n(D_i+U_j-U_i)\,\mathfrak T(w)
\end{equation}
with respect to \(\,\mathrm d D\,\,\mathrm d U\).  Its unnormalized partition
function is
\begin{equation}
 Z_n^{\rm can}=\frac{n^{2n-2}}{(n-1)!}.
\end{equation}
The translation \(D_i=A_i+U_i\) has unit Jacobian and gives the
equivalent density
\[
 \frac{n!}{n^{2n-1}}\,
 \1_{\{0\le A_i+U_i\le n\}}
 \prod_{i\ne j}\rho_n(A_i+U_j)\,
 \mathfrak T\bigl((\omega_n(A_i+U_j)\1_{i\ne j})_{ij}\bigr).
\]
Moreover the identities (equation eq:minplus of the paper) hold exactly.","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-26T20:58:28.473647+00:00","domain":"probability theory","id":"claim_84a02cb7d3ae4470d1b81610558e96a33f252347375450d55125e514be2c0ed0","kind":"lemma","schema_version":1,"statement":"[Lemma 54 (Rectangular trace-endpoint identification) of arXiv:2606.29292, 'Intrinsic Gaussian Tensor Geometry and Random Operator Spectra'] Let $m\ge1$.  For every algebraic order-$m$ kernel $K$,
\begin{equation}

 (C_m^{\mathrm{HP}})^{-1}\norm K_{\mathfrak T_{m,1}^{\Sigma}}
 \le \norm{\cT_K^{(m)}}_{L^1(\Omega;\Sch_1)}
 \le \norm K_{\mathfrak T_{m,1}^{\Sigma}},
\end{equation}
where $C_m^{\mathrm{HP}}<\infty$ depends only on $m$.  The constant is
independent of the dimensions of the stochastic supports and of the
deterministic Hilbert spaces.","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T21:30:14.229709+00:00","domain":"probability theory","id":"claim_84a11ae79635f85448e8c3de93406653f38d6a91398f454515605d2c3ab61f6c","kind":"theorem","schema_version":1,"statement":"[Proposition prop:strict of arXiv:2608.23203, 'Well-posedness of fully coupled McKean--Vlasov\\ FBSDEs with jumps under full-tuple law de'] Let $n=m=1$, $d\ge1$ and $G=1$, and fix $\beta_1>0$. For every $0<\varepsilon<\beta_1$,
the drift
\begin{equation}
b(t,\theta,\mu):=-\beta_1 y+\varepsilon\,g_0\bigl(y-m_Y(\mu)\bigr),\qquad
g_0(r):=\max\{-1,\min\{1,r\}\},
\end{equation}
with $m_Y(\mu):=\int_{\mathcal H}y\,\mu(\mathrm{d}\theta)$ the $Y$-marginal mean, is
free-measure $W_2$-Lipschitz with constant $\beta_1+\varepsilon$ and satisfies, along
all $(\Theta,\mu),(\Theta',\mu')\in\mathcal D_t$,
\begin{equation}
\mathbb{E}\inner{\delta b}{\delta Y}\ \le\ -(\beta_1-\varepsilon)\,\mathbb{E}|\delta Y|^2 ;
\end{equation}
yet for every $\beta\ge0$ the pointwise bound
$\inner{\delta b}{\delta y}\le-\beta\,|\delta y|^2$ fails at a pair of free inputs with
$\theta\in\operatorname{supp}\mu$ and $\theta'\in\operatorname{supp}\mu'$.","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T07:29:27.942458+00:00","domain":"probability theory","id":"claim_84a553b324108c04f636112a2df4ff745b1d8c486edf58a8072d3d62614187f4","kind":"concept","schema_version":1,"statement":"[Theorem 2 (Linear regression error) of arXiv:2608.24426, 'Sequential operator learning under dependent data'] Let $\obsop_\iteridx:\obsspace_\iteridx\to\fspace$ be predictable bounded linear maps and suppose that $\vnoise_\iteridx$ is conditionally $\vncov_\iteridx$-sub-Gaussian, where $\vncov_\iteridx$ is $\filtration_{\iteridx-1}$-measurable and positive semidefinite, for $\iteridx\geq 1$. Assume, for a fixed $\sigma_\vnoise^2>0$, that $\norm{\vncov_\iteridx}_\opnorm\leq\sigma_\vnoise^2$ and that $\obsop_\iteridx\vncov_\iteridx\obsop_\iteridx^\adj$ is almost surely trace class on $\mdlspace$, for all $\iteridx\in\N$. Define $\regsumop_\iteridx:=\regfactor\idop+\sum_{i=1}^\iteridx\obsop_i\obsop_i^\adj$ and $\sumcov_\iteridx:=\sum_{i=1}^\iteridx\obsop_i\vncov_i\obsop_i^\adj$. Then, given $\delta\in(0,1]$, with probability at least $1-\delta$,
\begin{equation}
    \abs{\pairing{\targetop-\learntop_\iteridx,\testop}}
    \leq
    \regfactor\norm{\regsumop_\iteridx^{-1}(\testop)}_1\norm{\targetop}_\opnorm
    +
    \norm{\regsumop_\iteridx^{-\half}(\testop)}_2
    \sqrt{
        2\sigma_\vnoise^2
        \log\paren*{
            \frac{
                \det\paren{
                    \idop+\regfactor^{-1}\sigma_\vnoise^{-2}\sumcov_\iteridx
                }^\half
            }{\delta}
        }
    },

\end{equation}
simultaneously for all $\testop\in\Schatten_1(\inH,\outH)$ and $\iteridx\in\N$. (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-26T20:47:22.258794+00:00","domain":"probability theory","id":"claim_84a63058c12916fe1270a808df05ae2059b25858e852af26b7bc19b67b8fec0a","kind":"concept","schema_version":1,"statement":"[Lem 130 of arXiv:2605.26664, 'Mixing times for Glauber dynamics of lozenge tilings of the hexagon'] For any $x \in [0,a]$, define $A = A_x$ by
	\begin{flalign} 

		A = f_0'' (\xi_x) - \displaystyle\frac{\mathfrak{q}^{x + \xi_x - \gamma_x} (\mathfrak{q}^{x + \xi_x - \gamma_x} + 1)}{(\mathfrak{q}^{x + \xi_x - \gamma_x}-1)^3} \cdot (\mathfrak{q}^{-x}-1) (\log \mathfrak{q})^2.
	\end{flalign}

	\noindent Further denoting
	\begin{flalign}

		\Gamma_{x;1} = -\displaystyle\frac{f_x (\gamma_x)}{( f_x (\gamma_x) - 1 )^2} \cdot \log \mathfrak{q}; \qquad \Gamma_{x;2} = ( f_x (\gamma_x)-1 )^2 \cdot \displaystyle\frac{\mathfrak{q}^{3\xi_x - 3\gamma_x-x} (\log \mathfrak{q})^3}{A (1 - \mathfrak{q}^{-x})^3},
	\end{flalign}

	\noindent we have 
	\begin{flalign}

		\gamma_x'' = \Gamma_{x;1} + \Gamma_{x;2}.
	\end{flalign}

	\noindent In particular, 
	\begin{flalign}

		\Gamma_{x;2} = \gamma_x'' - \gamma_x' (1 - \gamma_x') \log \mathfrak{q}. 
	\end{flalign} (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T14:25:44.585586+00:00","domain":"probability theory","id":"claim_84ab7f102511b2d58054e3b09ae9c76ab1aa2e0704675cf32d6dee2a98efe6e7","kind":"theorem","schema_version":1,"statement":"[Thm ext metric gap of arXiv:2509.08659, 'Gap metrics for stationary point processes and quantitative convexity of the free energy'] The space $\mathcal P_{s,1}(\Gamma)$ equipped with $\mathscr W_p$, $p\geq 1$, is a geodesic extended metric space. 
    For $\mathsf{P}_0,\mathsf{P}_1\in \mathcal P_{s,1}(\Gamma)$ and an $\mathscr W_p-$optimal $ \mathsf{Q}\in  \mathsf{Cpl}_{s,m}(\mathsf{P}_0,\mathsf{P}_1)$, the curve 
    \begin{align}
        [0,1]\ni t\mapsto \mathsf{P}_t= \mathsf{gap}^{-1}((T_t)_{\#}\iota( \mathsf{Q}))
    \end{align}
    defines a constant speed geodesic.","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T17:42:08.475190+00:00","domain":"probability theory","id":"claim_84ac54113550aca05e780d8eff46b70433e2a6006ee1791032b43c6833df10cd","kind":"lemma","schema_version":1,"statement":"[Lemma lemma13 of arXiv:2511.19391, 'Central limit theorem for supercritical Crump-Mode-Jagers processes counted with non-indiv'] Suppose that assumptions (A1 of the paper)-(A4 of the paper) hold and that $\mu_{\alpha}$ is spread-out such that there exists a Stone's decomposition of its associated renewal measure $e^{-\alpha x} \nu^{(\infty)}({\rm d}x)$ that satisfies (S1 of the paper). Furthermore, suppose that
\begin{align} 
\beta \coloneqq \int_{[0,\infty)} x e^{-\alpha x} \mu({\rm d}x) \in (0,\infty).
\end{align}
\noindent Let $\varphi$ be a non-negative characteristic that vanishes on the negative half-line (i.e., $\varphi(t)= 0$, for $t<0$) such that $t \in \mathbb{R} \mapsto \mathbb{E}[\varphi](t)$ is c\`adl\`ag, $\varphi(t) \in L^{1}(\Omega, \mathcal{F}, \mathbb{P})$, and 
\begin{align} 
\mathbb{E}[\varphi(t)] \leq C e^{(\alpha-\delta) t} \mathbf{1}_{[0,\infty)}(t), \quad \text{for every} \, \, t \in \mathbb{R},
\end{align}
\noindent for some $\delta \in (\varepsilon, \alpha)$ and finite constant $C > 0$, where $\varepsilon \in (\alpha/2, \alpha)$ is as in (S1 of the paper). Then, 
\begin{align} 
m_{t}^{\mathbb{E}[\varphi]} = \mathbf{1}_{[0,\infty)}(t) e^{\alpha t} \beta^{-1} \int_{0}^{\infty} \mathbb{E}[\varphi(x)] e^{-\alpha x} {\rm d} x + r(t), 
\end{align}
\noindent where $r: \mathbb{R} \rightarrow \mathbb{R}$ is a function  satisfying $|r(t)| \leq C^{\prime} e^{(\alpha-\varepsilon)t} \mathbf{1}_{[0,\infty)}(t)$  for all $t \in \mathbb{R}$ and some finite constant $C^{\prime} > 0$.","status":"unverified"}

