{"assumptions":[],"created_at":"2026-09-07T12:18:08.279474+00:00","domain":"probability theory","id":"claim_853352cf46ab2326b55958802ef6352ea0c083015c5ea9294b3518fa7547df30","kind":"concept","schema_version":1,"statement":"[Lemma 12 (Lemma 4.6 in \cite{Ledoux_Book}) of arXiv:2505.20799, 'A note on the improved sparse Hanson-Wright inequalities'] Let $F: \mathbb{R}^{+}\to \mathbb{R}^{+}$ be a convex non-decreasing function. Assume that $\{\eta_{i}, i\le n\}$ and $\{\xi_{i}, i\le n\}$ are two  sequences of independent symmetric random variables such that for some constant $K\ge 1$
	\begin{align}
		\mathbb{P}\{\vert \eta_{i}\vert>t  \}\le K\mathbb{P}\{\vert\xi_{i}\vert >t \},\quad i\le n,\quad t>0.
	\end{align}
	Then, for any sequence $\{a_{i}, i\le n\}$ in a Banach space $(\mathcal{A}, \Vert\cdot\Vert)$,
	\begin{align}
		\mathbb{E}F\Big( \big\Vert \sum_{i=1}^{n}a_{i}\eta_{i}\big\Vert    \Big)\le \mathbb{E}F\Big(K \big\Vert \sum_{i=1}^{n}a_{i}\xi_{i}\big\Vert   \Big).\nonumber
	\end{align} (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T22:31:02.818601+00:00","domain":"probability theory","id":"claim_853797a8aa84fa0706ffde4ad6037a54ffcd716120f818e9b420474d675d7c7b","kind":"lemma","schema_version":1,"statement":"[Lemma lem:centered-cubic-label of arXiv:2609.01690, 'Iterated-sumset spectra: The complete exponent law and its rank geometry'] Put
\begin{equation}
 S_1=\sum_{i=1}^t(\ell_i-1),\qquad
 S_2=\sum_{i=1}^t(\ell_i^2-1),\qquad
 Y_x=2x+4-S_1,\qquad L=S_2-4,
\end{equation}
and define
\begin{equation}
 P_{\boldsymbol\ell}(x)=Y_x^3+LY_x.
\end{equation}
Then
\begin{equation}
 48\sum_{0\leq j_i<\ell_i}M_{x-J}
 =R P_{\boldsymbol\ell}(x)
\end{equation}
whenever all $x-J\geq0$.  Consequently every set in
Lemma~(lem:stable-suspended-chart of the paper) satisfies the exact integer identity
\begin{equation}
 48|hA_t|=R\,G_{\boldsymbol\ell}(u,v,b,c),
\end{equation}
where
\begin{equation}
 G_{\boldsymbol\ell}(u,v,b,c)=
 P_{\boldsymbol\ell}(h)-P_{\boldsymbol\ell}(u)
 +P_{\boldsymbol\ell}(v)-P_{\boldsymbol\ell}(b)
 -P_{\boldsymbol\ell}(c)\in\mathbb Z_{>0}.
\end{equation}
Uniformly on the construction,
\begin{equation}
 |hA_t|\asymp_t Rh^3\asymp_t h^{t+3}.
\end{equation}","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T17:11:02.387478+00:00","domain":"probability theory","id":"claim_8537a35fcd32434ea87cddb763d59445aeae1c2794a84a239ee7603185d82e29","kind":"concept","schema_version":1,"statement":"[Corollary cor:local_subgraph_clt_intro of arXiv:2507.10531, 'Quantitative central limit theorems for exponential random graphs'] Recall the definition of $\varsigma_n^2$ from (equation eq:sigmadef_local_intro of the paper).
