{"assumptions":[],"created_at":"2026-10-27T20:36:16.007597+00:00","domain":"probability theory","id":"claim_85f7c7b56505e5853661ffe4622368ca90d014385bef3e65079326fc86648edf","kind":"lemma","schema_version":1,"statement":"[Lemma esti of arXiv:2606.27844, 'Critical percolation on preferential attachment graphs with infinite variance'] Let $X_l^{(i)}$ be the number of paths $x_0x_1\cdots x_l$ of length $l$ such that $x_l=i$ and $x_k>m$ for all $k=0,1,\ldots,l-1$. Then
  \begin{align}
		\mathbb E\big[X^{(i)}_l\big]&\le \mu_l(x_l) \,,
\end{align}
where
$$ \mu_l(x_l) \le \mathbbm{1}_{\{x_l > m\}}\psi_l\, x_{l}^{\gamma-1}+\phi_l\, x_{l}^{-\gamma}$$
and 
\begin{equation} 
    \begin{aligned}
    \psi_{l} = &\,O\big(\beta(n)^{l}m^{(1-2\gamma)\lfloor \tfrac{l}2 \rfloor}n^{\gamma + (2\gamma-1)(\lfloor \tfrac{l}2 \rfloor-1)}\log(n)^{\mathbbm{1}_{\{l \text{ odd}\}}}\big) \\
    \phi_{l} = &\,O\big(\beta(n)^{l}m^{(1-2\gamma)\lfloor \tfrac{l-1}2 \rfloor}n^{\gamma + (2\gamma-1)\lfloor \tfrac{l-1}2 \rfloor}\log(n)^{\mathbbm{1}_{\{l \text{ even}\}}}\big)\;.
\end{aligned}
\end{equation}","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T09:05:57.778236+00:00","domain":"probability theory","id":"claim_85fa2665cf30f7c0ae560dafd33e8421378e40cea702c5a10e55885f6c0b0da9","kind":"lemma","schema_version":1,"statement":"[Lemma 24 of arXiv:2608.30549, '\vspace{-1cm}Maximally Spread Out Measures and Implications\\{} for Phase Transitions in A'] Let $(\SC, \varrho)$ be a non-empty quasi-metric space.
 Let $\mu$ be a Borel probability measure on $\SC$, and let $s\in (0,\infty)$ and $t\in \RR$.
 Assume that there exist $r_0>0$ and $c>0$ such that
 \begin{equation*}
     \om{\mu} \bigl( \ball(x,r)\bigr) 
    \leq \exp
         \biggl(
           - c
             \cdot \Bigl( \frac{1}{r}\Bigr)^{s}
             \cdot \Bigl( \log_2 \Bigl(\frac{1}{r}\Bigr)\Bigr)^{t}
         \biggr)
    \quad \text{for all $x\in \SC$ and all $r\in (0,r_0)$.}
 \end{equation*}
 Then for every $\eps\in (0,r_0)$ and every $\eps$-net $\SC_{\eps}\subset \SC$ we have
 \begin{equation*}
     \num\SC_{\eps}
     \geq \exp
          \biggl(
            c \cdot \left(\frac{1}{\eps}\right)^s
              \cdot \left(\log_2 \left(\frac{1}{\eps}\right)\right)^{t}
          \biggr).
 \end{equation*}","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-26T19:25:12.186340+00:00","domain":"probability theory","id":"claim_85faece621235df8c15e8ee7b3e8936195e5ec9d3a658f25c9cdac7e8cb32a91","kind":"concept","schema_version":1,"statement":"[Lemma 12 of arXiv:2510.20492, 'Heterochromatic two-arm probabilities for metric graph Gaussian free fields'] For $d \ge 7$, there exists $C>0$ such that for any $M\ge 1$, $N\ge CM$ and $y\in \partial B(N)$, 
