	\max_{x_1\in B_y(M)}	  \sum\nolimits_{x_2\in B_y(M)}   \mathbb{P}\big(\bm{0}\xleftrightarrow{\ge 0} x_1,\bm{0}\xleftrightarrow{\ge 0} x_2\big)  
