        \begin{equation}
            \begin{tikzcd}
                {\mathcal{V}_{K}(\Gamma) \otimes \mathcal{V}_{K}(-\Gamma)} && {k}\\
                \\
                {\mathcal{V}_{\mathbf{K}_{/T}}(\Gamma/T) \otimes \mathcal{V}_{\mathbf{K}_{/T}}(-\Gamma/T)} && {k}
                \arrow["{\langle\cdot,\cdot\rangle_\Gamma\circ\iota}", from=1-1, to=1-3]
                \arrow["{(\bigcirc\otimes\bigcirc)\circ\iota}", from=1-1, to=3-1]
                \arrow["{\langle\cdot,\cdot\rangle_{\Gamma/T}}", from=3-1, to=3-3]
