\begin{align}
        \rho_\beta^{(2)}(0,\lambda)=\frac{1}{4\pi^2}+\frac{1}{2\pi^2}\sum_{k=1}^\infty  \frac{(-\beta/2)^{\uparrow k}}{(1+\beta/2)^{\uparrow k}} E[\cos(k \alpha_\lambda(0)].
