        \frac1{\kappa_q},
        \frac1{1-2^{-q}}
    \right\}.
\end{equation}

Furthermore, if
\[
    M_q(t):=A_{\alpha}(t)=\sum_{k\ge1}k^q p_k(t),
\]
then, for every \(t<T_q\),
\begin{equation}

    \frac1{T_q-t}
    \le
    M_q(t)
    \le
    \frac1{\kappa_q(T_q-t)}.
\end{equation}
Consequently,
\begin{equation}

    \bigl(q(T_q-t)\bigr)^{-1/q}
    \le
    \mu(t)
    \le
    \left(
        \frac{T_q}{T_q-t}
    \right)^{1/\kappa_q},
    \qquad 0\le t<T_q,
\end{equation}
and
\begin{equation}

    \left(
        \frac{T_q-t}{T_q}
    \right)^{1/\kappa_q}
    \le
    d(t)
    \le
    \bigl(q(T_q-t)\bigr)^{1/q}.
\end{equation}","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T07:29:27.984109+00:00","domain":"probability theory","id":"claim_88087ba8c95f3973cfac233b7493c05c8509e82128cd1aedf5bf19fd6c89d7b6","kind":"theorem","schema_version":1,"statement":"[Proposition 6 (Center-of-mass factorization) of arXiv:2608.24863, 'Uniform Logarithmic Sobolev Inequalities for the 2D Coulomb Gas at the Diffusive Temperatu'] Let
\begin{equation}
 c_N=N^{-1/2}\sum_{i=1}^Nz_i,
 \qquad
 r_k:=\frac{z_1+\cdots+z_k-kz_{k+1}}{\sqrt{k(k+1)}},
 \quad 1\le k\le N-1,
\end{equation}
and set $Z^{\rm rel}:=(r_1,\ldots,r_{N-1})$.  The map $Z\mapsto(c_N,Z^{\rm rel})$ is unitary and, in these coordinates,

\begin{equation}
 \mathbb P_{N,\beta}=\gamma_\beta^{(2)}\otimes \mathbb P_{N,\beta}^{\rm rel},
\end{equation}
where $\gamma_\beta^{(2)}(dc)=(\beta/2\pi)e^{-\beta|c|^2/2}\D c$ and $\mathbb P_{N,\beta}^{\rm rel}$ is the law of $Z^{\rm rel}$.  Consequently,
