 for all $x \in W^d$ with $\lvert x_j \rvert \leq t^{\theta}/\log(t)$ and $x_j - x_{j-1} \geq 1$ for all $j = 2, \ldots, d,$
\begin{align*}
\mathbf E_{x}[\Delta(B(t)); \tau^{\mathrm{bm}} > t, \mathcal C_t^c] & \leq C\Delta(x) e^{\theta t^a \log(2t)-t^{\beta/2}}.
\end{align*}
\end{enumerate}","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T05:50:44.876336+00:00","domain":"probability theory","id":"claim_88912550bbfeffe214de10f71656e2f7f4c17c361f10c7f45d2ba36843ce8e29","kind":"lemma","schema_version":1,"statement":"[Lemma 58 (Iterated lattice convolution and cutoff tails) of arXiv:2607.16724, 'Algebraic Transfer for Operator-Valued Gaussian Chaoses: Oriented Schatten Profiles and Si'] Let $m\ge2$, let
\[
 \frac{(m-1)D}{m}<\alpha\le D,
 \qquad v(x)=\langle x\rangle^{-\alpha},
 \qquad h_k=v^{*k}\quad(1\le k\le m),
\]
where convolution is on $\mathbb Z^D$.  Put
\[
 \rho=D-\alpha,
 \qquad \gamma_k=D-k\rho=k\alpha-(k-1)D>0.
\]
If $\alpha<D$, then
\begin{equation}

 h_k(z)\le C\langle z\rangle^{-\gamma_k}.
\end{equation}
If $\alpha=D$, then
\begin{equation}

 h_k(z)\le C\langle z\rangle^{-D}
                 \log(e+\langle z\rangle)^{k-1}.
\end{equation}
For $M\ge1$, let
\[
 h_{k,>M}(z):=
 \sum_{x_1+\cdots+x_k=z}
 \prod_{j=1}^kv(x_j)
 \mathbf1_{\{\max_j|x_j|>M\}}.
\]
If $\alpha<D$, then
\begin{equation}

 h_{k,>M}(z)\le
 C\max\{M,\langle z\rangle\}^{-\gamma_k}.
\end{equation}
At $\alpha=D$,
\begin{equation}

 h_{k,>M}(z)\le
 C\max\{M,\langle z\rangle\}^{-D}
 \log\!\bigl(e+\max\{M,\langle z\rangle\}\bigr)^{k-1}.
\end{equation}
Consequently, if $E\subset\mathbb Z^D$ and $\#E\le C_0R^D$, then
\begin{align}

 \sum_{z\in E}h_k(z)&\le C
 \begin{cases}
  R^{k\rho},&\alpha<D,\\
  \log(e+R)^k,&\alpha=D,
 \end{cases}\\

 \sum_{z\in E}h_{k,>M}(z)&\le C
 \begin{cases}
  R^{k\rho}\min\{1,(R/M)^{\gamma_k}\},&\alpha<D,\\
  \log(e+R)^k\min\{1,(R/M)^{\vartheta}\},&\alpha=D,
 \end{cases}
\end{align}
where the endpoint estimate holds for every $0<\vartheta<D$, with a
constant depending on $\vartheta$.","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T19:46:25.320448+00:00","domain":"probability theory","id":"claim_889129983a0b111c897e2a65e571f55acca6b23f46b7d0f285074ba245552697","kind":"concept","schema_version":1,"statement":"[Prop apriori of arXiv:2604.14122, 'The scaling limit of random walk and\\ the intrinsic metric on planar critical percolation'] Let $\varepsilon>0$. There exist $R_{0}=R_{0}(\varepsilon)$ and $C=C(\varepsilon)$ such that for each $R \ge R_0$ there exists $p_0=p_0(\varepsilon,R)$ such that for all $p<p_0$, $k \geq 1$, and $n> R^k$,
