 		\qquad\,.
 	\end{align}

Moreover, we have
\begin{equation} \int_{-1}^1|\beta_L^q(u)|^q \di \mu(u) \,\asymp \,
 		\begin{cases}
        1 \,\, &\textnormal{if } q<d/(2\nu) \\
 			\log L\,\, &\textnormal{if } q=d/(2\nu) \\
 			L^{q -d/(2\nu) }\,\, &\textnormal{if }q>d/(2\nu)
 		\end{cases}
 		\qquad\,.
        \end{equation}","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T23:05:09.625413+00:00","domain":"probability theory","id":"claim_88f528d43635d4c7a834de729861ccfa4ea7cef3438161ca8f4926b3d58a5424","kind":"concept","schema_version":1,"statement":"[Lemma lem:est for iid of arXiv:2411.03512, 'Ergodicity and Mixing of Sublinear Expectation System and Applications'] Let $\{X_k\}_{k\geq 1}$ be a d-dimensional i.i.d. sequence such that $\hat{\mathbb{E}}[|X_1|^{1+\beta}]<\infty$ for some $\beta\in (0,1]$ and $v\in C_b^{1,1+\beta}(\mathbb{R}_+\times \mathbb{R}^d)$ be the solution to equation (equation PDE of the paper) with $p(a)=\hat{\mathbb{E}}[\langle a, X_1\rangle]$. Set $S_n=\frac{1}{n}\sum_{i=1}^nX_i$. Then we have
        \begin{equation}
           \begin{split}
				v(1,0)-\hat{\mathbb{E}}[\phi(S_n)]&\geq -4n^{-\beta}\int_0^1|\nabla_xv(s,\cdot)|_{\beta}ds\times \hat{\mathbb{E}}[|X_1|^{1+\beta}]+\underline{f},
			\end{split}
        \end{equation}
        where 
		$
			\underline{f}=\inf_{\{0\leq t\leq 1,x\in \mathbb{R}^d\}}f(t,x)
	$ with $f$ defined as in (equation PDE of the paper). (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-28T01:37:28.981064+00:00","domain":"probability theory","id":"claim_88f6499c2b754eb64b424627db695046a0029f81aac13648cf662ade1adc6e03","kind":"concept","schema_version":1,"statement":"[Thm jointr1r2 of arXiv:2412.00610, 'Joint Poisson Convergence of Monochromatic Hyperedges in Multiplex Hypergraphs'] Fix integers $2 \le r_1 < r_2$. Let $\bm H_n = (H_n^{(1)}, H_n^{(2)})$ be a sequence of 2-hypermultiplexes on the same set of vertices $V_n$, such that 
$H_n^{(1)}$ is $r_1$-uniform, $H_n^{(2)}$ is $r_2$-uniform, $|E(H_n^{(1)})| \to \infty,$ and $|E(H_n^{(2)})| \to \infty$. Suppose $V_n$ is colored uniformly at random with $c_n$ colors as in (equation eq:cn of the paper), such that the following hold: 
      \begin{itemize}
      \item  There exist constants $\lambda_1, \lambda_2 \ge 0$ such that 
            \begin{align}
            \frac{|E(H_n^{(1)})|}{c_n^{r_1-1}} \to \lambda_1,~\frac{|E(H_n^{(2)})|}{c_n^{r_2-1}} \to \lambda_2 . 
            \end{align}

      \item  For all $t_1 \in [2, r_1 - 1]$ and $t_2 \in [2, r_2 - 1]$, 
      \begin{align}
      \frac{|\cK(t_1, H_n^{(1)})|}{c_n^{2r_1-t_1-1}} \to 0 \text{ and } \frac{|\cK(t_2, H_n^{(2)})|}{c_n^{2r_2-t_2-1}} \to 0 , 
      \end{align} 
     where $\cK(\cdot, \cdot)$ is defined in (equation defn:K of the paper). 
  \end{itemize} 
Then 
  $$\bm T(\bm H_n)= \left(\begin{array}{l}
    T(H_n^{(1)}) \\
    T(H_n^{(2)})
    \end{array}\right) \dto \left(\begin{array}{l}
      Z_1\\
      Z_2
      \end{array}\right) , $$
    where $Z_1 \sim \Pois(\lambda_1), Z_2 \sim \Pois(\lambda_2)$ are independent. (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T14:05:52.474959+00:00","domain":"probability theory","id":"claim_88f7277175e82d3e44dcbd9d48c3ae867ebed1db8872ba3e1cdb1ed0f9b46029","kind":"definition","schema_version":1,"statement":"[Definition def:domain-extension of arXiv:2505.02685, 'On the Spectral Expansion of Monotone Subsets of the Hypercube'] We define an operator $T$ that extends any function $f:A\rightarrow\mathbb{R}$ to the function $T[f]:\{0,1\}^{n}\rightarrow\mathbb{R}$ defined by
