{"assumptions":[],"created_at":"2026-10-27T21:59:24.054835+00:00","domain":"probability theory","id":"claim_89f1a9bb61b161d6876e16d88270a485d1b3e29efa2499578699ad408b6be8cb","kind":"theorem","schema_version":1,"statement":"[Corollary thm:Jacobi-inverse of arXiv:2608.30904, 'Entire monotone solutions of the anisotropic Allen--Cahn equation in dimension 5'] For any $\gamma\in(\mu,1-\mu)$ and $k\ge0$,
\begin{equation}
 J_\Gamma:
 C^{k+2,\alpha}_\gamma
 \longrightarrow
 C^{k,\alpha}_{\gamma+2}
\end{equation}
is an isomorphism on axis-smooth invariant functions, and
\begin{equation}
 \|f\|_{C^{k+2,\alpha}_\gamma}
 \le C_k\|J_\Gamma f\|_{C^{k,\alpha}_{\gamma+2}}.
\end{equation}","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-26T19:43:44.242551+00:00","domain":"probability theory","id":"claim_89f3c7377ac80f6720665b97f9a751c13de504ef6884991c47e7cc46bd650189","kind":"concept","schema_version":1,"statement":"[Theorem 2 of arXiv:2604.15152, 'The Multinomial Allocation Model and the Random Box Load'] For $0\le r,t\le n$ and $r\ne t$,  the following three approximation formulas hold
\begin{align}
\rE[\hat q_r]&=\rE[p_{r}(\xi)]+(2n)^{-1}\rE[p_{r}(\xi)(r-(\xi-r)^2)]+n^{-2}R_1(n,r), \\
\rV[\hat q_r]&=n^{-1}\alpha\rE[p_{r}(\xi)(1-p_{r}(\xi))]-n^{-1}(\rE[p_{r}(\xi)(\xi-r)])^2+n^{-2}(R_2(n,r,r)+\alpha R_1(n,r)), \\
\rC[\hat q_r,\hat q_t]&=-n^{-1}\alpha \rE[p_{r}(\xi)p_{t}(\xi)]-n^{-1}\rE[p_{r}(\xi)(\xi-r)]\,\rE[p_{t}(\xi)(\xi-t)]+n^{-2}R_2(n,r,t), 
\end{align}
where provided  $q_1\le1/4$, 
\begin{align}
- (r!)^{-1} \beta^r(r^32^{r-1}+4) &\le R_1(n,r) \le (r!)^{-1}\beta^rr^2(2r^2+ 4\beta^2),  \\

- (r!t!)^{-1}\beta^{2u}L_2(u,\beta) &\le R_2(n,r,t) \le (r!t!)^{-1}\beta^{2u} K_2(u,\beta), 
