{"assumptions":[],"created_at":"2026-10-27T06:32:19.900710+00:00","domain":"probability theory","id":"claim_89f54f508314b14ad717fe0864f3ad9393984caafe9c48db3d4a71328823552e","kind":"lemma","schema_version":1,"statement":"[Lemma 14 of arXiv:2608.02319, 'Averaging Principle for Ordinary Differential Equations in a Multiscale Random Environment'] For all $n,k\geq1$, $0<S<T$, $x\in E$ and $y\in\mathbb R^d$ we set
\begin{align*}
\phi_{S,T}^{n,k}(y,x)=\mathbf E_{x}\big[f_1(\mathbf Z_S^{n,y})\,f_2(\mathbf Z_T^{n,y})\mathbf 1_{\{\tau_{k-1}^n<S<T\leq\tau_k^n\}}\big].
\end{align*}
Let $L>0$, then for all $n,k\geq1$, $T>0$ there exist $M_T^k>0$ such that for all $z,y\in\mathbb R^d$ and $x\in E$
\begin{align*}
\lvert\phi_{S,T}^{n,k}(y,x)-\phi_{S,T}^{n,k}(z,x)\rvert&\leq2\,\|f_1\|_\infty\,\|f_2\|_\infty\,\big(\mathbf P_x(S\leq\tau_k^n,L_S^n>L)+\mathbf P_x(T\leq\tau_k^n,L_T^n>L)\big)\\
&+\lvert y-z\rvert\,\big(\|f_1'\|_\infty\,\|f_2\|_\infty\,e^{SL}+\|f_1\|_\infty\,\|f_2'\|_\infty\,e^{TL}\big),
\end{align*}
where for all $t>0$ and $n\geq1$
\begin{align*}
L_t^n:=\sup_{s\in[0,t]}L_{\mathbf I_s^n}.
\end{align*}","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T20:38:36.829211+00:00","domain":"probability theory","id":"claim_89f6328faf469a8ced7a1738c357b8c67bc784288a9cf7e67fed156e6724649f","kind":"theorem","schema_version":1,"statement":"[Proposition prop:affine-sig of arXiv:2606.28869, '\bfseries A General Theory of Paths:\\ \large Signatures, Jump Lifts, and Expected Signatu'] Fix $m<\infty$. There is a finite vector $U_t$ collecting the expected-signature coordinates $\mathbb{E}\inner{\mathrm{Sig}^{(m)}_{0,t}}{w}$ together with state-weighted coordinates $\mathbb{E}[X_t^{\gamma}\inner{\mathrm{Sig}^{(m)}_{0,t}}{w}]$ for all $|\gamma|+|w|\le m$, and there is a constant matrix $A_m$ depending on the affine characteristics in (equation eq:affine-generator of the paper) such that
\begin{equation}
\frac{\,\mathrm{d}}{\,\mathrm{d} t}U_t=A_mU_t,
\qquad
\mathbb{E}[\mathrm{Sig}^{(m)}_{0,t}]=\Pi_m e^{tA_m}U_0,

\end{equation}
where $\Pi_m$ selects the coordinates with no state weight.","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T07:06:18.030986+00:00","domain":"probability theory","id":"claim_89f7db4f943da65b64fae30dc5c3d235f002dd6b82077c31551627081e7ebeca","kind":"lemma","schema_version":1,"statement":"[Lemma 24 of arXiv:2608.15616, '\textbf{Compact Support Property of Super-Brownian Motion with Irregular Drift}'] Let $\eta \in (0,1/2)$ and $b_1>0$ and  let $c_\eta >0$ be such that 
        \begin{equation}
			\frac{1}{\Gamma(\mu)}\int_{c_\eta}^\infty u^{\mu-1}\ee^{-u}du \geq \frac{3}{4},
		\end{equation}
        for $\mu = 1-2\eta$.
        Assume that $f\in \mcC_c^+$ with $f\neq 0$, $m_f = \langle f,1\rangle$ and $K_f = \mathrm{diam}(\supp(f))/2$ is such that the following is satisfied
		\begin{enumerate}




			\item It holds that 
		\begin{equation*}
			m_f  = \langle f, 1\rangle < \frac{c_\eta}{2}.
