		\begin{equation*}
			\mathbbm{P}(\langle X_t ,1\rangle = 0) > \frac{1}{2},
		\end{equation*}
		where $X$ is the solution to \eqref{eq:SPDE1_sup} with $b_1>0$ and $f\in \mcC_c^+$ as above.","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T07:14:37.610359+00:00","domain":"probability theory","id":"claim_89f828b2305af8b6cbe6399275e14ad5b72fdf51977df0b04f42fa74f3b984a7","kind":"definition","schema_version":1,"statement":"[Definition 1 of arXiv:2608.19065, 'Boundedly exchangeable graphs'] An adjacency measure on $S$ is a simple measure $\xi$ on $S^2\times\{0,1\}$ such that
\begin{enumerate}[label=(\roman*)]
    \item there is a simple measure $\nu$ on $S$ with $\xi(C\times\{0,1\}) = \nu^{\otimes 2}(C)$ for every $C \in \Bcal(S)^{\otimes 2}$,
    \item $(\theta \otimes \mathrm{id})\,\xi = \xi$, where $\theta(x,y)=(y,x)$ and $\mathrm{id}$ denotes the identity function on $\{0,1\}$.
\end{enumerate}
For $B\in\mathcal{B}(S)$, the $B$-restriction of $\xi$ is the adjacency measure $\xi\vert_{B \times B \times \{0,1\}}$, which we denote by $\xi\vert_B$ for brevity.","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-28T02:47:21.610896+00:00","domain":"probability theory","id":"claim_89f8966ffc45bd1d1efef4632182af76592a18db892bb9ac6bdef5a4dfd4b60b","kind":"definition","schema_version":1,"statement":"[Definition def:equilibrium-defs of arXiv:2412.09087, 'General Markovian randomized equilibrium existence and construction in zero-sum Dynkin gam'] \enskip 

\begin{itemize}

\item A Markovian randomized stopping time pair $(\tau^*_1,\tau^*_2)=(\tau_{\Psi^{(1)}},\tau_{\Psi^{(2)}})$ is said to be a global Markovian randomized $\epsilon$-Nash equilibrium, for a fixed constant $\epsilon\geq 0$, if
\begin{align}
\begin{split}
& J(x;\tau_1,\tau^*_2) - \epsilon \leq J(x;\tau^*_1,\tau^*_2) \leq J(x;\tau_1^*,\tau_2) + \epsilon\\
& \enskip \text{for all $\tau_1 \in \mathbb{T}_1, \tau_2 \in \mathbb{T}_1$, and $x\in {\cal I}$.}
\end{split}
\end{align}
If (equation def:SE of the paper) is satisfied with $\epsilon=0$ then $(\tau^*_1,\tau^*_2)=(\tau_{\Psi^{(1)}},\tau_{\Psi^{(2)}})$ is said to be a global Markovian randomized Nash equilibrium.

\item A Markovian pure stopping time pair $(\tau^*_1,\tau^*_2)=(\tau^{D_1},\tau^{D_2})$ is said to be a global Markovian pure $\epsilon$-Nash equilibrium if it satisfies (equation def:SE of the paper). 
If it satisfies (equation def:SE of the paper) with $\epsilon=0$ then it is said to be a global Markovian pure Nash equilibrium.

\item The value of the game $V$ is defined as $V(x):=V^*(x)=V_*(x)$, whenever this equality holds for each $x\in  {\cal I}$, where 
\begin{align}
\begin{split}
V^*(x)&:=\adjustlimits \inf_{\tau_2 \in \mathbb{T}_2} \sup_{\tau_1 \in \mathbb{T}_1} J(x;\tau_1,\tau_2),\\
V_*(x)&:=\adjustlimits  \sup_{\tau_1\in \mathbb{T}_1} \inf_{\tau_2\in \mathbb{T}_2} J(x;\tau_1,\tau_2).
\end{split}
\end{align}



\end{itemize}","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T13:01:22.598111+00:00","domain":"probability theory","id":"claim_89fa07b46283529bf43cf414afcab6e417430ced3600aa16041c7446ebb7701b","kind":"concept","schema_version":1,"statement":"[Theorem thm:main_CPMRE of arXiv:2606.10257, 'Downward conditional monotonicity gives survival and extinction for contact processes in r'] Consider the CPMRE described above with increasing infection rate vector $\beta=(\beta_0,\beta_1,\ldots,\beta_{k-1})$, decreasing recovery rate vector $\mu=(\mu_0,\mu_1,\dots,\mu_{k-1})$, 
	and irreducible, monotone environmental process with generator matrix $T$. Let the initial environmental distribution at each site be arbitrary.	
	\begin{longlist}
		\setlength{\itemindent}{28pt}

		\setlength{\labelsep}{0.4em}
		\item If the MMPP with $\beta,T$ is DCM and 
		$\frac{\beta^*}{\max_j\mu_j}>\lambda_c$, 
		then the CPMRE survives (strongly).
		\item If the permutation-reversed MMPP with $\widehat\mu,\widehat{T}$ is DCM and 
		$\frac{\max_j\beta_j}{\mu^*}\leq\lambda_c$, 
		then the CPMRE goes extinct.
	\end{longlist} (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T21:25:41.601089+00:00","domain":"probability theory","id":"claim_89fa114ddfaaec2d5fd96e17eabe8ad783b49e6e7f4660e3ea578ca25de202de","kind":"concept","schema_version":1,"statement":"[Corollary 20 of arXiv:2608.12947, 'Branch-stationary max-stable fields on rooted trees'] Let \(Z\) be an \(\alpha\)-spectral representer satisfying
(equation 2 of the paper) and (equation 17 of the paper), and put
\(\Theta=\Theta^{[\varnothing]}\). Then \(Z\) is branch-BR stationary
if and only if
\begin{equation}
  \E*{
    \mathbf 1_{\{\Theta_a>0\}}
    \Theta_a^\alpha
    H\left(\frac{B^a\Theta}{\Theta_a}\right)
  }
