{"assumptions":[],"created_at":"2026-10-27T20:36:16.002664+00:00","domain":"probability theory","id":"claim_8a600e62e57e2e9966aae20b79494c9a35a0fd782b873f0b3cf7593d5c89a100","kind":"concept","schema_version":1,"statement":"[Lemma bound_separating of arXiv:2606.27357, '\textbf{Typical distances in high-genus triangulations}'] {lions2026locallimitsuniformtriangulations}}]
