	\lim_{N\rightarrow \infty} \langle \varphi_{\sf o}^{(1)} \varphi_{\sf x}^{(1)} \rangle_{g,\nu_c,  N} =: \langle \varphi_{\sf o}^{(1)} \varphi_{\sf x}^{(1)} \rangle_{g,\nu_c,  \Z^d} =: \C_{\sf x}
