{"assumptions":[],"created_at":"2026-10-27T21:12:46.898178+00:00","domain":"probability theory","id":"claim_8bd938b221236d8a157195fd1c7c4845ce1c0ad0deefd6ef94584d7013bf97b7","kind":"definition","schema_version":1,"statement":"[Definition condiGrom of arXiv:2608.09856, '\bf Mass erasure on measured $\bbR$-trees,\\ applications to L\'evy forests'] Let ${\boldsymbol{\mu}}_i \! \equiv \! (E_i,d_i,\rho_i, \mu_i)$ be finitely measured pointed metric spaces, $i\! \in \!  \{ 1,2\}$ and let $\eta \! \in \!  \mathbb{R}^*_+$. 
We introduce the following conditions. 
\begin{compactenum}

\smallskip

\item[$\mathtt{Cond}_{\mathtt{GH}}(\eta)$:]There is a correspondence $R$ between $E_1$ and $E_2$ such that 
\begin{equation}

\tfrac{1}{2} \mathtt{dis} (R) \! < \!  \eta \quad \textrm{and} \quad (\rho_1,\rho_2)\! \in \!  R .
\end{equation}
\item[$\mathtt{Cond}_{\mathtt{GP}}(\eta)$:]There is a \emph{compact} partial correspondence $R\!\subseteq\! E_1\! \times \! E_2$ which satisfies ((GHcondi of the paper)) and there is a measure $\mathtt m\! \in \!  \mathcal{M}_{\! f} (E_1\! \times \! E_2)$ such that 
\begin{equation}

\mathtt m ((E_1\! \times \! E_2) \backslash R) \! = \!  0  \quad \textrm{and $\quad \mathtt m$ is an $\eta$-coupling of $\mu_1$ and $\mu_2$.}
\end{equation}
\item[$\mathtt{Cond}_{\mathtt{GHP}}(\eta)$:]
There is a correspondence $R$ \emph{between} $E_1$ and $E_2$ satisfying ((GHcondi of the paper)) and there is a measure $\mathtt m\! \in \!  \mathcal{M}_{\! f} (E_1\! \times \! E_2)$ satisfying ((GPcondi of the paper)) $\hfill \square$
\end{compactenum}","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T09:13:18.504752+00:00","domain":"probability theory","id":"claim_8bd94b54b7e2b7be52df5e2f94fc93ea9b48895e1af7397081f25d273c76bcc6","kind":"definition","schema_version":1,"statement":"[Definition 1 (Hilbert module {\cite[Chapter~1) of arXiv:2608.30589, 'Vector-Valued Wavelet Bases as Hilbert $\mathbb{M}_m(\mathbb{R})$-Module Bases: A Construc'] {lance1995hilbert}}]
Let $\mathcal{A}$ be a (real) $C^*$-algebra.
A \emph{pre-Hilbert $\mathcal{A}$-module} is a left $\mathcal{A}$-module $\mathcal{H}$ equipped with an $\mathcal{A}$-valued inner product $\langle\cdot,\cdot\rangle_{\mathcal{A}}:\mathcal{H}\times\mathcal{H}\to\mathcal{A}$ such that for all $x,y\in\mathcal{H}$ and $A\in\mathcal{A}$:
\begin{enumerate}[label=(\roman*)]

  \item $\langle x,x\rangle_{\mathcal{A}}\ge 0$;
  \item $\langle x,x\rangle_{\mathcal{A}}=0$ implies $x=0$;
  \item $\langle x,y\rangle_{\mathcal{A}}=\langle y,x\rangle_{\mathcal{A}}^{*}$;
  \item $\langle Ax,y\rangle_{\mathcal{A}}=A\,\langle x,y\rangle_{\mathcal{A}}$.

\end{enumerate}
The induced norm is $\|x\|_{\mathcal{A}}:=\|\langle x,x\rangle_{\mathcal{A}}\|_{\mathcal{A}}^{1/2}$.
If $\mathcal{H}$ is complete for this norm, it is called a \emph{Hilbert $\mathcal{A}$-module}.","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T15:38:04.526508+00:00","domain":"probability theory","id":"claim_8bda63b8416d598641a65e8723bd415069b93c1e0f963970d4772882f4f38559","kind":"concept","schema_version":1,"statement":"[Proposition of arXiv:2607.18011, 'From local giants to locality in long-range percolation'] \thlabel{prop:rand_elec_net_rec}
    Let $G$ be a transitive graph of polynomial growth with $d = 2$, and let $\mathcal E$ be a random electrical network on $G$ such that the conductance of each edge is identically distributed (possibly dependent) random variable dominated by a Cauchy tail.

    Then $\mathcal E$ is recurrent almost surely. (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-26T20:58:09.066073+00:00","domain":"probability theory","id":"claim_8bdca1a7ae2be800c2b983b1cd25f1c9da3f78b13476475d09ea9f889974c06e","kind":"concept","schema_version":1,"statement":"[Theorem 2 of arXiv:2606.27520, 'Critical curve of loop percolation on the $d$-regular tree'] The critical curve $\kappa\mapsto \alpha_c(\kappa)$ is continuous, differentiable at $\kappa \neq \kappa_c$, and monotone increasing for $\kappa \geq \kappa_c$. Furthermore, 
 \begin{equation}
\alpha_c(\kappa) = \frac{2\sqrt{d}(d-1)^{3/4}}{d-2} \sqrt{\kappa - \kappa_c} + O_d(\kappa - \kappa_c),\quad\text{as }\kappa \downarrow \kappa_c
\end{equation}
and 
\begin{equation}
\alpha_c(\kappa) = d^2 \log \bigg( \frac{d-1}{d-2} \bigg)(1+\kappa)^2 + O_d(1),\quad\text{as }\kappa\to\infty.
\end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T11:23:37.839708+00:00","domain":"probability theory","id":"claim_8bdf3f0338e1402e60b2d654023494ee08a3dbf69c18e02e1bce5dc7ce64296e","kind":"definition","schema_version":1,"statement":"[Definition 4 of arXiv:2609.03647, 'Extension Problems for the Vladimirov--Taibleson Operator and the Hierarchical Laplacian'] Let $\alpha>0$. The Vladimirov--Taibleson operator $D^\alpha$ is the nonnegative self-adjoint operator on $L^2(\mathbb{Q}_p^n)$ defined by
    \begin{align*}
        \widehat{D^\alpha f}(\boldsymbol{\xi})
        =\|\boldsymbol{\xi}\|_p^{\alpha}\hat{f}(\boldsymbol{\xi}),
    \end{align*}
    with operator domain
    \begin{align*}
