\end{equation}","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T17:27:32.351652+00:00","domain":"probability theory","id":"claim_8c4992ff3d5d43af66bd7981f13d85b0d0f0a7599e6a95d91231498f39b54e7b","kind":"lemma","schema_version":1,"statement":"[Lemma lemma_steinmethod_xlessthanl of arXiv:2509.18045, 'Density convergence on Markov diffusion chaos via Stein's method'] Fix  $x\leq \ell$ and $k\in \mathbb{N}$. Let the function $h$ in the ODE (equation equation_stein of the paper) be 
    \begin{align*}
        h(y)=h_{k,x}(y):=\mathds{1}_{\{y\leq x\}}\rho_{k+1}(y), \qquad y\in \mathbb{R} \{ y\in (-\infty,x]:b(y)=0\}. 
    \end{align*} 
Then the solution $g_{k,x}:\mathbb{R}\to\mathbb{R}$ to (equation equation_stein_pearson of the paper) exists and satisfies for every $y\in \mathbb{R}$
\begin{align*}
     \abs{ g_{k,x}(y)}&\leq \mathcal{U}_3(k,y):= C\mathds{1}_{\{y\leq \ell\}}  \frac{\sum_{j=0}^{k+1} \left\vert y \right\rvert^j }{\left\vert b(y) \right\rvert^{k+1}\left\vert y-m \right\rvert }
