{"assumptions":[],"created_at":"2026-10-26T20:55:18.057946+00:00","domain":"probability theory","id":"claim_8c73b748d5e9190b72a1ed032b840aca7461a378838ad1ef1fbf5673b353bd3d","kind":"lemma","schema_version":1,"statement":"[Lemma 37 (Stability under linear perturbations of the initial condition) of arXiv:2606.16636, 'Free energy of non-convex multi-species spin glasses with centered Ising spins'] Let $u$ and $v$ be Lipschitz viscosity solutions of the same Hamilton--Jacobi equation on $\R_+\times\mcl Q_2^\sS$, with initial conditions $\psi_u$ and $\psi_v$. Define
\begin{equation*}
    \ell(q):=\sum_{s\in\sS}\int_0^1 q_s(r)\,\d r,\qquad q\in\mcl Q_2^\sS.
\end{equation*}
Assume that, for some $\rho\geq0$,
\begin{equation}

    |\psi_u(q)-\psi_v(q)|\leq \rho\,\ell(q),\qquad q\in\mcl Q_2^\sS.
\end{equation}
Then there is a constant $C_\H<\infty$, depending only on the Lipschitz constant of the Hamiltonian in the equation, such that
\begin{equation}

    |u(t,q)-v(t,q)|\leq \rho\Ll(\ell(q)+C_\H t\Rr),\qquad (t,q)\in\R_+\times\mcl Q_2^\sS.
\end{equation}","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T12:43:43.315328+00:00","domain":"probability theory","id":"claim_8c77f0cb1063090293d188ddf60310cbfaabe1a5337e41c90784495985c846a5","kind":"lemma","schema_version":1,"statement":"[Lemma lem:bulk-rem of arXiv:2506.21466, 'The Markov property for $\varphi^4_3$ on the cylinder'] There exists $C>0$ such that for every $\varepsilon > 0$, the following statements hold.
\begin{enumerate}
\item[(i)] For every $u \in \mathcal L$, 
\begin{equation}
\|{\rm rem}_\varepsilon(u)\|_{\mathcal L} \leq C \left(\| \Xi_\infty(W)\|_{\mathfrak S} + \|\Xi^\partial_\infty(\varphi_-,\varphi_+)\|_{\boldsymbol{
\mathcal B}}+ \|u\|_{\mathcal L}\right).
\end{equation}
\item[(ii)] For every $T \in (0,\infty]$ and $u \in \mathcal L$, 
\begin{equation}
\|Z_T({\rm rem}_\varepsilon(u))\|_{L^4} \leq \left(\|\Xi_\infty(W)\|_{\mathfrak S} + \|\Xi^\partial_\infty(\varphi_-,\varphi_+)\|_{\boldsymbol{
\mathcal B}} + \|Z_T(u)\|_{L^4}\right).
\end{equation}
\item[(iii)] For every $\varepsilon > 0$, there exists $c_\varepsilon > 0$ such that, for every $u \in \mathcal L$,
\begin{equation}
	\|\ell^{\varphi_-,\varphi_+}_\infty({\rm rem}_\varepsilon(u))\|_{\mathcal H}^2 \leq c_\varepsilon \left( (1+\|\Xi_\infty (W)\|_{\mathfrak S} + \|\Xi^\partial_\infty(\varphi_-,\varphi_+)\|_{\boldsymbol{
\mathcal B}})^4 + \|Z_\infty(u)\|_{L^4}^4 + \|u\|_{\mathcal L}^2 \right).
\end{equation}
Furthemore, the map $u \to \ell_{\infty}({\rm rem}_{\varepsilon})$ is a continuous from $\mathcal{L}_{w} \to \mathcal{H}$
\end{enumerate}","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T16:53:30.558166+00:00","domain":"probability theory","id":"claim_8c79a8a5218c000d1897edcd8f775f76fdbf1f934882d8647ff411a74b5f6721","kind":"lemma","schema_version":1,"statement":"[Lemma lem-u-bar is a semimartingale of arXiv:2505.24043, 'Weak solutions of Navier-Stokes Equation with purely discontinuous L\'evy Noise'] The process $\duality{\overline{u}}{\phi}\coloneqq \bigl\{\duality{\overline{u}(t)}{\phi}:\, t\in [0,T]\bigr\}$
