 (W_{1,n},W_{2,n})\Rightarrow(W_1,W_2),
\end{align}
and, for $i=1,2$,
\begin{align}
 \sup_{\mathfrak{s}_0\leqslant s\leqslant \mathfrak{s}_1}
 \abs{e^{-s}N_i(s)-W_{i,n}}
 \stackrel{\pr}{\to}0.
