\end{equation}","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-28T01:10:08.759345+00:00","domain":"probability theory","id":"claim_8cf20b9dde6a5967e6b47d7fdc285e47dd33eb1fd4477529ccd54aec462d347f","kind":"definition","schema_version":1,"statement":"[Def property-a of arXiv:2411.18155, 'Besov regularity of random wavelet series'] Let $d\in\mathds{N}$, $s\in\mathds{R}$, $p,q\in (0,\infty]$, $\alpha,\beta,\gamma,\theta\in\mathds{R}$, $\mu,\nu\in (-\infty,0]$, and $r\in (0,\infty)$.
We say that \emph{Property A is satisfied} if
 \begin{equation*}
\gamma <-\frac{d}{p},\qquad \beta<-\frac{d}{p},\qquad s+\frac{d}{2}+\alpha<0
\end{equation*}
or 
 \begin{equation*}
\gamma <-\frac{d}{p},\qquad \beta<-\frac{d}{p},\qquad s+\frac{d}{2}+\alpha=0,\qquad \theta  <-\frac{1}{q}.
\end{equation*}
When $p=\infty$, the conditions  $\gamma <-\frac{d}{p}$, $\beta<-\frac{d}{p}$ have to be replaced by  $\gamma\leq 0$, $\beta\leq 0$.
When $q=\infty$, the condition $\theta  <-\frac{1}{q}$ has to be replaced by $\theta\leq 0$.

We say that \emph{Property A' is satisfied} if one of the following sets of conditions is satisfied
\begin{enumerate}[label={(\alph*)},leftmargin=*,align=left,noitemsep]
\item{$p\neq\infty$, $q\neq \infty$, $\gamma +\frac{d+\nu}{p}<0$, $\beta +\frac{d+\nu}{p}< 0$, $s+\frac{d}{2}+\alpha+\frac{\mu}{p}< 0$;}
\item{$p\neq\infty$, $q= \infty$, $\gamma +\frac{d+\nu}{p}<0$, $\beta +\frac{d+\nu}{p}< 0$, $s+\frac{d}{2}+\alpha+\frac{\mu}{p}\leq 0$;}
\item{$p=\infty$, $q\neq \infty$, $\gamma\leq 0$, $\beta\leq 0$, $s+\frac{d}{2}+\alpha< 0$;}
\item{$p=\infty$, $q= \infty$, $\gamma\leq 0$, $\beta\leq 0$, $s+\frac{d}{2}+\alpha\leq 0$.}
\end{enumerate}
We say that \emph{Property A'' is satisfied} if one of the following sets of conditions is satisfied
\begin{enumerate}[label={(\alph*)},leftmargin=*,align=left,noitemsep]
\item{$p\neq\infty$, $\gamma +\frac{d}{p} +\frac{\nu }{\max\left\{r,p\right\}}< 0$, $\beta  +\frac{d}{p}+\frac{\nu}{\max\left\{r,p\right\}}< 0$, $s+\frac{d}{2}+\alpha+\frac{\mu}{\max\left\{r,p\right\}}< 0$;}
\item{$p=\infty$, $\gamma\leq 0$, $\beta\leq 0$, $s+\frac{d}{2}+\alpha\leq 0$.}
\end{enumerate}","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-26T20:24:59.500830+00:00","domain":"probability theory","id":"claim_8cf782c23a4ff85c370ced196b73b069aec62e6df405ca80991b88bf03c5b171","kind":"lemma","schema_version":1,"statement":"[Lemma 31 of arXiv:2605.10150, 'Rough path theory and an introduction to rough partial differential equations'] Let $Y : [0,T] \to W$ be measurable and bounded. We define the path $Z : [0,T] \to W$ as
\begin{align*}
Z_t := \int_0^t Y_s \, ds, \quad t \in [0,T].
\end{align*}
Then we have
\begin{align*}
|Z_{s,t}| \leq \| Y \|_{\infty} |t-s| \quad \text{for all $s,t \in [0,T]$.}
\end{align*}","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T12:02:11.325204+00:00","domain":"probability theory","id":"claim_8cf92d3b238e177fc212ed315e3445715aeeec981d776b5323856a42f96a8322","kind":"lemma","schema_version":1,"statement":"[Lem lem-uiqbot-boltzmann of arXiv:2510.26123, 'Directed distances in bipolar-oriented triangulations:\\ exact exponents and scaling limit'] For $r\geq 1$, let
\begin{equation} 
\widehat\tau_r^R := \min\mathopen{}\mathclose\bgroup\originalleft\{ n\in\mathbbm N : \widehat{\mathcal R}(n) = -r \aftergroup\egroup\originalright\}. 
\end{equation}
Let $\widehat M(r)$ be the submap of $\widehat M_{0,\infty}$ obtained by applying the KMSW procedure to $\widehat{\mathcal Z}|_{[0,\widehat\tau_r^R-1]}$. 
Also, let $\widehat z(r)$ be the last (in directed order) vertex on the left boundary of $\widehat M(r)$ which also lies on the left boundary of $\widehat M_{0,\infty}$. 
Then the law of $(\widehat M(r) , \widehat z(r))$ is the Boltzmann distribution on bipolar-oriented triangulations with right boundary length $r$ and a marked left boundary vertex (Definition~(def-boltzmann-right of the paper)). In particular, $\widehat M(r)$ is a bipolar-oriented map with no missing edges. 
Moreover,  with probability tending to one as $A\to\infty$, uniformly in the choice of $r$,
\begin{equation}
    A^{-1}r^{2} \leq \#\mathcal E(\widehat M(r)) \leq Ar^2.
\end{equation}","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-26T19:48:27.282416+00:00","domain":"probability theory","id":"claim_8cf987c1ce7eb2a818d43186d99c82a6d1c629677c2180fcd8622a33fff56381","kind":"definition","schema_version":1,"statement":"[Definition 7 of arXiv:2604.25336, 'Central limit theorem for slow-fast system under mixed fractional Brownian motion'] A weak solution to the following Young-It\^o SDE
\begin{equation}
\dd X_t = F( X_t) \dd B^H_t + G( X_t) \dd t+ V( X_t)\dd W_t,\ X_0 = x \in \mathbb{R}^n,
\end{equation}
is a triple \((X,B^H, W)\) on the probability space \((\Omega, \mathcal{F}, \mathbb{P})\) with filtration \(\{\mathcal{F}_t, t\in[0,T]\}\), where
\begin{itemize}
\item[1.] \((\Omega, \mathcal{F}, \mathbb{P})\) is a complete probability space, \(\{\mathcal{F}_t, t\in[0,T]\}\) is a right-continuous filtration such that \(\mathcal{F}_0\) contains the \(\mathbb{P}\)-null sets;
\item[2.] \(W\) is a \(\mathcal{F}_t\)-\(r\)-dimensional BM;
\item[3.] \(B^H\) is a FBM of Hurst parameter \(H\) that is \(\mathcal{F}_0\)-measurable;
\item[4.] The process \(X\) is \(\mathcal{F}_t\)-adapted and has trajectories in \(C^{\alpha}\) almost surely;
\item[5.] \((X,B^H, W)\) satisfies Young-It\^o SDE \eqref{weak_solution}.
\end{itemize}","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T08:26:47.165499+00:00","domain":"probability theory","id":"claim_8cfe21ec360fdfbd52fc0dd5eae5769c150eddb7895ac3b94539a57de12f3356","kind":"concept","schema_version":1,"statement":"[Ppn 41 of arXiv:2608.29416, 'Algorithmic threshold for high-dimensional projection pursuit I: general theory'] Let $\dbg$ be a standard gaussian in $\R^N$ and 
\beq

    V_\gamma(\by)\equiv \frac{(\dbD \by, \by)}{N}
            +\frac{(\dbX \by, \by)}{N}
            + \frac{2\gamma^{1/2}(\dbg,\by)}{N}\,.
\eeq
Then, with probability $1-e^{-cN}$, 
we have
    \beq

        \sup \Big\{ V_\gamma(\by) :\|\by\|^2=N\Big\}
        \le g(\gamma)
        + \frac{\epsilon'}{10}
    \eeq
simultaneously for all $\gamma \in [0, C_9]$. The constant $c$ depends on $C_9$ and the parameters of Remark~\ref{r:fp-rpr}. (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T19:58:40.868336+00:00","domain":"probability theory","id":"claim_8d00e631a91cf851d8082320831928aca52675b179b67d9943a4211ac2d064ca","kind":"concept","schema_version":1,"statement":"[Proposition prop_1725 of arXiv:2605.10479, 'Poisson approximation of random lattices'] Let $\varphi:\mathcal F(\mathbb R^n)\to [0,\infty)$ be a function such that
$\varphi(Y)=0$ whenever the vectors in $Y$ are linearly dependent.
Let $B\subseteq \mathbb R^n$ be finite, and let $k\geq 0$. Let $R_1,R_2\geq 0$
be integers such that $R_1$ is odd and $R_2$ is even. Then,
\begin{equation*}
\sum_{r=0}^{R_1}
(-1)^r
\sum_{X\in \mathcal S_{k,r}(B)}
\sum_{Y\in {X\choose k}}
\varphi(Y)
\leq
\varphi(B)1_{\{|B|=k\}}
\leq
\sum_{r=0}^{R_2}
(-1)^r
\sum_{X\in \mathcal T_{k,r}(B)}
\sum_{Y\in {X\choose k}}
\varphi(Y).
\end{equation*} (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T10:47:32.883159+00:00","domain":"probability theory","id":"claim_8d06277f1ab8f6b70b825ed8f5a9caeeff5d7be9be6688306ebcf26d72cda511","kind":"theorem","schema_version":1,"statement":"[Proposition 9 of arXiv:2609.02500, '2609.02500'] If $\gamma_q>0$, then $D_q$ is an effective $\Q$-divisor satisfying $D_q\sim_{\Q} H$, and 
\begin{equation}
S_m^n\setminus\Supp(D_q)
\simeq
\Spec\frac{\Bbbk[x,u,v]}{\bigl(uv-P_{T_q}(x)\bigr)}.
\end{equation}
In particular, $U_q=S_m^n\setminus \Supp(D_q)$ is smooth and flexible.","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T14:25:44.581735+00:00","domain":"probability theory","id":"claim_8d09bc0441ee9b0e129fa7660259e21c9d30c4e7ecc213076bd291a4716678c4","kind":"concept","schema_version":1,"statement":"[Quest of arXiv:2509.06730, 'Hyperbolic branching Brownian motion: \\ the empirical limit measure'] In Proposition (prop:conv_typical_to_mu of the paper) we have shown that $\mu_\infty$ is determined by particles that satisfy $Y_u(t)\approx e^{-t/2}$. It would be interesting look at the empirical measure of particles that satisfy $Y_u(t)\approx e^{-t/2+\lambda t}$. This should be non--trivial for any $\lambda$ with $\vert \lambda \vert < \sqrt{2\beta}$. In particular, if you look at $\lambda=1/2$ there should {be} a phase transition when $\beta=1/8$ because this is the threshold for local survival. For BBM on $\ensuremath{\mathbb{R}}$, the  number of particles {at a given speed} is counted by the additive martingale; note that here in the hyperbolic setting
    \begin{equation*}
        \sum_{u\in \mathcal{N}(t)} (Y_u(t))^\lambda e^{-t(\lambda^2+\lambda-2)/2}
    \end{equation*}
    has the same distribution as the regular additive martingale. (Stated as a question by the paper; open unless the paper says otherwise.)","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-26T20:57:44.949216+00:00","domain":"probability theory","id":"claim_8d0c39a60f723dde98ddc32c76e4cc766f8b0269572d37c2bd9b9258f7f64669","kind":"concept","schema_version":1,"statement":"[Lemma 8 (Error estimates) of arXiv:2606.24887, '2606.24887'] Let $\delta \in (0,1)$,  $\Gamma$ be as in \cref{eq:theta} and $\mathfrak c$ as in \cref{lem:roughboundsGT}.  
		If $\frac{\Gamma^2}{32\mathfrak c} \leq d \leq N^{\delta/8}$ then 
		\begin{align}
		\theta \max_{x \in [N],\, i\in \{1,2\}} \left|Y^{i}_{x}\right|  \le \mathcal{C}  \frac{\Gamma}{d}, \qquad 
		\theta \max_{x \in [N],\, i\in \{1,2\}} \left|Z^{i}_{x}\right| & \le \mathcal{C} \biggl( \frac{\Gamma}{d} + \frac{1}{\sqrt{d}} \biggr) \\
			\theta \max_{\substack{x,y \in [2N],\\y\notin \{x,\ubarr{x}\}}} \left|G_{xy}\right| &\le  \mathcal{C}  \frac{\Gamma^2}{\sqrt{d}} \\
			\theta \max_{\substack{x,y \in [2N],\\ \{x,y\}\cap \{a,\ubarr{a}\} =\emptyset }} \bigl|G_{xy} - G_{xy}^{\bset{a}}\bigr| &\le  \mathcal{C}\frac{\Gamma^3}{d} 
		\end{align}
		with very high probability
		uniformly for all $w \in \C$, $a \in [N]$ and $z \in \C_+$ satisfying $\Im z \geq N^{-1+\delta}$. (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T14:05:52.483727+00:00","domain":"probability theory","id":"claim_8d0d9b21d8ef7526beb25c50251f62038dcee721a58b697ae894d5fb6fc440c2","kind":"theorem","schema_version":1,"statement":"[Proposition prop:energy-violations of arXiv:2505.02685, 'On the Spectral Expansion of Monotone Subsets of the Hypercube'] For each $f \in L^2(V)$, it holds that
