\end{equation}
with $\mu > -1$.","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-26T19:45:07.259897+00:00","domain":"probability theory","id":"claim_8d38a36824d6fbb7a515065696db9fee0e142d1d71030d7292d4cbae101e3616","kind":"theorem","schema_version":1,"statement":"[Corollary 10 of arXiv:2604.19738, 'Phase Transitions in the Fluctuations of Functionals of Random Neural Networks \\'] Let $F_L[q]$ be the $q$th chaotic component of $F_L$ (cf.~\eqref{deco Y}). Under the same assumptions of \Cref{cor:boun-hatK-iper}, we have the following asymptotics for fixed $q\in \N$, $q\geq 2$.

\smallskip
\noindent
If $q<d/(2\nu)$, setting $\gimel_q = \beth_q \omega_d^2 q! \varphi_q^2$, as $L\rightarrow\infty$ we have
	\begin{equation*}
		\Var(F_L[q])= v_L^{q} \Big( \gimel_q +o(1) \Big)\,\,\,.
	\end{equation*}

\smallskip
\noindent
If $q\ge d/(2\nu)$, $\varphi_q\neq 0$ and $q$ is even whenever $\kappa$ is odd, we have
\begin{align*}
		\Var(F_L[q])\,\asymp \,
		\begin{cases}
			v_L^q \log(v_L^{-1})\, &\textnormal{if } q=d/(2\nu) \\
			v_L^{d/(2\nu)}\,\, &\textnormal{if }q>d/(2\nu)
		\end{cases}
		\qquad\,.
	\end{align*}","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-26T19:37:51.482408+00:00","domain":"probability theory","id":"claim_8d394fd4f7cb23f4b6fb9b1dcf8422961ea8031b6b49a0fcc946bdb2d4bd21db","kind":"concept","schema_version":1,"statement":"[Lemma 57 (Step A in theorem~\ref{SWLOG}) of arXiv:2604.04267, 'On Sharpest Tail Bounds for Functions \\ of Tail Bounded Random Variables'] This lemma proceeds from the assumptions in theorem~\ref{Smainresult}. Define
\begin{equation} 
   {G^1}' := \Big\{t \in \mathbb{R} \ \big| \ h_1(t) \geq h_1(-t) \Big\}\\
\end{equation}
where, as usual, $h_1(t) = P\{(t,X_2,...,X_n) \in V\}, \ \forall t \in \mathbb{R}$. Define
\begin{equation} 
\phi_1(t) := 
\begin{cases} 
|t| & \text{if }|t| \in {G^1}' \\ 
-|t| & \text{otherwise} 
\end{cases} 
\end{equation} 
Then 
$$
P(X \in V) \leq P\big((\phi \circ X_1,X_2,...,X_n) \in V \big)
$$
\begin{proof} 
Notice, $\forall t \in \mathbb{R}$, $t$ or $-t \in {G^1}'$. Thus
\begin{equation}
({G^1}')_{|\cdot|} = [0,\infty).
\end{equation} 
${G^1}'$ is measurable because ${G^1}' = H_1^{-1}([0,\infty))$, where $H^1(t) = h_1(t) - h_1(-t), \ \forall t \in \mathbb{R}$, which is measurable. 

It is elementary to show $\phi_1$ is Borel measurable. Indeed, $\forall U \subset \mathbb{R}$ measurable, one may verify
\begin{align*} 
\phi_1^{-1}(U) =& \Big[\big( U_{\geq 0} \cap {G^1}'\big) \cup \Big(\big\{-x \ \big| \ x \in U \cap (-\infty,0)   \big\} \backslash {G^1}'\Big) \Big] \\
               &\cup \Big[\big(U_{\geq 0} \cap {G^1}'\big) \cup \Big(\big\{-x \ \big| \ x \in U \cap (-\infty,0) \big\}\backslash {G^1}'\Big) \Big]_{-}
\end{align*}
which is a finite combination of unions, intersections, compliments, and reflections of measurable sets (sections~\ref{abbreviationschapter4} notations)). By theorem~\ref{Fubini'stheorem} applied to the indicator function of $V$, integrating $P(X \in V)$ over the $1$st component, 
$$
P(X \in V) = \int_{\mathbb{R}} h_1 {dX_1}_\#(m) 
$$
where $X_1\#(m)$ is the pushforward \eqref{pushforwarddef} of the Lebesgue measure on $(0,1)$. Similarly, 
$$
P\big((\phi_1 \circ X_1,X_2,...,X_n) \in V \big) = \int_\mathbb{R} h_1 \ d(\phi_1 \circ X_1)_\#(m).
$$
By change of variables for Lebesgue integration, 
\begin{align*} 
&P(X \in V) = \int_{(0,1)} h_1 \circ X_1 \ dm\\
P\big((\phi_1 \circ X_1,&X_2,...,X_n) \in V \big) = \int_{(0,1)} h_1 \circ \phi_1 \circ X_1 \ dm.
\end{align*} 
By definition of $\phi_1$ and ${G^1}'$ \eqref{G1'def}, notice $\forall t \in \mathbb{R}$, $\phi_1$ sends $t$ to $t$ or $-t$, depending which makes $h_1$ larger (with the nuance if $h_1(t) = h_1(-t)$, then $\phi$ sends 
$t$ to $|t|$). That is, $\forall t \in \mathbb{R}, h_1(t) \leq h_1(\phi_1(t))$. Since $X_1:(0,1) \rightarrow \mathbb{R}$ it follows $\forall s \in (0,1), \ h_1(X_1(s)) \leq h_1 \circ \phi(X_1(s))$. The lemma follows 
by monotonicity of Lebesgue integration.  
\end{proof} (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T12:15:15.540998+00:00","domain":"probability theory","id":"claim_8d3e514d081ed3ececfd1fa987de9773649579531f6a057ef357b28eb11807ef","kind":"theorem","schema_version":1,"statement":"[Theorem Phi-returnshift of arXiv:2507.01406, '{\Large On Iterated Lorenz Curves with Applications: The Multivariate Case }'] Fix $i\in \{1,2\}$ and $0<\delta <\eta <1$. There
exist integers $q_{1}<q_{2}<\cdots $, a shift $m=q_{1}$, an FS-set 
\begin{equation}
I=\mathrm{FS}(q_{1},q_{2},\dots ),\qquad I^{\prime }=\mathrm{FS}
(q_{2},q_{3},\dots ),  
\end{equation}
and a continuous function $G_{i}\in C([\delta ,\eta ])$ such that: 
\begin{equation}
\sup_{x\in \lbrack \delta ,\eta ]}|\Phi _{n}^{i}(x)-G_{i}(x)|\rightarrow
0\qquad \text{as }n\rightarrow \infty ,\ n\in I,  
\end{equation}
and 
\begin{equation}
\sup_{x\in \lbrack \delta ,\eta ]}|\Phi _{n+m}^{i}(x)-G_{i}(x)|\rightarrow
0\qquad \text{as }n\rightarrow \infty ,\ n\in I^{\prime }.  
\end{equation}
Moreover, for every $n\in I^{\prime }$, we have $(n,n+m)\in I\times I$.","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-26T20:47:22.250540+00:00","domain":"probability theory","id":"claim_8d405368b1a2e79d84aa1a54a55181e3872c71154039b71e92d8475a8193c39f","kind":"concept","schema_version":1,"statement":"[Lem 52 of arXiv:2605.26664, 'Mixing times for Glauber dynamics of lozenge tilings of the hexagon'] Let $A,K,D$ satisfy \eqref{eq:costanti}. Also let $k \ge 1$ be an integer and $q \in [2^k N^{K \delta-1}, \varepsilon_0]$ be a real number. Further let $q' \ge 0$ satisfy
		\begin{flalign}

			\begin{aligned} 
				& q' \in [q - 2^k N^{(D+1)\delta-1}, q - 2^k N^{(D-1)\delta - 1}]; \qquad 	\mathsf{t}:=q^{-1} k 2^{k+3} N^{1+11K\delta}.
			\end{aligned} 
		\end{flalign}

		\noindent  Consider the Glauber dynamics $(H_t)_{t \ge 0}$ starting from an initial condition $\mu \in \mathcal P^+$ (recall Definition \ref{def:P+}) and assume that, w.o.p. under $\mu$, 
		\begin{flalign}

			\begin{aligned}
				H_0 (w) \le \mathcal{H}_{q} (w) + N^{\delta-1}, \qquad  \text{for each $w \in \mathfrak{X}$}.
			\end{aligned} 
		\end{flalign}

		\noindent Then,  w.o.p., we have
		\begin{flalign}

			H_t (z) \le \mathcal{H}_{q'} (z), \qquad \text{for each $z \in \bigcup_{j=1}^{k+1} \mathcal{A}_j^{q'} (N^{A\delta})$ and $t \in [ \mathsf{t}, N^5]$.}
		\end{flalign} (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-26T19:24:25.930401+00:00","domain":"probability theory","id":"claim_8d47dec547a2c82445f0517806ee8c577833a6083a732ae283c7e2a133ad07a7","kind":"concept","schema_version":1,"statement":"[Thm 1 (Scaling limit for the length of the longest increasing subsequence of the Brownian separable permutons) of arXiv:2506.19123, 'The longest increasing subsequence of Brownian separable permutons'] For all $p\in(0,1)$, let $\sigma_n=\Perm[\bm{\mu}_p,n]$ be a random permutation of size $n$ sampled from the Brownian separable permuton $\bm{\mu}_p$ of parameter $p$, as introduced in \eqref{eq:finite_perm_brownian}. Recall that the permutations $\sigma_n$ are naturally coupled for different values of $n$. We have the almost sure convergence
    \begin{equation}
        \frac{\lis(\sigma_n)}{n^{\alpha}} \xlongrightarrow[n\rightarrow \infty]{a.s.} X,
    \end{equation}  
    where $\alpha=\alpha(p)$ is the unique solution in the interval $(1/2,1)$ to the equation	
        \begin{equation}
            \frac{1}{4^{\frac{1}{2\alpha}}\sqrt{\pi}}\,\frac{\Gamma\big(\tfrac{1}{2}-\tfrac{1}{2\alpha}\big)}{\Gamma\big(1-\tfrac{1}{2\alpha}\big)}=\frac{p}{p-1},
        \end{equation}
    and the limiting random variable $X=X(p)$ is non-deterministic and almost surely positive and finite.
    Moreover, $X$ is a deterministic measurable function of the Brownian separable permuton $\bm{\mu}_p$. (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T10:25:49.867846+00:00","domain":"probability theory","id":"claim_8d48119550ea7b06b4467d83ec710a899851721089d4be65b68d6fd330deaa4a","kind":"concept","schema_version":1,"statement":"[Prop 5 of arXiv:2609.02040, '\Large Quantum Landau Damping with Coulomb Repulsion in the Whole Space'] We consider the linearized Hartree equation~\eqref{eq:Hartree_linear} around the homogeneous state $\opmu=\mu_P(\opp)$. Then if $\rho_\h$ is the associated spatial density, its spatial Fourier transform satisfies
		\begin{equation}
			\widehat\rho_\h(t,k) = \widehat{\rho_\h^\circ}(t,k)- 2\pi\CK \int_0^t e^{-\n{k}(t-s)} \, \frac{\sin\!\lt(2\pi\Omega_k\lt(t-s\rt)\rt)}{\Omega_k} \, \widehat{\rho_\h^\circ}(s,k) \d s \, ,
		\end{equation}
		where
		\begin{equation*}
			\Omega_k=\sqrt{\CK+\tfrac{h^2\n{k}^4}{4}}
		\end{equation*}
		and
		\begin{equation*}
			\rho_\h^\circ(t,x) =\intd \Wigner{\op^\init}(x-tv,v) \d v
		\end{equation*}
		is the free-transport density. (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T22:11:11.700890+00:00","domain":"probability theory","id":"claim_8d48ac338bd3141a223faf1f528c8318a3ac393f54ce97151c583954e5445c95","kind":"theorem","schema_version":1,"statement":"[Prop basis of arXiv:2609.00672, 'Deciding superellipticity and computing the Weierstrass normal form'] The differential $\omega_{a,b}$ is holomorphic on $C$ if and only if $(a,b)\in A$, where

\begin{equation}
A=\Bigl\{(a,b): a\ge 0,\ 0\le b<n,\ a+\sum_{j}\Bigl\lfloor\frac{b\,l_j}{n}\Bigr\rfloor\le\frac{bm}{n}-1-\frac{1}{e_\infty}\Bigr\}.
\end{equation}

The set $\{\omega_{a,b}\}_{(a,b)\in A}$ is a basis of $H^0(C,\Omega^1)$, and

\begin{equation}
\ord_P(\omega_{a,b})=na+n-1-\bigl(b\,l_i \bmod n\bigr),
\end{equation}

where $b\,l_i\bmod n$ denotes the least non-negative residue.","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T20:36:16.061066+00:00","domain":"probability theory","id":"claim_8d4942eb7a986e7c1db91cbca4132923a349d8d1b3c293d544b1b00450f6ea66","kind":"theorem","schema_version":1,"statement":"[Proposition prop:CTL for W of arXiv:2606.28031, 'Insurance risk models in a heterogeneous time-dependent population: scaling limits and rui'] Under Assumptions~(A:hyp LLN for W of the paper) and~(A:hyp TCL for W of the paper), if  $X(1)$ and $Y(1)$ have finite second moments, then
