{"assumptions":[],"created_at":"2026-10-26T20:49:17.499370+00:00","domain":"probability theory","id":"claim_8d613f2f785abcda55cc40ec49ea7b8d4b745180d62057f2939a48fa6040b575","kind":"theorem","schema_version":1,"statement":"[Theorem 10 of arXiv:2605.29608, '2605.29608'] Let $(\{Y_{k}\}_{k\in\mathbb{Z}^{+}},\mathbb{P})$ denote the Markov chain considered in Theorem \ref{thm: transitionmatrix}, and let $\mu_{N}$ be the Gibbs measure of the 1D Ising model defined in Equation~\eqref{eq:isinggibbs}. For any $x\in\mathbb{R}^{N}$, define the function $g_{x}$ on $\Omega$ by
	\begin{align*}
		g_{x}(\sigma)=\langle \sigma	,x\rangle^{2}_{\mathbb{R}^{N}}, \qquad\sigma\in\Omega,
	\end{align*}
	where $\langle \cdot,\cdot\rangle_{\mathbb{R}^{N}}$ denotes the standard inner product on  $\mathbb{R}^{N}$. Then for the coupling constant $\hat{J}=0$ and any $x\in\mathbb{R}^{N}$ with $\Vert x\Vert_{2}^{2}=\langle x,x\rangle_{\mathbb{R}^{N}}\neq 0$, we have
	\begin{align}
		E_{\mu_{N}}[g_{x}]&=\Vert x\Vert_{2}^{2},
	\end{align}
	and the largest eigenvalue $\lambda_{1}(\mathbb{K})$ of the sample covariance matrix $\mathbb{K}$ satisfies
	\begin{align*}	
		\lim_{M\rightarrow+\infty}\lambda_{1}(\mathbb{K})=\frac{1}{N},\qquad \mathbb{P}\text{-a.s.}.
	\end{align*}
	Furthermore, for the coupling constant $\hat{J}=+\infty$ (critical point), we obtain that for any positive integer $N$, 
	\begin{align*}
		\lim\limits_{M\rightarrow+\infty}\lambda_{1}(\mathbb{K})=1,\qquad \mathbb{P}\text{-a.s.},
	\end{align*}
	and the second eigenvalue $\lambda_{2}(\mathbb{K})$ of the sample covariance matrix $\mathbb{K}$ satisfies
	\begin{align*}
		\lim\limits_{M\rightarrow+\infty}\lambda_{2}(\mathbb{K})=0, \qquad\mathbb{P}\text{-a.s.}.
	\end{align*}","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T10:42:55.318973+00:00","domain":"probability theory","id":"claim_8d6324af56c63e278817482299612cfa0a39c88adb9e861b1aad150294d9792a","kind":"lemma","schema_version":1,"statement":"[Lem 29 (Binding dichotomy) of arXiv:2609.02398, '\textbf{Convex Order Comparisons for Sub-Gamma Random Variables}'] Fix $p \in (0, 1/2]$ and $a > 0$, and set $\nu_* \coloneqq \nu^{\SG}_{\max}(p,a)$. Exactly one of the following holds.
\begin{itemize}
    \item[(i)] \emph{(Variance branch.)} $\nu_* = 1/\sqrt{p(1-p)}$, so that $\E[Y_{p,\nu_*}^2] = 1$ and \eqref{eqn:sgfeas} is asymptotically tight as $\lambda \to 0$.
    \item[(ii)] \emph{(Interior branch.)} $\nu_* < 1/\sqrt{p(1-p)}$, and there exists $\lambda_\sharp \in (0, 1/a)$ with
    \begin{align}
        g_p(\lambda_\sharp\nu_*) &= \frac{\lambda_\sharp^2}{2(1 - a\lambda_\sharp)},
        \\
        \nu_*\,g_p'(\lambda_\sharp\nu_*) &= \frac{\lambda_\sharp(2 - a\lambda_\sharp)}{2(1 - a\lambda_\sharp)^2}.

    \end{align}
\end{itemize}
The window endpoint $\lambda = 1/a$ never binds, the envelope diverging there. At $p = 1/2$ the variance branch occurs for every $a > 0$, with $\nu^{\SG}_{\max}(1/2,a) = 2$.","status":"unverified"}

