\end{align}
\end{enumerate}","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-26T19:28:04.860435+00:00","domain":"probability theory","id":"claim_8e2b6d9e7c95014a0ed6c6607a7fdc1b4f94bde54e6a6ce49567ae29852b9df8","kind":"theorem","schema_version":1,"statement":"[Prp 25 of arXiv:2511.21496, 'Optimal local central limit theorems on Wiener chaos'] Let $F \in \bD^{k+1, p}$, $\Delta_F^{-1} \in L^q(\Omega)$, and $G \in \bD^{k, r_0}$ for some $k \in \N$ and $p, q, r_0 \in (1, \infty)$. 
Define $r_j, \  j \in \{1, \ldots, k+1\}$ by \eqref{r_k def}.
\begin{enumerate}
    \item[(1)] If $r_{2j} > 1$ for some $j \in \{0, 1, \ldots, \ceil{\frac{k-1}{2}}\}$, then for every $i \in \{0, 1, \ldots, j\}$ and for any $\varphi \in \cS(\R)$, 
    \begin{equation}
        \E[(\cA^{i}\varphi)(F)G] = \E[\varphi(F)\Upsilon_F^{\circ i}(G)].
    \end{equation}
    \item[(2)] If $k$ is odd and $\frac{1}{r_{k+1}} + \frac{1}{p} \leq 1$, then for any $\varphi \in \cS(\R)$, 
    \begin{equation}
        \E\left[\left(\cA^{\frac{k+1}{2}}\varphi \right)(F)G \right] = \dpairLR{\bW^{1,r_{k+1}'}}{\varphi(F)}{\Upsilon_F^{\circ \frac{k+1}{2}}(G)}{\bW^{-1, r_{k+1}}}, \qquad \frac{1}{r_{k+1}} + \frac{1}{r_{k+1}'} = 1.
    \end{equation}
\end{enumerate}","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T06:32:19.969304+00:00","domain":"probability theory","id":"claim_8e2f5acc42d92dc631b6f8a91b9ea55240fd6888270350a0c8cd007ed9b14d3f","kind":"concept","schema_version":1,"statement":"[Theorem 4 (Modified, $L$-fold, coupled spherical integration for rank $M(N)\geq 1$) of arXiv:2608.03273, 'On the Asymptotic of Coupled Spherical Integrals: An Operator-Valued Extension of the Free'] Let $L=O(1)$, $M(N)=O\left(N^{1/2-\epsilon}\right)$ for some $\epsilon >0$, and $D_{l,i}= O_{l,i}\Sigma_{l,i} V^\dagger$ have a single non-zero singular value $\sqrt{\theta_{l,i}}$ at the $i^\mathrm{th}$ on-diagonal position of $\Sigma_{l,i}$. 
Define the modified, $L$-fold coupled HCIZ integral by
\begin{align}
    J_N^{(\beta)}\left(\left\{D_{l,i}\right\},\left\{E_{lk,i}\right\}\right)
    =
    \int
        \exp\left\{
            \sum_{i=1}^{M(N)}
            \sum_{l,k=1}^{L}
                N\mathrm{tr}\left(
                    D_{k,i} D_{l,i}^\dagger
                    U_l^\dagger
                    E_{lk,i}
                    U_k
                \right)
        \right\}
        \prod_{l=1}^{L}
            \mathrm d m_N^{(\beta)}(U_l)
            .
\end{align}
The block matrix $Z_{N,i}$ is structured as in Definition~\ref{def:operator_valued_convergence}, i.e. the block at position $(l,k)$ of $Z_{N,i}$ is $E_{lk,i}$ with $E_{lk,i} = E_{kl,i}^\dagger\in \mathbb A^{N\times N}$ for all $(l,k)$, $Z_{N,i}$ converges to some $Z_{i}$ with finite moments as $N\uparrow\infty$, is R-cyclic, and $||E_{lk,i}||_\infty<\infty$ for all $(l,k,i)$ as $N\uparrow\infty$.
If all $\theta_{l,i}$ are sufficiently small, such that
\begin{align}
-P_{i}=-\mathrm{diag\left\{\frac{2\theta_{1,i}}\beta,\ldots,\frac{2\theta_{L,i}}\beta\right\}}
    \in \left\{\left.G_{Z_{i}}^{\mathcal D_L}(S) \right| S^{Z_i}\in\mathcal S_{\{-\}^L}\right\},
\end{align}
then
\begin{align}
    \lim_{N\uparrow\infty} \frac{1}{NM(N)}
    \log J_N^{(\beta)}\left(\left\{D_{l,i}\right\},\left\{E_{lk,i}\right\}\right)
    =
    \lim_{N\uparrow\infty}
    \frac{1}{M(N)}
    \sum_{i=1}^{M(N)}
        \frac{\beta}{2}
        \int_{0}^1
            \mathrm{tr}\left(
                R_{Z_{i}}^{\mathcal D_L}(P_i w) P_i
            \right)
            \mathrm d w.
\end{align} (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-26T19:45:07.264261+00:00","domain":"probability theory","id":"claim_8e3000c1eefc77d811c68aa6d7a6452f8b755850fae75f7731021fa925efbbba","kind":"concept","schema_version":1,"statement":"[Proposition 3 of arXiv:2604.19924, 'Fluctuation theory for spectrally negative Lévy processes killed by additive functionals'] Let $A$ be a PcNAF and $\nu_A$ its Revuz measure. Then, for any $x \in \R$,
