{"assumptions":[],"created_at":"2026-10-27T22:46:36.162733+00:00","domain":"probability theory","id":"claim_8ec8dfbe49257fa80aaf07d08a906f12dc2509bef054c468db4e8d4b4b1a7a7b","kind":"theorem","schema_version":1,"statement":"[Prop Prop_Universal_Slice of arXiv:2609.02848, 'The universal moduli space of non-degenerate $\Z/2\Z$~harmonic spinors'] Let
  $\mathbf{Sl} \subseteq \mathbf{Dir} \times \mathbf{Ram}$ be a slice and
  $({\mathbf{p}}_0,[{\mathfrak l}_0]) \in \mathbf{Sl}$.
  \begin{enumerate}
  \item

    For every $({\mathbf{p}},[{\mathfrak l}]) \in \mathbf{Sl}$ the identity maps induce tame isomorphisms
    \begin{align*}
      H_a^\infty\Gamma\paren{X{\backslash} \mathrm{Br}({\mathfrak l}_0),S\otimes{\mathfrak l}_0;{\mathbf{p}}_0}
      &\cong
        H_a^\infty\Gamma\paren{X{\backslash} \mathrm{Br}({\mathfrak l}),S\otimes{\mathfrak l};{\mathbf{p}}} = \mathbf{E}_{{\mathbf{p}},{\mathfrak l}}, \\

      H_b^\infty\Gamma\paren{X{\backslash} \mathrm{Br}({\mathfrak l}_0),S\otimes{\mathfrak l}_0;{\mathbf{p}}_0}
      &\cong
        H_b^\infty\Gamma\paren{X{\backslash} \mathrm{Br}({\mathfrak l}),S\otimes{\mathfrak l};{\mathbf{p}}} = \mathbf{F}_{{\mathbf{p}},{\mathfrak l}}, \quad\text{and} \\

      \Gamma\paren{\mathrm{Br}({\mathfrak l}_0),\check S_{{\mathbf{p}}_0}}
      &\cong
        \Gamma\paren{\mathrm{Br}({\mathfrak l}),\check S_{{\mathbf{p}}}} = \mathbf{G}_{{\mathbf{p}},{\mathfrak l}}.
    \end{align*}
  \item

    The maps
    \begin{align*}
      {\mathbf{D}}|_\mathbf{Sl} \mskip0.5mu\colon\thinspace \mathbf{Sl} \times H_a^\infty\Gamma\paren{X{\backslash} \mathrm{Br}({\mathfrak l}_0),S\otimes{\mathfrak l}_0;{\mathbf{p}}_0} &\to H_b^\infty\Gamma\paren{X{\backslash} \mathrm{Br}({\mathfrak l}_0),S\otimes{\mathfrak l}_0;{\mathbf{p}}_0} \quad\text{and} \\
      {\mathbf{res}}|_{\mathbf{Sl}} \mskip0.5mu\colon\thinspace \mathbf{Sl} \times H_a^\infty\Gamma\paren{X{\backslash} \mathrm{Br}({\mathfrak l}_0),S\otimes{\mathfrak l}_0;{\mathbf{p}}_0} &\to \Gamma\paren{ \mathrm{Br}({\mathfrak l}_0),\check S_{{\mathbf{p}}_0}}
    \end{align*}
    induced by ${\mathbf{D}}$ and $\mathbf{res}$ are tame smooth.
  \end{enumerate}","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T13:52:23.575818+00:00","domain":"probability theory","id":"claim_8ec963b2456e9b17fbd02440e0bae5a6c18e5e495bd0c818558ef34d1c897000","kind":"lemma","schema_version":1,"statement":"[Lemma L:ML-Est of arXiv:2602.05317, 'Strong local nondeterminism for stochastic time-fractional\\ slow and fast diffusion equat'] Suppose that $\theta+ H>1$, $H\in (0,1)$, and $\beta\in (0,2]$. Then we have:
    \begin{enumerate}[\rm (i)]
      \item Suppose one of the following conditions: i) $\beta\in(0,2)$, and ii) $\beta = 2$, $\theta \geq 3$. Then, with  $C_{\beta,\theta} > 0$, for
          all $t>0$ and $\lambda>0$, it holds that
          \begin{align}
            \int_0^t w^{(\theta-1) / H} \left| E_{\beta,\theta}\left(-\lambda w^\beta \right)\right|^{1/H}\ensuremath{\mathrm{d} } w
            \le C_{\beta,\theta}\:\frac{t^{(\theta + H-1) /H}}{1+(t\lambda^{1/\beta})^{\min\left(\beta /H,(\theta + H-1) /H\right)}};
          \end{align}

    \item If $\beta = 2$ and $\theta \in [2,3)$, for some positive constant $C_{\theta}$, for all
          $t>0$ and $\lambda>0$, it holds that
          \begin{align}
            \int_0^t w^{(\theta-1) / H} \left| E_{2,\theta}\left(-\lambda w^2 \right)\right|^{1/H}\ensuremath{\mathrm{d} } w
            \le C_{\theta}\:\frac{t^{(\theta + H-1) /H}}{1+(t\lambda^{1/2})^{(\theta - 1)/H}}.
          \end{align}

  \end{enumerate}","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T21:51:33.331197+00:00","domain":"probability theory","id":"claim_8ecb3ffa2dc8917b3e4703c4f4eb34c3d7752eadd517c8e9dec3fb9728600e42","kind":"lemma","schema_version":1,"statement":"[Lemma kappa-bousfield of arXiv:2608.28504, 'Global $\bm\infty$-categories and global Thom spectra'] Let ${\mathcal{C}}$ be globally presentable. A left adjoint $F\colon{\mathpalette\ulhelper{{\mathfrak d\kern-.25pt}{\mathfrak S\kern-.5pt\mathfrak p}}}\hbox{\rule[-2pt]{0pt}{0pt}}_\textup{lvl}\to{\mathcal{C}}$ factors through ${\mathpalette\ulhelper{\mathfrak d\kern-.25pt}}\hbox{\rule[-2pt]{0pt}{0pt}}{\mathfrak S\kern-.5pt\mathfrak p}_\textup{gl}$ if and only if $F$ inverts the natural transformations $\kappa$ from the previous construction for all compact Lie groups $G$ and representations $V,W$.
    \begin{proof}
        The left adjoint $F$ factors through the localization if and only if its right adjoint $U\colon{\mathcal{C}}\to{\mathpalette\ulhelper{{\mathfrak d\kern-.25pt}{\mathfrak S\kern-.5pt\mathfrak p}}}\hbox{\rule[-2pt]{0pt}{0pt}}_\textup{lvl}$ factors through the full subcategory ${\mathpalette\ulhelper{\mathfrak d\kern-.25pt}}\hbox{\rule[-2pt]{0pt}{0pt}}{\mathfrak S\kern-.5pt\mathfrak p}^\Omega$. By definition, this precisely amounts to requiring that the pastings
        \[
            \begin{tikzcd}
                {\mathcal{C}}\arrow[from=d,"="]\arrow[r, "U"]&{\mathpalette\ulhelper{{\mathfrak d\kern-.25pt}{\mathfrak S\kern-.5pt\mathfrak p}}}\hbox{\rule[-2pt]{0pt}{0pt}}_\textup{lvl}\arrow[r,"\ev_V"]\arrow[from=d,"="{description}]\arrow[dr,Rightarrow,"\tilde\sigma"{description},shorten=1em] &[2em] \ul{{\mathfrak S\kern-.4pt}}_{\textup{gl},*}(\mathbb B{G}\times-)\\
                {\mathcal{C}}\arrow[r, "U"']& {\mathpalette\ulhelper{{\mathfrak d\kern-.25pt}{\mathfrak S\kern-.5pt\mathfrak p}}}\hbox{\rule[-2pt]{0pt}{0pt}}_\textup{lvl}\arrow[r,"\ev_{V\oplus W}"'] & \ul{{\mathfrak S\kern-.4pt}}_{\textup{gl},*}(\mathbb B{G}\times-)\arrow[u,"\Omega^W"']
            \end{tikzcd}
        \]
        are equivalences for all compact Lie groups $G$ and $G$-representations $V,W$. However, as a natural transformation is an equivalence if and only if its total mate is so and since passing to mates is compatible with pastings, this is in turn equivalent to the pastings
        \[
            \begin{tikzcd}
                {\mathcal{C}}\arrow[d,"="']\arrow[from=r, "F"']&{\mathpalette\ulhelper{{\mathfrak d\kern-.25pt}{\mathfrak S\kern-.5pt\mathfrak p}}}\hbox{\rule[-2pt]{0pt}{0pt}}_\textup{lvl}\arrow[from=r,"{\textbf{\textup{O}}(V,-)\otimes_G{-}}"']\arrow[d,"="{description}]\arrow[from=dr,Rightarrow,"\kappa"{description},shorten=1em] &[4em] \ul{{\mathfrak S\kern-.4pt}}_{\textup{gl},*}(\mathbb B{G}\times-)\\
                {\mathcal{C}}\arrow[from=r, "F"]& {\mathpalette\ulhelper{{\mathfrak d\kern-.25pt}{\mathfrak S\kern-.5pt\mathfrak p}}}\hbox{\rule[-2pt]{0pt}{0pt}}_\textup{lvl}\arrow[from=r,"\;{\textbf{\textup{O}}(V\oplus W,-)\otimes_G{-}}"] & \ul{{\mathfrak S\kern-.4pt}}_{\textup{gl},*}(\mathbb B{G}\times-)\arrow[from=u,"\Sigma^W"]
            \end{tikzcd}
        \]
        being equivalences, which precisely amounts to $F$ inverting the maps $\kappa$.
    \end{proof}","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-28T00:04:30.568681+00:00","domain":"probability theory","id":"claim_8ecbfc5698fad692fa2fb4b6261db12a2a9306ff2ca4eec056496765c13e7907","kind":"concept","schema_version":1,"statement":"[Lemma lmm:complementary scaling of arXiv:2411.10311, 'Planar Novikov-Shubin invariant for adjacency matrices of structured directed dense random'] There is a constant $C>0$, such that uniformly for all $\tau \le \rho(S)/2$ the polynomial bounds 
\bels{power law bound}{
\tau^C \lesssim v \lesssim \tau^{-C}\,,\qquad  \tau^C \lesssim w \lesssim \tau^{-C},
}
are satisfied. Furthermore,  
\bels{v average scaling}{
\widetilde{v}_k\sim \avg{\widetilde{v}_k} \sim \frac{1}{\widetilde{w}_k} \sim \frac{1}{\avg{\widetilde{w}_k}} \,, 
}
hold true for all $k \in \llbracket L \rrbracket$  and 
\bels{monotonicity for v}{
\avg{\widetilde{v}_k} \lesssim \avg{\widetilde{v}_l}\,, \qquad \avg{\widetilde{w}_l} \lesssim \avg{\widetilde{w}_k}\qquad \text{ for all }\; k \LHD l\,.
} (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T17:24:45.892700+00:00","domain":"probability theory","id":"claim_8ed4ad054cea1b32d9bb3712dd6fb82aaa1f15602c9fd5bf566238ee2d61948d","kind":"concept","schema_version":1,"statement":"[Corollary $(P_{la})_{ra}$ as the closest Markov kernel of arXiv:2509.02996, 'Group-averaged Markov chains: mixing improvement'] Assume that $\pi,\nu,G,P,\mathcal{X}$ satisfy the assumptions as stated in Theorem (thm:pythHS of the paper). We have
	\begin{align*}
		\norm{P_{da}-\Pi}_{\mathrm{HS}} &\geq \norm{(P_{la})_{ra}-\Pi}_{\mathrm{HS}}.
	\end{align*}
	In particular,
	\begin{align*}
		\norm{\overline{P}-\Pi}_{\mathrm{HS}} &\geq \norm{(P_{la})_{ra}-\Pi}_{\mathrm{HS}}, \quad \norm{\widetilde{P}-\Pi}_{\mathrm{HS}} \geq \norm{(P_{la})_{ra}-\Pi}_{\mathrm{HS}}, \\
		\norm{P_{la}-\Pi}_{\mathrm{HS}} &\geq \norm{(P_{la})_{ra}-\Pi}_{\mathrm{HS}}, \quad \norm{P_{ra}-\Pi}_{\mathrm{HS}} \geq \norm{(P_{la})_{ra}-\Pi}_{\mathrm{HS}}. 
