{"assumptions":[],"created_at":"2026-10-27T23:03:39.758615+00:00","domain":"probability theory","id":"claim_8f134a74c3a0ba2b4068985174f201f9873d78f50b11751921d519b450784e3d","kind":"lemma","schema_version":1,"statement":"[Lemma lem:moment-boud:H^1_epsilon of arXiv:2411.02459, 'Existence and higher regularity of statistically steady states for the stochastic Coleman-'] Assume the hypotheses of~Theorem (thm:well-posed of the paper) and let $U_0=(u_0,\eta_0)\in \mathcal{H}^1_\mu$. Then
\begin{enumerate}
[noitemsep,topsep=0pt,wide=0pt,label=\arabic*.,ref=\theassumption.\arabic*]
\item For all $\beta$ sufficiently small independent of $\mu\in\mathcal{M}_\delta$,
\begin{equation}
\mathbb{E} \exp\left({\beta\Psi_1(U(t))}\right)\le  e^{-c_{1,0}t}\exp\left({\beta C_{1,0}\Psi_1(U_0)}\right)+C_{1,0},\quad t\ge 0,
\end{equation}
where $\Psi_1(u,\eta)$ is as in (equation form:Psi_1 of the paper) and $c_{1,0}=c_{1,0}(\beta)>0$, $C_{1,0}=C_{1,0}(\beta)>0$ do not depend on $U_0$, $\mu\in\mathcal{M}_\delta$ and $t\ge 0$.

\item For all $n\ge 1$, there exist positive constants $c_{1,n}$, $C_{1,n}$ independent of $U_0$, $\mu\in\mathcal{M}_\delta$ and $t\ge 0$ such that
\begin{equation}  
\emph{d} \Psi_1(U(t))^n\le -c_{1,n} \Psi_1(U(t))^n\emph{d} t+C_{1,n}\emph{d} t+C_{1,n}\Psi_0(U(t))^{n}\emph{d} t+\emph{d} M_{1,n}(t),
\end{equation}
where $M_{1,n}(t)$ is the semi-martingale given by
\begin{equation} 
M_{1,n}(t)=\int_0^t n\Psi_1(U(r))^{n-1}\langle A^{1/2}u(t),A^{1/2}Q\emph{d} w(r)\rangle_H.
\end{equation}
Furthermore,
\begin{equation} 
\mathbb{E}\Psi_1(U(t))^n \le C_{1,n}e^{-c_{1,n}t}\Psi_1(U_0)^n+C_{1,n},\quad t\ge 0.
\end{equation}
\end{enumerate}","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-26T19:33:46.774040+00:00","domain":"probability theory","id":"claim_8f1635dad9601e980bb8e33c7b5e973d4ba2f41282b9c2ac59a959a4e9b8a064","kind":"lemma","schema_version":1,"statement":"[Lemma 73 of arXiv:2603.24616, 'Pinning in non-critical half-space geometric last passage percolation'] Fix $T_1 \in \mathbb{N}$, $\vec{y} \in \mathfrak{W}_2$, $q \in (0,1)$, $c \in [0, q^{-1})$, and complex numbers $\hat{q}, \hat{c} \in \mathbb{C}$ with $|\hat{q}| = q$ and $|\hat{c}| = c$. Then, the series
\begin{equation}
 \sum_{\mathfrak{B} \in \Omega_{\ice}(T_1, \vec{y})} W(\mathfrak{B};\hat{q},\hat{c})  =:Z(T_1, \vec{y}; \hat{q},\hat{c}),
\end{equation}
converges absolutely. In addition, we have the following formula 
\begin{equation}
Z(T_1, \vec{y}; \hat{q},\hat{c}) = \frac{\hat{q}^{y_1 - y_2}}{2 \pi \im} \oint_{C_{r_1}}du \frac{H_{T_1}(u)H_{T_1}(\hat{q}^2/u)}{u^{y_1 - y_2 + 1}(1- u\hat{c}/\hat{q})} - \frac{\hat{q}^{y_1 - y_2+2}}{2\pi \im}\oint_{C_{r_2}}du \frac{H_{T_1}(u) H_{T_1}(\hat{q}^2/u)}{u^{y_1 - y_2 + 3}(1 - \hat{q}\hat{c}/u)},
\end{equation}
where $H_{T_1}(x) = (1- x)^{-T_1}$. The contours $C_{r_i}$ are positively oriented circles that are centered at the origin where $r_1, r_2 \in (q^2,1)$, $r_1$ is sufficiently close to $q^2$ and $r_2$ is sufficiently close to $1$, so that $cr_1/q < 1$ and $qc/r_2 < 1$.","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T09:48:30.896520+00:00","domain":"probability theory","id":"claim_8f16707d240bb70b16a4658c36ec76233f5111b996a7cbce735c03f5744bf4e7","kind":"concept","schema_version":1,"statement":"[Theorem 2 of arXiv:2609.00867, '2609.00867'] Under Assumption~\ref{ass:kernel-density}, let \(g=g_{d,s}^{(m)}\).
Let \((\kappa_j)_{j\ge1}\) be the nonnegative eigenvalues of \(A_{g,\rho}\)
in nonincreasing order, repeated according to multiplicity, and let
\((Z_j)_{j\ge1}\) be independent standard Gaussian variables.  Then
\begin{equation}
 \cU_{N,\rho}(g)
 \xrightarrow[N\uparrow\infty]{\mathrm{law}}
 \cQ_{g,\rho}
 :=\frac12\sum_{j\ge1}\kappa_j(Z_j^2-1),
\end{equation}
where the series on the right-hand side converges in \(L^2\) and belongs to
the second Wiener chaos.
Moreover, for every \(\beta>0\),
\begin{align}
 \cZ_{\infty,\rho}(\beta;g)
 :=\lim_{N\uparrow\infty}\cZ_{N,\rho}(\beta;g)
 &=\E e^{-\beta\cQ_{g,\rho}}\notag\\
 &=\dettwo(\Id+\beta A_{g,\rho})^{-1/2},             
\end{align}
and
\begin{equation}
 \lim_{N\uparrow\infty}\log\cZ_{N,\rho}(\beta;g)
 =\log\cZ_{\infty,\rho}(\beta;g)
 =\frac12\sum_{j\ge1}
 \bigl(\beta\kappa_j-\log(1+\beta\kappa_j)\bigr).
\end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T07:06:18.058291+00:00","domain":"probability theory","id":"claim_8f194bace39c8e670c264ba69a9a07fd1d0e97f3a92a4251b8d4c18bb9f0a696","kind":"concept","schema_version":1,"statement":"[Lemma 36 of arXiv:2608.15914, 'Absorption cutoff and stationary singularities for rounded Gaussian random dynamical syste'] Let \cref{ass:gaussian-stable-selected} hold. Then, for every
