{"assumptions":[],"created_at":"2026-10-26T19:47:01.665837+00:00","domain":"probability theory","id":"claim_8f336ff6bccdda605b23cb18d61d0b47cd6cce49cebd0aec1e8588ef5d895f00","kind":"theorem","schema_version":1,"statement":"[Proposition 19 of arXiv:2604.23656, 'Doubly Reflected Backward SDEs Driven by $G$-Brownian Motion with Quadratic Generator'] Let $(\xi^i,g^i,L^i,U^i)$ be two sets of parameters such that $(\xi^i,g^i)$ satisfies (H1) and (H3), $L^i,U^i$ satisfy Assumption \ref{assLU} (1), $i=1,2$. Suppose that $(Y^i,Z^i,A^i)\in S_G^\infty(0,T)\times BMO_G\times\cap_{\alpha\geq 2}S^\alpha_G(0,T)$ is a solution to the doubly reflected $G$-BSDE with parameters $(\xi^i,g^i,L^i,U^i)$, $i=1,2$. Moreover, assume that 
    \begin{align*}
        \|L_z(1+|Z^1|+|Z^2|)\|_{BMO_G}<\phi(q):=\left(1+\frac{1}{q^2}\log \frac{2q-1}{2(q-1)}\right)^{\frac{1}{2}}-1,
    \end{align*}
    where $q>1$. Then, for any $p>\frac{q}{q-1}$, there exists a constant $C:=C(p,T,L_z,L_y,\bar{\sigma},N_0)$, such that for any $t\in[0,T]$,
    \begin{align*}
        |Y^1_t-Y^2_t|^2\leq &C\left(\hE_t\left[|\xi^1-\xi^2|^{2p}\right]\right)^{\frac{1}{p}}+C\left(\hE_t\left[\left(\int_t^T|\hat{\lambda}_s|^2 d\langle B \rangle_s\right)^p\right]\right)^{\frac{1}{p}}\\
        &+C\Psi_{t,T}\left(\hat{\mathbb{E}}_t\left[\sup_{s\in[t,T]}|\hat{L}_s|^{2p}\right]+\hat{\mathbb{E}}_t\left[\sup_{s\in[t,T]}|\hat{U}_s|^{2p}\right]\right)^{\frac{1}{2p}},
    \end{align*}
    where $\hat{\lambda}_s=g^1(s,Y^2_s,Z^2_s)-g^2(s,Y^2_s,Z^2_s)$ and
    \begin{align*}
        \Psi_{t,T}=\liminf_{n\rightarrow\infty}\left(\sum_{i=1}^2\left(\hE_t\left[|A^{i,n,+}_T|^{2p}\right]+\hE_t\left[|A^{i,n,-}_T|^{2p}\right]\right)\right)^{\frac{1}{2p}}.
    \end{align*}","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T07:21:06.876765+00:00","domain":"probability theory","id":"claim_8f337317a51f760440ce0d354eb006e40b28e885b6b1b8ba24332842b612790e","kind":"lemma","schema_version":1,"statement":"[Lemma 17 of arXiv:2608.21255, 'Laws of the iterated logarithm for random Dirichlet series with general weights'] Let $N$ be a positive integer-valued function. 
Fix any $\gamma\in (0, (\sqrt{5}-1)/2)$, pick any $\rho=\rho(\gamma)$ satisfying
