{"assumptions":[],"created_at":"2026-10-27T22:11:11.719134+00:00","domain":"probability theory","id":"claim_8f3fa978b82695eff3699cf5a50d7433eab9545cb481b68e3fdbee1b1081ebb5","kind":"theorem","schema_version":1,"statement":"[Proposition prop:wedge-wellposedness of arXiv:2609.00698, 'Kinetic Wedge Layers and Diffusive Limit of Neutron Transport in Polygonal Domains'] Let $0<\omega<\pi$, $1<\beta<\pi/\omega$ and $s>\beta+2$, and suppose the measurable source and incoming ray data in (equation eq:defect-wedge-problem of the paper) satisfy $\mathcal A_{s}<\infty$ in the sense of (equation eq:abstract-wedge-data-assumption-v6 of the paper). Then the wedge-corrector problem (equation eq:defect-wedge-problem of the paper) has a unique bounded mild solution $D$, and
\begin{align}
 \esssup_{Y,v}\left\langleR\right\rangle^\beta
 \Big(\abs{D(Y,v)}+\abs{\mathbf P D(Y)}\Big)
 \le C(\omega,\beta,s)\mathcal A_{s}.

\end{align}
As a consequence $\abs{D(Y,v)}+\abs{\mathbf P D(Y)}\le C\mathcal A_{s}\left\langleR\right\rangle^{-\beta}$, and the solution depends linearly and continuously on $F,h_1,h_2$ in the weighted norms (equation eq:wedge-data-weighted-norms of the paper).","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T20:53:00.842179+00:00","domain":"probability theory","id":"claim_8f405952d9be1b3511d6a767cb9cbce5988c792b37b6ddab125ce720721e1ae6","kind":"lemma","schema_version":1,"statement":"[Lemma lem: J sum of arXiv:2607.18635, 'Remainders of generalised Taylor expansions and a priori bounds for rough differential equ'] Fix $\rho\in{\mathcal T}_b^{I_{k-1}}$ and any $\ell\in\{1,\ldots, m_L(\rho)+1\}$. Then 
		\begin{itemize}
			\item For $f:\{0,1,\ldots, k\}\to\mathbb{R}^n$,
			\begin{equation}
				\sum_{j\le k} J_{\bullet_k\to_\ell\rho,1}(\,j) \, f(\,j)= \sum_{\boldsymbol{i}_\ell\in\{0,\ldots,k-1\}^\ell_<} 
				J_{\rho,\ell}(\boldsymbol{i}_\ell) \sum_{j=i_1+1}^k f(\,j)\,.	
			\end{equation}

			\item	For $m\in\{2,\ldots,\ell\}$, and $f:\{0,1,\ldots, k\}^{m}_<\to\mathbb{R}^n$,
			\begin{align}
				&\sum_{\boldsymbol{j}_{m}\in\{0,\ldots,k\}^{m}_<} J_{\bullet_k\to_\ell\rho,m}(\,\boldsymbol{j}_{m}) \, f(\,\boldsymbol{j}_{m})= 
				\sum_{\boldsymbol{i}_\ell\in\{0,\ldots,k-1\}^\ell_<}\,\sum_{i=i_{m-1}+1}^{i_{m}}
				J_{\rho,\ell}(\boldsymbol{i}_\ell)  \, f(\,\boldsymbol{i}_{m-1}, i)\,.
			\end{align}
			\item Finally for $f:\{0,1,\ldots, k\}^{\ell+1}_<\to\mathbb{R}^n$,
			\begin{equation}
				\sum_{\boldsymbol{j}_{\ell+1}\in\{0,\ldots,k\}^{\ell+1}_<} J_{\bullet_k\to_\ell\rho,\ell+1}(\,\boldsymbol{j}_{\ell+1})\, f(\,\boldsymbol{j}_{\ell+1})= \sum_{\boldsymbol{j}_{\ell}\in\{0,\ldots,k\}^{\ell}_<} J_{\rho,\ell}(\\,\boldsymbol{j}_{\ell}) \sum_{i=j_\ell+1}^k f(\,\boldsymbol{j}_{\ell},i)\,.
\end{equation}
		\end{itemize}","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-26T19:37:51.467669+00:00","domain":"probability theory","id":"claim_8f43e840a00297ad1e27646f1e3add54235fd638bfa269fc4af95d526bc3b428","kind":"theorem","schema_version":1,"statement":"[Theorem 33 of arXiv:2604.04267, 'On Sharpest Tail Bounds for Functions \\ of Tail Bounded Random Variables'] Let $f \in \mathcal{B}^n$. Let $Q:(x_1,...,x_n) \mapsto (|x_1|,...,|x_n|), \ \forall x \in \mathbb{R}^n$. Let $V \subset \mathbb{R}^n$ be closed. Then 
\begin{equation} 
\sup P(X \in V ) = \sup P\big(X \in \partial_{SW} Q(V)\big)
\end{equation} 
where the supremums are taken over\footnote{$X_k$ are not required to be independent.} $X = (X_1,...,X_n) : \Omega \rightarrow \mathbb{R}^n$ such that $P(|X_k| \geq t) \leq f_k(t), \ \forall t \geq 0, \ k=1,...,n$.","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-26T19:48:27.275681+00:00","domain":"probability theory","id":"claim_8f441331bfafee08d6b113d5c1629dfc070134fcfa4988d7930fe7f244230e4b","kind":"lemma","schema_version":1,"statement":"[Lem 9 ({Penrose~\cite[Corollary~3.6) of arXiv:2604.24624, 'Limit distributions of the threshold radius for the maximum degree and the associated poin'] {Penrose.2003}}]
    Let $j \geq 2$ and $\{\Gamma_i\}_{i=1}^m$ be a set of non-isomorphic feasible connected graphs with $j$ vertices.
    Suppose that $(r_n)_{n \in \BN}$ satisfies $n^j r_n^{d(j-1)} \to \beta$ for some $\beta \in (0,\infty)$.
    Let $\{Z_i\}_{i=1}^m$ be a set of independent Poisson random veriables with $E[Z_i] = \beta \mu_{\Gamma_i}$.
    Then,
    \begin{equation*}
        (G_n(\Gamma_1), \cdots, G_n(\Gamma_m)) \xrightarrow{d} (Z_1, \cdots, Z_m)
