{"assumptions":[],"created_at":"2026-10-27T19:48:47.287827+00:00","domain":"probability theory","id":"claim_8f79adac3db0e405f0aef6e6cd25aab59e89b718bbb0c21731f94e51822134e9","kind":"concept","schema_version":1,"statement":"[Lemma free co of arXiv:2604.20660, 'The Legendre structure of the TAP complexity\\ for the Ising spin glass'] Let $\mu$ be a probability measure on $\mathbb{R}$ and $t>0$. The mapping $H_t$ is a homeomorphism from $\overline{\Omega_{\mu,t}}$ onto $\mathbb{C}^+\cup\mathbb{R}$, which restricts to a conformal bijection from $\Omega_{\mu,t}$ onto $\mathbb{C}^+$. Its inverse
		\begin{equation*}
			\omega_{\mu,t} \colon \mathbb{C}^+\cup\mathbb{R} \longrightarrow \overline{\Omega_{\mu,t}}
		\end{equation*}
		is called the \emph{subordination function}. Moreover, for every $z\in \Omega_{\mu,t}$,
		\begin{equation}
			G_{\mu\boxplus \sigma_t}\bigl(z+tG_\mu(z)\bigr) = G_\mu(z).
		\end{equation}
		If the support of $\mu$ is bounded from below, the left edge of $\mu\boxplus\sigma_t$ is given by $\ell(\mu\boxplus\sigma_t) = H_t(\omega)$, where
		\begin{equation}
			\omega = \inf\Bigl\{\omega\in\mathbb{R} : \int \frac{\mathrm{d}\mu(\lambda)}{(\lambda-\omega)^2} \geq \frac{1}{t}\Bigr\}.
		\end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T07:27:14.805699+00:00","domain":"probability theory","id":"claim_8f7ee530dbcd88098ed1db2c04109948df8a6e1b04e41801832fb794a9b7d87e","kind":"theorem","schema_version":1,"statement":"[Proposition 1 of arXiv:2608.23301, 'On a Telegraph Process with Generalized Mittag-Leffler Waiting times and Velocity Driven b'] Let $\{X_i\}_{1\leq i\leq n}$ be a sequence of independent random variables with distribution $\bar{F}_{X_{i}}(t)=E_{\alpha}(-\lambda_{i}t^\alpha)$. Then, the pdf and cdf of $X=X_{1}+X_{2}+\dots+X_{n}$ are given by

		\begin{equation*}
			f_{X}(t)=t^{\alpha-1}\sum_{i=1}^{n}{\lambda_{i}E_{\alpha,\alpha}(-\lambda_{i}t^\alpha)}\underset{ k\neq i}{\prod_{k=1}^{n}}\frac{\lambda_{k}}{\lambda_{k}-\lambda_{i}}
		\end{equation*}
		and 
		\begin{equation*}
			F_{X}(t)=1-\sum_{i=1}^{n}E_{\alpha}(-\lambda_{i}t^\alpha)\prod_{\substack{k=1 \\ k \neq i}}^{n}\frac{\lambda_{k}}{\lambda_{k}-\lambda_i},
		\end{equation*}
		respectively.","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T11:50:36.757429+00:00","domain":"probability theory","id":"claim_8f7f37bac98f34e7184febababc502d88d0a11b2d5144032072355a02cfee88b","kind":"theorem","schema_version":1,"statement":"[Corollary 41 of arXiv:2609.04153, '\vspace*{-3cm}Smooth autonomous fast dynamo action on the three-torus'] Let $K \subset \CC$ be a compact set, and let $\lambda \in K$. Then, for any $m \in \NN$, the operator $\mathcal{U}^{[m]}_{\lambda,\eps}\mathcal{E}_u^{-1}:\mathcal{E}_u \mathcal X \to \mathcal X$ is bounded, and satisfies the Lasota--Yorke inequality
\begin{align}
&\|\mathcal{U}^{[m]}_{\lambda,\eps}\mathcal{E}_u^{-1}B_0\|_{\mathcal X} \leq (1+C_m\eps^{\frac{1-2r-\delta}{2}})\|B_0\|_{\mathcal{E}_u \mathcal X}+C\|B_0\|_{\mathcal{E}_u \mathcal Y},\\
& \|\mathcal{U}^{[m]}_{\lambda,\eps}\mathcal{E}_u^{-1}B_0\|_{\mathcal Y} \leq C_m\|B_0\|_{\mathcal{E}_u \mathcal Y},\\
&\|\mathcal{U}_{\lambda,\eps}\mathcal{E}_u^{-1} B_0-\mathcal{E}_u^{-1}B_0\|_{\mathcal Y} \leq C(\eps^{\frac{1-2r}{2}}+\eps^{\frac{\delta}{2}})\|B_0\|_{\mathcal{E}_u \mathcal X}.
\end{align}","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T20:48:25.150091+00:00","domain":"probability theory","id":"claim_8f7ff932c793ed43dcbcaf24b5d0803e524d56c24dd6d9bad7588b6983fe29ff","kind":"lemma","schema_version":1,"statement":"[Lem cty-of-eigenspaces of arXiv:2607.05097, 'Asymptotics of Lyapunov Exponents and Phase Transitions for Fluids with Degenerate Forcing'] Recall (def:sigma-lambda,def:eta-star of the paper).
    \begin{itemize}
         \item $T \mapsto \lambda(T)$ is continuous on all of $\mathbb{R}^{n \times n}$.
         \item If $z_0 \in \mathbb{R}^d$ and $\eta \in (0,\eta^*(z_0))$ then the function $z \mapsto P_\eta(z)$ as defined in (def:proj-eta of the paper) is continuous in a neighborhood of $z_0$.
    \end{itemize}","status":"unverified"}

