{"assumptions":[],"created_at":"2026-10-27T08:33:12.363260+00:00","domain":"probability theory","id":"claim_8f9b66943ba36cbffcfe8e14da0db898de085cff1b709772f7ee382e1404d310","kind":"lemma","schema_version":1,"statement":"[Lemma 13 (Rate of convergence for \textup{($i$)}) of arXiv:2608.29465, 'Deciding When to Decide:\\Testing Operational Suboptimality Under Distributional Shift'] Suppose the assumptions of Lemma~\ref{lem:termI_consistency} hold. Let $\varepsilon_n$ denote the uniform convergence rate of the empirical OCE risk over $\mathcal{Z} \times \Theta$ such that $\varepsilon_n = O_p(n^{-1/2})$ (as established in Lemma \ref{lem:rate_oce_criterion}). Under the $\kappa$-degree local inverse stability condition (Assumption \ref{assm:error_bound_P0}), it holds that:
\begin{equation}

\mathrm{dist}(\hat\theta,\Theta_{\rm inv})=O_p\!\big(\varepsilon_n^{1/\kappa}\big).
\end{equation}
Furthermore, the deployment optimality gap satisfies:
\begin{equation}

\Big|\Delta(z_0;\hat \theta,\rho,\mathbb P_1)-\Delta(z_0;\theta^\star,\rho,\mathbb P_1)\Big|
\le \delta_{\rm inv}+O_p\!\big(\varepsilon_n^{1/\kappa}\big).
\end{equation}
In particular, since $\varepsilon_n \asymp n^{-1/2}$, we have $\mathrm{dist}(\hat\theta,\Theta_{\rm inv})=O_p(n^{-1/(2\kappa)})$. If $\delta_{\rm inv}=0$, the gap strictly converges at the rate $O_p(n^{-1/(2\kappa)})$.","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T20:19:06.741614+00:00","domain":"probability theory","id":"claim_8f9c432c72257308fdc233facce28b08ba376d2a2b6fd800e300d92692f1d090","kind":"lemma","schema_version":1,"statement":"[Lem lm:TJr of arXiv:2606.02340, 'Transitivity in Inhomogeneous Random Tournaments'] Let $T_J$ be as defined in (equation eq:Tf of the paper) and denote $a^2 := 3  \| d_J^{\uparrow} \|_2^2 > 0 $. Fix an integer $r \geq 0$. Then, for almost every $x \in [0, 1]$, 
\begin{equation}
    T_J [(d_J^{\uparrow})^r] (x)  = 
    \begin{cases}
        \dfrac{ d_J^{\uparrow}(x)^{r+1}}{r+1} & \text{ when } r \text{ is even} , \\ 
        \dfrac{ d_J^{\uparrow}(x)^{r+1}- a^{r+1} }{r+1} & \text{ when } r \text{ is odd} . 
    \end{cases}

\end{equation}
Moreover, 
\begin{equation}
\int_0^1 d_J^{\uparrow}(x)^r \mathrm{d} x = 
\begin{cases}
        \frac{a^r}{r+1} & \text{ when } r \text{ is even},\\ 
        0 & \text{ when } r \text{ is odd} . 
    \end{cases} 

\end{equation}
Consequently, if $\eta \sim\mathrm{Unif}([0,1])$, then $d_J^{\uparrow}(\eta)\sim \mathrm{Unif}([-a,a])$.","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T23:07:56.652003+00:00","domain":"probability theory","id":"claim_8f9f674a28a76916ca7babdb77a5fb06892311282e901fd96774db9db5358d80","kind":"theorem","schema_version":1,"statement":"[Theorem thm:unstable_manifold of arXiv:2411.04590, 'Singular stochastic delay equations driven by fractional Brownian motion: Dynamics, longti'] Assume the same setting as in Theorem (thm:stable_manifold of the paper). Furthermore, suppose that \( \mu_1 > 0 \) holds for the first Lyapunov exponent and $\mu^{+}:=\min\lbrace\mu_j : \ \mu_j>0\rbrace$. Then there exists a $\theta_r$-invariant set of full measure $\tilde{\Omega}$ and a family of immersed submanifolds \( U^{\upsilon}_{loc}(\omega)\) of \( E_\omega \), for \( 0 < \upsilon < \mu^{+} \) and \( \omega \in \tilde{\Omega} \), satisfying the following properties for every \( \omega \in \tilde{\Omega} \):
			\begin{itemize}
				\item[(i)] There exist random variables \( \tilde{\rho}_{1}^{\upsilon}(\omega) \) and \( \tilde{\rho}_{2}^{\upsilon}(\omega) \), positive and finite on \( \tilde{\Omega} \), such that
				\begin{align*}
					\liminf_{p \to \infty} \frac{1}{p} \log \tilde{\rho}_i^{\upsilon}(\theta_{-pr} \omega) \geq 0, \quad i = 1, 2,
				\end{align*}
				and
				\begin{align*}
					&\left\lbrace \xi_{\omega} \in E_\omega\, :\, \exists \lbrace \xi_{\theta_{-pr}\omega}\rbrace_{p\geqslant 1} \text{ s.t. } \varphi^{m}_{\theta_{-pr}\omega}(\xi_{\theta_{-pr}\omega}) = \xi_{\theta_{(m-p)r}\omega} \text{ for all } 0 \leq m \leq p, \right. \\
					&\quad \left.\sup_{p \geqslant 0} \exp(p\upsilon)\Vert \xi_{\theta_{-pr}\omega} - Y_{\theta_{-pr}\omega} \Vert_{E_{\theta_{-pr}\omega}} < \tilde{\rho}_{1}^{\upsilon}(\omega)\right\rbrace \subseteq U^{\upsilon}_{loc}(\omega) \\
					&\quad \subseteq \left\lbrace\xi_{\omega} \in E_\omega\, :\, \exists \lbrace \xi_{\theta_{-pr}\omega}\rbrace_{p\geqslant 1} \text{ s.t. } \varphi^{m}_{\theta_{-pr}\omega}(\xi_{\theta_{-pr}\omega}) = \xi_{\theta_{(m-p)r}\omega} \text{ for all } 0 \leq m \leq p, \right. \\
					&\quad \left. \sup_{p\geqslant 0} \exp(p\upsilon)\Vert \xi_{\theta_{-pr}\omega} - Y_{\theta_{-pr}\omega} \Vert_{E_{\theta_{-pr}\omega}} < \tilde{\rho}_{2}^{\upsilon}(\omega)\right\rbrace.
				\end{align*}

				\item[(ii)] The tangent space at \( Y_{\omega} \) to \( U^{\upsilon}_{loc}(\omega) \) is given by
				\begin{align*}
					T_{Y_{\omega}}U^{\upsilon}_{loc}(\omega) = {U}_{\omega}:=\oplus_{i: \mu_{i}>0}H^{i}_{\omega}.
				\end{align*}

				\item[(iii)] For \( m \geqslant M(\omega) \),
				\begin{align*}
					U^{\upsilon}_{loc}(\omega) \subseteq \varphi^{m}_{\theta_{-mr}\omega}( U^{\upsilon}_{loc}(\theta_{-mr}\omega)).
				\end{align*}

				\item[(iv)] For \( 0 < \upsilon_{1} \leqslant \upsilon_{2} < \mu^{+} \),
				\begin{align*}
					U^{\upsilon_{2}}_{loc}(\omega) \subseteq U^{\upsilon_{1}}_{loc}(\omega).
				\end{align*}
				Also, for \( m \geqslant M(\omega) \),
				\begin{align*}
					U^{\upsilon_{1}}_{loc}(\omega) \subseteq \varphi^{m}_{\theta_{-mr}\omega}( U^{\upsilon_2}_{loc}(\theta_{-mr}\omega)),
				\end{align*}
				and consequently, for \( \xi_{\omega} \in U^{\upsilon}_{loc}(\omega) \),
				\begin{align*}
					\limsup_{p\rightarrow \infty} \frac{1}{p}\log\Vert \xi_{\theta_{-pr}\omega} - Y_{\theta_{-pr}\omega}\Vert_{E_{\theta_{-pr}\omega}} \leqslant -\mu^{+}.
				\end{align*}

				\item[(v)] 
				\begin{align*}
					\limsup_{p \rightarrow \infty} \frac{1}{p}\log\left[\sup\left\lbrace\frac{\Vert \xi_{\theta_{-pr}\omega} - \tilde{\xi}_{\theta_{-pr}\omega}\Vert_{E_{\theta_{-pr}\omega}}}{\Vert \xi_{\omega} - \tilde{\xi}_{\omega}\Vert_{E_{\omega}}}\, :\, \xi_{\omega} \neq \tilde{\xi}_{\omega},\ \xi_{\omega}, \tilde{\xi}_{\omega} \in U^{\upsilon}_{loc}(\omega)\right\rbrace\right] \leqslant -\mu^{+}.
				\end{align*}
			\end{itemize}","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T11:32:18.857309+00:00","domain":"probability theory","id":"claim_8f9ffb99cf45773119f98bfdbb798764759fa94eae05199cb3db409426fa5f3b","kind":"theorem","schema_version":1,"statement":"[Proposition 18 of arXiv:2609.03875, 'Measure theory without infinities'] Let $\fm{\Theta}{\Lambda}$ be a family of sets such that $A\cap B\in \Theta(\lambda)\cap\Theta(\lambda')$ for every $\lambda,\lambda'\in \Lambda$, $A\in\Theta(\lambda)$, and $B\in\Theta(\lambda')$. Let $\mathcal Q = \bigcup_{\lambda\in \Lambda} \Theta(\lambda)$.
  \begin{enumerate}
  \item [(i)] Let $\Theta(\lambda)$ be a semi-ring for every $\lambda\in \Lambda$. Then $\mathcal{Q}$ is a semi-ring.
  \item [(ii)] Let $\Theta(\lambda)$ be a $\delta$-ring for every $\lambda\in \Lambda$. Then $\kappa(\mathcal Q)$ is a $\delta$-ring.
  \item [(iii)] Let $\mf A$ be an HTM. A map $\fm{\eta}{\mathcal{Q}}$ is an $\mf A$-valued $\sigma$-additive function if and only if $\eta|_{\Theta(\lambda)}$ is an $\mf A$-valued $\sigma$-additive function for every $\lambda\in \Lambda$. 
  \end{enumerate}","status":"unverified"}

