{"assumptions":[],"created_at":"2026-10-27T06:16:18.683782+00:00","domain":"probability theory","id":"claim_9009d5b6f8ddc3f159bdeb2a4cf23e8ad73cdda1f7b109e753309e2799cd1d5a","kind":"definition","schema_version":1,"statement":"[Definition 1 of arXiv:2607.26254, 'A Simple Model of Sea Spray'] Let $\mathcal{F}(dr)$ be a finite measure on $(0,\infty)$ and for each fixed $r>0,$ let $(z_t(r), r_t) $ be a pair of nonnegative functions of $t\geq 0.$ Let
$$
\zeta=\inf\{\, t>0\mid z_t=0\quad\text{or}\quad r_t=0\,\}.
$$
be the duration of the droplet. We assume, 
\begin{itemize}
\item{$r_t, \,z_t(r)$ are continuous  on the interval $[0,\zeta]$}
\item{if $r_t=0$ for some $t>0$ then $r_s=0$ and $z_s=0$ for all $s\geq t$}
\item{if $z_t(r)=0$ for some $t>0$ then $z_s(r)=0$ and $r_s=0$ for all $s\geq t$}
\end{itemize}

\mpar
Let $\mathcal{X}=\mathbb{R}\times (0,\infty)$ and let $\Lambda(dr\, dt)=\mathcal{F}(dr) dt.$ Let $\mathcal{N}$ be the Poisson point process whose intensity measure is $\Lambda.$ Let $\mathcal{M}$ be the space of positive measures on $[0,\infty)$ and let $C([0,\infty),\mathcal{M})$ be the space of continuous functions from $[0,\infty)$ to $\mathcal{M}.$

\mpar
Let $\phi\colon (0,\infty)\to C([0,\infty), \mathcal{M})$ be defined by the rule,
$$
\phi(r,t) = \tfrac{4}{3}\pi r_t^3\rho\, \delta_{z_t(r)}
$$
Then the sea spray process is defined by the formula,

$$
\mathcal{S}_t =\int_{-\infty}^t\int_0^\infty \phi(t-s,r)\, \mathcal{N}(dr\, ds).
$$","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T16:26:02.364624+00:00","domain":"probability theory","id":"claim_900b5f75c36b1f7e58599bda48346697af8ec033ecdaaf678440ad18ad2f7d87","kind":"definition","schema_version":1,"statement":"[Defn def:adapted of arXiv:2608.30031, 'Ziggurats, taut foliations, and contact structures'] Let $\mathcal{F}_{\mathord{\scalebox{0.45}{$\square$}}}$ be a cooriented $C^0$-foliation on a manifold with fences and windows $M_{\mathord{\scalebox{0.45}{$\square$}}}$. We say that $\mathcal{F}_{\mathord{\scalebox{0.45}{$\square$}}}$ is \textbf{adapted} to the boundary of $M_{\mathord{\scalebox{0.45}{$\square$}}}$ if it is transverse to $\partial M_{\mathord{\scalebox{0.45}{$\square$}}}$, and there exist pairwise disjoint standard neighborhoods and coordinates of the fences and windows such that
    \begin{itemize}
        \item In $N(\mathcal{A}_i)$, $\mathcal{F}_{\mathord{\scalebox{0.45}{$\square$}}}$ is tangent to $\partial_y$, positively transverse to $\partial_z$ (i.e., horizontal), and it is
        \begin{itemize}
            \item Positively transverse to $\partial_x$ in $S^1 \times I \times [1,2)$
            \item Negatively transverse to $\partial_x$ in $S^1 \times I \times (-1,0]$,
        \end{itemize}

        \item If $\mathcal{W}_j$ is a square window, then in $N(\mathcal{W}_j)$, $\mathcal{F}_{\mathord{\scalebox{0.45}{$\square$}}}$ is the standard horizontal foliation by $(x,y)$-planes. In particular, it is smooth there. If $\mathcal{W}_j$ is a toroidal window, we only require that $\mathcal{F}_{\mathord{\scalebox{0.45}{$\square$}}}$ is tangent to $\partial_y$ in $N(\mathcal{W}_j)$.
    \end{itemize}","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-28T02:10:43.790442+00:00","domain":"probability theory","id":"claim_900bc9c88a9cb9531b3a08a363798e155994ffdf8811231d0637c1aff345f79f","kind":"lemma","schema_version":1,"statement":"[Lemma lem:degrees_are_Poisson of arXiv:2412.04328, 'The critical Karp--Sipser core of Erdős--Rényi random graphs'] Let $C>0$ be a constant and assume that $V_k Z_k \geqslant \log^3 n$ and $Z_k \leqslant C$. In what follows, the constants involved in the $O$ notation will only depend on $C$.
	\begin{enumerate}
		\item For all $X_k+1 \leqslant j \leqslant X_k+V_k$ and for all $3 \leqslant i \leqslant \log n$, we have
			\begin{equation}
			\mathbb{P} \left( \deg_{G_k}(j)=i | \mathcal{F}_k \right) = \frac{Z_k^i}{i! f(Z_k)} \left( 1+O \left( \frac{i^2}{V_k Z_k} \right) \right).
			\end{equation}
			Moreover, if $i=2$, the $O \left( \frac{i^2}{V_k Z_k} \right)$ error term can be replaced by $O \left( \frac{1}{V_k} \right)$.
			Also, for all $i \geqslant 2$, we have
			\begin{equation}
				\mathbb{P} \left( \deg_{G_k}(j)=i | \mathcal{F}_k \right) = O \left( \sqrt{V_k Z_k} \frac{Z_k^i}{i!f(Z_k)} \right).
			\end{equation}
			In particular, we have
			\begin{equation}
				\mathbb{P} \left( \deg_{G_k}(j) \geqslant \log n | \mathcal{F}_k \right) = O \left( n^{-10} \right).
			\end{equation}
			\item For all $X_k+1 \leqslant j_1<j_2 \leqslant X_k+V_k$ and $2 \leqslant i_1, i_2 \leqslant \log n$, we have
			\begin{equation}
				\mathbb{P} \left( \deg_{G_k}(j_1)=i_1 \mbox{ and } \deg_{G_k}(j_2)=i_2 | \mathcal{F}_k \right) = \frac{Z_k^{i_1}}{i_1 ! f(Z_k)} \frac{Z_k^{i_2}}{i_2 ! f(Z_k)} \left( 1+O \left( \frac{\log^2 n}{V_k Z_k} \right) \right).
			\end{equation}
			Moreover, if $i_1=i_2=2$, the error term can be replaced by $O \left( \frac{\log^2 n}{V_k} \right)$.
			\item For all $X_k+1 \leqslant j_1<j_2<j_3 \leqslant X_k+V_k$ and $2 \leqslant i_1, i_2, i_3 \leqslant \log n$, we have
			\begin{equation}
			\mathbb{P} \left( \forall a \in \{1,2,3\}, \deg_{G_k}(j_a)=i_a | \mathcal{F}_k \right) = \left( \prod_{a=1}^3 \frac{Z_k^{i_a}}{i_a ! f(Z_k)} \right) \times \left( 1+O \left( \frac{\log^2 n}{V_k Z_k} \right) \right).
			\end{equation}
			\item Let $m \geqslant 1$. Then for all $X_k+1 \leqslant j_1<\dots<j_m \leqslant X_k+V_k$, we have
			\begin{equation}
				\mathbb{P} \left( \deg_{G_k}(j_1)=\dots=\deg_{G_k}(j_m)=5 | \mathcal{F}_k \right) = (1+o(1)) \left( \frac{Z_k^5}{5! f(Z_k)} \right)^m,
			\end{equation}
			where the $o$ only depends on $m, C$.
		\end{enumerate}","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T09:05:57.812766+00:00","domain":"probability theory","id":"claim_9011aab776f7836cbc3c218bbadf814dc1a64abbf35fa938ae126cbea9bfcc85","kind":"theorem","schema_version":1,"statement":"[Corollary 13 of arXiv:2608.30570, '2608.30570'] Assume $\Sigma\subset \mathbb{R}^n$ is a complete immersed surface. Then $\Sigma$ has finite total curvature, i.e.,
\begin{align*}
\int_{\Sigma}|{\bf A}|^2d\mu<\infty.
\end{align*}
if and only if
\begin{enumerate}
\item ${\rm {Area}}(\Sigma\cap B_R)\le \Lambda R^2$ for all $R>0$,
\item the genus of $\Sigma$ is finite,
\item $\int_{\Sigma}|{\bf H}|^2d\mu<\infty,$
\end{enumerate}
for some constant $\Lambda<+\infty$. Moreover, if one of the two equivalent statements holds, then $\Sigma$ is properly immersed in $\mathbb{R}^n$ and only has finitely many ends.","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T18:51:26.726664+00:00","domain":"probability theory","id":"claim_9012331254797dc9ed72632716c118ad7c36d365fdfe183e7c5e38d169fd2611","kind":"concept","schema_version":1,"statement":"[Cor polynomial-log of arXiv:2606.08325, 'Digit Mixing under Polynomial Maps'] Let \(P\in\mathbb R[x]\) have degree \(d\ge2\).  There exists \(A_0=A_0(P)>0\) such that, if for all sufficiently large \(n\),
