		C_J^{(m)}(1/n)^{1-\frac1q}
		+
		C_J^{(c)}(1/n)^{(1-\frac1q)(1-\frac dp)}
		\bigg\}.

	\end{align}
	If $1<\bar p\leq2$, then
	\begin{align}
		[\mE T_1^\theta]^{1/\theta}
		&\leq
		\left(
		\mE\exp\left[
		\frac{\theta}{1-\theta}
		N_{\bar p}
		\left(
		(\sR_1^n)^{(\bar p/2)\vee 1}
		+\sB_1^n
		\right)
		\right]
		\right)^{\frac{1-\theta}{\theta}}
		\notag\\
		&\quad\times
		\bigg\{
		\mE |x_0-x_0^n|
		+
		(1/n)^{\frac{\alpha}{2}}
		+\varpi_b^n(\bar p)
		+(1/n)^{\frac12}\log n
		\notag\\
		&\qquad\qquad
		+
		C_J^{(m)}(1/n)^{1/2}
		+
		C_J^{(c)}(1/n)^{\frac12(1-\frac dp)}
		\bigg\}^{\bar p}.

	\end{align}
	Here
	\ce 
	T_1:=\sup_{r\in[0,1]}|X_r-X_r^n|^{\bar p},
	\de","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T20:51:52.062025+00:00","domain":"probability theory","id":"claim_9059fe46c3a15e2dda4233b82087ac162ad7625e8e52d9caa8f67b870ba98cbc","kind":"theorem","schema_version":1,"statement":"[Theorem of arXiv:2607.14993, 'Sharp phase transition for percolation with short-range dependencies'] We assume that there exists $\beta_c \in \mathbb R_+^*$ such that $ \theta(\beta) = 0$ for all $\beta \in ]0, \beta_c[$ and $ \theta(\beta) > 0$ for all $\beta \in ]\beta_c, +\infty[$. Then,
  \begin{itemize}
    \item for all $\beta \in ]0, \beta_c[$ there exists $c_\beta > 0$ such that for any $n$ large enough, $\theta_n(\beta) \leqslant \exp(- c_\beta n)$;
    \item there exists $c, \delta > 0$ such that $ \theta(\beta) \geqslant c (\beta - \beta_c)$ for all $\beta \in [\beta_c, \beta_c + \delta[$.
  \end{itemize}","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T07:27:14.910882+00:00","domain":"probability theory","id":"claim_905a1ae2649f7818b1a1e88027c055f305e6ec65397c76ec736e177b8118e5e5","kind":"concept","schema_version":1,"statement":"[Theorem 1 (Double loop global convergence) of arXiv:2608.24146, 'Robust Data-Collection Policy Learning for Low-Variance Online Policy Evaluation'] With a constant step size $\alpha\doteq \frac{D}{L_\Theta\sqrt{n}}$, we have
