\cap \{x_{k-1}, x_k \leftrightarrow \overline{g} \text{ off } \mathfrak{C}(\underline{g})\} \cap \{\mathcal{P}(\overline{g}, \{x_{k-1}, x_k\}) = \varnothing \} 
