{"assumptions":[],"created_at":"2026-10-26T20:55:18.059440+00:00","domain":"probability theory","id":"claim_913e78faf5d94d871144bc3a3cd59e2fe6d1f8f89a08f58b3c2aaa10dd921a9d","kind":"concept","schema_version":1,"statement":"[Theorem 4 (Mixed operator convergence with deterministic diagonal resolution) of arXiv:2606.16662, '2606.16662'] Fix \(\eps>0\), \(0<T_0\le1\), a finite color set \(\cC\), a finite family \(\cM\) of mixed triples, and a fixed Bony aperture \(c_{\rm ap}\).  Assume the Fourier-diagonal time covariance model \eqref{eq:conv-cov}--\eqref{eq:cov-decay} and the coefficient bounds of Assumption~\ref{ass:coeff}.  Let \((s,\sigma)\) be \((\tau,\eps)\)-centered admissible in the sense of Definition~\ref{def:admissible} for every \(\tau\in\cM\).

Choose a dyadically admissible deterministic diagonal resolution
\(\mathfrak P=\{(\Ret^\tau_\Lambda,\Ctr^\tau_\Lambda)\}_{\tau\in\cM}\)
in the sense of Definition~\ref{def:contraction-resolution}.  Assume that
every nonzero retained diagonal has gain \(\delta_\tau>20\eps\) and that
\(s<\delta_\tau-10\eps\) for those labels.

For each \(\tau=(i;j,k)\), define the finite \(\mathfrak P\)-resolved operator
\begin{equation}
        T_{\Lambda}^{\tau,\mathfrak P}:=T_{\Lambda}^{\tau}-\Ctr^\tau_\Lambda .
\end{equation}
Then, for every \(0<T\le T_0\), the following assertions hold.
The full-probability event below may be chosen for \(T_0\) and therefore
works simultaneously for every \(T\le T_0\).

\begin{enumerate}[label=(\roman*),leftmargin=2.4em]
\item \textup{Finite Wick split.}  The cutoff operator admits the exact finite-cutoff Wick decomposition
\begin{equation}
        T_{\Lambda}^{\tau}=D_{\Lambda}^{\tau}+B_{\Lambda}^{\tau}.
\end{equation}
The diagonal part \(D_{\Lambda}^{\tau}\) is deterministic and supported by \(n=q\) in the external variables.  The centered part \(B_{\Lambda}^{\tau}\) is a finite sum of second homogeneous Gaussian chaoses and preserves the incidence
\begin{equation}
        n=q+\ell+r.
\end{equation}
Consequently,
\begin{equation}
        T_{\Lambda}^{\tau,\mathfrak P}=\Ret^\tau_\Lambda+B^\tau_\Lambda.
\end{equation}

\item \textup{Centered operator component.}  For every finite \(p\ge2\), the centered operators \(B^\tau_\Lambda\) converge in \(L^p(\Omega)\) and almost surely in the centered operator topology
\begin{equation}
        \cL(X_T^\sigma,C_TH^{s-\lambda_i})
        \cap
        \cL(X_T^\sigma,L_T^1B^{\sigma-\lambda_i}_{2,\infty}).
\end{equation}
The limit \(B^\tau\) satisfies the operator-norm estimates
\begin{align}
        \|B^\tau\|_{L^p(\Omega;\cL(X_T^\sigma,C_TH^{s-\lambda_i}))}
        &\le C_p,\\
        \|B^\tau\|_{L^p(\Omega;\cL(X_T^\sigma,L_T^1B^{\sigma-\lambda_i}_{2,\infty}))}
        &\le C_p.
\end{align}
There is a full-probability event, independent of \(\tau\in\cM\), on which all centered cutoff sequences are Cauchy in the pathwise operator norm \eqref{eq:centered-op-topology}.  The centered estimate is an \(X_T^\sigma\)-estimate; the derivative components of \(E_{T,\cM}^{2,\sigma}\) are needed only when a retained diagonal is present.

\item \textup{Retained deterministic component.}  The retained diagonals converge to deterministic operators \(\Ret^\tau\) satisfying
\begin{equation}
        \|\Ret^\tau w\|_{C_TH^{s-\lambda_i}}
        +\|\Ret^\tau w\|_{L_T^1B^{\sigma-\lambda_i}_{2,\infty}}
        \le C\|w\|_{E_{T,\cM}^{2,\sigma}} .
\end{equation}

\item \textup{Assembled operator.}  On the same full-probability event,
\begin{equation}
        T_{\Lambda}^{\tau,\mathfrak P}
        \longrightarrow
        T^{\tau,\mathfrak P}:=\Ret^\tau+B^\tau
\end{equation}
in the assembled topology
\begin{equation}
        \cL(E_{T,\cM}^{2,\sigma},C_TH^{s-\lambda_i})
        \cap
        \cL(E_{T,\cM}^{2,\sigma},L_T^1B^{\sigma-\lambda_i}_{2,\infty}),
\end{equation}
for every \(\tau\in\cM\).  The convergence also holds in \(L^p(\Omega)\) for every finite \(p\ge2\).
\end{enumerate} (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-26T20:58:28.468055+00:00","domain":"probability theory","id":"claim_913e9e3d3c4a8bc022c9291945cd1c52ebcac616095de187123dd10b719453c8","kind":"theorem","schema_version":1,"statement":"[Proposition 8 (Functoriality and unitary invariance) of arXiv:2606.29292, 'Intrinsic Gaussian Tensor Geometry and Random Operator Spectra'] Fix $2\le r<\infty$.  Let
\[
  U_\nu:\cH_\nu\to\cH_\nu',\qquad
  U_\cC:\cC\to\cC',\qquad
  U_\cE:\cE\to\cE'
\]
be bounded, and write $U_S:=\bigotimes_{\nu\in S}U_\nu$.  The algebraic map
\begin{equation*}
  \mathbf U
  :=U_1\otimes\cdots\otimes U_m\otimes\conj{U_\cC}\otimes U_\cE
\end{equation*}
extends uniquely to
\begin{equation*}
  \mathbf U:\mathfrak T_{m,r}(\cH_1,\ldots,\cH_m;\cC,\cE)
  \longrightarrow
  \mathfrak T_{m,r}(\cH_1',\ldots,\cH_m';\cC',\cE').
\end{equation*}
For every cut $S\subset[m]$, the extended flattenings satisfy
\begin{equation}

  \Flat_S(\mathbf U\mathbf K)
  =(U_{S^c}\otimes U_\cE)\,
    \Flat_S(\mathbf K)\,
    (\conj{U_S}\otimes U_\cC)^*.
\end{equation}
Consequently,
\begin{equation*}
  \|\mathbf U\mathbf K\|_{\mathfrak T_{m,r}}
  \le
  \left(\prod_{\nu=1}^m\|U_\nu\|\right)
  \|U_\cC\|\,\|U_\cE\|\,
  \|\mathbf K\|_{\mathfrak T_{m,r}}.
\end{equation*}
If all maps are unitary, then $\mathbf U$ is an isometric isomorphism.","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-26T20:58:53.162385+00:00","domain":"probability theory","id":"claim_91405249fe1ba11ddc5a2a90c10dda865beb13be51660ecc47cac441131baff9","kind":"theorem","schema_version":1,"statement":"[Corollary 10 of arXiv:2606.29512, '2606.29512'] Let Assumptions 2.1, 2.2 and 2.3 hold, and let $u$ be a solution to
$(2.1)$--$(2.2)$ such that almost surely 
\begin{equation}

\int_0^T\Big( \int_{\cR}|u_s(x)|^p\,dx\Big)^{q/p}\,ds < \infty
