{"assumptions":[],"created_at":"2026-10-28T00:52:17.578041+00:00","domain":"probability theory","id":"claim_9154652b597f20459a9c503206e926996220ece7eed0048953bc11564477a0ba","kind":"concept","schema_version":1,"statement":"[Corollary eq:c:Girsanov:0 of arXiv:2411.14936, 'Massive Particle Systems,\\Wasserstein Brownian Motions,\\ and the Dean--Kawasaki Equation'] Fix~$\pi\in\msP(\mbfT_\circ)$ and suppose that Assumption~(ass:Girsanov of the paper) is satisfied.
Then, the quadratic form~$\tparen{\widehat\boldsymbol\mssE_\pi^{\boldsymbol\varphi},\dom{\widehat\boldsymbol\mssE_\pi^{\boldsymbol\varphi}}}$ defined by
\begin{equation}
\begin{gathered}
\dom{\widehat\boldsymbol\mssE_\pi^{\boldsymbol\varphi}}\eqdef \set{u\in \msD(\widehat\boldsymbol\mssE_\pi)^\bullet_{\loc} \cap L^2(\widehat\boldsymbol\nu_\pi^{\boldsymbol\varphi}) : \int_{\widehat\mbfM} \widehat\boldsymbol{\mathsf{\Gamma}}_\pi(u)\, \mathop{}\!\mathrm{d}\widehat\boldsymbol\nu_\pi^{\boldsymbol\varphi}<\infty } \,\mathrm{,}\;\,
\\
\widehat\boldsymbol\mssE_\pi^{\boldsymbol\varphi}(u,v)\eqdef \int_{\widehat\mbfM} \widehat\boldsymbol{\mathsf{\Gamma}}_\pi(u,v)\, \mathop{}\!\mathrm{d}\widehat\boldsymbol\nu_\pi^{\boldsymbol\varphi} \,\mathrm{,}\;\, \qquad u,v\in \dom{\widehat\boldsymbol\mssE_\pi^{\boldsymbol\varphi}} \,\mathrm{,}\;\, 
\end{gathered}
\end{equation}
is a $\widehat\tau_\mrmp$-quasi-regular local Dirichlet form on~$L^2(\widehat\boldsymbol\nu_\pi^{\boldsymbol\varphi})$.

If, additionally,
\begin{equation}
\boldsymbol\varphi\in L^2(\widehat\boldsymbol\nu_\pi) \qquad \text{and} \qquad\int \widehat\boldsymbol{\mathsf{\Gamma}}_\pi(\boldsymbol\varphi) \mathop{}\!\mathrm{d} \widehat\boldsymbol\nu_\pi <\infty \,\mathrm{.}
\end{equation}
Then, 
\begin{enumerate}[$(i)$]
\item the form~$\tparen{\widehat\boldsymbol\mssE_\pi^{\boldsymbol\varphi},\dom{\widehat\boldsymbol\mssE_\pi^{\boldsymbol\varphi}}}$ is additionally strongly local and recurrent;
\item for the generator~$\tparen{\widehat\boldsymbol\mssL_\pi^{\boldsymbol\varphi},\dom{\widehat\boldsymbol\mssL_\pi^{\boldsymbol\varphi}}}$ of~$\tparen{\widehat\boldsymbol\mssE_\pi^{\boldsymbol\varphi},\dom{\widehat\boldsymbol\mssE_\pi^{\boldsymbol\varphi}}}$ we have~$\mcC_b(\mbfT)\otimes \Cyl{}{}\subset \dom{\widehat\boldsymbol\mssL_\pi^{\boldsymbol\varphi}}$ and
\[
\widehat\boldsymbol\mssL_\pi^{\boldsymbol\varphi} u= \widehat\boldsymbol\mssL^{\boldsymbol\varphi} u\eqdef \widehat\boldsymbol\mssL u+\boldsymbol\varphi^{-1}\,\widehat\boldsymbol{\mathsf{\Gamma}}_\pi(\boldsymbol\varphi, u) \quad \text{on}\quad \mcC_b(\mbfT)\otimes \Cyl{}{} \,\mathrm{.}
\]

\item $\tparen{\widehat\boldsymbol\mssE_\pi^{\boldsymbol\varphi},\dom{\widehat\boldsymbol\mssE_\pi^{\boldsymbol\varphi}}}$ is properly associated with the $\widehat\boldsymbol\nu_\pi^{\boldsymbol\varphi}$-symmetric process~$\widehat\boldsymbol\mssW_\pi^{\boldsymbol\varphi}$, which is thus recurrent (in particular: conservative);

\item a $\widehat\boldsymbol\nu_\pi^{\boldsymbol\varphi}$-measurable set~$\mbfA\subset \widehat\mbfM$ is $\widehat\boldsymbol\mssE_\pi^{\boldsymbol\varphi}$-invariant if and only if it is $\widehat\boldsymbol\mssE_\pi$-invariant;

\item 
$\widehat\boldsymbol\mssW^{\boldsymbol\varphi}_\pi$ is a solution to the martingale problem for~$\tparen{\widehat\boldsymbol\mssL^{\boldsymbol\varphi},\mcC_b(\mbfT)\otimes\Cyl{}{}}$. In particular, for every~$\mbfu\in\mcC_b(\mbfT)\otimes\Cyl{}{}$ ($\subset \mcC_b(\widehat\tau_\mrmp)$), the process
\begin{equation}
M^{\class{u}}_t\eqdef \mbfu(\widehat\mbfX^{\pi,\boldsymbol\varphi}_t)- \mbfu(\widehat\mbfX^{\pi,\boldsymbol\varphi}_0)-\int_0^t (\widehat\boldsymbol\mssL^{\boldsymbol\varphi} \mbfu)(\widehat\mbfX^{\pi,\boldsymbol\varphi}_s)\mathop{}\!\mathrm{d} s
\end{equation}
is an adapted square-integrable martingale with quadratic variation
\begin{equation}
\tquadvar{M^{\class{\mbfu}}}_t = \int_0^t \widehat\boldsymbol{\mathsf{\Gamma}}(\mbfu)(\widehat\mbfX^{\pi,\boldsymbol\varphi}_s)\mathop{}\!\mathrm{d} s \,\mathrm{,}\;\,
\end{equation}
\end{enumerate} (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-28T00:59:45.429018+00:00","domain":"probability theory","id":"claim_9155ca414f862fa1f217d9e0d45e5639d8bbeb498617fb5a694cb00633b1e79f","kind":"definition","schema_version":1,"statement":"[Defi def_IOP of arXiv:2411.16464, 'Generating social networks with static and dynamic utility-maximization approaches'] For a given individuals graph $\mathcal{G}_N(\mathscr{I} , \alpha, C)$, we define for all individual $i \in \Iintv*{1, N }$ the Individual Optimization Problem (IOP) as:
