 \qquad k\ge1.
\end{equation}
No commutativity assumption on the time-dependent operators $K_vK_v^*$ is
required.","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T19:55:37.868862+00:00","domain":"probability theory","id":"claim_91dab9c8e2bdfe342d641f553a6585ab25c409935bae402d6f707f99ceb3f9d0","kind":"concept","schema_version":1,"statement":"[Theostar theotauberian of arXiv:2605.06488, 'Continuous-state branching processes with L\'evy-Khintchine drift-interaction: Laplace dua'] \
\begin{enumerate}
\item \textbf{Tauberian theorem}: Let $\ell:(0,\infty)\to (0,\infty)$ be slowly varying at $0$ (respectively, at $\infty$) and $\alpha\in[0,\infty)$ and $U$ be a locally finite measure on $[0,\infty)$. One has
\begin{align*}\int_0^{\infty}e^{-xz}U(\mathrm{d} z) \sim x^{-\alpha}\ell(1/x), \ &(x\rightarrow \infty, \text{ resp. } 0)\\ &\Longleftrightarrow
\int_0^{z}U(\mathrm{d} v)\sim z^{\alpha}\ell(z)/\Gamma(1+\alpha), \ (z\rightarrow 0, \text{resp. } \infty).
\end{align*}
\item \textbf{Monotone density theorem}: Suppose that $U(\mathrm{d} z)=u(z)\mathrm{d} z$, where $u:(0,\infty)\to (0,\infty)$ is monotone on some neighbourhood of $0+$ (respectively of $\infty$). If there exists $\alpha>0$ and a function $\ell$ slowly varying at $0$ (respectively, at $\infty$) such that 
\[ \int_0^zu(v)\mathrm{d} v\sim z^{\alpha}\ell(z) \ (z\rightarrow 0, \text{resp. }\infty), \text{ then }
u(z)\sim \alpha z^{\alpha-1}\ell(z) \ (z\rightarrow 0, \text{resp. }\infty).\]
\end{enumerate} (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T23:00:22.778690+00:00","domain":"probability theory","id":"claim_91dc8953a29147f8fbc0153196b13b5b520ad2c964572043a773e756d5c1bab6","kind":"lemma","schema_version":1,"statement":"[Lemma lem::norma_1 of arXiv:2411.01467, 'Conformal covariance of connection probabilities \\ in the 2D critical FK-Ising model'] With the notation of Theorem~(thm::cvg_proba of the paper), for small enough $\epsilon>0$, we have 
	\begin{align*}
		&\lim_{a\to 0}\frac{\mathbb{P}^a_{\Omega}\left[z_j^a\longleftrightarrow \partial B_{\epsilon}(z_j^a),\enspace 1\leq j\leq n\right]}{\Big(\mathbb{P}^a_{\mathbb{Z}^2}\left[0\longleftrightarrow \partial B_1(0)\right]\Big)^n}\\
		&\quad=\lim_{m\to\infty} \frac{\mathbb{P}_{\Omega}\left[z_j\longleftrightarrow \partial B_{\epsilon}(z_j),\enspace 1\leq j\leq n | z_j\longleftrightarrow \partial B_{\delta_m}(z_j),\enspace 1\leq j\leq n\right]}{\Big(\mathbb{P}_{\mathbb{C}}\left[0\longleftrightarrow \partial B_{1}(0)| 0\longleftrightarrow \partial B_{\delta_m}(0)\right]\Big)^n},
	\end{align*}
	where the equation means that the limits on both sides exist in $(0,\infty)$ and that they are equal, and where
	\begin{align*}
	\mathbb{P}_{\mathbb{C}}\left[0\longleftrightarrow \partial B_{1}(0)| 0\longleftrightarrow \partial B_{\delta_m}(0)\right]:=\lim_{M\to \infty}	\mathbb{P}_{[-M,M]^2}\left[0\longleftrightarrow \partial B_{1}(0)| 0\longleftrightarrow \partial B_{\delta_m}(0)\right]. 
	\end{align*}","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T20:17:04.330192+00:00","domain":"probability theory","id":"claim_91e099e310d4facb0a4cf581bf629c11abcc3fba3fc9339d719c1ed83a09c247","kind":"lemma","schema_version":1,"statement":"[Lemma laststep of arXiv:2606.01937, 'Stationary fluctuations for an exclusion process with mass and energy conservation'] Let $f:\Omega\longrightarrow\mathbb{R}$ be a local function supported in $\{0,\hdots ,\ell_0-1\}$ for some $\ell_0\ge 1$, and assume that $\psi_f(\rho ,\mathcal{E})=0$ and $\nabla\psi_f(\rho ,\mathcal{E})=0$ for fixed $\rho\in [0,1]$ and $\mathcal{E}\in [\rho ,\kappa\rho]$. Then, there exists a constant~$C_{16}=C_{16}(\kappa ,\rho ,\mathcal{E} ,f)>0$ such that for any $t\in [0,T]$, any $\ell\ge\ell_0$ and any measurable function $v:[0,T]\longrightarrow\ell^2(\mathbb{Z} )$, we have 
    \begin{multline}
        \mathbb{E}_{\rho ,\mathcal{E}}\left[\left( \int_0^t \sum_{x\in\mathbb{Z}} \tau_x\left\{ \mathbb{E}_\ell [f](s)-\frac12 \overline{\mathbf{u}}^\ell (s)^\top\mathrm{Hess}(\psi_f)(\rho ,\mathcal{E})\overline{\mathbf{u}}^\ell (s)\right.\right.\right. \\
        \left.\left.\left. +\frac{1}{2\ell}\mathrm{Tr}(\chi\mathrm{Hess}(\psi_f))(\rho ,\mathcal{E})\right\} v_s(x)\,\mathrm{d} s\right)^2\right] \le \frac{C_{16}}{N^a}\int_0^t\| v_s\|^2\,\mathrm{d} s.
    \end{multline}","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T05:47:53.347356+00:00","domain":"probability theory","id":"claim_91e1b16cb7747324bee9e22e0b8f843b07404bf109b50a54a7f0c8dd75f78d3e","kind":"definition","schema_version":1,"statement":"[Definition 1 ($q$-Bass martingale) of arXiv:2607.15872, 'Existence of $q$-Bass martingales in the semidiscrete setting'] Let $\mu, \nu \in \Prob_1(\RR)$, $q \in \Prob(\RR)$ such that $q\ll \lambda$, and
	\begin{equation}
		(M_0,M_1)\sim\pi\in\Mart(\mu,\nu).
	\end{equation}
	We say that $\pi$ is a $q$-Bass martingale if there exists a measure $\alpha \in \Prob(\RR)$ such that
	\begin{equation}

		M_0= (q \star T)(X_0), \qquad M_1=T(X_0+Q), \qquad \text{and} \qquad q \star T \text{ is increasing $\alpha$-a.s.},
	\end{equation}
	where $X_0 \sim \alpha$, $Q\sim q$, $X_0$ is independent of $Q$, and $T=Q_\nu \circ F_{\alpha \ast q}$. Such a  measure $\alpha$ is called Bass measure.","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-26T19:48:27.275247+00:00","domain":"probability theory","id":"claim_91e286f4613cd620020882106afb642fda748daa875d77300d0e756d87ca3b85","kind":"concept","schema_version":1,"statement":"[Thm 4 of arXiv:2604.24624, 'Limit distributions of the threshold radius for the maximum degree and the associated poin'] Assume that $d \geq 2$, $(k_n)_{n \in \BN}$ is a $\BN$-valued sequence satisfying $k_n \to \infty$ as $n \to \infty$ and $k_n = o(\log n)$.
    Assume also that $X_1$ has a uniform distribution on the $d$-dimensional unit cube (that is, $f = \mathbf{1}_{[-1/2,1/2]^d}$).
    Let $\theta$ be the volume of a $d$-dimensional unit ball.
    Then, as $n \to \infty$,
    \begin{equation*}
        -en^{1+1/k_n}\theta S_{k_n}(\CX_n)^d \exp\left(-\frac{n\theta S_{k_n}(\CX_n)^d}{k_n}\right) + k_n + \frac{1}{2} \log k_n + \log \sqrt{2\pi} \xrightarrow{d} Z,
    \end{equation*}
    where $Z$ is a random variable with the Gumbel distribution $P[Z \leq x] = \exp(-\exp(-x))$. (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T08:18:19.235463+00:00","domain":"probability theory","id":"claim_91e4e0ceacf6bcea22cdb4f5dd2ae9c0751d60cf61edb22c828dd9de76efc120","kind":"definition","schema_version":1,"statement":"[Definition 71 of arXiv:2608.29086, '2608.29086'] [$C^{\ast}(M)$]
Given $M \subset H_0$. The \textit{cochain complex} $C^{\ast}(M)$ on $M$ is a collection of three objects $C^0(M)$, $C^1(M)$, and $C^2(M)$ with two linear mappings $d^1$ and $d^2$ defined by
\begin{align*}
d^0: C^0(M) &\rightarrow C^1(M),\quad  d^0f(v_0v_1):=f(v_1)-f(v_0), \\
d^1: C^1(M) &\rightarrow C^2(M),\quad  d^1f(v_0v_1v_2):=f(v_0v_1)+f(v_1v_2)+f(v_2v_0)
\end{align*}
(Figure \ref{figure6} (a)), $d^0$ and $d^1$ are called \textit{coboundary operators} of $C^{\ast}(M)$.","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-26T19:49:02.093664+00:00","domain":"probability theory","id":"claim_91e5824b9dc04e6d225a1938160095f8153e62d6f9d967c756527a94957f895e","kind":"theorem","schema_version":1,"statement":"[Theorem 2 of arXiv:2604.26026, 'Stochastic Ordering of Dependent Systems under Transformation Models and Archimedean Copul'] {Assume the functional $T$ is differentiable with respect to its first argument, the generators are such that $\phi_2\circ\psi_1$ is super-additive, $\psi_2$ is $d$-monotone with $d\geq 3$, $\boldsymbol{\alpha} \overset{m}\succeq \boldsymbol{\beta}$} and 
\begin{equation}

V(\beta) =\frac{1}{\psi_2^\prime\circ\phi_2(T(\beta,F))}\frac{\partial T}{\partial\beta}(\beta,F),\quad\beta\in A,
\end{equation}
is increasing, then {$X_{n:n}(\boldsymbol{\alpha})\geqst Y_{n:n}(\boldsymbol{\beta})$}.","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T06:16:18.657369+00:00","domain":"probability theory","id":"claim_91e710e3a7e6f781c56456b8f6588bfc27c0a21b0ad6a9ae643e691556416772","kind":"concept","schema_version":1,"statement":"[Proposition 21 (Tree-graph inequality; Aizenman and Newman
\cite{AN84}) of arXiv:2607.24561, 'Range convergence and sharp one-arm asymptotics\\for the critical percolation cluster in h'] For all $m\ge1$ and \emph{all} $x_1,\dots,x_m\in\Z^d$ (not necessarily
distinct, and not necessarily distinct from $0$),
\begin{equation}
\tau_{m+1}(0,x_1,\dots,x_m)\;\le\;
\sum_{T\in\T_m}\ \sum_{(z_v)_{v\in V_{\mathrm{int}}(T)}\in(\Z^d)^{V_{\mathrm{int}}(T)}}
\ \prod_{\{a,b\}\in E(T)}\tau_2(w_a,w_b),
\end{equation}
where $w_0:=0$, $w_i:=x_i$ for leaves and $w_v:=z_v$ for internal vertices.
The bound holds verbatim when some of the points coincide: with the
convention that a repeated point is not repeated in the connection event,
$\tau_{m+1}(0,x_1,\dots,x_m)$ is then a connection function of the distinct
points among $0,x_1,\dots,x_m$, which is still dominated by the displayed
sum (the right-hand side only grows when leaves are placed at coinciding
positions). (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T09:05:57.800069+00:00","domain":"probability theory","id":"claim_91e8ba9088246744d1e16255e163a69abf06b49cb7c1e387006753b0d6e4c13d","kind":"theorem","schema_version":1,"statement":"[Proposition 14 (Fractional Hardy weights) of arXiv:2608.30551, 'Critical Discrete Hardy Inequalities in $L^p$'] Let \(p\in(1,\infty)\), \(\sigma\in(0,1/2)\), and
\(\alpha\in(\sigma,1/2)\). Put
\[
    h_{p,\sigma,\alpha}:=k_{-\alpha}^{q_p}
\]
and
\[
    \mu_{p,\sigma,\alpha}:=\nu_{k_{-\alpha}},
\]
where \(\nu_g\) is defined in
\eqref{abstract one-function reference measure}. Define
\begin{equation}
    w_{p,\sigma,\alpha}(x)
    :=
    \frac{1}{a_p+1}
    \frac{\Delta^\sigma k_{-\alpha}^{a_p}(x)}
         {k_{-\alpha}^{a_p}(x)}
    +
    \frac{a_p}{a_p+1}
    \frac{\Delta^\sigma k_{-\alpha}(x)}
         {k_{-\alpha}(x)},
    \qquad x\in\Z.
\end{equation}
Then
\[
    w_{p,\sigma,\alpha}(x)>0,
    \qquad x\in\Z,
\]
and, for every \(u\in\ell^p(\Z,\mu_{p,\sigma,\alpha})\),
\begin{equation}
    \mathcal E_p^{\Z,\sigma}(u)
    =
    \sum_{x\in\Z} w_{p,\sigma,\alpha}(x)|u(x)|^p
    +
    \mathcal R_{p,\sigma,\alpha}(u),
\end{equation}
where
\begin{align}
    \mathcal R_{p,\sigma,\alpha}(u)
    :={}&
    \frac{1}{p}
    \sum_{x,y\in\Z}
    F_p\left(
        \frac{u(x)}{k_{-\alpha}(x)^{q_p}},
        \frac{u(y)}{k_{-\alpha}(y)^{q_p}}
    \right)
    \notag\\
    &\qquad\times
    k_{-\alpha}(x)^{r_p}
    k_{-\alpha}(y)^{q_p}
    k_\sigma(x-y).

\end{align}
In particular,
\begin{equation}
    \mathcal E_p^{\Z,\sigma}(u)
    \geq
    \sum_{x\in\Z} w_{p,\sigma,\alpha}(x)|u(x)|^p .
\end{equation}","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-26T19:26:17.748995+00:00","domain":"probability theory","id":"claim_91e941a2b166b9966b8cff09ee5b008fadb904b0f1ff29a3e0765563503230b3","kind":"concept","schema_version":1,"statement":"[Proposition 15 (Free multiplicative Poisson distributions) of arXiv:2511.01456, 'Zero distribution of multiplicative Hermite and Laguerre polynomials'] Let $\gamma>0$ and $\beta\in \C$ be such that either $\beta \in \R \backslash [-1,0]$ or $\Re \beta = -1/2$. Then, there exists a unique probability measure  $\nu_{\beta, \gamma}$ which is supported on a compact subset of $(0,\infty)$ (when $\beta \in \R \backslash [-1,0]$) or on the unit  circle (when $\Re \beta = -1/2$) and has the $S$-transform $S(y)=\exp (\frac{\gamma}{\beta+1+y})$. Moreover, $\nu_{\beta, \gamma}$ has the following properties.
\begin{itemize}
\item[(a)] Moments: For every $k\in \N$, the $k$-th moment of $\nu_{\beta, \gamma}$ is given by
\begin{align}
\int_\C x^k \nu_{\beta, \gamma}(\dd x)
&=
\frac1k [t^{ k-1}] \left( (1+t)^k \eee^{-k \gamma/(1+\beta+t)}\right) 
\\
&=
\frac {\eee^{- k\gamma/(1 + \beta)}}k  \sum_{j=0}^{k-1}\binom{k}{j+1}\left(\frac {-1}{1+\beta}\right)^{j}
L_{j}^{(-1)}\left(\frac {k\gamma}{1+\beta}\right), 
\end{align}
where $L_n^{(-1)}(c)= \sum_{j=1}^{n} \binom{n-1}{n-j}\frac{(-c)^{j}}{j!}$, for $n\in \N$, and $L_0^{(-1)}(c) = 1$,  are the associated Laguerre polynomials with $\alpha = -1$.
\item[(b)] Free cumulants: For every $k\in \N$, the $k$-th free cumulant of $\nu_{\beta, \gamma}$ is given by
\begin{align}
\kappa_k
=
\frac{1}{k} [t^{ k-1}] \eee^{-k \gamma/(1+\beta+t)}
=
\frac {\eee^{- k\gamma/(1 + \beta)}}k \left(\frac {-1}{1+\beta}\right)^{k-1}
L_{k-1}^{(-1)}\left(\frac {k\gamma}{1+\beta}\right).  
\end{align}
\end{itemize} (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-26T19:26:00.618359+00:00","domain":"probability theory","id":"claim_91ed40f7010ba147ea92c432557dd38803c2e14e7a7e1c21678832f6b78fbc1d","kind":"lemma","schema_version":1,"statement":"[Lemma 76 of arXiv:2510.27589, 'Geodesic switches and exceptional times in dynamical Brownian last passage percolation'] There exist constants $C,c,g>0$ such that for all $\delta>0$, all $n$ and all $m$ satisfying $ n/2\geq m\geq n^{1-3\delta/4}$, we have
 \begin{equation}

    \PP(\sup_{|x|\geq (1+m)^{2/3}n^{\delta}}Z_{\0}^{\n}(m+x,m)-Z_{\0}^{\n}(m,m)\geq - g(1+m)^{1/3}n^\delta)\leq Ce^{-cn^{3\delta/8}}.
  \end{equation}","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T23:01:54.289165+00:00","domain":"probability theory","id":"claim_91f363843d37644cdc76a2f5727e6ddff2f6541410e1ccea4d104719e82e37b2","kind":"lemma","schema_version":1,"statement":"[Lem lm1 of arXiv:2411.01849, 'A tamed-adaptive Milstein scheme for stochastic differential equations with low regularity'] For any $p \in [2, p_0]$, there exists a positive constant $C= C(p, \gamma, \eta)$ such that for any $t \geq 0,$
\begin{align*} 
