        &\leq r_V + C_i B^*\, \E\biggl(\int_{\mathcal{X}}\bigl\vert\lambda(x\,|\, \Xi_I) -\lambda(t(x) \,|\, t(\Xi_I))\bigr\vert \, \alpha(\diff x)\biggr)\\
