{"assumptions":[],"created_at":"2026-10-27T12:52:05.713707+00:00","domain":"probability theory","id":"claim_923cc84990db54efe048179b575f7d4a812f099ee0be9ad1d149e9270eb87b4b","kind":"lemma","schema_version":1,"statement":"[Lem l:1104.3 of arXiv:2602.21277, 'A Limit in Law for the Cover Time and Last Visited Vertex of Wired Planar Domains'] Let $\widehat{\eta}_{\rm D}$ be limit of $\{\widehat{\eta}_{n,r_n}\}$ along some subsequence, with $\{r_n\}$ as in~(equation e:1.11i of the paper). Then, there exists a coupling between $\widehat{\eta}_{\rm D}$, the random measure $\eta_{\rm D}$ from~(equation e:1.10i of the paper), and $h_{\rm D}^\psi$ from~(equation e:1104.13 of the paper), such that $\widehat{\eta}_{\rm D}$ and $h_{\rm D}^\psi$ are independent and 
\begin{equation}

\widehat{\eta}_{\rm D} \circ \tau^{-1}_{h^{\psi}_{\rm D}} = \eta_{\rm D} \,,
\end{equation}
where $\tau_{\psi}: {\rm D} \times \mathbb{R} \times \mathbb{R}^{\mathbb{Z}^2} \to {\rm D} \times \mathbb{R} \times \mathbb{R}^{\mathbb{Z}^2}$ is the translation operator
\begin{equation}
	\tau_{\psi}(x,s,\omega) =(x,s + \psi(x), \omega) \,.
\end{equation}
Moreover, along the above subsequence we have
\begin{equation}
	 \big(\eta_{n,r_n}, \widehat{\eta}_{n,r_n}, h_n^\psi\big) \Longrightarrow \big(\eta_{\rm D}, \widehat{\eta}_{\rm D}, h^\psi_{\rm D}\big) \,.
\end{equation}","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T19:51:00.245146+00:00","domain":"probability theory","id":"claim_923df2cca1a03a7fb2492a2692006dfaa67c8deda6a39e371a2573ef7cae0627","kind":"lemma","schema_version":1,"statement":"[Lemma eq: short first row of arXiv:2604.23890, 'The Cutoff Profile for Random Transpositions on Repeated Cards in the Full Range of Parame'] For all $\lambda=(\lambda_1,\lambda_2,\ldots)\vdash n$, we have
\begin{equation}
-\frac{\lambda_1'}{n}\le\frac 1n+\frac{n-1}{n}\frac{\chi_\lambda(\tau)}{d_\lambda}\le\frac{\lambda_1}{n},
\end{equation}
\begin{equation}
-1+2\frac{\lambda_1}{n}\le\frac 1n+\frac{n-1}{n}\frac{\chi_\lambda(\tau)}{d_\lambda}\le1-2\frac{\lambda_1}{n}+2\left(\frac{\lambda_1}{n}\right)^2.
\end{equation}
In particular, when $\lambda_1\ge n-n^{o(1)}$, set $r:=n-\lambda_1$. Then, we have
\begin{equation}
\frac 1n+\frac{n-1}{n}\frac{\chi_\lambda(\tau)}{d_\lambda}=1-2\frac{r}{n}+O(n^{-2+o(1)}).
\end{equation}","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T14:49:05.446421+00:00","domain":"probability theory","id":"claim_923e4a6a7798862baf5cb1ff598bb0813b8c18180995ff16fde1b008ce437cdd","kind":"definition","schema_version":1,"statement":"[Def ass of arXiv:2601.10568, 'Hydrodynamic Limit with a Weierstrass-type result'] Let $ \{\mu_N\}_{N\geq 1} $ be a sequence of probability measures on $ \Omega_N $, and let $g:\mathbb{T}\to[0,1] $ be a measurable function. If, for any continuous function $ G:\mathbb{T}\to\mathbb{R} $ and every $ \delta>0 $, it holds
	\begin{align*}
		\lim_{N\to+\infty}\mu_N
		\left(
		\eta\in\Omega_N
		:\big|\pi^N(\eta,G)-\langle g,G\rangle\big|>\delta
		\right)
		=0,
	\end{align*}
	we say that the sequence $ \{\mu_N\}_{N\geq 1} $ is a local equilibrium measure associated with the profile $ g $.","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-26T19:36:44.550641+00:00","domain":"probability theory","id":"claim_923e54303387905389ced97914c9fef794ae3a4f26de7b917ddd7b7463be755c","kind":"concept","schema_version":1,"statement":"[Lemma 6 of arXiv:2604.01978, 'Homogenized Transformers'] Under Assumption \ref{ass:high_order_short}, there exist $C_1,C_2>0$ independent of $\alpha, \eta, L$ such that
\begin{enumerate}
\item $b\in C^4((\S^{d-1})^n;\mathsf{T}(\S^{d-1})^n)$.
\smallskip
\item We have
\begin{equation*}
    \upsigma \coloneqq \max_{X\in(\S^{d-1})^n}\|G(X,\cdot)\|_{L^2({\uprho_*})}<\infty
\end{equation*}
and 
\begin{equation*}
     \underset{X \in (\S^{d-1})^{n}}{\max}\|G(X,\cdot)\|_{L^3({\uprho_*})}\leq C_1\upsigma .
\end{equation*}
\smallskip 
\item For ${\uprho_*}$-a.e.\ $\bm{\theta}$, $G(\cdot,\bm{\theta})\in C^5((\S^{d-1})^n;\mathsf{T}(\S^{d-1})^n)$ and
\begin{equation*}
    \left\|\Big\|G(\cdot, \bm\theta)\Big\|_{C^5} \right\|_{L^2({\uprho_*})} + \left\|\Big\|\nabla_{G(\cdot,\bm{\theta})}G(\cdot,\bm{\theta})\Big\|_{C^5}\right\|_{L^2({\uprho_*})} \leq C_2 \upsigma .
