\end{enumerate}
Moreover we can choose $C_1=O(1+\frac{\sigma_{\bA}\|\E\bV\|_{\mathrm{op}}\upbeta}{\sigma_{\bV}})$ and $C_2=O(1+\upbeta^{10}\sigma_{\bA}^{10}d^5)$. (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-26T20:24:59.504483+00:00","domain":"probability theory","id":"claim_924c6489049599f0191ae577647e472f3af08711fbc8f64d518a59eead88f356","kind":"definition","schema_version":1,"statement":"[Definition 80 of arXiv:2605.10150, 'Rough path theory and an introduction to rough partial differential equations'] We introduce the following notions:
\begin{enumerate}
\item We say that a path $Y \in \hat{\calc}^{\alpha}([0,T],\bar{W})$ is \emph{mildly controlled} by $X$ if there exists $Y' \in \hat{\calc}^{\alpha}([0,T], L(V,\bar{W}))$ such that for the remainder term $R^Y : [0,T]^2 \to \bar{W}$ given by
\begin{align}
R_{s,t}^Y := \hat{\delta} Y_{s,t} - S_{t-s} Y_s' X_{s,t} \quad \text{for all $s,t \in [0,T]$.}
\end{align}
we have $R^Y \in \calc_2^{2 \alpha}([0,T]^2,\bar{W})$, where $\hat{\delta} Y_{s,t} = Y_t - S_{t-s} Y_s$.

\item This defines the space of \emph{mildly controlled rough paths}, and we write
\begin{align*}
(Y,Y') \in \scrd_{S,X}^{2 \alpha}([0,T], \bar{W}).
\end{align*}
\item We call $Y'$ a \emph{mild Gubinelli derivative} of $Y$ (with respect to $X$).
\end{enumerate}","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T22:51:15.020418+00:00","domain":"probability theory","id":"claim_924d85022351133816cdbfac4d4bd588bcaf67ed85b6e6f69777f5dca256ba40","kind":"concept","schema_version":1,"statement":"[Prop VarianceInequalityBuresDistance of arXiv:2609.03762, '\vspace*{-2cm} Projected Riemannian Gradient Descent for the Bures--Wasserstein Barycenter'] Let $(R_i, w_i)_{i \in [n]}$ be a weighted ensemble and $g_1 := f_1 \circ \pi$.
        For any $S \in \mathrm{PD}(d)$,
