{"assumptions":[],"created_at":"2026-10-28T00:15:09.028236+00:00","domain":"probability theory","id":"claim_9265677eeee56a6bfdfd5215d59277b6c7e6df3106bfdde345f49d3b7b302337","kind":"concept","schema_version":1,"statement":"[Lemma lem:RW1 of arXiv:2411.10829, 'Airy$_\beta$ line ensemble and its Laplace transform'] For any $C_1, C_2>0$, there is a constant $C_3=C_3(C_1,C_2)>0$, such that for any $C_1N^{-2/3}<x<C_2$ and $0\le h, g <C_2$, and $X, H, G\in \mathbb Z_{\ge 0}$, such that $|X-xN^{2/3}|, |H-hN^{1/3}|, |G-gN^{1/3}|<C_2$, the following estimates hold:
\begin{enumerate}
    \item[(1)] When $X+H+G$ is even and $h,g>C_1N^{-1/3}$, we have
\begin{multline*}
\left|N^{1/3}I(X;H,G)-\mathbf I(x;h,g)\right| \\ <C_3\mathbf F(x;h,g)\left(1\wedge (N^{-3/5}x^{-3} + N^{-1/40} + N^{-1/3}/h+N^{-1/3}/g)\right).
\end{multline*}
    \item[(2)] When $X+H$ is even and $h>C_1N^{-1/3}$, we have
\[
\left|N^{2/3}I(X;H,0)-\mathbf I_0(x;h)\right| < C_3\mathbf F_0(x;h)\left(1\wedge (N^{-3/5}x^{-3} + N^{-1/40} +N^{-1/3}/g )\right).
\]
    \item[(3)] When $X+H+G$ is even, $H\le G$, and $g-h>C_1N^{-1/3}$, we have
\begin{multline*}
\left|N^{2/3}I^+(X;H,G)-\exp(-\beta^{-1} xh )\mathbf I_0(x;g-h)\right| \\ <C\mathbf F_0(x;g-h)\left(1\wedge (N^{-3/5}x^{-3} + N^{-1/40} +N^{-1/3}/g)\right).
\end{multline*}
    \item[(4)] When $X$ is even, we have
\[
\left|NI^+(X;H,H)-\exp(-\beta^{-1} xh)\mathbf I_{0,0}(x)\right| < C_3\mathbf F_{0,0}(x)\left(1\wedge (N^{-3/5}x^{-3} + N^{-1/40} )\right).
\]
\end{enumerate} (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T16:45:10.055337+00:00","domain":"probability theory","id":"claim_9267e893f86bc9115013f8dee6b888f1d7f4aa2e503f631ce266f915d2ccbf83","kind":"concept","schema_version":1,"statement":"[Theorem thm:N_mom_formula of arXiv:2504.14457, 'Abstract'] We have
