    \begin{align}
        X(t) & = X(0) + \int_{0}^{t} b(s,X_{[0,s]}) \, ds + \int_{0}^{t} \sigma(s,X_{[0,s]}) \, dW(s), \quad 0 \leq t \leq T,
    \end{align}
    with deterministic initial value $X(0) \in \R^d$.","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-26T20:58:28.470936+00:00","domain":"probability theory","id":"claim_93ed81ec655abf18313b83498bf87006601da3a03b98f451ba9c3cdf34045181","kind":"definition","schema_version":1,"statement":"[Definition 32 (Symmetrization) of arXiv:2606.29292, 'Intrinsic Gaussian Tensor Geometry and Random Operator Spectra'] For $q\ge1$ and a Hilbert space $H$, define
\begin{equation*}
  \operatorname{Sym}_q
  :=\frac1{q!}\sum_{\tau\in\mathfrak S([q])}U_\tau
  \quad\text{on }H^{\otimes q},
\end{equation*}
where
\[
  U_\tau(h_1\otimes\cdots\otimes h_q)
  :=h_{\tau^{-1}(1)}\otimes\cdots\otimes h_{\tau^{-1}(q)}.
\]
Thus
\begin{equation*}
  (\operatorname{Sym}_qK)_{i_1\cdots i_q}
  =\frac1{q!}\sum_{\tau\in\mathfrak S([q])}
    K_{i_{\tau(1)}\cdots i_{\tau(q)}}.
\end{equation*}
Set $H^{\odot q}:=\operatorname{Ran}(\operatorname{Sym}_q)$.  If $B$ is a
vector space, the same notation denotes
$\operatorname{Sym}_q\otimes\Id_B$ on
$H^{\otimes q}\otimes_{\mathrm{alg}}B$.  Set
$H^{\odot0}=\C$ and let $\operatorname{Sym}_0$ be the identity on $\C$.","status":"unverified"}

