{"assumptions":[],"created_at":"2026-10-26T19:26:17.760633+00:00","domain":"probability theory","id":"claim_94c5034cc02ce7ae47f406e0b10d0bd10cb7bc289a70da13dd3cb0a99ac456d7","kind":"lemma","schema_version":1,"statement":"[Lemma 43 of arXiv:2511.05386, 'CLT for $\beta$-ensembles with Freud weights, application to the KLS conjecture in Schatte'] Let $\mu$ be a probability measure on $[-1,1]$. 
	Let $\ell \geq 1$ and $\theta \in \cC^\ell(\R^*)$ such that $\int_{-1}^1 \abs{\theta} \diff \mu < \infty$. 
	Define $\Theta(x)$ for $x \in \R^*$ as in \eqref{eq:def_Theta}.
	Then, the following properties hold.
	\begin{enumerate}
		\item The function $\Theta$ is in $\cC^{\ell-1}(\R^*)$ and, for any $0 \leq k \leq \ell-1$ and $x \in \R^*$, \eqref{eq:derivative_Theta} holds.
		Moreover, $\Theta$ is $\cC^{\ell}$ on $\R \setminus [-1,1]$ and \eqref{eq:derivative_Theta} holds with $k=\ell$ and $x \notin [-1,1]$.

		\item If $\int \frac{1}{1-t} \diff \mu(t) < \infty$, then $\Theta$ is $\ell$ times differentiable at 1 and \eqref{eq:derivative_Theta} holds with $k=\ell$ and $x=1$.

		\item If $\mu$ has a density $\varrho$ such that, for some $M>0$, for any $x \in[-1,1]$, $\varrho(x) \leq M \sqrt{1-x}$, and if, for any $x \geq 1$, $\theta(x) = T_\ell[\theta,1](x)$, then
		\begin{equation} 
			\abs{\Theta^{(\ell)}(x)-\Theta^{(\ell)}(1)}
			\begin{cases}
				\leq 8 M (\ell+1) \left( \sup_{[1/2,1]} \lvert \theta^{(\ell)} \rvert \right) (x-1)^{1/2} & \\
				\qquad {} + 2^{\ell+2} (\ell+1)!  
				\left( \int \abs{\theta} \diff \mu + \sum_{k=0}^\ell \lvert \theta^{(k)}(1) \rvert \right) (x-1), & \text{for } x \in [1,2], \\
				= o((x-1)^{1/2}), & \text{as } x \downarrow 1.
			\end{cases}
		\end{equation}
	\end{enumerate}","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T13:44:12.641204+00:00","domain":"probability theory","id":"claim_94c7a77289ed550ad27b6d6b47ef1f379bcd409ec2cbd8d73db1e53e7e372a0f","kind":"lemma","schema_version":1,"statement":"[Lemma lem:relu-fourier of arXiv:2512.04371, 'Constructive Approximation under Carleman's Condition, \\ with Applications to Smoothed An'] The Fourier transform of $\mathsf{ReLU}(t) = \max\{0,t\}$ is given by the tempered distribution such that for every test function $\psi \in \cS(\RR)$,
\begin{align}
    \dotp{\widehat{\mathsf{ReLU}}}{\psi } =  \dotp{\mathrm{f.p.}\,\frac{-1}{\xi^2}}{\psi} +   i\pi \psi'(0).
\end{align}
Here $\mathrm{f.p.}\, \frac{1}{\xi^2}$ is the Hadamard finite part distribution defined as
\begin{align}
    \dotp{\mathrm{f.p.}\,\frac{1}{\xi^2}}{\psi} = \lim_{\varepsilon \to 0^+} \int_{|\xi|>\varepsilon} \frac{\psi(\xi) - \psi(0)}{\xi^2} \, d\xi.
\end{align}","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T10:51:11.511683+00:00","domain":"probability theory","id":"claim_94caaaf5e0d929f185767816988d2313557cfcb979bb74d3db3ae698ab8c1e69","kind":"theorem","schema_version":1,"statement":"[Theorem 6 (Exact Skellam regimes) of arXiv:2609.02590, 'Directional Optimal Sub-Gamma Scales for Infinitely Divisible Laws'] For the centered Skellam law \eqref{eq:centered-skellam}, the right scale has
