A solution to \eqref{derivative stein eq} is given by 
\begin{align}
    f_{a,n} \coloneqq 
    \begin{cases}
        \dis f_a, &n = 0,\\
        \dis (-1)^n \left\{\sum_{k=0}^{n-1}H_k\sD^{n-1-k}\delta_a + H_n(a)f_a \right\}, &n \in \N.
    \end{cases}
\end{align}","status":"unverified"}

