{"assumptions":[],"created_at":"2026-10-27T11:07:35.023789+00:00","domain":"probability theory","id":"claim_95b2dd62ed6aa275bda6881321d8da336a841a1c4c7ba1caad2d8c1b9c0be72c","kind":"definition","schema_version":1,"statement":"[Defn 10 of arXiv:2609.02879, 'On the cut locus of Hamilton--Jacobi equations I: structure and propagation via the touchi'] Let \( \Omega \subset \R^n \) be an open convex subset and $\phi\in\text{\rm SCL}\,(\Omega)$.
	\begin{enumerate}[(1)]


	\item We call $x\in\Omega$ a \emph{regular point} of $\phi$ if there exists a convex open neighborhood $V$ of $x$ and a semiconvex function $\psi: V \to \R$ with linear modulus touching $\phi$ from below at $x$ in $V$. We denote by $\reg(\phi)$ the set of regular points of $\phi$ and call it the \emph{regular set} of \( \phi \).

	\item We call $x\in\Omega$ a \emph{cut point} of $\phi$ if $x$ is not a regular point of $\phi$. We denote by $\cut(\phi)$ the set of cut points of $\phi$ and call it the \emph{cut locus} of $\phi$, that is, 
	\begin{align*}
	\cut(\phi)= \Omega \setminus \reg(\phi).
	\end{align*}
	\end{enumerate}","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T13:56:17.363888+00:00","domain":"probability theory","id":"claim_95b45dc77353a532fd93668a67b3afa0dc4edf58b145cef2b774224a5be28c50","kind":"concept","schema_version":1,"statement":"[Corollary cor:intersection of arXiv:2606.02472, 'Correlated uniform attachment trees'] Let 
