{"assumptions":[],"created_at":"2026-10-27T17:42:08.418151+00:00","domain":"probability theory","id":"claim_95c8dbe6c2547b52e509852ee8910e7528de3d67b88335faf78ee133ca35e06e","kind":"lemma","schema_version":1,"statement":"[Lemma UcupU of arXiv:2511.15893, 'On a Class of Dynamical Poisson-Voronoi Tessellations'] Suppose $s, s'\in \mathbb{R}$ with $s< s'$ and $h, h'\in \mathbb{R}^+$ for which $U^{s}_{h}\cap U^{s'}_{h'}\neq \emptyset$ and $\exists h_1\geq 0$ such that $ \partial^*U^{s}_{h}\cap \partial^*U^{s'}_{h'}= \{(0, h_1)\}$. Then we have 

\begin{align}
\left\vert U^{s}_{h}\cup U^{s'}_{h'}\right\vert&=
\begin{cases}
    \frac{\pi}{2}h^2+{\frac{1}{2}} h_1(s'-s)+{\frac{1}{2}} F_1(h_1, h, h'), &\text{ if } s<s'<0,\\ 
    \frac{\pi}{2}(h^2+h'^2)+{\frac{1}{2}} h_1(s'-s)-{\frac{1}{2}} F_2(h_1, h, h'), &\text{ if } s<0<s',\\ 
    \frac{\pi}{2}h'^2+{\frac{1}{2}} h_1(s'-s)-{\frac{1}{2}} F_1(h_1, h, h'), &\text{ if }0<s<s',
\end{cases}

\end{align}

where 

\[
F_1(h_1, h, h')=h'^2\arcsin(h_1/h')- h^2\arcsin(h_1/h),\;\; F_2(h_1, h, h')=h'^2\arcsin(h_1/h')+h^2\arcsin(h_1/h).
\]","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T07:14:37.599080+00:00","domain":"probability theory","id":"claim_95d242cf3cbd9409ee34421d0a7c780e974f36de9f9533c65fe89bf99f213cd8","kind":"concept","schema_version":1,"statement":"[Lemma 19 of arXiv:2608.18688, 'Regularity Preservation for Jump-Type Stochastic Transport Equations with Singular Drift'] Take $\lambda, T>0$ and $p,q\in (1,\infty)$. For any $f\in \mL_p^q(T)$, there exists a unique solution $U\in \mH_p^{2,q}(T)$ to the backward parabolic system (\ref{Dackward-PDE1}). For this solution there exists a constant $C$ depending only on $d,p,q,T$ such that  for all $\lambda\geq 0$
\ce 
\|\nabla^2 U\|_{\mL_p^{q}([0,T])}\leq C\|f\|_{\mL_p^q([0,T])}
\de 
Moreover, for any $\vartheta\in[0,2)$ and $p'\in [p,\infty]$, $q'\in [q,\infty]$ satisfying 
\ce 
\frac{d}{p}+\frac{2}{q}<2-\vartheta+\frac{d}{p'}+\frac{2}{q'}
\de 
there exists a constant $C$ depending only on $d,p,q,T, p',q'$ such that  for all $\lambda>0$
\be 
\lambda^{\frac{1}{2}(2-\vartheta+\frac{d}{p'}+\frac{2}{q'}-\frac{d}{p}-\frac{2}{q})}
\|U\|_{\mW^{q'}_{\vartheta,p'}([0,T])}\leq  C\|f\|_{\mL_p^q([0,T])}.
\ee (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T14:01:56.343279+00:00","domain":"probability theory","id":"claim_95d42f5a60968523000d0728394bef85ab32d0d897848f136695ed4071155b2e","kind":"concept","schema_version":1,"statement":"[Thm 1-2-direction-rigidity of arXiv:2609.01499, 'On the rigidity of sloped height functions in $d\ge 3$ \\ and non-crossing surfaces'] Fix $d\ge 3$ and suppose $4$ divides $L$.\footnote{The same proofs go through in $d=2$, but most of the arguments degenerate to simpler Peierls bounds, so the presentation from now on will assume $d\ge 3$ so definitions are not vacuous.} There exist constants $c,\beta_0>0$ such that if  $\min_{i=1,2} V_i(1)\ge \beta_0$ the following holds. 
    Fix $\mathfrak{s} = (0,0,s_3,...,s_d)$ and consider an $\mathfrak{e}_1$ or $\mathfrak{e}_2$ oriented edge $e$; for all $r\ge 1$, 
    \begin{align*}
        \mu_{L,\mathfrak{s}}^\nabla (|\nabla_e \phi| \ge r) \le e^{ - c \min_{i=1,2} V_i(1) r }\,.
    \end{align*}
    More generally, for a family of distinct $\{\mathfrak{e}_1,\mathfrak{e}_2\}$-oriented edges $e_1,...,e_m$, and integers $r_1,...,r_m\ge 1$, 
    \begin{align*}
        \mu_{L,\mathfrak{s}}^\nabla \Big( \bigcap_{i=1}^m \{|\nabla_{e_i} \phi | \ge r_i\} \Big) \le e^{ - c \min_{i=1,2} V_i(1) \sum_{i=1}^m r_i}\,.
    \end{align*} (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-26T19:27:36.744598+00:00","domain":"probability theory","id":"claim_95d508657db51f2f7beb1530b8521019358e3d68cd12d82ec154c1b9ee2b505a","kind":"concept","schema_version":1,"statement":"[Theorem 1 (Uniform Laplace principle of bridges) of arXiv:2511.14757, 'A weak convergence approach to the large deviations of the dynamic Schr\"odinger problem'] Under Assumptions \ref{ass:b-sigma-local-properties}--\ref{ass:log-gradient-convergence}, for any compact set $K \Subset D$,
    \begin{equation}
        \lim_{\eta \downarrow 0} \sup_{x,y \in K} \left|-\eta \log \bE\left[\exp - \frac{1}{\eta} F(X^{\eta, xy}) \right] - \inf_{\varphi \in \calC_1} \left[F(\varphi) + I_B^{xy}(\varphi)\right]\right| = 0,
    \end{equation}
    where $X^{\eta, xy}$ is given by the dynamics \ref{eq:R-SDE-main-results}, conditioned on starting in $x$ at $t=0$ and ending in $y$ at $t=1$.
    The good rate function $I_B$ is given by
    \[ I_B(\varphi) = \inf_{\nu \in U^{xy}_\varphi} \frac{1}{2} \int_0^1 |\nu(t)|^2 dt,\]
    where $U^{xy}_\varphi \coloneq \{\nu \in L^2([0,1]:\bR^d): \varphi(\cdot) = \int_0^{\cdot} (b(s, \varphi(s) + \sigma(s, \varphi(s))\nu_s)ds\}$. (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-28T02:16:53.607047+00:00","domain":"probability theory","id":"claim_95d6ffd096e59744f170abfc4c582a5b6c7e10cd10b9acdf79b0d9c3bf767c47","kind":"lemma","schema_version":1,"statement":"[Lemma lem:auxli-S1S2 of arXiv:2412.05142, 'Strong convergence of the Euler scheme for singular kinetic SDEs driven by $\alpha$-stable'] Let $p\geqslant2$.  Let $\gamma_1,\gamma_2,\gamma_3\in(0,1]$ be constants so that
    \begin{align}

        \frac{\beta-2}{\alpha}+\gamma_1>0,\quad \gamma_2+\frac{\beta-1}{\alpha}>0.
    \end{align}
    Let $f\in{\mathbb C}_{\boldsymbol{a}} ^{(1+\alpha)\beta}$, $\beta\in(0,\alpha-1)$. Let $\phi,\psi:[0,1]\time\Omega\rightarrow{\mathbb R}^{2d}$ be bounded, adapted, measurable functions and suppose that there exists $C_\phi, C_\psi>0$ so that for any $(s,t)\in[0,1]_\leqslant^2$ we have a.s. 
    \begin{align}
       {\mathbb E}^s|\phi_t-{\mathbb E}^s\phi_t|\leqslant C_\phi|t-s|^{\gamma_1}, 
    \\ {\mathbb E}^s|\psi_t-{\mathbb E}^s\psi_t|  \leqslant C_\psi|t-s|^{\gamma_3}.
    \end{align}
    Then there exists a constant $N =N(\alpha,\gamma,p,d,\gamma_1,\gamma_2, \beta)$ so that for any $(S,T)\in[0,1]_\leqslant^2$ and any $\sigma$-algebra ${\mathscr G}\subset{\mathcal F}_S$ we have the bound
    \begin{align}

      \| \int_S^T f(M_r+\phi_r)-&f(M_r+\psi_r)dr\|_{L_p(\Omega)|{\mathscr G}}\nonumber\\\leqslant &N\|f\|_{{\mathbb C}_{\boldsymbol{a}}^{\beta}} |T-S|^{\frac{(\beta-1)}{\alpha}+\gamma_2+1}[\phi-\psi]_{{\mathscr C}_p^{\gamma_2}|{\mathscr G},[S,T]}\nonumber\\&+N\|f\|_{{\mathbb C}_{\boldsymbol{a}}^{\beta}} |T-S|^{\frac{(\beta-1)}{\alpha}+1}\|\phi-\psi\|_{C_p^0|{\mathscr G},[S,T]}\nonumber\\&+NC_\phi\|f\|_{{\mathbb C}_{\boldsymbol{a}}^{\beta}} |T-S|^{\frac{(\beta-2)}{\alpha}+1+\gamma_1}\|\phi-\psi\|_{C_p^0|{\mathscr G},[S,T]}.
    \end{align}","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-26T20:33:01.784479+00:00","domain":"probability theory","id":"claim_95d7316e38e5f735d604726788c9a8f266d396bf147434a1e398511e6e4c99bc","kind":"lemma","schema_version":1,"statement":"[Lemma 40 (Eigenfunctions of the Ornstein--Uhlenbeck generator in $\R^N$) of arXiv:2605.14630, '2605.14630'] For $k\in\H=\R^N$ let
