{"assumptions":[],"created_at":"2026-10-26T19:41:33.829342+00:00","domain":"probability theory","id":"claim_9623e83102381bfb1a6b14313819142d4629141a348395a7eb13a4eb845df015","kind":"concept","schema_version":1,"statement":"[Proposition 12 of arXiv:2604.10705, '#1'] Let $X:[0, T] \to \mathbb{R}^d$ be a semimartingale satisfying
\begin{align*}
dX(s) = a(s, X_{\wedge s})\mathrm{d}s + \sigma(s, X_{\wedge s^-})\mathrm{d}B(s),
\end{align*} 
with $a = (a_1,...,a_d)$, and $\sigma = (\sigma_{i,j})_{1\leq i\leq d, 1\leq j\leq m}$ such that $a_i \in \mathscr{C}^{0,0}([0,T],\mathbb{R}^d)$, $\sigma_{i,j} \in \mathscr{C}^{0,0}([0,T],\mathbb{R}^d)$, and $B$ a standard $m$-dimensional Brownian motion. Furthermore, let $g \in \mathscr{C}^{0,0}([0,T],\mathbb{R}^d), r \in \mathscr{C}^{0,0}([0,T],\mathbb{R}^d)$ be such that $g$ is integrable and $r$ is positive. Define the non-anticipative functional $f \in \mathscr{C}^{0,0}([0,T],\mathbb{R}^d)$ by,
\begin{align*}
f(t, x) &= \mathbb{E}\left[e^{-\int_t^T r(s, X_{\wedge s})\,\mathrm{d}s} g(T,X_{\wedge T})|X_{\wedge t} = x_{\wedge t}\right].
\end{align*}
Then, if $f \in \mathfrak{C}^2([0, T], \mathbb{R}^d)$, its functional derivatives satisfy 
\begin{align}
\partial f(t, X_{\wedge t}) + \langle a(t, X_{\wedge t}), \tilde{\nabla}f(t, X_{\wedge t^-})\rangle - r(t, X_{\wedge t})f(t,X_{\wedge t})\nonumber &\\
+ \frac{1}{2}Tr(\tilde{\nabla}^2 f(t, X_{\wedge t}) \sigma(t, X_{\wedge t})\sigma(t, X_{\wedge t})^T) = 0&\,\,\text{a.s.}
\end{align} 
\begin{proof}
Let $h \in \mathscr{C}^{0,0}([0,T],\mathbb{R}^d)$ satisfy
\begin{align*}
h(t, X_{\wedge t}) = e^{-\int_0^t r(s, X_{\wedge s})\,\mathrm{d}s}f(t,X_{\wedge t}).
\end{align*}
By the tower property of conditional expectation,
\begin{align*}
h(t, X_{\wedge t}) = \mathbb{E}\!\left[e^{-\int_0^T r(s, X_{\wedge s})\,\mathrm{d}s}\,
g(T,X_{\wedge T})\,\Big|\,\mathcal{F}_t\right].
\end{align*}
Since $r$ is positive and $g$ is integrable, the terminal variable
$e^{-\int_0^T r\,\mathrm{d}s}\,g(T,X_{\wedge T})$ is integrable, so $h$
is a true martingale. On the other hand, a direct application of
Theorem~\ref{Coinvariant Ito} gives
\begin{align}
dh(t, X_{\wedge t}) = e^{-\int_0^t r(s, X_{\wedge s})\,\mathrm{d}s}
\Big( -r(t, X_{\wedge t})f(t,X_{\wedge t})+\partial f(t, X_{\wedge t})
+ \langle a(t, X_{\wedge t}),\tilde{\nabla}f(t, X_{\wedge t^-})\rangle
\nonumber &\\
+ \tilde{\nabla}f(t, X_{\wedge t^-})^T\sigma(t, X_{\wedge t^-})dB(t)
+ \frac{1}{2}Tr(\tilde{\nabla}^2 f(t, X_{\wedge t})
\sigma(t, X_{\wedge t})\sigma(t, X_{\wedge t})^T\Big)
\,\,\text{a.s.}&
\end{align}
By the uniqueness of the semimartingale decomposition, the drift terms
in \eqref{h-dynamics} must vanish. Canceling the exponential factor,
we arrive at \eqref{F-Kac}.
\end{proof} (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

