 \frac{1}{\mathbb P(A)}\,\mathbb E[|g| \, \mathbf1_A]\le \lambda,
\end{equation}
then there exists a finite or countable collection of pairwise disjoint atoms $\{A_j\}_{j\in J}$ contained in $A$ such that

\smallskip
\noindent\textup{(i)}
\begin{equation}

 \lambda<\frac{1}{\mathbb P(A_j)}\,\mathbb E[|g| \, \mathbf1_{A_j}]\le \alpha^{-1}\lambda,
 \qquad j\in J;
\end{equation}

\noindent\textup{(ii)}
