				\langle u,f\rangle_{{\mathcal{H}}^{-k_1},{\mathcal{H}}^{k_1}}
				=
				\langle u,f\rangle_{{\mathcal{H}}^{-k_2},{\mathcal{H}}^{k_2}}
				=
				\langle u,f\rangle_{{\mathcal{H}}^{-k_2}_w,{\mathcal{H}}_w^{k_2}}.
			\end{align}
			\item For any $k \in {\mathbb{N}}$, $C_c^\infty({\mathbb{R}}^d)$ is dense in  ${\mathcal{H}}^{k}_w$ and 
			\begin{align} 
