{"assumptions":[],"created_at":"2026-10-27T12:59:58.432054+00:00","domain":"probability theory","id":"claim_9762bbf7a228ae61a1caecc73c9756e78b5e59e0da3124302c074e3309d659d3","kind":"definition","schema_version":1,"statement":"[Definition Villain model on a percolation configuration of arXiv:2604.24743, 'The impact of disorder and non-convex interactions on delocalisation of height functions'] Given an edge percolation configuration $\omega \in \{0 , 1\}^{E(\ensuremath{\mathbb{Z}^d})}$, a finite set $\Lambda \subseteq \ensuremath{\mathbb{Z}^d}$ and an inverse temperature $\beta \geq 0$, we consider the Villain model on the percolation configuration $\omega$ to be the probability distribution on the set of configurations $[0 , 2\pi)^{\Lambda}$
\begin{equation*}
    \mu_{\Lambda , \beta , \omega}^{\mathrm{Vil}}(d \theta) := \frac{1}{Z_{\Lambda, \beta, \omega}^{\mathrm{Vil}}} \prod_{\substack{x , y \in \Lambda \\ x \sim y}} v_{\omega_{xy}\beta} \left( \theta_x - \theta_y \right) \prod_{x \in \Lambda} d \theta_x.
\end{equation*}
We denote by $\mu_{\beta,\omega}^{\mathrm{Vil}}$ the thermodynamic limit obtained by taking the limit $\Lambda \uparrow \ensuremath{\mathbb{Z}^d}$ (whose existence
and uniqueness is once again guaranteed by compactness arguments and the Ginibre inequality), and denote by $\left\langle \cdot \right\rangle_{\beta, \omega}$ the corresponding expectation.","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T05:37:15.397367+00:00","domain":"probability theory","id":"claim_9763531974e09d0c500e3cc6ea58d9226232841c86ce79b01f04a2dbfb99bcc9","kind":"theorem","schema_version":1,"statement":"[Theorem 10 of arXiv:2607.12365, 'Bernoulli--Doob representation, asymptotic limits and boundary behavior of bounded homogen'] Suppose $(M_n(t))_{n\ge0}$ satisfies for $n\ge1$ the integral
recursion
\[
M_n(t) = z^ne^{-\lambda_n(t-s)}
+\lambda_n\int_s^te^{-\lambda_n(t-u)}M_{n-1}(u)\,du\,,
\]
with $M_0\equiv1$ and $M_1\equiv z$. Then:
\begin{enumerate}
\item[\rm(1)] \textbf{(ODE)}
      $\dfrac{d}{dt}M_n(t)=\lambda_n(M_{n-1}(t)-M_n(t))$,
      $M_n(s)=z^n$.
\item[\rm(2)] \textbf{(Matrix exponential)}
      With $B$ the lower-bidiagonal matrix $B_{n,n}=-\lambda_n$,
      $B_{n,n-1}=\lambda_n$:
      $M(t)=\exp((t-s)B)\,M(s)$.
\item[\rm(3)] \textbf{(Closed form)}
      For $0\le m\le n$:
      \[
      M_n(t)
      = \sum_{m=0}^nz^m\sum_{j=m}^ne^{-\lambda_j(t-s)}
        \frac{\displaystyle\prod_{r=m+1}^n\lambda_r}
             {\displaystyle\prod_{\substack{r=m\\r\ne j}}^n
              (\lambda_j-\lambda_r)}\,.
      \]
\item[\rm(4)] \textbf{(Examples)}
      $M_0=1$, $M_1=z$,
      $M_2(t)=z+z(z-1)e^{-\eta(t-s)}$,
      \[
      M_3(t)=z+\tfrac{3}{2}z(z-1)e^{-\eta(t-s)}
      +\bigl(z^3-\tfrac{3}{2}z(z-1)-z\bigr)e^{-3\eta(t-s)}\,.
      \]
\end{enumerate}
As $t\to\infty$, $M_n(t)\to z$ for all $n\ge1$, confirming that
$Z_\infty\sim\mathrm{Ber}(z)$.","status":"unverified"}

