{"assumptions":[],"created_at":"2026-10-27T20:36:16.067583+00:00","domain":"probability theory","id":"claim_990f5bbed1e2ce70e69a0bc97ac8cfcf5d1acdd75c19c82e56acab8cc742e4bd","kind":"lemma","schema_version":1,"statement":"[Lemma lem:nonlinear_est of arXiv:2606.28575, 'Global smooth solutions by high mode Lie-Transport noise for Logarithmically Hyperdissipat'] For all $g$ verifying (hp_correction of the paper) and every $\xi, \omega \in H^{-1/4}_g$, denoting $v=K[ \xi], \ u = K[\omega]$ it holds 
    \begin{equation}
        \|\nabla \times (\operatorname{div} (u\otimes v))\|_{H^{-2}_g}\le \|\omega \|_{H_g^{-1/4}}\|\xi \|_{H_g^{-1/4}}. 
    \end{equation}
    As a consequence, it holds 
    \begin{equation}
        \|\mathcal{L}_u\omega - \mathcal{L}_{v}\xi\|_{H^{-2}_g}\le C( \|\omega\|_{H_g^{-1/4}} + \|\xi\|_{H_g^{-1/4}})\|\omega - \xi\|_{H^{-1/4}_g}.
    \end{equation}","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-28T02:16:53.626923+00:00","domain":"probability theory","id":"claim_991089c6d616a2dd5215db6e308cd46d1716d12f905374cbd23b598763d3a106","kind":"concept","schema_version":1,"statement":"[Conjecture conj:perc of arXiv:2412.05503, 'Critical scaling profile for trees and connected subgraphs \\ on the complete graph'] For $s\in \mathbb{R}$, let
\begin{equation}

f_{\rm perc}(s) = \int_0^\infty x^2 \mathrm d\sigma_s, \qquad
\mathrm d \sigma_s =
	\frac 1 { \sqrt{2\pi} } x^{-5/2} \Psi(x^{3/2})
    e^{-\frac 1 6 x^3 + \frac s 2 x^2 - \frac{ s^2} 2 x}
    \mathrm dx
    .
\end{equation}
Then, for some $a,b>0$, as $V\to\infty$ we have
\begin{equation} 
\begin{aligned}
    \tau_{V,01}(1+sV^{-1/3}) & \sim b V^{-2/3} f_{\rm perc}(as),
    \\
    \chi_{V} ^{\rm {perc}}(1+sV^{-1/3}) & \sim b V^{1/3} f_{\rm perc}(as).
\end{aligned}
\end{equation} (Stated as a conjecture by the paper; open unless the paper says otherwise.)","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T09:19:56.684573+00:00","domain":"probability theory","id":"claim_9913968b97e68d3a0d95cbe64217b981f1944bc9531a9c6db2292baf53dd37b1","kind":"lemma","schema_version":1,"statement":"[Lemma 5 of arXiv:2608.30898, 'Necessity of Ladyzhenskaya \& Ural'tseva's sufficient conditions in nonuniform ellipticity'] The Fenchel conjugate of $\ti{J}_{q}$ is $A_{p}(z):=\ti{J}_{q}^{*}(z)=(1+\snr{z}^{p})^{\frac{1}{p}}$ for all $z\in \mathbb{R}^{n}$, with $p:=q/(q-1)$. Moreover, for all $z\in \mathbb{R}^{n}\setminus \{0\}$, $\xi\in B_{1}(0)\setminus\{0\}$ it holds
\eqn{0.98}
$$
\partial A_{p}(z)=\frac{\snr{z}^{p-2}z}{(1+\snr{z}^{p})^{1-1/p}},\qquad \quad \partial \ti{J}_{q}(\xi)=\frac{\snr{\xi}^{q-2}\xi}{(1-\snr{\xi}^{q})^{1-1/q}},
$$
and, in particular, 
\eqn{0.99}
$$
\partial A_{p}(\partial\ti{J}_{q}(\xi))=\xi\qquad \mbox{for all} \ \ \xi\in B_{1}(0)\setminus \{0\}.
$$","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T16:22:59.720370+00:00","domain":"probability theory","id":"claim_991447798498e2eb37c0cbadd76c415da65ba2b10616878722d508c245797e65","kind":"concept","schema_version":1,"statement":"[Theorem thm:k-completeness of arXiv:2608.29708, 'Intuitionistic and Constructive Modal Logics for Classical Modal Logicians'] Let $\mathcal{K} = \set{ \varphi \in \mathscr{L}_{\Box\Diamond}; \forall \mathfrak{F}: \text{k-frame}\ (\mathfrak{F} \vDash \varphi) }$, then the following properties hold:
  \begin{enumerate}[label=(\arabic*)]
    \item $\textbf{K}_\Box = \mathcal{K} \cap \mathscr{L}_\Box$ and $\textbf{K}_\Diamond = \mathcal{K} \cap \mathscr{L}_\Diamond$.
    \item $\textbf{K}_\Box + \textsf{Dual}_\Box = \mathcal{K}$ and $\textbf{K}_\Diamond + \textsf{Dual}_\Diamond = \mathcal{K}$.
  \end{enumerate}
  \begin{proof}
    (1) Routine completeness proof. (2) Follows from (1) and the usual translations $\tau_\Box(\Diamond \varphi) = \neg \Box \neg \tau_\Box(\varphi)$ and $\tau_\Diamond(\Box \varphi) = \neg \Diamond \neg \tau_\Diamond(\varphi)$.
  \end{proof} (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-28T01:16:46.709432+00:00","domain":"probability theory","id":"claim_99144dc82ed7fa156c3dae75740191b4734e08e8b7fbb399a1f1dc77b3e49b88","kind":"concept","schema_version":1,"statement":"[Theorem thrm:suplinpafit of arXiv:2411.18749, 'A star is born: Explosive Crump--Mode--Jagers branching processes'] Suppose that $f(i,w)=g(w)s(i)$, where $s$ satisfies Assumption~(ass:s of the paper) and $g$ and $s$ satisfy~(equation eq:gsass of the paper). Suppose there exists a sequence $(k_n)_{n\in\mathbb{N}}$ and constants $\varepsilon>0, \delta\in(0,\varepsilon)$, and $n_0\in\mathbb{N}$,  such that both 
	\begin{equation} 
	\mathbb{P}\!\left(g(W)>k_n\right)\leq n^{-(1+\varepsilon)}, \qquad\text{for all }n\geq n_0,
	\end{equation} 
	and
	\begin{equation} 
	\lim_{n\to\infty} \frac{\mu_{(\delta\log(n)/(\mu_n k_n))^{1/\beta}}}{\mu_nk_n}=\infty
	\end{equation}  
	are satisfied, where $\beta$ is as in Assumption~(ass:s of the paper). Then, the limiting infinite tree $T_\infty$ contains a unique infinite star and no infinite path, almost surely. (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T07:21:06.856187+00:00","domain":"probability theory","id":"claim_991a9cd649f6360b40c3683d97005f767dea9582e8d7fbc1f6b5b61801903c44","kind":"theorem","schema_version":1,"statement":"[Proposition 23 of arXiv:2608.21014, 'The stochastic Cahn--Hilliard equation in critical spaces'] Let $d=4$ and suppose that the assumptions of Theorem~\ref{thm:localWP_weakened} hold. Moreover, let $u_0\in L^0_{\F_0}(\Omega;H^1(\sO))$ and $T>0$. Let $(u,\sigma)$ be the unique maximal solution to \eqref{eq:SCHtorus} and $\mu$ the chemical potential of Definition~\ref{def:chemPotential}. Then, we have
	\begin{equation}
	       \sup_{t\in[0,T]\cap [0,\sigma)}\|u(t)\|_{H^1}+\int_0^{\sigma \land T} \|\grad \mu(t)\|_{L^2}^2 \dt < \infty  \qquad \mathbb{P}\text{-a.s.}
	\end{equation}
	If, in addition, $u_0\in L_{\F_0}^4(\Omega;L^4(\sO))\cap L_{\F_0}^2(\Omega;H^1(\sO))$, then
    \begin{equation}
    \E\bigg[\sup_{t\in[0,T]\cap[0,\sigma)}  \|u(t)\|^2_{H^1(\sO)} + \int_0^{\sigma \land T} \|\grad \mu(t)\|_{L^2}^2 \dt \bigg] \le C_{\psi,T,\sO}\big(1+\|u_0\|^4_{L^4(\Omega;L^4(\sO))}+\|u_0\|^2_{L^2(\Omega;H^1(\sO))}\big) < \infty.
    \end{equation}","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-26T19:32:15.350762+00:00","domain":"probability theory","id":"claim_991b838841e9298563f45efb0d9f34ee42ef0892ab8f6f7cee32c10c445e4d08","kind":"lemma","schema_version":1,"statement":"[Lemma 11 of arXiv:2506.15736, 'Coming down from infinity for coordinated particle systems'] Let $(X(t))_{t \geq 0}$ be a $\Lambda$-coalescent with death according to $D(dz)$ and $\Lambda(dz)$ satisfying \eqref{eq:density} with parameter $\alpha \in (1,2)$. Now if $X(s) = k+j$, then there exists a constant $C > 0$ such that the probability that the next event the process experiences is a death event that brings it below $k$ particles is bounded above by

    \begin{align*}
        \frac{C}{k^\alpha}\left(1 + \frac{k}{j} \right).
    \end{align*}

    \noindent In particular, the constant $C > 0$ is independent of $k$ and $j$.","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-28T02:31:45.221258+00:00","domain":"probability theory","id":"claim_991d02b1313971137b6977cd9934447ae535e231b9e66a8c2f0afd47ad9a5a15","kind":"concept","schema_version":1,"statement":"[Proposition fm4app of arXiv:2412.06086, 'Zeros of conditional Gaussian analytic functions, random sub-unitary matrices and q-series'] For every $t>0$, the multipoint factorial moments $F_{n,\, t/n}^{(k)}(r_1, \ldots, r_k) $(equation mpfm of the paper) of the eigenvalue moduli of random subunitary matrices $A_{n,\, t/n}$ converge, in the limit of infinite matrix dimension $n\to\infty$, to
\begin{align}
F_{t}^{(k)}(r_1, \ldots, r_k)=\exp\left[t-\frac{t}{(r_1\cdots r_k)^2} \right]\sum_{\sigma\in S_k} \prod_{\nu\in \sigma } (-1)^{|\nu|-1} \frac{1}{1-r_{\nu}^2}\, ,
\end{align}
where the sum is over all permutations of $k$ indices, the product is over all disjoint cycles $\nu$ of permutation $\sigma$, $|\nu|$ is the length of $\nu$ and $r_{\nu}=\prod_{j\in \nu} r_j$. (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T21:05:37.780066+00:00","domain":"probability theory","id":"claim_99211633d1ef57668c48561cb0734306722e5314d005c31e3b4e977676611588","kind":"theorem","schema_version":1,"statement":"[Corollary cor:bc-fidelity of arXiv:2608.01253, 'The pseudo-quantum representation of \\finite reversible Markov chains'] For all $t_1,t_2\ge0$,

\begin{equation}
\mathrm{BC}(\pi_{t_1},\pi_{t_2})=\braket{\sqrt{\pi_{t_1}}}{\sqrt{\pi_{t_2}}}
=\braket{\psi_{\theta(t_1)}}{\psi_{\theta(t_2)}}
=\cos^{n}\!\Bigl(\tfrac{\theta(t_2)-\theta(t_1)}2\Bigr).

\end{equation}

The Bhattacharyya overlap of the laws at two times equals the fidelity
overlap of the corresponding register states, and it depends only on the
clock increment.","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T20:42:16.247652+00:00","domain":"probability theory","id":"claim_99237473086e2c9f2a07da102f2a19005f6f7729b8aa72e996fa9415fb05e376","kind":"lemma","schema_version":1,"statement":"[Lemma lem:CRP case of arXiv:2607.01946, 'Second-order fluctuations for a phase transition in random partitions'] Suppose $\alpha\in(0,1)$. \begin{enumerate}[(i)]
\item 
Suppose $p_\ell = d_0\Gamma_\ell^{-1/\alpha}, \ell\in{\mathbb N}$ as in (equation eq:p_n CRP of the paper). 
For every $K>0$,
\begin{equation}
\max_{|k|\le K\sqrt{j_n\log\log n}}\abs{np_{\ell_n+k}-j_n   +\frac{j_n(\Gamma_{\ell_n}-\ell_n+k)}{\alpha\ell_n}}= O\pp{j_n^{1/4}(\log n)^{1/2}\pp{\log\log n}^{1/4}},
\end{equation}
almost surely. 
\item Suppose $p_n = d_0n^{-1/\alpha}(1+\rho_n)$. Then for all $K>0$,
\begin{equation}
\max_{|k|\le K j_n^{1/2}}\abs{np_{\ell_n+k}-j_n + \frac{j_nk}{\alpha\ell_n}} = O\pp{1}+O\pp{j_n\max_{|k|\le Kj_n^{1/2}}|\rho_{\ell_n+k}|}.
\end{equation}
\end{enumerate}","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T05:47:53.328216+00:00","domain":"probability theory","id":"claim_9923f6c5e712b5eee1335dae46088d29f0992ad0f497c49e794588e708779c01","kind":"concept","schema_version":1,"statement":"[Thm 1 of arXiv:2607.14674, 'On the entropy of the log-normal distribution'] The entropy $H[g_r]$ of the family of densities \eqref{eq:SC} is given as the power series
\begin{equation}
H[g_r]=H[g]+\alpha r -\sum_{k=1}^\infty \frac{\beta_k}{2k(2k-1)}r^{2k},\quad -1\le r\le 1,
\end{equation}
where
\begin{eqnarray}
\alpha&=&\frac{1}{\sqrt{2\pi}}\int_{-\infty}^\infty \exp(-t^2/2) t\sin(2\pi t)\,dt,\\
\beta_k&=&\frac{1}{\sqrt{2\pi}}\int_{-\infty}^\infty\exp(-t^2/2)\sin^{2k}(2\pi t)\,dt, k=1,2,\ldots.
\end{eqnarray} (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T06:29:21.910383+00:00","domain":"probability theory","id":"claim_9925b7448b381cede98b2161f97ebf718fc3c2274660d2c12fc53bab0348f3d2","kind":"theorem","schema_version":1,"statement":"[Proposition 19 of arXiv:2608.01081, 'The Optimal Rate in the Averaged Random-Marginal Central Limit Theorem for Log-Concave Mea'] For $A-2z=|x-y|^2>0$,
\begin{align}
 S_n(a,b,z)
 &:=\E_\Theta
 K(\ip{x}{\Theta},\ip{y}{\Theta})\notag\\
 &=m_n\left[
 \sqrt{A-2z}
