{"assumptions":[],"created_at":"2026-10-26T19:30:24.611782+00:00","domain":"probability theory","id":"claim_99502e263e4bafae88276555bfbc68de786402e13b680503765995a939fd53c9","kind":"definition","schema_version":1,"statement":"[Definition 8 of arXiv:2506.08910, 'Critical points of random polynomials and finite free cumulants'] Let $\{q_N\}_{N=1}^{\infty}$ be a sequence of real rooted polynomials indexed by their degree of the form \begin{equation}
			q_{N}(x)=\prod_{j=1}^{N}\left(x-X_{j,N}\right).
		\end{equation} We say a sequence of polynomials $\{q_{N}\}$ is generated by the L\'evy triple $(c,\sigma^2,\nu)$ if \begin{enumerate}
		\item For any $N\in\N$, $X_{1,N}, X_{2,N},\dots, X_{N,N}$ are iid random variables. 
		\item There exists $\sigma\geq 0$, $c\in\R$, and a measure $\nu$ on $\R$ satisfying \begin{equation}
			\int_{\R}\min(x^2,1)\ \dd \nu(x)<\infty,\quad\text{and}\quad \nu(\{0\})=0,
		\end{equation} such that  $S_{N}=\sum_{j=1}^{N}X_{j,N}$ converges in distribution as $N\rightarrow\infty$ to a random variable $Y$ with log-characteristic function  \begin{equation}
		\log\E e^{itY}=-\frac{\sigma^2}{2}t^2+itc+\int_{\R}\left(e^{itx}-1-\frac{itx}{1+x^2}\right)\dd\nu(x).
	\end{equation}
	\end{enumerate}","status":"unverified"}

