{"assumptions":[],"created_at":"2026-10-27T13:41:28.183178+00:00","domain":"probability theory","id":"claim_99828e838ec0e459f980a1c12ec6908f9ecf78921f7e659d5ebd2d553bc07e42","kind":"lemma","schema_version":1,"statement":"[Lemma lem:nonrevup of arXiv:2511.10630, 'Cutoff for generalised Bernoulli--Laplace urn models'] Let $\varepsilon \in (0, 1]$. Suppose $\Phi_{\ast}^{(n)} \geqslant c_1$ for some constant $c_1 > 0$. For constant $\theta > 0$, let
    \begin{equation*}
        t_n = mn (t_{\textup{mix,\,single}}^{(n)}(1/\sqrt{n}) + \theta), \text{ and } t_n' = mn (t_{\textup{mix,\,single}}^{(n)}(1/\sqrt{n}) - \theta),
    \end{equation*}
    for $n \in \mathbb{N}$. Then there are constants $\theta, C > 0$ so that $\pi(\mathrm{Centre}(C)) \geqslant 1 - \varepsilon$, and the following hold.
    \begin{enumerate}[label=(\alph*)]
        \item For all $\mathbf{x} \in \Omega_n$ and $n$ large enough, we have
        \begin{equation*}
            \Ps{\mathbf{x}}{X^{(n)}_{t_n} \in {\mathrm{Centre}(C)}} > 1-\varepsilon.
        \end{equation*}
        \item We can find a sequence of starting states $(\mathbf{x}_n)_{n \geqslant 1}$ such that for $n$ large enough, we have
        \begin{equation*}
            \Ps{\mathbf{x}_n}{X^{(n)}_{t_n'} \in {\mathrm{Centre}(C)}} < \varepsilon.
        \end{equation*}
    \end{enumerate}","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T12:36:49.876249+00:00","domain":"probability theory","id":"claim_99850144ea416b5db7b6e4d386e31c736641dc7ba3d8a1f327c4189e5374ddeb","kind":"lemma","schema_version":1,"statement":"[Lemma lem : inj of arXiv:2609.00105, 'Weighted composition operators and classification of weighted Hardy spaces'] Assume that $\mathcal{H}_1$ and $\mathcal{H}_2$ are $2$-interpolating.    
     If $W_{\lambda,\varphi}^\ast:\mathcal{H}_1\to\mathcal{H}_2$ is injective, then: 
     \begin{enumerate}
         \item $\lambda:X_1\to \mathbb{C}$ does not vanish. 
         \item $\varphi: X_1\to X_2$ is an injective map. 
     \end{enumerate} 
     Moreover, when $\mathcal{H}_1$ consists of functions that are holomorphic on the interior of $X_1$ and continuous on $X_1\subseteq \mathbb{C}^{d_1}$, and $\mathcal{H}_2$ contains the constant function and the coordinate functions on $X_2\subseteq\mathbb{C}^{d_2}$, then $\lambda$ and $\varphi$ are holomorphic on the interior of $X_1$ and continuous on $X_1$.","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T11:15:34.488186+00:00","domain":"probability theory","id":"claim_998a21b511101448aca28dd766d04b61d7a2454526761f2c249bf77507bc9cfb","kind":"concept","schema_version":1,"statement":"[Proposition 9 (Riemann curvature of the ansatz metric) of arXiv:2609.03332, 'Singularity Models of Finite-Time K\"ahler-Ricci Flows'] For the metric \eqref{eq:ansatz-metric}, with $X, Y, Z, W$ basic horizontal, $\xi^* = \xi/H$ the unit Reeb field, and $\nu = \partial_s$:

	\emph{(i) Horizontal components.}
	\begin{equation}
		\begin{aligned}
			&\mathrm{Rm}_g(X, Y, Z, W) \;=\; \mathrm{Rm}_{g_s}(X, Y, Z, W) \\
			& \;+\; \frac{1}{4} \sum_{i,j=1}^r (q_i H + \kappa_i)(q_j H + \kappa_j) \Big( \pi^*g_i(X_i, Z_i)\, \pi^*g_j(Y_j, W_j) \;-\; \pi^*g_i(X_i, W_i)\, \pi^*g_j(Y_j, Z_j) \Big),
		\end{aligned}
	\end{equation}
	with $\mathrm{Rm}_{g_s}$ given by \eqref{eq:leaf-curvature}; moreover $\mathrm{Rm}_g(X, Y, Z, \xi^*) = 0$.

	\emph{(ii) Vertizontal components.}
	\begin{equation}
		\mathrm{Rm}_g(X, \xi^*, \xi^*, Y) \;=\; \frac{1}{4} \sum_{i=1}^r \frac{(q_i H)^2}{F_i^2}\; \pi^*g_i(X_i, Y_i) \;-\; \frac{H'}{2H} \sum_{i=1}^r \big( q_i H + \kappa_i \big)\, \pi^*g_i(X_i, Y_i) .
	\end{equation}

	\emph{(iii) Codazzi components.} The only non-vanishing components with exactly one $\nu$-slot are
		\begin{equation}
		\mathrm{Rm}_g(X, Y, \xi^*, \nu) \;=\; 2\, \mathrm{Rm}_g(X, \xi^*, Y, \nu) \;=\; \sum_{i=1}^r q_i H \left( \frac{F_i'}{F_i} - \frac{H'}{H} \right) \pi^*\omega_i(X_i, Y_i) ;
	\end{equation}
	in particular $\mathrm{Rm}_g(X, Y, Z, \nu) = 0$ and $\mathrm{Rm}_g(X, \xi^*, \xi^*, \nu) = 0$.

	\emph{(iv) Radial components.}
	\begin{align}
			\mathrm{Rm}_g(X, \nu, \nu, Y) &\;=\; -\sum_{i=1}^r F_i F_i''\; \pi^*g_i(X_i, Y_i), \nonumber \\

			\mathrm{Rm}_g(\xi^*, \nu, \nu, \xi^*) &\;=\; -\frac{H''}{H}, \\
			\mathrm{Rm}_g(X, \nu, \nu, \xi^*) &\;=\; 0 .\nonumber
	\end{align}

	Together with the symmetries of the curvature tensor, (i)--(iv) determine $\mathrm{Rm}_g$ completely. (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-26T20:50:30.568483+00:00","domain":"probability theory","id":"claim_998f172352fe9bd0ffa3c5d733f9daf88f63828ed1b67cbca93edef7f3e375db","kind":"concept","schema_version":1,"statement":"[Pro 6 of arXiv:2605.30779, '2605.30779'] Let \(\beta\in\{1,2\}\) and \(\{\xi_{\beta,j}\}_{j\ge1}\) be i.i.d.\ random variables, independent of \(\{a_{\beta,j}^{\Theta}\}_{j\ge1}\), with \(\xi_{\beta,j}^2\sim\chi_\beta^2\). Define the Airy-Green function
