{"assumptions":[],"created_at":"2026-10-26T19:29:23.338486+00:00","domain":"probability theory","id":"claim_9a3673dc17016300735023bb128a18dda29476df3920983fcc40c9212c97dfd6","kind":"theorem","schema_version":1,"statement":"[Prop 9 of arXiv:2512.05687, '$L^p$-Boltzmann-Gibbs principle \\ via Littlewood-Paley-Stein inequality'] Let $1<p<\infty$ and assume the function $V$ satisfies the condition
\begin{align} 
V\in C^2(\R) \quad \text{and} \quad V''\ge 0.
\end{align}
\noindent
{\rm (1)}  Then, for every $f=f(\eta)$ on $\mathcal{X}_{\ell,m}$, we have
\begin{align} 
c \|\nabla_{\La_\ell}^* D_\eta f\|_{L^p(\mu_{\ell,m})}  
\le \|(-L_{0,\ell})^{1/2}f\|_{L^p(\mu_{\ell,m})} \le 
C \|\nabla_{\La_\ell}^* D_\eta f\|_{L^p(\mu_{\ell,m})},
\end{align}
where $D_\eta f(\eta) = (D_\eta f(x,\eta))_{x\in \La_\ell}$ with 
$D_\eta f(x,\eta):= \partial_{\eta(x)} f(\eta)$ and 
$\|\nabla_{\La_\ell}^* D_\eta f\|_{L^p(\mu_{\ell,m})}$ denotes the
$L^p(\mu_{\ell,m})$-norm of the Euclidean norm of
\begin{align} 
\nabla_{\La_\ell}^* D_\eta f (\eta):= 
\big( \nabla^* D_\eta f(x,\eta)\big)_{x=-\ell+1}^{\ell-1}
\in \R^{2\ell-1},
\end{align}
that is,
\begin{align} 
|\nabla_{\La_\ell}^* D_\eta f(\eta)| := \Big( \sum_{x=-\ell+1}^{\ell-1}
(\nabla^* D_\eta f(x,\eta))^2\Big)^{1/2}.
\end{align}
Here, $c=c_p,C=C_p>0$ are universal constants, depending
only on $p$ and, in particular, being uniform in $\ell$ and $m$.  
Note that $-L_{0,\ell}$ is symmetric on $L^2(\mu_{\ell,m})$ and 
the operator $(-L_{0,\ell})^{1/2}$ is defined via its spectral decomposition.

\noindent
{\rm (2)} The same estimate as \eqref{eq:LPS-D} holds for
$(\mathcal{X}_{N,m}, \mu_{N,m},\T_N,L_0)$ replacing
$(\mathcal{X}_{\ell,m}, \mu_{\ell,m},\La_\ell,L_{0,\ell})$.
Note that $|\nabla_{\T_N}^* D_\eta f|^2$ is defined as in \eqref{eq:2.13-Q}.","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-28T02:47:21.633739+00:00","domain":"probability theory","id":"claim_9a3aeb6d9061b1895422ae5af456eed4c528277ba68063fa746e7cd288d73985","kind":"concept","schema_version":1,"statement":"[Corollary cor:r=2 of arXiv:2412.09145, 'Asymptotic expansions for normal deviations of random walks conditioned to stay positive'] Assume that the conditions of Theorem~(thm:lattice of the paper) hold with $r=2$. Then
\begin{align*}
&P_2(t)=\frac{2\theta_0}{\sigma}t\\
&P_3(t)=\frac{\theta_0m_3}{3\sigma^3}(t^4-5t^2+2)
+\frac{2\theta_1}{\sigma}(t^2-1),
\end{align*}
where $m_3:=\mathbf E X^3$ and 
\begin{align*}
&\theta_0=\sum_{u=1}^\infty U_1(u)\mathbf P(X<-u),\\
&\theta_1:=\sum_{u=1}^\infty U_1(u)\mathbf E[(-X-u);X<-u].
\end{align*} (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T20:25:39.087178+00:00","domain":"probability theory","id":"claim_9a3b78967b815f9f3e7266905dbba3344e606c38f1c5ecdbfb0d9c8fc95c29e6","kind":"concept","schema_version":1,"statement":"[Theorem thm:forward of arXiv:2606.12143, 'Continuous stochastic flows driven by white noise and their duals'] Fix $\alpha>0$. There exists a family of processes
    $$
    \mathcal S = \left\{\bigl(\mathcal S_{r,x}(a),\, x \ge r\bigr)\right\}_{(a,r) \in {\mathbb H}}
    $$
    such that, almost surely, the regularity properties~(item:R1 of the paper)--(item:R3 of the paper) in Definition~(def:flow of the paper) (restricted to ${\mathbb H}$) hold, and for each $(a,r)\in {\mathbb H}$, $(\mathcal S_{r,x}(a),\, x\ge r)$ is the unique strong solution to
    \begin{align}
        \mathcal S_{r,x}(a) = a + \int_r^x \frac{2}{\mathcal S_{r,u}(a)^{\alpha}}  \int_{{\mathbb R}} s^\alpha \mathbbm{1}_{\{0<s\le \mathcal S_{r,u}(a)\}} \mathcal{W}(\ensuremath{\mathrm{d}} s, \ensuremath{\mathrm{d}} u) + \frac{x-r}{2\alpha+1},
    \end{align}
    which is absorbed at $\tau_{(a,r)}:=\inf \{x\ge r\vee 0:\, \mathcal S_{r,x}(a)=0\}$. Moreover, this family is unique and continuous, and is referred to as the \textbf{polynomially self-repelling flow with index $\alpha$}. (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

