{"assumptions":[],"created_at":"2026-10-27T12:10:07.264398+00:00","domain":"probability theory","id":"claim_9a4ba96b0825aa6741889bfdb4637f340b7d8afa8cf7ba9138c6cc6e6365943d","kind":"concept","schema_version":1,"statement":"[Lemma bolloexpdecay of arXiv:2603.05467, 'Thresholds for colouring the random Borsuk graph'] Let $G$ be a connected, infinite, transitive, locally-finite graph with $|B_r(x)|\leq r^{(\log r)/100} $ for all $x\in G$, where $B_r(x)$ is the ball with radius $r$ w.r.t. the graph distance around $x$. Then, if we consider site percolation on $G$ with $p<p_c(G)$ there exists a constant $c=c(p,G)>0$ such that for all $n\in \mathbb{N}$
    \begin{equation*}
        \mathbb{P}_p(|C_x| \geq n)\leq e^{-cn},
    \end{equation*}
    where $C_x$ is the connected component of $x$. (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T20:53:00.844728+00:00","domain":"probability theory","id":"claim_9a4c3de7030e9fd5cc7da868bbabca7b88d916d955a5e8d24a32913efbd0125a","kind":"lemma","schema_version":1,"statement":"[Lemma lem:difffun of arXiv:2607.18635, 'Remainders of generalised Taylor expansions and a priori bounds for rough differential equ'] Let $f_1,\ldots,f_{\ell+1}:\mathbb{R}^n\to\mathbb{R}^n$ differentiable functions and $0\le j_1<\cdots<j_\ell<k$, $j_{\ell+1}:= k$. Define, for $i=1, \ldots,\ell+1$, the maps $F_i:\mathbb{R}^n\to\mathbb{R}^n$ as
		\begin{equation}
		F_{\ell+1}:=f_{\ell+1}, \qquad F_{i}:=(\nabla f_{i})\cdot F_{i+1}=\sum_{j=1}^n \frac{\partial f_i}{\partial y_j}\, F^j_{i+1}, \quad i=1,\ldots, \ell\,.
		\end{equation}
		Then we have
		\begin{align}
			&\int_{[0,1]_\geq^k}\left[\left(\prod_{i=1}^\ell\nabla f_i(u_{j_i})\right) F_{\ell+1}(z_1)- F_1(u_{j_1})\right]\, {\mathrm d} \mathbf{t}_{k-1}\nonumber
			\\ &=-\sum_{m=1}^\ell\sum_{j=j_{m}+1}^{j_{m+1}}\int_{[0,1]_\geq^{k+1}}\left(\prod_{i=1}^{m}
			\nabla f_i(u_{j_i})\right)\, \nabla F_{m+1}(u_j) \cdot z^{[1]}\, {\mathrm d} \mathbf{t}_{k}\,.

		\end{align}","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T22:57:49.909126+00:00","domain":"probability theory","id":"claim_9a515af5a2d6ce754f5b754ebc0230486282a87b3d902a2ceeab01e6c1fc36f4","kind":"theorem","schema_version":1,"statement":"[Theorem thm:ergodic by independ. of arXiv:2411.00663, 'Ergodicity and Mixing of invariant capacities and applications'] Let $(\Omega,\mathcal{F},V,T)$ be a capacity preserving system, where $V$ is an upper probability. Then the following statements are equivalent:
	\begin{longlist}
		\item $V$ is weakly mixing with respect to $T$;
		\medskip
		\item For any capacity preserving system $(\Omega',\mathcal{F}',V',T')$ with $V'$ being an ergodic upper probability, $V\times V'$ is ergodic with respect to $T\times T'$;
		\medskip
		\item $V\times V$ is ergodic with respect to $T\times T$.

	\end{longlist}","status":"unverified"}

