{"assumptions":[],"created_at":"2026-10-26T19:42:47.759464+00:00","domain":"probability theory","id":"claim_9abaa8566d82a6822fa5c6515772a2a1741227f225b120209b41b6892aad808d","kind":"lemma","schema_version":1,"statement":"[Lemma 6 of arXiv:2604.12233, 'An upper bound on the smallest singular value of dense random combinatorial matrices'] \cite[Lemma 2.1]{KwanSudakovTran}
    Let $w\in \R^n$ be a positive vector and $f: \{0,1\}^n\to \R$ be a function  such that 
    \begin{equation}
        |f(x_1, \dots, x_{i-1}, 1, x_{i+1}, \dots, x_n)-f(x_1, \dots, x_{i-1}, 0, x_{i+1}, \dots, x_n)|\le w_i,
    \end{equation}
    for all $x\in \{0,1\}^n$ and all $i\in [n]$. Suppose that $\eta$ is a random vector uniformly distributed over $\{0,1\}^n$ with exactly $d$ ones, where $1\le d \le n$.  Then
    \begin{equation*}
    \forall t \ge 0\qquad     \P(|f(\eta)-\E f(\eta)|\ge t)\le 2\exp\lr{-\frac{t^2}{8\sum_{i=1}^n w_i^2}}.
    \end{equation*}","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-26T19:38:57.116162+00:00","domain":"probability theory","id":"claim_9abfa5bc2db71899263496e59b2fb39b6c13598f29732a32f62af6313c4d7a5d","kind":"definition","schema_version":1,"statement":"[Definition 1 (Spectral gap) of arXiv:2604.04823, '2604.04823'] Let~$P$ be a Markov kernel on a Polish space~$\mathcal X$, reversible with respect to a probability measure~$\pi$. The spectral gap of~$P$ is
\begin{equation}
    \gap(P) = \inf_{f\in L^2(\pi)\setminus\set{0}} \frac{\mathcal E(f)}{\var_\pi(f)}\,,
\end{equation}
where
\begin{equation}
    \mathcal E(f) = \ip*{f , (I-P)f}_{L^2(\pi)} 
    = \frac{1}{2}\int_{\mathcal X}\int_{\mathcal X} \abs*{f(y)-f(x)}^2 P(x,dy)\pi(dx)\,.
\end{equation}","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T08:18:19.226026+00:00","domain":"probability theory","id":"claim_9ac019140572064f7a94855a90a20507d87e716a1d1d1ee53e68193a60cf6b7b","kind":"definition","schema_version":1,"statement":"[Definition 19 ($Obj(Mol)$ and $\rightarrow_M$) of arXiv:2608.29086, '2608.29086'] The objects $Obj(Mol)$ and the binary relation $\rightarrow_M$ on them are defined as follows:
\begin{enumerate}
\item $Obj(Mol)$ denotes the collection of all subsets of $MOL(M_0)$ (i.e., the \textit{power set} of $MOL(M_0)$):
\begin{equation*}
Obj(Mol):=Power(MOL(M_0)).
\end{equation*}
Elements of $Obj(Mol)$ are called \textit{molecule complices} (on $M_0$). 

Given $m=\{\psi_i\} \in Obj(Mol)$. Then, $m$ is expressed as a monomial, i.e.,
\begin{equation*}
m=\prod_{i}{\psi}_i  \in Obj(Mol),
\end{equation*}
using the multiplicative notation. The \textit{region $|m|$ of $m$} is defined by
\begin{equation*}
|m|:= \bigcup_{{\psi}_i \in m}\ |\ {\psi}_i|  \in REG(M_0).
\end{equation*}
``$Z$'' denotes the empty set of $Obj(Mol)$ (Figure \ref{figure2} (a) right), i.e., 
\begin{equation*}
Z:= \emptyset  \in Obj(Mol).
\end{equation*}

\item Given $m_1=\prod_ i {\psi}_i,\  m_2=\prod_i {\phi}_i \in Obj(Mol)$. The binary relation $\rightarrow_M$ between $m_1$ and $m_2$ is defined by 
\begin{multline*} 
\phantom{aaaaaaaa}m_1 \rightarrow_M m_2 \text{ if and only if} \\
\text{ for } \forall {\phi}_i \in m_2,\  \exists B_{\phi_i}  \subset m_1 \text{ such that } {\phi}_i =\sum_{\psi_j \in B_{\phi_i}} {\psi}_j.
\end{multline*}
\end{enumerate}","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T08:18:19.205370+00:00","domain":"probability theory","id":"claim_9ac23745a7c2c13ea7466a270a4267a13e6c28c4b4876d1061fda446225ff25f","kind":"concept","schema_version":1,"statement":"[Proposition 10 of arXiv:2608.28991, 'Jigsaw-CRL: Recovering Global Latent Causal Order from Fragmented Multi-Client Interventio'] For each client $k$, let $C_{k,i},C_{k,j}\in\cC_k$ be two blocks.
