{"assumptions":[],"created_at":"2026-10-27T20:53:00.819399+00:00","domain":"probability theory","id":"claim_9b1e26ca5c865143636ecd73aa0866c2feae090afe9a6623daa99ddc2e27f685","kind":"definition","schema_version":1,"statement":"[Definition def: approx MILT and SILT 2D of arXiv:2607.17393, 'Optimal Covariance Estimates for Schr\"odinger Semigroups with White Noise in $d=1,2$'] For $d\in\{1,2\}$, $\epsilon>0$, and $A\subset[0,t]^2$ a bounded Borel subset, the approximate self-intersection local time of a Brownian Bridge, $B_t^{x,x}$, is defined as 
\begin{align}

    \beta_A^\epsilon(B^{x,x}_t) =  \int_Ap_\epsilon(B_t^{x,x}(u)-B_t^{x,x}(v))dudv
\end{align}
(note that $\beta_A^\epsilon(B^{x,x}_t)= \beta_A^\epsilon(B^{0,0}_t)$).
For $A\subset[0,t]\times[0,s]$, the approximate mutual intersection local time of the Brownian Bridges $B_t^{x,x}$ and $\overline{B}_s^{y,y}$ is defined as
\begin{align}
    \alpha^\epsilon_A(B_t^{x,x},\overline{B}_s^{y,y}) = \int_Ap_\epsilon(B_t^{x,x}(u)-\overline{B}_s^{y,y}(v))dudv
\end{align}","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T12:27:11.366832+00:00","domain":"probability theory","id":"claim_9b1e9d7d2872bdd5c0535f82994f902947cc87ef99f2a83bec18c813191d4800","kind":"concept","schema_version":1,"statement":"[Proposition p:asymptotic variance test function 0 of arXiv:2605.22803, 'Persistence of asymptotic variance under transport:\\ from hyperfluctuation to stealthy hy'] Suppose that $\Phi$ is a locally square-integrable invariant random complex measure. Further, suppose that $f\in L^1$ is Fourier smooth with exponent $-d+\vartheta$ with $\lambda_d(f)=0$, where $\vartheta>0$. Then, as $r\to \infty$,
\begin{equation}
    \frac{\BV[\Phi(f_r)]}{r^d} = o(r^d)
\end{equation}
\begin{proof}
Choose $\Psi:= \Phi - \lim_{r\to\infty}\frac{\Phi(B_r)}{\lambda_d(B_r)} \cdot \lambda_d$. Note that the limit is taken with respect to the $L^2$-norm and is well defined by the $L^2$-ergodic theorem; see, e.g.,~[Kallenberg_2021]. We can see that $\Phi(f_r)=\Psi(f_r)$, as $\lambda_d(f_r) = r^d\lambda_d(f)=0$, $r>0$. Further, by construction, $\Psi$ is pseudo-ergodic and therefore beyond $(-d)$-uniform by Proposition~(p:pseudo ergodic of the paper). Now the assertion follows from Theorem~(t:asymptotic variance test function of the paper).
\end{proof} (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T07:29:27.958159+00:00","domain":"probability theory","id":"claim_9b1fa93a667f0350e5af4db9ca76c1d287c217b57fe2e9d29d35457238ec879e","kind":"theorem","schema_version":1,"statement":"[Theorem 8 of arXiv:2608.24675, 'Towards Liouville Quantum Gravity on fractals'] \begin{enumerate}[wide=0em,label={\rm (\roman*)},itemsep=.5em]
\item
 The sequence $\{h_{\ell}\}_{\ell\geq 1}$ converges both in $L^2(\Omega)$ and $\mathbb{P}$-a.s. to the FGFF $h$ on $K$. In particular,
 \begin{equation*}
    h\stackrel{d}{=}\sum_{k=1}^\infty\xi_{k}\lambda_{k}^{-\frac{d_S}{4}}\varphi_k
 \end{equation*}
and, $\mathbb{P}$-a.s., it holds that $h\in {H}^{-\varepsilon}(K)$ for any $\varepsilon>0$ and $h\notin L^2(K)$.
\item
    For every $u\in{H}^{-d_S/2}(K)$, the sequence $\{\langle h_{\ell},u\rangle\}_{\ell\geq 1}$ is a centered, $L^2$-bounded martingale with respect to the filtration $\{\mathcal F_\ell\}_{\ell\geq1}$, where
    \begin{equation*}
        \mathcal{F}_{\ell}:=\sigma(\{\xi_1,\ldots,\xi_{N_\ell}\}).
    \end{equation*}
    Moreover, the sequence converges in $L^2(\Omega)$ and $\mathbb{P}$-a.s. to a centered Gaussian random variable, denoted by $h\cdot u$. In particular, $\P$-a.s.
    \begin{equation*}
    h\cdot u=\sum_{k=1}^{\infty}\xi_{k}\lambda_{k}^{-\frac{d_S}{4}}\langle \varphi_k,u\rangle
    \end{equation*}
    and
    \begin{equation*}
        \E[(h\cdot u)^2]=\|u\|_{H^{-d_S/2}}^2.
    \end{equation*}

\end{enumerate}","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-26T20:54:34.581421+00:00","domain":"probability theory","id":"claim_9b20d724bdb4d9e4a014d8f4c8e114e4179ec39bac3a10b817ee59c2007d57a1","kind":"theorem","schema_version":1,"statement":"[Thm 10 of arXiv:2606.14917, 'The Ornstein--Uhlenbeck process on $\scr P_2$ \\with a volatility operator'] Let $\varphi\in C^2(\RR^d)$,  $\sup_{x\in\RR^d}|\partial_k\partial_l\varphi(x)|<\infty$, $1\leq k,l\leq d$.

