{"assumptions":[],"created_at":"2026-10-26T19:46:12.272127+00:00","domain":"probability theory","id":"claim_9b5f1c94b845c4312d574f7a0655b6763163485f7975e4f618c24aa470ca8687","kind":"concept","schema_version":1,"statement":"[Propo 14 (cf. Theorem 4.4 in \cite{haagerup_larsen00} and Theorem 4.17  in \cite{haagerup_schultz2007}) of arXiv:2604.22114, 'Free compressions of R-diagonal random variables and the semigroup of Brown measures'] Let $x  = uh\in \AA^\Delta$ be an $R$-diagonal random variable, with a Haar unitary $u$ and $h = |x| \geq 0$, and let $\mu_x$ be its Brown measure.   Assume that $\mu_h \ne \delta_0$. 
\begin{enumerate}[label = (\Roman*)]
\item
The measure $\mu_x$ is rotationally invariant. If $\mu_x(\{0\}) = 0$ then 
\[
\mathrm{supp}(\mu_x) = \{\lambda \in \bC: \| x^{-1}\|_2^{-1} \leq \lambda \leq \|x\|_2)\},
\]
where $\|x\|_2 := \sqrt{\varphi(x^\ast x)}$. Otherwise, 
$\mathrm{supp}(\mu_x) = \{\lambda \in \bC:  \lambda \leq \|x\|_2)\}.$
\item For an atom at zero, 
\begin{equation}
\mu_x(\{0\}) = \mu_h(\{0\}).
\end{equation}

\item
 $S_{h^2}$ is non-increasing on $\big(\mu_h(\{0\}) - 1, 0\big)$, and strictly decreasing unless $\mu_h$ is a point mass. Moreover,
\bal{
S_{h^2}\big(\big(\mu_h(\{0\}) - 1, 0\big)\big)
= \begin{cases}
\big(\|x\|_2^{-2}, \|x^{-1}\|_2^2\big), & \text{ if } \mu_h(\{0\}) = 0 \text{ and } \mu_h \neq \delta_c, \\
\big\{\|x\|_2^{-2}\big\}, & \text{ if } \mu_h = \delta_c \text{ for some } c > 0, \\
\big(\|x\|_2^{-2}, \infty \big), & \text{ if } \mu_h(\{0\}) > 0.
\end{cases}
}

\item The Brown measure $\mu_x$ satisfies the following equation:
\begin{equation}

\mu_x \Big(B\big(0, \big[S_{h^2}(t - 1)\big]^{-1/2}\big)\Big) = t 
\text { for } t \in (\mu_h(\{0\}), 1). 
\end{equation}
\end{enumerate} (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T14:04:39.788567+00:00","domain":"probability theory","id":"claim_9b601c16a6de8fb0cacf8aad4ab9e9a22e11196bbbc031c3faf75545611019ec","kind":"concept","schema_version":1,"statement":"[Theorem thm:tailrl-harmonic-decomposition of arXiv:2609.02987, 'Tail Likelihood Reinforcement Learning'] The population-level TailRL{} objective decomposes as a harmonic mixture of Best-of-$k$ objectives
\begin{align}
