		\qquad\text{equivalently}\qquad
		\sum_{n\ge0}\widehat B_n(t)\frac{z^{n}}{n!}=\frac{z}{2}\coth\frac{z}{2}\;e^{tz} .
	\end{equation}
	For $n\ge1$ this may be written as
	\begin{equation}
		\widehat B_n(t)=B_n(t)+\tfrac n2\,t^{n-1}\qquad(n\ge1),
