\end{enumerate}","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T21:30:14.143888+00:00","domain":"probability theory","id":"claim_9c4a8c94c716ad344cad48e007fe568967fbce4b55b45118907059c77330f135","kind":"concept","schema_version":1,"statement":"[Theorem thm:Gordonpos1 of arXiv:2608.18990, 'Proving Lehner's formulas via RDT -- indefinite and asymmetric scenarios'] ([Gordon85,Slep62])
 Let $X_{i}$ and $Y_{i}$, $1\leq i\leq n$, be two centered Gaussian processes which satisfy the following inequalities for all choices of indices
\begin{enumerate}
\item ${\mathbb E}(X_{i}^2)={\mathbb E}(Y_{i}^2)$
\item ${\mathbb E}(X_{i}X_{l})\leq {\mathbb E}(Y_{i}Y_{l}), i\neq l$.
\end{enumerate}
 Then
\begin{equation*}
{\mathbb E}(\min_{i} X_{i})\leq {\mathbb E}(\min_i Y_{i}) \quad  \Longleftrightarrow \quad {\mathbb E}(\max_{i} X_{i})\geq {\mathbb E}(\max_i Y_{i}).
\end{equation*} (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T12:27:11.331456+00:00","domain":"probability theory","id":"claim_9c4b0f5126106b721aecd555f5955855718e1b76c2dbe6271ff742beab53a581","kind":"definition","schema_version":1,"statement":"[Definition of arXiv:2605.22803, 'Persistence of asymptotic variance under transport:\\ from hyperfluctuation to stealthy hy'] Let $p\in[-d,\infty)$. Suppose that $\Phi$ is a locally square-integrable invariant random complex measure, i.e., $\BE[|\Phi(B_1)|^2]<\infty$. If
\begin{equation}
    \frac{\hat\beta_\Phi(B_\varepsilon)}{\varepsilon^d} = O(\varepsilon^p)
\end{equation}
as $\varepsilon\to 0$, then $\Phi$ is called $p$\textit{-uniform}.
Similarly, if
\begin{equation}
    \frac{\hat\beta_\Phi(B_\varepsilon)}{\varepsilon^d} = o(\varepsilon^p)
\end{equation}
as $\varepsilon\to 0$, then $\Phi$ is called \textit{beyond} $p$\textit{-uniform}.
Further, if $\hat\beta_\Phi(B_\varepsilon)=0$ for some $\varepsilon>0$, then $\Phi$ is called $\infty$\textit{-uniform with radius} $\varepsilon$. Note that $B_\varepsilon:=\{x\in\R^d:\|x\|<\varepsilon\}$ is the open ball of radius $\varepsilon$ around $0$.

For $p<\infty$, if $\Phi$ is $p$-uniform but not beyond $p$-uniform, then it is called \textit{solely} $p$\textit{-uniform}. Moreover, if $\Phi$ is $\infty$-uniform with radius $\varepsilon$ but not $\infty$-uniform with radius $\vartheta$ for any $\vartheta>\varepsilon$, then it is called $\infty$\textit{-uniform} \textit{with maximal radius} $\varepsilon$. 

Finally, a tensor-valued random complex measure is called (beyond) $p$-uniform (with radius $\varepsilon$) if all of its components are.","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T14:24:20.973816+00:00","domain":"probability theory","id":"claim_9c4be219072e3adaa124b41c5586826e7b1ab8d8a39823914f268e4af8be14bc","kind":"concept","schema_version":1,"statement":"[Cor limiting spectral density of arXiv:2508.13827, 'Surface sums in two-dimensional large-$N$ lattice Yang--Mills: Cancellations and explicit '] Let $\upbeta_0>0$ be as in (thm: sum over surfaces representation in 't hooft limit of the paper) and assume that $|\upbeta|\leq \upbeta_0\wedge 1/2$. Suppose $\ell$ is a simple loop and set $a_{\ell}=\area(\ell)$. Then $f_{a_\ell, \upbeta}$ is a probability density (in particular, it is non-negative\footnote{While the non-negativity of $f_{a_{\ell},\upbeta}$ is only shown for $|\upbeta|\leq \upbeta_0 \wedge 1/2$, we believe it should be true up to $|\upbeta|\leq 1/2$, but we will not pursue this direction in the present paper.}), and moreover, the following holds. Let $\mu_{\ell,N}$ denote the empirical spectral distribution of $Q_{\ell}$, that is,
    \[\mu_{\ell,N}(x)=\frac{1}{N}\sum_{i=1}^N \delta_{\lambda_{\ell,N}^i}(x),\] 
    where $(\lambda_{\ell,N}^i)_i$ are the complex-valued unitary eigenvalues of the unitary matrix $Q_{\ell}$ and $ \delta_y(\cdot)$ is the Dirac delta function at $y$.
    Then, 
    \begin{align*}
        \mu_{\ell,N} \xrightarrow[N\to\infty]{} \mu_{a_\ell},\qquad\text{weakly in probability,}
    \end{align*}
     where $\mu_{a_\ell}$ is a probability measure on the unit circle with density $f_{a_{\ell},\upbeta}(x)$  for all $x\in[0,2\pi)$ (under the standard parameterization of the unit circle). (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T21:41:19.328302+00:00","domain":"probability theory","id":"claim_9c4cfc137cd6e7d301e551fd8523778182fc1bab98ee38d3a17543e99f7d67f7","kind":"concept","schema_version":1,"statement":"[Theorem thm:heat_content of arXiv:2609.04045, 'Heat content and spectrum for subordinated sub-Laplacians'] Let $\Omega$ be a bounded set in $\mathbb{G}$ whose $C^\infty$ boundary $\partial \Omega$ does contain no characteristic points. Then,  the following holds.
     \begin{enumerate}[leftmargin=*]
     \item For $1<\alpha< 2$,
     \begin{align*}
         \lim_{t\to 0} \frac{\operatorname{Vol}(\Omega) - H^{(\alpha)}_\Omega(t)}{t^{\frac{1}{\alpha}}}=\frac{1}{\pi}\Gamma\left(1-\frac{1}{\alpha}\right)\operatorname{Per}_\mathcal{H}(\Omega).
     \end{align*}
     \item When $\alpha=1$,
     \begin{align*}
         \lim_{t\to 0} \frac{\operatorname{Vol}(\Omega) - H^{(\alpha)}_\Omega(t)}{t\log(1/t)}=\frac{1}{\pi}\operatorname{Per}_\mathcal{H}(\Omega).
     \end{align*}
     \end{enumerate}
    For $0<\alpha<1$ and for any bounded open set $\Omega$ satisfying $\operatorname{Per}^{(\alpha)}_{\mathcal H}(\Omega)<\infty$ we have
    \begin{align*}
        \lim_{t\to 0} \frac{\operatorname{Vol}(\Omega) - H^{(\alpha)}_\Omega(t)}{t}=\operatorname{Per}^{(\alpha)}_{\mathcal H}(\Omega).
    \end{align*} (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T10:30:28.830021+00:00","domain":"probability theory","id":"claim_9c4eccde329a8a9cc84e5292ed0f55c2453d2599a1810abb0e5c55dedb8bf21f","kind":"definition","schema_version":1,"statement":"[Definition 3 (\textsf{KSD elimination scale}) of arXiv:2609.02138, 'HyperMC: Multi-Fidelity Hyperparameter Tuning for Stochastic Gradient MCMC'] Fix $\varepsilon>0$ and $\delta\in(0,1)$.  For every $i\in\{1,\ldots,n\}$ define
\begin{equation}
\tau_i(\varepsilon,\delta)
:=\psi_{n,\delta}^{-1}\!\left(
\max\left\{\frac{\varepsilon}{4},\frac{\nu_i-\nu_1}{2}\right\}\right).
\end{equation}
In particular,
$\tau_1(\varepsilon,\delta)=\psi_{n,\delta}^{-1}(\varepsilon/4)$.","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T10:58:44.403163+00:00","domain":"probability theory","id":"claim_9c4f2ef4cd4a042bb9560f3044d72b57dcfa9e445cbd221c3f5218f983b019f7","kind":"definition","schema_version":1,"statement":"[Definition 6 of arXiv:2609.02842, 'Global Well-posedness and Asymptotic Analysis of a Damped Nonlinear Wave Equation with a C'] The energy functional associated with \eqref{asym1} is defined by
			\begin{equation}
				E(\vartheta (t),\vartheta_t(t)):=\frac12\|\vartheta_t(t)\|_{L^2(\varOmega)}^2+\frac12\|\nabla \vartheta (t)\|_{L^2(\varOmega)}^2+\frac1p\|\vartheta (t)\|_{L^p(\varOmega)}^p,
