{"assumptions":[],"created_at":"2026-10-27T08:18:19.204375+00:00","domain":"probability theory","id":"claim_9c662906b7f1e4d00dc539cdf2fa2e5540bce448e0ea764dd552080a5b875108","kind":"concept","schema_version":1,"statement":"[Proposition 1 of arXiv:2608.28991, 'Jigsaw-CRL: Recovering Global Latent Causal Order from Fragmented Multi-Client Interventio'] For $Z$ generated by Eq.~\eqref{eq:gloabl latent}, let $Z_k=(Z_{(i)})_{i\in O_k}$. Then
\begin{equation}
Z_k = \bA_k Z_k + E_k,
\end{equation}
where
\begin{align}

    \bA_k
    &=
    [\bA]_{O_k,O_k}
    +
    [\bA]_{O_k,M_k}
    (\bI-[\bA]_{M_k,M_k})^{-1}
    [\bA]_{M_k,O_k}, \\
    E_k
    &=
    E_{O_k}
    +
    [\bA]_{O_k,M_k}
    (\bI-[\bA]_{M_k,M_k})^{-1}
    E_{M_k}.
\end{align}
Moreover, $E_k$ has mean zero and covariance
\begin{equation}

    \bSigma_k
    =
    [\bSigma]_{O_k,O_k}
    +
    [\bA]_{O_k,M_k}
    (\bI-[\bA]_{M_k,M_k})^{-1}
    [\bSigma]_{M_k,M_k}
    (\bI-[\bA]_{M_k,M_k})^{-T}
    [\bA]_{O_k,M_k}^{T}.
\end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-26T19:45:07.265619+00:00","domain":"probability theory","id":"claim_9c685048894b1a7f45a85f26a8b4f38aa8b25c7a594528d3ced3a0c748d8771d","kind":"lemma","schema_version":1,"statement":"[Lemma 19 of arXiv:2604.19924, 'Fluctuation theory for spectrally negative Lévy processes killed by additive functionals'] For $q\geq0$, and $x\in(c,b)$,
					\begin{align}
						\lim_{n\to\infty}\E_x\bigg[e^{-q\tau_b^+-\int_{\R}L^y_{\tau_b^+}\nu_{n}(dy)};\tau_b^+<\tau_c^-\bigg]=\E_x\bigg[e^{-q\tau_b^+-\int_{\R}L^y_{\tau_b^+}{\nu_A}(dy)};\tau_b^+<\tau_c^-\bigg].
					\end{align}
					\begin{align}
						\lim_{n\to\infty}\E_x\bigg[e^{-q\tau_c^--\int_{\R}L^y_{\tau_c^-}\nu_{n}(dy)};\tau_c^-<\tau_b^+\bigg]=\E_x\bigg[e^{-q\tau_c^--\int_{\R}L^y_{\tau_c^-}{\nu_A}(dy)};\tau_c^-<\tau_b^+\bigg].
					\end{align}
					Additionally, for any bounded measurable function $f:\R\to\R$, we have
					\begin{align}
						\lim_{n\to\infty}\E_x\bigg[e^{-\int_{\R}L^y_{t}\nu_{n}(dy)}f(X_t)1_{\{
							t<\tau_c^-\wedge\tau_b^+\}}\bigg]=\E_x\bigg[e^{-\int_{\R}L^y_{t}{\nu_A}(dy)}f(X_t)1_{\{
							t<\tau_c^-\wedge\tau_b^+\}}\bigg].
					\end{align}","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T22:43:18.739663+00:00","domain":"probability theory","id":"claim_9c68b334aaffda9f37a1eea05af5bdaefc259ccccfa68a20f9deb95cc36eb8b6","kind":"definition","schema_version":1,"statement":"[Defi process_tree of arXiv:2609.02346, 'Regularised double shuffle relations for planar \AZVs{}'] Let $T\in\mathcal{PT}_{\N^*}$ be a planar rooted tree. Its \emph{process tree $\operatorname{pr}(T)$}

  is a planar rooted tree whose vertices are decorated by elements from $\mathcal{PT}_{\N^*}$ defined recursively on $\lin(T)$.
  \begin{itemize}
   \item If $\lin(T)=0$, then $T$ is a ladder tree (eventually empty) and we set $\operatorname{pr}(T):=\begin{picture}(10,5)(-2,-1)
\put(0,0){\circle*{2}}
\put(2,-2){$\tiny T$}
\end{picture}$.

   \item Assume that for $N\in\N$, $\operatorname{pr}(S)$ has been defined for all $S\in\mathcal{PT}_{\N^*}$ with $\lin(S)\leq N$. Let $T\in\mathcal{PT}_{\N^*}$ be a planar rooted tree with $\lin(T)=N+1$. Then $T$ is not a ladder tree and

   let $(a,b)$ be its minimal incomparable pair. We set
   $$\operatorname{pr}(T) := B_+^{T}\left(\operatorname{pr}(T_{a+b})\, \operatorname{pr}(T_{b}^{a})\, \operatorname{pr}(T_{a}^{b})\right).$$
  \end{itemize}
  For any tree $T\in\mathcal{PT}_{\N^*}$, we write $\delta_{\operatorname{pr}(T)}:V(\operatorname{pr}(T))\longrightarrow\mathcal{PT}_{\N^*}$ the decoration map of $\operatorname{pr}(T)$.","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T22:01:01.823219+00:00","domain":"probability theory","id":"claim_9c6aad4d9c49cbbe843db30007dc93cebba0c9d98ee666df3f5c9371cec8efcf","kind":"concept","schema_version":1,"statement":"[Lemma lem:elliptical_sum of arXiv:2609.00193, 'Provably Efficient Federated Reinforcement Learning with Linear Function Approximation and'] Let $\{x_t\}_{t=1}^T \subset \mathbb{R}^d$ with $\|x_t\|_2 \le 1$, and define
\[
V_t = \lambda I + \sum_{s=1}^{t} x_s x_s^\top,
\]
for some $\lambda > 0$. Then,
\[
\sum_{t=1}^T \min\bigl\{1, \|x_t\|_{V_{t-1}^{-1}}^2\bigr\}
\;\le\;
2 \log \frac{\det(V_T)}{\det(\lambda I)}
\;\le\;
2d \log\Bigl(1 + \frac{T}{d\lambda}\Bigr).
\] (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-26T20:24:59.504795+00:00","domain":"probability theory","id":"claim_9c6db79b8337936922f122b7fd95fa4f6ad71a60fcac22a713fd29f185b04db2","kind":"theorem","schema_version":1,"statement":"[Proposition 85 of arXiv:2605.10150, 'Rough path theory and an introduction to rough partial differential equations'] For all $y \in D(A)$ and all $s,t \in [0,T]$ we have
