{"assumptions":[],"created_at":"2026-10-26T19:36:04.994443+00:00","domain":"probability theory","id":"claim_9c6e85d87ccffb2d84a8ba39115f093a423ae2a12c78683a510bb2a981369c47","kind":"theorem","schema_version":1,"statement":"[Corollary 13 of arXiv:2604.01685, 'Probability with Measure\footnote{Lecture notes. University of Ljubljana.}'] Let $\AA\subset 2^\Omega$. If further $A\subset \Omega$, then \begin{equation}
	\sigma_\Omega(\AA)\vert_A=\sigma_A(\AA\vert_A);
	\end{equation}
	in particular, if $\AA$ is a $\sigma$-field on $\Omega$, then $\AA\vert_A$ is a $\sigma$-field on $A$.


	Besides, $\sigma_\Omega(\AA)=\cup \{\sigma_\Omega(\BB):\BB\text{ countable}\subset \AA\}$.","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T19:37:08.313610+00:00","domain":"probability theory","id":"claim_9c72696844659e50706a0cbf6a7776f46934c11e3d1bee570b54a40d3506fcbf","kind":"concept","schema_version":1,"statement":"[Theorema WPHs of arXiv:2608.30777, 'Inhomogeneous nonlinear Schr\"odinger equation \\ in Fourier-Lebesgue and modulation space'] Let $s\geq 0 $ and  $0<b< 1-s$. 
    \begin{enumerate}
        \item (subcritical) If 
        \begin{align*}
            1< \alpha < \begin{cases}
            1+ \frac{4-2b}{1-2s}\quad &\text{if} \quad s<1/2 \\ 
            \infty \quad &\text{if} \quad s \geq 1/2
        \end{cases},
         \end{align*} 
         then (equation INLS of the paper) is locally well-posed in $H^s.$ 
        \item (critical) If $s> 1/2$ and $\alpha=1+\frac{4-2b}{1-2s},$ then (equation INLS of the paper) is locally well-posed in $H^s$ and globally well-posed for the small data.
        \item (mildly ill-posed) If $s>0,\quad 0<b<1 \leq b+s<5/2, \; \alpha-1 \in 2\mathbb{N} \quad \text{and,\; if}\quad b+s \geq 1,\quad b+s \not \in \mathbb{N},$ then  (equation INLS of the paper) is mildly ill-posed in $H^s.$ 
    \end{enumerate} (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T07:00:46.812560+00:00","domain":"probability theory","id":"claim_9c74844758cfe02afaa7a7bba144079ea8cec61def9d3f8fff72f7b6326ff543","kind":"definition","schema_version":1,"statement":"[Defn 3 of arXiv:2608.12804, 'Scaling Limits for Ising Models on Inhomogeneous Random Graphs and Applications'] Let $T$ be a trace--class operator with eigenvalues $\lambda_i$, counted with algebraic multiplicity. Then the \emph{Fredholm determinant} of $I+T$ ($I$ being the identity operator) is defined as,
    \begin{equation*}
        \det(I+T) = \prod_i(1+\lambda_i)
    \end{equation*}","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-26T19:25:40.074053+00:00","domain":"probability theory","id":"claim_9c772f15843e77cbd178465493a534d3d5a39425cf8df91426fc633d0a5b895b","kind":"theorem","schema_version":1,"statement":"[Thm 2 of arXiv:2510.26216, 'A functional Breuer-Major theorem with Poisson noise'] Fix $d\in\NN^+$, $\alpha > \frac{1}{2} + \frac{1}{2d}$ and $\gamma_0>d_\alpha+1$. Suppose that there exist $C_\psi>0$ and $M_0\in \NN$ such that
    \begin{equation}  
        |\psi(x)| \le C_\psi (1 + |x|)^{-\alpha}
    \end{equation}
        for all $x\in\RR$ and
    \begin{equation}  
        \phi(x) \in \cC^{\gamma_0}_{M_0}.
    \end{equation}
    Then, the process $\mathcal{T}^{\ge d} Y_n$ converges in law to $\mu B$ in the Skorohod space $\mathbf{D}([0,1])$, where $(B_t)_{t \in [0,1]}$ is a standard Brownian motion, and
	\begin{equation} 
    	\mu^2 = \sum_{u\in\ZZ}\mathbf{E} [\mathcal{T}^{\ge d}\phi\left(X_0\right)\mathcal{T}^{\ge d}\phi\left(X_u\right)].
	\end{equation}","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T12:43:43.213537+00:00","domain":"probability theory","id":"claim_9c7b805a8e7715027409178b1f6820ad8a564fe4ca7e98ae904c6522594caf5f","kind":"lemma","schema_version":1,"statement":"[Lemma lem: bdry rem properties of arXiv:2506.21466, 'The Markov property for $\varphi^4_3$ on the cylinder'] For every $\varepsilon >0$, define the boundary remainder map ${\rm rem}^0_\varepsilon: \boldsymbol{\mathfrak B}^0 \times \mathcal L^0 \rightarrow \mathcal L^0$ for every $(\Xi^0,u) \in \boldsymbol{\mathfrak B}^0 \times \mathcal L^0$ by 
\begin{equation}
{\rm rem}^0_\varepsilon(\Xi^0, u)_t := - 4J_t^0 \overline{H}^* \Xi^{0,3}_t + {\rm reg}_{\mathbb T^2,\varepsilon}\Big( 4J_t^0 \overline{H}^* \Xi^{0,3}_t  + \ell^0_\infty(u)_t  \Big), \quad \forall t \geq 0.
\end{equation}
This a continuous linear map $\boldsymbol{\mathfrak B}^0 \times \mathcal L^0  \rightarrow \mathcal {L}^0$ and also as a map from $\boldsymbol{\mathfrak B}^0 \times \mathcal {L}^0_w \rightarrow \mathcal L^0_w$. It satisfies 
\begin{equation}
\ell^{0}_\infty({\rm rem}_{\varepsilon}(\Xi^0, u))={\rm reg}_{\mathbb{T}^2,\varepsilon} \left( \ell^{0}_\infty(\Xi^0,u) \right).
\end{equation} 
Furthermore, the map satisfies the following properties: there exists $C>0$  and for every $\varepsilon > 0$ there exists $C_\varepsilon > 0$ such that:
\begin{enumerate}
\item[(i)] $\|{\rm rem}^0_\varepsilon(\Xi^0, u)\|_{\mathcal {L}^0} \leq C (\| \Xi^0\|_{\boldsymbol{\mathfrak B}^0} + \|u\|_{\mathcal L^0})$.
