\end{equation}
at every $(t, a, n)$ with $a < h_{n+1}(t+1) - 1$.","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T19:33:43.755259+00:00","domain":"probability theory","id":"claim_9d2ab01be027cf46164829297b395810e393e4f7b4f5c775e5219335ac5dffb8","kind":"theorem","schema_version":1,"statement":"[Proposition prop_rainbow of arXiv:2609.02136, 'Gamma approximation and Poisson--Gaussian invariance principle on Poisson chaos'] For every $r\geq2$,

\noindent
\begin{align}
 \cum_r\bigl(H_m^{(q)}(c,t)\bigr)
\xrightarrow{m\to\infty} tc^r.

\end{align}

Consequently, with $P_t\sim\Pois(t)$,
\noindent
\begin{align}
 H_m^{(q)}(c,t)&\xrightarrow{\mathrm d}c(P_t-t),
 \notag\\
 \mathbb{E}\left[H_m^{(q)}(c,t)^r\right]
 &\longrightarrow\mathbb{E}\left[c(P_t-t)^r\right],
 \quad r\geq1.

\end{align}
Moreover,
\noindent
\begin{align}
 \mathcal J_4\bigl(H_m^{(q)}(c,t)\bigr)
 =qtc^4(1+3a_m)^{q-1}
 \xrightarrow{m\to\infty} qtc^4.

\end{align}","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T12:15:15.571225+00:00","domain":"probability theory","id":"claim_9d35d65f1b00cf91c91d059e394cab3b672cb98a05eeb3d58fc9690543c44e2e","kind":"lemma","schema_version":1,"statement":"[Lemma Diffusion Matrix Structure of arXiv:2507.12502, 'Quantitative Edge Eigenvector Universality for Random Regular Graphs: Berry-Esseen Bounds '] For $t \leq t_*$, the instantaneous covariance satisfies
