{"assumptions":[],"created_at":"2026-10-28T00:22:21.904273+00:00","domain":"probability theory","id":"claim_9dde0b1f21c8c450cc2ab0eed92062830309f7f3f91931b0d7e80d6b6211eed9","kind":"concept","schema_version":1,"statement":"[Proposition prop:transition_op_marginals of arXiv:2411.11425, 'Non-equilibrium steady states with a spatial Markov structure'] Let $\{\Lambda^n\}_{n\geq1}$ be two-sided Markov. For $a,b \in \mathbb{R}^+$ and $n \geq 1$, $i\in \{1,...,n\}$ we have

    \begin{equation}
    \begin{cases}
         \Lambda_{a,b}^{n,i+1} = P_{n,i+1} \Lambda_{a,b}^{n,i} \quad \text{ for } i\in \{1,...,n-1\}\\
         \Lambda_{a,b}^{n,i-1} = Q_{n,i-1}\Lambda_{a,b}^{n,i} \quad \text{ for } i\in \{2,...,n\}
    \end{cases}.
    \end{equation}

    Here $P_{n,i+1}: L^1(-\infty, \infty) \rightarrow L^1(-\infty, \infty)$ and $Q_{n,i-1}: L^1(-\infty, \infty) \rightarrow L^1(-\infty, \infty)$ are given by

    \begin{equation}
    \begin{cases}
        P_{n,i+1} f (x) = \int_{-\infty}^\infty f(y) \cdot \Lambda_{y,b}^{n-i,1}(x) dy\\
        Q_{n,i-1} f (x) = \int_{-\infty}^\infty f(y) \cdot \Lambda_{a,y}^{i-1,i-1}(x) dy 
    \end{cases}.
    \end{equation}

    \begin{proof}

        It is straightforward to show that transition operators $P_{n,i+1}$ and $Q_{n,i-1}$ map $L^1(-\infty, \infty)$ functions to $L^1(-\infty, \infty)$ functions. Indeed, let $f \in L^1(-\infty, \infty)$, then

        \begin{equation}
            \int_{-\infty}^\infty |P_{n,i+1} f(x)| dx \leq \int_{-\infty}^\infty \int_{-\infty}^\infty |f(y)| \cdot |\Lambda_{y,b}^{n-i,1}(x)| dy dx \leq ||f||_1< \infty.\
        \end{equation}

        A similar argument can be used to show $Q_{n,i-1}$ map $L^1(-\infty, \infty)$ functions to $L^1(-\infty, \infty)$.\\

        \noindent
        We now show that $\Lambda_{a,b}^{n,i+1} = P_{n,i+1} \Lambda_{a,b}^{n,i}$. On can use an analogous proof to show $ \Lambda_{a,b}^{n,i-1} = Q_{n,i-1}\Lambda_{a,b}^{n,i}$. \\

        \noindent
        We use the notation $\Lambda_{a,b}^{n,(i,i+1)}$ to denote the joint distribution of $\Theta_i$ and $\Theta_{i+1}$, i.e.

        \begin{equation}
            \Lambda_{a,b}^{n,(i,i+1)}(\theta_{i},\theta_{i+1}) = \int_{-\infty}^{\infty} ... \int_{-\infty}^{\infty}  \Lambda_{a,b}^{n}(\theta_1,...,\theta_n) d\theta_1,...,d\theta_{i-1} d\theta_{i+2}...d\theta_n.
        \end{equation}

        \noindent
        We write $ \Lambda_{a,b}^{n,(i,i+1)}(y,\theta_{i+1}|\Theta_{i} = y)$ for the joint distribution under the condition $\Theta_{i}=y$. Suppose we have 
        \begin{align}

             \Lambda_{a,b}^{n,(i,i+1)}(y,\theta_{i+1}|\Theta_{i} = y) = \Lambda_{y,b}^{n-i,1}(\theta_{i+1}),
        \end{align}

        then the result follows directly:

        \begin{align}
            \Lambda_{a,b}^{n,i+1}(\theta_{i+1}) &= \int_{-\infty}^{\infty}\Lambda_{a,b}^{n,i}(y)  \cdot \Lambda_{a,b}^{n,(i,i+1)}(y,\theta_{i+1}|\Theta_{i} = y) dy\\
            &= \int_{-\infty}^{\infty}\Lambda_{a,b}^{n,i}(y)  \cdot \Lambda_{y,b}^{n-i,1}(\theta_{i+1}) dy\nonumber\\
            &= P_{n,i+1}  \Lambda_{a,b}^{n,i}(\theta_{i+1}) \nonumber.
        \end{align}

        To prove (equation eq:intermediate_step_trans_op of the paper) we compute $\Lambda_{a,b}^{n,(i,i+1)}(y,\theta_{i+1}|\Theta_{i} = y)$,

        \begin{align}
            \Lambda_{a,b}^{n,(i,i+1)}(y,\theta_{i+1}|&\Theta_{i} = y) \nonumber\\ 
            =& \int_{-\infty}^\infty ...\int_{-\infty}^\infty \Lambda_{a,b}^n(\theta_1,..., \theta_{i-1}, y, \theta_{i+1},...,\theta_n |\Theta_{i} = y) d\theta_1...d\theta_{i-1}d\theta_{i+2}...d\theta_n\\
            =& \int_{-\infty}^\infty ...\int_{-\infty}^\infty \Lambda_{a,y}^{i-1}(\theta_1,..., \theta_{i-1}) \cdot \Lambda_{y,b}^{n-i}(\theta_{i+1},..., \theta_n) d\theta_1...d\theta_{i-1}d\theta_{i+2}...d\theta_n\nonumber\\
            =& \int_{-\infty}^\infty ...\int_{-\infty}^\infty \Lambda_{y,b}^{n-i}(\theta_{i+1},..., \theta_n) d\theta_{i+2}...d\theta_n\nonumber\\
            &=\Lambda_{y,b}^{n-i,1}(\theta_{i+1}).\nonumber
        \end{align}
    \end{proof} (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-26T19:30:52.746028+00:00","domain":"probability theory","id":"claim_9ddf41399f59b7a41f0fef9de135e8d9b45ffa8b520acb33489c696f8953e78e","kind":"definition","schema_version":1,"statement":"[Define 4 of arXiv:2506.10522, 'On the Law of the Iterated Logarithm for $m$-dependent stationary random variables under s'] A  sub-linear expectation $\mbE$ on $\mathcal{H}$  is a function $\mbE: \mathcal{H}\to \overline{\mathbb R}$ satisfying the following properties: for all $X, Y \in \mathcal H$, we have
\begin{description}
  \item[\rm (a)]  Monotonicity: If $X \ge  Y$ then $\mbE [X]\ge \mbE [Y]$;
\item[\rm (b)] Constant preserving: $\mbE [c] = c$;
\item[\rm (c)] Sub-additivity: $\mbE[X+Y]\le \mbE [X] +\mbE [Y ]$ whenever $\mbE [X] +\mbE [Y ]$ is not of the form $+\infty-\infty$ or $-\infty+\infty$;
\item[\rm (d)] Positive homogeneity: $\mbE [\lambda X] = \lambda \mbE  [X]$, $\lambda\ge 0$.
 \end{description}
 Here $\overline{\mathbb R}=[-\infty, \infty]$, $0\cdot \infty$ is defined to be $0$. The triple $(\Omega, \mathcal{H}, \mbE)$ is called a sub-linear expectation space. Given a sub-linear expectation $\mbE $, let us denote the conjugate expectation $\mbe$of $\mbE$ by
$$ \mbe[X]:=-\mbE[-X], \;\; \forall X\in \mathcal{H}. $$","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T05:50:44.869661+00:00","domain":"probability theory","id":"claim_9ddfaf1d34cac96f73e4f36615ae77269bb7b6b9a67938cda352932e7c7cd682","kind":"theorem","schema_version":1,"statement":"[Corollary 7 (Finite-complexity operator-norm bridge) of arXiv:2607.16724, 'Algebraic Transfer for Operator-Valued Gaussian Chaoses: Oriented Schatten Profiles and Si'] Let $m\ge1$ and $K\in\cK_m$.  Put
\begin{equation}

 A_\infty(K):=\Prof_{m,\infty}(K),
 \qquad
 R_{\mathrm{eff}}(K):=
 \begin{cases}
 \norm K_{\cK_m}^{\,2}/A_\infty(K)^2,&K\ne0,\\
 1,&K=0.
\end{cases}
\end{equation}
The decoupled evaluator $\cT_K^{(m)}$ is the common extension obtained from
algebraic approximation in $\cK_m$.  There are constants
$C_m^{\mathrm{op}},A_m^{\mathrm{op}}<\infty$, depending only on $m$, such
that for every $1\le p<\infty$,
\begin{equation}

 \norm{\cT_K^{(m)}}_{L^p(\Omega;\cL(\cC,\cE))}
 \le C_m^{\mathrm{op}}
 \bigl(p+\log(e+R_{\mathrm{eff}}(K))\bigr)^{m/2}A_\infty(K).
\end{equation}
If
\[
 \cH_1=\cdots=\cH_m=\cH_{\C}
\]
and $K$ is invariant under permutations of its stochastic legs, then the
same-field extension $I_m(K)$ satisfies
\begin{equation}

 \norm{I_m(K)}_{L^p(\Omega;\cL(\cC,\cE))}
 \le A_m^{\mathrm{op}}
 \bigl(p+\log(e+R_{\mathrm{eff}}(K))\bigr)^{m/2}A_\infty(K).
\end{equation}
In the same-field assertions, $A_\infty(K)$ and
$R_{\mathrm{eff}}(K)$ are computed after regarding the stochastic legs as
labelled copies.  Moreover, for every $u\ge1$,
\begin{equation}

 \Prob\left(
  \norm{\cT_K^{(m)}}_{\cL}>
  C_m^{\mathrm{op}}
  \bigl(u+\log(e+R_{\mathrm{eff}}(K))\bigr)^{m/2}A_\infty(K)
 \right)\le e^{-u}.
\end{equation}
In the symmetric same-field case,
\begin{equation}

 \Prob\left(
  \norm{I_m(K)}_{\cL}>
  A_m^{\mathrm{op}}
  \bigl(u+\log(e+R_{\mathrm{eff}}(K))\bigr)^{m/2}A_\infty(K)
 \right)\le e^{-u}.
\end{equation}
For $p\ge2$, the decoupled evaluator also satisfies
\begin{equation}

 A_\infty(K)
 \le\norm{\cT_K^{(m)}}_{L^2(\Omega;\cL)}
 \le\norm{\cT_K^{(m)}}_{L^p(\Omega;\cL)}.
\end{equation}

If
\begin{equation}

 D_*(K):=\max\left\{1,\max_{S\subset[m]}\rank\Flat_S(K)\right\}<\infty,
\end{equation}
then
\begin{equation}

 1\le R_{\mathrm{eff}}(K)\le D_*(K),
\end{equation}
so all four upper bounds remain valid with
$R_{\mathrm{eff}}(K)$ replaced by $D_*(K)$.  All constants are independent
of the participating Hilbert spaces, support dimensions, and cut ranks.","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T21:25:41.609736+00:00","domain":"probability theory","id":"claim_9de03568fa8c9cbd6d84af71354927fb905e75f311accc4779e780e979ece001","kind":"lemma","schema_version":1,"statement":"[Lemma lem:conditioned-power of arXiv:2608.15515, '\LARGE Weak-Type Bounds for Convolution on the Boolean Hypercube'] Under $\mathbb P^\zeta=\mathbb P(\,\cdot\mid V_T=\zeta)$, the predictable generator on
$[\theta,T_{\mathrm o}]$ is
$\mathcal L_t^{0,\zeta}+\1_{\{t\leq\tau\}}\mathcal B_t^\zeta$, where
\begin{equation}
 \mathcal B_t^\zeta h(x,y)
 =\sum_{S_i(t,x)>0}\delta_i(t,x)S_i(t,x)\Delta_i^yh(x,y)
 +\sum_{S_i(t,x)\leq0}r_{t,i}^\zeta(x)\delta_i(t,x)S_i(t,x)
       \Delta_i^yh(\sigma_i x,y).
\end{equation}
The power coefficients satisfy
\begin{equation}
 \left|\delta_i(t,x)\left(
