{"assumptions":[],"created_at":"2026-10-27T23:06:42.722257+00:00","domain":"probability theory","id":"claim_9e02c351f0930fb78b718a6f0dc6de7f9c0b63cb9c73b028cfa448aa1c918c64","kind":"lemma","schema_version":1,"statement":"[Lemma star of arXiv:2411.04157, 'Stochastic homogenization of dynamical discrete optimal transport'] Let $\eta$ be a function in $C^0(\mathbb{R}^n)$ and $J^\varepsilon$ a sequence of vector fields in $\mathbb{R}^{\mathcal E_{\varepsilon}}_a$. We define their product $\eta \pentagram J\in \mathbb{R}^{\mathcal E_{\varepsilon}}_a$  by
\begin{align*}
    (\eta\pentagram J) (x,y)=\frac{\eta(x)+\eta(y)}{2}J(x,y).
\end{align*}
Then:
    \begin{enumerate}

      \item Modulation:
      Let $ \iota J^\varepsilon\stackrel{*}{\rightharpoonup} \nu$ vaguely. Then
      \begin{align*}
       \iota(\eta \pentagram J^\varepsilon) \stackrel{*}{\rightharpoonup} \eta \nu \text{ vaguely.}
      \end{align*}
      \item Convergence of divergence:
        Let $\eta\in C^1(\mathbb{R}^n)$. Let $J^\varepsilon\stackrel{*}{\rightharpoonup} \nu$ and $\dive \iota  J^\varepsilon\stackrel{*}{\rightharpoonup} \dive \nu$ vaguely. Then
\begin{align*}
    \dive \iota (\eta\pentagram J^\varepsilon) \stackrel{*}{\rightharpoonup} \dive (\eta \nu) \text{ vaguely.}
\end{align*}
    \end{enumerate}","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T19:35:19.872177+00:00","domain":"probability theory","id":"claim_9e059b56c6bda27ce14fb94f6254817a0baf7aeeb52377a0ec0b3b815f763804","kind":"concept","schema_version":1,"statement":"[Proposition prop:sobolev_curvature of arXiv:2608.24963, 'Why and When Neural Networks Improve Local Approximation in Optimization'] (Adapted from Proposition~3.1 in [Taminiau2025Arxiv2502].)
Let $m_\theta:\mathbb{R}^n\to\mathbb{R}$ be twice continuously differentiable. Fix $z\in\mathbb{R}^n$ and $h>0$ such that
\begin{equation}
m_\theta(z)=f(z),\qquad m_\theta(z+h e_\ell)=f(z+h e_\ell),\ \ell=1,\dots,n.
\end{equation}
Define $g_h(z)$ by forward differences (equation eq:fd_forward of the paper). Then there exist $\zeta_1,\dots,\zeta_n\in[0,1]$ such that
\begin{equation}
\left\lVert g_h(z)-\nabla m_\theta(z) \right\rVert_2^2=\frac{h^2}{4}\sum_{\ell=1}^n\left([\nabla^2 m_\theta(z+h\zeta_\ell e_\ell)]_{\ell\ell}\right)^2.
\end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

