{"assumptions":[],"created_at":"2026-10-28T02:04:41.050731+00:00","domain":"probability theory","id":"claim_9f55e2ee8b846ab7de8ab846f3379d8fa70d37fe2069732c85fc5c9d9c115b14","kind":"concept","schema_version":1,"statement":"[Theorem th:diff_reg of arXiv:2412.04032, 'Cutoff for the mixing time of the Facilitated Exclusion Process'] For all $\varepsilon \in (0,1)$, for all sequence $K=K(N)$ such that for all $N$, $N/2 < K < N$, 
\begin{itemize}
\item If $\frac{\log (2K-N)}{\log K} \longrightarrow 0$ (e.g. $K = N/2 + \log N$), then 
\eqs{\left|\tau^{\textsc{fep}}_{N,K}(\varepsilon)-\frac{1}{\pi^2}K^2 \log K\right| =\mathcal{O}_\varepsilon\left( N^2 \max\left(\log\log N,  \log (2K-N)\right)\right).}
\item If $\frac{\log (2K-N)}{\log K} \longrightarrow \alpha \in (0,1)$ (e.g. $K = N/2 + N^\alpha$), then
\eqs{\max\Big(\frac{1-\alpha}{\pi^2},\frac{\alpha}{8\pi^2}\Big) \le \varliminf\limits_{N \to \infty} \frac{\tau^{\textsc{fep}}_{N,K}(\varepsilon)}{K^2 \log K} \le \varlimsup\limits_{N \to \infty} \frac{\tau^{\textsc{fep}}_{N,K}(\varepsilon)}{K^2 \log K} \le \frac{1-\alpha}{\pi^2} + \frac{\alpha}{8 \pi^2}.}
\item If $\frac{\log (2K-N)}{\log K} \longrightarrow 1$ and $(N-K)\to \infty$  (e.g. $K/N \longrightarrow \rho \in (\frac12,1)$), then, setting $P=\min(2K-N,N-K)$,
\eqs{\left|\tau^{\textsc{fep}}_{N,K}(\varepsilon)- \frac{1}{8\pi^2}K^2 \log P\right| =\mathcal{O}_\varepsilon \left(K^2\left(1+\log\frac{K}{2K-N}\right)\right).}
\end{itemize} (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T18:58:38.058887+00:00","domain":"probability theory","id":"claim_9f59616143d861a4bcb38a8d453447572f8d28d77ee7e85ba4f936c5bef6d732","kind":"concept","schema_version":1,"statement":"[Theorem thm:Main of arXiv:2606.19313, 'Stability of Khintchine-type inequalities via log-monotonicity'] Let $X$ be a symmetric random variable, $X_1, X_2, \ldots, X_n$ iid copies of $X$ and $r_k=r_k(X)$. Let $(a_1, a_2, \ldots, a_n)\in\mathbb{R}^n$ and $p\geq 2$ be an even integer. Then the following bounds hold for the sum $S=\sum_ka_kX_k$. Moreover, the constants are optimal.
\begin{enumerate}
\item If $(r_k)$ is log-concave, then $\big( \frac{\| X \|_p}{\| X \|_2}\big) \| S \|_2\leq \| S \|_p\leq \gamma_p\| S \|_2$;\\

\item If $(r_k)$ is log-convex, then $\gamma_p\| S \|_2\leq \| S \|_p\leq \big( \frac{\| X \|_p}{\| X \|_2}\big) \| S \|_2$.
\end{enumerate} (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-26T20:57:07.298981+00:00","domain":"probability theory","id":"claim_9f67b7e0b62b9e7989b3d18080c65af0872f747f6a9cfc0db488883c347e1931","kind":"concept","schema_version":1,"statement":"[Theorem 8 (Main theorem) of arXiv:2606.23383, 'Near-Lipschitz stability of the Kim--Milman flow map'] Suppose $\mu$ satisfies \eqref{theta} and $\nu \in \cP_2(\R^d)$ with $\mathsf m_2(\mu),\mathsf m_2(\nu) \leq M$. In addition, let $\mathsf C_\mu \geq 0$ be such that for all $0\leq s\leq t$, it holds that
