{"assumptions":[],"created_at":"2026-10-28T02:56:14.341750+00:00","domain":"probability theory","id":"claim_a053e65fe98306211eeebe1430330851d01fd0c97f2633e3c589fa150a0bd696","kind":"theorem","schema_version":1,"statement":"[Them Markov_stationnaire of arXiv:2412.10001, 'On the Markov transformation of Gaussian processes'] Consider an interval  $T \subset \mathbb{R}$  and  a continuous positive semi-definite kernel $K : T \times T \to \mathbb{R}$ with constant variance function equal to $1.$ We denote by $P$ the centered Gaussian process with covariance function $K.$ For every $(s,t,h^*) \in T \times T \times \mathbb{R}_+^*$, we set  $$C_{s,t}(h^*) := \ens{(v,h)}{v \in [s,t[, v +h \in [s,t], h \in ] 0, h^*]}.$$

		\begin{enumerate}
			\item Assume $\alpha^K$ is well defined, continuous and for every $ s<t \in T \times T$
			\begin{equation}
				 \sup_{(v,h) \in C_{s,t}(h^*)} \left|L^K_v(h) - \alpha^K(v)\right| \xrightarrow[h^* \to 0^+]{} 0.
			\end{equation} 
			Then  $P_{\alpha^K}$ is the strong local Markov transform of $P.$
			\item Assume, for every $s<t  \in T \times T$ 
			\begin{equation}
				\inf_{(v,h) \in C_{s,t}(h^*)} L^K_v(h) \xrightarrow[h^* \to 0^+]{} + \infty.
			\end{equation}
		Then $P_{+\infty}$ is the strong local Markov transform of $P.$
		\end{enumerate}","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T05:47:53.352354+00:00","domain":"probability theory","id":"claim_a054813e9f52faef99c1afa684bb19b7080ab27c15b842a9d49cbd61c8230019","kind":"theorem","schema_version":1,"statement":"[Theorem 5 of arXiv:2607.15903, 'Uniqueness for nonlinear Fokker-Planck equations with general diffusion terms and their as'] Assume that \textbf{Hypothesis (\MakeUppercase{\romannumeral 1})} holds. Let $u_{1}, u_{2} \in L^{1}((0,T)\times \mathbb{R}^{d})\cap L^{\infty}((0,T)\times \mathbb{R}^{d})$ be two distributional solutions to (\ref{1}) in $(0,T)\times \mathbb{R}^{d}$ such that $u_{1}-u_{2} \in L^{\infty}((0,T);H^{-1})$ and
 \begin{equation}
     \displaystyle\lim_{t \rightarrow 0} \displaystyle \esssup_{s \in (0,t)}\left | \left ( u_{1}(s)-u_{2}(s),\varphi  \right )_{2}\right |=0, \quad  \forall \varphi \in C^{\infty}_{0}(\mathbb{R}^{d}). 
 \end{equation}
 Then, $u_{1}\equiv u_{2} $.","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-26T19:29:00.763830+00:00","domain":"probability theory","id":"claim_a05821f529ce72ebf53f1ad837e703c5a5d11543aff70aaf4ff1980ab290a127","kind":"theorem","schema_version":1,"statement":"[Theorem 9 (Well-posedness of RDEs) of arXiv:2512.04646, '\textbf{Canonical Rough Path over Tempered Fractional Brownian Motion: Existence, Construc'] Let $H > 1/4$, $\lambda > 0$,
$f \in C^3_b(\mathbb{R}^d,\mathcal{L}(\mathbb{R}^m,\mathbb{R}^d))$,
and $y_0 \in \mathbb{R}^d$. The rough differential equation
\begin{equation}

dY_t = f(Y_t)\,d\mathbf{B}_{H,\lambda}(t), \qquad Y_0 = y_0,
\end{equation}
admits a unique solution
$Y \in \mathscr{C}^p([0,T],\mathbb{R}^d)$ for any $p > 1/H$.
The solution map $(y_0,f,\mathbf{B}_{H,\lambda})\mapsto Y$ is
locally Lipschitz continuous.","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-26T20:54:53.437201+00:00","domain":"probability theory","id":"claim_a05822b2c5237c6264ae30314cb0ea2863f59d14dbb41cf0e08d53201c26c0d2","kind":"theorem","schema_version":1,"statement":"[Theorem 8 of arXiv:2606.15178, 'The distribution of the de Moivre experiment'] Let $X\sim\mathcal{B}^{(s)}(n,p)$ and let $x_i=\sum_{l=1}^{s}l^ip^lq^{s-l}=E(X_1^i)$. Then, for every $r\geq1$,
	\begin{equation}
		\kappa_r(X)=n\sum_{k=1}^{r}(-1)^{k-1}(k-1)!\,B_{r,k}\big(x_1,x_2,\ldots,x_{r-k+1}\big), \quad \text{ for } p\neq q, 
	\end{equation}
	and
	\begin{equation}
		\kappa_r(X)=n\sum_{k=1}^{r}(-1)^{k-1}(k-1)!\,p^{ks}\,B_{r,k}\Big(\sum_{l=1}^{s}l,\sum_{l=1}^{s}l^2,\ldots,\sum_{l=1}^{s}l^{r-k+1}\Big), \quad \text{ for } p=q.
	\end{equation}","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T11:43:45.388799+00:00","domain":"probability theory","id":"claim_a05c3be46c9ca7c57140bdf4c37551061817125e292b2bedb0b4b93dcf478e1c","kind":"lemma","schema_version":1,"statement":"[Lemma 13 of arXiv:2609.04139, 'The conformally invariant metric on CLE$_4$ II:\\ existence of geodesics'] Let $\alpha \subset \partial \BD$ be a deterministic connected arc. Let $\tau$ be a stopping time for the filtration generated by 
	\begin{equation*}
		\left(\SCB_t(\alpha; D_{\Gamma_\BD}^\BD), \Gamma_\BD|_{\SCB_t(\alpha; D_{\Gamma_\BD}^\BD)}\right)_{t \ge 0}. 
	\end{equation*}
	Let $\{V_j\}_j$ denote the connected components of $\BD \setminus \SCB_\tau(\alpha; D^\BD_{\Gamma_\BD})$.
	Then, there is a coupling $\{(\Gamma_\BD\vert_{V_j}, D^{V_j}_{\Gamma_\BD \vert_{V_j}})\}_j$ such that, conditionally on $\SCB_\tau(\alpha; D^\BD_{\Gamma_\BD})$, the $(\Gamma_\BD\vert_{V_j}, D^{V_j}_{\Gamma_\BD \vert_{V_j}})$'s are independent and have the law of $(\Gamma_{V_j}, D^{V_j}_{\Gamma_{V_j}})$ respectively. Moreover,
		\begin{itemize}
	\item For all $j$, for all $\SCL_1, \SCL_2 \in \Gamma_\BD|_{V_j}$, we have $D_{\Gamma_\BD}^\BD(\SCL_1, \SCL_2)\le D_{\Gamma_\BD|_{V_j}}^{V_j}(\SCL_1, \SCL_2)$.
	\item For all $j$, for all $\SCL \in \Gamma_\BD|_{V_j}, \ t \in [0, D_{\Gamma_\BD}^\BD(\SCL, \partial V_j)]$, we have $\SCB_t(\SCL; D_{\Gamma_\BD}^\BD) = \SCB_t(\SCL; D_{\Gamma_\BD|_{V_j}}^{V_j})$.
	\end{itemize}","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T16:57:16.068254+00:00","domain":"probability theory","id":"claim_a05cae5cb584e3accd361f75ae913fa048c7ea1636e01ff5e16d27a2f7b8951b","kind":"lemma","schema_version":1,"statement":"[Lem elemlemma of arXiv:2506.15500, 'On extinction and survival of the Bak-Sneppen model on arbitrary graphs'] Let $X_n$ be an ergodic Markov chain on a finite state space $\mathcal{S}$ with the stationary distribution $\pi$; assume that $0$ is one of the states. Suppose there is a non-negative function $f:\mathcal{S}\to{\mathbb R}$ such that 
\begin{align}
\begin{split}
f(0)&=0;\\    
\max_{x\in\mathcal{S}: \ p_{0x}>0} f(x)&=c_0;\\
|f(X_{n+1})-f(X_n)|&\le C;\\
{\mathbb E}(f(X_{n+1})-f(X_n)\mid X_n=x)&<-\varepsilon,\quad x\ne 0,
\end{split}
\end{align}
for some $\varepsilon>0$, $c_0>0$, and $C>0$.
Then for some $c_1,c_2>0$ depending on $c_0,C,\varepsilon$ only,
\begin{align}
\pi(A_k)\le c_1 e^{-c_2 k},
\quad\text{where }A_k=\{x\in\mathcal{S}:\ f(x)>k\},\ k>0.  
\end{align}","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-26T19:28:04.865940+00:00","domain":"probability theory","id":"claim_a05d961c0d0331aeec912acd7be9a30840985968feb970502ef0fda0fb7b9a2e","kind":"lemma","schema_version":1,"statement":"[Lemma 21 of arXiv:2512.00213, 'On strong sharp phase transition in the random connection model'] Let $n, k\in\N$ and assume that $D^*_\varphi<\infty$. 
