{"assumptions":[],"created_at":"2026-10-26T19:24:25.935116+00:00","domain":"probability theory","id":"claim_a05db50077c8b4ac7fca1cdefb6e03f173144b35eaaf67412a7fbfec0cfb9851","kind":"lemma","schema_version":1,"statement":"[Lemma 22 of arXiv:2507.07702, 'Observables of random spanning trees in random environment'] Let $(G, \weight)$, $|V(G)| = n$, be a finite weighted graph with $\weight(e) = \exp(-\beta \omega_e)$ and (weighted) UST law $\bP^\omega_{G,\beta}$ with partition function $Z^\omega_{G, \beta}$. Recall that the Hamiltonian of $T$ was defined as $H(T,\omega) = \sum_{e \in T} \omega_e$. We have the following (partial) derivatives:
    \begin{align}
        \frac{\partial }{\partial \beta} \bP^\omega_{G,\beta}(\cT = T) &= \bP^\omega_{G, \beta}(\cT = T) \big(\bE^\omega_{G, \beta}[H(\cT, \omega)] - H(T, \omega) \big), \\



        \frac{\partial }{\partial \beta } \bP^\omega_{G,\beta}(e \in \cT ) &= \bE^\omega_{G, \beta}[ 1_{e \in \cT}] \bE^\omega_{G, \beta}[H(\cT, \omega)] - \bE^\omega_{G, \beta}[ 1_{e \in \cT} H(\cT, \omega)], \\

        \frac{\partial }{\partial \omega_f }  \bP^\omega_{G,\beta}(e \in \cT) &= \beta \big(  \bP^\omega_{G,\beta}(e \in \cT)  \bP^\omega_{G,\beta}(f \in \cT) - \bP^\omega_{G,\beta}(e,f \in \cT) \big). 
    \end{align}
    Furthermore, if $(\omega_e)_{e \in E}$ are distributed as independent standard Gaussian random variables, then the partition function $Z^\omega_{G, \beta}$ satisfies
    \begin{equation}
         \frac{\partial }{\partial \beta } \E \Big[ \log Z^\omega_{G, \beta} \Big] =  \beta (n-1) -  \beta \sum_{e \in E} \E \big[ \bP^\omega_{G,\beta}(e \in \cT)^2 \big] . 
    \end{equation}","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-28T02:42:39.100822+00:00","domain":"probability theory","id":"claim_a05dd584d7d0110d14036154c627bef98164bfde3e3748ce195c5bb4ac9ab96f","kind":"definition","schema_version":1,"statement":"[Definition DEF33 of arXiv:2412.08886, 'On domination for (non-symmetric) Dirichlet forms'] A real-valued process $M=(M_t)_{t\geq 0}$ is called a \emph{multiplicative functional} (MF, for short) of $X$ if it satisfies the following conditions:
\begin{itemize}
\item[(1)] The map $t\mapsto M_t(\omega)$ is decreasing,  right continuous and takes values in $[0,1]$ for all $\omega\in \Omega$;
\item[(2)] $M$ is adapted, i.e., $M_t\in \mathcal{F}_t$ for every $t\geq 0$;
\item[(3)] $M_{t+s}(\omega)=M_t(\omega)M_s(\theta_t\omega)$ holds for all $s,t\geq 0$ and $\omega\in \Omega$.
\end{itemize}","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T12:52:05.706265+00:00","domain":"probability theory","id":"claim_a05e817c1233c6a13a4b540016e9053597e31d60a9d14132435c02bae7d43081","kind":"concept","schema_version":1,"statement":"[Lem l:8.2 of arXiv:2602.21277, 'A Limit in Law for the Cover Time and Last Visited Vertex of Wired Planar Domains'] For all $n$ large enough, $x \in {\rm D}_n^\circ$ and $y \in \partial {\rm B}(x; r_n)$, 
