{"assumptions":[],"created_at":"2026-10-27T08:18:19.228299+00:00","domain":"probability theory","id":"claim_a06cb5854aeb38141dddd7783e35cd1888e77a09b5615391b285dbc86017fa43","kind":"definition","schema_version":1,"statement":"[Definition 37 of arXiv:2608.29086, '2608.29086'] [The defining system of equations for a rational molecule (2)]
\textbf{The case when all $Spec(x_i)$'s are monochromatic:} Equation(\ref{def_eq2}) yields
\begin{equation*}
\left\{
\begin{aligned}
|x|&=|\lambda_i|/ |\prod_{k \in [1,k_{i,j}] \setminus\{l_{i,j}\}} x_{k}|, \\
Spec(x)&=\{{\lambda}_{1},\ {\lambda}_{2},\ \ldots ,\ {\lambda}_{n} \}, \\
Spec(x_k)&=\{{\lambda}_{i,j,k}\}  \bmod \ RM(Obj(Mol))
\end{aligned}
\right.
\end{equation*}
($k \in [1,k_{i,j}] \setminus \{ l_{i,j}\},\ j \in [1, n_i],\  i \in [1,n]$). By identifying $x_i$ with $\lambda_{i,j,k}$, we obtain the defining system of equations for $m$ by
\begin{equation*}
|x|=|\lambda_l|/ |\prod_{k \in [1,k_{i,j}] \setminus\{l_{i,j}\}} \lambda_{i,j,k}|
\end{equation*}
($j \in [1, n_i],\  i \in [1,n]$).","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-26T19:17:42.314443+00:00","domain":"probability theory","id":"claim_a06e0bc912f8c6e4f48f3db5ee743064f6cc6857c3117d8a95e15d2c657167f1","kind":"theorem","schema_version":1,"statement":"[Proposition 48 of arXiv:2608.05931, 'Effective Lagrangian regularity and the uniqueness threshold for random H\"older velocity '] Suppose $u : \T^d \to \R^d$, $\alpha \in (0,1)$, and $Z := \{u =0\} \subseteq \T^d$ are such that
    \begin{enumerate}
        \item $\nabla \cdot u=0,$
        \item $u \in C^\alpha(\T^d)$,
        \item $\liminf_{r \to 0} r^{-(1-\alpha)} |\{ x \in \T^d : d_{\T^d}(x,Z) \leq r\}| =0$,
        \item and for all $\tau>0, y \in \T^d$, if $X^1, X^2$ are solutions to~\eqref{eq:abstract ode} on $[0,\tau]$ such that for all $t \in [0,\tau]$, $X^1_t, X^2_t \not \in Z$, then $X^1|_{[0,\tau]} = X^2|_{[0,\tau]}$.
    \end{enumerate}
    Then for almost every $y \in \T^d$,~\eqref{eq:abstract ode} admits a unique solution on $[0,\infty)$.","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T05:47:53.332046+00:00","domain":"probability theory","id":"claim_a06f709e25f4a92ed51f37c293880468fbe3594262750cf09f96ce367ea378cc","kind":"theorem","schema_version":1,"statement":"[Theorem 4 (Quenched  heat kernel estimate) of arXiv:2607.14718, 'Anchored Nash inequalities and heat kernel bounds for a class of random conductance models'] Let $d \geq 3$ and suppose there exist $m_{0} > d$, $p \in \big(\max\{1, \frac{d}{m_{0}-2}\}, \infty\big]$ and $q \in (1, \infty]$ satisfying \eqref{a1-1-2} such that $\theta^{\omega}(0), \mu^{\omega}_{m_{0}}(0) \in L^{p}(\prob)$ and $\nu^{\omega}(0) \in L^{q}(\prob)$. Then, there exist random constant $\cM_{1}^{\omega}$ and non-random constant $C_{4} \in (0, \infty)$ such that for every $\omega \in \Omega$ and $t > 0$,

  \begin{align}
    p^{\omega}(t,0,0)
    \;\leq\;
    C_{4}\, \cM_{1}^{\omega}\, t^{-d/2},
  \end{align}

  where $\cM_{1}^{\omega}$ is $\prob$-a.s.\ finite and explicity given by

  \begin{align}
    \cM_{1}^{\omega}
    \;\ldef\;
    \bigl(\cM_{0}^{\omega}\bigr)^{(1+m_{0}\gamma)/\beta}
    \bigg(1 + \frac{\mu_{m_{0}}^{\omega}(0)}{\theta^{\omega}(0)}\bigg)
  \end{align}

  with

  \begin{align}
    \cM_{0}^{\omega}
    \;\ldef\;
    \sup_{R \geq 1}\Bigl(
      \Bigl(
        \Norm{1 \vee \mu_{m_{0}}^{\omega}}{p, B(R)}
        + \Norm{1 \vee \theta^{\omega}}{p, B(R)}
      \Bigr) \cdot \Norm{1 \vee \nu^{\omega}}{q, B(R)}
    \Bigr),
  \end{align}

  and $\alpha, \beta, \gamma \in (0,1)$ are the same constants as in Lemma~\ref{l2-1} below associated with $m = m_{0}$.","status":"unverified"}

