{"assumptions":[],"created_at":"2026-10-27T07:23:05.301340+00:00","domain":"probability theory","id":"claim_a11772ac9cddf425814282a65d852935a9ca1175d05d711d2234a88fdd552775","kind":"concept","schema_version":1,"statement":"[Corollary 22 (One-dimensional reduction and zero-field reference) of arXiv:2608.21709, 'Posterior Information Dynamics of Diffusion Models for Linear Inverse Problems'] Under the model of Proposition~\ref{thm:conditional-gmm}, with \(\phi_r\) as in
\eqref{eq:conditional-cloning}, let
\begin{equation}

\kappa_t=a_t^2\delta^\top \Lambda_t^{-1}\delta,
\qquad
G_\pm(s)=\calN(s;\pm\sqrt{\kappa_t},1).
\end{equation}
Then
\begin{equation}

\phi_r(t)
=
\int_{\R}
\frac{\alpha_+^2G_+(s)^2+\alpha_-^2G_-(s)^2}
{\alpha_+G_+(s)+\alpha_-G_-(s)}\,\dd s.
\end{equation}
In the zero-field reference case \(\eta(r)=0\), the origin \(z=0\) is a local
maximum of \(\log \widetilde p_t(z\mid r)\) if and only if
\(\kappa_t\le1\); for
\(\kappa_t>1\) it loses local maximality, becoming a local minimum in the
one-dimensional reduction and a saddle when \(d>1\).  Since
\(\kappa_t\) is nondecreasing along the reverse trajectory, and strictly
increasing whenever \(\delta\neq0\), the double-well landscape forms as
\(\kappa_t\) first crosses the threshold
\begin{equation}

\kappa_t=a_t^2\delta^\top \Lambda_t^{-1}\delta=1.
\end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T14:04:39.820572+00:00","domain":"probability theory","id":"claim_a117e920b5cd1618666604dbdbcd4bbd47e79b38fbd78a6d12fdd7c12f228483","kind":"concept","schema_version":1,"statement":"[Corollary tail-bounds of arXiv:2504.02207, 'Finite-Time behaviors of M/M/$n$ Queue: Mixing Time, Mean Queue Length and Tail Bounds'] Let $\pi_{n,t}, \nu_n$ be the queue length distribution at time $t$ and the stationary distribution of the $M/M/n$ system with arrival rate $\lambda_n = n-n^{1-\alpha_n}$ and unit service rate respectively, and let $\varepsilon = 1-\frac{\lambda_n}{n}$ and $q$ be the random variable denoting the queue length. For $n \geq n_0, \delta \in (0,+\infty)$ and $n_0$ is a constant dependent on the regime, we have
\begin{align*}
    \P_{\pi_{n,t}}\sqbr{\varepsilon_n \br{q-n} > x} \leq \br{1+\chi(\pi_{n,t}, \nu_n)} \sqrt{ex} e^{-\frac{x}{2}}
\end{align*}
In particular, for $\alpha_n = \alpha \in [1,\infty)$, we have
\begin{align*}
    \P_{\pi_{n,t}}\sqbr{\varepsilon_n \br{q-n} > x} &\leq \br{1 + e^{-(\sqrt{n}-\sqrt{\lambda_n})^2 t} \chi(\pi_{n,0}, \nu_n)} \sqrt{ex} e^{-\frac{x}{2}}.
\end{align*}

For $\alpha_n = \alpha \in (1/2,1)$, we have
\begin{align*}
    \P_{\pi_{n,t}}\sqbr{\varepsilon_n \br{q-n} > x} &\leq \br{1 + e^{-C_n (\sqrt{n}-\sqrt{\lambda_n})^2 t} \chi(\pi_{n,0}, \nu_n)} \sqrt{ex} e^{-\frac{x}{2}}
\end{align*}
where $C_n$ is a positive parameter such that $\lim_{n \rightarrow \infty} C_n = 1$.

For $\alpha_n = \alpha \in (0,1/2)$, we have 

\begin{align*}
    \P_{\pi_{n,t}}\sqbr{\varepsilon\br{q-n} > x} &\leq \br{1+e^{-D_n t} \chi(\pi_{n,0}, \nu_n)}\sqrt{0.5e^{-\frac{2n^{1-2\alpha}}{7}} + 6 n^{2\alpha - 1}} \times \sqrt{ex} e^{-\frac{x}{2}}

\end{align*}
where $D_n$ is a positive parameter such that $\lim_{n \rightarrow \infty} D_n = 1/25$.

\textcolor{black}{Finally, if $\lambda_n$ is a sequence of arrival rates such that $\lim_{n \rightarrow \infty} \frac{\lambda_n}{n} = c$ for $c \in [0,1)$ then we have
\begin{align*}
    \P_{\pi_{n,t}}\sqbr{q-n > x} &\leq \br{1+e^{-L_n t} \chi(\pi_{n,0}, \nu_n)} \sqrt{e^{-\frac{(1-c)n^{1-\alpha_n}}{2}} + 2n^{\alpha_n-1} + \frac{8n^{2\alpha_n-1}}{e(1-c)}} \times e^{-\frac{x}{2}}
\end{align*}
where $\lim_{n \rightarrow \infty} \alpha_n = 0$ and $L_n$ is a positive parameter such that $\lim_{n \rightarrow \infty} L_n = 1-c$.} (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-26T19:45:07.257745+00:00","domain":"probability theory","id":"claim_a11aaf8a7aee2dc984332f8125f2243fda37a37010ad6bfb22a9081dfab9e79d","kind":"concept","schema_version":1,"statement":"[Proposition 8 of arXiv:2604.19308, '\textbf{On McKean--Vlasov SDEs with polynomial drifts for SIS epidemic models}'] In the setting of Example~\ref{ex:a representative SIS epidemic model} let~\eqref{a.1} and~\eqref{a.2} hold and suppose that if $\eta_{0} = \frac{1}{2}$, then $g_{1,1} = 0$ or $g_{1,2} = 0$. Further, let $u_{1}\in\R$ be such that
\begin{equation}
\limsup_{t\uparrow\infty} (\beta + \beta_{1}^{+})(t) - \frac{1}{2}(g_{1,2}^{2} + g_{2,1}^{2})(t)\mathbbm{1}_{\{\frac{1}{2}\}}(\eta_{0}) \leq u_{1}
\end{equation}
and $c_{1,2,\infty},c_{2,1,\infty},c_{2,2,\infty},u_{2},u_{3}\in\R$ satisfy the following four conditions:
\begin{enumerate}[(i)]
\item $\lim_{t\uparrow\infty} c_{i,j}(t) = c_{i,j,\infty}$ for any $(i,j)\in\{(2,1),(1,2),(2,2)\}$.

\item $\lim_{t\uparrow\infty} (\beta_{1}^{-} - \beta)(t) + \frac{1}{2}(g_{1,2}(t)^{2} + g_{2,1}(t)^{2})\mathbbm{1}_{\{\frac{1}{2}\}}(\eta_{0}) = u_{2}$.

\item $\lim_{t\uparrow\infty} \big(g_{1,1}(t) + g_{1,2}(t)\mathbbm{1}_{\{1\}}(\eta_{0})\big)^{2} + g_{2,1}(t)^{2}\mathbbm{1}_{\{1\}}(\eta_{0}) = u_{3}$.

\item $u_{4} := c_{1,2,\infty} + c_{2,1,\infty} + c_{2,2,\infty}N_{\infty} + \frac{1}{2}u_{3}$ is positive.
\end{enumerate}
For a positive solution $I$ to~\eqref{eq:SIS epidemic model} set $u := -(\mu_{\infty} + \gamma_{\infty})$, if $u_{2} \geq (2c_{1,2,\infty} + c_{2,1,\infty})N_{\infty}$ $ +\, c_{2,2,\infty}N_{\infty}^{2}$, and
\begin{align*}
u &:= - (\mu_{\infty} + \gamma_{\infty} + u_{I}) + u_{1}N_{\infty} + \bigg(c_{1,2,\infty} - \frac{1}{2}u_{3}\bigg)N_{\infty}^{2}\\
&\quad + \frac{1}{4} \frac{\big((u_{2} + (c_{2,1,\infty} + u_{3})N_{\infty} + c_{2,2,\infty}N_{\infty}^{2})^{+}\big)^{2}}{u_{4}},
\end{align*}
otherwise, with the non-negative constant $u_{I} := \liminf_{t\uparrow\infty} \beta_{1}^{+}(t)N(t) - \beta_{1}(t)\E\big[I_{t}\big]$. Then $I$ becomes exponentially extinct if $u < 0$. (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T19:55:37.884429+00:00","domain":"probability theory","id":"claim_a11b089a3bcc29af2cccdbc96240dcb200dab583451421040ae99ecf74e7cd5e","kind":"concept","schema_version":1,"statement":"[Lemma lm:ql+._ of arXiv:2605.09377, 'A factorization formula for the partition function in the semi-discrete parabolic Anderson'] There exists a constant $C > 0$ such that for $\| y \| < t^\sigma$, $l_\bullet \in J(t-2t^{\xi_1})$, $l_-,l_+\in \mathbb{N}_0$, one has 
