{"assumptions":[],"created_at":"2026-10-27T20:17:04.326042+00:00","domain":"probability theory","id":"claim_a121ce97057a590fefb3fe5f904e2f47544dfc1b7dd2cf1035e5b4401fb0c8cc","kind":"concept","schema_version":1,"statement":"[Proposition eq:sslongrange of arXiv:2606.01866, 'Phase Transition of a Semiflexible Membrane in Two Dimensions'] \label[proposition]{thm:sslongrange}
