				&\mathbb{E}\left[ \mathbf{1}_{\tau \ge T} (\|(u,v)\|^2_{C([0,T]; H^{1+s,2}(\mathbb{T}^d)\times H^{1+s_v,2}(\mathbb{T}^d))}+\|(u,v)\|^2_{L^2([0,T],w_\kappa; H^{2+s,2}(\mathbb{T}^d)\times H^{2+s_v,2}(\mathbb{T}^d))}) \right]\\&
				\lesssim \mathbb{E} \|(u_0,v_0)\|_{H^{d/2-2,2}(\mathbb{T}^d)\times H^{d/2,2}(\mathbb{T}^d)}^2.
