{"assumptions":[],"created_at":"2026-10-26T19:39:41.407581+00:00","domain":"probability theory","id":"claim_a451c7680aff25b4e70165ace0c11e6d4c42e9231d137206a3af9c8ba1624e02","kind":"lemma","schema_version":1,"statement":"[Lemma 2 of arXiv:2604.06645, '2604.06645'] Fix $i\in \{1,...,m\}$ and $k\in \{1,...,r\}$. Let $b_i:\mathbb R_{+}^m\to \mathbb R$ and $g_{ik}: \mathbb R^m_{+}\to \mathbb R$. Assume that:
    \begin{enumerate}
        \item $u_i$ solves the integral equation
        \begin{align*}
        u_i(t,x) &= \int_D G_i(t,x,y)u_{i0}(y)+\int_0^t\int_D G_i(t-s,x,y)b_i(u(s,y))dyds\\
    &+ \sum_{k=1}^r \int_0^t\int_D G_i(t-s,x,y)g_{ik}(u(s,y))W_k(dyds),
        \end{align*}
        where $G_i(t,x,y)$ is the heat kernel;
        \item The functions $b_i$ and $g_{ik}$ are globally Lipschitz continuous: There exists an $L>0$ such that, whenever $x,y\in [0,\infty)^m$,
        \begin{align*}
            &|b_i(x)-b_i(y)|\leq L||x-y||_2\\
            &|g_{ik}(x)-g_{ik}(y)|\leq L||x-y||_2
        \end{align*}
        \item The functions $b_i$ and $g_{ik}$ are uniformly bounded: There exists a $K>0$ such that
        \begin{align*}
            &\sup_{\substack{a_1,...,a_m\\ a_i\geq 0}} |b_i(a_1,...,a_m)|\leq K,\\
            &\sup_{\substack{a_1,...,a_m\\ a_i\geq 0}} |g_{ik}(a_1,...,a_m)|\leq K.
        \end{align*}
        \item The functions $b_i$ and $g_{ik}$ satisfy the positivity conditions
        \begin{align*}
        b_i(a_1,...,a_{i-1},0,a_{i+1},...,a_m) &\geq 0;\\
        g_{ik}(a_1,...,a_{i-1},0,a_{i+1},...,a_m) &= 0, \quad \text{ for any } k\in \{1,...,r\},
        \end{align*}
        whenever $a_1,...,a_m\geq 0$.
        \item The initial data $u_{i0}(y)$ are nonnegative a.e.
    \end{enumerate}
    Then $\mathbb{P}\bigl(u_i(t,\cdot)\ge 0 \text{ a.e. in } D \text{ for all } t\in[0,T]\bigr)=1$.","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T05:33:17.712410+00:00","domain":"probability theory","id":"claim_a4544ace624002580487d4f901bf9051bbc0add201be919cd23a7865c6649c97","kind":"theorem","schema_version":1,"statement":"[Corollary 33 (Localized cubic coordinate) of arXiv:2607.10813, '2607.10813'] Fix an adapted localization pair $(\chi,\rho)$ and $a\in\mathfrak C$.
For every $M>0$ and every finite $p\ge2$, the sequence
$\mathcal R_{a,\Lambda}^{\chi,\rho}$ in
\eqref{eq:localized-cubic-split} converges in
\begin{equation}
 L^p\!\left(\Omega;
 C_T(H^M\cap\mathcal C^M)\right)
\end{equation}
to a compactly supported path $\mathcal R_a^{\chi,\rho}$.  The limit obeys
\begin{equation}
 \|\mathcal R_a^{\chi,\rho}\|_{C_T(H^M\cap\mathcal C^M)}
 \lesssim_{M,\chi,\rho}
 \|V_{a^\perp}\|_{C_T\mathfrak T_{J_{\mathrm{ps}}}}
 \|\Psi_a\|_{C_T\mathfrak T_{J_{\mathrm{ps}}}}.
\end{equation}
More generally, if $f_j,g_j\in C_T\mathfrak T_{J_{\mathrm{ps}}}$, then
with
$\mathcal R^{\chi,\rho}(f,g):=
 \chi(((\rho-1)f)\circ g)$,
\begin{align}
 &\|\mathcal R^{\chi,\rho}(f_1,g_1)
      -\mathcal R^{\chi,\rho}(f_2,g_2)\|_{C_T(H^M\cap\mathcal C^M)}
 \notag\\
 &\quad\lesssim_{M,\chi,\rho}
 \|f_1-f_2\|_{C_T\mathfrak T_{J_{\mathrm{ps}}}}
 \bigl(\|g_1\|_{C_T\mathfrak T_{J_{\mathrm{ps}}}}
      +\|g_2\|_{C_T\mathfrak T_{J_{\mathrm{ps}}}}\bigr)
 \notag\\
 &\qquad\quad+
 \|g_1-g_2\|_{C_T\mathfrak T_{J_{\mathrm{ps}}}}
 \bigl(\|f_1\|_{C_T\mathfrak T_{J_{\mathrm{ps}}}}
      +\|f_2\|_{C_T\mathfrak T_{J_{\mathrm{ps}}}}\bigr).

\end{align}
The finite-cutoff Wick decomposition from
\eqref{eq:cubic-wick-decomposition} and
\eqref{eq:localized-cubic-split} gives
\begin{equation}
 \Gamma_{a,\Lambda}^{\chi,\rho}
 =\chi\Gamma_{a,\Lambda}^{(3)}
  +\chi\Gamma_{a,\Lambda}^{(1)}
  +\mathcal R_{a,\Lambda}^{\chi,\rho}.
\end{equation}
Set
\begin{equation}
 \Gamma_a^{\chi,\rho}:=\chi\Gamma_a+\mathcal R_a^{\chi,\rho}.
\end{equation}
Then
\begin{equation}
 \Gamma_{a,\Lambda}^{\chi,\rho}
 \longrightarrow \Gamma_a^{\chi,\rho}
\end{equation}
in
\[
 L^p\!\left(\Omega;
 C_T\mathcal C^{-\beta_{\Gamma,a}-\kappa}
 \cap L_T^\infty B_{2,\infty}^{-\beta_{\Gamma,a}-\kappa}\right).
\]
Along a fixed-profile dyadic family the convergence holds almost surely along
the full sequence; along an arbitrary admissible cofinal sequence it holds in
probability.  In all cases the decomposition
\begin{equation}
 \Gamma_a^{\chi,\rho}
 =\chi\Gamma_a^{(3)}+\chi\Gamma_a^{(1)}
  +\mathcal R_a^{\chi,\rho}
\end{equation}
is preserved in the limit.","status":"unverified"}

