{"assumptions":[],"created_at":"2026-10-27T13:56:17.361578+00:00","domain":"probability theory","id":"claim_a573f08088abdbbd6d59ff9438d56a476627e9cd6f2d51bb143ace7830158aae","kind":"theorem","schema_version":1,"statement":"[Proposition prop:collision-eigenfunction of arXiv:2605.16244, 'Analysis of a twisted Bose--Einstein Markov chain with applications to sampling Catalan st'] Assume $n,k\ge2$. 
Let $K$ and $\pi$ be the transition kernel and stationary distribution of the twisted Bose--Einstein Markov chain on $[k]^n$. 
Then
\begin{equation}
 K F_{r,s}=\rho F_{r,s},
\end{equation}
and, for every $x\in[k]^n$ and $t\ge0$,
\begin{equation}
 \mathbb P_x(X_t(r)=X_t(s))
 =c+\rho^tF_{r,s}(x).
\end{equation}
Moreover,
\[
 \pi(x_r=x_s)=c,
\]
and
\begin{equation}
 \left\|K^t(x,\cdot)-\pi\right\|_{\mathrm{TV}}
 \ge
 \rho^t
 \left|H_{r,s}(x)-c\right|.
\end{equation}
If $x_{\mathrm{const}}$ is any constant word, then
\begin{equation}
 \left\|K^t(x_{\mathrm{const}},\cdot)-\pi\right\|_{\mathrm{TV}}
 \ge
 \frac{\theta(k-1)}{k\theta+1}\rho^t.
\end{equation}
Consequently,
\begin{equation}
 d(t)
 \ge
 \frac{\max\{\theta+1,\theta(k-1)\}}
 {k\theta+1}\rho^t.
\end{equation}
For the lumped chain,
\begin{equation}
 \overline K(J-c)=\rho(J-c),
\end{equation}
and
\begin{equation}
 \overline d(t)
 \ge
 \frac{\theta(k-1)}{k\theta+1}\rho^t.
\end{equation}","status":"unverified"}

