\int_0^{\infty}
\frac{e^{\theta}r_a(\xi)}
{1+(e^{\theta}-1)r_a(\xi)}
\,\mathrm{d}\xi,
\]
\[
\Lambda_a''(\theta)
=
\frac{1}{2\pi}
\int_0^{\infty}
