\begin{equation}
\widehat\mbfX^\pi_\bullet(\omega,\mbfs)\eqdef \big({\mbfs,\mbfX^\mbfs_\bullet(\omega)}\big) \quad\text{and} \quad \widehat P^\pi_{(\mbfs,\mbfx)}\eqdef P^\mbfs_\mbfx\,\mathrm{,}\;\, \qquad \mbfx\in\mbfM\,\mathrm{,}\;\, \mbfs\in\mbfT\,\mathrm{,}\;\,\omega\in\Omega \,\mathrm{;}\;\,
\end{equation}

\item
the process $\widehat\boldsymbol\mssW_\pi$ is the ---unique up to $\widehat\boldsymbol\nu_\pi$-equivalence--- $\widehat\boldsymbol\nu_\pi$-sub-stationary $\widehat\boldsymbol\nu_\pi$-special standard process solving the martingale problem for $(\widehat\boldsymbol\mssL_\pi,\mcC_b(\mbfT)\otime (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-28T01:41:54.363003+00:00","domain":"probability theory","id":"claim_a67a241b9e67e43687e9e74d8cda7a9548a94d2560221ecf61121179fe7ac24a","kind":"concept","schema_version":1,"statement":"[Corollary cor:interpolation of arXiv:2412.01645, 'Regularisation by Gaussian rough path lifts of fractional Brownian motions'] Let $0\leq s<t\leq 1$. Let $\gamma>1-2H$. Let $f\in\mathcal{H}$ such that   $\mathop{\mathrm{supp}} f\subset[s,t]$ and the restriction of $f$ to $[s,t]$ belongs to $\mathcal{C}^\gamma$.
