{"assumptions":[],"created_at":"2026-10-27T06:02:34.833871+00:00","domain":"probability theory","id":"claim_a6abdf1bf68d6a9d6b3c99eb21508633a44ede1c980e39f60a31d056af01fc1b","kind":"theorem","schema_version":1,"statement":"[Theorem 14 (Gaussian cofactor induction) of arXiv:2607.20329, '2607.20329'] Let $\mathbb K\in\{\R,\C,\Hh\}$ and $\beta=\dim_{\R}\mathbb K$.
		For each $m\ge1$, let $g_m^{\mathbb K}$ be a standard
		$\mathbb K$-Gaussian column in $\mathbb K^m$, independent of the gamma
		variables.  Then, for every $n\ge1$,
		\begin{equation}
			\Pi_{n-1,\beta}g_n^{\mathbb K}(g_n^{\mathbb K})^*
			\preceq_{\mathrm{Lt}}
			C_n^{\mathbb K}(C_n^{\mathbb K})^*.
		\end{equation}
		Moreover,
		\begin{equation}
			\Pi_{n,\beta}
			\le_{\mathrm{Lt}}\|C_n^{\mathbb K}\|_2^2.
		\end{equation}
		Finally, for every $z\in\mathbb K^{n+1}$,
		\begin{equation}
			0\le \E e^{\ii(z,C_{n+1}^{\mathbb K})_{\R}}
			\le \E e^{\ii(z,\sqrt{\Pi_{n,\beta}}\,
				g_{n+1}^{\mathbb K})_{\R}}.
		\end{equation}","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T11:32:18.864111+00:00","domain":"probability theory","id":"claim_a6ac313c3ab2e3437b465d1ad600821b95c7c1156c40c98896b10e1929636a88","kind":"theorem","schema_version":1,"statement":"[Proposition 54 of arXiv:2609.03875, 'Measure theory without infinities'] Let $\mf A$ be an HOTM and $\mu$ and $\nu$ be $\mf A$-valued premeasures such that $\q{\mu}=\q{\nu}$. 
  \begin{enumerate}
  \item[(i)]  $\mu\dotleq\nu$ if and only if $\as[\mf A]{\mu}\dotleq\as[\mf A]{\nu}$.
  \item[(ii)] Suppose $\mu$ and $\nu$ are measures. If $\mu\dotleq\nu$ and $\nu\dotleq\mu$, then $\mu=\nu$.
  \end{enumerate}","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-26T20:25:44.969042+00:00","domain":"probability theory","id":"claim_a6ac5e03bd4612fd380cd53f2afa6008a83791f7e20003e7443cd59880ca453c","kind":"lemma","schema_version":1,"statement":"[Lemma 8 (Fourth moments for the cross-polytope) of arXiv:2605.11451, '2605.11451'] Let $X\sim \nu_{1,n}$ be uniform on $B_1^n$ and let $i\neq j$. Then
\begin{align}
 \E X_i^4
