{"assumptions":[],"created_at":"2026-10-26T19:29:23.337928+00:00","domain":"probability theory","id":"claim_a71817b9f56b5038f8d61672f02cd37948623448cc38d1fddb79c5327d5c8099","kind":"lemma","schema_version":1,"statement":"[Lem 2 of arXiv:2512.05687, '$L^p$-Boltzmann-Gibbs principle \\ via Littlewood-Paley-Stein inequality'] The generator $L=L_0+L_1$ of the process $\eta_t$, determined by 
\eqref{eq:eta_t-pert-2}, is given by
\begin{align*} 
L_0 & = \sum_{x\in \T_N} \big( \partial_{\eta(x)}^2 - \partial_{\eta(x)}\partial_{\eta(x-1)}
\big)  + \frac12 \sum_{x\in \T_N} \big( V'(\eta(x+1)) -2V'(\eta(x))+ V'(\eta(x-1)) \big) \partial_{\eta(x)} \\
& = \frac12 \sum_{x\in \T_N} 
\Big( \big( \partial_{\eta(x)} - \partial_{\eta(x-1)} \big)^2
- \big( V'(\eta(x)) - V'(\eta(x-1)) \big)
\big( \partial_{\eta(x)} - \partial_{\eta(x-1)} \big)\Big),   \\
L_1 & = \ga \sum_{x\in \T_N} \big( V'(\eta(x+1)) - V'(\eta(x-1)) \big) \partial_{\eta(x)},
\end{align*}
where $\partial_{\eta(x)} = \frac{\partial}{\partial\eta(x)}$.
Note that $\eta(N+1)=\eta(1), \eta(0)= \eta(N)$ and $\partial_{\eta(0)}
= \partial_{\eta(N)}$ by \eqref{eq:eta-p}.","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T13:52:23.577945+00:00","domain":"probability theory","id":"claim_a71bcb8ccf69f01d059bbb5e505c43ab21139f32355208edc3948eff9dc87108","kind":"lemma","schema_version":1,"statement":"[Lemma lem:localenergy of arXiv:2602.05477, 'On the Resistance Conjecture'] If $\Omega\subset X$ is open, then the following hold.
    \begin{enumerate}  
			\item \textbf{Homogeneity:} For every $f\in \mathcal{F}_{p,\loc}(\Omega)$ there exists a finite non-negative Borel measure $\Gamma_p \langle f \rangle$ on $\Omega$ and for all $\lambda \in \mathbb{R}$
			\[
			\Gamma_p\langle \lambda f\rangle = |\lambda|^p \Gamma_p\langle f\rangle.
			\]
			\item \textbf{Triangle inequality:} For every $f,g\in \mathcal{F}_{p,\loc}(\Omega)$ and every Borel set $A\subset \Omega$, 
			\begin{equation} 
				\Gamma_p\langle f+g\rangle(A)^{\frac{1}{p}}\le \Gamma_p\langle f\rangle(A)^{\frac{1}{p}}+\Gamma_p\langle g\rangle(A)^{\frac{1}{p}}
			\end{equation}
            \item \textbf{Addition of constant:} For all $f\in \mathcal{F}_{p,\loc}(\Omega)$ and $c\in \mathbb{R}$ we have $f+c\in \mathcal{F}_{p,\loc}(\Omega)$ and $\Gamma_p\langle f\rangle=\Gamma_p\langle f+c\rangle$.
			\item \textbf{Lipschitz contractivity:} For all $f\in \mathcal{F}_{p,\loc}(\Omega)$ and $g\in \Lip(\mathbb{R})$,  we have $g \circ f \in \mathcal{F}_{p,\loc}(\Omega)$ and
			\begin{equation} 
				d\Gamma_p\langle g\circ f\rangle \le \LIP[g]^p d\Gamma_p\langle f\rangle.
			\end{equation}
			\item \textbf{Strong locality:} For every $f\in \mathcal{F}_{p,\loc}(\Omega)$ and any open set $A\subset \Omega$, if $f|_\Omega=c$ $\mu$-a.e., then $\Gamma_p\langle f\rangle(A)=0$. 
		\end{enumerate}","status":"unverified"}

