{"assumptions":[],"created_at":"2026-10-27T14:05:52.415842+00:00","domain":"probability theory","id":"claim_a72a75e6a52224b3f67a3186faac9fe3aa14c52e0b15c2e6aaae5edc669f12e5","kind":"lemma","schema_version":1,"statement":"[Lemma lemma6.234 of arXiv:2504.15992, 'Repeated singular values of a random symmetric matrix and decoupled singular value estimat'] For $B>0$ consider $\zeta\in\Gamma_B$ and $X\sim\operatorname{Col}_n(\zeta)$. Let $M_1,M_2$ be two $n\times n$ symmetric matrices, $u\in\mathbb{R}^n$, $t_1,t_2\in\mathbb{R}$ and $s,\delta_1,\delta_2\geq 0$. Then 
\begin{equation}\begin{aligned}
    &\mathbb{P}(|\langle M_iX,X\rangle-t_i|<\delta_i,i=1,2,\langle X,u\rangle\geq s)\\&\lesssim \delta_1\delta_2e^{-s}\int_{\{\theta\in\mathbb{R}^2:\theta_1^2\delta_1^2+\theta_2^2\delta_2^2\leq 2\}}|\mathbb{E}e^{2\pi i\theta_1\langle M_1X,X\rangle+2\pi i\theta_2\langle M_2X,X\rangle+\langle X,u\rangle}|d\theta.
\end{aligned}\end{equation}","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T10:34:20.693418+00:00","domain":"probability theory","id":"claim_a72ea4469803e28aa22cebbd575a963927e3a14cf789924ae87637232658a9af","kind":"lemma","schema_version":1,"statement":"[Lemma 15 of arXiv:2609.02193, 'State-law dynamics of McKean-Vlasov stochastic reaction-diffusion equations on $\mathbb R^'] Let $\epsilon\in[0,\epsilon_0]$, $\omega\in\Omega_0$, $x\in H$ and $\mu\in P$. Then equation~\eqref{Eq4-trans} with $\eta=\ell^\epsilon_\mu$ and initial datum $x-\epsilon z(\omega)$ has a unique pathwise variational solution
	\begin{align*}
		v_{\ell^\epsilon_\mu}(\cdot,\omega;
		x-\epsilon z(\omega))
		\in
		C([0,T];H)\cap L^2(0,T;V)
		\cap L^p(0,T;L^p(\mathbb R^n))
	\end{align*}
	for every $T>0$. Consequently,
	\begin{align}
		\varphi^\epsilon_H(t,\omega,x,\mu)
		=
		v_{\ell^\epsilon_\mu}
		(t,\omega;x-\epsilon z(\omega))
		+\epsilon z(\theta_t\omega)
	\end{align}
	is well defined. The map
	$(t,\omega,x,\mu)\mapsto\varphi^\epsilon_H(t,\omega,x,\mu)$ is jointly measurable, and, for all $x,y\in H$ and $\mu,\nu\in P$,
	\begin{align}
		\|\varphi^\epsilon_H(t,\omega,x,\mu)
		-\varphi^\epsilon_H(t,\omega,y,\nu)\|^2
		&\leq
		e^{-\bar\gamma t}\|x-y\|^2
		+L_G\int_0^t e^{-\bar\gamma(t-r)}
		\mathcal W_2^2\big(
		\varphi^\epsilon_P(r)\mu,
		\varphi^\epsilon_P(r)\nu
		\big)dr
		\notag\\
		&\leq
		e^{-\bar\gamma t}\|x-y\|^2
		+\big(e^{(L_G-\bar\gamma)t}-e^{-\bar\gamma t}\big)
		\mathcal W_2^2(\mu,\nu).
	\end{align}
	In particular, $(x,\mu)\mapsto\varphi^\epsilon_H(t,\omega,x,\mu)$ is continuous from $H\times P$ to $H$ for every $t\geq0$ and $\omega\in\Omega_0$.","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T23:32:34.789272+00:00","domain":"probability theory","id":"claim_a7301f3c4e7bb7d6534da52688da24fae75cc8a1f9786b99ad208de90a8618f6","kind":"concept","schema_version":1,"statement":"[Proposition prop:asympvarspeedup of arXiv:2411.08295, 'Improving the convergence of Markov chains via permutations and projections'] Let $P \in \mathcal{L}(\pi)$ and $Q \in \mathcal{I}(\pi) \cap \mathcal{L}$ be an isometric involution transition matrix. Fix $\alpha \in (0,1)$ and recall that $\overline{P}_{\alpha}(Q)$ is introduced in (equation eq:PbaralphaQ of the paper). We have 
	\begin{itemize}
		\item(worst-case asymptotic variance) \begin{align*}
			V(\overline{P}_\alpha(Q)) \leq V(P), 
		\end{align*}
		where the equality holds if and only if $\lambda_2(\overline{P}_\alpha(Q)) = \lambda_2(P)$ if and only if there exists a common eigenvector $g$ such that $\overline{P}_{\alpha}(Q)g = \lambda_2(\overline{P}_{\alpha}(Q))g$, $Pg = \lambda_2(P) g$ and $QPQg = \lambda_2(QPQ) g$.

		If $P$ is further assumed to be positive-semi-definite, then
		\begin{align*}
				\max\{\alpha,1-\alpha\} V(P) &\leq V(\overline{P}_\alpha(Q)) \leq V(P).
		\end{align*}

		\item(average-case asymptotic variance) \begin{align*}
			\overline{v}(\overline{P}_\alpha(Q)) \leq \overline{v}(P).
		\end{align*}
	\end{itemize}
	Consequently, this leads to
	\begin{align*}
		\min_{\alpha \in [0,1]} V(\overline{P}_\alpha(Q)) &= V(\overline{P}(Q)), \\
		\min_{\alpha \in [0,1]} \overline{v}(\overline{P}_\alpha(Q)) &= \overline{v}(\overline{P}(Q)).
	\end{align*} (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

