\\
\left(\mathcal L_1,\mathcal L_2, \mathcal L_3,\mathcal L_4\right)&=&(0,-1,-1,-2).

\end{eqnarray}","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-26T19:29:00.763147+00:00","domain":"probability theory","id":"claim_a8174e7080d23a3f02f9ae6a4a832b876ada3b5ed1ffb2fb32f9b20d54a15069","kind":"definition","schema_version":1,"statement":"[Definition 1 (Tempered fractional Brownian motion
\cite{MeerschaertSabzikar2013}) of arXiv:2512.04646, '\textbf{Canonical Rough Path over Tempered Fractional Brownian Motion: Existence, Construc'] For $H \in (0,1)$ and $\lambda > 0$, the \emph{tempered fractional
Brownian motion} (tfBm)
$B_{H,\lambda} = (B_{H,\lambda}(t))_{t \ge 0}$ is the centred
Gaussian process defined by
\begin{equation}

B_{H,\lambda}(t) = \frac{1}{\Gamma(H+\frac{1}{2})} \int_{\mathbb{R}}
\Bigl[ e^{-\lambda(t-s)_+}(t-s)_+^{H-\frac{1}{2}}
      - e^{-\lambda(-s)_+}(-s)_+^{H-\frac{1}{2}} \Bigr] \, dW(s),
\end{equation}
where $W$ is a standard two-sided Brownian motion and
$x_+ = \max(x,0)$.","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-26T19:18:27.579219+00:00","domain":"probability theory","id":"claim_a81a4d67b9664d426f3442981897bdc62b38a3b84ae73e41c84851d6b0d614a1","kind":"theorem","schema_version":1,"statement":"[Theorem 3 (Reduction; conditional on Hypothesis~\ref{hyp:red}) of arXiv:2608.15987, 'Threshold cascades of interacting diffusions on unimodular random trees: a conditional bra'] Under Hypothesis~\ref{hyp:red}, the failed cluster of the root converges in distribution (as a random rooted tree) to the family tree of the multitype Galton--Watson process on type set $D$ with mean matrix
\begin{equation}
M_{d,d'}=m_*\,q(d')\,p_{d,d'},\qquad d,d'\in D,
\end{equation}
where $p_{d,d'}$ is the transmission probability \eqref{eq:wald}. In particular the survival probability of the cascade is positive iff $\rho(M)>1$, and zero iff $\rho(M)\le1$, where $\rho(M)$ is the Perron root of the nonnegative matrix $M$.","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-28T02:56:14.270487+00:00","domain":"probability theory","id":"claim_a81aa477e04ead579f7c8e6f9fc34f32fec05322a8b094d5e6f1b3270beaada2","kind":"lemma","schema_version":1,"statement":"[Lem setup2 of arXiv:2412.09535, 'Local limit theorem for joint subgraph counts'] Let $H\in \mathcal{H}$ be connected and let $\eps \leq \alpha \leq 1$ be real. We get $\abs{\sete[e^{if}]} = n^{-\omega_{\lambda,\ell,\eps}(1)}$ as long as
\begin{cond}
    \item  $n^{-\alpha+\eps} \leq \Delta_H^2 \leq 1.1\pi^2 (p(1-p))^{e(H)}$;
    \item  For any graph $H' \succ H$, we have $n^{v(H')} \Delta_{H'}^2 < n^{v(H)- \alpha - \eps}$.
\end{cond}","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-26T20:58:09.066001+00:00","domain":"probability theory","id":"claim_a81ad026572e95ea456fe0afcce4752b51a5871e971cbb838ce9982fb32cef09","kind":"concept","schema_version":1,"statement":"[Theorem 1 of arXiv:2606.27520, 'Critical curve of loop percolation on the $d$-regular tree'] The critical value $\alpha_c(\kappa)$ is positive if and only if $\kappa>\kappa_c$. Furthermore, for each $\kappa>\kappa_c$, 
$\alpha_c(\kappa)$ is the unique solution of $\alpha > 0$ to the equation \begin{equation}
\sum_{n \geq 0} \Big( \big(1-\tau_\kappa^{2(n+1)}\big)^{-\alpha} -1 \Big) (d-1)^n  = \frac{1}{d-2}.
\end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T21:24:20.648212+00:00","domain":"probability theory","id":"claim_a81b9747b3d7e63c2ce8a47db1cd4f1d1aa8b614c836481671facfd241b37e4a","kind":"concept","schema_version":1,"statement":"[Corollary cor:smallpmode of arXiv:2608.11378, 'On the most likely geodesic in last passage percolation'] There is $p_{n} > 0$ such that if $\omega_x \sim \mathrm{Ber}(p)$ with $0 < p \le p_n$, then for any path $\gamma$,
    \begin{equation*}
        \mathbb{P}(\gamma^{\raisebox{-0.5ex}{$\scriptstyle\ulcorner$}} \in \Gamma^*_n ) \ge \mathbb{P}(\gamma \in \Gamma^*_n).
    \end{equation*}
    This inequality is strict unless $\gamma \in \set{\gamma^{\raisebox{-0.5ex}{$\scriptstyle\ulcorner$}}, \gamma^{\raisebox{-0.5ex}{$\scriptstyle\lrcorner$}}}$. (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T08:52:08.657264+00:00","domain":"probability theory","id":"claim_a81cce9dfd46fb525966e95c12bd55d2c2ce177e2672ce58785bc23faf6428c2","kind":"definition","schema_version":1,"statement":"[Definition 7 of arXiv:2608.29976, 'The Pego Theorem for the Hilbert--Schmidt Class'] Let $1\le p\le 2$ and  $F\subset\mathcal{T}^p(\mathcal{H})$. We say that $F$ is
