\,\E\bigl[\|\bY\|_{\ell_\varrho}^2+1\big|\min(Y_0^2,Y_{-1}^2)\ge \delta\bigr].
}
Moreover, for a sequence $\bY=(Y_n)_{n\in-\N_0}$ of i.i.d.\ $ L^2 $-integrable random variables with~\cref{eq63645} one has that
\bas{
\E\bigl[&(1+ v^*(\bY)^{-1}) (\|\bY\|_{\ell_\varrho}^2+1) \bigr]\le\Bigl(1+ \frac\beta{(1-\beta)} \Bigl(\frac { q}{\beta-(1-q)}\Bigr)^2\, \delta^{-1}\Bigr) 
