{"assumptions":[],"created_at":"2026-10-27T12:17:13.081687+00:00","domain":"probability theory","id":"claim_a98e4dab316a48b3354c7704298fdbfbf6e98ee97472a883b95d2522045f11d4","kind":"concept","schema_version":1,"statement":"[Theorem TU of arXiv:2510.12480, 'Cyclic and alternating $U$-statistics'] With notations and assumptions 
as in Section~(Sprel of the paper),
the following holds.
\begin{romenumerate}
\par
 \refstepcounter{thmenumerate}\textup{(\roman{thmenumerate})\enspace} 
We have
\begin{align}
  \operatorname{\mathbb E}{} U_n(f) = \tbinom n2\mu
\end{align}
and, as \ensuremath{{n\to\infty}}, we have the weak law of large numbers
\begin{align}
  \frac{1}{\binom n2} U_n(f)\overset{\mathrm{p}}{\longrightarrow} \mu.
\end{align}

\par
 \refstepcounter{thmenumerate}\textup{(\roman{thmenumerate})\enspace} 
As \ensuremath{{n\to\infty}},
\begin{align}
n^{-3}\operatorname{Var}[U_n(f)]\to
  \sigma^2:=\tfrac{1}{3}
\bigl(\operatorname{\mathbb E}{} [f_1(X)^2] + \operatorname{\mathbb E}{} [f_2(X)^2] + \operatorname{\mathbb E}{} [f_1(X)f_2(X)]\bigr)
\end{align}
and 
\begin{align}
  n^{-3/2}\left(U_n(f)-\tbinom n2 \mu\right) \overset{\mathrm{d}}{\longrightarrow} N(0,\sigma^2).
\end{align}
Furthermore, $\sigma^2>0$ unless $f_1(X)=f_2(X)=0$ a.s.

\par
 \refstepcounter{thmenumerate}\textup{(\roman{thmenumerate})\enspace} 
If\/ $f_1(X)=f_2(X)=0$ a.s., and thus $\sigma^2=0$, then
\begin{align}

  \operatorname{Var}[U_n(f)] = \tbinom{n}{2}\operatorname{Var} [f(X_1,X_2)]
=\tfrac{1}{2}n^2\operatorname{Var} [f(X_1,X_2)] + O(n).
\end{align}
Moreover, there exists
a finite or infinite sequence of real numbers $(\lambda_r)_1^R$ such that
\begin{align}
  n^{-1}\left(U_n(f)-\tbinom n2 \mu\right) \overset{\mathrm{d}}{\longrightarrow} W:=\sum_{r=1}^R\tfrac12\lambda_r(\zeta_r^2-1),
\end{align}
where $(\zeta_r)_1^R$ are independent standard normal variables.
The coefficients
$(\lambda_r)_1^R$ 
are the nonzero eigenvalues (with multiplicities) 
of the self-adjoint 
integral operator $T_{{\widehat{f}}-\mu}$ 
on $L^2({\mathcal X}\times\ensuremath{[0,1]},\nu\times\ell)$
(where $\ell$ is Lebesgue measure)
defined as in (equation Tg of the paper) using (equation hff of the paper).
We have
\begin{align}
\operatorname{Var} W=
 \tfrac12 \sum_{r=1}^R\lambda_r^2 = \tfrac12\operatorname{Var}[f(X_1,X_2)]
<\infty.
\end{align}

\par
 \refstepcounter{thmenumerate}\textup{(\roman{thmenumerate})\enspace} 
In the special case of (TU2 of the paper) where
furthermore
$f$ is symmetric, 
the coefficients
$(\lambda_r)_1^R$ in (equation tu2 of the paper) are the nonzero eigenvalues (with multiplicities) 
of the self-adjoint 
integral operator $T_{f-\mu}$ 
on $L^2({\mathcal X},\nu)$.

\par
 \refstepcounter{thmenumerate}\textup{(\roman{thmenumerate})\enspace} 
In the special case of (TU2 of the paper) where
furthermore
$f$ is antisymmetric, 
then also
\begin{align}

  n^{-1}{U_n(f)} \overset{\mathrm{d}}{\longrightarrow} 
W:=\sum_{q=1}^{Q_+}\lambda^{\mathsf a}_q\eta_q,
\end{align}
where $(\eta_q)_1^{Q_+}$ are independent random variables with the stochastic area
distribution (equation area of the paper), and
the coefficients 
$(\lambda^{\mathsf a}_q)_1^{Q_+}$  are the positive numbers such that the imaginary
number $\mathrm{i}\lambda^{\mathsf a}_q$ is an eigenvalue of the 
anti-self-adjoint
operator $T_f$ on $L^2_{\mathbb C}({\mathcal X},\nu)$.
We have
\begin{align}
  \operatorname{Var} W = \sum_{q=1}^{Q_+}(\lambda^{\mathsf a}_q)^2 = \tfrac12\operatorname{Var}[f(X_1,X_2)].
\end{align}

\end{romenumerate} (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-28T00:32:56.101713+00:00","domain":"probability theory","id":"claim_a98e7ed81e2f6e55c6c50416cc0b199ec78cccddac0a55f12257c73cfe917921","kind":"lemma","schema_version":1,"statement":"[Lemma Lem:ftc of arXiv:2411.13030, 'Classification of the limit shape for 1+1-dimensional FPP'] Let $f(x)$ be a Riemann-integrable function on $[0,1]$ and set $L=\int_0^1 f(x) \,dx$. For $\varepsilon>0$, define the sets
