{"assumptions":[],"created_at":"2026-10-27T06:29:21.945321+00:00","domain":"probability theory","id":"claim_aa70a621d27d5e7b923400319af1929f15b144b407245fec706241fc9aeb1a88","kind":"theorem","schema_version":1,"statement":"[Thm 7 of arXiv:2608.01860, 'A Variational Characterization of a Gibbs Measure related to the Aviles-Giga Functional'] Choosing 
\begin{align*}
     a_T=&6\langle\partial_1Y,\partial_1Y\rangle_T(\partial_1Y_T)^2+6\langle\partial_2Y,\partial_2Y\rangle_T(\partial_2Y_T)^2+2\langle\partial_2Y,\partial_2Y\rangle_T(\partial_1Y_T)^2\\
    &+2\langle\partial_1Y,\partial_1Y\rangle_T(\partial_2Y_T)^2+4\langle\partial_1Y,\partial_2Y\rangle_T^2-3\langle\partial_1Y,\partial_1Y\rangle_T^2-3\langle\partial_2Y,\partial_2Y\rangle_T^2\\
    &-2\langle\partial_1Y,\partial_1Y\rangle_T\langle\partial_2Y,\partial_2Y\rangle_T\\
    &+8 \int_0^T\int_0^s \partial_1 Y_u\ d(\partial_2 Y_u) \ d\langle\partial_1 Y,\partial_2Y\rangle_s +8 \int_0^T\int_0^s \partial_2 Y_u\ d(\partial_1 Y_u) \ d\langle\partial_1 Y,\partial_2Y\rangle_s\\
    &+8 \int_0^T\int_0^s \partial_1 Y_u\ d\langle\partial_2 Y,\partial_2 Y\rangle_u\ d(\partial_1Y_s)+8 \int_0^T\int_0^s \langle\partial_2 Y,\partial_2 Y\rangle_u\ d(\partial_1 Y_u)\ d(\partial_1Y_s)\\
    &+8 \int_0^T\int_0^s \partial_2 Y_u\ d\langle\partial_1 Y,\partial_1 Y\rangle_u\ d(\partial_2Y_s)+8 \int_0^T\int_0^s \langle\partial_1 Y,\partial_1 Y\rangle_u\ d(\partial_2 Y_u)\ d(\partial_2Y_s),\\
     b_T=&\begin{pmatrix}
        3\langle\partial_1Y,\partial_1Y\rangle_T\partial_1Y_T+2\langle\partial_1Y,\partial_2Y\rangle_T\partial_2Y_T+\langle\partial_2Y,\partial_2Y\rangle_T\partial_1Y_T\\ 
        3\langle\partial_2Y,\partial_2Y\rangle_T\partial_2Y_T+2\langle\partial_1Y,\partial_2Y\rangle_T\partial_1Y_T+\langle\partial_1Y,\partial_1Y\rangle_T\partial_2Y_T
    \end{pmatrix},\text{\ and}  
\end{align*}
\begin{align*}
     &c_T:\R^2\to\R,\quad c_T((x_1,x_2))=&&6\langle\partial_1Y,\partial_1Y\rangle_Tx_1^2+6\langle\partial_2Y,\partial_2Y\rangle_Tx_2^2+2\langle\partial_1Y,\partial_1Y\rangle_Tx_2^2\\
     & &&+2\langle\partial_2Y,\partial_2Y\rangle_Tx_1^2+8\langle\partial_1Y,\partial_2Y\rangle_Tx_1x_2
     \end{align*}
yields
\begin{align*}
  &  \int|\nabla Y_T+\nabla Z_T(u)|^4-c_T(\nabla Z_T(u))-4b_T\cdot\nabla Z_T(u)-a_T\\
  &  =\int[\![\nabla Y_T^4]\!]
    +4[\![\nabla Y_T^3]\!]\cdot\nabla Z_T(u)+4\nabla Y_T\cdot(\nabla Z_T(u))^3
    +(\nabla Z_T(u))^4\\&
    +\sum_{i,j,k,l\in\{1,2\}}2(\delta_{ik}\delta_{jl}+\delta_{il}\delta_{jk}+\delta_{ij}\delta_{kl})[\![\partial_iY_T\partial_j Y_T]\!]\partial_k Z_T(u) \partial_l Z_T(u).
\end{align*}
If we define
\begin{align}
    &\Phi_T(u)\coloneq\int4\nabla Y_T\cdot(\nabla Z_T(u))^3 +4[\![\nabla Y_T^3]\!]\cdot\nabla Z_T(u)\nonumber\\
    &+\sum_{i,j,k,l\in\{1,2\}}2(\delta_{ik}\delta_{jl}+\delta_{il}\delta_{jk}+\delta_{ij}\delta_{kl})[\![\partial_iY_T\partial_j Y_T]\!]\partial_k Z_T(u) \partial_l Z_T(u)
\end{align}
we obtain the representation
\begin{align*}
    F_T(u)=\mathbb{E}\left[ f(Y_T+Z_T(u))+\Phi_T(u)+\Vert\nabla Z_T(u)\Vert_{L^4}^4+\frac{1}{2}\int_0^\infty\Vert u_s\Vert^2_{L^2}\ ds\right].
\end{align*}","status":"unverified"}

