    \end{equation}
    where the constants $K,\kappa>0$ and $p,q\geq 1,1/p+1/q=1$ all depend on $C,C_\alpha,\alpha$ and $\beta$. (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T20:58:10.024930+00:00","domain":"probability theory","id":"claim_aa915079a6c108ebf0541a7fff4ef26ea807bc3512bf1b68fe9f504f6664220e","kind":"lemma","schema_version":1,"statement":"[Lem upplow0 of arXiv:2607.19660, 'Smallest gaps between zeros of stationary Gaussian processes'] We have the following upper bound on $\Omega_k$,
	\begin{equation}
		\begin{split}&\tilde{\tau}_k(x_1,\ldots, x_k)  \\   \leq  &  R^{k}
