{"assumptions":[],"created_at":"2026-10-28T00:32:56.073791+00:00","domain":"probability theory","id":"claim_ab1f82f0a4ab4e82e1173ef691c15bc74b84bd34532eb5ad1c179efc7bcef88d","kind":"theorem","schema_version":1,"statement":"[Proposition prop:reg-V of arXiv:2411.12192, 'Sample path properties and small ball probabilities for stochastic fractional diffusion eq'] Assume the conditions of Lemma (le:sLND-U of the paper) hold. Then, $\{V(t,x),t\ge0,x\in\mathbb{R}^d\}$ is well-defined.
\begin{enumerate}
  \item[(1)] There exists a finite constant $c > 0$  such that for all $x\in\mathbb{R}^d$ and $0< s < t<\infty$, 
  \begin{equation}
    \mathbb E\left[|V(t,x)-V(s,x)|^2\right]^{1/2}\le
    \begin{cases}
      \dfrac{c|t-s|}{s^{1-\theta_1}}, & \mbox{if } \beta+\gamma-2\le0, \\
      \dfrac{c\: t^{\beta+\gamma-2}|t-s|}{s^{-H_0+\frac{\beta}{\alpha}(d-H)}}, & \mbox{if }\beta+\gamma-2>0 .
    \end{cases}
  \end{equation}
   In particular, for any $0<a<b<\infty$, there exists a finite constant $C > 0$ such that for all $x\in\mathbb{R}^d$ and 
   $s,t\in[a,b]$, 
  \begin{equation}
  \mathbb E\left[ \left|V(t,x)-V(s,x)\right|^2 \right] \le C |t-s|^2.
  \end{equation}
   Consequently,  for any $x\in\mathbb{R}^d$, the  function $t\mapsto V(t,x)$ is smoother than $t\mapsto U(t,x)$ on $[a,b]$.

  \item[(2)]
    There exists a finite constant $C > 0$ such that for all $t>0$ and $x,y\in\mathbb{R}^d$ with $|x-y|\le e^{-1}$,
  \begin{equation}
    \begin{split}
       &\mathbb E\left[ \left|V(t,x)-V(t,y)\right|^2 \right] \\
         &\qquad\le
    \begin{cases}
      C\:t^{2H_0+2\gamma-2}\times|x-y|^{2\alpha-2d+2H}, & \mbox{if } 0<\alpha-d+H<1, \\
       C\:t^{2H_0+2\gamma-2}\times|x-y|^2 \log\left(|x-y|^{-1}\right), & \mbox{if } \alpha-d+H=1, \\
      C\:t^{2\beta+2\gamma+2H_0-2-\frac{\beta(2d-2H+2)}{\alpha}}\times|x-y|^2, & \mbox{if } \alpha-d+H>1.
    \end{cases}
    \end{split}
  \end{equation}
