{"assumptions":[],"created_at":"2026-10-26T20:46:55.640840+00:00","domain":"probability theory","id":"claim_ab29021232813e21d271984ab796c1537021607feb481961cd9d00af3485ab03","kind":"theorem","schema_version":1,"statement":"[Proposition 22 (Localized compactness estimates) of arXiv:2605.23529, 'Generalized Bessel-Dunkl diffusions'] Assume \ref{ass:cont}-\ref{ass:sigma}. Let $X^{(n)}$ be the approximating solutions associated with \eqref{eq:kn:defn}. For every $T,r>0$, define
        \begin{equation}
            \chi_r^{(n)} := T\wedge \inf\{t\in[0,\zeta^{(n)}):\ |X^{(n)}(t)|\ge r\},

        \end{equation}
with the convention $\inf\varnothing=\infty$. Then the following hold.

\begin{enumerate}[label=\textup{(\roman*)}]
    \item The laws of the stopped processes
        \begin{equation*}
            \bigl(X^{(n)}(t\wedge\chi_r^{(n)})\bigr)_{0\le t\le T}, \qquad n\in\N,
        \end{equation*}
    form a tight family in $\mathcal C([0,T];\Cc)$.

    \item There exists a constant $C_{r,T}<\infty$, independent of $n$, such
    that
        \begin{equation*}
            \sup_{n\in\N}  \mathbb E \sum_{\alpha\in R_+} A^{(n),\alpha}(\chi_r^{(n)}) \le C_{r,T}.
        \end{equation*}
    In particular, for every $\alpha\in R_+$there exists $C_{\alpha,r,T}<\infty$, independent of $n$, such that
        \begin{equation*}
            \sup_{n\in\N} \mathbb E \int_0^{\chi_r^{(n)}} \frac{k_\alpha^{(n)}(s,X^{(n)}(s))}{\langle X^{(n)}(s),\alpha\rangle}\,ds\le C_{\alpha,r,T}.
        \end{equation*}

    \item For every $\alpha\in R_+$, define the stopped drift measure on $[0,T]$ by
        \begin{equation}
            \mu_{r,T}^{(n),\alpha}(dt) := \mathbf 1_{\{t\le \chi_r^{(n)}\}} \frac{k_\alpha^{(n)}(t,X^{(n)}(t))}{\langle X^{(n)}(t),\alpha\rangle}\,dt.

        \end{equation}
    Then the joint laws of
        \begin{equation*}
            \left(X^{(n)}(\cdot\wedge\chi_r^{(n)}),\bigl(\mu_{r,T}^{(n),\alpha}\bigr)_{\alpha\in R_+}\right), \qquad n\in\N,
        \end{equation*}
    are tight in
        \begin{equation*}
            \mathcal C([0,T];\Cc) \times \prod_{\alpha\in R_+}\mathcal M_+([0,T]),
        \end{equation*}
    where $\mathcal M_+([0,T])$ is equipped with the weak topology.
\end{enumerate}

    Moreover, for every $n\in\N$,
        \begin{equation*}
             \chi_r^{(n)} \uparrow T\wedge\zeta^{(n)} \qquad\text{as } r\to\infty.
        \end{equation*}","status":"unverified"}

