{"assumptions":[],"created_at":"2026-10-27T15:38:04.490906+00:00","domain":"probability theory","id":"claim_ab80195dc4b537b4cecbacc10c8c85ec59998dad0e0e7a16e316d5d602cc6f2a","kind":"lemma","schema_version":1,"statement":"[Lemma lem:lower of arXiv:2607.05054, 'Root Dynamics of Differentiated Polynomials with Rotationally Invariant Structure'] Under the same assumptions, after $ \ell m $ differentiations, the $ j $-th smallest radius $ r_j^{(n,m,\ell)} $ (for $ 1 \leq j \leq n-\ell $) satisfies  
\begin{align}
r_j^{(n,m,\ell)} \geq r_{j+\ell} \prod_{s=1}^{\ell} \left(1 - \frac{1}{\max\left(1, j+s-2 - y\right)}\right).
\end{align}  
In particular, if $ j > y + 2 $, then  
\begin{align}
r_j^{(n,m,\ell)} \geq r_{j+\ell} \frac{j - 2 - y}{j + \ell - 2 - y} \geq r_{j+\ell} \frac{j - 2 - y}{j + \ell}.
\end{align}  
For $ j \leq y + 2 $, the bound holds trivially as the right-hand side is nonpositive.","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T23:20:55.483104+00:00","domain":"probability theory","id":"claim_ab8051ef5cc51284588d7436190c4d72823adfa669d513a1f5d175be58b9c199","kind":"theorem","schema_version":1,"statement":"[Pro rec of arXiv:2411.07158, 'Markov chains on trees: almost lower and upper directed cases'] Let ${\sf U}$ be an {\sf AUD}\xspace irreducible transition matrix on an infinite tree $T$, and $(X_k,k\geq 0)$ a ${\sf U}$-Markov chain. For any set of nodes $A$, denote by
  \[\tau_{A}=\tau_A(X)=\inf\left\{k: X_k\in A\right\}\] the hitting time of $A$; for a single node, as the root $\varnothing$, we write $\tau_{\varnothing}$ instead of $\tau_{\{\varnothing\}}$. Let $T_{\geq h}=\{u \in T, |u|\geq h\}$ be the subset of $T$ consisting of the nodes at distance $\geq h$ from $\varnothing$.
  \begin{itemize} \topsep0pt   \itemsep=0pt   \partopsep=0pt   \parsep=0pt \setcounter{c}{0}
	\addtocounter{c}{1}\item[($\roman{c}$)]  ${\sf U}$ is recurrent on $T$ if and only if for each node $i$ of the first generation ($i\in c_T(\varnothing)$), we have
	\begin{eqnarray}\lim_{b \to +\infty} {\mathbb{P}}(\tau_{\varnothing} < \tau_{T_{\geq b}}~|~X_0=i)=1.\end{eqnarray}
	\addtocounter{c}{1}\item[($\roman{c}$)] 
Let  $T_{i,< h}=\{u \in T_i,~|u|<h\}$ be the restriction of the subtree $T_i$ to the $h-1$ first levels (of $T$), and $U_{[i,<h]}$ be the matrix obtained by keeping only the rows and columns of ${\sf U}$ corresponding to the elements of $T_{i,< h}$ (and ${\sf U}^{(i)}_{[i,<h]}$ for the same matrix, deprived from the row and column indexed by $i$). We have:
	\begin{eqnarray}
	{\mathbb{P}}(\tau_{\varnothing} <  \tau_{T_{\geq h}}~|~X_0=i)=\frac{\det({\sf Id}-{\sf U}^{(i)}_{[i,<h]})}{\det({\sf Id} -{\sf U}_{[i, <h]})} {\sf U}_{i,\varnothing}. 
	\end{eqnarray}
\end{itemize}\vspace{-2em}~","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-28T01:10:08.765732+00:00","domain":"probability theory","id":"claim_ab827e4a739f25664d7b3dae9f115bd7fc77f149dbd7cb03673809664fd1450f","kind":"lemma","schema_version":1,"statement":"[Lem thm:master-lemma of arXiv:2411.18155, 'Besov regularity of random wavelet series'] Let $d\in\mathds{N}$, $p\in (0,\infty)$, and $\beta \in\mathds{R}$ such that $\beta <-\frac{d}{p}$.
Let further $(\xi_{j,t,m})_{(j,t,m)\in\mathds{N}_0\times\left\{F,M\right\}^d\times\mathds{Z}^d}$ be a family of random variables.
Then for all $j\in\mathds{N}_0$ and $t\in \left\{F,M\right\}^d$, we have
\begin{equation}
Z_{j,t}\mathrel{\mathop:}= \mnorm{\lr{\lr{1 + \frac{\left\lVertm\right\rVert_\infty}{2^j}}^\beta \abs{\xi_{j,t,m}}}_{m\in\mathds{Z}^d}}_{\ell_p}\lesssim 2^{j\frac{d}{p}} \cdot \Xi^{\frac{1}{p}},
\end{equation}
where the implied constant only depends on $d$, $\beta$, and $p$.
Here
\begin{align}
\Xi_t&\mathrel{\mathop:}= \sup_{j \in \mathds{N}_0} \lr{\frac{1}{M_j} \sum_{\tau=1}^{M_j} \abs{\xi_{j,t,\phi(\tau)}}^p+\sup_{\ell\geq j} \frac{1}{N_\ell} \sum_{\tau=M_\ell + 1}^{M_{\ell+1}} \abs{\xi_{j,t,\phi(\tau)}}^p}\nonumber\\
\intertext{for $t\in\left\{F,M\right\}^d$, and}
\Xi&\mathrel{\mathop:}= \max_{t\in\left\{F,M\right\}^d}\Xi_t
\end{align}
where $\phi:\mathds{N}\to \mathds{Z}^d$ is a bijection such that $\tau\mapsto \left\lVert\phi(\tau)\right\rVert_\infty$ is nondecreasing, and for $j\in\mathds{N}_0$, we set
\begin{align*}
N_j&\mathrel{\mathop:}=\#\setcond{m\in\mathds{Z}^d}{2^j<\left\lVertm\right\rVert_\infty\leq 2^{j+1}},\\
\intertext{and}
M_j&\mathrel{\mathop:}= \#\setcond{m\in\mathds{Z}^d}{\left\lVertm\right\rVert_{\infty}\leq 2^j}=(2^{j+1}+1)^d.
\end{align*}","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-26T20:51:30.072301+00:00","domain":"probability theory","id":"claim_ab8299a84d7a40be2abdad2a6437f8f3d633a86bf67cca30890720f7fdb67aa5","kind":"lemma","schema_version":1,"statement":"[Lemma 25 of arXiv:2606.01832, 'MA(1) processes with uniform innovations conditioned to stay positive in the non-expanding'] It holds
