{"assumptions":[],"created_at":"2026-10-27T23:06:42.719703+00:00","domain":"probability theory","id":"claim_abcd19e89cb1f0cac0ab5cf925c2ce8c3a44fbe473a89904023623f9bb58b0b7","kind":"lemma","schema_version":1,"statement":"[Lemma prop:concentration of arXiv:2411.04116, 'Poisson genericity in numeration systems with exponentially mixing probabilities'] Let $\mu$ be an invariant and exponentially $\psi$-mixing measure on $\Omega^{\mathbb N}$. 
Let $k\in \mathbb N$ be  large enough and $j\ge 0$. Also, let $S\subset \mathbb R^{+}$ be a finite union of bounded intervals and denote by $\sup S$ the supremum of $S$. 
\begin{enumerate}

\item   
For  
 $\varphi_{k,S}:\Omega^\mathbb N \to \mathbb R$, 
$
\varphi_{k,S}(x)={\mathds{E}}_{\mu_k}[M_k^x(S)]
$ 
we have, for any $t>0$,
\begin{align*}
    \mu\pare{\{ x\in \Omega^\mathbb N: \abs{\varphi_{k,S}(x) - {\mathds{E}}_\mu [\varphi_{k,S}] } \geq t \}} 
    \leq 
    2\exp\pare{
\frac{-t^2}
    {\|\Delta\|^28k^4 (\sup S) K^2 \rho^k}}.
\end{align*}

\item For  
 $\varphi_{k,j,S} : \Omega^{\mathbb N} \to [0,1]$,
$
\varphi_{k,j,S} (x)=\mu_k(\{w\in\Omega^k: M_k^x(w)(S)=j\})
$
we have, for any $t > 0$,
\begin{align*}
    \mu\pare{\{ x\in \Omega^\mathbb N: \abs{\varphi_{k,j,S}(x) - {\mathds{E}}_\mu [\varphi_{k,j,S}] } \geq t \}} 
    \leq 
    2\exp\pare{{\frac{-t^2}{\|\Delta\|^28 k^2 (\sup {S})     K^2 \rho^k} }}.
\end{align*}

\end{enumerate}
The numbers   $\rho\in (0,1)$, and $K>0$
 are the contraction ratio and the constant 
given in (equation eq:rhoK of the paper); and
$\Delta$ is the matrix of $\eta$-mixing coefficients associated with the mixing measure $\mu$.","status":"unverified"}

