{"assumptions":[],"created_at":"2026-10-27T17:38:58.714723+00:00","domain":"probability theory","id":"claim_ac109671a3eca8158581e25d45af7ab1356cab272c7e1ff47b0f264100ec9faa","kind":"definition","schema_version":1,"statement":"[Definition def:bbphipt of arXiv:2511.06321, 'Torus scaling limits and the plateau of the critical weakly coupled $|\varphi|^4$ model in'] On $\cV_{\varnothing}$ we define projections
\begin{align}
	p^{(\km_1)}
		& : (\vec{\nu}, \vec{g})  \mapsto \nu^{(\km_1)} ,  \qquad
	q^{(\km_2)} : (\vec{\nu}, \vec{g})  \mapsto g^{(\km_2)}  
\end{align}
for $\km_1 \in \ko_2 \cup \ko_{2,\nabla}$ and $\km_2 \in \ko_4 \cup \ko_{4,\nabla}$.
For subsets $A \subset \{ 0,1,2,3 \}$ and $B \subset \{0,1\}$,  we define projections $p^{A}$ and $q^{B}$ by 
\begin{align}
	p^{A}
		& : (\vec{\nu}, \vec{g})  \mapsto \vec{\nu}^{A} := (\nu^{(\km_1)} )_{\km_1 \in \cup_{i \in A} \kA_i }, \\
	q^{B} 
		&: (\vec{\nu}, \vec{g} ) \mapsto 
		\vec{g}^{B} :=
	 	(g^{(\km_2)} )_{\km_2 \in \cup_{i \in B} \kB_i  }  .
\end{align}
Also,  we denote for $V \in \cV_\varnothing$
\begin{align}
	V^{(\km)} = \begin{cases}
