{"assumptions":[],"created_at":"2026-10-28T01:29:08.611491+00:00","domain":"probability theory","id":"claim_ac197fc3ab119568154bab1617b400e540320f9301f8aefcb59feb626dc6e682","kind":"concept","schema_version":1,"statement":"[Lemma lem-LF-SLE of arXiv:2411.19810, 'Radial conformal welding in Liouville quantum gravity'] Let $W \in (0, \frac{\gamma^2}2)$ and $\alpha = Q - \frac W{2\gamma}$. 
	    Sample $(\psi, \eta^\mathrm{wp})$ from $\frac1{2\pi(Q-\alpha)} \mathrm{LF}_{\mathbb C}^{(\alpha, 0), (\gamma, 1), (2Q-\alpha, \infty)} \times \mathrm{SLE}_\kappa^\mathrm{wp}(W-2)$. For each connected component $B$ of $\mathbb{C} \backslash \eta^\mathrm{wp}$, let $p_B$ and $q_B$ be the first and last points of $\partial B$ hit by $\eta^\mathrm{wp}$. Let $\tilde \mathcal{W}$ be the collection of all quantum surfaces $(B, \psi, p_B, q_B)/{\sim_\gamma}$, and  endow $\tilde \mathcal{W}$ with the ordering where $(B_1, \psi, p_{B_1}, q_{B_1})/{\sim_\gamma}$ precedes $(B_2, \psi, p_{B_2}, q_{B_2})/{\sim_\gamma}$ if $\eta^\mathrm{wp}$ hits $q_{B_1}$ for the last time before it hits $q_{B_2}$ for the last time. 


	    Let $B_\bullet$ be the connected component of $\mathbb{C} \backslash \eta_0^\mathrm{wp}$ containing $1$, and let $\mathcal{B}_\bullet = (B_\bullet, \psi, 1, p_{B_\bullet}, q_{B_\bullet})/{\sim_\gamma}$. Let $ \mathcal{D} \subset \tilde \mathcal{W}$ (resp.\ $\mathcal{W} \subset \tilde \mathcal{W}$) be the ordered collection of elements that come before (resp.\ after) $(B_\bullet, \psi, p_{B_\bullet}, q_{B_\bullet})/{\sim_\gamma}$. Then the joint law of $(\mathcal{D}, \mathcal{B}_\bullet, \mathcal{W})$ is $(1 - \frac{2W}{\gamma^2})^2 {\mathcal{M}}^\mathrm{disk}_{0,2}(W) \times {\mathcal{M}}^\mathrm{disk}_{1,2}(\gamma^2 - W) \times \mathcal{M}^\mathrm{wed}(W)$. (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-28T02:28:34.976463+00:00","domain":"probability theory","id":"claim_ac1b8f2aa008ef9c6a1bbcaeba8daaeb014479d7809b42d56b3c029e6cd71df2","kind":"theorem","schema_version":1,"statement":"[Cor thm:Corner of the invertible matrix of arXiv:2412.05999, 'Non-Archimedean GUE corners and Hecke modules'] Let $t=1/q$, and $m>n\ge 1$ be integers.
\begin{enumerate}[left=0pt]
\item(Alternating case)\begin{enumerate}[left=0pt]
\item Let $A$ be the top left $2n\times2n$ submatrix of a Haar-distributed element of $\Alt_{2m}(\mathfrak{o})\cap \mathrm{GL}_{2m}(\mathfrak{o})$. Then $\SN^{\alt}(A)\in\Sig_n^+$ has distribution given by the Hall-Littlewood measure $\mathbf{P}_{2n<2m}^{\alt}(\cdot\mid0)$ defined by

\begin{equation}
\mathbf{P}_{2n<2m}^{\alt}(\lambda\mid0)=\frac{P_\lambda(1,t^2,\ldots,t^{2n-2};t^2)Q_\lambda(t,t^3,\ldots,t^{2m-2n-1};t^2)}{\Pi_{t^2}(1,t^2,\ldots,t^{2n-2};t,t^3,\ldots,t^{2m-2n-1})}.
\end{equation}

\item Let $A$ be the top left $(2n+1)\times(2n+1)$ submatrix of a Haar-distributed element of $\Alt_{2m}(\mathfrak{o})\cap \mathrm{GL}_{2m}(\mathfrak{o})$. Then $\SN^{\alt}(A)\in\Sig_n^+$ has distribution given by the Hall-Littlewood measure $\mathbf{P}_{2n+1< 2m}^{\alt}(\cdot\mid0)$ defined by

\begin{equation}
\mathbf{P}_{2n+1< 2m}^{\alt}(\lambda\mid0)=\frac{P_\lambda(1,t^2,\ldots,t^{2n-2};t^2)Q_\lambda(t^3,t^5,\ldots,t^{2m-2n-1};t^2)}{\Pi_{t^2}(1,t^2,\ldots,t^{2n-2};t^3,t^5,\ldots,t^{2m-2n-1})}.
\end{equation}
\end{enumerate}

\item(Hermitian case)Let $A$ be the top left $n\times n$ submatrix of a Haar-distributed element of $\Her_m(\mathfrak{o})\cap \mathrm{GL}_m(\mathfrak{o})$.  Then $\SN^{\her}(A)
\in\Sig_n^+$ has distribution given by the Hall-Littlewood measure $\mathbf{P}_{n<m}^{\her}(\cdot\mid0)$ defined by

\begin{equation}
\mathbf{P}_{n<m}^{\her}(\lambda\mid0)=\frac{P_\lambda(1,-t,t^2,\ldots,(-t)^{n-1};-t)Q_\lambda(t,-t^2,\ldots,-(-t)^{m-n};-t)}{\Pi_{-t}(1,-t,t^2,\ldots,(-t)^{n-1};t,-t^2,\ldots,-(-t)^{m-n})}.
\end{equation}
\end{enumerate}","status":"unverified"}

