{"assumptions":[],"created_at":"2026-10-26T20:50:30.552784+00:00","domain":"probability theory","id":"claim_ac7a4cc1a9e4109faf9865c07dc9e1751ddc1adca1c91cecf9ee119ea344ebce","kind":"definition","schema_version":1,"statement":"[Definition 1 (self-normalized importance sampling measure) of arXiv:2605.30055, 'The Wasserstein cost of importance sampling'] Let $f,g$ be two probability densities on $(0,1)^d$. Let $(X_i)$ be a sequence of iid random variables with distribution $f$. The \emph{self-normalized importance sampling measure} for $g$ based on the samples from $f$ is defined as 
    \begin{equation}
        \hat{g}_n = \frac{1}{Z_n}\sum_{i=1}^n W_i \delta_{X_i}, 
    \end{equation}
    where $W_i = g(X_i)/f(X_i)$ are the importance weights and $Z_n$ is the normalization constant
    \begin{equation}
        Z_n = \sum_{i=1}^n W_i.
    \end{equation}","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-28T02:10:43.923405+00:00","domain":"probability theory","id":"claim_ac7cbefebde7f909bde8432d8bb716d7eabc877c40e573459bda1e7e95bd5297","kind":"definition","schema_version":1,"statement":"[Defn of arXiv:2412.04527, 'Critical Drift for Brownian Bees and a Reflected Brownian Motion Invariance Principle'] A stochastic process $(Y_n)_{n\in\mathbb{N}}$ with state space $\mathcal{Y}$ is called a \textbf{recurrent and strongly aperiodic Harris chain} if $\exists A\subseteq \mathcal{Y}$ such that:
\begin{itemize}
    \item $\exists \varepsilon >0$ and probability measure $q$ on $A$ such that $\mathbb{P}_\xi(Y_1\in C)\geq \varepsilon q(C) \; \; \forall \xi \in A, C\subseteq A$ 
    \item the hitting time of $A$ is almost surely finite for any initial $Y_0 \in \mathcal{Y}$; that is $\mathbb{P}_\xi(\tau_A < \infty)=1 \; \; \forall \xi \in \mathcal{Y}$ where $\tau_A := \inf\{ n\geq 1: Y_n\in A\} $.
\end{itemize}
 Further, we call the proces \textbf{positive Harris recurrent} if $\sup_{\xi \in A}\mathbb{E}_\xi[\tau_A]<\infty $, and \textbf{null Harris recurrent} otherwise.","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-26T20:48:17.125582+00:00","domain":"probability theory","id":"claim_ac7d81d83a72c20e920d6edd7fa0baf2edbbd53657faeb3fc3a5980f46c8bc12","kind":"lemma","schema_version":1,"statement":"[Lemma 18 of arXiv:2605.27818, 'Exponential decay of mass for inertial coalescing particles with Hamiltonian noise'] Fix $\vt\in(0,\vt_1)$ and $\eta\in(0,\min(\eta_1,c_*\vt^2))$. Then, for every
$\al>0$, $x\in D_{\mathfrak{r}}$, and  $s\geq T_{\eta,\al}$, we have
\begin{equation}
\int_s^{s+1}\div g_\al(\phi_\al(r,x))\,dr\;\geq\;
\chi_\alpha\bigg(\,c_2\,\vt^2-(c_2\vt^2+c_1\vt)\int_s^{s+1}\ind_{F_{\eta,\vt}}(\phi_\al(r,x))\,dr\bigg),\quad\P\text{-a.s.}
\end{equation}
where $\chi_\alpha$ is defined as in \eqref{sfm20}","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-26T20:52:17.366630+00:00","domain":"probability theory","id":"claim_ac7ecd6b2efe5f46158fed4c237a3bfbb174ff3281d5549b34f7cab12fb3e910","kind":"concept","schema_version":1,"statement":"[Proposition 9 of arXiv:2606.02786, 'Non-local SDEs, critical drifts and local blow-ups'] Assume that Borel measurable vector field $b$ satisfies  {\rm($\mathbf{H}_1$)}.
Then, for every $p>\frac{\theta}{\alpha}$, provided that $\theta$  in the definition  \eqref{rho_def}  of weight $\rho$ is chosen so that $d<\theta<d+\alpha$ and $\kappa$ is fixed sufficiently small (that is, depending only on $d$, $\alpha$ and the norms of $b_{\mathfrak b}$ and $b_\mathfrak{s}$), the following are true for all $\lambda>1$:

\begin{enumerate}
\item[{\rm (\textit{i})}]
\begin{align}
\||b|^{\frac{1}{p}}(\lambda \pm \partial_t  + & (- \Delta)^{\frac{\alpha}{2}} )^{(-1+\frac{1}{\alpha})\frac{1}{p}}\|_{L_\rho^p(\mathbb{R}^{1+d}) \rightarrow L_\rho^p(\mathbb{R}^{1+d})} \notag \\
& \leq K_1\sup_{x \in \mathbb R^d}\|\mathbf{1}_{Q_2(x)}|b_{\mathfrak s}|^{\frac{1}{\alpha-1}}\|^{\frac{\alpha-1}{p}}_{E_{1+\epsilon}}  + K_2 
A_{\lambda,p}
 \langle |b_{\mathfrak s}| \rangle^{\frac{1}{p}} + K_3 \lambda^{-\frac{1}{p}(1-\frac{1}{\alpha})}\|b_{\mathfrak b}\|^{\frac{1}{p}}_{L^\infty(\mathbb R^{1+d})} ,
\end{align}

\item[{\rm (\textit{ii})}]
\begin{align}
\|(\lambda \pm \partial_t  + & (- \Delta)^{\frac{\alpha}{2}} )^{(-1+\frac{1}{\alpha})\frac{1}{p'}}|b|^{\frac{1}{p'}}\|_{L_\rho^p(\mathbb{R}^{1+d}) \rightarrow L_\rho^p(\mathbb{R}^{1+d})} \notag \\
& \leq K_1\sup_{x \in \mathbb R^d}\|\mathbf{1}_{Q_2(x)}|b_{\mathfrak s}|^{\frac{1}{\alpha-1}}\|^{\frac{\alpha-1}{p'}}_{E_{1+\epsilon}} + K_2 
A_{\lambda,p'}
 \langle |b_{\mathfrak s}| \rangle^{\frac{1}{p'}} + K_3 \lambda^{-\frac{1}{p'}(1-\frac{1}{\alpha})}\|b_{\mathfrak b}\|^{\frac{1}{p'}}_{L^\infty(\mathbb R^{1+d})}. 
\end{align}
for constants $K_i=K_i(d,\alpha,p,\epsilon,\theta,\kappa)$.

\end{enumerate} (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T12:13:31.971835+00:00","domain":"probability theory","id":"claim_ac89b258448a508a55d2a240a62f381c1a3f9ed95a525251ce210af64c0fd36f","kind":"concept","schema_version":1,"statement":"[Theorem thm:shifted_chain_rule of arXiv:2506.23062, 'Shifted Composition IV\@: \\ Toward Ballistic Acceleration for Log-Concave Sampling'] Let $\mathsf{X}$, $\mathsf{X}'$, $\mathsf{Y}$ be three jointly defined random variables on a standard probability space $\Omega$. Let $\mathbf{P}$, $\mathbf{Q}$ be two probability measures over $\Omega$, with superscripts denoting the laws of random variables under these measures. Then

	\begin{align*}
		\KL(\mathbf{P}^{\mathsf{Y}} \mathbin{\|} \mathbf{Q}^{\mathsf{Y}})
		&\leqslant \KL(\mathbf{P}^{\mathsf{X}'} \mathbin{\|} \mathbf{Q}^{\mathsf{X}}) + \inf_{\gamma \in \mathscr{C}(\mathbf{P}^{\mathsf{X}}, \mathbf{P}^{\mathsf{X}'})} \int \KL(\mathbf{P}^{\mathsf{Y}\mid \mathsf{X}=x} \mathbin{\|} \mathbf{Q}^{\mathsf{Y}\mid \mathsf{X}=x'}) \,\gamma(\mathrm{d} x, \mathrm{d} x')\,.
	\end{align*} (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T22:55:27.164053+00:00","domain":"probability theory","id":"claim_ac8f368723c47d6fdda2d5d6482d42494fcb1aa89781e35006e3c12b38ba453a","kind":"definition","schema_version":1,"statement":"[Definition \cite{kottwitz1992svfinitefields}, §5 of arXiv:2609.04072, 'Oort's conjecture for split unitary Shimura varieties'] Fix a compact open subgroup $K^p \subset \mathbf G(\mathbb{A}_f^p)$. Let $\operatorname{Sh}_{K^p}$ denote the moduli stack on schemes over  $\mathcal{O}_E \otimes \mathbb{Z}_{(p)}$, sending $S$ to the groupoid whose objects consist of quadruples $(A,i,\lambda,\overline{\eta})$, where
    \begin{itemize}
        \item $A$ is an abelian scheme over $S$. 
        \item $i: \mathcal{O}_B \otimes \mathbb{Z}_{(p)} \to \operatorname{End}_S(A) \otimes \mathbb{Z}_{(p)}$ is an $\mathcal{O}_B$-action that satisfies the Kottwitz condition
        \begin{equation*}
            \det(i(b) \mid \operatorname{Lie} A) = \det (b \mid V_1)
        \end{equation*}
        for all $b \in \mathcal{O}_B$. 
        \item $\lambda: A \to A^\vee$ is a prime-to-$p$ polarization, i.e.~a prime-to-$p$ quasi-isogeny which is symmetric with respect to double-duality $A \simeq (A^\vee)^{\vee}$, induces a pointwise polarization $n\lambda$ for some $n \gg 0$, and such that the induced Rosati involution on $\operatorname{End}_S(A) \otimes \mathbb{Z}_{(p)}$ is compatible with the involution on $\mathcal{O}_B$ via the $\mathcal{O}_B$-action $i$.
        \item $\overline{\eta}$ is a $K^p$-level structure (see [kottwitz1992svfinitefields] for details).
    \end{itemize}
    An isomorphim of quadruples is a prime-to-$p$ quasi-isogeny that respects the $\mathcal{O}_B$-action, the $K^p$-level structure and the polarizations up to a similitude factor in $\mathbb{Z}_{(p)}^\times$.","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-26T19:42:47.764841+00:00","domain":"probability theory","id":"claim_ac91273aa3f854d41058df61b649d8c419d2746157e084bb55ef3e71a701a5bf","kind":"theorem","schema_version":1,"statement":"[Thm 5 (Perturbation formula) of arXiv:2604.12797, 'A free boundary problem for the mean-field limit of diffusing particles with nonlinear bou'] Restricted to the event $\{X_t^{i,n}\neq \dagger\}$, for $t>0$, the conditional law of $X_t^{i,n}$ given $\sigma(\cup_{s>0}\mathcal{{G}}_{s}^{i,n})$ has a random density $p^{i,n}(t,x)$, which is supported on $[\hat{A}_t^{i,n},\infty)$ and  jointly continuous in $x
    \geq \hat{A}_t^{i,n}$ and $t>0$. This density can be expressed as
	\begin{equation}
	p^{i,n}(t,x)=\hat{p}^{i,n}\Bigl(t\,,\int_{\hat{A}^{i,n}_t}^x \frac{1}{\sigma(t,y)}\dy  \Bigr)\frac{1}{\sigma(t,x)},\quad \text{for all}\quad x \geq \hat{A}_t^{i,n},\,t> 0,
	\end{equation}
	where $\hat{p}^{i,n}$ is supported on $[0,\infty)$ and satisfies the implicit Volterra relation
	\begin{align}
	\hat{p}^{i,n}(t,x) & =\int_0^\infty N(x,t,y,0)\hspace{1pt} \di \hat{\mu}^{i}_0(y) +\int_{0}^{t}\int_{0}^{\infty}\partial_{y}N(x,t; y ,r)\tilde{b}^{i,n}(r, y)\hat{p}^{i,n}(r,y)\dy \dr \nonumber\\
	& \qquad\; -\int_{0}^{t}N(x,t;0,r)\gamma(r,\hat{{C}}_{r}^{i,n})\sigma(r,\hat{{A}}_{r}^{i,n})^2p^{i,n}(r,\hat{A}^{i,n}_r)\dr
	\end{align}
     with $\hat{\mu}_0^{i}=\mathrm{Law}(X_0^i) \circ (\int_{a_0}^\cdot \frac{1}{\sigma(0,y)}\dy)^{-1}$.    Furthermore, for any $T>0$, we have
\begin{equation}
	\hat{p}^{i,n}(t,x) \leq \frac{C_1}{\sqrt{t}} \exp\Bigl( -c_1x^{2}\Bigr),\quad \text{for all}\quad x\in[0,\infty), \,t\in(0,T],
	\end{equation}
for some constants $c_1,C_1>0$, and, in turn, there are constants $c_2,C_2>0$ such that
	\begin{equation}
		p^{i,n}(t,x) \leq \frac{C_2 }{\sqrt{t}} \exp\Bigl( -c_2(x-\hat{A}^{i,n}_t)^2 \Bigr),\quad \text{for all}\quad x\in[\hat{A}^{i,n}_t,\infty), \,t\in(0,T],
	\end{equation}
	These constants can be chosen independently of $i=1,\ldots,n$ and $n\geq 1$, and we note that \eqref{eq:lamperti_aronson}--\eqref{eq:particle_aronson} confirm that the perturbation formula \eqref{eq:density_rep-1} is well-defined.","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T06:47:07.702307+00:00","domain":"probability theory","id":"claim_ac91e44c9756077b6dc047658a158d277397a35a0e3218f3ea25d46d05c64ba7","kind":"lemma","schema_version":1,"statement":"[Lemma 18 of arXiv:2608.06011, 'Strong averaging principle for multiscale time-inhomogeneous SDEs with multiplicative $\al'] For any $x\in\br^n$ and $T,t>0$, there exists $C>0$ such that
       \begin{equation*}
           \left|\frac{1}{T}\int_t^{t+T}\bar{b}(r_1,r_2,x)\d r_2-\frac{1}{\tau_2}\int_0^{\tau_2}\bar{b}(r_1,r_2,x)\d r_2\right|\leq \frac{C\tau_2}{T}(1+|x|).
       \end{equation*}","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T17:48:24.621735+00:00","domain":"probability theory","id":"claim_ac9499ddc2b193332446a7a9bbb38fdc4b9367fa523139431bfd1f63d35fdd4a","kind":"lemma","schema_version":1,"statement":"[Lemma mg_problem_psi of arXiv:2601.04997, 'Fluctuations of the Boundary-Driven Symmetric Zero-Range Process from the NESS'] Let $\mathscr{Y}$ be an $\mathcal{S}'$-valued stochastic process satisfying (equation eq:martingale_problem of the paper) and items i) and ii) of Proposition~(prop:uniqueness_neg of the paper) for each $H\in\mathcal{S}$. Fix $\beta\in(0, 1)$ and $\alpha>\frac{1}{1-\beta}$. For $\psi\in\{\psi_{\alpha, \beta}, \tilde\psi_{\alpha, \beta}\}$, the process $\{\mathscr{\tilde M}_t(\psi), t\in[0, T]\}$ defined via 
\begin{equation}
    \mathscr{\tilde M}_t(\psi):=\mathscr{Y}_t(\psi)-\mathscr{Y}_0(\psi)-\int_0^t\mathscr{Y}_s(\mathfrak{A}_\theta \psi)\de s
\end{equation}
is a martingale with continuous trajectories and with quadratic variation given by
\begin{equation}
    \scal{\mathscr{\tilde M}(\psi)}_t=t\|\partial_u \psi\|_{L^{2, \theta}}^2.
\end{equation}
Moreover, the process $\{\mathscr{Y}_t(\psi), t\in[0, T]\}$ has continuous trajectories.","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T11:57:07.200474+00:00","domain":"probability theory","id":"claim_ac959148ede570f3ec1934d28557ad3caf8e5ca5e60d436706c7585f560bc01f","kind":"theorem","schema_version":1,"statement":"[Proposition prop:bound-partition-functions of arXiv:2509.04333, 'The limiting law of the Discrete Gaussian level lines'] Let $Z^n_{A', B'} = \sum_{\gamma \in \ensuremath{\mathcal P}_{\mathbb Z^2}(A', B')}w^n(\gamma)$. Then, for all $k \leq \frac{a}{1-\delta}\log_2\log L$, uniformly over all $A', B' \in \ensuremath{\mathcal R}_k$, we have
		\begin{equation*}
			Z^n_{A', B'} \leq z_ke^{{\ensuremath{\mathscr G}}^n_\mu(\ell_{A', B'}, \theta_{A', B'}})
		\end{equation*}
