{"assumptions":[],"created_at":"2026-10-27T20:53:00.822370+00:00","domain":"probability theory","id":"claim_ada579d71db9e69957ba4b52ff39d8cea3927d452bee06346abc4ae229dc91f6","kind":"definition","schema_version":1,"statement":"[Definition Def: grafting of arXiv:2607.18635, 'Remainders of generalised Taylor expansions and a priori bounds for rough differential equ'] For $\tau\in{\mathcal T}, w\in{\mathcal F}$ we recursively define the grafting of trees in $\mathcal{H}$ as
		\begin{equation}
			\tau\curvearrowright\one=0\,,\qquad\tau\curvearrowright [w]_i=[\tau\cdot w+\tau\curvearrowright w]_i\,,\qquad i=1,\ldots, d\,,
		\end{equation}
		where we implicitly extend $\curvearrowright$ to forests on the right by Leibniz rule, i.e, for $\tau_1,\ldots, \tau_k\in{\mathcal T}$
		\begin{equation}
			\tau\curvearrowright(\tau_1\cdots\tau_k)=\sum_{i=1}^k\tau_1\cdots(\tau\curvearrowright\tau_i)\cdots\tau_k\,.
		\end{equation}","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-26T19:36:04.994004+00:00","domain":"probability theory","id":"claim_ada5edeed5e36651b272ad49e2736e8cfb66bbf7f04473093b7ec5900e7f6522","kind":"definition","schema_version":1,"statement":"[Definition 7 of arXiv:2604.01685, 'Probability with Measure\footnote{Lecture notes. University of Ljubljana.}'] Let $f:\Omega\to \Omega'$. 

	Given a $\sigma$-field $\FF'$ on $\Omega'$ we define 
	\begin{equation*}
		\sigma^{\FF'}(f):=f^{-1}(\FF'):=\{f^{-1}(A'):A'\in \FF'\},
	\end{equation*}
the initial structure for $f$ relative to $\FF'$ (or the $\sigma$-field generated by $f$ relative to $\FF'$, also the pull-back of $\FF'$ by $f$). 

Given a $\sigma$-field $\FF$ on $\Omega$ we define 
\begin{equation*}
	\sigma_{\FF}^{\Omega'}(f):=\{A'\in 2^{\Omega'}:f^{-1}(A')\in \FF\},
\end{equation*}
the final structure on $\Omega'$ for $f$ relative to $\FF$ (or the push-forward to $\Omega'$ of $\FF$ by $f$).

Given a $\sigma$-field $\FF'$ on $\Omega'$  and a $\sigma$-field $\FF$ on $\Omega$, we say that $f$ is $\FF/\FF'$-measurable \deff $f^{-1}(A')\in \FF$ for all $A'\in \FF'$.","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T06:09:23.962738+00:00","domain":"probability theory","id":"claim_ada739da1591361bd83b10c8d31aeb69d639b054f73ae36605d0db4a9f7fa180","kind":"concept","schema_version":1,"statement":"[Lem 6 of arXiv:2607.22414, 'Asymptotic fluctuations in supercritical multi-type Crump--Mode--Jagers processes'] Suppose that~\ref{assumpt:Malthusian alpha} holds.
