{"assumptions":[],"created_at":"2026-10-26T19:27:36.717494+00:00","domain":"probability theory","id":"claim_addc5c4724b08e6f4b21a31bdca19515176055fdb76c83b7fb8361d5c5d6dbf0","kind":"definition","schema_version":1,"statement":"[Definition 1 of arXiv:2511.13404, 'Asymptotic stability and mean ergodicity of Feller processes on Polish spaces'] Let $(\mathcal{P}(\X), \tau)$ be a topological space, where $\tau$ is a topology on $\mathcal{P}(\X)$.
    \begin{enumerate}[label=(\roman*)]
        \item $\Phi$ is called \textit{$\tau$-asymptotically stable} if there exists a unique invariant measure $\mu \in \mathcal{P}(\X)$ such that:
        \begin{equation*}
            \lim_{t \to \infty} P_t(x, \cdot) = \mu \quad \text{in } (\mathcal{P}(\X), \tau), \quad \forall\, x \in \X.
        \end{equation*}
        \item $\Phi$ is called \textit{$\tau$-mean ergodic} if there exists a unique invariant measure $\mu \in \mathcal{P}(\X)$ such that:
        \begin{equation*}
            \lim_{t \to \infty} \frac{1}{t} \int_0^t P_s(x, \cdot) \d s = \mu \quad \text{in } (\mathcal{P}(\X), \tau), \quad \forall\, x \in \X.
        \end{equation*}
    \end{enumerate}","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-28T02:47:21.592337+00:00","domain":"probability theory","id":"claim_addec0ff9ddd52e79714b50d4cd07a8f6211d250d5f0cd9ed5288ca4dbb495c2","kind":"lemma","schema_version":1,"statement":"[Lemma Bound for J_4 of arXiv:2412.08932, 'Gaussian heat kernel asymptotics for conditioned random walks'] For any  $\varepsilon \in (0,\frac{1}{2}]$, there exists a constant $c=c_{\varepsilon}>0$ 
