{"assumptions":[],"created_at":"2026-10-26T19:43:16.149474+00:00","domain":"probability theory","id":"claim_ade76fd1a60da177df2f29608975790800a42f761bd5df0741e464d41774d614","kind":"concept","schema_version":1,"statement":"[Lema 20 of arXiv:2604.13387, 'Multiradial Schramm-Loewner evolution: \\ Infinite-time large deviations and transience'] [Varadhan's lemma; see, e.g.,~\cite{Dembo-Zeitouni:Large_deviations_techniques_and_applications}, Lemmas~4.3.4 and 4.3.6]

Suppose that the probability measures $(P^\kappa)_{\kappa>0}$ satisfy an LDP in a topological space $X$
with good rate function $E$. 
Let $\Phi \colon X \to \bR$ be a function bounded from above, and let $Q^\kappa$ be a measure on $X$ absolutely continuous with respect to $P^\kappa$ with Radon-Nikodym derivative 
\begin{align*}
\frac{\ud Q^\kappa}{\ud P^\kappa}(x) = \exp \Big(\frac{1}{\kappa} \Phi(x) \Big) , \qquad x \in X . 
\end{align*}
Then, the following hold.
\begin{enumerate}
\item  
If $\Phi$ is upper semicontinuous, then for any closed subset $F$ of $X$, 
\begin{align*}
\limsup_{\kappa\to 0+} \kappa \log Q^\kappa[F]
\leq - \inf_{x \in F} \big(E(x) - \Phi(x)\big) .
\end{align*}
\item  
If $\Phi$ is lower semicontinuous, then for any open subset $O$ of $X$,
\begin{align*}
\liminf_{\kappa\to 0+} \kappa \log Q^\kappa[O]
\geq - \inf_{x \in O} \big( E(x) - \Phi(x)\big).
\end{align*}
\end{enumerate} (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-28T00:22:21.903858+00:00","domain":"probability theory","id":"claim_ade86d0bd90237aa82a7a3f505416a5b99a307211129d69a4701be379794b1fa","kind":"theorem","schema_version":1,"statement":"[Proposition prop:characterization_prod of arXiv:2411.11425, 'Non-equilibrium steady states with a spatial Markov structure'] For notational convenience we write $\theta_0 :=a$ and $ \theta_{n+1}:=b$. The following statements are equivalent:\\

 \begin{enumerate}
     \item $\{\Lambda^n\}_{n \geq 1}$ is two-sided Markov.\\

     \item For all $n \geq 1$, $a,b \in \mathbb{R}^+$ and $\theta_1, ..., \theta_n \in I_{a,b}$ we have

    \begin{equation}

    \begin{cases}
        \Lambda_{a,b}^n(\theta_1, ..., \theta_n|\Theta_n = \theta_n) = \Lambda_{a,\theta_n}^{n-1}(\theta_1, ..., \theta_{n-1})\\
        \Lambda_{a,b}^n(\theta_1, ..., \theta_n|\Theta_1 = \theta_1) = \Lambda_{\theta_1,b}^{n-1}(\theta_2, ..., \theta_{n}).
    \end{cases}
    \end{equation}\\

    \item For all $n \geq 1$, $a,b \in \mathbb{R}^+$ and $\theta_1, ..., \theta_n \in I_{a,b}$,

    \begin{equation}

         \Lambda_{a,b}^n(\theta_1, ..., \theta_n) = \prod_{i=0}^{n-1} \Lambda_{\theta_i,b}^{n-i,1}(\theta_{i+1}) = \prod_{i=0}^{n-1} \Lambda_{a,\theta_{n-i+1}}^{n-i,n-i}(\theta_{n-i}).
    \end{equation}
 \end{enumerate}","status":"unverified"}

