{"assumptions":[],"created_at":"2026-10-27T07:17:17.075096+00:00","domain":"probability theory","id":"claim_ae2470fb75da8a340178b8caa8b94a1c7d7c708eb9f4f4df817f8861e567099e","kind":"theorem","schema_version":1,"statement":"[Corollary 16 (ULDPs with initial data in $L^q(D)$) of arXiv:2608.19753, 'Uniform large deviation principles for the stochastic heat equation over unbounded sets of'] Let the conditions of Theorem \ref{th:Lp} hold. For $\eps>0$ and $x\in L^q(D)$, let $X_x^{\eps}=X_x^{\eps,0}$ be the mild solution to \eqref{eq:SHE} provided by Theorem \ref{th:wpnLp}. Then:  
\begin{enumerate}
    \item 
    The family $\{X_x^{\eps}-S(\cdot)x:\eps>0,x\in L^q(D)\}$  satisfies the ULDP on $C([0,T];L^{p}(D))$  uniformly over bounded subsets of $L^q(D)$, with rate functions $J_x\col C([0,T];L^{p}(D))\to [0,+\infty]$ given by 
\begin{align*}
J_x(\varphi)\ceqq \frac12\inf\{\|u&\|_{L^2(0,T;L^2(D))}^2 : u\in L^2(0,T;L^2(D)),\, \varphi=\tilde X_x^{0,u} \}, 
\end{align*}
where $\inf\varnothing\ceqq +\infty$ and $\tilde X_x^{0,u}$ is the mild solution to 
\begin{equation*} 
\begin{cases}
\frac{\partial \tilde X}{\partial t}(t, \xi) = \Delta \tilde X(t, \xi) +b\big(\tilde X(t,\xi)+S(t)x(\xi)\big)\\
\qquad\qquad\quad+ \sigma\big(\tilde X(t, \xi)+S(t)x(\xi)\big)u(t,\xi), \quad  \xi \in D, t \in(0,T], \\ 
\tilde X(0, \xi) = 0, \quad\xi\in D.
\end{cases} 
\end{equation*}  
\item If $\mathcal{J}$ is any subset of $L^q(D)$, and $(\mathcal{E},d)$ is any Polish topological vector space such that 
\begin{align}
\{S(\cdot)x:x\in \mathcal{J}\}\subset \mathcal{E}, \quad
C([0,T];L^p(D))\subset \mathcal{E},    
\end{align}
and there exists a constant $K$ such that  for all $f,g\in \mathcal{E}$ with $f-g\in C([0,T];L^p(D))$,   
\begin{align}
d(f,g)\leq K\|f-g\|_{C([0,T];L^p(D))},  
\end{align} 
then the family  $\{X_x^{\eps} :\eps>0,x\in \mathcal{J}\}$  satisfies the ULDP on $\mathcal{E}$  uniformly over $L^q(D)$-bounded subsets of $\mathcal{J}$, with rate functions $I_x\col \mathcal{E}\to [0,+\infty]$ defined by the formula \eqref{eq:rate}. 
\end{enumerate}","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T18:35:56.960663+00:00","domain":"probability theory","id":"claim_ae24994ae55a4b5352d873676a8c92de191ac2d60e72d0752e9fd7975f0b282f","kind":"concept","schema_version":1,"statement":"[Theorem thm:E[weak-sl] of arXiv:2604.05921, 'Simplicity of random hypergraphs'] Let $\hat{R}(\cdot)$ be as in (equation def:B_hat of the paper). For a uniformly random directed hypergraph with degree sequence $\vb*{d}$,
