    &\hspace{0.5cm}  \times\prod_{\substack{\vb*{y} \in \mathds{N}^{\delta_e^{\textnormal{tail}}}\\ \vb*{z} \in \mathds{N}^{\delta_e^{\textnormal{head}}}}} \Bigg( \frac{1}{\gamma(\vb*{y},\vb*{z})!} \Big(\frac{n\mathds{E}\big[\prod_{i=1}^{\delta_e^{\textnormal{tail}}} (f(d_U^{\textnormal{out}},i))^{y_i} \prod_{j=1}^{\delta_e^{\textnormal{head}}} (f(d_U^{\textnormal{in}} ,j)^{z_j} \big] \big(\sum_{i=1}^{\delta_e^{\textnormal{tail}}} y_i + \sum_{j=1}^{\delta_e^{\textnormal{head}}}z_j-1 \big)!}{\prod_{i=1}^{\delta_e^{\textnormal{tail}}} y_i! \prod_{j=1}^{\delta_e^{\textnormal{head}}} z_j!} \Big)^{\gamma(\vb*{y},\vb*{z})} \Bigg),
