{"assumptions":[],"created_at":"2026-10-27T09:24:34.421874+00:00","domain":"probability theory","id":"claim_ae460b55591b2132f5787f10c18d8185aa559359092b18553c875dd09904bd4f","kind":"theorem","schema_version":1,"statement":"[Theorem 10 of arXiv:2608.31145, 'Gauge-compatible tensors on statistical manifolds: splitting and submanifold geometry'] Let $M$ be a $\Theta$-CR submanifold of a $\Theta$-statistical
manifold.

\begin{enumerate}
\item For $X,Y\in\Gamma(D_{\Theta})$,
\begin{equation}
F_{\Theta}([X,Y])
=
h(X,\Theta Y)-h(Y,\Theta X).
\end{equation}

\item For $U,V\in\Gamma(D_{\Theta}^{\perp})$,
\begin{equation}
P_{\Theta}([U,V])
=
A_{\Theta U}V-A_{\Theta V}U.
\end{equation}
\end{enumerate}

Consequently:

\begin{enumerate}
\item[(a)] if
\[
\ker(F_{\Theta}|_{TM})=D_{\Theta},
\]
then $D_{\Theta}$ is integrable if and only if
\begin{equation}
h(X,\Theta Y)=h(Y,\Theta X)
\end{equation}
for all $X,Y\in\Gamma(D_{\Theta})$;

\item[(b)] if
\[
\ker(P_{\Theta}|_{TM})=D_{\Theta}^{\perp},
\]
then $D_{\Theta}^{\perp}$ is integrable if and only if
\begin{equation}
A_{\Theta U}V=A_{\Theta V}U
\end{equation}
for all $U,V\in\Gamma(D_{\Theta}^{\perp})$.
\end{enumerate}","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-26T20:38:37.403051+00:00","domain":"probability theory","id":"claim_ae465fd7d67eeb40b902bb3b3cc986633c74fbc8bb4fe64c4f6fa45448fe7817","kind":"concept","schema_version":1,"statement":"[Lemma 14 (Lemma 5.1 of \cite{gz25}) of arXiv:2605.15386, 'The non-central gamma sum and difference distributions: exact distribution and asymptotic '] 1. Fix $a>0$, $b\in\mathbb{R}$, $m\in\mathbb{R}$ and let $u_0, u_1, \ldots $ be real-valued constants. Then, as $x\rightarrow\infty$,
	\begin{align}\nonumber
		\int_{x}^{\infty}t^m\exp\big(-at+b\sqrt{t}\big)\sum_{l=0}^{\infty}\frac{u_l}{t^{l/2}}\,\mathrm{d}t\sim\frac{x^{m}}{a}\exp\big(-ax+b\sqrt{x}\big)\sum_{p=0}^{\infty}\frac{U_p}{x^{p/2}},
	\end{align}
	where
	\begin{align*}
		U_p&=\sum_{\substack{i,j,k,l\geq0 \\ i+2j+k+l=p}}(-1)^{i+j}u_l\binom{2m+1-l}{k}\binom{2m-l-k-2j}{i}\frac{((l+k)/2-m)_j}{a^j}\bigg(\frac{b}{2a}\bigg)^{k+i}, \quad p\geq0.
	\end{align*}
	2. Fix $a>0$, $m\in\mathbb{R}$ and let $v_0,v_1,\ldots$ be real-valued constants. Then, as $x\rightarrow\infty$,
	\begin{equation}

		\int_{x}^{\infty}t^m\mathrm{e}^{-at}\sum_{j=0}^{\infty}\frac{v_j}{t^j}\,\mathrm{d}t\sim\frac{1}{a}x^m\mathrm{e}^{-ax}\sum_{k=0}^{\infty}\frac{V_k}{x^k}, \nonumber
	\end{equation}
	where $V_k=\sum_{j=0}^{k}v_j(k-m)_{k-j}/(-a)^{k-j}$ for $k\geq0$. (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T09:36:31.232836+00:00","domain":"probability theory","id":"claim_ae47101f92fd527a88f1a83314da80e46a31ca8ee346fc567dcec62e54479cac","kind":"concept","schema_version":1,"statement":"[Theorema 2 ({\Cref{criterion-decomp-log}}) of arXiv:2609.00567, 'Hodge--Tate splitting and Akizuki--Nakano vanishing in positive characteristic'] Let \(X\) be a smooth \(k\)-variety of dimension \(d\), and let \(D\)
be a simple normal crossings divisor on \(X\).  Then the following
conditions are equivalent:
\begin{enumerate}
\item The pair \((X,D)\) is log HT-split.
\item There is an isomorphism
\begin{equation}
F_{*}\Omega_{X/k}^{\bullet}(\log D)
\simeq
\bigoplus_{i=0}^{d}
\Omega_{X/k}^i(\log D)[-i]
\end{equation}
in \(\mcalD_{\qcoh}(X)\).
\end{enumerate}
If \(X\) is projective, these equivalent conditions imply logarithmic
Akizuki--Nakano vanishing and the \(E_1\)-degeneration of the
logarithmic Hodge-to-de Rham spectral sequence (\Cref{vanishing}). (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

