{"assumptions":[],"created_at":"2026-10-26T20:46:26.256441+00:00","domain":"probability theory","id":"claim_ae7557ac4f87e841fc21b7f55e3425ea54ef4a94260ba516d88237d17ab23068","kind":"concept","schema_version":1,"statement":"[Thm 49 of arXiv:2605.23308, 'Convergence rate estimates for semigroups and heat kernels associated with resistance form'] For $\alpha\in (0,\alpha_n),\;\kappa\in (0,1],\;y\in F,\;y_n\in F_n$ and $f\in\BL^{\kappa}(M)$, we have that
\begin{equation*}
  \begin{aligned}
    |G^{\alpha}f(y)-G^{\alpha,n}f(y_n)|
  \lesssim&\g{c}{estres,n}\Bigl\{ \|f\|_{K_n}  (d(y,y_n)+d_{\mathrm{H}}(F,F_n))+\|f\|_{\BL^{\kappa}(K_n)}d_{\BL^{\kappa}}(\mu,\mu_n)\Bigr\}\\
  \leq&\g{c}{estres,n}\|f\|_{\BL^{\kappa}(K_n)}(d(y,y_n)+d_{\mathrm{H}}(F,F_n)+d_{\BL^{\kappa}}(\mu,\mu_n)).
  \end{aligned}
\end{equation*}
Here, 
$\g{c}{estres,n}=\g{c}{estres,n}(\alpha,\delta_n)$ is defined by setting
\begin{align*}
  \g{c}{estres,n}(\alpha,\delta_n)=\g{c}{itkill}\left( 1+\frac{\mu(F)\diam F}{\g{c}{sle,n}(\delta_n)} \right)\left(1+\frac{1}{\alpha \g{c}{sle,n}(\delta_n)}\right).
\end{align*} (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T05:33:17.671103+00:00","domain":"probability theory","id":"claim_ae78248784eba1a8bea967d7bc29d8e88c00cb6fe8865f8c3f22a67b75bfdd36","kind":"concept","schema_version":1,"statement":"[Theorem 1 of arXiv:2607.10725, 'From the Airy line ensemble to the Gaussian free field'] For all $T > 0$, define on $\R^2$ the random functions
    \begin{equation}

        \begin{aligned}
            h_T(t, x) = h(T^{1/2} t, Tx),\quad
            H_T(t, x) = h_T(t, x) - \E[h_T(t, x)].
        \end{aligned}
    \end{equation}
    For all compactly supported continuous functions $\varphi \in C_c(\R^2)$, define the pairing of $H_T$ and $\varphi$ to be the random variable
    \begin{equation}
        \ang{H_T, \varphi}
        = \int_{\R^2} dt dx H_T(t, x) \varphi(t, x).
    \end{equation}
    Then, for all $m \geq 1$, all $\varphi_1, \ldots, \varphi_m \in C_c(\R^2)$, and all $T_n > 0$ satisfying $T_n \uparrow \infty$, it holds that
    \begin{equation*}
        (\ang{\sqrt{\pi} H_{T_n}, \varphi_1}, \ldots, \ang{\sqrt{\pi} H_{T_n}, \varphi_m})
        \xrightarrow{n \to \infty} (\xi_1, \ldots, \xi_m),
    \end{equation*}
    where the convergence of random vectors is in the sense of joint moments, and $(\xi_1, \ldots, \xi_m)$ is a mean-zero Gaussian random vector with covariance matrix
    \begin{equation}
        \E[\xi_j \xi_k]
        =-\frac{1}{2 \pi} \int_{\mathcal{D}} dt_j dx_j \int_{\mathcal{D}} dt_k dx_k \log \left|\frac{t_j + \im \sqrt{-x_j}-t_k - \im \sqrt{-x_k}}{t_j + \im \sqrt{-x_j}-t_k +\im \sqrt{-x_k}}\right| \varphi_j(t_j, x_j) \varphi_k(t_k, x_k).
    \end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-26T19:42:47.753698+00:00","domain":"probability theory","id":"claim_ae78da62129d7229e19ced354c1be335bbe69f1ea4f386eb484e7599c2d83a20","kind":"concept","schema_version":1,"statement":"[Lemma 22 of arXiv:2604.11682, 'Semilocalization for inhomogeneous random graphs'] For any $\nu > 0$ and
  $x_{1} \in \hcV^{(\rm i)}_{\nu}$ we have
  \begin{equation*}
    \sum_{\substack{x_{2} \in \hcV^{(\rm i)}_{\nu}\\x_{2} \neq x_{1}}} \left< \b 1_{\Sdu(x_{1})}, \b 1_{\Sdu(x_{2})} \right> \leq 2\nu \frac{\log N}{\log\log N}
