{"assumptions":[],"created_at":"2026-10-27T12:59:58.432193+00:00","domain":"probability theory","id":"claim_ae8656108243c04074f3d43e7f593631b5cc5d72bf582f871bfec0d01ac7e97d","kind":"definition","schema_version":1,"statement":"[Definition d.AV of arXiv:2604.24743, 'The impact of disorder and non-convex interactions on delocalisation of height functions'] Let $\kappa$ be a probability measure on $(0 , \infty)$ and $\beta \in (0 , \infty)$ be an inverse temperature. We define the annealed Villain interaction associated with the measure $\kappa$ and with inverse temperature $\beta$ to be the function $F_{\kappa , \beta} : [0 , 2 \pi) \to \ensuremath{\mathbb{R}}$ given by the formula
    \begin{equation*}
        F_{\kappa, \beta}(\theta) = \int_0^\infty v_{\beta J}( \theta) \kappa(d J).
    \end{equation*}
    Given a finite set $\Lambda \subseteq \ensuremath{\mathbb{Z}^d}$, we define the spin system with annealed Villain interaction associated with the measure $\kappa$ and at inverse temperature $\beta$ in the set $\Lambda$ to be the probability distribution on the set of configurations $[0 , 2\pi)^{\Lambda}$
    \begin{equation} 
        \mu^{\mathrm{Ann-Vil}}_{L, \kappa, \beta}(d \theta) := \frac{1}{Z^{\mathrm{Ann-Vil}}_{L, \kappa, \beta}} \prod_{\substack{x , y \in \Lambda \\ x \sim y}} F_{\kappa, \beta}(\theta_x - \theta_y) \prod_{x \in \Lambda} d\theta_x.
    \end{equation}
    We denote by $\mu^{\mathrm{Ann-Vil}}_{\kappa, \beta}$ the limit as $\Lambda \uparrow \ensuremath{\mathbb{Z}^d}$ of the finite-volume measures $\mu^{\mathrm{Ann-Vil}}_{\Lambda, \kappa, \beta}$ and by $\left\langle \cdot \right\rangle_{\kappa, \beta}^{\mathrm{Ann-Vil}}$ the corresponding expectation.","status":"unverified"}

