{"assumptions":[],"created_at":"2026-10-27T18:48:24.320347+00:00","domain":"probability theory","id":"claim_aeda5d7b65f8d1141e4bf5b67a2ccdee2fc96e484990120bc35f5b3bec712c75","kind":"concept","schema_version":1,"statement":"[Proposition prop:convergence of R-transforms of arXiv:2605.31356, 'P\'olya--Schur problems and free probability'] Let $\{f_{n}\}_{n\geq 1}$ satisfy Assumption (assump:main assumption of the paper). 
	\begin{enumerate}
		\item Let $R_{\mu_{c,\Sigma}}$ be the $R$-transform of $\mu_{c,\Sigma}$, then 
		\begin{equation}
			\lim\limits_{n\rightarrow\infty}-\frac{f_{n}'(nu)}{f_{n}(nu)}= R_{\mu_{c,\Sigma}}(u),
		\end{equation} 
		uniformly on compact subsets of $\mathbb{C}_{-}$.

		\item Define $\left[ \log(1-xw)\frac{x^2+1}{x^2}+\frac{w}{x}\right]\Big|_{x=0}:=-\frac{w^2}{2}$ by continuous extension, then		
		\begin{equation}
			\lim\limits_{n\rightarrow\infty}\frac{1}{n}\log f_{n}(nu)-\frac{1}{n}\log f_{n}(-n\ii)=-c(u+\ii)+\int_{\mathbb{R}}\log\left(\frac{1-ux}{1+\ii x}\right)\frac{x^2+1}{x^2}+\frac{u+\ii}{x}\mathrm{d}\Sigma(x),
		\end{equation}  uniformly on compact subsets of $\mathbb{C}_{-}$.
		\item For any $M\in\mathbb{R}$ define $\log_{M}|z|:=\max(\log|z|,-M)$, then \begin{align}
			\lim\limits_{n\rightarrow\infty} &\frac{1}{n}\log_{M}| f_{n}(nu)|-\frac{1}{n}\log_{M}| f_{n}(-n\ii)|\\
			&=\operatorname{Re}\left(-c(u+\ii)\right)+\int_{\mathbb{R}}\left[\log_{M}\left|{1-ux}\right|-\log_{M}\left|{1+\ii x}\right|\right]\frac{x^2+1}{x^2} +\operatorname{Re}\frac{u+\ii}{x}\mathrm{d}\Sigma(x),\nonumber
		\end{align} uniformly on compact subsets of $\mathbb{C}_{-}\cup\mathbb{R}\setminus\{0\}$.
	\end{enumerate} (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-26T19:25:12.193023+00:00","domain":"probability theory","id":"claim_aeda64a0119f6976c7d459bd9bcfb9209c81373a2f32e4831dc8c7b99d56fc61","kind":"concept","schema_version":1,"statement":"[Lemma 7 of arXiv:2510.22533, 'Marginal dynamics of probabilistic cellular automata on trees'] Suppose $X$, $Y$, and $Z$ are random variables with values in some Polish spaces, and assume $X \perp Y \,\, | \,\, Z$.
