\end{itemize}

\begin{remark}
To be precise, the result is proved in~[van2023duality] for general graphs, but the extension to multigraph (considered here) is only notational.

\end{remark} (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T20:48:25.220915+00:00","domain":"probability theory","id":"claim_afd3bfc196e69a5ee34bdcd6e0c24f5bcc03e5ac65b0f02308d11e4596b24118","kind":"lemma","schema_version":1,"statement":"[Lemma eq: 678 of arXiv:2607.05848, 'Mesoscopic eigenvalue statistics for correlated random matrices'] {Vova25a} and [LS20]}]
Let $\Omega_{0}$ and $\Omega_{0}'$ as in (equation eq: 273 of the paper).
Define
\begin{equation*}
	\tilde{e}(\lambda)
	\coloneqq
	\exp\bigg\{ \frac{\mathrm{i}\lambda}{\pi}\int_{\Omega_{0}'}\frac{\partial\tilde{f}}{\partial\bar{z}}\Tr (G(z) - \mathbb{E} G(z))\mathrm{d}^{2}z\bigg\},
\end{equation*}
and
\begin{equation}
	\mathfrak{g} \equiv \mathfrak{g}(z, \lambda) \coloneqq \mathbb{E}[\tilde{e} (\lambda)  (G(z)-\mathbb{E}[G(z)])].
\end{equation}
Then it follows that
\begin{equation}
	\phi'(\lambda) = \frac{\mathrm{i}}{\pi}\int_{\Omega_{0}}\frac{\partial\tilde{f}}{\partial\bar{z}}
	\Tr(\mathfrak{g}) \mathrm{d}^{2}z
	+ O_{\prec}(|\lambda|N^{-\epsilon_{0}/2}).
\end{equation}","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T17:18:19.426498+00:00","domain":"probability theory","id":"claim_afd4227b83e233d505d5357fd5988aa72aa9f8e4982f36df7a5816f8822d35eb","kind":"definition","schema_version":1,"statement":"[Definition def:mutlCol of arXiv:2508.03577, 'Phase Transitions in a Particle Model\\ for the Self-Adaptive Response to Cancer Dynamics'] Let $(A_t)_{t\ge 0}$ with $A_t\in\mathbb{R}^{M\times N}$ be the continuous-time Markov chain with following transition rates
    \begin{equation}
        Q(A,B)=\begin{cases}
