        &\quad -\int_0^t\int_{\mathbb{S}}\nabla_y\partial_{\mu}\psi(\mu_s,X_s(\mathbf{x}))[DX_s(\mathbf{x})]^2\mathrm{d}\mathbf{x}\mathrm{d}s
        +\frac{1}{2}\int_0^t\int_{\mathbb{S}}\nabla_y\partial_{\mu}\psi(\mu_s,X_s(\mathbf{x}))G_1(\mathbf{x})\mathrm{d}\mathbf{x}\mathrm{d}s \\
        &\quad  + \frac{1}{2}\int_0^t\int_{\mathbb{S}}\int_{\mathbb{S}}\partial_{\mu}^2\psi(\mu_s,X_s(\mathbf{x}),X_s(\mathbf{x}'))G_2(\mathbf{x},\mathbf{x}')\mathrm{d}\mathbf{x}\mathrm{d}\mathbf{x}'\mathrm{d}s +\int_0^t\int_{\mathbb{S}}\partial_{\mu}\psi(\mu_s,X_s(\mathbf{x}))\mathrm{d}W_s(\mathbf{x}),
        \end{split}
    \end{equation}
where $\mu_t:= \mathrm{Leb}_{\mathbb{S}}\circ X^{-1}_t$ and $X_t$ is the solution to \eqref{eq:4.28} and the functions $G_1$ and $G_2$ are given below:
    \begin{align}
        G_1(\mathbf{x}):= \sum_{k\in \mathbb{N}}\lambda_k^2e_k^2(\mathbf{x}), \quad G_2(\mathbf{x},\mathbf{x}'):= \sum_{k\in \mathbb{N}}\lambda_k^2e_k(\mathbf{x})e_k(\mathbf{x}'), \quad \forall \mathbf{x},\mathbf{x}' \in \mathbb{S}.
    \end{align}
and the noise $(W_t)_{t\geq 0}$ is given by \eqref{eq:noise:1.8}. (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T20:58:10.025965+00:00","domain":"probability theory","id":"claim_b090c29d72239e1884683c6058ee2b3ef274df76c9cf5bfcd4faedd7eba33727","kind":"theorem","schema_version":1,"statement":"[Theorem thm:split of arXiv:2607.19844, 'Binomial probabilities at a fixed distance from the mode:\\ size-biasing and the complete '] For every $k\ge1$, every $h$ and every $r\in\mathbb Z$,
	\begin{equation}
	\begin{aligned}
		\widetilde A_k(h+r;p)&=\widetilde A_k(h;p)-\frac{\Xi_k(p)}{k}\;S_k(h,r),
		\\
		\widehat A_k(h+r;p)&=\widehat A_k(h;p)-\frac{\Xi_k(p)}{k}\;T_k(h,r).
	\end{aligned}
	\end{equation}
	Consequently $\widetilde A_k(h+r;p)$ and $\widehat A_k(h+r;p)$ are polynomials in $r$ of degree at most
