{"assumptions":[],"created_at":"2026-10-27T19:48:47.296930+00:00","domain":"probability theory","id":"claim_b1b4f1bd512e0a41db60457d66eff78582daffb8110df3543a3ff9c212fa7525","kind":"definition","schema_version":1,"statement":"[Definition 2DHD-Def3.1 of arXiv:2604.21591, '\bf Long-time dynamics of stochastic 2D hydrodynamic-type evolution equations driven by mu'] An $H$-valued c\`{a}dl\`{a}g $\mathscr{F}_t$-adapted process $\{u(t),t\in [\tau,\tau+T]\}$ is called a solution of (equation 2DHD-1.1 of the paper) if for all $\mathscr{F}_\tau$-measurable $u_{\tau}\in H$ and any $T>0$,

	\begin{description}
		\item{$(i)$}
	  $u\in \mathcal{D}([\tau,\tau+T],H)\cap L^2([\tau,\tau+T],V)$, $\mathbb{P}$-a.s.,


		\item{$(ii)$} the following  equality holds for every $t\in [\tau,\tau+T]$, as an element of $V'$, $\mathbb{P}$-a.s., 
		\begin{eqnarray*}
			u(t) &=&u_{\tau} -\mu\int_{\tau}^t \mathcal{A}u(s) ds - \int_{\tau}^t B(u(s),u(s)) ds+\int_{\tau}^t f(s) ds
			\\  &&+\varepsilon_1\int_{\tau}^t h(s,u(s))d W(s)+\varepsilon_2\int_{\tau}^t\int_{\mathcal{Z}}  G(u(s-),z) \widetilde{N}(ds,dz). 
		\end{eqnarray*}
		\end{description}
		An alternative version of Condition $(ii)$ stipulates that for every $t\in [\tau,\tau+T]$, $\mathbb{P}$-a.s.,
		\begin{align*}
			\langle u(t),\eta\rangle =&\langle u_{\tau},\eta\rangle -\mu\int_{\tau}^t\langle\mathcal{A}u(s), \eta\rangle ds - \int_{\tau}^t\langle B(u(s),u(s)),\eta\rangle ds+\int_{\tau}^t \langle f(s),\eta\rangle ds
			\\  
			&+\varepsilon_1\int_{\tau}^t\langle h(s,u(s))d W(s),
			\eta \rangle+\varepsilon_2\int_{\tau}^t\int_{\mathcal{Z}} \langle G(u(s-),z), \eta \rangle\widetilde{N}(ds,dz),  
		\end{align*}
		for any $\eta\in V$.","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T19:38:25.224513+00:00","domain":"probability theory","id":"claim_b1b74bb865bee8bda299365c915327b959ee03d84916281f645214ae781d6b5e","kind":"theorem","schema_version":1,"statement":"[Proposition of arXiv:2609.00324, 'Quantitative Stability for Fractional Yamabe minimizers'] Let $(\mathbb{S}^n , h_0 )$ be the round sphere with $n\geq 3$. Then, there exists a constant $C>0$ such that for all $w \in H^{\gamma}(\mathbb{S}^n)$
