L^1_{s^{\text{\tiny{${\boldsymbol{\tau}}$}}}}(\R^{\mathfrak{s}(\text{\tiny{${\boldsymbol{\tau}}$}})})}\\
&\equiv \sup_{t_{\tau_1}\leqslant1}
\int_{(-\infty,1]^{p(\text{\tiny{${\boldsymbol{\tau}}$}})-1}\times\R^{\text{\tiny{$\mathfrak{s}$}}(\text{\tiny{${\boldsymbol{\tau}}$}})}}
| K_{N,\mu}^{\otimes \text{\scriptsize{$\mathfrak{l}$}}(\text{\scriptsize{${\boldsymbol{\tau}}$}})}    \text{{\Large $\kappa$}}_{\eps,\mu}^{\text{\scriptsize{${\boldsymbol{\tau}}$}}}( t_{\text{\scriptsize{${\boldsymbol{\tau}}$}}},s^{\text{\scriptsize{${\boldsymbol{\tau}}$}}})|\text{$\mathrm{d}$} s^{\text{\scriptsize{${\boldsymbol{\tau}}$}}}\mathrm{d} t_{\tau_2}\cdots\mathrm{d} t_{\tau_{{p({\boldsymbol{\tau}})}}}
\,.
\end{equs}
We write $\widecheck{{\mcb{C}}}_{\mu}[{\boldsymbol{\tau}}]$ for the closure of $\widecheck{{\mcb{C}}}[{\boldsymbol{\tau}}]$ with respect to ${\vert\kern-0.25ex\vert\kern-0.25ex\vert  
    \vert\kern-0.25ex\vert\kern-0.25ex\vert}_{N,\mu}$, again dropping the scale $\mu$ from notation when it is clear from context.","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T13:32:58.312225+00:00","domain":"probability theory","id":"claim_b27550b5f18e145a9d2a0c223b74a6e5bed1dfc1b0affc1ed72426e0a63828a9","kind":"concept","schema_version":1,"statement":"[Theo local survival gives liminf of number of particles of arXiv:2505.12127, 'Generalised principal eigenvalues and global survival of branching Markov processes'] We assume Assumption (assum:uniformly elliptic standing assumptions of the paper), that $\lambda_1'(L)>0$, and ${\mathbb P}_x(\ensuremath{\mathrm{locSurv}})>0$ for some given $x\in E$. Then 
