{"assumptions":[],"created_at":"2026-10-26T19:24:25.983140+00:00","domain":"probability theory","id":"claim_b27a89f8ce61318272f6a88a1d50386daf0f2a21f9192f35c1f02d522d3f45c5","kind":"concept","schema_version":1,"statement":"[Conjecture 38 (cf.\ {\cite[Conjecture 1.3) of arXiv:2507.07702, 'Observables of random spanning trees in random environment'] {MSS24}}] 
