{"assumptions":[],"created_at":"2026-10-27T09:32:20.751804+00:00","domain":"probability theory","id":"claim_b37bf48eb9ad503b57ca42109ffb0729bcc1edb1687ae5e58e8b5c8565cc3aa6","kind":"definition","schema_version":1,"statement":"[Definition 7 of arXiv:2609.00448, 'Equivariant formality and representation theory'] (\cite[p. 172]{H}, \cite{GD}). Let $A$ be a ring and $B$ an $A$-algebra. The module of K\"ahler differentials $\Omega^1_{B/A}$ of $B$ over $A$ is the quotient of the $B$-module freely generated by the symbols $\{db| b\in B\}$ by the submodule generated by the following sets
	\begin{enumerate}
		\item(Constancy of elements of $A$) $\{da| a\in A\}$, 
		\item(Linearity of $d$) $\{d(b_1+b_2)-db_1-db_2| b_1, b_2\in B\}$, and 
		\item(Derivation) $\{d(b_1b_2)-b_1db_2-b_2db_1| b_1, b_2\in B\}$.
	\end{enumerate}
	The Grothendieck differentials $\Omega^*_{B/A}$ is defined to be the exterior $B$-algebra $\displaystyle\bigoplus_{p=0}^\infty \bigwedge\nolimits_B^p\Omega_{B/A}^1$.","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T18:40:26.993367+00:00","domain":"probability theory","id":"claim_b37c655bd613cec4cd02f502dd178e3c4ccdc276a0867086bf574f9dcab62753","kind":"theorem","schema_version":1,"statement":"[Prop lem-uppboundJ_W of arXiv:2604.14318, '\large The free energy of the interacting Bose gas:\\\medskip a variational description \\'] Fix $M,R\in(1,\infty)$ and any odd $m\in\mathbb{N}$. Recall $\mathfrak p_{W_{R},M}$  defined in (equation pMdef of the paper). The constants $C$ and $C_{M,\mathfrak r,T}$ stem from Lemma~(lem-lowerboundlogpint of the paper), while $C_M$ appears first in Lemma~(lem-UpperLDPbound of the paper). Then the following hold.

\begin{enumerate} 
\item For any $\xi\in{\mathcal M }_1({\mathcal L }_{W_{mR}}^{{{\scriptscriptstyle{({M}})}}}\times{\mathcal S }^{{{\scriptscriptstyle{({M}})}}}_{W_{mR}})$ such that $\psi=\partial \Pi_{W_{mR}}^{{{\scriptscriptstyle{({\mathcal S }})}}}(\xi)$ is $W_{mR}$-admissible,
\begin{equation}
J_{W_R;M}(f_{m,R}(\xi))
 \leq J_{W_{mR};M}(\xi)+ \frac {C_M}{(mR)^{d/2}}-\frac 1{|W_{mR}|}\langle\psi,\mathfrak p_{W_{mR},M}\rangle,
\end{equation}
and, for any $x\in \mathbb{R}^d$ such that $x+W_R\subset W_{mR}$,
\begin{equation}
J_{W_R;M}(\theta_x(\Pi_{x+W_R}(\xi)))\leq J_{W_{mR};M}(\xi)+ \frac {C_M}{(mR)^{d/2}}-\frac 1{|W_{mR}|}\langle\psi,\mathfrak p_{W_{mR},M}\rangle.
\end{equation}
where $J_{W;M}$ is defined in (equation JWMTdef of the paper) with all other parameters $K,L,T,\vartheta$ equal to $\infty$. 

\item For any  $P\in {\mathcal M }_1^{{{\scriptscriptstyle{({\rm s}})}}}({\mathcal L }^{{{\scriptscriptstyle{({M}})}}}\times {\mathcal S }^{{{\scriptscriptstyle{({M}})}}})$ such that  $P$ is $W_{mR}$-ergodic and $\Pi^{{{\scriptscriptstyle{({\mathcal S }})}}}_{W_R}(P)$ is concentrated on $A^{{{\scriptscriptstyle{({\mathcal S }})}}}_{W_R;M,\mathfrak r, T}\cap{\mathcal S }_{W_R}^{{{\scriptscriptstyle{({\vartheta, S}})}}}$,
\begin{equation}
\begin{aligned}
J_{W_R;M}(\Pi_{W_R}(P))&\leq J_{W_{mR};M}(\Pi_{W_{mR}}(P))+ \frac {C_M}{(mR)^{d/2}}+\Big[\frac {C_{M,\mathfrak r,T}}{mR}+\frac{C\vartheta^2}S\Big]\langle P,\mathfrak N_U^{\ssup\ell}\rangle.
