\item For any  $P,P_1,P_2,\dots\in {\mathcal M }_1^{{{\scriptscriptstyle{({\rm s}})}}}({\mathcal L }\times {\mathcal S })$ such that $P_n$ converges weakly to $P$, we have $J_{W_R}(\Pi_{W_R}(P))\leq \liminf_{n\to\infty} J_{W_{R_n}}(\Pi_{W_{R_n}}(P_n))$  for any sequence $R_n\downarrow R$.

\item For any $\xi\in{\mathcal M }_1({\mathcal L }^{{{\scriptscriptstyle{({M}})}}}_{W_{R}}\times{\mathcal S }^{{{\scriptscriptstyle{({M}})}}}_{W_{R}})$ such that $\psi=\partial \Pi_{W_{R}}^{{{\scriptscriptstyle{({\mathcal S }})}}}(\xi)$ is $W_{R}$-admissible,  and for  any $k\in\mathbb{N}$,
\begin{equation}
\begin{aligned}
J_{W_R;M}(\xi)&\geq  \inf\big\{J_{3^k W_{R};M}(\xi^{{{\scriptscriptstyle{({k}})}}})\colon \xi^{{{\scriptscriptstyle{({k}})}}}\in \widetilde{\mathcal M }_1^{{{\scriptscriptstyle{({k}})}}},\Pi_{3^k W_R\to W_R}(\xi^{{{\scriptscriptstyle{({k}})}}})=\xi\big\}
 -\frac {C_M}{R^{d/2}}+\frac 1{|W_{R}|}\langle\psi,\mathfrak p_{W_{R},M}\rangle.
\end{aligned}
\end{equation}
\end{enumerate}","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-26T19:48:27.275956+00:00","domain":"probability theory","id":"claim_b37d48ff4e32a7c6da187d834f80dcf51a3e5face71bc77826ba8e98ad2f0807","kind":"theorem","schema_version":1,"statement":"[Prop 12 of arXiv:2604.24624, 'Limit distributions of the threshold radius for the maximum degree and the associated poin'] Assume that $n^{k+1}r_n^{dk} \to \infty$.
