	\begin{equ}

		\|e^{t\Delta} u\|_{\Besov{\alpha + \beta}{p,q}} \lesssim_{\beta} t^{-\beta/2} \|u\|_{\Besov{\alpha}{p,q}}\;.
	\end{equ}","status":"unverified"}

