{"assumptions":[],"created_at":"2026-10-26T19:43:44.240833+00:00","domain":"probability theory","id":"claim_b4146e7217e4b7dc6cc762a052e565090dc9399e268017936885ea25c08db4ee","kind":"theorem","schema_version":1,"statement":"[Propo 14 of arXiv:2604.14752, 'Strong and weak rates of convergence in the Smoluchowski--Kramers approximation for stocha'] Let Assumptions~\ref{ass:mapping-f} and~\ref{ass:noise} be satisfied. Let $\varphi:H\to\R$ be of class $\mathcal{C}^4$ with bounded first and second order derivatives.

For all $T\in(0,\infty)$ and all $\alpha\in[0,1]$, there exists a real number $C_\alpha(T)\in(0,\infty)$ such that, for all $\epsilon\in(0,1)$, all $t\in(0,T]$, all $N\in\N$ and all $(u,v)\in \HH_N$, $h\in H_N$, one has
 	\begin{align}
		\big|D_{u}\Phi^{(\epsilon,N)}(t,u,v).h\big|&\le C_\alpha(T)\vvvert \varphi\vvvert_1 t^{-\frac{\alpha}{2}}\bigl(\epsilon^{\alpha}\|h\|_H+\|h\|_{H^{-\alpha}}\bigr),\\ 
	 \frac{1}{\epsilon}|D_v\Phi^{(\epsilon,N)}(t,u,v).h|&\le C_\alpha(T)\vvvert \varphi\vvvert_1 t^{-\frac{\alpha}{2}}\|h\|_{H^{-\alpha}}. 
	\end{align}
Moreover, for all $\alpha_1,\alpha_2\in[0,1)$, there exists $C_{\alpha_1,\alpha_2}(T)\in(0,\infty)$ such that, for all $\epsilon\in(0,1)$, all $t\in(0,T]$, all $N\in\N$ and all $(u,v)\in \HH_N$, $h,k\in H_N$, one has
\begin{align}
	&|D^2_{uu}\Phi^{(\epsilon,N)}(t,u,v).(h,k)|\le C_{\alpha_1,\alpha_2}(T)\vvvert\varphi\vvvert_2 t^{-\frac{\alpha_1+\alpha_2}{2}}\bigl(\epsilon^{\alpha_1}\|h\|_H\!+\!\|h\|_{H^{-\alpha_1}}\bigr)\bigl(\epsilon^{\alpha_2}\|k\|_H\!+\!\|k\|_{H^{-\alpha_2}}\bigr),\\
	&\frac{1}{\epsilon}|D^2_{uv}\Phi^{(\epsilon,N)}(t,u,v).(h,k)|\le C_{\alpha_1,\alpha_2}(T)\vvvert\varphi\vvvert_2 t^{-\frac{\alpha_1+\alpha_2}{2}}\bigl(\epsilon^{\alpha_1}\|h\|_H\!+\!\|h\|_{H^{-\alpha_1}}\bigr)\|k\|_{H^{-\alpha_2}}, \\
      &\frac{1}{\epsilon}|D^2_{vu}\Phi^{(\epsilon,N)}(t,u,v).(h,k)|\le C_{\alpha_1,\alpha_2}(T)\vvvert\varphi\vvvert_2 t^{-\frac{\alpha_1+\alpha_2}{2}}\|h\|_{H^{-\alpha_1}}\bigl(\epsilon^{\alpha_2}\|k\|_H\!+\!\|k\|_{H^{-\alpha_2}}\bigr),\\
      &\frac{1}{\epsilon^2}|D^2_{vv}\Phi^{(\epsilon,N)}(t,u,v).(h,k)|\le C_{\alpha_1,\alpha_2}(T)\vvvert\varphi\vvvert_2 t^{-\frac{\alpha_1+\alpha_2}{2}}\|h\|_{H^{-\alpha_1}}\|k\|_{H^{-\alpha_2}}. 
	\end{align}","status":"unverified"}

