{"assumptions":[],"created_at":"2026-10-27T13:54:12.532036+00:00","domain":"probability theory","id":"claim_b5aeb6f753a33d5f0bf13bcd16a42a9a71ffe69b9fda9eac0cb036bface5c36c","kind":"definition","schema_version":1,"statement":"[Definition D:horizon-topology of arXiv:2604.10020, 'The directed landscape in half-space'] Let $L$ be an interval in $\mathbb{R}$ and let $J \in \{\mathbb{R}, \mathbb{Z}\}$, and fix a distinguished point $\gamma_0 \in L$. Define $\mathcal{D}(L, J, \gamma_0)$ to be the set of functions $F:L \times J \to \mathbb{R}$, such that (denoting $F_\gamma(j)=F(\gamma,j)$)
\begin{itemize}[nosep]
    \item $F_{\gamma_0}$ is continuous if $J = \mathbb{R}$;
    \item $F_\gamma(0) = 0$ for all $\gamma$;
    \item there is a $\sigma$-finite measure $\mu_F$ on $L \times J$ such that for any $\gamma_1<\gamma_2\in L$ and $j_1<j_2\in J$, we have
    \begin{equation}

        \mu_F((\gamma_1, \gamma_2] \times ((j_1, j_2]\cap J)) = F(\gamma_1, j_1) + F(\gamma_2, j_2) - F(\gamma_1, j_2) - F(\gamma_2, j_1). 
    \end{equation}
\end{itemize}
We say that $F^n \to F$ in $\mathcal{D}(L, J, \gamma_0)$ if $F^n_{\gamma_0} \to F_{\gamma_0}$ in the uniform-on-compact topology, and $\mu_{F^n} \to \mu_F$ vaguely. This turns $\mathcal{D}(L, J, \gamma_0)$ into a Polish space.","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-26T19:27:36.718290+00:00","domain":"probability theory","id":"claim_b5aeec8408e694918bfa6938f0743a229fac9ba29fe8ea22cad9054017d104e6","kind":"definition","schema_version":1,"statement":"[Definition 6 of arXiv:2511.13404, 'Asymptotic stability and mean ergodicity of Feller processes on Polish spaces'] $\Phi$ is said to be Ces\`aro eventually continuous with respect to a family $\mathfrak{F}\subset\mathcal{A}$ at $x\in \X$ if for any $f\in\mathfrak{F}$,
		\begin{equation*}
			\limsup\limits_{x'\rightarrow x}\limsup\limits_{t\rightarrow\infty}|Q_tf(x')-Q_tf(x)|=0.
		\end{equation*}","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T12:15:15.512578+00:00","domain":"probability theory","id":"claim_b5b675f8d31d5fb9d4ef3cad594e0e08b6fe9d3c7a72396113e002ff4b80cc5e","kind":"theorem","schema_version":1,"statement":"[Corollary density-conditions of arXiv:2507.01406, '{\Large On Iterated Lorenz Curves with Applications: The Multivariate Case }'] Assume that $F$ has a continuous positive density 
$f$ on $(0,1)$, and define 
\begin{equation}
G_{F}(x)=F(x)+F(1-x)-1,\qquad x\in \lbrack 0,1].  
\end{equation}
Then:

\begin{enumerate}
\item If $f(x)-f(1-x)$ changes sign at most once on $(0,1)$, then $G_{F}$
has a constant sign on $[0,1]$.

\item Consequently, by \textit{Claim~(prob-meaning of the paper)}, 
\begin{equation}
H_{F}(u)=Q(u)+Q(1-u)-1  
\end{equation}
has a constant sign on $[0,1]$, and by \textit{Corollary~(HF-one-sign of the paper)}
the first defect $D_{0}$ has a constant sign on $[0,1]$.

\item A sufficient condition for the hypothesis in \emph{(1)} is that the
ratio 
\begin{equation}
x\longmapsto \frac{f(x)}{f(1-x)}  
\end{equation}
be monotone on $(0,1)$.
\end{enumerate}","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-26T19:22:46.469634+00:00","domain":"probability theory","id":"claim_b5b8f7bc84468cdd1297967604a97b18806b30a8e7e812508c839d798c1b9106","kind":"lemma","schema_version":1,"statement":"[Lemma 79 of arXiv:2609.03101, 'The emergence of the Cauchy horizon from the crease for $3D$ compressible Euler flow'] The material vectorfield $\Transport$ admits the following decompositions in terms of the double-null frame and the vectorfield from \eqref{E:TORITANGENTVECTORFIELDASSOCIATEDTODOUBLENULLFRAME}:
		\begin{subequations}
			\begin{align}
				\Transport &= \frac{1}{\upmu} \newuL + \frac{1}{\ingoingmu} \newL + \ReciprocalLunitAppliedtoTimeFunction \ToriTangentVectorfieldAssociatedToDoubleNullFolliations   \\
				& = \frac{1}{\MagnitueofinnerproductofLunitanduLunit} \uLunit + \frac{1}{\MagnitueofinnerproductofLunitanduLunit} \Lunit + \breve{\slashed{\Transport}}. 
			\end{align}
		\end{subequations}
In particular, we have: 
	\begin{align}
		\ReciprocalLunitAppliedtoTimeFunction \ToriTangentVectorfieldAssociatedToDoubleNullFolliations  = \breve{\slashed{\Transport}} 
	\end{align}In addition, there exists unique $\Sigma_t$-tangent vectorfields $\Lunit^\perp$ and $\uLunit^\perp$ such that: 
	\begin{subequations}
		\begin{align}
			\Lunit & = \Transport + \Lunit^\perp,  \\
			\uLunit & = \Transport + \uLunit^\perp. 
		\end{align}
	\end{subequations}
Moreover, $\Lunit^\perp$ and $\uLunit^\perp$ satisfy:
	\begin{align}
		 \gfour(\Lunit^\perp,\Lunit^\perp) & = 1, & \gfour(\uLunit^\perp,\uLunit^\perp) & = 1, & \gfour(\Lunit^\perp,\uLunit^\perp) & = 1 - \MagnitueofinnerproductofLunitanduLunit. 
	\end{align}","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T20:19:06.744408+00:00","domain":"probability theory","id":"claim_b5b99989f4ed276e87d7741e88842e6720f948dedaf879948440c762771d65c0","kind":"concept","schema_version":1,"statement":"[Lemma lm012104-26 of arXiv:2606.07353, 'The Gaussian structure of a perturbed KPZ'] For any $\beta>0$ we have
  \begin{equation}
  \begin{split}
&     \mathbf{E}_{{\mu_N(0)}} {\frak
  l}_{N,V}\Big({u_{N,V} (t)} \Big) 
\le  
