\right).
\end{equation}
In particular,
\begin{equation}

\frac{1}{N}\sum_{i=1}^N
\E\left(
\norm{D_s^j X_u^{i,N}}^p
\right)^{1/p}
\le
\frac{C_p}{N} e^{-\kappa_p \left( u-s \right)/8}.
\end{equation}","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T14:38:23.550752+00:00","domain":"probability theory","id":"claim_b5c72d6fa3d3d2672e20174765b810f0ca1819bb15496062bc7addf89d96f1d2","kind":"concept","schema_version":1,"statement":"[Theorem thrm:lump of arXiv:2511.01058, 'Limit profiles and cutoff for the Burnside process on Sylow double cosets'] Define \(T: S_{pk} \to \{k,\ldots 2k\}\) by
    \begin{equation}
        T(\sigma)=a \Longleftrightarrow |H\sigma H|=p^a. 
    \end{equation}
    Then the Sylow--Burnside kernel \(P\) lumps under \(T\) and the lumped transition kernel is given by
    \begin{equation}
        \overline{P}(a,b)=\sum_{y=0}^{2k-\max\{a,b\}}\binom{2k-a}{y} \left(\frac{p-1}{p}\right)^y  \frac{p^{a+b-2k}}{(p(k-y))!}f(b-y;k-y),
    \end{equation}
    where \(f(a;k)\) is the number of Sylow \(p\)-double cosets in \(S_{pk}\) of size \(p^a\). Furthermore, if \(Z = \sum_{a=k}^{2k}f(a;k)\) is the total number of Sylow \(p\)-double cosets, then the lumped stationary distribution is given by
    \begin{equation}
        \overline{\pi}(a) = \frac{f(a;k)}{Z}.
    \end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T06:45:05.473418+00:00","domain":"probability theory","id":"claim_b5c734b9136901497784ceaaf021a3bff01f9e1f7bc99e3de238a8138034c8c3","kind":"lemma","schema_version":1,"statement":"[Lemma 167 (Euler-generated parameter-field completion) of arXiv:2608.04993, '2608.04993'] Assume the hypotheses of \Cref{lem:trace-clock-Euler-sections} and suppose
also that $\cP$ is uniformly tight on
$\Omega=C_0([0,T];H)$.  The fixed-parameter classes admit compatible
completions
\begin{equation}
 \Phi^R\in\bigcap_{1\le q<\infty}
 \mathbb L_{\cP}^q(\mathscr B_R),
 \qquad R\in\mathbb N.
\end{equation}
Put
\[
 \varrho((s,y),(r,z)):=|s-r|^{1/2}+|y-z|.
\]
For every $q>m+2$ and every
$0<\delta<1-(m+2)/q$,
\begin{equation}
 \sup_{P\in\cP}E^P\left[
  \sup_{\substack{(s,y)\ne(r,z)\\|y|,|z|\le R}}
  \frac{\|\Phi^R(s,y)-\Phi^R(r,z)\|_\infty^q}
       {\varrho((s,y),(r,z))^{\delta q}}
 \right]<\infty.
\end{equation}

There are a total jointly Borel raw-causal field
\begin{equation}
 \Phi:\Omega\times\Delta_T\times\mathbb R^m\to\mathbb R^m
\end{equation}
and one sequence $(F_n)$ with the following properties.  Each $F_n$ is a
continuous finite-parameter interpolation field assembled from finitely many
finite-step raw Euler maps.  There is one Borel full-capacity set
$G_{\rm reg}$, independent of the radius, moment exponent, and parameters,
such that
\begin{equation}
 \Phi_{s,t}(x,y)=\Phi^R(x)(s,y)(t)
 \quad
 (x\in G_{\rm reg},\ |y|\le R,\ 0\le s\le t\le T),
\end{equation}
while the right-hand path is frozen before $s$.  In particular,
the field is locally jointly continuous in $(s,t,y)$ on $G_{\rm reg}$.
There is an increasing compact capacity core $(K_j^{\rm E})_{j\ge1}$ on
each member of which $(x,s,t,y)\mapsto\Phi_{s,t}(x,y)$ is jointly continuous
when the parameters range over compact sets.","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-26T19:36:04.999660+00:00","domain":"probability theory","id":"claim_b5c943714944435d0121ad02b1338ed2541762ac9e9875e4563fa956e91e7bdc","kind":"concept","schema_version":1,"statement":"[Proposition 84 of arXiv:2604.01685, 'Probability with Measure\footnote{Lecture notes. University of Ljubljana.}'] Let $(\Omega,\FF,\PP)$  be a probability space and let $(X,Y)$ be a bivariate absolutely continuous random vector. Denote $f_{(X,Y)}:=\frac{\dd\PP_{(X,Y)}}{\dd \leb^2}$. Then $X$ and $Y$ are both absolutely continuous, 
\begin{equation} 
f_X(x)=\int f_{(X,Y)}(x,y)\leb(dy)\text{ for $\leb$-a.e. }x\in \mathbb{R}\text{ and } f_Y(y)=\int f_{(X,Y)}(x,y)\leb(dx)\text{ for $\leb$-a.e. }y\in \mathbb{R},
\end{equation}
 and $X$ is independent of $Y$ iff 
\begin{equation*}
f_{(X,Y)}(x,y)=f_X(x)f_Y(y) \text{ for $\leb^2$-a.e. $(x,y)\in \mathbb{R}^2$}.
\end{equation*}
When $X$ and $Y$ are independent, then, for all $g\in \mathcal{B}_{\mathbb{R}^2}/\mathcal{B}_{[-\infty,\infty]}$,
\begin{equation}
\PP[g(X,Y)]=\int\int g(x,y)f_X(x)f_Y(y)\leb(\dd x)\leb(\dd y),
\end{equation}
provided $\PP[g^-(X,Y)]\land \PP[g^+(X,Y)]<\infty$. (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T19:33:43.754806+00:00","domain":"probability theory","id":"claim_b5caa9f458ac201ce5d985639d216333dc98ad336545110ff49954a40fe4b321","kind":"concept","schema_version":1,"statement":"[Proposition prop18 of arXiv:2609.02136, 'Gamma approximation and Poisson--Gaussian invariance principle on Poisson chaos'] Fix $q\geq1$ and $\nu>0$.  If
\noindent
\begin{align*}
 F=I_q^\eta(f)\in\mathcal{C}_q^\eta\cap L^4(\Omega),
