		\cE_1 \de \inf\{t\geq 0: s_i(t) \neq s_i(0) \} \quad \text{ and }\quad \cE_2 \de \inf\{t\geq \cE_1: s_i(t)\neq  s_i(\cE_1)\} - \cE_1 \nonumber
	\end{align}
	to be the first two increments between times for which $s_i$ changes value.
