{"assumptions":[],"created_at":"2026-10-26T19:39:41.438953+00:00","domain":"probability theory","id":"claim_b77f86a9d3fb119c35ec53c78b20476a5b7fa2bdf427f8bc98a881c7dcfc8dee","kind":"definition","schema_version":1,"statement":"[Defn 14 of arXiv:2604.07370, 'Probabilistic Weyl law for twisted Toeplitz matrices with rough symbols'] We say that a continuous function $m:\mc{T}_{\A{1},\A{2}}\to (0,+\infty)$ is an order function on $\mc{T}_{\A{1},\A{2}}$ if there exist $C_0>0$ and $N_0\geq 0$ such that for all $\rho$, $\mu\in \mc{T}_{\A{1},\A{2}}$
    \begin{equation*}
        m(\rho)\leq C_0\jap{\rho-\mu}_{\mc{T}_{\A{1},\A{2}}}^{N_0}m(\mu)
    \end{equation*}
    with $\jap{\rho}_{\mc{T}_{\A{1},\A{2}}}=\pr{1+\bb{\rho}_{\mc{T}_{\A{1},\A{2}}}}^{1/2}$, where for $\rho=(x,\xi)\in \mc{T}_{\A{1},\A{2}}$,
    \begin{equation}
        \bb{\rho}_{\mc{T}_{\A{1},\A{2}}}:=\inf\limits_{{\gamma_1,\gamma_2\in \Z^d}}\pr{\bb{x-\Ab{1}\gamma_1}^2+\bb{\xi-\Ab{2}\gamma_2}^2}^{\frac{1}{2}}.

    \end{equation}","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-28T02:39:12.215452+00:00","domain":"probability theory","id":"claim_b7809e88b8cdaaf4c286def97f1ac3768d804d5d814acb38e194b1ae89c70e32","kind":"concept","schema_version":1,"statement":"[Theorem th: main of arXiv:2412.07690, 'A law of large numbers concerning the distribution of critical points of random Fourier se'] Fix an amplitude $\mathfrak{a}$,  a positive integer $m\in {{\mathbb N}}$,  a radius $r_0\in (0,1/2)$ and  a  nonnegative  function $f:{\mathbb R}^m\to{\mathbb R}$  with support contained in $B_{r_0}(0)$. Then the following hold.

\begin{enumerate} 
\item
\begin{equation}
 \lim_{R\to \infty} R^{-m}{\mathbb E}\big[\, \mathfrak{C}[ f, F^R_\mathfrak{a}]\,\big]={\mathbb E}\big[\, \mathfrak{C}[f,\Phi_\mathfrak{a}]\,\big] =C_m(\mathfrak{a})\int_{{\mathbb R}^m} f({\boldsymbol{x}}){\boldsymbol{\lambda}}\big[\, dx\,\big].
 \end{equation}

\item There  exists  a constant $V_m(\mathfrak{a})\geq 0$ that depends only on $m$ and $\mathfrak{a}$ such that
 \begin{equation}
