{"assumptions":[],"created_at":"2026-10-27T12:40:22.274357+00:00","domain":"probability theory","id":"claim_b901dbb9fadeb034ef652a5c8b99dd89499d62d32ad8e6f96f4fb6c8d5d7a090","kind":"concept","schema_version":1,"statement":"[Thm finiteVsInfinite of arXiv:2609.02588, 'Ramsey-type results for Maker-Breaker games'] {}
