{"assumptions":[],"created_at":"2026-10-26T19:25:40.048192+00:00","domain":"probability theory","id":"claim_b944482dfcc6973fc31c08aef07cc0dda5e32d5ee70cf678962d638cf1a55379","kind":"theorem","schema_version":1,"statement":"[Cor 6 of arXiv:2510.25151, '$L^{\alpha-1}$ distance between two one-dimensional stochastic differential equations with'] Let $Z$ be a one-dimensional symmetric $\alpha$-stable process with $\alpha \in (1,2)$. Consider two processes, $X$ and $\tilde{X}$, satisfying the SDEs
\begin{align*}
X_t = x_0 + \int_0^t b(X_s) \rd s + \int_0^t \sigma(X_{s-}) \rd Z_s \quad \text{and} \quad \tilde{X}_t = \tilde{x}_0 + \int_0^t \tilde{b}(\tilde{X}_s) \rd s +  \int_0^t \tilde{\sigma}(\tilde{X}_{s-}) \rd Z_s,
\end{align*}
for $t\in[0,T]$ with initial values $x_0, \tilde{x}_0\in\real$.

Suppose the coefficients satisfy the following conditions for some constants $K, k, K'>0$, and $\tilde{\eta} \in [1/\alpha,1]$:
\begin{itemize}
    \item[(i)'] The drift coefficient $b$ is continuous bounded and $\tilde{b}$ is Lipschitz continuous:
    \begin{align*}
       |b(x)|\le K, \quad |\tilde{b}(x)-\tilde{b}(y)|\le K |x-y|. 
    \end{align*}
    \item[(ii)'] The jump coefficients $\sigma$ and $\tilde{\sigma}$ are bounded and H\"older continuous, and $\sigma$ is strictly positive:
    \begin{align*}
       k \le \sigma(x)\le K, \quad |\sigma^\alpha(x)-\sigma^\alpha(y)|\le K|x-y|^\eta,\\
       |\tilde{\sigma}(x)|\le K', \quad |\tilde{\sigma}(x)-\tilde{\sigma}(y)|\le K|x-y|^{\tilde{\eta}}.
    \end{align*}
    \item[(iii)'] The distances between the coefficients are small in the weighted norms defined in \eqref{weighted_norm}:
    \begin{align*}
       B \coloneqq \|b-\tilde{b}\|_{L^1\left(\mu_{x_0,\sigma}^{\alpha,T}\right)} < 1, \quad S \coloneqq \|\sigma-\tilde{\sigma}\|_{L^\alpha\left(\mu_{x_0,\sigma}^{\alpha,T}\right)} < 1. 
    \end{align*}
\end{itemize}
Then, there exists a positive constant $C = C(T, \alpha, K, k)$ such that\\
\noindent (1) Convergence in Expectation:
\begin{align*}
\sup_{t \in [0,T]} \e\left[|X_t-\tilde{X}_t|^{\alpha-1}\right] \le 
 \begin{cases}
    C\left\{\left|x_0-\tilde{x}_0\right|^{\alpha-1}+ \max\left\{B^{(\alpha\tilde{\eta}-1)/(\alpha\tilde{\eta}-\alpha+1)}, S^{\alpha-1/\tilde{\eta}}\right\}\right\}& \textrm{if~~}\tilde{\eta} \in(1/\alpha,1]\\
	C\left[\left|x_0-\tilde{x}_0\right|^{\alpha-1}+ \left\{\log\left(\frac{1}{\max\left\{B, S\right\}}\right)\right\}^{-1}\right] & \textrm{if~~}\tilde{\eta} =1/\alpha,
  \end{cases}
\end{align*}
\noindent (2) Convergence in Probability: For any $h>0$,
\begin{align*}
\p\left(\sup_{t \in [0,T]}|X_t-\tilde{X}_t|^{\alpha-1}>h\right) \le
 \begin{cases}
    \frac{C}{h}\left\{\left|x_0-\tilde{x}_0\right|^{\alpha-1}+ \max\left\{B^{(\alpha\tilde{\eta}-1)/(\alpha\tilde{\eta}-\alpha+1)}, S^{\alpha-1/\tilde{\eta}}\right\}\right\}& \text{if~~}\tilde{\eta} \in(1/\alpha,1]\\
	\frac{C}{h}\left[\left|x_0-\tilde{x}_0\right|^{\alpha-1}+ \left\{\log\left(\frac{1}{\max\left\{B, S\right\}}\right)\right\}^{-1}\right] & \textrm{if~~}\tilde{\eta} =1/\alpha.
 \end{cases}
\end{align*}","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T18:58:38.059483+00:00","domain":"probability theory","id":"claim_b949f31c5fb7a13c068dafe43c41d62d649dd62453aeeb2cb4a09ec5e79d37a2","kind":"lemma","schema_version":1,"statement":"[Lemma lem:Key2 of arXiv:2606.19313, 'Stability of Khintchine-type inequalities via log-monotonicity'] Let $r_k=r_k(X)$ for a random variable $X$. Let $\alpha=(\alpha_1, \alpha_2, \ldots, \alpha_n)$ be a weak partition of $q$ with length $\ell(\alpha)<q$. The following bounds hold.

\begin{enumerate}
\item If $(r_k)$ is log-concave, then $\prod_ir_{\alpha_i}\leq r_1^{q-2}r_2$;\\

\item If $(r_k)$ is log-convex, then $\prod_ir_{\alpha_i}\geq r_1^{q-2}r_2$.
\end{enumerate}","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T12:17:13.061883+00:00","domain":"probability theory","id":"claim_b94c6e9cc558c69c879685315794c8084d5cdcafed7579d3c37912b08fff6c31","kind":"lemma","schema_version":1,"statement":"[Lem bootstrap of arXiv:2508.04954, 'Conditional exponential directed last passage percolation under a one-point upper large de'] Let $I$ be an open interval in ${\mathbb R}$ and let $y_0\in I$. 
For each $n\in {\mathbb N}$, let $A_n$ be an event, and let $\{Y_n(y)\}_{y\in I}$ be a stochastic process. 
Let $r\in{\mathbb R}$. 
Suppose that the following two conditions hold:
\begin{enumerate}[(a)]
\item There is a continuous function $f$ on $I$ such that
\begin{equation} 

    \lim_{n\to\infty} \mathbb{P}(\{Y_n(y)\le r \} \cap A_n) =f(y)
    \qquad \text{for every} \quad y \in I\setminus \{y_0\}.
\end{equation}
\item There is a continuous function $g$ on $I\times I$ satisfying $g(y,y)=0$ for $y\in I$,  such that
\begin{equation*}

    \lim_{n\to\infty} \mathbb{P}(Y_n(y)\le r, \, Y_n(y')>r  ) =g(y,y') 
    \qquad \text{for every} \quad  y, y'\in I \quad \text{with} \quad y\neq y'. 
\end{equation*}
\end{enumerate}
Then, (equation eq:convergenced2 of the paper) also holds for $y=y_0$.","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T17:22:39.688297+00:00","domain":"probability theory","id":"claim_b94ce760889e6e802c0b2c8a2b0ce9a931d39aa2eff9c2922ec05caa4cdc8ae7","kind":"concept","schema_version":1,"statement":"[Lemma lem:scaling_limit_diagrams_no_cutoff of arXiv:2508.18807, '{\bf Critical long-range percolation I: High effective dimension}'] We have



