{"assumptions":[],"created_at":"2026-10-27T23:00:22.776812+00:00","domain":"probability theory","id":"claim_b9b9d73ee9b2564cbccb4b9eb9a66536e7a5023ba85881e6002a3661ce9128ea","kind":"lemma","schema_version":1,"statement":"[Lemma thm:ldsde-comparison of arXiv:2411.01364, 'Global Dynamics of Granular Media Equations via Stochastic Order'] Suppose Assumption (asp:potential of the paper) holds. Let $\mu,\nu\in C([s,\8);\mathcal P_2(\mathbb R))$ and $T>0$.
Assume
\begin{equation}
    \int_{\mathbb R}x\mathop{}\!\mathrm{d} \mu_t(x)\leq \int_{\mathbb R}x\mathop{}\!\mathrm{d} \nu_t(x), \ \text{ for all } \ t\in [s,s+T].
\end{equation}
If $\xi,\eta\in L^2(\Omega,\mathcal F_s,\mathbf P)$ and $\mathcal L(\xi)\leq_{\mathrm{st}}\mathcal L(\eta)$, then $\mathcal L(X_t^{s,\mu,\xi})\leq_{\mathrm{st}}\mathcal L(Y_t^{s,\nu,\eta})$ for all $t\in [s,s+T]$.","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T06:29:21.946896+00:00","domain":"probability theory","id":"claim_b9bbe51053799ef4fcdd7101ea67c5ea403baeb80fb00c2c63e2fe248a116076","kind":"lemma","schema_version":1,"statement":"[Lem 16 of arXiv:2608.01860, 'A Variational Characterization of a Gibbs Measure related to the Aviles-Giga Functional'] Let $p\in\N$ with $p\geq 3$ and $q\in\N$ with $q\leq p-1$. For any $\delta>0$ there exist $C<\infty$, independent of $T$, $\max\{1,\frac{p}{q}2(\frac{q}{p}-\frac{2}{p}+2)^{-1}\}<\beta<\frac{p}{q}$ and $0<\varepsilon\leq \frac{(p-2)\beta}{2(p-q\beta)}$  such that for $\alpha\in\{1,2\}^{p-k}$ and $\gamma\in\{1,2\}^q$
     \begin{align*}
        &|(\int_0^T...\int_0^{s_{k-1}} d(\partial_{\alpha_1}Y_{s_1})...d(\partial_{\alpha_k}Y_{s_{p-q}}))(\partial_{\gamma_1} Z_T(u)...\partial_{\gamma_q}Z_T(u))|\\
        &\lesssim \Vert\int_0^T...\int_0^{s_{k-1}} d(\partial_{\alpha_1}Y_{s_1})...d(\partial_{\alpha_k}Y_{s_{p-q}})\Vert_{W^{-\varepsilon,\frac{\beta}{\beta-1}}}\Vert  \nabla Z_T(u)\Vert_{W^{\varepsilon,\frac{p\beta}{p-(q-1)\beta}}}\Vert \nabla Z_T(u)\Vert_{L^p}^{q-1}
    \end{align*}
    and
    \begin{align*}
       &\mathbb{E}\left[ |(\int_0^T...\int_0^{s_{k-1}} d(\partial_{\alpha_1}Y_{s_1})...d(\partial_{\alpha_k}Y_{s_{p-q}}))(\partial_{\gamma_1} Z_T(u)...\partial_{\gamma_q}Z_T(u))|\right]\\
       &\leq C+\delta\mathbb{E}\left[\Vert \nabla Z_T(u)\Vert_{L^p}^p+\frac{1}{2}\Vert u\Vert_\mathcal{H}^2\right].
    \end{align*}","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-26T19:32:38.634345+00:00","domain":"probability theory","id":"claim_b9c3b16b85ce997cedc5b844292a3f699031f412466bb86048cb0887467d0c6a","kind":"concept","schema_version":1,"statement":"[Proposition 1 of arXiv:2506.17109, 'Limit theorems under nonlinear expectations dominated by sublinear expectations'] Suppose that a nonlinear expectation $\mathbb{\tilde{E}}[\cdot]$
