    	\]
    	\[
    	\lim_{s\rightarrow \infty} b(s) P(X<-sx) = \kappa_{-} x^{-\alpha}.   \tag{1.2.2} 
    	\]","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T16:53:30.531026+00:00","domain":"probability theory","id":"claim_bafb8ab72e68fc6839b4bddfec0ec198028dba5d7135097363be518d64eec1c9","kind":"lemma","schema_version":1,"statement":"[Lemma lem_P_n of arXiv:2505.24043, 'Weak solutions of Navier-Stokes Equation with purely discontinuous L\'evy Noise'] Assume that
