{"assumptions":[],"created_at":"2026-10-27T21:30:14.227946+00:00","domain":"probability theory","id":"claim_bb27925cba3d30e5f30295c318396a9fac54a2a1e00250270f78585a318e461b","kind":"lemma","schema_version":1,"statement":"[Lemma lemma_upper and lower for F-KPP of arXiv:2608.23202, 'Locally finite Fixed points of Branching Brownian Motion'] \begin{enumerate}[label= (\alph*)]
    \item Let $f, \phi, u_\phi$ be as in Proposition (Bramson-psi-estimate-for-one-sided-f of the paper) and $0<\alpha<\beta<\infty$. Then, there exist $t_0\ge 1, C_1, C_2 >0$ such that for all $t \ge t_0$ and $z \in [\alpha t, \beta t]$,
    \begin{equation}
        C_1\frac{e^{-\sqrt 2 z}}{\sqrt t}e^{-z^2/2t} \le u_\phi(t,z+\sqrt 2t)\le C_2\frac{e^{-\sqrt 2 z}}{\sqrt t}e^{-z^2/2t}.
    \end{equation}
The upper bound in the above holds for $\phi$ with $f\in C_c^+(\mathbb{R})$ as well. 
    \item Let $0< \alpha < \beta < \infty$. Then, there exists $t_0 \geq 1$, $K>0$ large enough and constants $C_1, C_2 >0$ such that for all $t\geq t_0$ and $z\in [\alpha t, \beta t]$,
    \begin{equation}
        C_1\frac{e^{-\sqrt 2 z}}{\sqrt t}e^{-z^2/2t} \le u_M(t, \sqrt{2}t + z - K ) - u_M(t, \sqrt{2}t + z + K )\le C_2\frac{e^{-\sqrt 2 z}}{\sqrt t}e^{-z^2/2t}.
    \end{equation}
\end{enumerate}","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-26T19:16:49.559773+00:00","domain":"probability theory","id":"claim_bb2a9df19efa9e39bb49a867c8054f2be12cdb6006046a85fce604aa2d753415","kind":"theorem","schema_version":1,"statement":"[Cor 43 ($L\log L$-regularisation) of arXiv:2509.06869, 'Infinite Interacting Brownian Motions and EVI Gradient Flows'] \ 
