{"assumptions":[],"created_at":"2026-10-26T20:53:31.973511+00:00","domain":"probability theory","id":"claim_bb3b1b0668704d124b200001767d863fbe2ea4ebc6d7fccf687dd6fa334ac29c","kind":"theorem","schema_version":1,"statement":"[Proposition 9 of arXiv:2606.10336, 'From Pitman's local times representation to the Gorin-Shkolnikov identity and beyond'] Let $\{m(t)\}_{0 \le t \le 1}$ be a Brownian meander on $[0,1]$.
Assume that $\phi: \mathbb{R} \to \mathbb{R}$ be sufficiently smooth and $\int_0^1\phi(x)^2dx < \infty$.
We have:
\begin{equation}
\frac{1}{2}\int_0^1\left( \frac{\phi(t)}{M(t)} - M(t) \left( \frac{\phi(t)}{t} + \phi'(t)\right)\right)dt + \frac{M(1)\phi(1)}{4}
\stackrel{d}{=} \mathcal{N}\left(0, \frac{1}{4} \int_0^1 \phi(x)^2 dx\right),
\end{equation}
which is independent of $M(1)$.
In particular, for $\alpha > 0$,
\begin{equation}
\frac{1}{2} \int_0^1 \left(\frac{t^\alpha}{M(t)} - (\alpha +1)t^{\alpha - 1} M(t)\right)dt + \frac{M(1)}{4}\stackrel{d}{=} \mathcal{N}\left(0, \frac{1}{4(1+ 2 \alpha)}\right).
\end{equation}","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-26T19:40:21.275507+00:00","domain":"probability theory","id":"claim_bb3b75badd4466777b38fbcec7552031cbabf2bf07eb43eed79f71736ab8c9af","kind":"concept","schema_version":1,"statement":"[Theorem 5 (McLeish, 1974) of arXiv:2604.07579, 'Topology of Percolation Clusters: Central Limit Theorems beyond the Lattice'] Let $\{X_{r,j}\}_{r \geq 1, 1 \leq
      j \leq b_r}$ be a martingale difference array with respect to filtrations
      $\{\mathcal{F}_{r,j}\}$, satisfying:
      \begin{enumerate}
        \item $\max_{1 \leq j \leq b_r}|X_{r,j}|$ is uniformly bounded in
          $L_{2}$-norm;

        \item $\max_{1 \leq j \leq b_r}|X_{r,j}|$ converges in probability
          to $0$; and

        \item $\sum_{j=1}^{b_r}X^{2}_{r,j}$ converges in probability to $1$.
      \end{enumerate}
      Then, denoting $S_{r}= \sum_{j=1}^{b_r}X_{r,j}$, $S_{r}$ converges in
      distribution to $\mathcal{N}(0,1)$. (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T20:19:06.721947+00:00","domain":"probability theory","id":"claim_bb3ba9657115fdfc7dfcc7a255e09c2d3d7e72b19108ee222abf3ded33716358","kind":"theorem","schema_version":1,"statement":"[Proposition property of LN of arXiv:2606.01944, 'Propagation of Chaos for Mean-field Mean Reflected Backward Stochastic Differential Equati'] (i) For any $X,Y\in L^2(\mathcal{F}^{(N)}_t;\mathbb{R}^N)$, we have 
    \begin{align}
        |L_t^{(N)}(X)-L_t^{(N)}(Y)|\le \frac{M}{m}\frac{1}{N}\sum_{j=1}^N|X^j-Y^j|.
    \end{align}

  \noindent  (ii) For any $S\in\mathcal{S}^2(\mathbb{F}^{(N)};\mathbb{R}^N)$, we have $\{L^{(N)}_t(S_t)\}_{t\in[0,T]}\in \mathcal{S}^2(\mathbb{F}^{(N)})$.","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-26T20:56:03.902487+00:00","domain":"probability theory","id":"claim_bb3bd51f1c3363596e0a09444dd787f57201ca29d9b78a0b8416b02d7beb1dba","kind":"theorem","schema_version":1,"statement":"[Proposition 19 of arXiv:2606.20908, 'On It\^o-Stratonovich formula for rough sheets'] Let $x$ be an element of $\mathcal{P}_{1,1}^{\ga_1,\ga_2}$ with $\ga_1>1/3$ and  $\ga_2>1/2$. Like in Theorem \ref{th:main-yr-integral}, we assume that $x$ can be lifted as a rough sheet $\XX$ satisfying Hypotheses \ref{hyp:rs1}, \ref{hyp:rs2}, and~\ref{hyp:rs3}. Consider a function $\vp \in \mathcal{C}_b^5(\RR)$ and for $i\ge 1$ we set $y^{(i)}:=\vp^{(i)}(x)$. Then the following holds true for $y=\vp(x)$:
\begin{enumerate}
\item The rectangular increment of $y$ can be decomposed as
\begin{equation}
\der y = \int_{1}\int_{2} y^{(1)} \, d_{12}x + \int_{1}\int_{2} y^{(2)} \, d_{\hone\htwo}x,
\end{equation}
where the integrals are understood as in \eqref{E:z1-rough-young}-\eqref{E:z2-rough-young}-\eqref{z-z-hate} and Remark \ref{Rmk:control2}.

\item Let $\pi_n^1$ and $\pi_n^2$ be two sequences of partitions, respectively of $[s_1,s_2]$ and $[t_1,t_2]$, whose mesh go to $0$ as $n\rightarrow \infty$. Then we have convergrence of the following Riemann sums:
\begin{multline}
   \delta y_{s_1s_2;t_1t_2} 
   =\lim_{n \to \infty}\Bigl( 
\sum_{\pi_n^1, \pi_n^2}
\big[y^{(1)}_{\sigma_i, \tau_j} \,
