{"assumptions":[],"created_at":"2026-10-27T14:05:52.432684+00:00","domain":"probability theory","id":"claim_bbd6fa2bf12eef161284bf0f2b388b7616c7eb27b09ba15f3b57380db8e744ba","kind":"lemma","schema_version":1,"statement":"[Lemma threeeventsnsigma of arXiv:2504.15992, 'Repeated singular values of a random symmetric matrix and decoupled singular value estimat'] Let $A_n$ be as in Lemma (corollary3.6chap9 of the paper). Let $\Delta>0,\kappa>0$ and $\sigma\in(0,1)$ be fixed constants. Fix any $\lambda_1,\lambda_2\in[-(2-\kappa)\sqrt{n},(2-\kappa)\sqrt{n}]$ satisfying $|\lambda_1-\lambda_2|\geq\Delta n^{\sigma-\frac{1}{2}}$. Then \begin{enumerate}
\item We can find some constant $\Delta_0>0$ and some $C_0>0$ depending on $\Delta$ such that, for any $1\leq k\leq \Delta_0n^\sigma$ and $j\neq i$, we have
    \begin{equation}
        \mathbb{P}(c_j(i;k)\leq C_0n^\sigma)\leq \exp(-\Omega(n^{\sigma/2})).
    \end{equation} \item For any $i\neq j\in\{1,2\}$, on an event with probability $1-e^{-\Omega(n^{\sigma/2})},$ we have
\begin{equation}
    \frac{\mu_{c_i(j;1)}(\lambda_i)}{\mu_1(\lambda_i)}\leq 10^{-1}.
\end{equation}
\item Fix a given $(\theta_1,
\theta_2)\in\mathbb{R}^2$ and some $j\neq i\in\{1,2\}$ that satisfy $|\frac{\theta_j}{\mu_1(\lambda_j)}|\geq |\frac{\theta_i}{\mu_1(\lambda_i)}|$. We can find some $\Delta_1>0$ depending on $\Delta$ such that on an event with probability $1-e^{-\Omega(n^{\sigma/2})},$ for any $1\leq k\leq \Delta_1n^{\sigma}$, we have 
\begin{equation}
   |\theta_i| \frac{\mu_{c_i(j;k)}(\lambda_i)}{\mu_1(\lambda_i)}\leq 10^{-1}|\theta_j|\frac{\mu_k(\lambda_j)}{\mu_1(\lambda_j)}
\end{equation}
\end{enumerate} The constant term in the error $\exp(-\Omega(n^{\sigma/2}))$ depends on all the constants $\Delta,\kappa,\sigma>0$.","status":"unverified"}

