{"assumptions":[],"created_at":"2026-10-27T06:39:11.675193+00:00","domain":"probability theory","id":"claim_bc5bfc5a90d4291c770f42fab1a1437de1ff914cfdd2d16afa9eaff07cbd6096","kind":"definition","schema_version":1,"statement":"[Definition 7 of arXiv:2608.04937, '2608.04937'] We say that a quadruple $(X,Y,Z,R)$ of $\mathbb{F}$-adapted processes is a solution to the mean-field forward-backward stochastic differential equation with reflection on $[0,T]$, with generators $B$ and $f$, diffusion coefficient $\sigma$, initial condition $\xi$, terminal function $h$, lower barrier $L$, and upper barrier $U$ (MF-FBSDER$^T(\xi,h,B,\sigma,f,L,U)$ for short), if
\begin{enumerate}[(a)]
\item $X,Y$ are regulated processes and $Z\in\mathcal{H}_{\mathbb{F}}(0,T)$,
\item $R\in\mathcal{V}_{0,\mathbb{F}}(0,T)$, $L_t\le Y_t\le U_t$, $t\in[0,T]$, and
\begin{equation*}
\begin{split}
&\int^T_0(Y_{r-}-\overrightarrow{L}_r)\,dR^{+,*}_r+\sum_{0\le r<T}(Y_r-L_r)\Delta^+R^+_r\\&
=\int^T_0(\underrightarrow{U}_r-Y_{r-})\,dR^{-,*}_r+\sum_{0\le r<T}(U_r-Y_r)\Delta^+R^-_r=0,
\end{split}
\end{equation*}
where $R=R^+-R^-$ is the Jordan decomposition of $R$,
\item $\int^T_0|B(r,X_r,Y_r,Z_r,\mathcal{L}(X_r,Y_r,Z_r))|+|f(r,X_r,Y_r,Z_r,\mathcal{L}(X_r,Y_r,Z_r))|\,dr<\infty$,
\item $X_t=\xi+\int^t_0 B(r,X_r,Y_r,Z_r,\mathcal{L}(X_r,Y_r,Z_r))\,dr+\sigma W_t$, $t\in[0,T]$,
\item $Y_t=h(X_T,\mathcal{L}(X_T))+\int^T_t f(r,X_r,Y_r,Z_r,\mathcal{L}(X_r,Y_r,Z_r))\,dr+R_T-R_t-\int^T_t Z_r \,dW_r$, $t\in[0,T]$.
