+2 \operatorname{Cov}(X_{k-1}, \eta_{k}),
\end{equation}
\begin{equation}
\mathbf{E}(M_{k}^{2})
= \sigma^{2} \mathbf{E}(X_{k-1})
+\mathbf{E}\nu_{k}.
\end{equation}","status":"unverified"}

