	Consequently, for every compact set $\mathcal C\subset\mathbb X$,
	\begin{align}
		\lim_{\epsilon\to0}
		\sup_{(x,\mu)\in \mathcal C}\sup_{0\leq t\leq T}
		d_{\mathbb X}\big(
		\Phi^\epsilon(t,\omega)(x,\mu),
		\Phi^0(t,\omega)(x,\mu)
		\big)=0.
	\end{align}","status":"unverified"}

