{"assumptions":[],"created_at":"2026-10-27T17:24:45.970946+00:00","domain":"probability theory","id":"claim_bcd80762cd6dba5b01f1d7b4b48ec6b668c1deecc807bf9599d9a8a9cf301664","kind":"concept","schema_version":1,"statement":"[Theorem thm:R1b of arXiv:2509.17319, 'Non-directed polymers in random environments with range penalties: the high-dimensional ca'] Let $\alpha\in(\frac{d}{2},2)$ (in particular $d=2,3$) and $(\zeta,\gamma)\in R_1$ (see Figure (diagram2 of the paper)). Then $(S_n)_{0\leq n \leq N}$ has end-to-end fluctuations of order $N^{\xi}$ under ${\ensuremath{\mathbf P}} _N$ with $\xi=\frac12$ and we have the following scaling limits for ${\ensuremath{\mathbf Z}} _N$.

\noindent{\rm (i)} If $\zeta\in(1,\gamma+\frac{d(\alpha-1)}{2\alpha})$, then
\begin{equation}
\frac{1}{h_N{\ensuremath{\mathbf E}} [|{\ensuremath{\mathcal R}} _N|]}\log{\ensuremath{\mathbf Z}} _N\overset{{\ensuremath{\mathbbm P}} }{\longrightarrow}-1.
\end{equation}

\noindent{\rm (ii)} If $\zeta>\gamma+\frac{d(\alpha-1)}{2\alpha}$, then setting $v_N=\log N$ for $d=2$ and $v_N=\sqrt{N}$ for $d=3$, we have that
\begin{equation}
\frac{v_N}{\beta_N N^{\frac{d}{2\alpha}}}\log{\ensuremath{\mathbf Z}} _N\overset{(d)}{\longrightarrow}{\ensuremath{\mathcal W}} ,
\end{equation}
where
\begin{equation}
{\ensuremath{\mathcal W}} :=\int_{{\ensuremath{\mathbbm R}} ^d\times{\ensuremath{\mathbbm R}} }\omega f(x)({\ensuremath{\mathcal P}} -\eta)({\ensuremath{\mathrm d}}  x,{\ensuremath{\mathrm d}}  w)
\end{equation}
is a well-defined random variable with
\begin{equation}
f(x):=\begin{cases}
\int_{\|x\|^2/2}^{\infty}u^{-1}e^{-u}{\ensuremath{\mathrm d}}  u,\quad&\text{if}~d=2,\\
2\lambda_d\int_0^1\rho_d(u,x){\ensuremath{\mathrm d}}  u,\quad&\text{if}~d=3,
\end{cases}
\end{equation}
a Poisson point process ${\ensuremath{\mathcal P}} $ with intensity measure $\eta({\ensuremath{\mathrm d}}  x,{\ensuremath{\mathrm d}} \omega)=\alpha p^{\mathbbm{1}_{\{\omega>0\}}}q^{\mathbbm{1}_{ \{\omega<0\}}}|\omega|^{-(1+\alpha)}{\ensuremath{\mathrm d}}  x{\ensuremath{\mathrm d}}  \omega$, $\lambda_d={\ensuremath{\mathbf P}} (S_n\neq0,\forall n\geq1)$, and the Gaussian kernel $\rho_d(t,x)=(2\pi t/d)^{-d/2}\exp(-d\|x\|^2/2t)$. (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-26T20:56:03.894316+00:00","domain":"probability theory","id":"claim_bcd98a61bdf9c76a589acb8490ab76fc8561c33be74da717656fe7e3b8e2a996","kind":"lemma","schema_version":1,"statement":"[Lem 16 of arXiv:2606.18877, 'Ergodic Properties of Non-Linear Density-Dependent Perturbations of the Ornstein--Uhlenbec'] Let \(Y_t\) be the Ornstein-Uhlenbeck process defined in~\eqref{OU_a0}. Then, for any \(p\geq 1\), it holds that
