		\frac{Q(f_R,f_R)^2}{f_R}	+	|Q(f_R,f_R)|\,\delta_{f_R} 	\rp\d v \leq	CR^{-2K-2}.
	\end{equation}","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T19:22:08.410024+00:00","domain":"probability theory","id":"claim_bd2569758294579eb10ed1ccd0452979947f1c2a69d35b181844d5fa9a833c72","kind":"concept","schema_version":1,"statement":"[Lemma lem:qtaylor of arXiv:2607.28817, 'Limiting spectral distribution for the adjacency matrix of the Watts--Strogatz random grap'] There exists a constant $C > 0$ so that 
    \begin{align*}
        &\left| \mathbb{E}[s_{Q_n'((\tilde{X}_n)_{ab})}(z)] - \mathbb{E}[s_{Q_n'((\tilde{Y}_n)_{ab})}(z)] \right| \\
        &\qquad\leq C \frac{(A_n)_{ab}}{\varepsilon n K_n}   \left( \mathbb{E}[( X_n)^2_{ab}\chi_{ \{|(X_n)_{ab}| > \varepsilon \sqrt{K_n} \} }] + \mathbb{E}[( Y_n)^2_{ab}\chi_{ \{|(Y_n)_{ab}| > \varepsilon \sqrt{K_n} \} }] \right) \\
        &\qquad\qquad + C \frac{(A_n)_{ab}}{ n K_n} \varepsilon \left( \mathbb{E}[|(X_n)_{ab}|^2] + \mathbb{E}[|(Y_n)_{ab}|^2] \right),
    \end{align*}
    if $a < b$,
    and 
    \[ \left| \mathbb{E}[s_{Q_n'((\tilde{X}_n)_{aa})}(z)] - \mathbb{E}[s_{Q_n'((\tilde{Y}_n)_{aa})}(z)] \right| \leq \frac{C \varepsilon}{n}(A_n)_{aa} \]
    if $a = b$.
    The constant $C$ is independent $a,b$, and $\varepsilon$. (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T13:56:17.359852+00:00","domain":"probability theory","id":"claim_bd256a12f9bdf7d07755ba956dbd52eda57a5d00a014cdab54ebcbe886c754f2","kind":"concept","schema_version":1,"statement":"[Theorem mainthm of arXiv:2605.16244, 'Analysis of a twisted Bose--Einstein Markov chain with applications to sampling Catalan st'] Fix $n \geq 2$. 
Let $K_{\mathrm{PF}}$ be the transition kernel of the Burnside process on $\mathrm{PF}_n$ and let $\pi_{\mathrm{PF}}$ be its stationary distribution. 
Then $\lambda_{2,\mathrm{PF}} = \lambda_2(K_{\mathrm{PF}}) = \frac{n}{2(n+1)}$, and for all $t\ge1$, 
\begin{equation}
 \max\left\{
  \frac{n}{n+2}\lambda_{2,\mathrm{PF}}^t,\,
  1-\frac{t+\log 3}{\log n}
 \right\}
 \le d_{K_{\mathrm{PF}}}(t)
 \le n\sqrt{\frac{n+1}{2}} \lambda_{2,\mathrm{PF}}^{t/2}.

\end{equation}
Consequently, for every fixed $0<\varepsilon<1$,
\[
 t_{\mathrm{mix},K_{\mathrm{PF}}}(\varepsilon)=\Theta_\varepsilon(\log n).
\] (Proof in the paper; no proof environment follows the statement in the TeX.)","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-27T09:19:56.685537+00:00","domain":"probability theory","id":"claim_bd262079ad122f849315946ecf9ad90c0b2b55f0419c1957037a9d3dcb07dda9","kind":"theorem","schema_version":1,"statement":"[Prop 1 of arXiv:2608.30967, 'B-Frames, B-Riesz basis, and Their tensor products'] Let $\{e_j\}_{j \in \mathcal{K}}$ be an orthonormal basis  for $\mathcal{H}$ and let $\{x_k\}_{k \in \mathcal{K}} \subset \mathcal{B}$.
\begin{enumerate}
\item $(\{x_k\}_{k \in \mathcal{K}},\mathfrak{b})$ is a b-frame for $\mathcal{Z}$ with the b-frame bounds $A$ and $B$  if and only if $\{\mathfrak{b}(e_j,x_k)\}_{j,k \in \mathcal{K}}$ is a frame for $\mathcal{Z}$ with the frame bounds $A$ and $B$.
  \item Suppose $(\{x_k\}_{k \in \mathcal{K}},\mathfrak{b})$ is a b-frame for $\mathcal{Z}$.
  \begin{enumerate}
    \item $S$ is the b-frame operator of $(\{x_k\}_{k \in \mathcal{K}},\mathfrak{b})$, if and only if $S$ is the frame operator of $\{b(e_j,x_k)\}_{j,k \in \mathcal{K}}$.
     \item $(\{x_k\}_{k \in \mathcal{K}},\tilde{\mathfrak{b}})$ is a b-frame for $\mathcal{Z}$ with the frame bounds $B^{-1}$ and $A^{-1}$. We call $(\{x_k\}_{k \in \mathcal{K}},\tilde{\mathfrak{b}})$ the canonical dual b-frame of the b-frame $(\{x_k\}_{k \in \mathcal{K}},\mathfrak{b})$.
    \item For each $z \in \mathcal{Z}$, we have the following b-frame expansion
    \begin{eqnarray}
z=\sum_{k \in \mathcal{K}}\tilde{\mathfrak{ b }}(\langle z / x_k \rangle,x_k )=\sum_{k \in \mathcal{K}} \mathfrak{ b }(\langle z / x_k \rangle\tilde{ \ },x_k ),
\end{eqnarray}
where $\langle . / . \rangle\tilde{\ }$ is the b-frame product with respect to $\tilde{\mathfrak{ b }}$.
\end{enumerate}
\end{enumerate}","status":"unverified"}

{"assumptions":[],"created_at":"2026-10-26T20:24:59.499124+00:00","domain":"probability theory","id":"claim_bd2eed3fe1aed2dfb79c8a5373074527d6b2eface199cf9184a1d64b62475ee9","kind":"concept","schema_version":1,"statement":"[Proposition 5 of arXiv:2605.10150, 'Rough path theory and an introduction to rough partial differential equations'] There is a unique linear operator $x \mapsto x^*$ from $L(V \otimes V)$ such that
